var GUIDES2 = [{ "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uC124\uCE58", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uB294 \uC5B4\uB5BB\uAC8C \uC9C4\uD589\uB418\uB098\uC694? \u2014 \uC811\uC218\uBD80\uD130 \uCCAB \uACB0\uC81C\uAE4C\uC9C0", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uAC00 \uC811\uC218, \uAC00\uB9F9\uC810 \uB4F1\uB85D \uC2EC\uC0AC, \uAE30\uAE30 \uC5F0\uACB0, \uACB0\uC81C \uD14C\uC2A4\uD2B8\uC758 \uC21C\uC11C\uB85C \uC9C4\uD589\uB418\uB294 \uACFC\uC815\uC744 \uB2E8\uACC4\uBCC4\uB85C \uD480\uACE0, \uB9E4\uC7A5\uC774 \uBBF8\uB9AC \uC900\uBE44\uD560 \uC11C\uB958\uC640 \uC804\uC6D0\xB7\uD1B5\uC2E0 \uC790\uB9AC, \uC124\uCE58\uAC00 \uB2A6\uC5B4\uC9C0\uB294 \uD754\uD55C \uC6D0\uC778\uACFC \uCCAB \uC8FC\uC5D0 \uD655\uC778\uD560 \uAC83\uAE4C\uC9C0 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uB294 \uC811\uC218, \uAC00\uB9F9\uC810 \uB4F1\uB85D, \uAE30\uAE30 \uC5F0\uACB0, \uACB0\uC81C \uD14C\uC2A4\uD2B8\uC758 \uB124 \uB2E8\uACC4\uB85C \uB05D\uB098\uBA70, \uC11C\uB958\uAC00 \uAC16\uCDB0\uC838 \uC788\uC73C\uBA74 \uC811\uC218 \uB4A4 \uBA70\uCE60 \uC548\uC5D0 \uCCAB \uACB0\uC81C\uAE4C\uC9C0 \uC774\uC5B4\uC9D1\uB2C8\uB2E4. \uAC00\uC7A5 \uC624\uB798 \uAC78\uB9AC\uB294 \uCABD\uC740 \uAE30\uAE30\uAC00 \uC544\uB2C8\uB77C \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uB4F1\uB85D \uC2EC\uC0AC\uC774\uACE0, \uB9E4\uC7A5\uC774 \uC900\uBE44\uD560 \uAC83\uC740 \uC11C\uB958 \uC138 \uAC00\uC9C0\uC640 \uAE30\uAE30\uB97C \uB193\uC744 \uC790\uB9AC\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uC124\uCE58 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uC900\uBE44\uD574\uC57C \uD558\uB098\uC694?", "p": ["\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D, \uB300\uD45C\uC790 \uC2E0\uBD84\uC99D, \uC815\uC0B0\uBC1B\uC744 \uD1B5\uC7A5 \uC0AC\uBCF8 \uC138 \uAC00\uC9C0\uAC00 \uAE30\uBCF8 \uC11C\uB958\uC774\uACE0, \uC138 \uC11C\uB958\uC758 \uC0C1\uD638\uC640 \uBA85\uC758\uAC00 \uC11C\uB85C \uB9DE\uC544\uC57C \uC2EC\uC0AC\uAC00 \uD55C \uBC88\uC5D0 \uC9C0\uB098\uAC11\uB2C8\uB2E4.", "\uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uCE74\uB4DC\uC0AC\uB9C8\uB2E4 \uB530\uB85C \uC774\uB904\uC9C0\uBBC0\uB85C \uC11C\uB958\uC5D0 \uC801\uD78C \uC8FC\uC18C\uAC00 \uB9E4\uC7A5 \uC2E4\uC81C \uC8FC\uC18C\uC640 \uB2E4\uB974\uBA74 \uC2EC\uC0AC\uAC00 \uB418\uB3CC\uC544\uC624\uACE0, \uB418\uB3CC\uC544\uC628 \uB9CC\uD07C \uC124\uCE58\uC77C\uC774 \uBC00\uB9BD\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uCABD\uC5D0\uC11C\uB294 \uB2E8\uB9D0\uAE30\uB97C \uB193\uC744 \uC790\uB9AC\uC640 \uC804\uC6D0 \uCF58\uC13C\uD2B8, \uC778\uD130\uB137 \uC120\uC774 \uB2FF\uB294 \uAC70\uB9AC\uC778\uC9C0 \uD655\uC778\uD574 \uB450\uBA74 \uC124\uCE58 \uB2F9\uC77C \uC791\uC5C5\uC774 \uC9E7\uC544\uC9D1\uB2C8\uB2E4.", "\uBC30\uB2EC\uC774\uB098 \uD14C\uC774\uBE14 \uACB0\uC81C\uCC98\uB7FC \uC790\uB9AC\uB97C \uC62E\uACA8 \uB2E4\uB2C8\uB294 \uACB0\uC81C\uAC00 \uC788\uC73C\uBA74 \uC811\uC218 \uB54C \uBBF8\uB9AC \uB9D0\uD574 \uB450\uB294 \uD3B8\uC774 \uAE30\uAE30 \uC885\uB958\uB97C \uACE0\uB974\uB294 \uB370 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30\uB97C \uAC19\uC774 \uC4F8 \uACC4\uD68D\uC774\uBA74 \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC744 \uC54C\uB824 \uC8FC\uC5B4\uC57C \uC5F0\uB3D9\uC774 \uB418\uB294 \uAE30\uAE30\uB85C \uC811\uC218\uB418\uACE0, \uB098\uC911\uC5D0 \uAE30\uAE30\uB97C \uBC14\uAFB8\uB294 \uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC601\uC5C5\uC2E0\uACE0\uC99D\uC774 \uD544\uC694\uD55C \uC5C5\uC885\uC740 \uC811\uC218 \uB54C \uAC19\uC774 \uB0B4\uC57C \uD558\uBBC0\uB85C \uB4F1\uB85D\uC99D \uC678\uC5D0 \uC5B4\uB5A4 \uC11C\uB958\uAC00 \uB354 \uD544\uC694\uD55C\uC9C0 \uCC98\uC74C \uC0C1\uB2F4\uC5D0\uC11C \uBB3B\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB2F9\uC77C\uC5D0\uB294 \uC5B4\uB5A4 \uC77C\uC774 \uBC8C\uC5B4\uC9C0\uB098\uC694?", "p": ["\uAE30\uC0AC\uAC00 \uBC29\uBB38\uD558\uBA74 \uAE30\uAE30\uB97C \uC804\uC6D0\uACFC \uD1B5\uC2E0\uC5D0 \uC5F0\uACB0\uD558\uACE0 \uAC00\uB9F9\uC810 \uBC88\uD638\uB97C \uB123\uC740 \uB4A4 \uC18C\uC561 \uACB0\uC81C\uC640 \uCDE8\uC18C\uB97C \uD55C \uBC88\uC529 \uD574 \uBCF4\uB294 \uAC83\uC73C\uB85C \uC791\uC5C5\uC774 \uB05D\uB0A9\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uCD9C\uB825 \uC5EC\uBD80, \uC11C\uBA85 \uBC29\uC2DD, \uD560\uBD80 \uAC1C\uC6D4 \uD45C\uC2DC \uAC19\uC740 \uC124\uC815\uC740 \uC774\uB54C \uB9E4\uC7A5 \uC6B4\uC601 \uBC29\uC2DD\uC5D0 \uB9DE\uCDB0 \uC815\uD558\uBBC0\uB85C \uC6D0\uD558\uB294 \uBC29\uC2DD\uC744 \uBBF8\uB9AC \uC0DD\uAC01\uD574 \uB461\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30\uC640 \uD568\uAED8 \uC4F0\uB294 \uB9E4\uC7A5\uC774\uB77C\uBA74 \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uACFC \uB2E8\uB9D0\uAE30\uAC00 \uC11C\uB85C \uAE08\uC561\uC744 \uC8FC\uACE0\uBC1B\uB294\uC9C0 \uC2E4\uC81C \uC8FC\uBB38 \uD558\uB098\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uACB0\uC81C\uB294 \uB2F9\uC77C \uCDE8\uC18C\uD558\uBA74 \uC815\uC0B0\uC5D0 \uB0A8\uC9C0 \uC54A\uC73C\uBBC0\uB85C \uBC18\uB4DC\uC2DC \uCDE8\uC18C\uAE4C\uC9C0 \uD574 \uBCF4\uACE0 \uC2B9\uC778 \uC601\uC218\uC99D\uACFC \uCDE8\uC18C \uC601\uC218\uC99D\uC744 \uD568\uAED8 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4\uC5D0\uB294 \uC815\uC0B0 \uC77C\uC815\uACFC \uACE0\uAC1D\uC13C\uD130 \uC5F0\uB77D\uCC98\uB97C \uBC1B\uC544 \uB450\uACE0, \uCCAB \uC815\uC0B0\uC774 \uB4E4\uC5B4\uC624\uB294 \uB0A0\uC9DC\uB97C \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB450\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4.", "\uC9C1\uC6D0\uC774 \uBC14\uB00C\uC5B4\uB3C4 \uC4F8 \uC218 \uC788\uAC8C \uACB0\uC81C\xB7\uCDE8\uC18C \uC21C\uC11C\uB97C \uD55C \uC7A5\uC73C\uB85C \uC801\uC5B4 \uAE30\uAE30 \uC606\uC5D0 \uBD99\uC5EC \uB450\uBA74 \uBB38\uC758 \uC804\uD654\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58\uAC00 \uB2A6\uC5B4\uC9C0\uB294 \uACBD\uC6B0\uB294 \uC5B8\uC81C\uC778\uAC00\uC694?", "p": ["\uAC00\uB9F9\uC810 \uC2EC\uC0AC\uC5D0\uC11C \uC11C\uB958 \uBD88\uC77C\uCE58\uAC00 \uB098\uC624\uAC70\uB098, \uC5C5\uC885 \uCF54\uB4DC\uAC00 \uB9E4\uC7A5 \uC2E4\uC81C \uC5C5\uC885\uACFC \uB2E4\uB974\uAC8C \uC811\uC218\uB41C \uACBD\uC6B0\uAC00 \uAC00\uC7A5 \uD754\uD55C \uC9C0\uC5F0 \uC6D0\uC778\uC785\uB2C8\uB2E4.", "\uC2E0\uADDC \uAC1C\uC5C5\uC774\uB77C \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC774 \uB9C9 \uB098\uC628 \uC0C1\uD0DC\uB77C\uBA74 \uCE74\uB4DC\uC0AC \uCABD \uB4F1\uB85D\uC774 \uD558\uB8E8 \uC774\uD2C0 \uB354 \uAC78\uB9B4 \uC218 \uC788\uC5B4 \uAC1C\uC5C5\uC77C\uC5D0 \uB9DE\uCD94\uB824\uBA74 \uC5EC\uC720\uB97C \uB461\uB2C8\uB2E4.", "\uC778\uD130\uB137 \uD68C\uC120\uC774 \uC544\uC9C1 \uAC1C\uD1B5\uB418\uC9C0 \uC54A\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30\uB97C \uB450\uACE0\uB3C4 \uACB0\uC81C\uB97C \uC5F4\uC9C0 \uBABB\uD558\uBBC0\uB85C \uD1B5\uC2E0 \uAC1C\uD1B5 \uC77C\uC815\uC744 \uBA3C\uC800 \uC7A1\uC2B5\uB2C8\uB2E4.", "\uAE30\uC0AC \uBC29\uBB38 \uC77C\uC815\uC740 \uC9C0\uC5ED\uACFC \uBC30\uC815 \uC0C1\uD669\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC815\uD655\uD55C \uB0A0\uC9DC\uB294 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC2EC\uC0AC\uAC00 \uB418\uB3CC\uC544\uC654\uC744 \uB54C\uB294 \uC5B4\uB290 \uC11C\uB958\uAC00 \uBB38\uC81C\uC778\uC9C0 \uC811\uC218 \uCC3D\uAD6C\uC5D0 \uBC14\uB85C \uBB3C\uC5B4\uC57C \uD558\uB8E8\uB97C \uC544\uB084 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5EC\uB7EC \uCE74\uB4DC\uC0AC \uAC00\uC6B4\uB370 \uD55C \uACF3\uB9CC \uB2A6\uC5B4\uC9C0\uB294 \uACBD\uC6B0\uB3C4 \uC788\uC5B4, \uB4F1\uB85D\uC774 \uB05D\uB09C \uCE74\uB4DC\uC0AC\uBD80\uD130 \uACB0\uC81C\uB97C \uC5F4\uACE0 \uB098\uBA38\uC9C0\uB294 \uB4A4\uC5D0 \uBD99\uC774\uB294 \uBC29\uBC95\uB3C4 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB4A4 \uCCAB \uC8FC\uC5D0 \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uCCAB \uC815\uC0B0\uC774 \uB4E4\uC5B4\uC624\uBA74 \uC2B9\uC778 \uCD1D\uC561\uACFC \uC785\uAE08\uC561\uC744 \uB9DE\uCDB0 \uBCF4\uACE0 \uC218\uC218\uB8CC \uAD6C\uAC04\uC774 \uC548\uB0B4\uBC1B\uC740 \uB300\uB85C \uC801\uC6A9\uB410\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC5D0 \uCC0D\uD788\uB294 \uC0C1\uD638\uC640 \uC0AC\uC5C5\uC790\uBC88\uD638\uAC00 \uB4F1\uB85D\uC99D\uACFC \uAC19\uC740\uC9C0 \uC190\uB2D8 \uC601\uC218\uC99D \uD55C \uC7A5\uC73C\uB85C \uD655\uC778\uD558\uBA74 \uB098\uC911\uC5D0 \uC138\uBB34 \uC790\uB8CC\uAC00 \uC5B4\uAE0B\uB098\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C\uAC00 \uBA48\uCDC4\uC744 \uB54C \uC804\uD654\uD560 \uCC3D\uAD6C\uB97C \uC9C1\uC6D0\uC774 \uBCF4\uC774\uB294 \uACF3\uC5D0 \uC801\uC5B4 \uB450\uACE0, \uC57C\uAC04 \uC601\uC5C5\uC774\uBA74 \uADF8 \uC2DC\uAC04\uC5D0 \uBC1B\uB294 \uBC88\uD638\uC778\uC9C0\uB3C4 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uC124\uC815\uC744 \uBC14\uAFB8\uACE0 \uC2F6\uC73C\uBA74 \uC124\uCE58 \uCCAB \uC8FC \uC548\uC5D0 \uC694\uCCAD\uD558\uB294 \uD3B8\uC774 \uC124\uC815 \uBCC0\uACBD\uC774 \uBE60\uB985\uB2C8\uB2E4.", "\uCE74\uB4DC\uC0AC\uBCC4 \uC815\uC0B0 \uC8FC\uAE30\uAC00 \uB2EC\uB77C \uC785\uAE08\uC77C\uC774 \uD769\uC5B4\uC9C0\uBBC0\uB85C \uCCAB \uB2EC\uC740 \uCE74\uB4DC\uC0AC\uBCC4 \uC785\uAE08\uC744 \uB530\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uCCAB \uC8FC \uB3D9\uC548 \uACB0\uC81C\uAC00 \uD55C \uBC88\uB3C4 \uC2E4\uD328\uD558\uC9C0 \uC54A\uC558\uB294\uC9C0 \uC601\uC218\uC99D \uBB36\uC74C\uC73C\uB85C \uD655\uC778\uD558\uBA74 \uD1B5\uC2E0 \uC0C1\uD0DC\uB97C \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uC601\uC218\uC99D\uC740 \uC190\uB2D8 \uBCF4\uAD00\uC6A9\uACFC \uAC00\uB9F9\uC810 \uBCF4\uAD00\uC6A9\uC774 \uB098\uB258\uBBC0\uB85C \uAC00\uB9F9\uC810\uC6A9\uC744 \uB0A0\uC9DC\uBCC4\uB85C \uBAA8\uC544 \uB450\uBA74 \uC815\uC0B0 \uB300\uC870\uAC00 \uC26C\uC6CC\uC9D1\uB2C8\uB2E4."] }], "steps": { "h": "\uC124\uCE58 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uC0C1\uB2F4\uC5D0\uC11C \uB9E4\uC7A5 \uD615\uD0DC\uC640 \uACB0\uC81C \uBC29\uC2DD\uC744 \uC815\uB9AC\uD558\uACE0 \uC11C\uB958\uB97C \uC811\uC218\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uB4F1\uB85D \uC2EC\uC0AC\uAC00 \uC9C4\uD589\uB418\uACE0 \uAC00\uB9F9\uC810 \uBC88\uD638\uAC00 \uB098\uC635\uB2C8\uB2E4.", "\uAE30\uC0AC\uAC00 \uBC29\uBB38\uD574 \uAE30\uAE30\uB97C \uC5F0\uACB0\uD558\uACE0 \uACB0\uC81C\xB7\uCDE8\uC18C \uD14C\uC2A4\uD2B8\uB97C \uD569\uB2C8\uB2E4.", "\uC815\uC0B0 \uC77C\uC815\uACFC \uACE0\uAC1D\uC13C\uD130 \uC5F0\uB77D\uCC98\uB97C \uBC1B\uACE0 \uC6B4\uC601\uC744 \uC2DC\uC791\uD569\uB2C8\uB2E4.", "\uCCAB \uC815\uC0B0\uC11C\uC5D0\uC11C \uC218\uC218\uB8CC \uC801\uC6A9\uACFC \uC785\uAE08\uC561\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC124\uCE58 \uB2E8\uACC4\uBCC4 \uC900\uBE44\uBB3C\uACFC \uB2F4\uB2F9", "head": ["\uB2E8\uACC4", "\uC900\uBE44\uBB3C", "\uB2F4\uB2F9"], "rows": [["\uC811\uC218", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\xB7\uC2E0\uBD84\uC99D\xB7\uD1B5\uC7A5 \uC0AC\uBCF8", "\uB9E4\uC7A5"], ["\uAC00\uB9F9\uC810 \uB4F1\uB85D", "\uC5C5\uC885\xB7\uC8FC\uC18C \uD655\uC778", "\uCE74\uB4DC\uC0AC\xB7\uC124\uCE58\uC5C5\uCCB4"], ["\uAE30\uAE30 \uC5F0\uACB0", "\uC804\uC6D0\xB7\uC778\uD130\uB137 \uC790\uB9AC", "\uAE30\uC0AC"], ["\uACB0\uC81C \uD14C\uC2A4\uD2B8", "\uC18C\uC561 \uACB0\uC81C\xB7\uCDE8\uC18C", "\uAE30\uC0AC\xB7\uB9E4\uC7A5"], ["\uCCAB \uC815\uC0B0 \uD655\uC778", "\uC815\uC0B0\uC11C", "\uB9E4\uC7A5"]] }, "faq": [["\uC124\uCE58\uAE4C\uC9C0 \uBA70\uCE60 \uAC78\uB9AC\uB098\uC694?", "\uC11C\uB958\uAC00 \uAC16\uCDB0\uC838 \uC788\uC73C\uBA74 \uC811\uC218 \uB4A4 \uBA70\uCE60 \uC548\uC5D0 \uB05D\uB098\uC9C0\uB9CC, \uAC00\uB9F9\uC810 \uC2EC\uC0AC\uC640 \uAE30\uC0AC \uC77C\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uAC1C\uC5C5\uC77C\uC774 \uC815\uD574\uC838 \uC788\uC73C\uBA74 \uADF8 \uB0A0\uC9DC\uB97C \uBA3C\uC800 \uC54C\uB824 \uC8FC\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."], ["\uC778\uD130\uB137\uC774 \uC5C6\uC5B4\uB3C4 \uC124\uCE58\uB418\uB098\uC694?", "\uC720\uC120 \uC778\uD130\uB137\uC774 \uC5C6\uC73C\uBA74 LTE \uBC29\uC2DD \uB2E8\uB9D0\uAE30\uB85C \uC124\uCE58\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uACBD\uC6B0 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uAE30\uAE30\uB9C8\uB2E4 \uB530\uB85C \uBC1C\uC0DD\uD569\uB2C8\uB2E4."], ["\uC124\uCE58 \uB2F9\uC77C \uAF2D \uB9E4\uC7A5\uC5D0 \uC788\uC5B4\uC57C \uD558\uB098\uC694?", "\uC124\uC815\uACFC \uD14C\uC2A4\uD2B8 \uACB0\uC81C\uB97C \uD655\uC778\uD574\uC57C \uD558\uBBC0\uB85C \uB300\uD45C\uC790\uB098 \uC6B4\uC601 \uB2F4\uB2F9\uC790\uAC00 \uC788\uB294 \uD3B8\uC774 \uC88B\uC2B5\uB2C8\uB2E4. \uC9C1\uC6D0\uB9CC \uC788\uC744 \uB54C\uB294 \uC124\uC815 \uD56D\uBAA9\uC744 \uBBF8\uB9AC \uC815\uD574\uC11C \uC804\uB2EC\uD569\uB2C8\uB2E4."], ["\uC124\uCE58 \uB4A4 \uC790\uB9AC\uB97C \uC62E\uACA8\uB3C4 \uB418\uB098\uC694?", "\uAC19\uC740 \uB9E4\uC7A5 \uC548\uC5D0\uC11C\uB294 \uC804\uC6D0\uACFC \uD1B5\uC2E0\uB9CC \uC5F0\uACB0\uB418\uBA74 \uB429\uB2C8\uB2E4. \uB2E4\uB978 \uC8FC\uC18C\uB85C \uC62E\uAE30\uBA74 \uAC00\uB9F9\uC810 \uC8FC\uC18C \uBCC0\uACBD\uC774 \uD544\uC694\uD558\uACE0 \uCE74\uB4DC\uC0AC \uC7AC\uC2EC\uC0AC\uAC00 \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uC5C5\uCCB4", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4"], "posts": ["/post/install-day-prep/"], "sources": [], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uC124\uCE58\uBE44\uC6A9", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uC740 \uC5BC\uB9C8\uC778\uAC00\uC694? \u2014 \uD56D\uBAA9\uBCC4\uB85C \uB098\uB220 \uBCF4\uB294 \uBE44\uC6A9 \uAD6C\uC870", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uC744 \uAE30\uAE30\uAC12, \uC124\uCE58 \uCD9C\uC7A5\uBE44, \uD1B5\uC2E0 \uAC1C\uD1B5\uBE44, \uC57D\uC815 \uC870\uAC74\uC73C\uB85C \uB098\uB220 \uC124\uBA85\uD558\uACE0, \uC784\uB300\uC640 \uAD6C\uB9E4\uC5D0\uC11C \uBE44\uC6A9\uC774 \uC5B4\uB5BB\uAC8C \uB2EC\uB77C\uC9C0\uB294\uC9C0\uC640 \uBE44\uC6A9\uC774 \uB298\uC5B4\uB098\uAC70\uB098 \uC904\uC5B4\uB4DC\uB294 \uC0C1\uD669, \uACAC\uC801\uC11C\uB97C \uC77D\uB294 \uBC95\uACFC \uACAC\uC801\uC744 \uBC1B\uB294 \uC21C\uC11C\uAE4C\uC9C0 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC124\uCE58\uBE44\uC6A9\uC740 \uAE30\uAE30\uAC12, \uC124\uCE58 \uCD9C\uC7A5\uBE44, \uD1B5\uC2E0 \uAC1C\uD1B5\uBE44 \uC138 \uAC00\uC9C0\uB85C \uAD6C\uC131\uB418\uACE0, \uAE08\uC561\uC740 \uAE30\uAE30 \uC885\uB958\uC640 \uC57D\uC815 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC838 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uC784\uB300 \uC57D\uC815\uC774\uBA74 \uAE30\uAE30\uAC12\uC774 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uBC14\uB00C\uACE0, \uAD6C\uB9E4\uBA74 \uCC98\uC74C \uD55C \uBC88\uC5D0 \uCE58\uB974\uB294 \uAD6C\uC870\uC774\uBBC0\uB85C \uACAC\uC801\uC11C\uC5D0\uC11C \uC138 \uD56D\uBAA9\uC774 \uB098\uB258\uC5B4 \uC788\uB294\uC9C0\uBD80\uD130 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uBE44\uC6A9\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uAE30\uAE30\uAC12\uC740 \uB2E8\uB9D0\uAE30 \uC790\uCCB4\uC758 \uAC00\uACA9\uC774\uACE0, \uCD9C\uC7A5\uBE44\uB294 \uAE30\uC0AC\uAC00 \uB9E4\uC7A5\uC5D0 \uC640\uC11C \uC5F0\uACB0\uD558\uACE0 \uD14C\uC2A4\uD2B8\uD558\uB294 \uC791\uC5C5\uC758 \uAC12\uC785\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uAC1C\uD1B5\uBE44\uB294 \uC720\uC120 \uC778\uD130\uB137\uC774\uB098 LTE \uD68C\uC120\uC744 \uC0C8\uB85C \uC5EC\uB294 \uB370 \uB4DC\uB294 \uBE44\uC6A9\uC73C\uB85C, \uC774\uBBF8 \uC4F0\uB294 \uD68C\uC120\uC5D0 \uBD99\uC774\uBA74 \uC774 \uD56D\uBAA9\uC774 \uBE60\uC9D1\uB2C8\uB2E4.", "\uC138 \uD56D\uBAA9\uC774 \uACAC\uC801\uC11C\uC5D0 \uB530\uB85C \uC801\uD600 \uC788\uB294\uC9C0 \uBCF4\uB294 \uAC83\uC774 \uCCAB \uD655\uC778 \uC0AC\uD56D\uC774\uACE0, \uD569\uCCD0\uC11C \uC801\uD600 \uC788\uC73C\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC774 \uC57D\uC815\uC5D0 \uBB36\uC600\uB294\uC9C0 \uC54C\uAE30 \uC5B4\uB835\uC2B5\uB2C8\uB2E4.", "\uCE74\uB4DC \uC218\uC218\uB8CC\uB294 \uC124\uCE58\uBE44\uC6A9\uACFC \uBCC4\uAC1C \uD56D\uBAA9\uC774\uBBC0\uB85C \uAC19\uC740 \uC904\uC5D0 \uC801\uD600 \uC788\uB2E4\uBA74 \uBD84\uB9AC\uD574\uC11C \uBCF4\uACE0, \uC218\uC218\uB8CC\uB294 \uAC00\uB9F9\uC810 \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C4\uB2E4\uB294 \uC810\uC744 \uAE30\uC5B5\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC6A9\uC9C0\uB098 \uAC70\uCE58\uB300 \uAC19\uC740 \uBD80\uC18D\uD488\uC774 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0\uB3C4 \uD56D\uBAA9\uC73C\uB85C \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD558\uBA74 \uB098\uC911\uC5D0 \uCD94\uAC00 \uCCAD\uAD6C\uB97C \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uAE30\uAE30 \uBAA8\uB378\uBA85\uC774 \uC5C6\uC73C\uBA74 \uC124\uCE58 \uB2F9\uC77C \uB2E4\uB978 \uAE30\uAE30\uAC00 \uC62C \uC218 \uC788\uC73C\uB2C8 \uBAA8\uB378\uBA85\uACFC \uD568\uAED8 \uC801\uD78C \uACAC\uC801\uC11C\uB97C \uBC1B\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC784\uB300\uC640 \uAD6C\uB9E4\uB294 \uBE44\uC6A9 \uAD6C\uC870\uAC00 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uC784\uB300\uB294 \uAE30\uAE30\uAC12\uC744 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uB098\uB220 \uB0B4\uB294 \uB300\uC2E0 \uC57D\uC815 \uAE30\uAC04\uC774 \uC0DD\uAE30\uACE0, \uC911\uAC04\uC5D0 \uADF8\uB9CC\uB450\uBA74 \uB0A8\uC740 \uAE30\uAC04\uC5D0 \uB300\uD55C \uC870\uAC74\uC774 \uBD99\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB294 \uCC98\uC74C\uC5D0 \uAE30\uAE30\uAC12\uC744 \uCE58\uB974\uACE0 \uC6D4 \uBE44\uC6A9\uC740 \uD1B5\uC2E0\uB8CC \uC815\uB3C4\uB9CC \uB0A8\uC73C\uBBC0\uB85C \uC624\uB798 \uC4F8\uC218\uB85D \uC6D4 \uBD80\uB2F4\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC624\uB798 \uC4F8 \uB9E4\uC7A5\uC740 \uAD6C\uB9E4 \uCABD\uC774, \uC6B4\uC601 \uAE30\uAC04\uC774 \uBD88\uD655\uC2E4\uD55C \uB9E4\uC7A5\uC740 \uC784\uB300 \uCABD\uC774 \uB9DE\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC5B4\uB290 \uCABD\uC774\uB4E0 \uAE30\uAE30 \uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uC870\uAC74\uC774 \uC5B4\uB5BB\uAC8C \uB418\uB294\uC9C0 \uC57D\uC815\uC11C\uC5D0\uC11C \uD568\uAED8 \uD655\uC778\uD574\uC57C \uC6B4\uC601 \uC911 \uBE44\uC6A9\uC774 \uAC11\uC790\uAE30 \uC0DD\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uB450 \uBC29\uC2DD\uC758 \uC6D4 \uBE44\uC6A9\uC744 \uC6B4\uC601 \uC608\uC815 \uAC1C\uC6D4 \uC218\uB85C \uACF1\uD574 \uBCF4\uBA74 \uCD1D\uBE44\uC6A9\uC774 \uD55C\uB208\uC5D0 \uBE44\uAD50\uB418\uACE0, \uC774\uB54C \uD1B5\uC2E0\uB8CC\uB294 \uC591\uCABD \uB2E4 \uBE7C\uACE0 \uBD10\uC57C \uCC28\uC774\uAC00 \uBD84\uBA85\uD569\uB2C8\uB2E4.", "\uC784\uB300 \uC57D\uC815\uC774 \uB05D\uB09C \uB4A4 \uAE30\uAE30\uB97C \uC5B4\uB5BB\uAC8C \uD558\uB294\uC9C0(\uBC18\uB0A9\xB7\uC5F0\uC7A5\xB7\uC18C\uC720\uAD8C \uC774\uC804)\uC5D0 \uB530\uB77C \uB4A4\uCABD \uBE44\uC6A9\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uADF8 \uC870\uD56D\uB3C4 \uAC19\uC774 \uC77D\uC2B5\uB2C8\uB2E4."] }, { "h": "\uBE44\uC6A9\uC774 \uB298\uC5B4\uB098\uB294 \uACBD\uC6B0\uB294 \uC5B8\uC81C\uC778\uAC00\uC694?", "p": ["\uB2E8\uB9D0\uAE30\uB97C \uC5EC\uB7EC \uB300 \uB450\uAC70\uB098 \uBC30\uB2EC\uC6A9 \uBB34\uC120\uAE30\uB97C \uB354\uD558\uBA74 \uB300\uC218\uB9CC\uD07C \uAE30\uAE30\uAC12\uC774 \uB354\uD574\uC9C0\uACE0, \uCD9C\uC7A5\uBE44\uB294 \uAC19\uC740 \uB0A0 \uC124\uCE58\uBA74 \uD55C \uBC88\uC73C\uB85C \uBB36\uC774\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30\uC640 \uC5F0\uB3D9\uD558\uB294 \uC791\uC5C5\uC774 \uD544\uC694\uD558\uBA74 \uC5F0\uB3D9 \uC124\uC815 \uC791\uC5C5\uC774 \uCD94\uAC00\uB420 \uC218 \uC788\uC5B4 \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC744 \uBBF8\uB9AC \uC54C\uB824 \uB461\uB2C8\uB2E4.", "\uC57C\uAC04\uC774\uB098 \uD734\uC77C \uC124\uCE58, \uC12C\uC774\uB098 \uC0B0\uAC04 \uC9C0\uC5ED \uCD9C\uC7A5\uC740 \uC77C\uC815 \uC870\uC815\uC774 \uD544\uC694\uD558\uACE0 \uBE44\uC6A9\uC774 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBC18\uB300\uB85C \uD1B5\uC2E0 \uD68C\uC120\uC744 \uAE30\uC874 \uAC83\uC73C\uB85C \uC4F0\uAC70\uB098 \uAE30\uAE30\uB97C \uC9C1\uC811 \uBC1B\uC544 \uC5F0\uACB0\uD558\uBA74 \uC904\uC5B4\uB4DC\uB294 \uD56D\uBAA9\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uC0AC\uC740\uD488\uC774\uB098 \uC124\uCE58\uBE44 \uC9C0\uC6D0\uC774 \uBD99\uC740 \uC81C\uC548\uC740 \uADF8 \uAC12\uC774 \uC6D4 \uC774\uC6A9\uB8CC\uB098 \uC57D\uC815 \uAE30\uAC04\uC5D0 \uB4E4\uC5B4\uAC00 \uC788\uB294\uC9C0 \uD56D\uBAA9\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC774\uB098 \uBB34\uC120\uD615\uCC98\uB7FC \uAE30\uAE30 \uC885\uB958\uAC00 \uB2EC\uB77C\uC9C0\uBA74 \uAE30\uAE30\uAC12 \uC790\uCCB4\uAC00 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uB9E4\uC7A5\uC5D0 \uD544\uC694\uD55C \uAE30\uB2A5\uB9CC \uACE0\uB985\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uC744 \uAE38\uAC8C \uC7A1\uC73C\uBA74 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB0AE\uC544\uC9C0\uB294 \uB300\uC2E0 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uBB34\uAC70\uC6CC\uC9C0\uBBC0\uB85C \uAE30\uAC04\uACFC \uC6D4 \uBE44\uC6A9\uC744 \uD568\uAED8 \uBD05\uB2C8\uB2E4."] }, { "h": "\uACAC\uC801\uC11C\uB97C \uC5B4\uB5BB\uAC8C \uC77D\uC5B4\uC57C \uD558\uB098\uC694?", "p": ["\uAE30\uAE30 \uBAA8\uB378\uBA85, \uD56D\uBAA9\uBCC4 \uAE08\uC561, \uC57D\uC815 \uAE30\uAC04, \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74 \uB124 \uAC00\uC9C0\uAC00 \uC788\uB294\uC9C0 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uD1B5\uC2E0\uB8CC\uAC00 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uD45C\uC2DC\uAC00 \uC5C6\uC73C\uBA74 \uBB3B\uACE0, \uB2F5\uC744 \uACAC\uC801\uC11C\uC5D0 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uB450 \uC5C5\uCCB4 \uACAC\uC801\uC744 \uAC19\uC740 \uD56D\uBAA9 \uC21C\uC11C\uB85C \uB2E4\uC2DC \uC801\uC5B4 \uBCF4\uBA74 \uCC28\uC774\uAC00 \uC5B4\uB514\uC11C \uB098\uB294\uC9C0 \uBCF4\uC774\uACE0, \uD569\uACC4\uB9CC \uBE44\uAD50\uD558\uB294 \uC2E4\uC218\uB97C \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uC801\uD78C \uB2F4\uB2F9\uC790 \uC5F0\uB77D\uCC98\uAC00 \uC124\uCE58 \uB4A4 \uACE0\uC7A5 \uBB38\uC758\uC5D0\uB3C4 \uC4F0\uC774\uB294\uC9C0 \uD655\uC778\uD574 \uB450\uBA74 \uC6B4\uC601 \uC911 \uC5F0\uB77D\uCC98\uB97C \uCC3E\uB294 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC815\uD655\uD55C \uAE08\uC561\uC740 \uB9E4\uC7A5 \uC870\uAC74\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uC9C0\uB9CC, \uD56D\uBAA9 \uAD6C\uC870\uB294 \uC5B4\uB290 \uC5C5\uCCB4\uB4E0 \uAC19\uC73C\uBBC0\uB85C \uAD6C\uC870\uB97C \uC54C\uACE0 \uAC00\uBA74 \uBE44\uAD50\uAC00 \uC27D\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C \uD56D\uBAA9\uC744 \uD45C\uB85C \uC62E\uACA8 \uC801\uC5B4 \uB450\uBA74 \uC124\uCE58 \uB4A4 \uCCAD\uAD6C\uC11C\uC640 \uB300\uC870\uD560 \uB54C \uC5B4\uB290 \uD56D\uBAA9\uC774 \uB298\uC5C8\uB294\uC9C0 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4."] }], "steps": { "h": "\uACAC\uC801\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uBC1B\uB098\uC694?", "items": ["\uB9E4\uC7A5 \uD615\uD0DC\uC640 \uACB0\uC81C \uBC29\uC2DD, \uD544\uC694\uD55C \uB300\uC218\uB97C \uC0C1\uB2F4\uC5D0\uC11C \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4 \uB450 \uAC00\uC9C0 \uC870\uAC74\uC73C\uB85C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0\uC11C \uAE30\uAE30\uAC12\xB7\uCD9C\uC7A5\uBE44\xB7\uD1B5\uC2E0\uBE44\uAC00 \uB098\uB258\uC5B4 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uACFC \uD574\uC9C0 \uC870\uAC74\uC744 \uC77D\uC740 \uB4A4 \uACB0\uC815\uD569\uB2C8\uB2E4.", "\uACB0\uC815\uD55C \uC870\uAC74\uC774 \uC57D\uC815\uC11C\uC5D0 \uADF8\uB300\uB85C \uC801\uD614\uB294\uC9C0 \uC11C\uBA85 \uC804\uC5D0 \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC784\uB300\uC640 \uAD6C\uB9E4\uC758 \uBE44\uC6A9 \uD56D\uBAA9 \uCC28\uC774", "head": ["\uD56D\uBAA9", "\uC784\uB300", "\uAD6C\uB9E4"], "rows": [["\uAE30\uAE30\uAC12", "\uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uD3EC\uD568", "\uCC98\uC74C \uD55C \uBC88"], ["\uC124\uCE58 \uCD9C\uC7A5\uBE44", "\uACAC\uC801\uC11C \uD655\uC778", "\uACAC\uC801\uC11C \uD655\uC778"], ["\uD1B5\uC2E0 \uD68C\uC120", "\uC6D4 \uC694\uAE08", "\uC6D4 \uC694\uAE08"], ["\uC57D\uC815 \uAE30\uAC04", "\uC788\uC74C", "\uC5C6\uC74C"], ["\uACE0\uC7A5 \uAD50\uCCB4", "\uC57D\uC815 \uC870\uAC74", "\uBCF4\uC99D \uC870\uAC74"]] }, "faq": [["\uAE30\uAE30\uAC12\uB9CC \uB530\uB85C \uC54C \uC218 \uC788\uB098\uC694?", "\uACAC\uC801\uC11C\uC5D0 \uD56D\uBAA9\uBCC4\uB85C \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD558\uBA74 \uB429\uB2C8\uB2E4. \uD56D\uBAA9\uC774 \uB098\uB258\uC5B4 \uC788\uC5B4\uC57C \uC784\uB300\uC640 \uAD6C\uB9E4\uB97C \uAC19\uC740 \uAE30\uC900\uC73C\uB85C \uBE44\uAD50\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC124\uCE58\uBE44\uC6A9\uC744 \uB098\uC911\uC5D0 \uB3CC\uB824\uBC1B\uB294 \uACBD\uC6B0\uAC00 \uC788\uB098\uC694?", "\uB3CC\uB824\uBC1B\uB294 \uAD6C\uC870\uB294 \uC544\uB2D9\uB2C8\uB2E4. \uC57D\uC815 \uC911 \uD574\uC9C0\uD558\uBA74 \uC624\uD788\uB824 \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uC73C\uBBC0\uB85C \uC57D\uC815\uC11C\uC758 \uD574\uC9C0 \uC870\uD56D\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4."], ["\uAC04\uC774\uACFC\uC138\uC790\uB294 \uBE44\uC6A9\uC774 \uB2E4\uB978\uAC00\uC694?", "\uC124\uCE58\uBE44\uC6A9 \uC790\uCCB4\uB294 \uAC19\uC2B5\uB2C8\uB2E4. \uC218\uC218\uB8CC \uCABD\uC774 \uAC00\uB9F9\uC810 \uB9E4\uCD9C \uAD6C\uBD84\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C8 \uBFD0\uC785\uB2C8\uB2E4. \uAC04\uC774\uACFC\uC138\uC790 \uC5EC\uBD80\uB85C \uC124\uCE58 \uC870\uAC74\uC774 \uB2EC\uB77C\uC9C0\uB294 \uACBD\uC6B0\uB294 \uC5C6\uC73C\uB2C8 \uACFC\uC138 \uC720\uD615\uBCF4\uB2E4 \uACB0\uC81C \uBC29\uC2DD\uC744 \uAE30\uC900\uC73C\uB85C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4."], ["\uCD94\uAC00 \uB2E8\uB9D0\uAE30\uB294 \uBE44\uC6A9\uC774 \uB610 \uB4DC\uB098\uC694?", "\uB300\uC218\uB9CC\uD07C \uAE30\uAE30\uAC12\uC774 \uB354\uD574\uC9D1\uB2C8\uB2E4. \uAC19\uC740 \uB0A0 \uD568\uAED8 \uC124\uCE58\uD558\uBA74 \uCD9C\uC7A5\uBE44\uB294 \uD55C \uBC88\uC73C\uB85C \uBB36\uC774\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uCC98\uC74C\uBD80\uD130 \uB300\uC218\uB97C \uC815\uD574 \uC811\uC218\uD569\uB2C8\uB2E4. \uCD94\uAC00 \uC124\uCE58\uB294 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uB4F1\uB85D\uB418\uBBC0\uB85C \uC815\uC0B0\uC11C\uB294 \uD558\uB098\uB85C \uB4E4\uC5B4\uC635\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uC5C5\uCCB4", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uC124\uCE58\uC5C5\uCCB4 \uACE0\uB974\uB294 \uBC95", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uC5C5\uCCB4\uB294 \uC5B4\uB5BB\uAC8C \uACE0\uB974\uB098\uC694? \u2014 \uACAC\uC801\uC11C\uC5D0\uC11C \uD655\uC778\uD560 \uB2E4\uC12F \uAC00\uC9C0", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uC5C5\uCCB4\uB97C \uACE0\uB97C \uB54C \uACAC\uC801\uC11C \uD56D\uBAA9, \uAE30\uAE30 \uBAA8\uB378\uBA85, \uC57D\uC815\uACFC \uD574\uC9C0 \uC870\uAC74, \uACE0\uC7A5 \uB300\uC751 \uCC3D\uAD6C, \uC815\uC0B0 \uBB38\uC758\uCC98, \uC124\uCE58 \uC9C0\uC5ED\uC744 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD655\uC778\uD558\uB294\uC9C0\uC640 \uD53C\uD574\uC57C \uD560 \uC81C\uC548\uC758 \uD2B9\uC9D5, \uC124\uCE58\uC5C5\uCCB4\uC640 \uBC34\uC0AC\uC758 \uCC28\uC774\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC124\uCE58\uC5C5\uCCB4\uB294 \uACAC\uC801\uC11C\uAC00 \uD56D\uBAA9\uBCC4\uB85C \uB098\uB258\uC5B4 \uC788\uB294\uC9C0, \uC57D\uC815\uACFC \uD574\uC9C0 \uC870\uAC74\uC774 \uBB38\uC11C\uB85C \uC788\uB294\uC9C0, \uACE0\uC7A5 \uB54C \uB204\uAC00 \uC5B4\uB5BB\uAC8C \uB300\uC751\uD558\uB294\uC9C0 \uC138 \uAC00\uC9C0\uB85C \uBA3C\uC800 \uAC00\uB985\uB2C8\uB2E4. \uAC00\uACA9\uBCF4\uB2E4 \uC6B4\uC601 \uC911\uC5D0 \uC5F0\uB77D\uC774 \uB2FF\uB294\uC9C0\uAC00 \uB9E4\uC7A5\uC5D0\uB294 \uB354 \uC911\uC694\uD558\uACE0, \uC774 \uC138 \uAC00\uC9C0\uAC00 \uBB38\uC11C\uB85C \uC5C6\uB294 \uC5C5\uCCB4\uB294 \uB4A4\uB85C \uBBF8\uB8F9\uB2C8\uB2E4.", "sections": [{ "h": "\uACAC\uC801\uC11C\uC5D0\uC11C \uBB34\uC5C7\uC744 \uBD10\uC57C \uD558\uB098\uC694?", "p": ["\uAE30\uAE30\uAC12, \uCD9C\uC7A5\uBE44, \uD1B5\uC2E0\uBE44, \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB530\uB85C \uC801\uD600 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4. \uD569\uACC4\uB9CC \uC801\uD78C \uACAC\uC801\uC11C\uB294 \uB098\uC911\uC5D0 \uC5B4\uB290 \uD56D\uBAA9\uC774 \uBC14\uB00C\uC5C8\uB294\uC9C0 \uB530\uC9C0\uAE30 \uC5B4\uB835\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uACAC\uC801\uC11C\uB098 \uBCC4\uC9C0\uC5D0 \uAE00\uB85C \uB0A8\uC544 \uC788\uC5B4\uC57C \uD558\uACE0, \uB9D0\uB85C\uB9CC \uC124\uBA85\uD558\uB294 \uC870\uAC74\uC740 \uC5C6\uB294 \uAC83\uC73C\uB85C \uCE69\uB2C8\uB2E4.", "\uAE30\uAE30 \uBAA8\uB378\uBA85\uC774 \uC801\uD600 \uC788\uB294\uC9C0\uB3C4 \uD655\uC778\uD569\uB2C8\uB2E4. \uBAA8\uB378\uBA85\uC774 \uC5C6\uC73C\uBA74 \uC124\uCE58 \uB2F9\uC77C \uB2E4\uB978 \uAE30\uAE30\uAC00 \uC62C \uC218 \uC788\uACE0 \uB4A4\uC5D0 \uB530\uC9C8 \uADFC\uAC70\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC744 \uB450 \uACF3 \uC774\uC0C1\uC5D0\uC11C \uAC19\uC740 \uC870\uAC74\uC73C\uB85C \uBC1B\uC544\uC57C \uD56D\uBAA9\uBCC4\uB85C \uB9DE\uCDB0 \uBCFC \uC218 \uC788\uC73C\uBBC0\uB85C \uB300\uC218\uC640 \uACB0\uC81C \uBC29\uC2DD\uC744 \uB611\uAC19\uC774 \uC801\uC5B4 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uC801\uD78C \uB2F4\uB2F9\uC790 \uC774\uB984\uACFC \uC5F0\uB77D\uCC98\uAC00 \uC124\uCE58 \uB4A4\uC5D0\uB3C4 \uC720\uD6A8\uD55C\uC9C0 \uBB3B\uACE0, \uD68C\uC0AC \uB300\uD45C \uBC88\uD638\uB3C4 \uD568\uAED8 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uACAC\uC801 \uC720\uD6A8 \uAE30\uAC04\uC774 \uC788\uB294\uC9C0\uB3C4 \uBD05\uB2C8\uB2E4. \uAE30\uAC04\uC774 \uC9C0\uB098\uBA74 \uC870\uAC74\uC774 \uBC14\uB014 \uC218 \uC788\uC5B4 \uACB0\uC815 \uC2DC\uC810\uC744 \uADF8 \uC548\uC5D0 \uB461\uB2C8\uB2E4."] }, { "h": "\uC6B4\uC601 \uC911 \uB300\uC751\uC740 \uC5B4\uB5BB\uAC8C \uD655\uC778\uD558\uB098\uC694?", "p": ["\uB2E8\uB9D0\uAE30\uAC00 \uBA48\uCDC4\uC744 \uB54C \uC804\uD654\uB97C \uBC1B\uB294 \uCC3D\uAD6C\uAC00 \uC124\uCE58\uC5C5\uCCB4\uC778\uC9C0 \uBC34\uC0AC\uC778\uC9C0 \uBA3C\uC800 \uBB3B\uACE0, \uADF8 \uBC88\uD638\uB97C \uC57D\uC815\uC11C\uC5D0 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAE30\uB97C \uBCF4\uB0B4 \uC8FC\uB294 \uAE30\uC900\uACFC \uAC78\uB9AC\uB294 \uC2DC\uAC04\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4. \uAE30\uC900\uC774 \uC5C6\uC73C\uBA74 \uACE0\uC7A5 \uB54C\uB9C8\uB2E4 \uD611\uC758\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uC815\uC0B0\uC774 \uC798\uBABB \uB4E4\uC5B4\uC654\uC744 \uB54C \uC5B4\uB514\uC5D0 \uBB3C\uC5B4\uC57C \uD558\uB294\uC9C0\uB3C4 \uC124\uCE58 \uC804\uC5D0 \uC54C\uC544 \uB450\uBA74 \uCCAB \uC815\uC0B0 \uB54C \uB2F9\uD669\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5\uC774 \uC788\uB294 \uC9C0\uC5ED\uC5D0 \uAE30\uC0AC\uAC00 \uC624\uB294\uC9C0, \uC6D0\uACA9\uC73C\uB85C\uB9CC \uCC98\uB9AC\uD558\uB294\uC9C0\uB3C4 \uCC28\uC774\uAC00 \uD07D\uB2C8\uB2E4. \uC6D0\uACA9\uB9CC \uB418\uB294 \uC5C5\uCCB4\uB294 \uAE30\uAE30 \uAD50\uCCB4\uAC00 \uD0DD\uBC30\uB85C \uC9C4\uD589\uB429\uB2C8\uB2E4.", "\uC57C\uAC04 \uC601\uC5C5 \uB9E4\uC7A5\uC774\uBA74 \uC601\uC5C5 \uC2DC\uAC04\uC5D0 \uBC1B\uB294 \uCC3D\uAD6C\uAC00 \uC788\uB294\uC9C0 \uD655\uC778\uD558\uACE0, \uC8FC\uB9D0 \uB300\uC751 \uC5EC\uBD80\uB3C4 \uAC19\uC774 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uC124\uC815 \uBCC0\uACBD\uC744 \uC694\uCCAD\uD588\uC744 \uB54C \uCC98\uB9AC \uBC29\uC2DD(\uC6D0\uACA9\xB7\uBC29\uBB38)\uACFC \uBE44\uC6A9 \uC720\uBB34\uB97C \uBBF8\uB9AC \uB4E4\uC5B4 \uB461\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uCCAB \uACE0\uC7A5 \uB54C \uAC78\uB9B0 \uC2DC\uAC04\uACFC \uB300\uC751\uC744 \uC801\uC5B4 \uB450\uBA74 \uC57D\uC815 \uAC31\uC2E0 \uB54C \uC5C5\uCCB4\uB97C \uBC14\uAFC0\uC9C0 \uD310\uB2E8\uD558\uB294 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uD53C\uD574\uC57C \uD560 \uC2E0\uD638\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04\uC744 \uB9D0\uB85C\uB9CC \uC124\uBA85\uD558\uACE0 \uBB38\uC11C\uB97C \uC8FC\uC9C0 \uC54A\uB294 \uACBD\uC6B0\uAC00 \uCCAB \uBC88\uC9F8 \uC2E0\uD638\uC785\uB2C8\uB2E4.", "\uC218\uC218\uB8CC\uB97C \uC124\uCE58\uC5C5\uCCB4\uAC00 \uC815\uD560 \uC218 \uC788\uB2E4\uACE0 \uB9D0\uD558\uB294 \uACBD\uC6B0\uB3C4 \uC870\uC2EC\uD569\uB2C8\uB2E4. \uC218\uC218\uB8CC \uAD6C\uAC04\uC740 \uAC00\uB9F9\uC810 \uB9E4\uCD9C\uC5D0 \uB530\uB77C \uC815\uD574\uC9C0\uB294 \uBD80\uBD84\uC774 \uD07D\uB2C8\uB2E4.", "\uC0AC\uC740\uD488\uC774\uB098 \uC9C0\uC6D0\uAE08\uC744 \uC55E\uC138\uC6B0\uBA74\uC11C \uAE30\uAE30 \uBAA8\uB378\uACFC \uC6D4 \uBE44\uC6A9\uC744 \uD750\uB9AC\uB294 \uC81C\uC548\uC740 \uD56D\uBAA9\uC744 \uB2E4\uC2DC \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uC5F0\uB77D\uC774 \uB04A\uAE30\uB294 \uC5C5\uCCB4\uB294 \uC57D\uC815\uC11C\uC5D0 \uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uAC00 \uC5C6\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uADF8 \uC904\uBD80\uD130 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uACC4\uC57D\uC744 \uB2F9\uC77C\uC5D0 \uC11C\uB450\uB974\uAC8C \uD558\uB294 \uC81C\uC548\uC740 \uD558\uB8E8 \uB450\uACE0 \uACAC\uC801\uC11C\uB97C \uB2E4\uC2DC \uC77D\uACE0, \uC77D\uB294 \uB3D9\uC548 \uC870\uAC74\uC774 \uBC14\uB00C\uBA74 \uADF8 \uC790\uCCB4\uAC00 \uC2E0\uD638\uC785\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC758 \uB2F9\uC0AC\uC790 \uD68C\uC0AC\uBA85\uC774 \uACAC\uC801\uC11C\uC758 \uD68C\uC0AC\uBA85\uACFC \uB2E4\uB974\uBA74 \uC5B4\uB290 \uCABD\uC774 \uCC45\uC784\uC9C0\uB294\uC9C0 \uBC18\uB4DC\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58\uC5C5\uCCB4\uC640 \uBC34\uC0AC\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uBC34\uC0AC\uB294 \uACB0\uC81C \uC2B9\uC778\uC744 \uC911\uACC4\uD558\uACE0 \uC815\uC0B0 \uC790\uB8CC\uB97C \uB9CC\uB4DC\uB294 \uD68C\uC0AC\uC774\uACE0, \uC124\uCE58\uC5C5\uCCB4\uB294 \uAE30\uAE30\uB97C \uB193\uACE0 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC744 \uB3D5\uB294 \uACF3\uC785\uB2C8\uB2E4.", "\uB458\uC774 \uAC19\uC740 \uD68C\uC0AC\uC77C \uC218\uB3C4 \uC788\uACE0, \uC124\uCE58\uC5C5\uCCB4\uAC00 \uD2B9\uC815 \uBC34\uC0AC\uC758 \uB300\uB9AC\uC810\uC778 \uACBD\uC6B0\uB3C4 \uC788\uC5B4 \uC57D\uC815\uC11C \uC0C1\uB2E8\uC758 \uB2F9\uC0AC\uC790 \uC774\uB984\uC73C\uB85C \uAD6C\uBD84\uD569\uB2C8\uB2E4.", "\uC5B4\uB290 \uCABD\uC774 \uC57D\uC815 \uB2F9\uC0AC\uC790\uC778\uC9C0 \uC54C\uC544\uC57C \uD574\uC9C0\uB098 \uAD50\uCCB4\uB97C \uC694\uCCAD\uD560 \uACF3\uC774 \uBD84\uBA85\uD574\uC9D1\uB2C8\uB2E4.", "\uBC34\uC0AC\uAC00 \uBC14\uB00C\uBA74 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uB3C4 \uB2E4\uC2DC \uD574\uC57C \uD560 \uC218 \uC788\uC5B4 \uC5C5\uCCB4 \uBCC0\uACBD \uC804\uC5D0 \uBB3B\uACE0, \uACB0\uC81C\uAC00 \uB04A\uAE30\uB294 \uB0A0\uC774 \uC5C6\uB3C4\uB85D \uB0A0\uC9DC\uB97C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uC815\uC0B0 \uBB38\uC758\uB294 \uBCF4\uD1B5 \uBC34\uC0AC\uB098 \uCE74\uB4DC\uC0AC \uCC3D\uAD6C\uC774\uACE0, \uAE30\uAE30 \uBB38\uC758\uB294 \uC124\uCE58\uC5C5\uCCB4 \uCC3D\uAD6C\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uB450 \uBC88\uD638\uB97C \uB530\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uBC34\uC0AC \uB300\uB9AC\uC810\uC774\uBA74 \uBC34\uC0AC \uACE0\uAC1D\uC13C\uD130\uB85C\uB3C4 \uC5F0\uB77D\uD560 \uC218 \uC788\uC73C\uBBC0\uB85C \uB300\uB9AC\uC810 \uC5F0\uB77D\uC774 \uC548 \uB420 \uB54C\uC758 \uB300\uC548\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uC124\uCE58\uC5C5\uCCB4\uAC00 \uBC14\uB00C\uC5B4\uB3C4 \uBC34\uC0AC\uAC00 \uAC19\uC73C\uBA74 \uC815\uC0B0 \uCC3D\uAD6C\uB294 \uADF8\uB300\uB85C\uC774\uBBC0\uB85C \uB9E4\uC7A5 \uC6B4\uC601\uC5D0 \uBBF8\uCE58\uB294 \uC601\uD5A5\uC774 \uC791\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uC5C5\uCCB4\uB97C \uACE0\uB974\uB294 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uAC19\uC740 \uC870\uAC74\uC73C\uB85C \uACAC\uC801\uC744 \uB450 \uACF3 \uC774\uC0C1 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD56D\uBAA9\uBCC4 \uAE08\uC561\uACFC \uAE30\uAE30 \uBAA8\uB378\uBA85, \uC57D\uC815 \uC870\uAC74\uC744 \uB098\uB780\uD788 \uC801\uC5B4 \uBD05\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB300\uC751 \uCC3D\uAD6C\uC640 \uC815\uC0B0 \uBB38\uC758\uCC98\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBB38\uC11C\uB85C \uB0A8\uC740 \uC870\uAC74\uC744 \uAE30\uC900\uC73C\uB85C \uACB0\uC815\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C \uC0C1\uB2E8\uC758 \uB2F9\uC0AC\uC790 \uD68C\uC0AC\uBA85\uACFC \uACAC\uC801\uC11C \uD68C\uC0AC\uBA85\uC774 \uAC19\uC740\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC124\uCE58\uC5C5\uCCB4 \uD655\uC778 \uD56D\uBAA9", "head": ["\uD655\uC778 \uD56D\uBAA9", "\uC788\uC5B4\uC57C \uD560 \uAC83", "\uC5C6\uC744 \uB54C"], "rows": [["\uACAC\uC801\uC11C", "\uD56D\uBAA9\uBCC4 \uAE08\uC561\xB7\uBAA8\uB378\uBA85", "\uB2E4\uC2DC \uC694\uCCAD"], ["\uC57D\uC815", "\uAE30\uAC04\xB7\uD574\uC9C0 \uC870\uAC74 \uBB38\uC11C", "\uC11C\uBA74 \uC694\uCCAD"], ["\uACE0\uC7A5 \uB300\uC751", "\uCC3D\uAD6C\xB7\uAD50\uCCB4 \uAE30\uC900", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"], ["\uC815\uC0B0 \uBB38\uC758", "\uB2F4\uB2F9 \uC5F0\uB77D\uCC98", "\uC124\uCE58 \uC804 \uD655\uBCF4"], ["\uC57D\uC815 \uB2F9\uC0AC\uC790", "\uD68C\uC0AC\uBA85\xB7\uB300\uD45C \uBC88\uD638", "\uC57D\uC815\uC11C \uC0C1\uB2E8 \uD655\uC778"]] }, "faq": [["\uACAC\uC801\uC744 \uBC1B\uC73C\uBA74 \uAF2D \uACC4\uC57D\uD574\uC57C \uD558\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uACAC\uC801\uC740 \uC870\uAC74\uC744 \uB9DE\uCDB0 \uBCF4\uB294 \uB2E8\uACC4\uC774\uACE0 \uC57D\uC815\uC11C\uC5D0 \uC11C\uBA85\uD558\uAE30 \uC804\uAE4C\uC9C0\uB294 \uACC4\uC57D\uC774 \uC544\uB2D9\uB2C8\uB2E4. \uACAC\uC801\uC11C \uC0AC\uBCF8\uC740 \uC0AC\uC9C4\uC73C\uB85C\uB77C\uB3C4 \uB0A8\uACA8 \uB450\uBA74 \uB098\uC911\uC5D0 \uC870\uAC74\uC744 \uB300\uC870\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC9C0\uC5ED \uC5C5\uCCB4\uC640 \uC804\uAD6D \uC5C5\uCCB4 \uC911 \uC5B4\uB290 \uCABD\uC774 \uB098\uC740\uAC00\uC694?", "\uAE30\uC0AC\uAC00 \uB9E4\uC7A5\uAE4C\uC9C0 \uC624\uB294\uC9C0\uAC00 \uAE30\uC900\uC785\uB2C8\uB2E4. \uC804\uAD6D \uC5C5\uCCB4\uB77C\uB3C4 \uC9C0\uC5ED\uC5D0 \uAE30\uC0AC\uAC00 \uC5C6\uC73C\uBA74 \uC6D0\uACA9 \uB300\uC751\uACFC \uD0DD\uBC30 \uAD50\uCCB4\uB9CC \uB429\uB2C8\uB2E4."], ["\uC0AC\uC740\uD488\uC744 \uC8FC\uB294 \uC870\uAC74\uC740 \uAD1C\uCC2E\uB098\uC694?", "\uC0AC\uC740\uD488 \uAC12\uC774 \uC6D4 \uC774\uC6A9\uB8CC\uB098 \uC57D\uC815 \uAE30\uAC04\uC5D0 \uB4E4\uC5B4\uAC00 \uC788\uB294\uC9C0 \uD56D\uBAA9\uC73C\uB85C \uD655\uC778\uD558\uBA74 \uB429\uB2C8\uB2E4. \uB4E4\uC5B4\uAC00 \uC788\uB2E4\uBA74 \uADF8\uB9CC\uD07C \uC6D4 \uBE44\uC6A9\uC774 \uB192\uC740 \uAC83\uC785\uB2C8\uB2E4."], ["\uC5C5\uCCB4\uB97C \uBC14\uAFB8\uBA74 \uAC00\uB9F9\uC810\uB3C4 \uC0C8\uB85C \uD574\uC57C \uD558\uB098\uC694?", "\uBC34\uC0AC\uAC00 \uAC19\uC73C\uBA74 \uAE30\uAE30\uB9CC \uBC14\uB00C\uACE0, \uBC34\uC0AC\uAC00 \uB2EC\uB77C\uC9C0\uBA74 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC744 \uB2E4\uC2DC \uD558\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4. \uBC14\uAFB8\uAE30 \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4. \uBC34\uC0AC \uBCC0\uACBD\uC774 \uD544\uC694\uD55C\uC9C0\uB294 \uC0C8 \uC5C5\uCCB4\uC5D0 \uBB3C\uC73C\uBA74 \uBC14\uB85C \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uC784\uB300 vs \uAD6C\uB9E4", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB294 \uC784\uB300\uC640 \uAD6C\uB9E4 \uC911 \uBB34\uC5C7\uC774 \uB9DE\uB098\uC694? \u2014 \uC6B4\uC601 \uAE30\uAC04\uC73C\uB85C \uAC00\uB974\uB294 \uBC95", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC784\uB300\uC640 \uAD6C\uB9E4\uB97C \uC6B4\uC601 \uAE30\uAC04, \uCD08\uAE30 \uBD80\uB2F4, \uC6D4 \uBE44\uC6A9, \uACE0\uC7A5 \uAD50\uCCB4, \uD574\uC9C0 \uC870\uAC74\uC73C\uB85C \uBE44\uAD50\uD574 \uAC1C\uC5C5 \uC9C1\uD6C4 \uB9E4\uC7A5\uACFC \uC7A5\uAE30 \uC6B4\uC601 \uB9E4\uC7A5\uC5D0 \uAC01\uAC01 \uC5B4\uB290 \uCABD\uC774 \uB9DE\uB294\uC9C0, \uACB0\uC815 \uC804\uC5D0 \uAC19\uC774 \uBCFC \uD56D\uBAA9\uACFC \uC911\uAC04\uC5D0 \uBC29\uC2DD\uC744 \uBC14\uAFB8\uB294 \uC870\uAC74\uAE4C\uC9C0 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC6B4\uC601 \uAE30\uAC04\uC774 \uC57D\uC815 \uAE30\uAC04\uBCF4\uB2E4 \uAE38 \uAC83 \uAC19\uC73C\uBA74 \uAD6C\uB9E4, \uC9E7\uAC70\uB098 \uBD88\uD655\uC2E4\uD558\uBA74 \uC784\uB300\uAC00 \uB9DE\uC2B5\uB2C8\uB2E4. \uB450 \uBC29\uC2DD\uC740 \uAE30\uAE30\uAC12\uC744 \uC5B8\uC81C \uC5B4\uB5BB\uAC8C \uB0B4\uB290\uB0D0\uC758 \uCC28\uC774\uC774\uACE0 \uACB0\uC81C \uAE30\uB2A5 \uC790\uCCB4\uB294 \uAC19\uC73C\uBBC0\uB85C, \uC608\uC0C1 \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uB97C \uBA3C\uC800 \uC801\uC5B4 \uBCF4\uB294 \uAC83\uC774 \uACB0\uC815\uC758 \uCD9C\uBC1C\uC810\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uC784\uB300\uB294 \uC5B4\uB5A4 \uB9E4\uC7A5\uC5D0 \uB9DE\uB098\uC694?", "p": ["\uAC1C\uC5C5 \uC9C1\uD6C4\uB77C \uC6B4\uC601\uC774 \uC5B4\uB5BB\uAC8C \uB420\uC9C0 \uBAA8\uB974\uB294 \uB9E4\uC7A5, \uD31D\uC5C5\uC774\uB098 \uACC4\uC808 \uC601\uC5C5\uCC98\uB7FC \uAE30\uAC04\uC774 \uC815\uD574\uC9C4 \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0 \uD070\uB3C8\uC774 \uB098\uAC00\uC9C0 \uC54A\uACE0 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uB098\uB258\uC5B4 \uB098\uAC00\uBBC0\uB85C \uAC1C\uC5C5 \uC790\uAE08\uC774 \uBE60\uB4EF\uD55C \uB9E4\uC7A5\uC5D0\uC11C \uCD08\uAE30 \uBD80\uB2F4\uC744 \uC904\uC785\uB2C8\uB2E4.", "\uAE30\uAE30 \uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uAE30\uAE30\uB97C \uBC1B\uB294 \uC870\uAC74\uC774 \uC57D\uC815\uC5D0 \uD3EC\uD568\uB41C \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uC6B4\uC601 \uC911 \uC2E0\uACBD \uC4F8 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uB300\uC2E0 \uC57D\uC815 \uAE30\uAC04\uC774 \uC788\uACE0, \uAE30\uAC04 \uC548\uC5D0 \uADF8\uB9CC\uB450\uBA74 \uB0A8\uC740 \uAC1C\uC6D4 \uC870\uAC74\uC774 \uBD99\uC73C\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uBC18\uB4DC\uC2DC \uC77D\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815\uC774 \uB05D\uB09C \uB4A4 \uAE30\uAE30\uB97C \uC5B4\uB5BB\uAC8C \uD558\uB294\uC9C0\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC5B4\uC57C \uD558\uACE0, \uC790\uB3D9 \uC5F0\uC7A5 \uC870\uD56D\uC774 \uC788\uC73C\uBA74 \uB05D\uB098\uAE30 \uC804\uC5D0 \uC758\uC0AC\uB97C \uBC1D\uD600\uC57C \uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uC8FC\uAE30\uAC00 \uC9E7\uC740 \uBB34\uC120\uAE30\uB098 \uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC740 \uC784\uB300\uB85C \uC4F0\uB2E4 \uBC14\uAFB8\uB294 \uD3B8\uC774 \uD3B8\uD55C \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uC758 \uC218\uB9AC\uC640 \uAD50\uCCB4\uAC00 \uBB34\uC0C1\uC778\uC9C0 \uC720\uC0C1\uC778\uC9C0\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uB530\uB85C \uC801\uD600 \uC788\uB294 \uD56D\uBAA9\uC785\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04 \uC911 \uD3D0\uC5C5 \uAC00\uB2A5\uC131\uC774 \uC870\uAE08\uC774\uB77C\uB3C4 \uC788\uC73C\uBA74 \uC784\uB300\uC758 \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uC774 \uCD1D\uBE44\uC6A9\uC744 \uC88C\uC6B0\uD558\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uBA3C\uC800 \uC77D\uC2B5\uB2C8\uB2E4."] }, { "h": "\uAD6C\uB9E4\uB294 \uC5B4\uB5A4 \uB9E4\uC7A5\uC5D0 \uB9DE\uB098\uC694?", "p": ["\uBA87 \uB144 \uC774\uC0C1 \uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uC6B4\uC601\uD560 \uACC4\uD68D\uC774 \uC120 \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0 \uAE30\uAE30\uAC12\uC744 \uB0B4\uACE0 \uB098\uBA74 \uC6D4 \uBE44\uC6A9\uC740 \uD1B5\uC2E0\uB8CC \uC815\uB3C4\uB9CC \uB0A8\uC544 \uC624\uB798 \uC4F8\uC218\uB85D \uBD80\uB2F4\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uAE30\uAC00 \uB9E4\uC7A5 \uC18C\uC720\uC774\uBBC0\uB85C \uC5C5\uCCB4\uB97C \uBC14\uAFB8\uAC70\uB098 \uC774\uC804\uD560 \uB54C \uC81C\uC57D\uC774 \uC801\uACE0, \uBC18\uB0A9 \uC808\uCC28\uB3C4 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C\uB294 \uBCF4\uC99D \uAE30\uAC04\uACFC \uC218\uB9AC \uBE44\uC6A9 \uC870\uAC74\uC744 \uB530\uB85C \uD655\uC778\uD574\uC57C \uD558\uACE0, \uBCF4\uC99D\uC774 \uB05D\uB09C \uB4A4\uC758 \uC218\uB9AC\uB294 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uACB0\uC81C \uADDC\uACA9\uC774 \uBC14\uB00C\uC5B4 \uAE30\uAE30\uB97C \uBC14\uAFD4\uC57C \uD560 \uB54C\uB294 \uAD6C\uB9E4 \uB9E4\uC7A5\uC774 \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uC9C1\uC811 \uBD80\uB2F4\uD558\uAC8C \uB418\uBBC0\uB85C \uAE30\uAE30 \uC138\uB300\uAC00 \uCD5C\uC2E0\uC778\uC9C0 \uC0AC\uAE30 \uC804\uC5D0 \uBD05\uB2C8\uB2E4.", "\uC5EC\uB7EC \uB300\uB97C \uC4F0\uB294 \uB9E4\uC7A5\uC740 \uAD6C\uB9E4\uC640 \uC784\uB300\uB97C \uC11E\uC5B4 \uC8FC \uAE30\uAE30\uB294 \uAD6C\uB9E4, \uC608\uBE44 \uAE30\uAE30\uB294 \uC784\uB300\uB85C \uB450\uB294 \uBC29\uBC95\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB294 \uBD80\uC18D\uD488(\uC5B4\uB311\uD130\xB7\uAC70\uCE58\uB300)\uC774 \uACE0\uC7A5 \uB0AC\uC744 \uB54C \uB530\uB85C \uC0AC\uC57C \uD558\uBBC0\uB85C \uBD80\uC18D\uD488 \uBCF4\uC99D\uB3C4 \uBD05\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB294 \uBCF4\uC99D\uC11C\uC640 \uAD6C\uB9E4 \uC601\uC218\uC99D\uC744 \uBCF4\uAD00\uD574\uC57C \uBCF4\uC99D \uAE30\uAC04 \uC548 \uC218\uB9AC\uAC00 \uBB34\uC0C1\uC73C\uB85C \uCC98\uB9AC\uB429\uB2C8\uB2E4."] }, { "h": "\uACB0\uC815\uD560 \uB54C \uBB34\uC5C7\uC744 \uAC19\uC774 \uBD10\uC57C \uD558\uB098\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04\uACFC \uC608\uC0C1 \uC6B4\uC601 \uAE30\uAC04\uC744 \uB098\uB780\uD788 \uB193\uACE0, \uC6B4\uC601 \uAE30\uAC04\uC774 \uC9E7\uC73C\uBA74 \uC784\uB300 \uCABD \uCD1D\uBE44\uC6A9\uC774 \uB0AE\uC544\uC9C0\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uC8FC\uAE30\uB3C4 \uBD05\uB2C8\uB2E4. \uACB0\uC81C \uADDC\uACA9\uC774\uB098 \uBCF4\uC548 \uC778\uC99D \uAE30\uC900\uC774 \uBC14\uB00C\uBA74 \uC624\uB798\uB41C \uAE30\uAE30\uB294 \uAD50\uCCB4\uAC00 \uD544\uC694\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBC30\uB2EC\uC774\uB098 \uD589\uC0AC\uCC98\uB7FC \uBB34\uC120\uAE30\uB97C \uC4F0\uB294 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uC218\uBA85\uC774 \uC9E7\uC544 \uC784\uB300\uAC00 \uD3B8\uD55C \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5B4\uB290 \uCABD\uC774\uB4E0 \uACAC\uC801\uC11C\uC5D0 \uAE30\uAE30 \uBAA8\uB378\uBA85\uACFC \uC6D4 \uBE44\uC6A9, \uC57D\uC815 \uC870\uAC74\uC774 \uAE00\uB85C \uB0A8\uC544 \uC788\uC5B4\uC57C \uBE44\uAD50\uAC00 \uB429\uB2C8\uB2E4.", "\uD1B5\uC2E0\uB8CC\uB294 \uB450 \uBC29\uC2DD \uBAA8\uB450 \uB530\uB85C \uB098\uAC00\uBBC0\uB85C \uBE44\uAD50\uD45C\uC5D0\uC11C \uBE7C\uACE0 \uBCF4\uBA74 \uCC28\uC774\uAC00 \uBD84\uBA85\uD574\uC9D1\uB2C8\uB2E4.", "\uC5C5\uCCB4\uB97C \uBC14\uAFC0 \uAC00\uB2A5\uC131\uC774 \uC788\uC73C\uBA74 \uAD6C\uB9E4 \uAE30\uAE30\uAC00 \uB2E4\uB978 \uBC34\uC0AC\uC5D0\uC11C\uB3C4 \uB4F1\uB85D\uB418\uB294 \uBAA8\uB378\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uC885\uB8CC \uC2DC\uC810\uC5D0 \uACB0\uC81C \uADDC\uACA9\uC774 \uBC14\uB014 \uAC00\uB2A5\uC131\uAE4C\uC9C0 \uB123\uC5B4 \uB450\uBA74 \uC5B4\uB290 \uCABD\uC774 \uC548\uC804\uD55C\uC9C0 \uD310\uB2E8\uC774 \uC27D\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC911\uAC04\uC5D0 \uBC29\uC2DD\uC744 \uBC14\uAFC0 \uC218 \uC788\uB098\uC694?", "p": ["\uC784\uB300 \uC911 \uAD6C\uB9E4\uB85C \uBC14\uAFB8\uB294 \uC804\uD658 \uC870\uAC74\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uBA3C\uC800 \uCC3E\uC544\uBD05\uB2C8\uB2E4.", "\uC804\uD658\uC774 \uC5C6\uC73C\uBA74 \uC57D\uC815 \uC885\uB8CC \uC2DC\uC810\uC5D0 \uC0C8\uB85C \uC815\uD558\uB294 \uAC83\uC774 \uBE44\uC6A9\uC774 \uC801\uACE0, \uC885\uB8CC \uC804\uC5D0 \uD574\uC9C0\uD558\uBA74 \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB97C \uB098\uC911\uC5D0 \uC784\uB300 \uC57D\uC815\uC73C\uB85C \uB3CC\uB9AC\uB294 \uACBD\uC6B0\uB294 \uB4DC\uBB3C\uACE0, \uBCF4\uD1B5\uC740 \uC0C8 \uAE30\uAE30 \uC784\uB300\uB85C \uC2DC\uC791\uD569\uB2C8\uB2E4.", "\uC804\uD658 \uAC00\uB2A5 \uC5EC\uBD80\uC640 \uC870\uAC74\uC740 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC804\uD658\uD560 \uB54C \uAC00\uB9F9\uC810 \uBC88\uD638\uB294 \uADF8\uB300\uB85C \uC4F0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC9C0\uB9CC \uBC34\uC0AC\uAC00 \uBC14\uB00C\uBA74 \uB2E4\uC2DC \uB4F1\uB85D\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uBC29\uC2DD\uC744 \uBC14\uAFB8\uB294 \uC2DC\uC810\uC5D0\uB294 \uAE30\uAE30 \uBAA8\uB378\uC774 \uBC14\uB00C\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uD3EC\uC2A4 \uC5F0\uB3D9 \uC5EC\uBD80\uB97C \uB2E4\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uACAC\uC801\uC11C \uB450 \uC7A5\uC744 \uAC19\uC740 \uD45C\uC5D0 \uC62E\uACA8 \uC801\uC73C\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC5D0\uC11C \uCC28\uC774\uAC00 \uB098\uB294\uC9C0 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4."] }], "steps": { "h": "\uC120\uD0DD \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uC608\uC0C1 \uC6B4\uC601 \uAE30\uAC04\uC744 \uC801\uC5B4 \uBD05\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4 \uACAC\uC801\uC744 \uAC19\uC740 \uAE30\uAE30\uB85C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC6B4\uC601 \uAE30\uAC04 \uB3D9\uC548\uC758 \uCD1D\uBE44\uC6A9\uC744 \uB450 \uBC29\uC2DD\uC73C\uB85C \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uAD50\uCCB4\uC640 \uD574\uC9C0 \uC870\uAC74\uC744 \uC77D\uACE0 \uACB0\uC815\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uC804\uD658 \uC870\uAC74\uACFC \uC885\uB8CC \uB4A4 \uCC98\uB9AC \uBC29\uC2DD\uC774 \uC801\uD614\uB294\uC9C0 \uC11C\uBA85 \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC784\uB300\uC640 \uAD6C\uB9E4 \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uC784\uB300", "\uAD6C\uB9E4"], "rows": [["\uCD08\uAE30 \uBD80\uB2F4", "\uB0AE\uC74C", "\uB192\uC74C"], ["\uC6D4 \uBE44\uC6A9", "\uC774\uC6A9\uB8CC+\uD1B5\uC2E0\uB8CC", "\uD1B5\uC2E0\uB8CC"], ["\uC57D\uC815", "\uC788\uC74C", "\uC5C6\uC74C"], ["\uACE0\uC7A5 \uAD50\uCCB4", "\uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB984", "\uBCF4\uC99D \uC870\uAC74\uC5D0 \uB530\uB984"], ["\uADDC\uACA9 \uBCC0\uACBD \uC2DC \uAD50\uCCB4", "\uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB984", "\uB9E4\uC7A5 \uBD80\uB2F4"]] }, "faq": [["\uAD6C\uB9E4\uD55C \uAE30\uAE30\uB97C \uB2E4\uB978 \uB9E4\uC7A5\uC5D0 \uC62E\uACA8 \uC368\uB3C4 \uB418\uB098\uC694?", "\uAE30\uAE30\uB294 \uC62E\uAE38 \uC218 \uC788\uC9C0\uB9CC \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uC8FC\uC18C\uBCC4\uC774\uB77C \uC0C8 \uB9E4\uC7A5 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uC62E\uAE34 \uB4A4 \uCCAB \uACB0\uC81C \uC804\uC5D0 \uAC00\uB9F9\uC810 \uC8FC\uC18C \uBCC0\uACBD\uC774 \uB05D\uB0AC\uB294\uC9C0 \uCE74\uB4DC\uC0AC \uC548\uB0B4\uBB38\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC784\uB300 \uAE30\uAC04\uC774 \uB05D\uB098\uBA74 \uAE30\uAE30\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "\uC57D\uC815\uC11C\uC5D0 \uBC18\uB0A9, \uC5F0\uC7A5, \uC18C\uC720\uAD8C \uC774\uC804 \uC911 \uC5B4\uB290 \uAC83\uC778\uC9C0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4. \uB05D\uB098\uAE30 \uC804\uC5D0 \uC870\uAC74\uC744 \uBCF4\uACE0 \uC758\uC0AC\uB97C \uAE00\uB85C \uB0A8\uAE41\uB2C8\uB2E4. \uC57D\uC815 \uC885\uB8CC \uD1B5\uC9C0\uAC00 \uC624\uC9C0 \uC54A\uB294 \uC5C5\uCCB4\uB3C4 \uC788\uC73C\uBBC0\uB85C \uC885\uB8CC \uB2EC\uC744 \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB461\uB2C8\uB2E4."], ["\uC911\uACE0 \uAE30\uAE30 \uAD6C\uB9E4\uB294 \uAD1C\uCC2E\uB098\uC694?", "\uACB0\uC81C \uADDC\uACA9\uACFC \uBCF4\uC548 \uC778\uC99D\uC774 \uD604\uC7AC \uAE30\uC900\uC5D0 \uB9DE\uB294\uC9C0 \uD655\uC778\uD574\uC57C \uD569\uB2C8\uB2E4. \uB9DE\uC9C0 \uC54A\uC73C\uBA74 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uC548 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC911\uACE0 \uAE30\uAE30\uB294 \uBCF4\uC99D\uC774 \uC5C6\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uACE0\uC7A5 \uB54C \uC218\uB9AC \uBE44\uC6A9\uC774 \uC804\uBD80 \uB9E4\uC7A5 \uBD80\uB2F4\uC774 \uB429\uB2C8\uB2E4."], ["\uC784\uB300 \uAE30\uAE30\uB3C4 \uD3EC\uC2A4\uAE30\uC640 \uC5F0\uB3D9\uB418\uB098\uC694?", "\uAE30\uAE30 \uC885\uB958\uAC00 \uAC19\uC73C\uBA74 \uC5F0\uB3D9 \uC870\uAC74\uC740 \uAC19\uC2B5\uB2C8\uB2E4. \uC811\uC218 \uB54C \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC744 \uC54C\uB824 \uC8FC\uBA74 \uB429\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08", "\uD3EC\uC2A4\uAE30\uC784\uB300"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC218\uC218\uB8CC", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uC218\uC218\uB8CC \uC601\uC138\xB7\uC911\uC18C \uC6B0\uB300", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC218\uC218\uB8CC\uB294 \uC5B4\uB5BB\uAC8C \uC815\uD574\uC9C0\uB098\uC694? \u2014 \uC601\uC138\xB7\uC911\uC18C \uAC00\uB9F9\uC810 \uC6B0\uB300 \uAD6C\uAC04", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC218\uC218\uB8CC\uAC00 \uAE30\uAE30\uAC00 \uC544\uB2C8\uB77C \uAC00\uB9F9\uC810 \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uB294 \uAD6C\uC870\uC640 \uC601\uC138\xB7\uC911\uC18C \uAC00\uB9F9\uC810 \uC6B0\uB300 \uC801\uC6A9 \uBC29\uC2DD, \uAD6C\uAC04\uC774 \uB2E4\uC2DC \uC815\uD574\uC9C0\uB294 \uC2DC\uAE30, \uC815\uC0B0\uC11C\uC5D0\uC11C \uB9E4\uB2EC \uD655\uC778\uD560 \uC138 \uC904, \uB9E4\uC7A5\uC774 \uBC14\uAFC0 \uC218 \uC788\uB294 \uBD80\uBD84\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uCE74\uB4DC \uC218\uC218\uB8CC\uB294 \uB2E8\uB9D0\uAE30 \uD68C\uC0AC\uAC00 \uC544\uB2C8\uB77C \uAC00\uB9F9\uC810\uC758 \uC5F0\uB9E4\uCD9C \uAD6C\uAC04\uC5D0 \uB530\uB77C \uC815\uD574\uC9C0\uBA70, \uC601\uC138\xB7\uC911\uC18C \uAC00\uB9F9\uC810\uC740 \uC6B0\uB300\uC218\uC218\uB8CC\uC728 \uAD6C\uAC04\uC5D0 \uB4E4\uC5B4\uAC11\uB2C8\uB2E4. \uAD6C\uAC04 \uAE30\uC900\uACFC \uBE44\uC728\uC740 \uAE08\uC735\uB2F9\uAD6D\uC774 \uC815\uAE30\uC801\uC73C\uB85C \uACE0\uC2DC\uD558\uBBC0\uB85C \uD604\uC7AC \uAC12\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uACE0, \uB9E4\uC7A5\uC740 \uC815\uC0B0\uC11C \uC138 \uC904\uB85C \uC801\uC6A9 \uC5EC\uBD80\uB97C \uC9C0\uCF1C\uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uC218\uC218\uB8CC\uB294 \uB204\uAC00 \uC815\uD558\uB098\uC694?", "p": ["\uCE74\uB4DC\uC0AC\uAC00 \uAC00\uB9F9\uC810\uB9C8\uB2E4 \uB9E4\uCD9C \uAD6C\uAC04\uC744 \uC815\uD558\uACE0 \uADF8 \uAD6C\uAC04\uC758 \uBE44\uC728\uC744 \uC801\uC6A9\uD569\uB2C8\uB2E4. \uC124\uCE58\uC5C5\uCCB4\uB098 \uB2E8\uB9D0\uAE30 \uBAA8\uB378\uC740 \uC774 \uBE44\uC728\uC744 \uBC14\uAFB8\uC9C0 \uBABB\uD569\uB2C8\uB2E4.", "\uC601\uC138\xB7\uC911\uC18C \uAC00\uB9F9\uC810 \uAD6C\uAC04\uC740 \uC5F0\uB9E4\uCD9C\uC744 \uAE30\uC900\uC73C\uB85C \uB098\uB258\uACE0, \uAD6D\uC138\uCCAD \uB9E4\uCD9C \uC790\uB8CC\uB97C \uBC14\uD0D5\uC73C\uB85C \uBC18\uAE30\uB9C8\uB2E4 \uB2E4\uC2DC \uC815\uD574\uC9D1\uB2C8\uB2E4.", "\uC0C8\uB85C \uAC1C\uC5C5\uD55C \uB9E4\uC7A5\uC740 \uB9E4\uCD9C \uC790\uB8CC\uAC00 \uC5C6\uC5B4 \uCC98\uC74C\uC5D0\uB294 \uC77C\uBC18 \uAD6C\uAC04\uC73C\uB85C \uC2DC\uC791\uD588\uB2E4\uAC00 \uB2E4\uC74C \uC0B0\uC815 \uB54C \uBC14\uB014 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAD6C\uAC04\uC774 \uBC14\uB00C\uBA74 \uCE74\uB4DC\uC0AC\uAC00 \uAC00\uB9F9\uC810\uC5D0 \uD1B5\uC9C0\uD558\uBBC0\uB85C \uADF8 \uC548\uB0B4\uBB38\uC744 \uBCF4\uAD00\uD574 \uB450\uBA74 \uB4A4\uC5D0 \uBE44\uC728\uC744 \uB530\uC9C8 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uC5EC\uB7EC \uCE74\uB4DC\uC0AC\uC5D0 \uAC00\uB9F9\uB3FC \uC788\uC5B4\uB3C4 \uAD6C\uAC04 \uAE30\uC900\uC740 \uAC19\uC740 \uB9E4\uCD9C \uC790\uB8CC\uB85C \uC815\uD574\uC9C0\uBBC0\uB85C \uCE74\uB4DC\uC0AC\uBCC4\uB85C \uD06C\uAC8C \uB2E4\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC6B0\uB300 \uAD6C\uAC04\uC758 \uAE30\uC900 \uAE08\uC561\uACFC \uBE44\uC728\uC740 \uBC95\uC5D0 \uADFC\uAC70\uD574 \uACE0\uC2DC\uB418\uBA70, \uACE0\uC2DC\uAC00 \uBC14\uB00C\uBA74 \uD1B5\uC9C0 \uC5C6\uC774\uB3C4 \uB2E4\uC74C \uC0B0\uC815\uC5D0 \uBC18\uC601\uB429\uB2C8\uB2E4.", "\uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uC5D0\uB294 \uC801\uC6A9 \uC2DC\uC791\uC77C\uC774 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uADF8 \uB0A0\uC9DC \uC804\uD6C4 \uC815\uC0B0\uC11C\uB97C \uBE44\uAD50\uD558\uBA74 \uC801\uC6A9 \uC5EC\uBD80\uAC00 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4."] }, { "h": "\uC6B0\uB300 \uAD6C\uAC04\uC5D0 \uB4E4\uC5B4\uAC00\uBA74 \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uAC19\uC740 \uACB0\uC81C\uB77C\uB3C4 \uACF5\uC81C\uB418\uB294 \uBE44\uC728\uC774 \uB0AE\uC544\uC838 \uC785\uAE08\uC561\uC774 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uCCB4\uD06C\uCE74\uB4DC\uC640 \uC2E0\uC6A9\uCE74\uB4DC \uBE44\uC728\uC774 \uB530\uB85C \uC788\uC73C\uBBC0\uB85C \uC190\uB2D8 \uAD6C\uC131\uC5D0 \uB530\uB77C \uCCB4\uAC10\uC774 \uB2E4\uB985\uB2C8\uB2E4.", "\uC6B0\uB300 \uC801\uC6A9\uC740 \uC790\uB3D9\uC73C\uB85C \uB418\uC9C0\uB9CC, \uB9E4\uCD9C\uC774 \uC904\uC5C8\uB294\uB370 \uAD6C\uAC04\uC774 \uADF8\uB300\uB85C\uB77C\uBA74 \uCE74\uB4DC\uC0AC\uC5D0 \uC7AC\uC0B0\uC815\uC744 \uBB3C\uC5B4\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAD6C\uAC04 \uAE30\uC900 \uAE08\uC561\uACFC \uBE44\uC728\uC740 \uACE0\uC2DC\uAC00 \uBC14\uB014 \uB54C\uB9C8\uB2E4 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uACFC\uAC70 \uC790\uB8CC\uB97C \uADF8\uB300\uB85C \uBBFF\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uAC1C\uC5C5 \uCCAB \uD574\uB77C\uBA74 \uB2E4\uC74C \uBC18\uAE30 \uC0B0\uC815 \uB54C \uAD6C\uAC04\uC774 \uB0B4\uB824\uAC08 \uC218 \uC788\uC73C\uB2C8 \uD1B5\uC9C0\uBB38\uC744 \uAE30\uB2E4\uB824 \uBCF4\uACE0, \uC624\uC9C0 \uC54A\uC73C\uBA74 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC13C\uD130\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC6B0\uB300 \uAD6C\uAC04\uC774\uB77C\uB3C4 \uBE44\uB300\uBA74 \uACB0\uC81C\uB098 \uD2B9\uC815 \uC81C\uD734\uCE74\uB4DC\uB294 \uBE44\uC728\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4 \uC815\uC0B0\uC11C\uC5D0\uC11C \uACB0\uC81C \uC885\uB958\uBCC4\uB85C \uB098\uB220 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC815\uC0B0\uC11C\uC5D0\uC11C\uB294 \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uC2B9\uC778 \uCD1D\uC561, \uACF5\uC81C \uCD1D\uC561, \uC785\uAE08\uC561 \uC138 \uC904\uC744 \uB9E4\uB2EC \uC801\uC5B4 \uB450\uBA74 \uBE44\uC728 \uBCC0\uD654\uAC00 \uBCF4\uC785\uB2C8\uB2E4.", "\uACF5\uC81C \uD56D\uBAA9\uC5D0 \uC218\uC218\uB8CC \uC678\uC5D0 \uB2E4\uB978 \uBA85\uBAA9\uC774 \uC11E\uC5EC \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4. \uBC34 \uC218\uC218\uB8CC\uB098 \uBD80\uAC00 \uC11C\uBE44\uC2A4 \uC694\uAE08\uC774 \uB530\uB85C \uBD99\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uBE44\uB300\uBA74 \uACB0\uC81C\uC640 \uB300\uBA74 \uACB0\uC81C\uB294 \uCC98\uB9AC \uACBD\uB85C\uAC00 \uB2EC\uB77C \uBE44\uC728\uC774 \uAC19\uC9C0 \uC54A\uC73C\uBBC0\uB85C \uB458\uC744 \uB098\uB220 \uBD05\uB2C8\uB2E4.", "\uC815\uC0B0 \uC8FC\uAE30\uAC00 \uCE74\uB4DC\uC0AC\uB9C8\uB2E4 \uB2EC\uB77C \uC785\uAE08\uC77C\uC774 \uD769\uC5B4\uC9C0\uBBC0\uB85C \uC6D4 \uB2E8\uC704\uB85C \uD569\uCCD0\uC11C \uBD10\uC57C \uBE44\uC728\uC774 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uC218\uC218\uB8CC \uAD6C\uAC04\uBCC4 \uC790\uC138\uD55C \uD750\uB984\uC740 \uAE30\uC874 \uAE00 '\uCE74\uB4DC \uC218\uC218\uB8CC\uB294 \uC5B4\uB514\uC11C \uAC08\uB9AC\uB098'\uC5D0\uC11C \uC774\uC5B4\uC9D1\uB2C8\uB2E4.", "\uC138\uBB34 \uC2E0\uACE0 \uB54C\uB294 \uACF5\uC81C \uC804 \uC2B9\uC778 \uCD1D\uC561\uC774 \uB9E4\uCD9C\uC774\uBBC0\uB85C \uC785\uAE08\uC561\uB9CC \uC801\uC5B4 \uB450\uBA74 \uB9E4\uCD9C\uC774 \uC791\uAC8C \uC7A1\uD788\uB294 \uC2E4\uC218\uAC00 \uC0DD\uAE41\uB2C8\uB2E4."] }, { "h": "\uB9E4\uC7A5\uC774 \uBC14\uAFC0 \uC218 \uC788\uB294 \uBD80\uBD84\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uAD6C\uAC04\uC740 \uB9E4\uCD9C\uB85C \uC815\uD574\uC9C0\uB2C8 \uB2F9\uC7A5 \uBC14\uAFB8\uAE30 \uC5B4\uB835\uC9C0\uB9CC, \uC5B4\uB5A4 \uACB0\uC81C\uB97C \uC5B4\uB290 \uACBD\uB85C\uB85C \uBC1B\uC744\uC9C0\uB294 \uB9E4\uC7A5\uC774 \uC815\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uB300\uBA74 \uACB0\uC81C\uB85C \uBC1B\uC744 \uC218 \uC788\uB294 \uC8FC\uBB38\uC744 \uAD73\uC774 \uB9C1\uD06C \uACB0\uC81C\uB85C \uBC1B\uC73C\uBA74 \uCC98\uB9AC \uACBD\uB85C\uAC00 \uB2EC\uB77C\uC838 \uBE44\uC728\uC774 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBD80\uAC00 \uC11C\uBE44\uC2A4 \uC694\uAE08\uC740 \uACC4\uC57D \uB54C \uB123\uACE0 \uBE84 \uC218 \uC788\uB294 \uD56D\uBAA9\uC774\uBBC0\uB85C \uC4F0\uC9C0 \uC54A\uB294 \uC11C\uBE44\uC2A4\uB294 \uBE7C \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C \uC138 \uC904\uC744 \uAFB8\uC900\uD788 \uC801\uC5B4 \uB450\uBA74 \uC7AC\uC0B0\uC815 \uBB38\uC758 \uB54C \uADFC\uAC70\uAC00 \uB418\uACE0, \uC5C5\uCCB4\uB97C \uBC14\uAFC0 \uB54C\uB3C4 \uBE44\uAD50 \uAE30\uC900\uC774 \uB429\uB2C8\uB2E4.", "\uD604\uAE08\uC601\uC218\uC99D \uB9E4\uCD9C\uC740 \uCE74\uB4DC \uC218\uC218\uB8CC\uC640 \uBB34\uAD00\uD558\uBBC0\uB85C \uB450 \uB9E4\uCD9C\uC744 \uC11E\uC5B4 \uBE44\uC728\uC744 \uACC4\uC0B0\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C\uB294 \uC885\uC774\uB85C \uC624\uB4E0 \uD654\uBA74\uC73C\uB85C \uBCF4\uB4E0 \uB9E4\uB2EC \uAC19\uC740 \uB0A0 \uD655\uC778\uD558\uB294 \uC2B5\uAD00\uC744 \uB4E4\uC774\uBA74 \uBE44\uC728 \uBCC0\uD654\uB97C \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uACFC \uC815\uC0B0\uC11C\uB97C \uAC19\uC740 \uD3F4\uB354\uC5D0 \uB450\uBA74 \uBC18\uAE30\uB9C8\uB2E4 \uBE44\uC728\uC774 \uC5B4\uB5BB\uAC8C \uBC14\uB00C\uC5C8\uB294\uC9C0 \uD55C\uB208\uC5D0 \uBCF4\uC785\uB2C8\uB2E4.", "\uBE44\uB300\uBA74 \uACB0\uC81C \uBE44\uC911\uC774 \uD070 \uB9E4\uC7A5\uC740 \uADF8 \uACBD\uB85C\uC758 \uBE44\uC728\uC744 \uB530\uB85C \uC801\uC5B4 \uB450\uC5B4\uC57C \uC804\uCCB4 \uBE44\uC728 \uBCC0\uD654\uB97C \uC124\uBA85\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uB0B4 \uB9E4\uC7A5 \uAD6C\uAC04\uC744 \uD655\uC778\uD558\uB294 \uC21C\uC11C\uB294\uC694?", "items": ["\uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC548\uB0B4\uBB38\uC774\uB098 \uAC00\uB9F9\uC810 \uC870\uD68C \uD654\uBA74\uC5D0\uC11C \uD604\uC7AC \uAD6C\uAC04\uC744 \uBD05\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C \uC138 \uC904\uC744 \uC801\uC5B4 \uC6D4\uBCC4 \uBE44\uC728\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uB9E4\uCD9C\uC774 \uAD6C\uAC04 \uAE30\uC900\uACFC \uB9DE\uC9C0 \uC54A\uC73C\uBA74 \uCE74\uB4DC\uC0AC\uC5D0 \uC7AC\uC0B0\uC815\uC744 \uBB38\uC758\uD569\uB2C8\uB2E4.", "\uACB0\uACFC\uB97C \uB2E4\uC74C \uC815\uC0B0\uC11C\uC5D0\uC11C \uB2E4\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC7AC\uC0B0\uC815 \uACB0\uACFC \uD1B5\uC9C0\uBB38\uC744 \uBCF4\uAD00\uD558\uACE0 \uC815\uC0B0\uC11C \uBE44\uC728\uACFC \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC218\uC218\uB8CC\uB97C \uC815\uD558\uB294 \uC694\uC18C", "head": ["\uC694\uC18C", "\uC815\uD558\uB294 \uACF3", "\uB9E4\uC7A5\uC774 \uBC14\uAFC0 \uC218 \uC788\uB294\uAC00"], "rows": [["\uB9E4\uCD9C \uAD6C\uAC04", "\uCE74\uB4DC\uC0AC(\uAD6D\uC138\uCCAD \uC790\uB8CC)", "\uC9C1\uC811\uC740 \uC5B4\uB824\uC6C0"], ["\uCE74\uB4DC \uC885\uB958", "\uC190\uB2D8 \uC120\uD0DD", "\uC5B4\uB824\uC6C0"], ["\uACB0\uC81C \uBC29\uC2DD(\uB300\uBA74\xB7\uBE44\uB300\uBA74)", "\uB9E4\uC7A5 \uC6B4\uC601", "\uAC00\uB2A5"], ["\uBD80\uAC00 \uC11C\uBE44\uC2A4 \uC694\uAE08", "\uACC4\uC57D \uC870\uAC74", "\uACC4\uC57D \uB54C \uC870\uC815"]] }, "faq": [["\uB2E8\uB9D0\uAE30\uB97C \uBC14\uAFB8\uBA74 \uC218\uC218\uB8CC\uAC00 \uB0B4\uB824\uAC00\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uC218\uC218\uB8CC\uB294 \uAC00\uB9F9\uC810 \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uACE0 \uAE30\uAE30\uC640 \uBB34\uAD00\uD569\uB2C8\uB2E4. \uAE30\uAE30\uB97C \uBC14\uAFB8\uC790\uB294 \uC81C\uC548\uC774 \uC218\uC218\uB8CC\uB97C \uC774\uC720\uB85C \uB4E4\uC5B4\uC624\uBA74 \uAC00\uB9F9\uC810 \uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4."], ["\uC6B0\uB300 \uAD6C\uAC04 \uC801\uC6A9 \uC5EC\uBD80\uB294 \uC5B4\uB514\uC11C \uBCF4\uB098\uC694?", "\uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC548\uB0B4\uBB38\uC774\uB098 \uC5EC\uC2E0\uAE08\uC735\uD611\uD68C \uC870\uD68C \uC11C\uBE44\uC2A4\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD1B5\uC9C0\uBB38\uC774 \uC5C6\uC73C\uBA74 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC13C\uD130\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uAD6C\uAC04 \uAE30\uC900 \uAE08\uC561\uC774 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uACE0\uC2DC\uC5D0 \uB530\uB77C \uBC14\uB00C\uBBC0\uB85C \uD604\uC7AC \uAE30\uC900\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uAD6C\uAC04 \uC0B0\uC815 \uC2DC\uAE30(\uBC18\uAE30)\uB294 \uC815\uD574\uC838 \uC788\uC73C\uBBC0\uB85C \uB2E4\uC74C \uC0B0\uC815 \uB2EC\uC744 \uC801\uC5B4 \uB450\uACE0 \uD1B5\uC9C0\uBB38\uC744 \uAE30\uB2E4\uB9BD\uB2C8\uB2E4."], ["\uAC04\uC774\uACFC\uC138\uC790\uB3C4 \uC6B0\uB300\uAC00 \uB418\uB098\uC694?", "\uC6B0\uB300\uB294 \uACFC\uC138 \uC720\uD615\uC774 \uC544\uB2C8\uB77C \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uBBC0\uB85C \uB9E4\uCD9C\uC774 \uAE30\uC900 \uC548\uC774\uBA74 \uC801\uC6A9\uB429\uB2C8\uB2E4. \uC601\uC138\xB7\uC911\uC18C \uAD6C\uAC04\uC740 \uB9E4\uCD9C \uAE30\uC900\uC774\uBBC0\uB85C \uAC04\uC774\uACFC\uC138\uC790\uC640 \uC77C\uBC18\uACFC\uC138\uC790 \uBAA8\uB450 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uB429\uB2C8\uB2E4."]], "related": ["\uAC04\uC774\uACFC\uC138\uC790\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uAC04\uC774\uACFC\uC138\uC790\uC218\uC218\uB8CC"], "posts": ["/post/fee-tiers/"], "sources": ["\uC5EC\uC2E0\uC804\uBB38\uAE08\uC735\uC5C5\uBC95 \uC81C18\uC870\uC7583(\uC6B0\uB300\uC218\uC218\uB8CC\uC728)"], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uD574\uC9C0\xB7\uC704\uC57D\uAE08", "title": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uD574\uC9C0\uD558\uBA74 \uC704\uC57D\uAE08\uC774 \uC788\uB098\uC694? \u2014 \uC57D\uC815\uC11C\uC5D0\uC11C \uCC3E\uC744 \uC870\uD56D", "desc": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uD574\uC9C0 \uB54C \uC704\uC57D\uAE08\uC774 \uC0DD\uAE30\uB294 \uC870\uAC74\uACFC \uC57D\uC815\uC11C\uC5D0\uC11C \uD655\uC778\uD560 \uC870\uD56D, \uAC00\uB9F9\uC810 \uD574\uC9C0\uC640 \uAE30\uAE30 \uC57D\uC815 \uD574\uC9C0\uC758 \uCC28\uC774, \uBC18\uB0A9 \uC808\uCC28\uC640 \uBBF8\uC815\uC0B0 \uB9E4\uCD9C \uCC98\uB9AC, \uD3D0\uC5C5\uACFC \uC5C5\uCCB4 \uBCC0\uACBD\uC5D0\uC11C \uB2EC\uB77C\uC9C0\uB294 \uC810, \uD574\uC9C0 \uB4A4 \uBCF4\uAD00\uD560 \uC11C\uB958\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC704\uC57D\uAE08\uC740 \uC784\uB300\xB7\uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC544 \uC788\uC744 \uB54C\uB9CC \uC0DD\uAE30\uACE0, \uAE08\uC561\uACFC \uC0B0\uC815 \uBC29\uC2DD\uC740 \uC57D\uC815\uC11C\uC758 \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uC5D0 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uBA3C\uC800 \uCC3E\uC544 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uAD6C\uB9E4\uD55C \uAE30\uAE30\uB294 \uC704\uC57D\uAE08\uC774 \uC5C6\uACE0, \uD574\uC9C0\uB294 \uAC00\uB9F9\uC810 \uD574\uC9C0\uC640 \uAE30\uAE30 \uC57D\uC815 \uD574\uC9C0 \uB450 \uAC00\uC9C0\uB97C \uB530\uB85C \uD574\uC57C \uBE44\uC6A9\uC774 \uBA48\uCDA5\uB2C8\uB2E4.", "sections": [{ "h": "\uC704\uC57D\uAE08\uC740 \uC5B8\uC81C \uC0DD\uAE30\uB098\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04 \uC548\uC5D0 \uD574\uC9C0\uD560 \uB54C \uB0A8\uC740 \uAE30\uAC04\uC5D0 \uB300\uD55C \uC870\uAC74\uC73C\uB85C \uC0DD\uAE41\uB2C8\uB2E4. \uAE30\uAC04\uC774 \uB05D\uB09C \uB4A4 \uD574\uC9C0\uB294 \uD574\uB2F9\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC740\uD488\uC774\uB098 \uC124\uCE58\uBE44 \uC9C0\uC6D0\uC744 \uBC1B\uC740 \uC870\uAC74\uC774 \uC788\uC73C\uBA74 \uADF8 \uAE08\uC561\uC744 \uB3CC\uB824\uC8FC\uB294 \uC870\uD56D\uC774 \uB530\uB85C \uC788\uC744 \uC218 \uC788\uC5B4 \uC57D\uC815\uC11C \uB4B7\uC7A5\uAE4C\uC9C0 \uC77D\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uC9C0 \uC54A\uAC70\uB098 \uD30C\uC190\uB41C \uCC44 \uBC18\uB0A9\uD558\uBA74 \uAE30\uAE30\uAC12 \uC870\uD56D\uC774 \uBD99\uC73C\uBBC0\uB85C \uBC18\uB0A9 \uC804\uC5D0 \uC0C1\uD0DC\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uAE41\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uC0B0\uC815 \uBC29\uC2DD\uC774 \uC5C6\uB294\uB370 \uC704\uC57D\uAE08\uC744 \uC694\uAD6C\uBC1B\uC73C\uBA74 \uC870\uD56D\uC744 \uBCF4\uC5EC \uB2EC\uB77C\uACE0 \uC694\uCCAD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5 \uC870\uD56D\uC774 \uC788\uB294 \uC57D\uC815\uC740 \uB05D\uB098\uAE30 \uC804\uC5D0 \uD574\uC9C0 \uC758\uC0AC\uB97C \uAE00\uB85C \uB0A8\uACA8\uC57C \uC5F0\uC7A5\uC774 \uC548 \uB429\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uD68C\uC120 \uC57D\uC815\uC774 \uAE30\uAE30 \uC57D\uC815\uACFC \uBCC4\uB3C4\uB85C \uC788\uC73C\uBA74 \uD68C\uC120 \uCABD \uC704\uC57D \uC870\uAC74\uB3C4 \uB530\uB85C \uBD05\uB2C8\uB2E4.", "\uC704\uC57D \uC870\uD56D\uC740 \uC57D\uC815\uC11C \uBCF8\uBB38\uBCF4\uB2E4 \uBCC4\uC9C0\uB098 \uB4B7\uBA74\uC5D0 \uC791\uAC8C \uC801\uD78C \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uC11C\uBA85 \uC804\uC5D0 \uBC1B\uC740 \uC11C\uB958 \uC804\uCCB4\uB97C \uB118\uACA8 \uBD05\uB2C8\uB2E4."] }, { "h": "\uAC00\uB9F9\uC810 \uD574\uC9C0\uC640 \uAE30\uAE30 \uD574\uC9C0\uB294 \uAC19\uC740 \uAC74\uAC00\uC694?", "p": ["\uB2E4\uB985\uB2C8\uB2E4. \uAC00\uB9F9\uC810 \uD574\uC9C0\uB294 \uCE74\uB4DC\uC0AC\uC640\uC758 \uACB0\uC81C \uACC4\uC57D\uC744 \uB05D\uB0B4\uB294 \uAC83\uC774\uACE0, \uAE30\uAE30 \uD574\uC9C0\uB294 \uC124\uCE58\uC5C5\uCCB4\xB7\uBC34\uC0AC\uC640\uC758 \uC57D\uC815\uC744 \uB05D\uB0B4\uB294 \uAC83\uC785\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774\uBA74 \uB458 \uB2E4 \uD574\uC57C \uC6D4 \uC774\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uB8CC\uAC00 \uBA48\uCD94\uACE0, \uD558\uB098\uB9CC \uD558\uBA74 \uBE44\uC6A9\uC774 \uACC4\uC18D \uB098\uAC11\uB2C8\uB2E4.", "\uC5C5\uCCB4\uB9CC \uBC14\uAFB8\uB294 \uACBD\uC6B0\uB77C\uBA74 \uAC00\uB9F9\uC810\uC740 \uADF8\uB300\uB85C \uB450\uACE0 \uAE30\uAE30 \uC57D\uC815\uB9CC \uC815\uB9AC\uD558\uB294 \uBC29\uBC95\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC740 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC544 \uB450\uC5B4\uC57C \uB098\uC911\uC5D0 \uCCAD\uAD6C\uAC00 \uACC4\uC18D\uB420 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uBC34\uC0AC\uAC00 \uBC14\uB00C\uB294 \uC5C5\uCCB4 \uBCC0\uACBD\uC774\uBA74 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uB3C4 \uC0C8 \uBC34\uC0AC\uB85C \uC62E\uACA8\uC57C \uD558\uBBC0\uB85C \uACB0\uC81C\uAC00 \uB04A\uAE30\uB294 \uB0A0\uC774 \uC5C6\uB3C4\uB85D \uB0A0\uC9DC\uB97C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uD604\uAE08\uC601\uC218\uC99D \uAC00\uB9F9\uC810\uC740 \uBCC4\uB3C4\uC774\uBBC0\uB85C \uD3D0\uC5C5\uC774\uBA74 \uC138\uBB34 \uB300\uB9AC\uC778\uACFC \uAC19\uC774 \uC815\uB9AC\uD560\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uBBF8\uC815\uC0B0 \uB9E4\uCD9C\uC774 \uB0A8\uC544 \uC788\uB294\uC9C0 \uC815\uC0B0\uC11C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4. \uD574\uC9C0\uD574\uB3C4 \uBBF8\uC815\uC0B0\uBD84\uC740 \uC9C0\uAE09\uB418\uC9C0\uB9CC \uCC3D\uAD6C\uAC00 \uBC14\uB00C\uBA74 \uBB3B\uAE30 \uC5B4\uB824\uC6CC\uC9D1\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uD68C\uC120\uC774 \uBCC4\uB3C4 \uC57D\uC815\uC774\uBA74 \uD68C\uC120 \uD574\uC9C0\uB97C \uB530\uB85C \uD574\uC57C \uC694\uAE08\uC774 \uBA48\uCDA5\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB294 \uBC18\uB0A9 \uBC29\uBC95\uACFC \uAE30\uD55C\uC744 \uBC1B\uC544 \uB450\uACE0, \uBC18\uB0A9 \uD655\uC778\uC99D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC0AC\uC720\uAC00 \uD3D0\uC5C5\uC774\uBA74 \uC138\uBB34\uC11C \uD3D0\uC5C5 \uC2E0\uACE0\uC640 \uC21C\uC11C\uB97C \uB9DE\uCDB0 \uC9C4\uD589\uD569\uB2C8\uB2E4.", "\uC815\uC0B0\uBC1B\uB358 \uD1B5\uC7A5\uC740 \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uC774 \uB4E4\uC5B4\uC62C \uB54C\uAE4C\uC9C0 \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\uC9C1\uC6D0\uC774 \uC4F0\uB358 \uAE30\uAE30 \uBE44\uBC00\uBC88\uD638\uB098 \uC124\uC815\uC740 \uBC18\uB0A9 \uC804\uC5D0 \uCD08\uAE30\uD654\uD574 \uB9E4\uC7A5 \uC815\uBCF4\uAC00 \uB0A8\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD \uB4A4 \uCC98\uB9AC\uAE4C\uC9C0 \uAC78\uB9AC\uB294 \uAE30\uAC04\uC774 \uC788\uC73C\uBBC0\uB85C \uADF8 \uAE30\uAC04\uC758 \uC774\uC6A9\uB8CC\uAC00 \uCCAD\uAD6C\uB418\uB294\uC9C0\uB3C4 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC11C\uC5D0 \uBC18\uB0A9 \uC608\uC815\uC77C\uACFC \uBBF8\uC815\uC0B0 \uB9E4\uCD9C \uCC98\uB9AC \uBC29\uC2DD\uC744 \uD568\uAED8 \uC801\uC5B4 \uB450\uBA74 \uB4A4\uC5D0 \uD655\uC778\uD560 \uD56D\uBAA9\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uB4A4\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB0A8\uB098\uC694?", "p": ["\uD574\uC9C0 \uC2DC\uC810\uAE4C\uC9C0\uC758 \uB9E4\uCD9C\uC740 \uC815\uC0B0 \uC8FC\uAE30\uB300\uB85C \uB4E4\uC5B4\uC624\uBBC0\uB85C \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uC11C\uB97C \uBC1B\uC744 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9BD\uB2C8\uB2E4.", "\uC57D\uC815 \uD574\uC9C0 \uD655\uC778\uC11C\uC640 \uBC18\uB0A9 \uD655\uC778\uC99D\uC740 \uBD84\uC7C1\uC774 \uC0DD\uACBC\uC744 \uB54C \uADFC\uAC70\uAC00 \uB418\uBBC0\uB85C \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uB2E4\uC2DC \uC124\uCE58\uD558\uBA74 \uC0C8 \uC57D\uC815\uC73C\uB85C \uC2DC\uC791\uD558\uACE0, \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB97C \uC4F8 \uC218 \uC788\uB294\uC9C0\uB294 \uCE74\uB4DC\uC0AC \uB4F1\uB85D \uC0C1\uD0DC\uC5D0 \uB530\uB985\uB2C8\uB2E4.", "\uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uD574\uC9C0 \uB4A4\uC5D0\uB3C4 \uBE60\uC838\uB098\uAC00\uBA74 \uC811\uC218 \uBC88\uD638\uB97C \uB4E4\uACE0 \uBC14\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4\uC5D0 \uC624\uB294 \uC815\uC0B0\uC11C\uB294 \uC138\uBB34 \uC790\uB8CC\uC774\uBBC0\uB85C \uD3D0\uC5C5 \uC2E0\uACE0 \uC11C\uB958\uC640 \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD574\uC9C0\uD55C \uB2EC\uC758 \uD1B5\uC2E0\uB8CC\uC640 \uC774\uC6A9\uB8CC\uAC00 \uC77C\uD560\uB85C \uC815\uC0B0\uB418\uB294\uC9C0, \uC6D4 \uB2E8\uC704\uB85C \uCCAD\uAD6C\uB418\uB294\uC9C0\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uCC98\uB9AC \uC644\uB8CC \uD1B5\uC9C0\uB97C \uBC1B\uC73C\uBA74 \uB0A0\uC9DC\uB97C \uC801\uC5B4 \uB450\uACE0, \uB2E4\uC74C \uB2EC \uD1B5\uC7A5\uC5D0\uC11C \uC790\uB3D9\uC774\uCCB4\uAC00 \uBA48\uCDC4\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uD574\uC9C0 \uCC98\uB9AC \uC644\uB8CC \uD1B5\uC9C0\uB97C \uBC1B\uC73C\uBA74 \uB0A0\uC9DC\uB97C \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uD574\uC9C0 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uC57D\uC815\uC11C\uC5D0\uC11C \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uACFC \uBC18\uB0A9 \uC870\uAC74\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uBBF8\uC815\uC0B0 \uB9E4\uCD9C\uC744 \uD655\uC778\uD558\uACE0 \uD574\uC9C0 \uC2E0\uCCAD\uC744 \uAE00\uB85C \uC811\uC218\uD569\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uACE0 \uD655\uC778\uC99D\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uD68C\uC120\uACFC \uAC00\uB9F9\uC810 \uD574\uC9C0\uB97C \uAC01\uAC01 \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uD655\uC778\uC11C\uC640 \uBC18\uB0A9 \uD655\uC778\uC99D, \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uC11C\uB97C \uD55C\uACF3\uC5D0 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD574\uC9C0 \uC0C1\uD669\uBCC4 \uD655\uC778 \uD56D\uBAA9", "head": ["\uC0C1\uD669", "\uC704\uC57D\uAE08", "\uBC18\uB0A9"], "rows": [["\uC57D\uC815 \uAE30\uAC04 \uC911 \uD574\uC9C0", "\uC57D\uC815\uC11C \uC870\uD56D \uD655\uC778", "\uD544\uC694"], ["\uC57D\uC815 \uAE30\uAC04 \uC885\uB8CC \uB4A4", "\uC5C6\uC74C", "\uC57D\uC815\uC11C \uC870\uAC74\uC5D0 \uB530\uB984"], ["\uAD6C\uB9E4 \uAE30\uAE30", "\uC5C6\uC74C", "\uBD88\uD544\uC694"], ["\uC5C5\uCCB4 \uBCC0\uACBD", "\uAE30\uAE30 \uC57D\uC815\uB9CC \uD655\uC778", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"]] }, "faq": [["\uC704\uC57D\uAE08 \uAE08\uC561\uC740 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uB418\uB098\uC694?", "\uC57D\uC815\uC11C\uC758 \uC0B0\uC815 \uBC29\uC2DD\uC5D0 \uB530\uB974\uBA70 \uB0A8\uC740 \uAC1C\uC6D4 \uC218\uC5D0 \uBE44\uB840\uD558\uB294 \uBC29\uC2DD\uC774 \uD754\uD569\uB2C8\uB2E4. \uC815\uD655\uD55C \uAC12\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uB0A8\uC740 \uAC1C\uC6D4 \uC218 \uC678\uC5D0 \uC0AC\uC740\uD488 \uBC18\uD658 \uC870\uD56D\uC774 \uB530\uB85C \uC788\uC73C\uBA74 \uB450 \uAE08\uC561\uC774 \uD569\uC0B0\uB429\uB2C8\uB2E4."], ["\uD574\uC9C0\uD558\uBA74 \uC218\uC218\uB8CC \uC815\uC0B0\uB3C4 \uB04A\uAE30\uB098\uC694?", "\uD574\uC9C0 \uC2DC\uC810\uAE4C\uC9C0\uC758 \uB9E4\uCD9C\uC740 \uC815\uC0B0 \uC8FC\uAE30\uB300\uB85C \uB4E4\uC5B4\uC635\uB2C8\uB2E4. \uD1B5\uC7A5\uC740 \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uAE4C\uC9C0 \uC720\uC9C0\uD569\uB2C8\uB2E4. \uD574\uC9C0 \uB4A4 \uC815\uC0B0\uC11C\uAC00 \uC624\uC9C0 \uC54A\uC73C\uBA74 \uBC34\uC0AC \uC815\uC0B0 \uCC3D\uAD6C\uC5D0 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4."], ["\uAE30\uAE30\uB97C \uC783\uC5B4\uBC84\uB838\uC73C\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uC784\uB300 \uAE30\uAE30\uB294 \uBD84\uC2E4 \uC870\uD56D\uC5D0 \uB530\uB77C \uAE30\uAE30\uAC12\uC774 \uCCAD\uAD6C\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBC14\uB85C \uC5C5\uCCB4\uC5D0 \uC54C\uB824 \uAE30\uAE30\uB97C \uC815\uC9C0\uC2DC\uD0B5\uB2C8\uB2E4. \uC815\uC9C0\uC2DC\uD0A4\uC9C0 \uC54A\uC73C\uBA74 \uBD84\uC2E4 \uAE30\uAE30\uB85C \uACB0\uC81C\uAC00 \uC2DC\uB3C4\uB420 \uC218 \uC788\uC73C\uBBC0\uB85C \uC2E0\uACE0\uAC00 \uBA3C\uC800\uC785\uB2C8\uB2E4."], ["\uD574\uC9C0 \uB4A4 \uB2E4\uC2DC \uC124\uCE58\uD558\uBA74 \uC0C8 \uC57D\uC815\uC778\uAC00\uC694?", "\uC0C8 \uC57D\uC815\uC73C\uB85C \uC2DC\uC791\uD569\uB2C8\uB2E4. \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB97C \uC4F8 \uC218 \uC788\uB294\uC9C0\uB294 \uCE74\uB4DC\uC0AC \uB4F1\uB85D \uC0C1\uD0DC\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uC7AC\uC124\uCE58 \uB54C \uAE30\uC874 \uC815\uC0B0 \uD1B5\uC7A5\uACFC \uC11C\uB958\uB97C \uADF8\uB300\uB85C \uC4F0\uBA74 \uC2EC\uC0AC\uAC00 \uBE68\uB77C\uC9D1\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uD3EC\uC2A4\uAE30\uD574\uC9C0\uBC18\uB0A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uAC04\uC774\uACFC\uC138\uC790\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uAC04\uC774\uACFC\uC138\uC790", "title": "\uAC04\uC774\uACFC\uC138\uC790\uB3C4 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uC124\uCE58\uD560 \uC218 \uC788\uB098\uC694? \u2014 \uC11C\uB958\uC640 \uC218\uC218\uB8CC \uC801\uC6A9 \uBC29\uC2DD", "desc": "\uAC04\uC774\uACFC\uC138\uC790 \uB9E4\uC7A5\uC758 \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58 \uAC00\uB2A5 \uC5EC\uBD80\uC640 \uD544\uC694\uD55C \uC11C\uB958, \uC218\uC218\uB8CC \uAD6C\uAC04\uC774 \uACFC\uC138 \uC720\uD615\uACFC \uBB34\uAD00\uD558\uAC8C \uB9E4\uCD9C\uB85C \uC815\uD574\uC9C0\uB294 \uAD6C\uC870, \uCE74\uB4DC \uB9E4\uCD9C \uC9D1\uACC4\uC640 \uBD80\uAC00\uC138 \uC2E0\uACE0\uC5D0\uC11C \uB2EC\uB77C\uC9C0\uB294 \uC810, \uACFC\uC138 \uC720\uD615\uC774 \uBC14\uB014 \uB54C \uD560 \uC77C\uACFC \uAC1C\uC5C5 \uCCAB \uB2EC \uC810\uAC80 \uD56D\uBAA9\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uAC04\uC774\uACFC\uC138\uC790\uB3C4 \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\uB9CC \uC788\uC73C\uBA74 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uC124\uCE58\uD558\uACE0 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC744 \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC218\uC218\uB8CC\uB294 \uACFC\uC138 \uC720\uD615\uC774 \uC544\uB2C8\uB77C \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uBBC0\uB85C \uC77C\uBC18\uACFC\uC138\uC790\uC640 \uAC19\uC740 \uAE30\uC900\uC774 \uC801\uC6A9\uB418\uACE0, \uB2EC\uB77C\uC9C0\uB294 \uCABD\uC740 \uC138\uAE08 \uC2E0\uACE0 \uBC29\uC2DD\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uC124\uCE58\uC5D0 \uD544\uC694\uD55C \uC11C\uB958\uB294 \uAC19\uC740\uAC00\uC694?", "p": ["\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D, \uB300\uD45C\uC790 \uC2E0\uBD84\uC99D, \uD1B5\uC7A5 \uC0AC\uBCF8\uC73C\uB85C \uC77C\uBC18\uACFC\uC138\uC790\uC640 \uAC19\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\uC5D0 \uAC04\uC774\uACFC\uC138\uC790\uB85C \uD45C\uC2DC\uB418\uC5B4 \uC788\uC5B4\uB3C4 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uADF8\uB300\uB85C \uC9C4\uD589\uB418\uACE0 \uC2EC\uC0AC \uD56D\uBAA9\uB3C4 \uB2E4\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC5C5\uC885\uC5D0 \uB530\uB77C \uC601\uC5C5\uC2E0\uACE0\uC99D \uAC19\uC740 \uCD94\uAC00 \uC11C\uB958\uB97C \uC694\uAD6C\uD558\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uC811\uC218 \uB54C \uBB3B\uC2B5\uB2C8\uB2E4.", "\uAC1C\uC5C5 \uC9C1\uD6C4\uB77C\uBA74 \uB4F1\uB85D\uC99D\uC774 \uB098\uC628 \uB4A4 \uC811\uC218\uD558\uB294 \uAC83\uC774 \uC21C\uC11C\uC774\uACE0, \uB4F1\uB85D\uC99D \uBC1C\uAE09 \uC804\uC5D0\uB294 \uAC00\uB9F9\uC810 \uC2EC\uC0AC\uAC00 \uC2DC\uC791\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD1B5\uC7A5\uC740 \uC0AC\uC5C5\uC790 \uBA85\uC758\uAC00 \uC544\uB2C8\uC5B4\uB3C4 \uB300\uD45C\uC790 \uBA85\uC758\uBA74 \uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC9C0\uB9CC \uCE74\uB4DC\uC0AC\uB9C8\uB2E4 \uB2EC\uB77C \uC811\uC218 \uB54C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uACF5\uB3D9 \uB300\uD45C \uC0AC\uC5C5\uC790\uB294 \uB300\uD45C\uC790 \uBAA8\uB450\uC758 \uC2E0\uBD84\uC99D\uC774 \uD544\uC694\uD560 \uC218 \uC788\uC73C\uB2C8 \uBBF8\uB9AC \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uC811\uC218 \uB54C \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D \uBC1C\uAE09\uC77C\uC774 \uCD5C\uADFC\uC774\uBA74 \uCE74\uB4DC\uC0AC \uC2EC\uC0AC\uAC00 \uB4F1\uB85D \uC0C1\uD0DC\uB97C \uB2E4\uC2DC \uC870\uD68C\uD558\uB290\uB77C \uD558\uB8E8 \uC815\uB3C4 \uB354 \uAC78\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC218\uC218\uB8CC\uC640 \uC138\uAE08\uC740 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uCE74\uB4DC \uC218\uC218\uB8CC\uB294 \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uACE0 \uAC04\uC774\uACFC\uC138 \uC5EC\uBD80\uC640 \uAD00\uACC4\uC5C6\uC2B5\uB2C8\uB2E4.", "\uCE74\uB4DC \uB9E4\uCD9C\uC740 \uAD6D\uC138\uCCAD\uC5D0 \uC790\uB3D9\uC73C\uB85C \uC9D1\uACC4\uB418\uBBC0\uB85C \uC2E0\uACE0 \uB54C \uB9E4\uCD9C \uC790\uB8CC\uB85C \uC4F0\uC774\uACE0, \uB204\uB77D\uD558\uBA74 \uC9D1\uACC4\uC640 \uC2E0\uACE0\uAC00 \uC5B4\uAE0B\uB0A9\uB2C8\uB2E4.", "\uAC04\uC774\uACFC\uC138\uC790\uB294 \uBD80\uAC00\uAC00\uCE58\uC138 \uC2E0\uACE0 \uBC29\uC2DD\uC774 \uB2E4\uB974\uBBC0\uB85C \uCE74\uB4DC \uB9E4\uCD9C \uC9D1\uACC4\uB97C \uC138\uBB34 \uB300\uB9AC\uC778\uACFC \uB9DE\uCDB0 \uB461\uB2C8\uB2E4.", "\uD604\uAE08\uC601\uC218\uC99D \uBC1C\uAE09 \uC758\uBB34 \uC5C5\uC885\uC774\uBA74 \uB2E8\uB9D0\uAE30\uC5D0\uC11C \uD604\uAE08\uC601\uC218\uC99D \uAE30\uB2A5\uC744 \uAC19\uC774 \uC5F4\uC5B4 \uB461\uB2C8\uB2E4.", "\uCE74\uB4DC \uB9E4\uCD9C \uC138\uC561\uACF5\uC81C \uAC19\uC740 \uD56D\uBAA9\uC740 \uC5C5\uC885\uACFC \uB9E4\uCD9C\uC5D0 \uB530\uB77C \uC801\uC6A9\uC774 \uB2EC\uB77C \uC138\uBB34 \uB300\uB9AC\uC778\uC5D0\uAC8C \uBB3B\uC2B5\uB2C8\uB2E4.", "\uB9E4\uCD9C\uC774 \uAE30\uC900\uC744 \uB118\uC5B4 \uACFC\uC138 \uC720\uD615\uC774 \uBC14\uB00C\uBA74 \uAD6D\uC138\uCCAD\uC774 \uD1B5\uC9C0\uD558\uBA70, \uADF8\uB54C \uB2E8\uB9D0\uAE30 \uCABD\uC5D0\uC11C \uD560 \uC77C\uC740 \uC0AC\uC5C5\uC790 \uC815\uBCF4 \uAC31\uC2E0\uBFD0\uC785\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uB9E4\uCD9C\uACFC \uCE74\uB4DC \uB9E4\uCD9C\uC744 \uB530\uB85C \uC801\uC5B4 \uB450\uBA74 \uACFC\uC138 \uC720\uD615 \uD310\uC815 \uAE30\uC900\uC774 \uB418\uB294 \uCD1D\uB9E4\uCD9C\uC744 \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uBB34\uC5C7\uC744 \uC8FC\uC758\uD574\uC57C \uD558\uB098\uC694?", "p": ["\uB9E4\uCD9C\uC774 \uB298\uC5B4 \uACFC\uC138 \uC720\uD615\uC774 \uBC14\uB00C\uC5B4\uB3C4 \uB2E8\uB9D0\uAE30\uC640 \uAC00\uB9F9\uC810\uC740 \uADF8\uB300\uB85C \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uB2E4\uB9CC \uC218\uC218\uB8CC \uAD6C\uAC04\uC740 \uB9E4\uCD9C\uC5D0 \uB530\uB77C \uC7AC\uC0B0\uC815\uB418\uBBC0\uB85C \uD1B5\uC9C0\uBB38\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uACB0\uC81C\uCC98\uB7FC \uB2E8\uB9D0\uAE30\uB97C \uAC70\uCE58\uC9C0 \uC54A\uB294 \uB9E4\uCD9C\uC740 \uC815\uC0B0\uC11C\uAC00 \uB530\uB85C \uC624\uBBC0\uB85C \uD569\uC0B0 \uAD00\uB9AC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uC601\uC138 \uAC00\uB9F9\uC810 \uC6B0\uB300 \uC801\uC6A9 \uC5EC\uBD80\uB294 \uCE74\uB4DC\uC0AC \uC548\uB0B4\uBB38\uC73C\uB85C \uD655\uC778\uD558\uACE0, \uD604\uC7AC \uAE30\uC900\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC0AC\uC5C5\uC790 \uC815\uBCF4\uAC00 \uBC14\uB00C\uBA74 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC815\uBCF4\uB3C4 \uAC31\uC2E0\uD574\uC57C \uC815\uC0B0\uC774 \uB04A\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uAC04\uC774\uACFC\uC138\uC790\uB294 \uC138\uAE08\uACC4\uC0B0\uC11C \uBC1C\uAE09\uC774 \uC81C\uD55C\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uAE30\uC5C5 \uC190\uB2D8\uC774 \uB9CE\uC740 \uC5C5\uC885\uC774\uBA74 \uC138\uBB34 \uB300\uB9AC\uC778\uACFC \uBA3C\uC800 \uC0C1\uC758\uD569\uB2C8\uB2E4.", "\uAC04\uC774\uACFC\uC138\uC790\uB3C4 \uCE74\uB4DC \uB9E4\uCD9C\uC774 \uB298\uBA74 \uACFC\uC138 \uC720\uD615\uC774 \uBC14\uB014 \uC218 \uC788\uC73C\uBBC0\uB85C \uC6D4 \uB9E4\uCD9C \uD569\uACC4\uB97C \uAFB8\uC900\uD788 \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }, { "h": "\uAC1C\uC5C5 \uCCAB \uB2EC\uC5D0\uB294 \uBB34\uC5C7\uC744 \uCC59\uAE30\uB098\uC694?", "p": ["\uCCAB \uC815\uC0B0\uC11C\uAC00 \uC624\uBA74 \uC785\uAE08 \uD1B5\uC7A5\uACFC \uBA85\uC758\uAC00 \uB9DE\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC5D0 \uCC0D\uD788\uB294 \uC0AC\uC5C5\uC790\uBC88\uD638\uC640 \uC0C1\uD638\uAC00 \uB4F1\uB85D\uC99D\uACFC \uAC19\uC740\uC9C0 \uBD05\uB2C8\uB2E4.", "\uB9E4\uCD9C \uC790\uB8CC\uAC00 \uC313\uC774\uAE30 \uC804\uC774\uB77C \uAD6C\uAC04\uC774 \uC77C\uBC18\uC73C\uB85C \uC7A1\uD600 \uC788\uC744 \uC218 \uC788\uC73C\uB2C8 \uB2E4\uC74C \uC0B0\uC815 \uC2DC\uAE30\uB97C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uD604\uAE08 \uB9E4\uCD9C\uC740 \uB2E8\uB9D0\uAE30 \uBC16\uC5D0\uC11C \uC0DD\uAE30\uBBC0\uB85C \uC7A5\uBD80\uB97C \uB530\uB85C \uB450\uC5B4 \uC2E0\uACE0 \uB54C \uD569\uCE69\uB2C8\uB2E4.", "\uC815\uC0B0 \uC8FC\uAE30\uC640 \uCE74\uB4DC\uC0AC\uBCC4 \uC785\uAE08\uC77C\uC744 \uD55C \uBC88 \uC801\uC5B4 \uB450\uBA74 \uC6D4\uB9D0 \uB9E4\uCD9C \uD655\uC778\uC774 \uC26C\uC6CC\uC9D1\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C\uC5D0 \uCC0D\uD78C \uC785\uAE08\uC561\uC740 \uC218\uC218\uB8CC\uAC00 \uBE60\uC9C4 \uAE08\uC561\uC774\uBBC0\uB85C \uB9E4\uCD9C\uB85C \uC801\uC744 \uB54C\uB294 \uC2B9\uC778 \uCD1D\uC561\uC744 \uC501\uB2C8\uB2E4.", "\uCCAB \uB2EC \uC815\uC0B0\uC11C\uB97C \uC138\uBB34 \uB300\uB9AC\uC778\uC5D0\uAC8C \uBCF4\uB0B4 \uC2E0\uACE0 \uBC29\uC2DD\uC5D0 \uB9DE\uB294\uC9C0 \uBBF8\uB9AC \uD655\uC778\uD574 \uB450\uBA74 \uC2E0\uACE0 \uB54C \uB2F9\uD669\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC138\uBB34 \uB300\uB9AC\uC778\uC774 \uC5C6\uB294 \uB9E4\uC7A5\uC740 \uAD6D\uC138\uCCAD \uD648\uD0DD\uC2A4\uC5D0\uC11C \uCE74\uB4DC \uB9E4\uCD9C \uC9D1\uACC4\uB97C \uC9C1\uC811 \uBCFC \uC218 \uC788\uC73C\uB2C8 \uC6D4\uCD08\uC5D0 \uD55C \uBC88 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uD45C\uAE30\uAC00 \uC798\uBABB\uB3FC \uC788\uC73C\uBA74 \uC124\uCE58\uC5C5\uCCB4\uC5D0 \uBC14\uB85C \uC218\uC815\uC744 \uC694\uCCAD\uD574\uC57C \uC138\uBB34 \uC790\uB8CC\uAC00 \uC5B4\uAE0B\uB098\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC6D4\uB9D0\uC5D0 \uCE74\uB4DC \uB9E4\uCD9C\uACFC \uD604\uAE08 \uB9E4\uCD9C\uC744 \uD569\uCCD0 \uC7A5\uBD80\uC5D0 \uC801\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uC124\uCE58 \uC808\uCC28\uB294 \uC77C\uBC18\uACFC\uC138\uC790\uC640 \uB2E4\uB978\uAC00\uC694?", "items": ["\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\uACFC \uC2E0\uBD84\uC99D, \uD1B5\uC7A5 \uC0AC\uBCF8\uC744 \uC811\uC218\uD569\uB2C8\uB2E4.", "\uAC00\uB9F9\uC810 \uB4F1\uB85D \uC2EC\uC0AC\uB97C \uAC70\uCCD0 \uAC00\uB9F9\uC810 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uC5F0\uACB0\uD558\uACE0 \uD604\uAE08\uC601\uC218\uC99D \uAE30\uB2A5 \uC5EC\uBD80\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uCCAB \uC815\uC0B0\uC11C\uC5D0\uC11C \uC218\uC218\uB8CC \uAD6C\uAC04\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB2E4\uC74C \uBC18\uAE30 \uC218\uC218\uB8CC \uC7AC\uC0B0\uC815 \uC2DC\uAE30\uB97C \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }, "table": { "caption": "\uAC04\uC774\uACFC\uC138\uC790\uC640 \uC77C\uBC18\uACFC\uC138\uC790 \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uAC04\uC774\uACFC\uC138\uC790", "\uC77C\uBC18\uACFC\uC138\uC790"], "rows": [["\uC124\uCE58 \uC11C\uB958", "\uAC19\uC74C", "\uAC19\uC74C"], ["\uC218\uC218\uB8CC \uAE30\uC900", "\uB9E4\uCD9C \uAD6C\uAC04", "\uB9E4\uCD9C \uAD6C\uAC04"], ["\uBD80\uAC00\uC138 \uC2E0\uACE0", "\uAC04\uC774 \uBC29\uC2DD", "\uC77C\uBC18 \uBC29\uC2DD"], ["\uD604\uAE08\uC601\uC218\uC99D", "\uC5C5\uC885\uC5D0 \uB530\uB77C \uC758\uBB34", "\uC5C5\uC885\uC5D0 \uB530\uB77C \uC758\uBB34"], ["\uACFC\uC138 \uC720\uD615 \uBCC0\uACBD \uC2DC", "\uC0AC\uC5C5\uC790 \uC815\uBCF4 \uAC31\uC2E0", "\uC0AC\uC5C5\uC790 \uC815\uBCF4 \uAC31\uC2E0"]] }, "faq": [["\uAC04\uC774\uACFC\uC138\uC790\uB294 \uC124\uCE58\uAC00 \uAC70\uC808\uB418\uAE30\uB3C4 \uD558\uB098\uC694?", "\uACFC\uC138 \uC720\uD615 \uB54C\uBB38\uC5D0 \uAC70\uC808\uB418\uC9C0\uB294 \uC54A\uC2B5\uB2C8\uB2E4. \uC5C5\uC885 \uC81C\uD55C\uC774\uB098 \uC11C\uB958 \uBD88\uC77C\uCE58\uAC00 \uC774\uC720\uC778 \uACBD\uC6B0\uAC00 \uB300\uBD80\uBD84\uC785\uB2C8\uB2E4. \uC11C\uB958\uAC00 \uB9DE\uC9C0 \uC54A\uC544 \uB418\uB3CC\uC544\uC654\uB2E4\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC778\uC9C0 \uC811\uC218 \uCC3D\uAD6C\uC5D0 \uBB3C\uC5B4 \uBC14\uB85C \uBCF4\uC644\uD569\uB2C8\uB2E4."], ["\uC218\uC218\uB8CC\uAC00 \uB354 \uB192\uAC8C \uC801\uC6A9\uB418\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uB9E4\uCD9C \uAD6C\uAC04\uC774 \uAC19\uC73C\uBA74 \uAC19\uC740 \uBE44\uC728\uC785\uB2C8\uB2E4. \uC6B0\uB300 \uAD6C\uAC04 \uC801\uC6A9\uB3C4 \uB9E4\uCD9C \uAE30\uC900\uC774\uBBC0\uB85C \uACFC\uC138 \uC720\uD615\uACFC \uAD00\uACC4\uC5C6\uC774 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uC815\uD574\uC9D1\uB2C8\uB2E4."], ["\uB098\uC911\uC5D0 \uC77C\uBC18\uACFC\uC138\uC790\uB85C \uBC14\uB00C\uBA74 \uB2E4\uC2DC \uC124\uCE58\uD558\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uC0AC\uC5C5\uC790 \uC815\uBCF4\uB9CC \uAC31\uC2E0\uD558\uBA74 \uB418\uACE0 \uAE30\uAE30\uC640 \uAC00\uB9F9\uC810 \uBC88\uD638\uB294 \uADF8\uB300\uB85C\uC785\uB2C8\uB2E4."], ["\uD604\uAE08\uC601\uC218\uC99D\uB3C4 \uB2E8\uB9D0\uAE30\uB85C \uBC1C\uAE09\uB418\uB098\uC694?", "\uAE30\uB2A5\uC744 \uC5F4\uC5B4 \uB450\uBA74 \uAC19\uC740 \uAE30\uAE30\uC5D0\uC11C \uBC1C\uAE09\uB429\uB2C8\uB2E4. \uC758\uBB34 \uC5C5\uC885\uC774\uBA74 \uC124\uCE58 \uB54C \uAC19\uC774 \uC5F4\uC5B4 \uB461\uB2C8\uB2E4. \uD604\uAE08\uC601\uC218\uC99D \uBC1C\uAE09 \uB0B4\uC5ED\uC740 \uAD6D\uC138\uCCAD\uC73C\uB85C \uBC14\uB85C \uC804\uC1A1\uB418\uBBC0\uB85C \uB530\uB85C \uC2E0\uACE0\uD560 \uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC218\uC218\uB8CC", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uAC04\uC774\uACFC\uC138\uC790\uC218\uC218\uB8CC"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uBB34\uC120", "product": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "tail": "\uBC30\uB2EC \uBB34\uC120\uB2E8\uB9D0\uAE30", "title": "\uBC30\uB2EC \uB9E4\uC7A5\uC5D0\uB294 \uC5B4\uB5A4 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uAC00 \uB9DE\uB098\uC694? \u2014 \uBB34\uC120 \uACB0\uC81C\uB97C \uBC1B\uB294 \uC138 \uAC00\uC9C0 \uBC29\uC2DD", "desc": "\uBC30\uB2EC \uB9E4\uC7A5\uC5D0\uC11C \uD604\uC7A5 \uACB0\uC81C\uB97C \uBC1B\uC744 \uB54C \uC571 \uC120\uACB0\uC81C, \uBB34\uC120\uB2E8\uB9D0\uAE30 \uD604\uC7A5 \uACB0\uC81C, \uB9C1\uD06C \uACB0\uC81C\uC758 \uC815\uC0B0 \uACBD\uB85C \uCC28\uC774\uC640 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uACE0\uB974\uB294 \uAE30\uC900, \uBC30\uB2EC \uAE30\uC0AC\uC5D0\uAC8C \uAE30\uAE30\uB97C \uB9E1\uAE38 \uB54C \uC815\uD560 \uADDC\uCE59, \uAE30\uAE30 \uC218\uB97C \uC815\uD558\uB294 \uBC29\uBC95\uACFC \uC6B4\uC601 \uC911 \uC8FC\uC758\uC810\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBC30\uB2EC \uD604\uC7A5 \uACB0\uC81C\uB294 LTE \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uBC30\uB2EC \uAE30\uC0AC\uAC00 \uB4E4\uACE0 \uB098\uAC00\uB294 \uBC29\uC2DD\uC774 \uAE30\uBCF8\uC774\uACE0, \uC8FC\uBB38 \uC571 \uACB0\uC81C\uAC00 \uB300\uBD80\uBD84\uC778 \uB9E4\uC7A5\uC740 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uD55C \uB300\uB85C\uB3C4 \uC6B4\uC601\uB429\uB2C8\uB2E4. \uD604\uC7A5 \uACB0\uC81C \uBE44\uC911\uC744 \uBA3C\uC800 \uC138\uC5B4 \uBCF4\uBA74 \uAE30\uAE30 \uC218\uAC00 \uC815\uD574\uC9C0\uACE0, \uAE30\uAE30 \uC218\uAC00 \uC815\uD574\uC9C0\uBA74 \uD1B5\uC2E0 \uC694\uAE08\uACFC \uBC18\uB0A9 \uADDC\uCE59\uC774 \uB530\uB77C\uC635\uB2C8\uB2E4.", "sections": [{ "h": "\uBC30\uB2EC \uACB0\uC81C\uB294 \uC5B4\uB5A4 \uBC29\uC2DD\uB4E4\uC774 \uC788\uB098\uC694?", "p": ["\uC8FC\uBB38 \uC571\uC5D0\uC11C \uBBF8\uB9AC \uACB0\uC81C\uB418\uB294 \uBC29\uC2DD, \uBC30\uB2EC \uAE30\uC0AC\uAC00 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB85C \uD604\uC7A5\uC5D0\uC11C \uBC1B\uB294 \uBC29\uC2DD, \uC804\uD654 \uC8FC\uBB38 \uB4A4 \uB9E4\uC7A5\uC5D0\uC11C \uB9C1\uD06C\uB85C \uBC1B\uB294 \uBC29\uC2DD\uC774 \uC788\uC2B5\uB2C8\uB2E4.", "\uC571 \uACB0\uC81C\uB294 \uC571 \uC815\uC0B0\uC11C\uB85C \uB4E4\uC5B4\uC624\uACE0 \uB2E8\uB9D0\uAE30\uB97C \uAC70\uCE58\uC9C0 \uC54A\uC73C\uBBC0\uB85C \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uC815\uC0B0\uC11C\uC5D0\uB294 \uBCF4\uC774\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C\uB294 \uB9E4\uC7A5 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uC2B9\uC778\uB418\uBBC0\uB85C \uB9E4\uC7A5 \uC815\uC0B0\uC11C\uC5D0 \uB4E4\uC5B4\uC635\uB2C8\uB2E4.", "\uC138 \uBC29\uC2DD\uC758 \uC815\uC0B0 \uACBD\uB85C\uAC00 \uB2E4\uB974\uBBC0\uB85C \uC6D4\uB9D0\uC5D0 \uD569\uCCD0 \uBCF4\uB294 \uC2B5\uAD00\uC774 \uD544\uC694\uD558\uACE0, \uC138\uBB34 \uC2E0\uACE0 \uB54C\uB3C4 \uC138 \uACBD\uB85C\uB97C \uBAA8\uB450 \uD569\uCE69\uB2C8\uB2E4.", "\uB9C1\uD06C \uACB0\uC81C\uB294 \uBE44\uB300\uBA74 \uACBD\uB85C\uB77C \uB300\uBA74 \uACB0\uC81C\uC640 \uCC98\uB9AC \uBE44\uC728\uC774 \uB2E4\uB97C \uC218 \uC788\uC73C\uB2C8 \uC815\uC0B0\uC11C\uC5D0\uC11C \uB098\uB220 \uBD05\uB2C8\uB2E4.", "\uC804\uD654 \uC8FC\uBB38\uC774 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uB9C1\uD06C \uACB0\uC81C\uC640 \uD604\uC7A5 \uACB0\uC81C\uB97C \uC11E\uC5B4 \uC4F0\uBA74 \uAE30\uC0AC \uAE30\uAE30 \uC218\uB97C \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uB294 \uC5B4\uB5BB\uAC8C \uACE0\uB974\uB098\uC694?", "p": ["\uD1B5\uC2E0\uC740 LTE \uBC29\uC2DD\uC774 \uBC30\uB2EC\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4. \uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uC2A4\uB9C8\uD2B8\uD3F0\uACFC \uC9DD\uC744 \uC774\uB904\uC57C \uD574 \uAE30\uC0AC\uB9C8\uB2E4 \uC124\uC815\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uBC30\uD130\uB9AC \uC0AC\uC6A9 \uC2DC\uAC04\uACFC \uCDA9\uC804 \uBC29\uC2DD\uC744 \uD655\uC778\uD569\uB2C8\uB2E4. \uD558\uB8E8 \uBC30\uB2EC \uAC74\uC218\uAC00 \uB9CE\uC73C\uBA74 \uC608\uBE44 \uBC30\uD130\uB9AC\uB098 \uAC70\uCE58\uB300 \uCDA9\uC804\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uCD9C\uB825\uC774 \uD544\uC694\uD55C \uC5C5\uC885\uC774\uBA74 \uD504\uB9B0\uD130 \uB0B4\uC7A5 \uAE30\uAE30\uB97C, \uC544\uB2C8\uBA74 \uC804\uC790 \uC601\uC218\uC99D \uAE30\uAE30\uB97C \uACE0\uB985\uB2C8\uB2E4.", "\uAE30\uC0AC\uAC00 \uC5EC\uB7EC \uBA85\uC774\uBA74 \uAE30\uAE30 \uB300\uC218\uC640 \uBC18\uB0A9 \uADDC\uCE59\uC744 \uC815\uD574 \uB450\uACE0, \uAE30\uAE30\uB9C8\uB2E4 \uBC88\uD638\uB97C \uBD99\uC5EC \uB204\uAC00 \uB4E4\uACE0 \uB098\uAC14\uB294\uC9C0 \uC801\uC2B5\uB2C8\uB2E4.", "\uBE44 \uC624\uB294 \uB0A0 \uBC30\uB2EC\uC774 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uBC29\uC218 \uD30C\uC6B0\uCE58\uB098 \uBCF4\uD638 \uCF00\uC774\uC2A4\uB97C \uAC19\uC774 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uBB34\uAC8C\uC640 \uD06C\uAE30\uB3C4 \uAE30\uC0AC\uAC00 \uD558\uB8E8 \uC885\uC77C \uB4E4\uACE0 \uB2E4\uB2C8\uB294 \uAC83\uC774\uBBC0\uB85C \uC2E4\uC81C\uB85C \uC950\uC5B4 \uBCF4\uACE0 \uACE0\uB985\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C\uAC00 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uD558\uB098\uAC00 \uBA48\uCD94\uBA74 \uB9E4\uCD9C\uC774 \uBC14\uB85C \uC904\uAE30 \uB54C\uBB38\uC5D0 \uAD50\uCCB4 \uAE30\uAE30 \uC870\uAC74\uC744 \uC57D\uC815\uC11C\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C \uC601\uC218\uC99D\uC744 \uAE30\uC0AC\uAC00 \uAC00\uC838\uC624\uBA74 \uB0A0\uC9DC\uBCC4 \uBD09\uD22C\uC5D0 \uBAA8\uC544 \uB450\uACE0 \uC815\uC0B0\uC11C\uC640 \uB9DE\uCD94\uB294 \uB2F4\uB2F9\uC744 \uC815\uD574 \uB461\uB2C8\uB2E4."] }, { "h": "\uC6B4\uC601\uD560 \uB54C \uBB34\uC5C7\uC744 \uC8FC\uC758\uD558\uB098\uC694?", "p": ["\uAE30\uC0AC\uAC00 \uBC14\uB014 \uB54C \uAE30\uAE30 \uBC18\uB0A9\uC744 \uD655\uC778\uD558\uACE0, \uBD84\uC2E4 \uC870\uD56D\uC744 \uC57D\uC815\uC11C\uC5D0\uC11C \uBBF8\uB9AC \uBD10 \uB461\uB2C8\uB2E4.", "\uD604\uC7A5 \uCDE8\uC18C\uB294 \uAC19\uC740 \uAE30\uAE30\uC5D0\uC11C \uD574\uC57C \uD558\uBBC0\uB85C \uCDE8\uC18C \uBC29\uBC95\uC744 \uAE30\uC0AC\uC5D0\uAC8C \uC54C\uB824 \uB450\uACE0 \uAE30\uAE30 \uC606\uC5D0 \uC21C\uC11C\uB97C \uBD99\uC5EC \uB461\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uC694\uAE08\uC740 \uAE30\uAE30\uB9C8\uB2E4 \uB530\uB85C \uB098\uAC00\uBBC0\uB85C \uB300\uC218\uB97C \uB298\uB9B4 \uB54C \uC6D4 \uBE44\uC6A9\uC744 \uAC19\uC774 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uC571 \uACB0\uC81C\uC640 \uD604\uC7A5 \uACB0\uC81C \uBE44\uC911\uC774 \uBC14\uB00C\uBA74 \uAE30\uAE30 \uC218\uB97C \uB2E4\uC2DC \uC815\uD558\uACE0, \uC870\uC815 \uC870\uAC74\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC30\uD130\uB9AC\uAC00 \uB5A8\uC5B4\uC838 \uACB0\uC81C\uAC00 \uC548 \uB41C \uAC74\uC740 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC5D0\uC11C \uC804\uD654 \uACB0\uC81C\uB85C \uBC1B\uC744 \uC218 \uC788\uB3C4\uB85D \uC190\uB2D8 \uC5F0\uB77D\uCC98\uB97C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uB9E4\uC7A5 \uBC16\uC73C\uB85C \uAC00\uC838\uAC00\uB294 \uB9CC\uD07C \uBD84\uC2E4\xB7\uD30C\uC190\uC774 \uB9E4\uC7A5 \uC548\uBCF4\uB2E4 \uC7A6\uC73C\uB2C8 \uBCF4\uD5D8\uC774\uB098 \uBCF4\uD638 \uC57D\uC815\uC774 \uC788\uB294\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4."] }, { "h": "\uAE30\uAE30 \uC218\uB294 \uC5B4\uB5BB\uAC8C \uC815\uD558\uB098\uC694?", "p": ["\uD55C \uB2EC \uCE58 \uC8FC\uBB38\uC5D0\uC11C \uD604\uC7A5 \uACB0\uC81C\uAC00 \uBA87 \uAC74\uC778\uC9C0 \uC138\uACE0, \uAC19\uC740 \uC2DC\uAC04\uB300\uC5D0 \uB098\uAC00\uB294 \uAE30\uC0AC \uC218\uB97C \uBD05\uB2C8\uB2E4.", "\uB3D9\uC2DC\uC5D0 \uB098\uAC00\uB294 \uAE30\uC0AC \uC218\uB9CC\uD07C \uAE30\uAE30\uAC00 \uC788\uC5B4\uC57C \uACB0\uC81C\uB97C \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C\uAC00 \uB4DC\uBB3C\uBA74 \uAE30\uAE30 \uD55C \uB300\uB97C \uB9E4\uC7A5\uC5D0 \uB450\uACE0 \uD544\uC694\uD55C \uAE30\uC0AC\uB9CC \uB4E4\uACE0 \uB098\uAC00\uB294 \uBC29\uC2DD\uC73C\uB85C \uC2DC\uC791\uD569\uB2C8\uB2E4.", "\uB300\uC218\uB294 \uB098\uC911\uC5D0 \uB298\uB9B4 \uC218 \uC788\uC73C\uB2C8 \uCC98\uC74C\uBD80\uD130 \uB9CE\uC774 \uB450\uC9C0 \uC54A\uC544\uB3C4 \uB429\uB2C8\uB2E4.", "\uD53C\uD06C \uC2DC\uAC04\uB300\uC5D0\uB9CC \uAE30\uC0AC\uAC00 \uB298\uC5B4\uB098\uB294 \uB9E4\uC7A5\uC740 \uC608\uBE44 \uAE30\uAE30 \uD55C \uB300\uB97C \uCDA9\uC804\uD574 \uB450\uB294 \uBC29\uC2DD\uC774 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uBC30\uB2EC\uC774 \uBAB0\uB9AC\uB294 \uC694\uC77C\uACFC \uC2DC\uAC04\uB300\uB97C \uD55C \uB2EC \uC815\uB3C4 \uC801\uC5B4 \uB450\uBA74 \uAE30\uAE30 \uC218\uB97C \uB298\uB9B4 \uC2DC\uC810\uC774 \uBCF4\uC785\uB2C8\uB2E4.", "\uAE30\uC0AC \uAD50\uB300 \uC2DC\uAC04\uC5D0 \uAE30\uAE30\uB97C \uB118\uAE30\uB294 \uC790\uB9AC\uB97C \uC815\uD574 \uB450\uBA74 \uBD84\uC2E4\uACFC \uBC30\uD130\uB9AC \uBC29\uC804\uC774 \uD568\uAED8 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uAE30 \uD1B5\uC2E0 \uC0C1\uD0DC\uAC00 \uB098\uC05C \uC9C0\uC5ED\uC774 \uBC18\uBCF5\uB418\uBA74 \uD1B5\uC2E0\uC0AC \uBCC0\uACBD\uC774 \uAC00\uB2A5\uD55C\uC9C0 \uC5C5\uCCB4\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uBC88\uD638\uC640 \uAE30\uC0AC \uC774\uB984\uC744 \uC801\uC740 \uC7A5\uBD80\uB294 \uBD84\uC2E4 \uB54C \uBCF4\uD5D8 \uCC98\uB9AC\uC5D0\uB3C4 \uADFC\uAC70\uB85C \uC4F0\uC785\uB2C8\uB2E4.", "\uBD84\uC2E4\xB7\uD30C\uC190 \uC870\uD56D\uC744 \uAE30\uC0AC \uAD50\uC721 \uB54C \uD568\uAED8 \uC54C\uB824 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uB3C4\uC785 \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD55C \uB2EC \uCE58 \uC8FC\uBB38\uC5D0\uC11C \uD604\uC7A5 \uACB0\uC81C \uBE44\uC911\uC744 \uC149\uB2C8\uB2E4.", "\uD544\uC694\uD55C \uBB34\uC120\uB2E8\uB9D0\uAE30 \uB300\uC218\uC640 \uD1B5\uC2E0 \uBC29\uC2DD\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uAE30\uAE30\uB97C \uB4F1\uB85D\uD558\uACE0 \uACB0\uC81C\xB7\uCDE8\uC18C\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uAE30\uC0AC\uBCC4 \uAE30\uAE30 \uBC30\uC815\uACFC \uBC18\uB0A9 \uADDC\uCE59\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uD55C \uB2EC \uB4A4 \uD604\uC7A5 \uACB0\uC81C \uAC74\uC218\uC640 \uAE30\uAE30 \uC0AC\uC6A9 \uBE48\uB3C4\uB97C \uB2E4\uC2DC \uC138\uC5B4 \uB300\uC218\uB97C \uC870\uC815\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uBC30\uB2EC \uACB0\uC81C \uBC29\uC2DD \uBE44\uAD50", "head": ["\uBC29\uC2DD", "\uAE30\uAE30", "\uC815\uC0B0 \uACBD\uB85C"], "rows": [["\uC571 \uC120\uACB0\uC81C", "\uC5C6\uC74C", "\uC571 \uC815\uC0B0"], ["\uD604\uC7A5 \uBB34\uC120 \uACB0\uC81C", "LTE \uBB34\uC120\uB2E8\uB9D0\uAE30", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810"], ["\uB9C1\uD06C \uACB0\uC81C", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\xB7\uC571", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810"], ["\uC804\uD654 \uC8FC\uBB38 \uB4A4 \uBC29\uBB38", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810"]] }, "faq": [["\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB85C \uBC30\uB2EC \uACB0\uC81C\uB97C \uBC1B\uC744 \uC218 \uC788\uB098\uC694?", "\uAE30\uC0AC\uAC00 \uB3CC\uC544\uC640\uC11C \uBC1B\uB294 \uBC29\uC2DD\uC774\uBA74 \uB418\uC9C0\uB9CC \uD604\uC7A5\uC5D0\uC11C\uB294 \uBB34\uC120\uAE30\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4. \uAE30\uC0AC\uAC00 \uB9E4\uC7A5\uC5D0 \uB3CC\uC544\uC624\uB294 \uAC04\uACA9\uC774 \uAE38\uBA74 \uADF8 \uC0AC\uC774 \uACB0\uC81C\uAC00 \uBC00\uB9AC\uBBC0\uB85C \uD604\uC7A5 \uAE30\uAE30\uAC00 \uB0AB\uC2B5\uB2C8\uB2E4."], ["\uBB34\uC120\uB2E8\uB9D0\uAE30 \uD1B5\uC2E0\uBE44\uB294 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uAE30\uAE30\uB9C8\uB2E4 \uC6D4 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB530\uB85C \uC788\uC73C\uBA70 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uB300\uC218\uB97C \uB298\uB9AC\uBA74 \uADF8\uB9CC\uD07C \uB354\uD574\uC9D1\uB2C8\uB2E4. \uD1B5\uC2E0 \uC694\uAE08\uC740 \uAE30\uAE30 \uC57D\uC815\uACFC \uBB36\uC5EC \uC788\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC57D\uC815\uC11C\uC5D0\uC11C \uD568\uAED8 \uBD05\uB2C8\uB2E4."], ["\uAE30\uC0AC\uAC00 \uAE30\uAE30\uB97C \uC783\uC5B4\uBC84\uB9AC\uBA74\uC694?", "\uC57D\uC815\uC11C\uC758 \uBD84\uC2E4 \uC870\uD56D\uC5D0 \uB530\uB974\uBA70, \uBC14\uB85C \uC5C5\uCCB4\uC5D0 \uC54C\uB824 \uAE30\uAE30\uB97C \uC815\uC9C0\uC2DC\uD0B5\uB2C8\uB2E4. \uBD84\uC2E4 \uC2E0\uACE0 \uB4A4 \uC0C8 \uAE30\uAE30\uB97C \uBC1B\uB294 \uAE30\uAC04\uC5D0\uB294 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uB9C1\uD06C \uACB0\uC81C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4."], ["\uC571 \uACB0\uC81C\uB9CC \uBC1B\uB294 \uB9E4\uC7A5\uB3C4 \uB2E8\uB9D0\uAE30\uAC00 \uD544\uC694\uD55C\uAC00\uC694?", "\uB9E4\uC7A5 \uBC29\uBB38 \uC190\uB2D8\uC774 \uC788\uC73C\uBA74 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uD55C \uB300\uB294 \uD544\uC694\uD569\uB2C8\uB2E4. \uBC29\uBB38 \uC190\uB2D8\uC774 \uC5C6\uC73C\uBA74 \uB9C1\uD06C \uACB0\uC81C\uC6A9 \uAE30\uAE30\uB9CC\uC73C\uB85C\uB3C4 \uB429\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uC124\uCE58", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uC124\uCE58", "title": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694? \u2014 \uD504\uB85C\uADF8\uB7A8 \uC138\uD305\uBD80\uD130 \uCCAB \uC601\uC5C5\uAE4C\uC9C0", "desc": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uAC00 \uD504\uB85C\uADF8\uB7A8 \uC120\uD0DD, \uBA54\uB274\xB7\uC88C\uC11D \uC785\uB825, \uAE30\uAE30 \uC124\uCE58, \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC5F0\uACB0, \uC9C1\uC6D0 \uAD50\uC721\uC758 \uC21C\uC11C\uB85C \uC9C4\uD589\uB418\uB294 \uACFC\uC815\uACFC, \uC124\uCE58 \uC804\uC5D0 \uB9E4\uC7A5\uC774 \uC815\uB9AC\uD574 \uB458 \uBA54\uB274 \uC790\uB8CC\uC640 \uC790\uB9AC, \uC124\uCE58 \uB2F9\uC77C \uC810\uAC80 \uD56D\uBAA9\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uB294 \uD504\uB85C\uADF8\uB7A8\uC744 \uACE0\uB974\uACE0 \uBA54\uB274\uC640 \uC88C\uC11D\uC744 \uC785\uB825\uD55C \uB4A4 \uAE30\uAE30\uB97C \uB193\uACE0 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uC5F0\uACB0\uD574 \uCCAB \uC8FC\uBB38\uC73C\uB85C \uD14C\uC2A4\uD2B8\uD558\uB294 \uC21C\uC11C\uC785\uB2C8\uB2E4. \uAE30\uAE30\uB97C \uB193\uB294 \uC791\uC5C5\uBCF4\uB2E4 \uBA54\uB274 \uC785\uB825\uC774 \uB354 \uC624\uB798 \uAC78\uB9AC\uBBC0\uB85C \uBA54\uB274\uD45C\uB97C \uBA3C\uC800 \uC815\uB9AC\uD574 \uB450\uB294 \uAC83\uC774 \uC124\uCE58\uC77C\uC744 \uB2F9\uAE30\uB294 \uAE38\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uC124\uCE58 \uC804\uC5D0 \uC815\uB9AC\uD560 \uAC83\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uBA54\uB274 \uC774\uB984, \uAC00\uACA9, \uC635\uC158, \uCE74\uD14C\uACE0\uB9AC\uB97C \uD45C\uB85C \uC815\uB9AC\uD574 \uB450\uBA74 \uD504\uB85C\uADF8\uB7A8 \uC785\uB825\uC774 \uD55C \uBC88\uC5D0 \uB05D\uB0A9\uB2C8\uB2E4.", "\uC2DD\uB2F9\uC774\uBA74 \uD14C\uC774\uBE14 \uBC88\uD638\uC640 \uC88C\uC11D \uBC30\uCE58\uB3C4\uB97C, \uC18C\uB9E4\uC810\uC774\uBA74 \uC0C1\uD488 \uBC14\uCF54\uB4DC \uBAA9\uB85D\uC744 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30\uB97C \uB193\uC744 \uCE74\uC6B4\uD130 \uC790\uB9AC\uC5D0 \uC804\uC6D0\uACFC \uC778\uD130\uB137\uC774 \uB2FF\uB294\uC9C0, \uD504\uB9B0\uD130\uC640 \uB3C8\uD1B5\uC744 \uB193\uC744 \uACF5\uAC04\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uC774\uBBF8 \uC4F0\uACE0 \uC788\uB2E4\uBA74 \uBAA8\uB378\uBA85\uC744 \uC54C\uB824 \uC8FC\uC5B4\uC57C \uC5F0\uB3D9\uB418\uB294 \uD504\uB85C\uADF8\uB7A8\uC73C\uB85C \uC811\uC218\uB429\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC8FC\uBB38\uC744 \uD3EC\uC2A4\uC5D0\uC11C \uBC1B\uACE0 \uC2F6\uC73C\uBA74 \uC571 \uACC4\uC815 \uC815\uBCF4\uAC00 \uD544\uC694\uD558\uBBC0\uB85C \uC544\uC774\uB514\uB97C \uD655\uC778\uD574 \uB461\uB2C8\uB2E4.", "\uC9C1\uC6D0\uC774 \uC5EC\uB7EC \uBA85\uC774\uBA74 \uB204\uAC00 \uC5B4\uB5A4 \uAD8C\uD55C(\uCDE8\uC18C\xB7\uAC00\uACA9 \uC870\uC815\xB7\uB9C8\uAC10)\uC744 \uAC00\uC9C8\uC9C0 \uBBF8\uB9AC \uC815\uD574 \uB450\uBA74 \uC124\uCE58 \uB2F9\uC77C \uAD8C\uD55C \uC124\uC815\uC774 \uBE60\uB985\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC5D0 \uCC0D\uC744 \uC0C1\uD638, \uC0AC\uC5C5\uC790\uBC88\uD638, \uC804\uD654\uBC88\uD638, \uC8FC\uC18C\uB97C \uB4F1\uB85D\uC99D\uACFC \uAC19\uC740 \uD45C\uAE30\uB85C \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uBA54\uB274\uD45C\uC5D0 \uC635\uC158 \uAC00\uACA9\uACFC \uC138\uD2B8 \uAD6C\uC131\uAE4C\uC9C0 \uC801\uC5B4 \uB450\uBA74 \uC785\uB825 \uB4A4 \uC218\uC815\uD560 \uC77C\uC774 \uC904\uC5B4\uB4E4\uC5B4 \uC124\uCE58 \uB2F9\uC77C \uC2DC\uAC04\uC774 \uB0A8\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB2F9\uC77C\uC5D0\uB294 \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uAE30\uC0AC\uAC00 \uAE30\uAE30\uB97C \uB193\uACE0 \uD504\uB85C\uADF8\uB7A8\uC744 \uC124\uCE58\uD55C \uB4A4 \uBBF8\uB9AC \uBC1B\uC740 \uBA54\uB274 \uC790\uB8CC\uB97C \uC785\uB825\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30, \uC601\uC218\uC99D \uD504\uB9B0\uD130, \uC8FC\uBC29 \uD504\uB9B0\uD130, \uB3C8\uD1B5\uC744 \uC5F0\uACB0\uD558\uACE0 \uC8FC\uBB38 \uD558\uB098\uB97C \uB05D\uAE4C\uC9C0 \uB123\uC5B4 \uBD05\uB2C8\uB2E4.", "\uC8FC\uBB38 \u2192 \uACB0\uC81C \u2192 \uC601\uC218\uC99D \u2192 \uC8FC\uBC29 \uCD9C\uB825 \u2192 \uB9C8\uAC10\uAE4C\uC9C0 \uD55C \uBC14\uD034\uB97C \uC2E4\uC81C\uB85C \uB3CC\uB824\uC57C \uBE60\uC9C4 \uC5F0\uACB0\uC774 \uBCF4\uC785\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uACC4\uC815\uACFC \uAD8C\uD55C\uC744 \uB9CC\uB4E4\uACE0, \uCDE8\uC18C\uC640 \uD658\uBD88\uC744 \uC5B4\uB5BB\uAC8C \uD558\uB294\uC9C0 \uC9C1\uC6D0\uC774 \uBCF4\uB294 \uC55E\uC5D0\uC11C \uD55C \uBC88 \uC2DC\uC5F0\uD569\uB2C8\uB2E4.", "\uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB97C \uCD9C\uB825\uD574 \uB9E4\uCD9C \uD569\uACC4\uAC00 \uC2E4\uC81C \uACB0\uC81C\uC640 \uB9DE\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uC640 \uC6D0\uACA9 \uC9C0\uC6D0 \uBC29\uBC95\uC744 \uBC1B\uC544 \uCE74\uC6B4\uD130 \uC606\uC5D0 \uBD99\uC5EC \uB461\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC740 \uB2F9\uC77C \uCDE8\uC18C\uD558\uAC70\uB098 \uC0AD\uC81C\uD574 \uB9E4\uCD9C \uC790\uB8CC\uC5D0 \uC11E\uC774\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC740 \uC2DD\uB2F9\uC774\uBA74 \uC8FC\uBC29 \uCD9C\uB825\uAE4C\uC9C0, \uC18C\uB9E4\uC810\uC774\uBA74 \uBC14\uCF54\uB4DC \uC77D\uAE30\uAE4C\uC9C0 \uD3EC\uD568\uD574\uC57C \uC2E4\uC81C \uC601\uC5C5 \uD750\uB984\uC774 \uD655\uC778\uB429\uB2C8\uB2E4.", "\uC8FC\uBC29 \uD504\uB9B0\uD130\uAC00 \uB450 \uB300 \uC774\uC0C1\uC774\uBA74 \uC5B4\uB290 \uBA54\uB274\uAC00 \uC5B4\uB290 \uD504\uB9B0\uD130\uB85C \uAC00\uB294\uC9C0 \uBD84\uB958\uB97C \uC124\uCE58 \uB2F9\uC77C \uC815\uD574\uC57C \uC870\uB9AC \uAD6C\uC5ED\uC774 \uC11E\uC774\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58\uAC00 \uB05D\uB09C \uB4A4 \uCCAB \uC8FC\uC5D0\uB294 \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uBA54\uB274 \uC785\uB825\uC774 \uC798\uBABB\uB41C \uD488\uBAA9\uC774 \uC788\uB294\uC9C0 \uC2E4\uC81C \uC8FC\uBB38\uC73C\uB85C \uD558\uB8E8\uC774\uD2C0 \uC548\uC5D0 \uAC78\uB7EC\uB0C5\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC640 \uD3EC\uC2A4 \uAE08\uC561\uC774 \uC5B4\uAE0B\uB098\uB294 \uACB0\uC81C\uAC00 \uC788\uB294\uC9C0 \uC601\uC218\uC99D\uACFC \uC815\uC0B0\uC11C\uB97C \uB300\uC870\uD569\uB2C8\uB2E4.", "\uC8FC\uBC29 \uD504\uB9B0\uD130 \uCD9C\uB825\uC774 \uBC00\uB9AC\uAC70\uB098 \uBE60\uC9C0\uB294 \uC2DC\uAC04\uB300\uAC00 \uC788\uB294\uC9C0 \uD53C\uD06C \uB54C \uC9C0\uCF1C\uBD05\uB2C8\uB2E4.", "\uC9C1\uC6D0\uB9C8\uB2E4 \uCDE8\uC18C \uCC98\uB9AC \uBC29\uBC95\uC774 \uB2EC\uB77C\uC9C0\uC9C0 \uC54A\uB3C4\uB85D \uCCAB \uC8FC\uC5D0 \uD55C \uBC88 \uB354 \uB9DE\uCDA5\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC8FC\uBB38\uC774 \uD3EC\uC2A4\uC5D0 \uB4E4\uC5B4\uC624\uB294 \uB9E4\uC7A5\uC740 \uC571 \uC8FC\uBB38\uACFC \uD3EC\uC2A4 \uC8FC\uBB38\uC774 \uB450 \uBC88 \uCC0D\uD788\uC9C0 \uC54A\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC124\uC815\uC744 \uBC14\uAFB8\uACE0 \uC2F6\uC740 \uD56D\uBAA9\uC740 \uCCAB \uC8FC \uC548\uC5D0 \uBAA8\uC544\uC11C \uD55C \uBC88\uC5D0 \uC694\uCCAD\uD558\uB294 \uD3B8\uC774 \uBE60\uB985\uB2C8\uB2E4.", "\uCCAB \uC8FC \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB97C \uB0A0\uC9DC\uBCC4\uB85C \uBAA8\uC544 \uB450\uBA74 \uCE74\uB4DC \uB9E4\uCD9C\uACFC \uD604\uAE08 \uB9E4\uCD9C \uBE44\uC728\uC774 \uBCF4\uC5EC \uB2E4\uC74C \uB2EC \uC6B4\uC601 \uACC4\uD68D\uC5D0 \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58\uAC00 \uB2A6\uC5B4\uC9C0\uB294 \uC774\uC720\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uBA54\uB274 \uC790\uB8CC\uAC00 \uC900\uBE44\uB418\uC9C0 \uC54A\uC544 \uC785\uB825\uC774 \uBC00\uB9AC\uB294 \uACBD\uC6B0\uAC00 \uAC00\uC7A5 \uD754\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uB05D\uB098\uC9C0 \uC54A\uC544 \uACB0\uC81C \uD14C\uC2A4\uD2B8\uB97C \uBABB \uD558\uB294 \uACBD\uC6B0\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uC778\uD130\uB137 \uD68C\uC120 \uAC1C\uD1B5\uC774 \uB2A6\uC73C\uBA74 \uD504\uB85C\uADF8\uB7A8 \uC778\uC99D\uACFC \uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774 \uC548 \uB429\uB2C8\uB2E4.", "\uAE30\uC0AC \uBC29\uBB38 \uC77C\uC815\uC740 \uC9C0\uC5ED\uACFC \uBC30\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAC1C\uC5C5\uC77C\uC5D0 \uB9DE\uCD94\uB824\uBA74 \uC124\uCE58\uC77C\uC744 \uAC1C\uC5C5 \uBA70\uCE60 \uC804\uC73C\uB85C \uC7A1\uC544 \uC9C1\uC6D0 \uAD50\uC721 \uC2DC\uAC04\uC744 \uB0A8\uACA8 \uB461\uB2C8\uB2E4.", "\uC124\uCE58\uC77C\uACFC \uAC1C\uC5C5\uC77C \uC0AC\uC774\uC5D0 \uC9C1\uC6D0\uC774 \uAC00\uC0C1 \uC8FC\uBB38\uC73C\uB85C \uC5F0\uC2B5\uD560 \uC2DC\uAC04\uC744 \uD558\uB8E8 \uC774\uC0C1 \uB450\uBA74 \uAC1C\uC5C5 \uCCAB\uB0A0 \uC904\uC774 \uB35C \uBC00\uB9BD\uB2C8\uB2E4.", "\uC124\uCE58 \uC77C\uC815\uC740 \uAE30\uC0AC \uBC30\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uD76C\uB9DD \uB0A0\uC9DC\uB97C \uB450\uC138 \uAC1C \uC8FC\uBA74 \uC7A1\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uAE30\uC0AC\uAC00 \uB5A0\uB098\uAE30 \uC804\uC5D0 \uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uB85C \uC2E4\uC81C \uC804\uD654\uAC00 \uC5F0\uACB0\uB418\uB294\uC9C0 \uD55C \uBC88 \uAC78\uC5B4 \uBCF4\uBA74 \uB4A4\uC5D0 \uB2F9\uD669\uD560 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC124\uCE58 \uB2F9\uC77C \uC124\uC815\uAC12\uACFC \uB2F4\uB2F9 \uAE30\uC0AC \uC5F0\uB77D\uCC98\uB97C \uC801\uC5B4 \uBCF4\uAD00\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uC124\uCE58 \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD504\uB85C\uADF8\uB7A8\uC744 \uACE0\uB974\uACE0 \uBA54\uB274\xB7\uC88C\uC11D \uC790\uB8CC\uB97C \uB118\uAE41\uB2C8\uB2E4.", "\uAE30\uC0AC\uAC00 \uAE30\uAE30\uB97C \uC124\uCE58\uD558\uACE0 \uBA54\uB274\uB97C \uC785\uB825\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\xB7\uD504\uB9B0\uD130\xB7\uB3C8\uD1B5\uC744 \uC5F0\uACB0\uD558\uACE0 \uC8FC\uBB38 \uD55C \uBC14\uD034\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uACC4\uC815\uACFC \uAD8C\uD55C\uC744 \uB9CC\uB4E4\uACE0 \uCDE8\uC18C\xB7\uB9C8\uAC10\uC744 \uC2DC\uC5F0\uD569\uB2C8\uB2E4.", "\uCCAB \uC8FC \uB3D9\uC548 \uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uB9C8\uAC10 \uC790\uB8CC\uB97C \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC124\uCE58 \uC804 \uC900\uBE44 \uC790\uB8CC", "head": ["\uC790\uB8CC", "\uB0B4\uC6A9", "\uC4F0\uC774\uB294 \uACF3"], "rows": [["\uBA54\uB274\uD45C", "\uC774\uB984\xB7\uAC00\uACA9\xB7\uC635\uC158\xB7\uBD84\uB958", "\uD504\uB85C\uADF8\uB7A8 \uC785\uB825"], ["\uC88C\uC11D \uBC30\uCE58\uB3C4", "\uD14C\uC774\uBE14 \uBC88\uD638\xB7\uAD6C\uC5ED", "\uC8FC\uBB38 \uD654\uBA74"], ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uBAA8\uB378\uBA85", "\uC5F0\uB3D9 \uAC00\uB2A5 \uC5EC\uBD80", "\uACB0\uC81C \uC5F0\uACB0"], ["\uC0AC\uC5C5\uC790 \uC815\uBCF4", "\uC0C1\uD638\xB7\uBC88\uD638\xB7\uC8FC\uC18C", "\uC601\uC218\uC99D \uD45C\uAE30"], ["\uC9C1\uC6D0 \uBA85\uB2E8", "\uAD8C\uD55C \uAD6C\uBD84", "\uACC4\uC815 \uC124\uC815"]] }, "faq": [["\uC124\uCE58\uC5D0 \uD558\uB8E8\uBA74 \uB418\uB098\uC694?", "\uBA54\uB274\uAC00 \uC815\uB9AC\uB3FC \uC788\uC73C\uBA74 \uAE30\uAE30 \uC124\uCE58\uC640 \uC5F0\uACB0\uC740 \uD558\uB8E8 \uC548\uC5D0 \uB05D\uB098\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uBA54\uB274\uAC00 \uB9CE\uAC70\uB098 \uC635\uC158\uC774 \uBCF5\uC7A1\uD558\uBA74 \uC785\uB825 \uC2DC\uAC04\uC774 \uB354 \uAC78\uB9BD\uB2C8\uB2E4."], ["\uAE30\uC874 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uADF8\uB300\uB85C \uC368\uB3C4 \uB418\uB098\uC694?", "\uC5F0\uB3D9\uB418\uB294 \uBAA8\uB378\uC774\uBA74 \uADF8\uB300\uB85C \uC501\uB2C8\uB2E4. \uC811\uC218 \uB54C \uBAA8\uB378\uBA85\uC744 \uC54C\uB824 \uC8FC\uBA74 \uC5F0\uB3D9 \uAC00\uB2A5 \uC5EC\uBD80\uB97C \uD655\uC778\uD574 \uC90D\uB2C8\uB2E4."], ["\uBA54\uB274\uB97C \uB098\uC911\uC5D0 \uBC14\uAFB8\uB824\uBA74 \uAE30\uC0AC\uB97C \uBD88\uB7EC\uC57C \uD558\uB098\uC694?", "\uB300\uBD80\uBD84 \uB9E4\uC7A5\uC5D0\uC11C \uC9C1\uC811 \uBC14\uAFC0 \uC218 \uC788\uACE0, \uC6D0\uACA9\uC73C\uB85C \uB3C4\uC640\uC8FC\uB294 \uACBD\uC6B0\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uBC29\uBC95\uC740 \uC124\uCE58 \uB2F9\uC77C \uBC30\uC6CC \uB461\uB2C8\uB2E4. \uBA54\uB274 \uC218\uC815 \uBC29\uBC95\uC744 \uC9C1\uC6D0\uC5D0\uAC8C\uB3C4 \uC54C\uB824 \uB450\uBA74 \uC0AC\uC7A5\uC774 \uC790\uB9AC\uB97C \uBE44\uC6CC\uB3C4 \uAC00\uACA9 \uBCC0\uACBD\uC774 \uB429\uB2C8\uB2E4."], ["\uD3EC\uC2A4\uAE30 \uC124\uCE58\uC640 \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uB97C \uAC19\uC774 \uD558\uB098\uC694?", "\uAC19\uC740 \uB0A0 \uAC19\uC774 \uD558\uB294 \uAC83\uC774 \uC5F0\uACB0 \uD14C\uC2A4\uD2B8\uC5D0 \uD3B8\uD569\uB2C8\uB2E4. \uB530\uB85C \uD558\uBA74 \uB450 \uBC88\uC9F8 \uC124\uCE58 \uB54C \uC5F0\uB3D9 \uC791\uC5C5\uC774 \uCD94\uAC00\uB429\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58\uBE44\uC6A9", "\uD3EC\uC2A4\uAE30\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC5F0\uB3D9", "\uD3EC\uC2A4\uAE30\uC784\uB300"], "posts": ["/post/install-day-prep/"], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uC124\uCE58\uBE44\uC6A9", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uC124\uCE58\uBE44\uC6A9", "title": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uAD6C\uC131\uB418\uB098\uC694? \u2014 \uAE30\uAE30\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uC8FC\uBCC0\uAE30\uAE30\uB85C \uB098\uB220 \uBCF4\uAE30", "desc": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uBE44\uC6A9\uC774 \uBCF8\uCCB4 \uAE30\uAE30\uAC12, \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC, \uD504\uB9B0\uD130\xB7\uB3C8\uD1B5\xB7\uBC14\uCF54\uB4DC \uC2A4\uCE90\uB108 \uAC19\uC740 \uC8FC\uBCC0\uAE30\uAE30, \uC124\uCE58 \uCD9C\uC7A5\uBE44\uB85C \uB098\uB258\uB294 \uAD6C\uC870\uC640, \uB9E4\uC7A5 \uD615\uD0DC\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uB294 \uD56D\uBAA9, \uACAC\uC801\uC11C\uC5D0\uC11C \uD655\uC778\uD560 \uC810\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD3EC\uC2A4\uAE30 \uC124\uCE58\uBE44\uC6A9\uC740 \uBCF8\uCCB4 \uAE30\uAE30\uAC12, \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uBE44\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC, \uC8FC\uBCC0\uAE30\uAE30, \uC124\uCE58 \uCD9C\uC7A5\uBE44 \uB124 \uAC00\uC9C0\uB85C \uB098\uB258\uACE0 \uAE08\uC561\uC740 \uAD6C\uC131\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC838 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uACFC \uB2EC\uB9AC \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uACC4\uC18D \uB098\uAC00\uB294 \uD56D\uBAA9\uC774\uB77C\uB294 \uC810\uC774 \uB2E4\uB985\uB2C8\uB2E4.", "sections": [{ "h": "\uBE44\uC6A9 \uD56D\uBAA9\uC5D0\uB294 \uBB34\uC5C7\uC774 \uC788\uB098\uC694?", "p": ["\uBCF8\uCCB4\uB294 \uD654\uBA74\uACFC \uBCF8\uCCB4\uAC00 \uD569\uCCD0\uC9C4 \uC77C\uCCB4\uD615\uACFC \uD0DC\uBE14\uB9BF\uD615\uC774 \uC788\uACE0, \uAE30\uAE30\uAC12\uC774 \uC11C\uB85C \uB2E4\uB985\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8\uC740 \uC124\uCE58\uBE44\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uB530\uB85C \uC788\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uACE0, \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uC6D0\uACA9 \uC9C0\uC6D0\uC774 \uD3EC\uD568\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uD504\uB9B0\uD130, \uC8FC\uBC29 \uD504\uB9B0\uD130, \uB3C8\uD1B5, \uBC14\uCF54\uB4DC \uC2A4\uCE90\uB108, \uACE0\uAC1D\uC6A9 \uD654\uBA74\uC740 \uAC01\uAC01 \uBCC4\uB3C4 \uD56D\uBAA9\uC785\uB2C8\uB2E4.", "\uC124\uCE58 \uCD9C\uC7A5\uBE44\uB294 \uAE30\uAE30 \uC124\uCE58\uC640 \uBA54\uB274 \uC785\uB825, \uC5F0\uACB0 \uD14C\uC2A4\uD2B8 \uC791\uC5C5\uC758 \uAC12\uC73C\uB85C, \uBA54\uB274 \uC785\uB825 \uB300\uD589\uC774 \uD3EC\uD568\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB294 \uD3EC\uC2A4\uAE30\uC640 \uBCC4\uB3C4 \uAE30\uAE30\uC774\uBBC0\uB85C \uD568\uAED8 \uC124\uCE58\uD574\uB3C4 \uD56D\uBAA9\uC740 \uB098\uB269\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uD56D\uBAA9\uC774 \uD569\uCCD0\uC838 \uC788\uC73C\uBA74 \uB098\uC911\uC5D0 \uC8FC\uBCC0\uAE30\uAE30 \uD558\uB098\uB97C \uBC14\uAFC0 \uB54C \uAC12\uC744 \uC54C \uC218 \uC5C6\uC73C\uB2C8 \uB098\uB220 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC18C\uBAA8\uD488(\uC601\uC218\uC99D \uC6A9\uC9C0)\uC740 \uC124\uCE58\uBE44\uC6A9\uC774 \uC544\uB2C8\uB77C \uC6B4\uC601\uBE44\uC774\uBBC0\uB85C \uB530\uB85C \uC0DD\uAC01\uD569\uB2C8\uB2E4.", "\uACE0\uAC1D\uC6A9 \uD654\uBA74\uC774\uB098 \uAC04\uD3B8\uACB0\uC81C \uB9AC\uB354\uAE30\uB294 \uC120\uD0DD \uD56D\uBAA9\uC774\uBBC0\uB85C \uC190\uB2D8 \uACB0\uC81C \uBC29\uC2DD\uC744 \uBCF4\uACE0 \uB123\uC744\uC9C0 \uC815\uD569\uB2C8\uB2E4."] }, { "h": "\uB9E4\uC7A5 \uD615\uD0DC\uC5D0 \uB530\uB77C \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC2DD\uB2F9\uC740 \uC8FC\uBC29 \uD504\uB9B0\uD130\uC640 \uD14C\uC774\uBE14 \uAD00\uB9AC \uAE30\uB2A5\uC774 \uD544\uC694\uD574 \uC18C\uB9E4\uC810\uBCF4\uB2E4 \uD56D\uBAA9\uC774 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uC18C\uB9E4\uC810\uC740 \uBC14\uCF54\uB4DC \uC2A4\uCE90\uB108\uC640 \uC7AC\uACE0 \uAE30\uB2A5\uC774 \uC911\uC694\uD558\uACE0 \uC8FC\uBC29 \uD504\uB9B0\uD130\uB294 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uCE74\uD398\uCC98\uB7FC \uD68C\uC804\uC774 \uBE60\uB978 \uB9E4\uC7A5\uC740 \uACE0\uAC1D\uC6A9 \uD654\uBA74\uC774\uB098 \uAC04\uD3B8\uACB0\uC81C \uC5F0\uB3D9\uC774 \uB4E4\uC5B4\uAC00\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uBC30\uB2EC \uB9E4\uC7A5\uC740 \uBC30\uB2EC \uC571 \uC8FC\uBB38 \uC5F0\uB3D9 \uAE30\uB2A5\uC774 \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uC6B4\uC601\uD558\uBA74 \uBCF8\uC0AC \uD1B5\uD569 \uAD00\uB9AC \uAE30\uB2A5\uC774 \uC6D4 \uC0AC\uC6A9\uB8CC\uB97C \uBC14\uAFB8\uB294 \uD56D\uBAA9\uC785\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uADDC\uBAA8\uAC00 \uD06C\uBA74 \uD3EC\uC2A4\uAE30\uB97C \uB450 \uB300 \uC774\uC0C1 \uB450\uC5B4 \uAE30\uAE30\uAC12\uC774 \uB300\uC218\uB9CC\uD07C \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uD504\uB79C\uCC28\uC774\uC988 \uB9E4\uC7A5\uC740 \uBCF8\uC0AC\uAC00 \uC815\uD55C \uD504\uB85C\uADF8\uB7A8\uACFC \uAD6C\uC131\uC774 \uC788\uC5B4 \uD56D\uBAA9\uC774 \uACE0\uC815\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uBCF8\uC0AC \uC9C0\uCE68\uC744 \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC18C\uB9E4\uC810\uC740 \uBC14\uCF54\uB4DC \uC2A4\uCE90\uB108 \uC885\uB958(\uC720\uC120\xB7\uBB34\uC120\xB72D)\uC5D0 \uB530\uB77C \uAC12\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC0C1\uD488 \uBC14\uCF54\uB4DC \uD615\uD0DC\uB97C \uC54C\uB824 \uC8FC\uACE0 \uACE0\uB985\uB2C8\uB2E4."] }, { "h": "\uC784\uB300\uC640 \uAD6C\uB9E4\uC5D0\uC11C \uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uC784\uB300\uB294 \uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC774 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uBC14\uB00C\uACE0 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uC640 \uD569\uCCD0 \uCCAD\uAD6C\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB294 \uBCF8\uCCB4\uB97C \uCC98\uC74C\uC5D0 \uCE58\uB974\uACE0 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uB9CC \uB0A8\uC2B5\uB2C8\uB2E4.", "\uC8FC\uBCC0\uAE30\uAE30\uB294 \uC784\uB300 \uC57D\uC815\uC5D0 \uD3EC\uD568\uB418\uAE30\uB3C4 \uD558\uACE0 \uAD6C\uB9E4\uB9CC \uB418\uAE30\uB3C4 \uD558\uBBC0\uB85C \uD56D\uBAA9\uB9C8\uB2E4 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uACFC \uD574\uC9C0 \uC870\uAC74\uC740 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uB418\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uC77D\uC2B5\uB2C8\uB2E4.", "\uC6B4\uC601 \uAE30\uAC04\uC774 \uC9E7\uC73C\uBA74 \uC784\uB300, \uAE38\uBA74 \uAD6C\uB9E4\uAC00 \uCD1D\uBE44\uC6A9\uC5D0\uC11C \uC720\uB9AC\uD55C \uACBD\uC6B0\uAC00 \uB9CE\uC9C0\uB9CC \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uC591\uCABD \uBAA8\uB450 \uAC19\uC2B5\uB2C8\uB2E4.", "\uC784\uB300 \uC57D\uC815\uC5D0 \uC8FC\uBCC0\uAE30\uAE30\uAC00 \uD3EC\uD568\uB418\uBA74 \uACE0\uC7A5 \uAD50\uCCB4\uB3C4 \uD3EC\uD568\uC778\uC9C0 \uD488\uBAA9\uBCC4\uB85C \uBB3B\uACE0, \uAD6C\uB9E4 \uC8FC\uBCC0\uAE30\uAE30\uB294 \uBCF4\uC99D \uAE30\uAC04\uC744 \uB530\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC784\uB300 \uC57D\uC815\uC758 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB97C \uD3EC\uD568\uD558\uB294\uC9C0 \uC544\uB2CC\uC9C0\uC5D0 \uB530\uB77C \uC6D4 \uCCAD\uAD6C\uAC00 \uD06C\uAC8C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uD56D\uBAA9 \uBD84\uB9AC\uB97C \uAF2D \uC694\uCCAD\uD569\uB2C8\uB2E4."] }, { "h": "\uACAC\uC801\uC744 \uBE44\uAD50\uD560 \uB54C \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uBCF8\uCCB4 \uBAA8\uB378\uBA85\uACFC \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uAC19\uC740 \uC870\uAC74\uB07C\uB9AC \uBE44\uAD50\uB429\uB2C8\uB2E4.", "\uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uC6D0\uACA9 \uC9C0\uC6D0, \uC5C5\uB370\uC774\uD2B8, \uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774 \uD3EC\uD568\uC778\uC9C0 \uD56D\uBAA9\uBCC4\uB85C \uD45C\uC2DC\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uC785\uB825 \uB300\uD589\uC774 \uD3EC\uD568\uC778\uC9C0, \uB9E4\uC7A5\uC774 \uC9C1\uC811 \uD558\uB294\uC9C0\uC5D0 \uB530\uB77C \uC124\uCE58\uBE44\uAC00 \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uAE30\uAE30 \uC81C\uACF5 \uC870\uAC74\uACFC \uBE44\uC6A9\uC744 \uC57D\uC815\uC11C\uC5D0\uC11C \uBD05\uB2C8\uB2E4.", "\uC815\uD655\uD55C \uAE08\uC561\uC740 \uAD6C\uC131\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uC9C0\uB9CC, \uD56D\uBAA9 \uAD6C\uC870\uB97C \uC54C\uACE0 \uAC00\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC774 \uBE44\uC2FC\uC9C0 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uB97C \uBC1B\uC740 \uB0A0\uC9DC\uC640 \uC720\uD6A8 \uAE30\uAC04\uC744 \uC801\uC5B4 \uB450\uACE0, \uC870\uAC74\uC774 \uBC14\uB00C\uBA74 \uBC14\uB010 \uACAC\uC801\uC11C\uB97C \uB2E4\uC2DC \uBC1B\uC544 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uCD9C\uC7A5\uBE44\uC640 \uBA54\uB274 \uC785\uB825 \uB300\uD589\uBE44\uB294 \uAC19\uC740 \uC791\uC5C5\uCC98\uB7FC \uBCF4\uC5EC\uB3C4 \uB530\uB85C \uCCAD\uAD6C\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uB458\uC744 \uAD6C\uBD84\uD574 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uCCAB \uCCAD\uAD6C\uC11C\uB97C \uACAC\uC801\uC11C\uC640 \uD56D\uBAA9\uBCC4\uB85C \uB300\uC870\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uACAC\uC801\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uBC1B\uB098\uC694?", "items": ["\uB9E4\uC7A5 \uD615\uD0DC\uC640 \uD544\uC694\uD55C \uAE30\uB2A5(\uC8FC\uBC29 \uCD9C\uB825\xB7\uC7AC\uACE0\xB7\uBC30\uB2EC \uC5F0\uB3D9)\uC744 \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uBCF8\uCCB4\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uC8FC\uBCC0\uAE30\uAE30\xB7\uCD9C\uC7A5\uBE44\uB85C \uB098\uB25C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4 \uC870\uAC74\uC73C\uB85C \uCD1D\uBE44\uC6A9\uC744 \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uB85C \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB41C \uC11C\uBE44\uC2A4\uB97C \uD655\uC778\uD558\uACE0 \uACB0\uC815\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uBAA8\uB378\uBA85\uACFC \uD56D\uBAA9\uBCC4 \uAE08\uC561\uC774 \uC801\uD614\uB294\uC9C0 \uC11C\uBA85 \uC804\uC5D0 \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD3EC\uC2A4\uAE30 \uBE44\uC6A9 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "1\uD68C \uBE44\uC6A9", "\uC6D4 \uBE44\uC6A9"], "rows": [["\uBCF8\uCCB4", "\uAD6C\uB9E4 \uC2DC", "\uC784\uB300 \uC2DC"], ["\uD504\uB85C\uADF8\uB7A8", "\uC124\uCE58\uBE44", "\uC0AC\uC6A9\uB8CC"], ["\uC8FC\uBCC0\uAE30\uAE30", "\uAE30\uAE30\uAC12", "\uC5C6\uC74C(\uC784\uB300 \uC81C\uC678)"], ["\uC124\uCE58 \uCD9C\uC7A5\uBE44", "\uC791\uC5C5\uBE44", "\uC5C6\uC74C"], ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "\uBCC4\uB3C4 \uD56D\uBAA9", "\uBCC4\uB3C4 \uD56D\uBAA9"]] }, "faq": [["\uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uB294 \uAF2D \uB0B4\uC57C \uD558\uB098\uC694?", "\uB300\uBD80\uBD84 \uD504\uB85C\uADF8\uB7A8\uC774 \uC6D4 \uC0AC\uC6A9\uB8CC \uBC29\uC2DD\uC785\uB2C8\uB2E4. \uC0AC\uC6A9\uB8CC \uC5C6\uB294 \uD504\uB85C\uADF8\uB7A8\uC740 \uC6D0\uACA9 \uC9C0\uC6D0\uACFC \uC5C5\uB370\uC774\uD2B8\uAC00 \uBE60\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC870\uAC74\uC744 \uBD05\uB2C8\uB2E4."], ["\uD0DC\uBE14\uB9BF \uD3EC\uC2A4\uB294 \uB354 \uC2FC\uAC00\uC694?", "\uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC740 \uB0AE\uC740 \uD3B8\uC774\uC9C0\uB9CC \uD504\uB9B0\uD130\uC640 \uB3C8\uD1B5\uC740 \uB611\uAC19\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uCD1D\uBE44\uC6A9\uC740 \uAD6C\uC131\uC73C\uB85C \uBE44\uAD50\uD569\uB2C8\uB2E4."], ["\uC911\uACE0 \uD3EC\uC2A4\uAE30\uB97C \uC0AC\uBA74 \uC124\uCE58\uBE44\uC6A9\uC774 \uC904\uC5B4\uB4DC\uB098\uC694?", "\uBCF8\uCCB4 \uAC12\uC740 \uC904\uC9C0\uB9CC \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uBE44\uC640 \uC0AC\uC6A9\uB8CC\uB294 \uAC19\uC2B5\uB2C8\uB2E4. \uAD6C\uD615 \uAE30\uAE30\uB294 \uD504\uB85C\uADF8\uB7A8\uC774 \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAD6C\uD615 \uAE30\uAE30\uB294 \uC6B4\uC601\uCCB4\uC81C\uAC00 \uB9DE\uC9C0 \uC54A\uC544 \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58 \uC790\uCCB4\uAC00 \uC548 \uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uBAA8\uB378\uBA85\uC73C\uB85C \uC9C0\uC6D0 \uC5EC\uBD80\uB97C \uBA3C\uC800 \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uC124\uCE58\uBE44\uC6A9\uC5D0 \uBA54\uB274 \uC785\uB825\uC774 \uD3EC\uD568\uB418\uB098\uC694?", "\uC5C5\uCCB4\uB9C8\uB2E4 \uB2E4\uB985\uB2C8\uB2E4. \uD3EC\uD568 \uC5EC\uBD80\uC640 \uBA54\uB274 \uC218 \uC81C\uD55C\uC744 \uACAC\uC801\uC11C\uC5D0 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58", "\uD3EC\uC2A4\uAE30\uC784\uB300", "\uD3EC\uC2A4\uAE30\uD504\uB85C\uADF8\uB7A8\uC6D4\uC0AC\uC6A9\uB8CC"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uC784\uB300", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uC784\uB300", "title": "\uD3EC\uC2A4\uAE30 \uC784\uB300\uB294 \uC5B4\uB5A4 \uC870\uAC74\uC73C\uB85C \uD558\uB098\uC694? \u2014 \uC57D\uC815 \uAE30\uAC04\uACFC \uD3EC\uD568 \uD56D\uBAA9 \uC77D\uB294 \uBC95", "desc": "\uD3EC\uC2A4\uAE30 \uC784\uB300\uC758 \uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uBB34\uC5C7\uC774 \uD3EC\uD568\uB418\uB294\uC9C0, \uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74, \uACE0\uC7A5 \uAD50\uCCB4\uC640 \uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8 \uC870\uAC74, \uC57D\uC815 \uC885\uB8CC \uB4A4 \uAE30\uAE30 \uCC98\uB9AC \uBC29\uC2DD\uC744 \uC815\uB9AC\uD558\uACE0 \uC784\uB300\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uACFC \uAD6C\uB9E4\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC744 \uB098\uB234\uC2B5\uB2C8\uB2E4.", "answer": "\uD3EC\uC2A4\uAE30 \uC784\uB300\uB294 \uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC744 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uB098\uB220 \uB0B4\uB294 \uC57D\uC815\uC774\uBA70, \uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uC640 \uC8FC\uBCC0\uAE30\uAE30, \uACE0\uC7A5 \uAD50\uCCB4\uAC00 \uD3EC\uD568\uC778\uC9C0\uAC00 \uC870\uAC74\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uAE00\uB85C \uC788\uB294 \uC81C\uC548\uB9CC \uBE44\uAD50 \uB300\uC0C1\uC5D0 \uC62C\uB9BD\uB2C8\uB2E4.", "sections": [{ "h": "\uC6D4 \uC774\uC6A9\uB8CC\uC5D0\uB294 \uBB34\uC5C7\uC774 \uD3EC\uD568\uB418\uB098\uC694?", "p": ["\uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC774 \uAE30\uBCF8\uC774\uACE0, \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uD569\uCCD0\uC838 \uC788\uB294\uC9C0 \uB530\uB85C\uC778\uC9C0 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2E4\uB985\uB2C8\uB2E4.", "\uD504\uB9B0\uD130\uC640 \uB3C8\uD1B5 \uAC19\uC740 \uC8FC\uBCC0\uAE30\uAE30\uAC00 \uD3EC\uD568\uC774\uBA74 \uC57D\uC815\uC11C\uC5D0 \uD488\uBAA9\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uAE30\uAE30\uB97C \uBCF4\uB0B4 \uC8FC\uB294 \uC870\uAC74\uC774 \uD3EC\uD568\uC778\uC9C0, \uBC29\uBB38 \uC218\uB9AC\uAC00 \uC720\uC0C1\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8\uC640 \uC6D0\uACA9 \uC9C0\uC6D0\uC774 \uC6D4 \uC774\uC6A9\uB8CC \uC548\uC5D0 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB294 \uBCF4\uD1B5 \uBCC4\uB3C4 \uC57D\uC815\uC774\uBBC0\uB85C \uD3EC\uC2A4 \uC784\uB300\uB8CC\uC5D0 \uB4E4\uC5B4 \uC788\uB2E4\uACE0 \uC0DD\uAC01\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC6A9\uC9C0 \uAC19\uC740 \uC18C\uBAA8\uD488\uC740 \uD3EC\uD568\uB418\uC9C0 \uC54A\uB294 \uAC83\uC774 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4.", "\uD3EC\uD568 \uD56D\uBAA9\uC774 \uB9CE\uC744\uC218\uB85D \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB192\uC73C\uBBC0\uB85C \uB9E4\uC7A5\uC5D0 \uD544\uC694\uD55C \uD56D\uBAA9\uB9CC \uB0A8\uAE41\uB2C8\uB2E4.", "\uD3EC\uD568 \uD56D\uBAA9 \uBAA9\uB85D\uC744 \uC57D\uC815\uC11C \uBCC4\uC9C0\uB85C \uBC1B\uC544 \uB450\uBA74 \uB098\uC911\uC5D0 \uD488\uBAA9\uC774 \uBE60\uC84C\uC744 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815 \uAE30\uAC04\uACFC \uD574\uC9C0 \uC870\uAC74\uC740 \uC5B4\uB5BB\uAC8C \uBCF4\uB098\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04\uC774 \uAE38\uC218\uB85D \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB0AE\uC544\uC9C0\uB294 \uB300\uC2E0 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uBB34\uAC70\uC6CC\uC9D1\uB2C8\uB2E4.", "\uC911\uB3C4 \uD574\uC9C0 \uB54C \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uB418\uB294\uC9C0 \uC57D\uC815\uC11C \uC870\uD56D\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC774 \uB05D\uB09C \uB4A4 \uBC18\uB0A9\uC778\uC9C0, \uC5F0\uC7A5\uC778\uC9C0, \uC18C\uC720\uAD8C\uC774 \uB118\uC5B4\uC624\uB294\uC9C0 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5 \uC870\uD56D\uC774 \uC788\uC73C\uBA74 \uC885\uB8CC \uC804\uC5D0 \uC758\uC0AC\uB97C \uAE00\uB85C \uB0A8\uACA8\uC57C \uC5F0\uC7A5\uC774 \uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774\uB098 \uC774\uC804 \uB54C \uC57D\uC815\uC744 \uC2B9\uACC4\uD560 \uC218 \uC788\uB294\uC9C0\uB3C4 \uC870\uD56D\uC5D0 \uC788\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uC870\uAC74\uACFC \uC704\uC57D \uC0B0\uC815 \uBC29\uC2DD\uC740 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC0AC\uC720\uAC00 \uD3D0\uC5C5\uC778\uC9C0 \uC774\uC804\uC778\uC9C0\uC5D0 \uB530\uB77C \uC870\uAC74\uC774 \uB2E4\uB978 \uC5C5\uCCB4\uB3C4 \uC788\uC5B4 \uC0AC\uC720\uBCC4 \uC870\uD56D\uC744 \uD568\uAED8 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC784\uB300\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uAC1C\uC5C5 \uC790\uAE08\uC774 \uBE60\uB4EF\uD558\uAC70\uB098 \uC6B4\uC601 \uAE30\uAC04\uC774 \uBD88\uD655\uC2E4\uD55C \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uACE0\uC7A5\uC744 \uC9C1\uC811 \uCC98\uB9AC\uD558\uAE30 \uC5B4\uB824\uC6B4 \uB9E4\uC7A5\uC740 \uAD50\uCCB4 \uC870\uAC74\uC774 \uD3EC\uD568\uB41C \uC784\uB300\uAC00 \uD3B8\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8\uACFC \uAE30\uAE30\uB97C \uD55C \uC5C5\uCCB4\uC5D0\uC11C \uAD00\uB9AC\uD558\uAE38 \uC6D0\uD558\uBA74 \uC784\uB300 \uCABD\uC774 \uCC3D\uAD6C\uAC00 \uD558\uB098\uB85C \uBB36\uC785\uB2C8\uB2E4.", "\uBC18\uB300\uB85C \uBA87 \uB144 \uC774\uC0C1 \uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uC6B4\uC601\uD560 \uB9E4\uC7A5\uC740 \uAD6C\uB9E4 \uCABD \uCD1D\uBE44\uC6A9\uC774 \uB0AE\uC544\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uACC4\uC808 \uC601\uC5C5\uC774\uB098 \uD31D\uC5C5 \uB9E4\uC7A5\uC740 \uC9E7\uC740 \uC57D\uC815\uC774 \uAC00\uB2A5\uD55C\uC9C0 \uBA3C\uC800 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD55C \uC5C5\uCCB4\uC5D0\uC11C \uD3EC\uC2A4\uC640 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uAC19\uC774 \uC784\uB300\uD558\uBA74 \uCC3D\uAD6C\uAC00 \uD558\uB098\uAC00 \uB418\uC9C0\uB9CC \uC57D\uC815 \uC885\uB8CC \uC2DC\uC810\uC774 \uAC19\uC740\uC9C0 \uD655\uC778\uD574\uC57C \uD55C \uCABD\uB9CC \uB0A8\uB294 \uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uACC4\uC808 \uC601\uC5C5\uC740 \uBE44\uC218\uAE30 \uB3D9\uC548 \uC0AC\uC6A9\uB8CC\uB9CC \uB0B4\uACE0 \uAE30\uAE30\uB294 \uB450\uB294 \uC870\uAC74\uC774 \uAC00\uB2A5\uD55C\uC9C0\uB3C4 \uBB3C\uC5B4\uBCFC \uB9CC\uD569\uB2C8\uB2E4."] }, { "h": "\uC784\uB300 \uC911 \uBC14\uAFC0 \uC218 \uC788\uB294 \uAC83\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC8FC\uBCC0\uAE30\uAE30 \uCD94\uAC00\uB098 \uD504\uB85C\uADF8\uB7A8 \uAE30\uB2A5 \uCD94\uAC00\uB294 \uC57D\uC815 \uC911\uC5D0\uB3C4 \uAC00\uB2A5\uD558\uC9C0\uB9CC \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uBC14\uB01D\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4\uB294 \uACE0\uC7A5\uC77C \uB54C\uC640 \uB9E4\uC7A5 \uC694\uCCAD\uC77C \uB54C \uC870\uAC74\uC774 \uB2E4\uB974\uBBC0\uB85C \uAD6C\uBD84\uD574\uC11C \uBD05\uB2C8\uB2E4.", "\uC784\uB300\uC5D0\uC11C \uAD6C\uB9E4\uB85C \uC804\uD658\uD558\uB294 \uC870\uAC74\uC774 \uC788\uC73C\uBA74 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC774\uC804 \uB54C \uAE30\uAE30\uB97C \uC62E\uAE30\uB294 \uC791\uC5C5\uC774 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBCC0\uACBD \uC694\uCCAD\uC740 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uBC14\uB010 \uC6D4 \uC774\uC6A9\uB8CC\uB97C \uB2E4\uC2DC \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uBCC0\uACBD \uB4A4 \uCCAB \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uBC14\uB010 \uD56D\uBAA9\uB9CC \uB298\uC5C8\uB294\uC9C0 \uBCF4\uACE0, \uB2E4\uB978 \uD56D\uBAA9\uC774 \uD568\uAED8 \uBC14\uB00C\uC5C8\uC73C\uBA74 \uBC14\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4.", "\uC784\uB300 \uC57D\uC815\uACFC \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uC758 \uC885\uB8CC\uC77C\uC774 \uB2E4\uB974\uBA74 \uD55C\uCABD\uB9CC \uB0A8\uC544 \uBE44\uC6A9\uC774 \uACC4\uC18D \uB098\uAC00\uBBC0\uB85C \uB450 \uB0A0\uC9DC\uB97C \uAC19\uC774 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uC694\uCCAD\uC774 \uB9E4\uC7A5 \uC0AC\uC815\uC774\uBA74 \uC720\uC0C1\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uACE0\uC7A5 \uAD50\uCCB4\uC640 \uAD6C\uBD84\uD574\uC11C \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uAE30\uB2A5\uC744 \uCD94\uAC00\uD55C \uB4A4\uC5D0\uB294 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uBC14\uB010 \uCCAD\uAD6C\uC11C\uAC00 \uCC98\uC74C \uC654\uC744 \uB54C \uCD94\uAC00 \uD56D\uBAA9\uB9CC \uB298\uC5C8\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC774\uC804 \uB54C \uC774\uC124 \uC791\uC5C5\uC774 \uBCC4\uB3C4\uBA74 \uC0C8 \uB9E4\uC7A5\uC758 \uC804\uC6D0\xB7\uD1B5\uC2E0 \uC0C1\uD0DC\uB97C \uBBF8\uB9AC \uC54C\uB824 \uC8FC\uC5B4\uC57C \uCD94\uAC00 \uACF5\uC0AC \uC5EC\uBD80\uAC00 \uC815\uD574\uC9D1\uB2C8\uB2E4.", "\uBCC0\uACBD \uC694\uCCAD\uC774 \uC788\uC73C\uBA74 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uBC14\uB010 \uC6D4 \uC774\uC6A9\uB8CC\uB97C \uB2E4\uC2DC \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uC885\uB8CC \uB2EC\uACFC \uC790\uB3D9 \uC5F0\uC7A5 \uD1B5\uC9C0 \uAE30\uD55C\uC744 \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uC784\uB300 \uACC4\uC57D\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uD544\uC694\uD55C \uAE30\uAE30\uC640 \uAE30\uB2A5\uC744 \uC815\uB9AC\uD574 \uC6D4 \uC774\uC6A9\uB8CC \uD3EC\uD568 \uD56D\uBAA9\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uBCC4 \uC6D4 \uC774\uC6A9\uB8CC\uC640 \uD574\uC9C0 \uC870\uAC74\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uACE0\uC7A5 \uAD50\uCCB4\xB7\uC5C5\uB370\uC774\uD2B8\xB7\uC6D0\uACA9 \uC9C0\uC6D0 \uD3EC\uD568 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uC885\uB8CC \uB4A4 \uAE30\uAE30 \uCC98\uB9AC \uBC29\uC2DD\uC744 \uD655\uC778\uD558\uACE0 \uC11C\uBA85\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C \uC0AC\uBCF8\uACFC \uD3EC\uD568 \uD56D\uBAA9 \uBAA9\uB85D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC784\uB300 \uC870\uAC74 \uD655\uC778\uD45C", "head": ["\uD56D\uBAA9", "\uD655\uC778\uD560 \uAC83", "\uC5C6\uC73C\uBA74"], "rows": [["\uC6D4 \uC774\uC6A9\uB8CC \uD3EC\uD568 \uD56D\uBAA9", "\uAE30\uAE30\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uC8FC\uBCC0\uAE30\uAE30", "\uD488\uBAA9 \uBA85\uC2DC \uC694\uCCAD"], ["\uC57D\uC815 \uAE30\uAC04", "\uAC1C\uC6D4 \uC218\xB7\uC5F0\uC7A5 \uC870\uD56D", "\uC11C\uBA74 \uC694\uCCAD"], ["\uC911\uB3C4 \uD574\uC9C0", "\uC0B0\uC815 \uBC29\uC2DD", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"], ["\uACE0\uC7A5 \uAD50\uCCB4", "\uBB34\uC0C1\xB7\uC720\uC0C1 \uAD6C\uBD84", "\uC57D\uC815\uC11C \uCD94\uAC00 \uC694\uCCAD"], ["\uC885\uB8CC \uB4A4 \uCC98\uB9AC", "\uBC18\uB0A9\xB7\uC5F0\uC7A5\xB7\uC18C\uC720\uAD8C", "\uC11C\uBA74 \uC694\uCCAD"]] }, "faq": [["\uC784\uB300 \uAE30\uAE30\uAC00 \uACE0\uC7A5 \uB098\uBA74 \uB204\uAC00 \uACE0\uCE58\uB098\uC694?", "\uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB77C \uC5C5\uCCB4\uAC00 \uAD50\uCCB4 \uAE30\uAE30\uB97C \uBCF4\uB0B4\uAC70\uB098 \uBC29\uBB38 \uC218\uB9AC\uD569\uB2C8\uB2E4. \uBB34\uC0C1\uC778\uC9C0 \uC720\uC0C1\uC778\uC9C0 \uC57D\uC815\uC11C\uC5D0\uC11C \uBD05\uB2C8\uB2E4. \uAD50\uCCB4 \uAE30\uAE30\uAC00 \uC624\uAE30\uAE4C\uC9C0 \uC601\uC5C5 \uACF5\uBC31\uC774 \uC0DD\uAE30\uBBC0\uB85C \uAD50\uCCB4 \uAE30\uAC04\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4."], ["\uC57D\uC815 \uC911\uC5D0 \uD3D0\uC5C5\uD558\uBA74 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "\uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uACFC \uBC18\uB0A9 \uC808\uCC28\uB97C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD504\uB85C\uADF8\uB7A8\uB9CC \uBC14\uAFC0 \uC218 \uC788\uB098\uC694?", "\uAE30\uAE30\uC640 \uD504\uB85C\uADF8\uB7A8\uC774 \uBB36\uC778 \uC57D\uC815\uC774\uBA74 \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uBB36\uC784 \uC5EC\uBD80\uB97C \uACC4\uC57D \uC804\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uC784\uB300\uB8CC\uC5D0 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB3C4 \uB4E4\uC5B4\uAC00\uB098\uC694?", "\uBCF4\uD1B5 \uBCC4\uB3C4\uC785\uB2C8\uB2E4. \uD3EC\uD568\uC774\uB77C\uACE0 \uD558\uBA74 \uC57D\uC815\uC11C\uC5D0 \uD488\uBAA9\uC73C\uB85C \uC801\uD600 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4. \uD3EC\uD568\uC774\uB77C\uBA74 \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC57D\uC815 \uAE30\uAC04\uB3C4 \uD3EC\uC2A4\uC640 \uAC19\uC740\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58\uBE44\uC6A9", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC784\uB300\uAD6C\uB9E4", "\uD3EC\uC2A4\uAE30\uD574\uC9C0\uBC18\uB0A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uD504\uB85C\uADF8\uB7A8\uC6D4\uC0AC\uC6A9\uB8CC", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC", "title": "\uD3EC\uC2A4\uAE30 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694? \u2014 \uB9E4\uB2EC \uB0B4\uB294 \uD56D\uBAA9 \uC810\uAC80", "desc": "\uD3EC\uC2A4\uAE30 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB418\uB294 \uC5C5\uB370\uC774\uD2B8, \uC6D0\uACA9 \uC9C0\uC6D0, \uB9E4\uCD9C \uC790\uB8CC \uC800\uC7A5, \uBC30\uB2EC \uC571 \uC5F0\uB3D9 \uAC19\uC740 \uD56D\uBAA9\uACFC \uBCC4\uB3C4\uB85C \uCCAD\uAD6C\uB418\uB294 \uD56D\uBAA9, \uC0AC\uC6A9\uB8CC\uAC00 \uC624\uB974\uB294 \uC870\uAC74, \uC4F0\uC9C0 \uC54A\uB294 \uAE30\uB2A5\uC744 \uBE7C\uB294 \uBC29\uBC95\uACFC \uCCAD\uAD6C\uC11C\uB97C \uC810\uAC80\uD558\uB294 \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uB294 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uAD8C\uC5D0 \uC5C5\uB370\uC774\uD2B8, \uC6D0\uACA9 \uC9C0\uC6D0, \uB9E4\uCD9C \uC790\uB8CC \uC800\uC7A5\uC774 \uBB36\uC778 \uAC12\uC774\uBA70, \uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774\uB098 \uD1B5\uD569 \uAD00\uB9AC \uAC19\uC740 \uAE30\uB2A5\uC740 \uBCC4\uB3C4 \uD56D\uBAA9\uC73C\uB85C \uB354\uD574\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uC5B4\uB290 \uAE30\uB2A5\uC774 \uAE30\uBCF8\uC774\uACE0 \uC5B4\uB290 \uAE30\uB2A5\uC774 \uCD94\uAC00\uC778\uC9C0 \uD56D\uBAA9\uD45C\uB85C \uBC1B\uC544 \uB450\uBA74 \uB9E4\uB2EC \uB098\uAC00\uB294 \uB3C8\uC758 \uAD6C\uC870\uAC00 \uBCF4\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uAE30\uBCF8 \uC0AC\uC6A9\uB8CC\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uD504\uB85C\uADF8\uB7A8\uC744 \uC4F0\uB294 \uAD8C\uB9AC \uC790\uCCB4\uC640 \uC815\uAE30 \uC5C5\uB370\uC774\uD2B8\uAC00 \uAE30\uBCF8\uC785\uB2C8\uB2E4.", "\uC6D0\uACA9 \uC9C0\uC6D0\uC740 \uB300\uBD80\uBD84 \uD3EC\uD568\uB418\uC9C0\uB9CC \uBC29\uBB38 \uC9C0\uC6D0\uC740 \uBCC4\uB3C4\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uB9E4\uCD9C \uC790\uB8CC\uB97C \uC11C\uBC84\uC5D0 \uC800\uC7A5\uD574 \uB2E4\uB978 \uAE30\uAE30\uC5D0\uC11C \uBCF4\uB294 \uAE30\uB2A5\uC774 \uD3EC\uD568\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC591\uC2DD \uBCC0\uACBD, \uBA54\uB274 \uC218\uC815 \uAC19\uC740 \uC124\uC815 \uBCC0\uACBD\uC774 \uAE30\uBCF8\uC778\uC9C0 \uC720\uC0C1\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC138\uBB34 \uC790\uB8CC \uB0B4\uBCF4\uB0B4\uAE30 \uAE30\uB2A5\uC774 \uD3EC\uD568\uC774\uBA74 \uC138\uBB34 \uB300\uB9AC\uC778\uC5D0\uAC8C \uC790\uB8CC\uB97C \uB118\uAE30\uAE30 \uD3B8\uD569\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC0AC\uC6A9\uB8CC\uC758 \uBC94\uC704\uB294 \uD504\uB85C\uADF8\uB7A8\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC0AC\uC6A9\uB8CC\uAC00 \uAE30\uAE30 \uC784\uB300\uB8CC\uC640 \uD569\uCCD0\uC838 \uCCAD\uAD6C\uB418\uBA74 \uBD84\uB9AC\uB41C \uAE08\uC561\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC0AC\uC6A9\uB8CC\uB9CC \uB0B4\uB294 \uB9E4\uC7A5\uACFC \uCD94\uAC00 \uD56D\uBAA9\uC774 \uC5EC\uB7FF \uBD99\uC740 \uB9E4\uC7A5\uC740 \uC6D4 \uCCAD\uAD6C\uC11C\uAC00 \uB450 \uBC30 \uB118\uAC8C \uCC28\uC774 \uB098\uAE30\uB3C4 \uD558\uBBC0\uB85C \uD56D\uBAA9\uD45C\uB97C \uAF2D \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC5C5\uCCB4\uAC00 \uBC14\uB00C\uAC70\uB098 \uD569\uBCD1\uB418\uBA74 \uC0AC\uC6A9\uB8CC \uCCB4\uACC4\uAC00 \uBC14\uB014 \uC218 \uC788\uC73C\uB2C8 \uD1B5\uC9C0\uBB38\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC6D4 \uC0AC\uC6A9\uB8CC \uCCAD\uAD6C\uC77C\uACFC \uAE30\uAE30 \uC784\uB300\uB8CC \uCCAD\uAD6C\uC77C\uC774 \uB2E4\uB974\uBA74 \uB450 \uCCAD\uAD6C\uC11C\uB97C \uD55C \uB2EC \uB2E8\uC704\uB85C \uB9DE\uCDB0 \uC801\uC5B4\uC57C \uC6D4 \uBE44\uC6A9\uC774 \uC815\uD655\uD788 \uBCF4\uC785\uB2C8\uB2E4."] }, { "h": "\uBCC4\uB3C4\uB85C \uB354\uD574\uC9C0\uB294 \uD56D\uBAA9\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uBC30\uB2EC \uC571 \uC8FC\uBB38\uC744 \uD3EC\uC2A4\uB85C \uBC1B\uB294 \uC5F0\uB3D9 \uAE30\uB2A5\uC740 \uC571\uB9C8\uB2E4 \uCD94\uAC00\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uD55C \uD654\uBA74\uC5D0\uC11C \uBCF4\uB294 \uD1B5\uD569 \uAD00\uB9AC\uB294 \uB9E4\uC7A5 \uC218\uC5D0 \uB530\uB77C \uC0AC\uC6A9\uB8CC\uAC00 \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.", "\uACE0\uAC1D \uC801\uB9BD\uC774\uB098 \uBA64\uBC84\uC2ED \uAE30\uB2A5\uC740 \uBCC4\uB3C4 \uBAA8\uB4C8\uB85C \uBD99\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uD0A4\uC624\uC2A4\uD06C\uB098 \uD14C\uC774\uBE14\uC624\uB354\uC640 \uC5F0\uB3D9\uD558\uBA74 \uADF8\uCABD \uC0AC\uC6A9\uB8CC\uAC00 \uB530\uB85C \uC0DD\uAE41\uB2C8\uB2E4.", "\uC7AC\uACE0 \uAD00\uB9AC\uC640 \uBC1C\uC8FC \uAE30\uB2A5\uC740 \uC18C\uB9E4\uC810\uC5D0\uC11C \uCD94\uAC00 \uD56D\uBAA9\uC73C\uB85C \uB4E4\uC5B4\uAC00\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uCD94\uAC00 \uD56D\uBAA9\uC740 \uC4F0\uC9C0 \uC54A\uC73C\uBA74 \uBE7C \uB2EC\uB77C\uACE0 \uD560 \uC218 \uC788\uC73C\uBBC0\uB85C \uACC4\uC57D \uB54C \uBAA9\uB85D\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uD56D\uBAA9\uC740 \uC571 \uCABD \uC218\uC218\uB8CC\uC640 \uBCC4\uAC1C\uC774\uBBC0\uB85C \uC571 \uC815\uC0B0\uC11C\uC640 \uD3EC\uC2A4 \uCCAD\uAD6C\uC11C\uB97C \uB098\uB220 \uBD05\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC740 \uC571\uB9C8\uB2E4 \uC8FC\uBB38 \uD615\uC2DD\uC774 \uB2EC\uB77C \uC5F0\uB3D9 \uBE44\uC6A9\uC774 \uC571\uBCC4\uB85C \uCC45\uC815\uB418\uB294 \uAD6C\uC870\uAC00 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4.", "\uD074\uB77C\uC6B0\uB4DC \uC800\uC7A5 \uC6A9\uB7C9\uC774\uB098 \uBCF4\uAD00 \uAE30\uAC04\uC5D0 \uD55C\uB3C4\uAC00 \uC788\uC73C\uBA74 \uD55C\uB3C4\uB97C \uB118\uAE38 \uB54C \uCD94\uAC00 \uC694\uAE08\uC774 \uBD99\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD11\uACE0 \uD654\uBA74\uC774\uB098 \uB300\uAE30 \uD654\uBA74 \uAFB8\uBBF8\uAE30 \uAC19\uC740 \uAE30\uB2A5\uC740 \uB9E4\uC7A5\uC774 \uC694\uCCAD\uD558\uC9C0 \uC54A\uC544\uB3C4 \uAE30\uBCF8\uC5D0 \uD3EC\uD568\uB3FC \uB4E4\uC5B4\uC624\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uD56D\uBAA9\uC744 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC0AC\uC6A9\uB8CC\uAC00 \uC624\uB974\uB294 \uACBD\uC6B0\uB294 \uC5B8\uC81C\uC778\uAC00\uC694?", "p": ["\uB9E4\uC7A5\uC774\uB098 \uAE30\uAE30 \uC218\uAC00 \uB298\uC5B4\uB098\uBA74 \uAE30\uAE30\uB2F9 \uC0AC\uC6A9\uB8CC\uAC00 \uB354\uD574\uC9D1\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571\uC774\uB098 \uACB0\uC81C \uC218\uB2E8\uC744 \uCD94\uAC00 \uC5F0\uB3D9\uD558\uBA74 \uADF8 \uD56D\uBAA9\uC774 \uBD99\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uC774 \uB05D\uB098\uACE0 \uC790\uB3D9 \uC5F0\uC7A5\uB418\uBA74\uC11C \uC870\uAC74\uC774 \uBC14\uB00C\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC885\uB8CC \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC0C1\uC704 \uBC84\uC804\uC73C\uB85C \uBC14\uAFB8\uBA74 \uAE30\uB2A5\uACFC \uD568\uAED8 \uC0AC\uC6A9\uB8CC\uAC00 \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.", "\uC778\uC0C1 \uC870\uAC74\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uC5C6\uC73C\uBA74 \uC778\uC0C1 \uD1B5\uC9C0\uAC00 \uC654\uC744 \uB54C \uADFC\uAC70\uB97C \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uBB36\uC5B4 \uACC4\uC57D\uD558\uBA74 \uAE30\uAE30\uB2F9 \uC0AC\uC6A9\uB8CC\uAC00 \uB0AE\uC544\uC9C0\uB294 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAC31\uC2E0 \uC2DC\uC810\uC5D0 \uC0AC\uC6A9\uB8CC \uC870\uC815\uC744 \uC694\uCCAD\uD560 \uC218 \uC788\uC73C\uBBC0\uB85C \uAC31\uC2E0 \uB2EC\uC744 \uBBF8\uB9AC \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC0AC\uC6A9\uB8CC \uC778\uC0C1 \uD1B5\uC9C0\uAC00 \uC624\uBA74 \uC57D\uC815\uC11C\uC758 \uC778\uC0C1 \uC870\uD56D\uACFC \uB300\uC870\uD558\uACE0 \uADFC\uAC70\uAC00 \uC5C6\uC73C\uBA74 \uC870\uC815\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4."] }, { "h": "\uC4F0\uC9C0 \uC54A\uB294 \uAE30\uB2A5\uC740 \uC5B4\uB5BB\uAC8C \uC815\uB9AC\uD558\uB098\uC694?", "p": ["\uC6D4 \uCCAD\uAD6C\uC11C\uC758 \uD56D\uBAA9\uC744 \uD558\uB098\uC529 \uBCF4\uACE0 \uB9E4\uC7A5\uC5D0\uC11C \uC2E4\uC81C\uB85C \uC4F0\uB294 \uAE30\uB2A5\uC778\uC9C0 \uD45C\uC2DC\uD569\uB2C8\uB2E4.", "\uC4F0\uC9C0 \uC54A\uB294 \uCD94\uAC00 \uD56D\uBAA9\uC740 \uD574\uC9C0 \uC694\uCCAD\uC744 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uBE60\uC84C\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC0AC\uC6A9\uB8CC \uC548\uC5D0 \uBB36\uC778 \uAE30\uB2A5\uC740 \uBE7C\uB3C4 \uAE08\uC561\uC774 \uC904\uC9C0 \uC54A\uC73C\uBBC0\uB85C \uCD94\uAC00 \uD56D\uBAA9\uB9CC \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uC815\uB9AC\uD55C \uB4A4 \uBC14\uB010 \uC6D4 \uC0AC\uC6A9\uB8CC\uB97C \uC11C\uBA74\uC73C\uB85C \uBC1B\uC544 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC815\uB9AC\uD55C \uB4A4\uC5D0\uB3C4 \uB2E4\uC74C \uB2EC \uCCAD\uAD6C\uC11C\uC5D0 \uBE60\uC9C4 \uD56D\uBAA9\uC774 \uB2E4\uC2DC \uC62C\uB77C\uC624\uBA74 \uC811\uC218 \uBC88\uD638\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4.", "\uCCAD\uAD6C\uC11C \uD56D\uBAA9\uC774 \uBC14\uB010 \uB2EC\uC5D0\uB294 \uBC14\uB010 \uC774\uC720\uB97C \uC801\uC5B4 \uB450\uBA74 \uB2E4\uC74C \uC810\uAC80 \uB54C \uBE44\uAD50\uAC00 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC815\uB9AC \uC694\uCCAD\uACFC \uC751\uB2F5\uC744 \uAC19\uC740 \uBA54\uC77C\uC774\uB098 \uBA54\uC2DC\uC9C0 \uBB36\uC74C\uC5D0 \uBAA8\uC544 \uB450\uBA74 \uB2E4\uC74C \uD574\uC9C0\xB7\uAC31\uC2E0 \uB54C \uCC3E\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uAC31\uC2E0 \uD611\uC758 \uB54C\uB294 \uADF8\uB3D9\uC548 \uC801\uC5B4 \uB454 \uC6D4\uBCC4 \uD56D\uBAA9\uD45C\uB97C \uADFC\uAC70\uB85C \uC4F0\uC9C0 \uC54A\uB294 \uAE30\uB2A5\uC744 \uBE7C\uACE0 \uD544\uC694\uD55C \uAE30\uB2A5\uB9CC \uB0A8\uAE41\uB2C8\uB2E4.", "\uC810\uAC80 \uACB0\uACFC\uB97C \uC6D4\uBCC4\uB85C \uC801\uC5B4 \uC57D\uC815 \uAC31\uC2E0 \uB54C \uADFC\uAC70\uB85C \uC501\uB2C8\uB2E4."] }], "steps": { "h": "\uC0AC\uC6A9\uB8CC \uC810\uAC80\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uC6D4 \uCCAD\uAD6C\uC11C\uB97C \uD56D\uBAA9\uBCC4\uB85C \uB098\uB220 \uC801\uC2B5\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC0AC\uC6A9\uB8CC \uD3EC\uD568 \uBC94\uC704\uB97C \uC5C5\uCCB4\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC4F0\uC9C0 \uC54A\uB294 \uCD94\uAC00 \uD56D\uBAA9\uC744 \uACE8\uB77C \uD574\uC9C0 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uBC18\uC601 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC14\uB010 \uC6D4 \uC0AC\uC6A9\uB8CC\uB97C \uC11C\uBA74\uC73C\uB85C \uBC1B\uC544 \uC57D\uC815\uC11C\uC640 \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC0AC\uC6A9\uB8CC \uD56D\uBAA9 \uAD6C\uBD84", "head": ["\uAD6C\uBD84", "\uC608\uC2DC", "\uC815\uB9AC \uAC00\uB2A5"], "rows": [["\uAE30\uBCF8", "\uC0AC\uC6A9\uAD8C\xB7\uC5C5\uB370\uC774\uD2B8\xB7\uC6D0\uACA9 \uC9C0\uC6D0", "\uC544\uB2C8\uC694"], ["\uCD94\uAC00", "\uBC30\uB2EC \uC571 \uC5F0\uB3D9\xB7\uBA64\uBC84\uC2ED\xB7\uC7AC\uACE0", "\uC608"], ["\uC5F0\uB3D9", "\uD0A4\uC624\uC2A4\uD06C\xB7\uD14C\uC774\uBE14\uC624\uB354", "\uD574\uB2F9 \uAE30\uAE30 \uD574\uC9C0 \uC2DC"], ["\uD655\uC7A5", "\uD1B5\uD569 \uAD00\uB9AC\xB7\uB2E4\uC810\uD3EC", "\uB9E4\uC7A5 \uC218\uC5D0 \uB530\uB77C"]] }, "faq": [["\uC0AC\uC6A9\uB8CC\uB97C \uC548 \uB0B4\uBA74 \uD3EC\uC2A4\uAE30\uAC00 \uBA48\uCD94\uB098\uC694?", "\uD504\uB85C\uADF8\uB7A8\uC774 \uC7A0\uAE30\uAC70\uB098 \uC5C5\uB370\uC774\uD2B8\uAC00 \uB04A\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4. \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4. \uC7A0\uAE30\uAE30 \uC804\uC5D0 \uD1B5\uC9C0\uAC00 \uC624\uB294\uC9C0, \uBBF8\uB0A9 \uC720\uC608 \uAE30\uAC04\uC774 \uC788\uB294\uC9C0 \uC57D\uC815\uC11C\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC0AC\uC6A9\uB8CC \uC5C6\uB294 \uD504\uB85C\uADF8\uB7A8\uB3C4 \uC788\uB098\uC694?", "\uC788\uC9C0\uB9CC \uC6D0\uACA9 \uC9C0\uC6D0\uACFC \uC5C5\uB370\uC774\uD2B8\uAC00 \uBE60\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uACE0\uC7A5 \uB54C \uB300\uC751\uC744 \uB530\uC838 \uBD05\uB2C8\uB2E4."], ["\uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC740 \uC571\uB9C8\uB2E4 \uC0AC\uC6A9\uB8CC\uAC00 \uBD99\uB098\uC694?", "\uD504\uB85C\uADF8\uB7A8\uB9C8\uB2E4 \uB2E4\uB985\uB2C8\uB2E4. \uC5F0\uB3D9\uD560 \uC571 \uBAA9\uB85D\uC744 \uC8FC\uACE0 \uD56D\uBAA9\uBCC4 \uAE08\uC561\uC744 \uBC1B\uC2B5\uB2C8\uB2E4. \uCD94\uAC00 \uC5F0\uB3D9 \uB4A4 \uCCAB \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uD56D\uBAA9\uC774 \uB298\uC5B4\uB09C \uB9CC\uD07C\uB9CC \uC62C\uB790\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC0AC\uC6A9\uB8CC \uC778\uC0C1\uC740 \uBBF8\uB9AC \uC54C\uB824 \uC8FC\uB098\uC694?", "\uC57D\uC815\uC11C\uC5D0 \uD1B5\uC9C0 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4. \uC5C6\uC73C\uBA74 \uC778\uC0C1 \uD1B5\uC9C0 \uB54C \uADFC\uAC70\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4. \uC778\uC0C1 \uD3ED\uC774 \uC57D\uC815\uC11C\uC5D0 \uC5C6\uC73C\uBA74 \uAC70\uC808\uD558\uAC70\uB098 \uC870\uAC74\uC744 \uB2E4\uC2DC \uD611\uC758\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58\uBE44\uC6A9", "\uD3EC\uC2A4\uAE30\uC784\uB300", "\uD14C\uC774\uBE14\uC624\uB354\uBC30\uB2EC\uC571\uC5F0\uB3D9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC5F0\uB3D9", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC5F0\uB3D9", "title": "\uD3EC\uC2A4\uAE30\uC640 \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC5F0\uB3D9\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694? \u2014 \uAE08\uC561\uC774 \uC790\uB3D9\uC73C\uB85C \uB118\uC5B4\uAC00\uB294 \uC870\uAC74", "desc": "\uD3EC\uC2A4\uAE30\uC640 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uC5F0\uB3D9\uD588\uC744 \uB54C \uC8FC\uBB38 \uAE08\uC561\uC774 \uB2E8\uB9D0\uAE30\uB85C \uC790\uB3D9 \uC804\uB2EC\uB418\uB294 \uBC29\uC2DD\uACFC \uC5F0\uB3D9\uC774 \uB418\uB294 \uAE30\uAE30 \uC870\uD569, \uC124\uCE58 \uB54C \uD655\uC778\uD560 \uC124\uC815, \uC5F0\uB3D9\uC774 \uB04A\uACBC\uC744 \uB54C \uB9E4\uC7A5\uC774 \uD560 \uC218 \uC788\uB294 \uC870\uCE58\uC640 \uB9C8\uAC10 \uB300\uC870 \uBC29\uBC95\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC5F0\uB3D9\uC740 \uD3EC\uC2A4\uC5D0\uC11C \uC8FC\uBB38\uC744 \uACB0\uC81C\uB85C \uB118\uAE30\uBA74 \uB2E8\uB9D0\uAE30\uC5D0 \uAE08\uC561\uC774 \uC790\uB3D9\uC73C\uB85C \uB728\uB294 \uC5F0\uACB0\uC774\uBA70, \uD504\uB85C\uADF8\uB7A8\uC774 \uC9C0\uC6D0\uD558\uB294 \uB2E8\uB9D0\uAE30 \uBAA8\uB378\uACFC \uC5F0\uACB0 \uBC29\uC2DD(\uCF00\uC774\uBE14\xB7\uB124\uD2B8\uC6CC\uD06C)\uC774 \uB9DE\uC544\uC57C \uB429\uB2C8\uB2E4. \uC5F0\uB3D9\uC774 \uC548 \uB418\uBA74 \uAE08\uC561\uC744 \uB2E8\uB9D0\uAE30\uC5D0 \uC190\uC73C\uB85C \uC785\uB825\uD574\uC57C \uD574\uC11C \uC624\uD0C0\uC640 \uB204\uB77D\uC774 \uC0DD\uAE30\uBBC0\uB85C \uC124\uCE58 \uB54C \uBC18\uB4DC\uC2DC \uB9DE\uCDA5\uB2C8\uB2E4.", "sections": [{ "h": "\uC5F0\uB3D9\uB418\uBA74 \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC8FC\uBB38 \uAE08\uC561\uC774 \uB2E8\uB9D0\uAE30\uB85C \uC790\uB3D9 \uC804\uB2EC\uB3FC \uC190\uC73C\uB85C \uC785\uB825\uD558\uB294 \uACFC\uC815\uC774 \uC5C6\uC5B4\uC9D1\uB2C8\uB2E4.", "\uACB0\uC81C \uACB0\uACFC\uAC00 \uD3EC\uC2A4\uB85C \uB3CC\uC544\uC640 \uC601\uC218\uC99D\uACFC \uB9E4\uCD9C \uC790\uB8CC\uC5D0 \uC790\uB3D9\uC73C\uB85C \uB0A8\uC2B5\uB2C8\uB2E4.", "\uCDE8\uC18C\uB3C4 \uD3EC\uC2A4\uC5D0\uC11C \uCC98\uB9AC\uD558\uBA74 \uB2E8\uB9D0\uAE30 \uCDE8\uC18C\uAE4C\uC9C0 \uC774\uC5B4\uC838 \uB450 \uBC88 \uC791\uC5C5\uD560 \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uB9C8\uAC10 \uB54C \uD3EC\uC2A4 \uB9E4\uCD9C\uACFC \uB2E8\uB9D0\uAE30 \uC2B9\uC778 \uD569\uACC4\uAC00 \uAC19\uC544\uC57C \uD558\uB294\uB370, \uC5F0\uB3D9\uC774 \uB418\uBA74 \uC5B4\uAE0B\uB098\uB294 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uBD84\uD560 \uACB0\uC81C\uB098 \uD604\uAE08 \uC601\uC218\uC99D\uB3C4 \uD3EC\uC2A4 \uD654\uBA74\uC5D0\uC11C \uD55C \uBC88\uC5D0 \uCC98\uB9AC\uB429\uB2C8\uB2E4.", "\uC190\uB2D8 \uB300\uAE30 \uC2DC\uAC04\uC774 \uC9E7\uC544\uC9C0\uACE0, \uC9C1\uC6D0\uC774 \uBC14\uB00C\uC5B4\uB3C4 \uACB0\uC81C \uC21C\uC11C\uAC00 \uAC19\uC544\uC9D1\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uC5C6\uC774 \uC4F0\uBA74 \uAE08\uC561 \uC785\uB825 \uC2E4\uC218\uAC00 \uC815\uC0B0 \uCC28\uC774\uB85C \uC774\uC5B4\uC9C0\uBBC0\uB85C \uC124\uCE58 \uB54C \uC5F0\uB3D9 \uC5EC\uBD80\uB97C \uBC18\uB4DC\uC2DC \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC5F0\uB3D9\uC774 \uB418\uBA74 \uC138\uBB34 \uC790\uB8CC\uC5D0 \uCE74\uB4DC \uC2B9\uC778 \uBC88\uD638\uAE4C\uC9C0 \uB0A8\uC544 \uD658\uBD88 \uBD84\uC7C1 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uB4A4 \uC601\uC218\uC99D\uC5D0 \uD3EC\uC2A4 \uC8FC\uBB38 \uBC88\uD638\uC640 \uC2B9\uC778 \uBC88\uD638\uAC00 \uD568\uAED8 \uCC0D\uD788\uB294\uC9C0 \uD655\uC778\uD558\uBA74 \uD658\uBD88 \uB54C \uCC3E\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC5F0\uB3D9\uC774 \uB418\uBA74 \uC190\uB2D8 \uC601\uC218\uC99D\uACFC \uAC00\uB9F9\uC810 \uBCF4\uAD00\uC6A9 \uC601\uC218\uC99D\uC774 \uD55C \uBC88\uC5D0 \uCD9C\uB825\uB418\uBBC0\uB85C \uCD9C\uB825 \uB9E4\uC218 \uC124\uC815\uB3C4 \uD568\uAED8 \uC815\uD569\uB2C8\uB2E4."] }, { "h": "\uC5B4\uB5A4 \uAE30\uAE30\uB07C\uB9AC \uC5F0\uB3D9\uB418\uB098\uC694?", "p": ["\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC774 \uC9C0\uC6D0\uD558\uB294 \uB2E8\uB9D0\uAE30 \uBAA8\uB378 \uBAA9\uB85D\uC774 \uC788\uC73C\uBBC0\uB85C \uBAA8\uB378\uBA85\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5F0\uACB0 \uBC29\uC2DD\uC740 \uCF00\uC774\uBE14 \uC9C1\uACB0\uACFC \uAC19\uC740 \uB124\uD2B8\uC6CC\uD06C \uC5F0\uACB0\uC774 \uC788\uACE0, \uC790\uB9AC \uBC30\uCE58\uC5D0 \uB530\uB77C \uACE0\uB985\uB2C8\uB2E4.", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uB294 \uC5F0\uB3D9\uC774 \uC81C\uD55C\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB9CC \uC5F0\uB3D9\uD558\uACE0 \uBB34\uC120\uAE30\uB294 \uB530\uB85C \uC4F0\uB294 \uB9E4\uC7A5\uC774 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAE30\uC874 \uB2E8\uB9D0\uAE30\uB97C \uC4F0\uB824\uBA74 \uBC34\uC0AC\uC640 \uD504\uB85C\uADF8\uB7A8\uC774 \uC11C\uB85C \uB9DE\uB294\uC9C0\uB3C4 \uBD10\uC57C \uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uBAA9\uB85D\uC5D0 \uC5C6\uB294 \uAE30\uAE30\uB294 \uC5F0\uB3D9\uC774 \uC548 \uB418\uBBC0\uB85C \uAE30\uAE30\uB97C \uBC14\uAFB8\uAC70\uB098 \uD504\uB85C\uADF8\uB7A8\uC744 \uBC14\uAFB8\uB294 \uC120\uD0DD\uC774 \uB429\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uC5EC\uBD80\uC640 \uC124\uC815 \uBC29\uBC95\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAC19\uC740 \uBC34\uC0AC \uAE30\uAE30\uB77C\uB3C4 \uD504\uB85C\uADF8\uB7A8 \uBC84\uC804\uC5D0 \uB530\uB77C \uC9C0\uC6D0\uC774 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uC5B4 \uBC84\uC804\uAE4C\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5F0\uACB0 \uBC29\uC2DD\uC744 \uBC14\uAFB8\uBA74(\uCF00\uC774\uBE14\u2192\uB124\uD2B8\uC6CC\uD06C) \uC124\uC815\uAC12\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uBC14\uAFBC \uB4A4 \uD14C\uC2A4\uD2B8\uB97C \uB2E4\uC2DC \uD569\uB2C8\uB2E4.", "\uB124\uD2B8\uC6CC\uD06C \uBC29\uC2DD\uC740 \uACF5\uC720\uAE30 \uC124\uC815\uC774 \uBC14\uB00C\uBA74 \uB04A\uAE30\uAE30 \uC26C\uC6CC \uACF5\uC720\uAE30\uB97C \uAD50\uCCB4\uD560 \uB54C \uC5C5\uCCB4\uC5D0 \uBBF8\uB9AC \uC54C\uB9BD\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB54C \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uC8FC\uBB38 \uD558\uB098\uB97C \uB123\uC5B4 \uAE08\uC561\uC774 \uB2E8\uB9D0\uAE30\uC5D0 \uB728\uB294\uC9C0, \uACB0\uC81C \uB4A4 \uD3EC\uC2A4\uC5D0 \uACB0\uACFC\uAC00 \uB3CC\uC544\uC624\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uCDE8\uC18C\uB97C \uD3EC\uC2A4\uC5D0\uC11C \uD574\uC11C \uB2E8\uB9D0\uAE30 \uCDE8\uC18C\uAE4C\uC9C0 \uC774\uC5B4\uC9C0\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC5D0 \uC2B9\uC778 \uBC88\uD638\uAC00 \uCC0D\uD788\uB294\uC9C0, \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uC5D0 \uCE74\uB4DC \uB9E4\uCD9C\uC774 \uC7A1\uD788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uB2E8\uB9D0\uAE30\uAC00 \uB450 \uB300\uBA74 \uC5B4\uB290 \uD3EC\uC2A4 \uD654\uBA74\uC774 \uC5B4\uB290 \uAE30\uAE30\uB85C \uC5F0\uACB0\uB418\uB294\uC9C0 \uC815\uD574 \uB461\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uC124\uC815\uAC12(\uD1B5\uC2E0 \uBC29\uC2DD\xB7\uD3EC\uD2B8)\uC744 \uC801\uC5B4 \uB450\uBA74 \uB098\uC911\uC5D0 \uB04A\uACBC\uC744 \uB54C \uBCF5\uAD6C\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uC124\uC815\uAC12\uC740 \uC0AC\uC9C4\uC73C\uB85C \uCC0D\uC5B4 \uB450\uC5B4\uB3C4 \uB418\uACE0, \uACE0\uAC1D\uC13C\uD130\uC5D0 \uC124\uC815\uAC12 \uAE30\uB85D\uC744 \uC694\uCCAD\uD574\uB3C4 \uB429\uB2C8\uB2E4.", "\uC124\uCE58 \uAE30\uC0AC\uAC00 \uB5A0\uB098\uAE30 \uC804\uC5D0 \uCDE8\uC18C \uACB0\uC81C\uB97C \uD3EC\uC2A4\uC5D0\uC11C \uC9C1\uC811 \uD574 \uBCF4\uB294 \uAC83\uC774 \uAC00\uC7A5 \uD655\uC2E4\uD55C \uD655\uC778\uC785\uB2C8\uB2E4.", "\uC124\uCE58 \uB54C \uACB0\uC81C \uD14C\uC2A4\uD2B8\uB97C \uCE74\uB4DC \uC885\uB958\uBCC4(\uC2E0\uC6A9\xB7\uCCB4\uD06C)\uB85C \uD55C \uBC88\uC529 \uD574 \uBCF4\uBA74 \uACB0\uC81C \uACB0\uACFC \uBC18\uC601\uC774 \uBAA8\uB450 \uD655\uC778\uB429\uB2C8\uB2E4."] }, { "h": "\uC5F0\uB3D9\uC774 \uB04A\uAE30\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uCF00\uC774\uBE14\uC774 \uBE60\uC84C\uAC70\uB098 \uB124\uD2B8\uC6CC\uD06C\uAC00 \uBC14\uB00C\uC5C8\uC744 \uB54C \uAC00\uC7A5 \uB9CE\uC774 \uB04A\uAE30\uBBC0\uB85C \uC5F0\uACB0\uBD80\uD130 \uBD05\uB2C8\uB2E4.", "\uB2E8\uB9D0\uAE30\uB9CC \uCF1C\uC838 \uC788\uC73C\uBA74 \uAE08\uC561\uC744 \uC190\uC73C\uB85C \uC785\uB825\uD574 \uACB0\uC81C\uB97C \uC774\uC5B4\uAC00\uACE0, \uD3EC\uC2A4\uC5D0\uB294 \uC678\uBD80 \uACB0\uC81C\uB85C \uAE30\uB85D\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8 \uB4A4 \uB04A\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC5C5\uB370\uC774\uD2B8 \uC9C1\uD6C4\uC5D0\uB294 \uACB0\uC81C \uD55C \uBC88\uC744 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uBCF5\uAD6C\uAC00 \uC548 \uB418\uBA74 \uACE0\uAC1D\uC13C\uD130\uC5D0 \uC124\uC815\uAC12\uC744 \uC54C\uB824 \uC8FC\uACE0 \uC6D0\uACA9 \uC9C0\uC6D0\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB04A\uAE34 \uB3D9\uC548\uC758 \uACB0\uC81C\uB294 \uB9C8\uAC10 \uB54C \uB2E8\uB9D0\uAE30 \uC2B9\uC778 \uB0B4\uC5ED\uACFC \uB530\uB85C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uBCF5\uAD6C \uB4A4\uC5D0\uB294 \uB04A\uAE34 \uB3D9\uC548 \uC190\uC73C\uB85C \uC785\uB825\uD55C \uACB0\uC81C\uB97C \uD3EC\uC2A4\uC5D0 \uC678\uBD80 \uACB0\uC81C\uB85C \uB123\uC5B4 \uB9C8\uAC10 \uD569\uACC4\uB97C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uB04A\uAE40\uC774 \uC7A6\uC73C\uBA74 \uCF00\uC774\uBE14 \uAD50\uCCB4\uB098 \uB124\uD2B8\uC6CC\uD06C \uBD84\uB9AC\uB85C \uD574\uACB0\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uC6D0\uC778\uC744 \uC801\uC5B4 \uB450\uACE0 \uC5C5\uCCB4\uC5D0 \uC54C\uB9BD\uB2C8\uB2E4.", "\uB04A\uAE40 \uBCF5\uAD6C \uB4A4 \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uC758 \uCE74\uB4DC \uB9E4\uCD9C\uACFC \uB2E8\uB9D0\uAE30 \uC2B9\uC778 \uD569\uACC4\uB97C \uB9DE\uCDB0 \uBCF4\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uC124\uC815\uAC12\uC744 \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uACA8 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uC5F0\uB3D9 \uC124\uCE58 \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uB2E8\uB9D0\uAE30 \uBAA9\uB85D\uC5D0\uC11C \uBAA8\uB378\uC744 \uB9DE\uCDA5\uB2C8\uB2E4.", "\uC5F0\uACB0 \uBC29\uC2DD\uC744 \uC815\uD558\uACE0 \uAE30\uAE30\uB97C \uC124\uCE58\uD569\uB2C8\uB2E4.", "\uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uCDE8\uC18C \uD55C \uBC14\uD034\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uC124\uC815\uAC12\uC744 \uAE30\uB85D\uD558\uACE0 \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5F0\uB3D9\uC774 \uB04A\uACBC\uC744 \uB54C \uC190 \uC785\uB825\uC73C\uB85C \uC774\uC5B4\uAC00\uB294 \uC21C\uC11C\uB97C \uC9C1\uC6D0\uC5D0\uAC8C \uC54C\uB824 \uB461\uB2C8\uB2E4."] }, "table": { "caption": "\uC5F0\uB3D9 \uC5EC\uBD80\uC5D0 \uB530\uB978 \uCC28\uC774", "head": ["\uC791\uC5C5", "\uC5F0\uB3D9 \uC2DC", "\uBBF8\uC5F0\uB3D9 \uC2DC"], "rows": [["\uAE08\uC561 \uC785\uB825", "\uC790\uB3D9", "\uC190 \uC785\uB825"], ["\uCDE8\uC18C", "\uD3EC\uC2A4\uC5D0\uC11C \uD55C \uBC88", "\uD3EC\uC2A4\xB7\uB2E8\uB9D0\uAE30 \uAC01\uAC01"], ["\uB9E4\uCD9C \uC790\uB8CC", "\uC790\uB3D9 \uAE30\uB85D", "\uC218\uAE30 \uB300\uC870"], ["\uB9C8\uAC10 \uB300\uC870", "\uC2B9\uC778 \uD569\uACC4 \uC790\uB3D9", "\uC601\uC218\uC99D \uBB36\uC74C \uD655\uC778"]] }, "faq": [["\uAE30\uC874 \uB2E8\uB9D0\uAE30\uB3C4 \uC5F0\uB3D9\uB418\uB098\uC694?", "\uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uBAA9\uB85D\uC5D0 \uC788\uACE0 \uBC34\uC0AC\uAC00 \uB9DE\uC73C\uBA74 \uB429\uB2C8\uB2E4. \uBAA8\uB378\uBA85\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uB3C4 \uC5F0\uB3D9\uB418\uB098\uC694?", "\uC81C\uD55C\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB9CC \uC5F0\uB3D9\uD558\uACE0 \uBB34\uC120\uAE30\uB294 \uBCC4\uB3C4\uB85C \uC4F0\uB294 \uBC29\uC2DD\uC774 \uD754\uD569\uB2C8\uB2E4."], ["\uC5F0\uB3D9 \uC124\uC815\uC5D0 \uBE44\uC6A9\uC774 \uB4DC\uB098\uC694?", "\uC124\uCE58 \uC791\uC5C5\uC5D0 \uD3EC\uD568\uB418\uAE30\uB3C4 \uD558\uACE0 \uBCC4\uB3C4\uC774\uAE30\uB3C4 \uD569\uB2C8\uB2E4. \uACAC\uC801\uC11C \uD56D\uBAA9\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4. \uC5F0\uB3D9 \uC124\uC815\uC774 \uBCC4\uB3C4\uB77C\uBA74 \uD3EC\uC2A4\uC640 \uB2E8\uB9D0\uAE30\uB97C \uAC19\uC740 \uB0A0 \uC124\uCE58\uD574 \uD55C \uBC88\uC5D0 \uB05D\uB0B4\uB294 \uD3B8\uC774 \uBE44\uC6A9\uC774 \uC801\uC2B5\uB2C8\uB2E4."], ["\uC5F0\uB3D9\uC774 \uB04A\uAE30\uBA74 \uACB0\uC81C\uB97C \uBABB \uD558\uB098\uC694?", "\uB2E8\uB9D0\uAE30 \uB2E8\uB3C5\uC73C\uB85C \uACB0\uC81C\uB294 \uB429\uB2C8\uB2E4. \uAE08\uC561\uC744 \uC190\uC73C\uB85C \uC785\uB825\uD558\uACE0 \uD3EC\uC2A4\uC5D0\uB294 \uB530\uB85C \uAE30\uB85D\uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58", "\uD3EC\uC2A4\uAE30\uD504\uB85C\uADF8\uB7A8\uC6D4\uC0AC\uC6A9\uB8CC"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uD574\uC9C0\uBC18\uB0A9", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uD574\uC9C0\xB7\uBC18\uB0A9", "title": "\uD3EC\uC2A4\uAE30 \uD574\uC9C0\uC640 \uBC18\uB0A9\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694? \u2014 \uD504\uB85C\uADF8\uB7A8\xB7\uAE30\uAE30\xB7\uC790\uB8CC\uB97C \uB098\uB220 \uC815\uB9AC\uD558\uAE30", "desc": "\uD3EC\uC2A4\uAE30\uB97C \uD574\uC9C0\uD560 \uB54C \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC \uD574\uC9C0, \uC784\uB300 \uAE30\uAE30 \uBC18\uB0A9, \uB9E4\uCD9C \uC790\uB8CC \uBC31\uC5C5\uC744 \uAC01\uAC01 \uC5B4\uB5BB\uAC8C \uCC98\uB9AC\uD558\uB294\uC9C0\uC640 \uC57D\uC815 \uC911 \uD574\uC9C0 \uC870\uAC74, \uBC18\uB0A9 \uC804 \uCD08\uAE30\uD654, \uD574\uC9C0 \uB4A4 \uC790\uB8CC \uBCF4\uAD00 \uAE30\uAC04\uACFC \uCCAD\uAD6C \uC911\uB2E8 \uD655\uC778 \uBC29\uBC95\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD3EC\uC2A4\uAE30 \uD574\uC9C0\uB294 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9 \uD574\uC9C0, \uC784\uB300 \uAE30\uAE30 \uBC18\uB0A9, \uB9E4\uCD9C \uC790\uB8CC \uBC31\uC5C5 \uC138 \uAC00\uC9C0\uB97C \uB530\uB85C \uB05D\uB0B4\uC57C \uC644\uB8CC\uB418\uBA70, \uD558\uB098\uB77C\uB3C4 \uBE60\uC9C0\uBA74 \uC0AC\uC6A9\uB8CC\uAC00 \uACC4\uC18D \uB098\uAC00\uAC70\uB098 \uC790\uB8CC\uB97C \uC783\uC2B5\uB2C8\uB2E4. \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC544 \uC788\uC73C\uBA74 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uBD99\uC73C\uBBC0\uB85C \uC57D\uC815\uC11C \uC870\uD56D\uC744 \uBA3C\uC800 \uC77D\uACE0 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uD574\uC9C0 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uBC31\uC5C5\uD558\uB098\uC694?", "p": ["\uB9E4\uCD9C \uC790\uB8CC, \uBA54\uB274, \uACE0\uAC1D \uC801\uB9BD \uC815\uBCF4\uB294 \uD574\uC9C0\uD558\uBA74 \uC811\uADFC\uC774 \uB04A\uAE30\uBBC0\uB85C \uBA3C\uC800 \uB0B4\uB824\uBC1B\uC2B5\uB2C8\uB2E4.", "\uC138\uBB34 \uC2E0\uACE0\uC5D0 \uC4F0\uB294 \uAE30\uAC04\uBCC4 \uB9E4\uCD9C \uBCF4\uACE0\uC11C\uB97C \uD30C\uC77C\uB85C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC5F0\uB3D9 \uACC4\uC815\uC740 \uD3EC\uC2A4\uC640 \uBD84\uB9AC\uD574 \uB450\uC5B4\uC57C \uC571 \uCABD \uC8FC\uBB38\uC774 \uB04A\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC591\uC2DD\uC774\uB098 \uBA54\uB274 \uC790\uB8CC\uB294 \uB2E4\uC74C \uD504\uB85C\uADF8\uB7A8\uC5D0\uC11C \uB2E4\uC2DC \uC4F8 \uC218 \uC788\uB3C4\uB85D \uD45C\uB85C \uB0A8\uAE41\uB2C8\uB2E4.", "\uC790\uB8CC \uB0B4\uBCF4\uB0B4\uAE30 \uAE30\uB2A5\uC774 \uC5C6\uC73C\uBA74 \uC5C5\uCCB4\uC5D0 \uC694\uCCAD\uD574 \uBC1B\uC544\uC57C \uD558\uBBC0\uB85C \uD574\uC9C0 \uC2E0\uCCAD \uC804\uC5D0 \uD569\uB2C8\uB2E4.", "\uD074\uB77C\uC6B0\uB4DC \uC800\uC7A5 \uD504\uB85C\uADF8\uB7A8\uC740 \uD574\uC9C0 \uB4A4 \uC790\uB8CC \uBCF4\uAD00 \uAE30\uAC04\uC774 \uC788\uC73C\uBBC0\uB85C \uADF8 \uAE30\uAC04\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC790\uB8CC \uBC31\uC5C5\uC774 \uB05D\uB0AC\uB294\uC9C0 \uD655\uC778\uD55C \uB4A4 \uD574\uC9C0 \uC2E0\uCCAD\uC744 \uB123\uB294 \uC21C\uC11C\uAC00 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uBC31\uC5C5 \uD30C\uC77C\uC740 \uB450 \uACF3(\uCEF4\uD4E8\uD130\uC640 \uC678\uBD80 \uC800\uC7A5)\uC5D0 \uB450\uC5B4\uC57C \uD55C \uACF3\uC774 \uC9C0\uC6CC\uC838\uB3C4 \uB0A8\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274 \uC790\uB8CC\uB97C \uD45C\uB85C \uB0A8\uAE30\uBA74 \uB2E4\uC74C \uB9E4\uC7A5\uC774\uB098 \uB2E4\uB978 \uD504\uB85C\uADF8\uB7A8\uC5D0\uC11C \uC785\uB825 \uC2DC\uAC04\uC744 \uD06C\uAC8C \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACE0\uAC1D \uC801\uB9BD \uC815\uBCF4\uB294 \uAC1C\uC778\uC815\uBCF4\uB77C \uD574\uC9C0 \uB4A4 \uC5C5\uCCB4 \uBCF4\uAD00 \uAE30\uAC04\uACFC \uD30C\uAE30 \uC5EC\uBD80\uB97C \uD655\uC778\uD574 \uB450\uB294 \uAC83\uC774 \uC548\uC804\uD569\uB2C8\uB2E4."] }, { "h": "\uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0\uC640 \uAE30\uAE30 \uBC18\uB0A9\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0\uB294 \uC6D4 \uC0AC\uC6A9\uB8CC\uB97C \uBA48\uCD94\uB294 \uAC83\uC774\uACE0, \uAE30\uAE30 \uBC18\uB0A9\uC740 \uC784\uB300 \uBCF8\uCCB4\uC640 \uC8FC\uBCC0\uAE30\uAE30\uB97C \uB3CC\uB824\uC8FC\uB294 \uAC83\uC785\uB2C8\uB2E4.", "\uAD6C\uB9E4\uD55C \uAE30\uAE30\uB294 \uBC18\uB0A9\uD560 \uD544\uC694\uAC00 \uC5C6\uACE0 \uD504\uB85C\uADF8\uB7A8\uB9CC \uD574\uC9C0\uD558\uBA74 \uB429\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB294 \uBC18\uB0A9 \uAE30\uD55C\uACFC \uBC29\uBC95(\uD0DD\uBC30\xB7\uBC29\uBB38 \uD68C\uC218)\uC744 \uBC1B\uC544 \uB450\uACE0 \uBC18\uB0A9 \uD655\uC778\uC99D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uC804\uC5D0 \uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD574 \uB9E4\uC7A5 \uC790\uB8CC\uC640 \uBE44\uBC00\uBC88\uD638\uAC00 \uB0A8\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uC8FC\uBCC0\uAE30\uAE30\uAC00 \uC784\uB300 \uD488\uBAA9\uC5D0 \uD3EC\uD568\uB3FC \uC788\uC73C\uBA74 \uD568\uAED8 \uBC18\uB0A9\uD574\uC57C \uD558\uBBC0\uB85C \uC57D\uC815\uC11C \uD488\uBAA9\uC744 \uBD05\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB294 \uBCC4\uB3C4 \uC57D\uC815\uC774\uB77C \uD3EC\uC2A4 \uD574\uC9C0\uC640 \uB530\uB85C \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD488\uBAA9\uC774 \uBE60\uC9C0\uBA74 \uAE30\uAE30\uAC12\uC774 \uCCAD\uAD6C\uB420 \uC218 \uC788\uC73C\uBBC0\uB85C \uC57D\uC815\uC11C \uD488\uBAA9\uACFC \uBC18\uB0A9 \uD488\uBAA9\uC744 \uD558\uB098\uC529 \uB300\uC870\uD569\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB3C4 \uD504\uB85C\uADF8\uB7A8 \uB77C\uC774\uC120\uC2A4\uB294 \uBC18\uD658\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uB77C\uC774\uC120\uC2A4 \uCC98\uB9AC \uBC29\uBC95\uC744 \uC5C5\uCCB4\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD0DD\uBC30\uB294 \uAE30\uAE30 \uC190\uC0C1\uC774 \uC0DD\uAE30\uC9C0 \uC54A\uB3C4\uB85D \uC6D0\uB798 \uD3EC\uC7A5\uC7AC\uB098 \uC644\uCDA9\uC7AC\uB97C \uC4F0\uACE0 \uC1A1\uC7A5 \uBC88\uD638\uB97C \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uB77C\uC774\uC120\uC2A4\uAC00 \uAE30\uAE30\uC5D0 \uBB36\uC5EC \uC788\uC73C\uBA74 \uAE30\uAE30 \uBC18\uB0A9\uACFC \uB3D9\uC2DC\uC5D0 \uB05D\uB098\uC9C0\uB9CC, \uB9E4\uC7A5 \uBA85\uC758 \uB77C\uC774\uC120\uC2A4\uB294 \uB530\uB85C \uD574\uC9C0\uD574\uC57C \uD569\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815 \uC911 \uD574\uC9C0\uD558\uBA74 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uB0A8\uC740 \uC57D\uC815 \uAE30\uAC04\uC5D0 \uB300\uD55C \uC870\uAC74\uC774 \uC57D\uC815\uC11C \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uC5D0 \uC788\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC740\uD488\uC774\uB098 \uC124\uCE58\uBE44 \uC9C0\uC6D0\uC744 \uBC1B\uC558\uB2E4\uBA74 \uBC18\uD658 \uC870\uD56D\uC774 \uB530\uB85C \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774 \uC0AC\uC720\uBA74 \uC99D\uBE59\uC744 \uB0B4\uBA74 \uC870\uAC74\uC774 \uB2EC\uB77C\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC5C5\uCCB4\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5 \uC0C1\uD0DC\uB77C\uBA74 \uC5F0\uC7A5 \uB4A4 \uD574\uC9C0 \uC870\uAC74\uC774 \uB2E4\uB97C \uC218 \uC788\uC73C\uBBC0\uB85C \uD604\uC7AC \uC57D\uC815 \uC0C1\uD0DC\uB97C \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC870\uAC74\uACFC \uAE08\uC561\uC740 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC0AC\uC740\uD488 \uBC18\uD658 \uC870\uD56D\uC740 \uBC1B\uC740 \uD488\uBAA9\uACFC \uAE08\uC561\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uD558\uBBC0\uB85C \uC5C6\uC73C\uBA74 \uC5C5\uCCB4\uC5D0 \uADFC\uAC70\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD \uB4A4 \uCC98\uB9AC \uAE30\uAC04 \uB3D9\uC548\uC758 \uC0AC\uC6A9\uB8CC \uCCAD\uAD6C \uC5EC\uBD80\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uB2C8 \uD568\uAED8 \uBD05\uB2C8\uB2E4.", "\uC57D\uC815 \uC911 \uD574\uC9C0\uAC00 \uBD88\uAC00\uD53C\uD558\uBA74 \uD574\uC9C0 \uC608\uC815\uC77C\uC744 \uC5C5\uCCB4\uC640 \uC815\uD574 \uADF8\uB0A0\uAE4C\uC9C0 \uC0AC\uC6A9\uB8CC\uAC00 \uC815\uC0B0\uB418\uB3C4\uB85D \uD569\uB2C8\uB2E4.", "\uD3D0\uC5C5 \uC99D\uBE59\uC740 \uD3D0\uC5C5\uC0AC\uC2E4\uC99D\uBA85\uC6D0\uCC98\uB7FC \uC138\uBB34\uC11C\uC5D0\uC11C \uBC1C\uAE09\uBC1B\uB294 \uC11C\uB958\uB85C \uD558\uBA74 \uC5C5\uCCB4\uAC00 \uBC14\uB85C \uBC1B\uC544 \uC90D\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uB4A4\uC5D0\uB294 \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uB2E4\uC74C \uB2EC \uCCAD\uAD6C\uC11C\uC5D0 \uC0AC\uC6A9\uB8CC\uAC00 \uBE60\uC84C\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD655\uC778\uC99D\uACFC \uD574\uC9C0 \uD655\uC778\uC11C\uB97C \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uBC31\uC5C5\uD55C \uB9E4\uCD9C \uC790\uB8CC\uB294 \uC138\uBB34 \uC790\uB8CC\uC774\uBBC0\uB85C \uC2E0\uACE0 \uAE30\uAC04 \uB3D9\uC548 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uAC19\uC740 \uC5C5\uCCB4\uB85C \uB2E4\uC2DC \uC124\uCE58\uD560 \uAC00\uB2A5\uC131\uC774 \uC788\uC73C\uBA74 \uBA54\uB274 \uC790\uB8CC\uB97C \uBCF4\uAD00\uD574 \uB450\uBA74 \uC7AC\uC124\uCE58\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4 \uBC1B\uB294 \uB9C8\uC9C0\uB9C9 \uCCAD\uAD6C\uC11C\uB294 \uC77C\uD560 \uACC4\uC0B0\uC778\uC9C0 \uC6D4 \uB2E8\uC704\uC778\uC9C0 \uBCF4\uACE0, \uB2E4\uB974\uBA74 \uC811\uC218 \uBC88\uD638\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4.", "\uC138\uBB34 \uC2E0\uACE0\uAC00 \uB05D\uB09C \uB4A4\uC5D0\uB3C4 \uC790\uB8CC \uBCF4\uAD00 \uC758\uBB34 \uAE30\uAC04\uC774 \uC788\uC73C\uBBC0\uB85C \uBC31\uC5C5 \uD30C\uC77C\uC740 \uC9C0\uC6B0\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uD655\uC778\uC11C\uC5D0 \uD574\uC9C0\uC77C\uACFC \uB0A8\uC740 \uCCAD\uAD6C \uAE08\uC561\uC774 \uC801\uD600 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uC5C6\uC73C\uBA74 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4 \uBC1B\uB294 \uB9C8\uC9C0\uB9C9 \uCCAD\uAD6C\uC11C\uC5D0 \uB0A8\uC740 \uCCAD\uAD6C \uD56D\uBAA9\uC774 \uC788\uC73C\uBA74 \uD574\uC9C0\uC77C \uAE30\uC900\uC73C\uB85C \uB9DE\uAC8C \uACC4\uC0B0\uB410\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uBC31\uC5C5 \uD30C\uC77C\uC744 \uB450 \uACF3\uC5D0 \uB098\uB220 \uBCF4\uAD00\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uD655\uC778\uC11C\uC5D0 \uD574\uC9C0\uC77C\uACFC \uB0A8\uC740 \uCCAD\uAD6C \uAE08\uC561\uC774 \uC801\uD614\uB294\uC9C0 \uD655\uC778\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uD574\uC9C0 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uB9E4\uCD9C\xB7\uBA54\uB274\xB7\uACE0\uAC1D \uC790\uB8CC\uB97C \uB0B4\uB824\uBC1B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0\uC11C \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uACFC \uBC18\uB0A9 \uD488\uBAA9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0 \uC2E0\uCCAD\uC744 \uAE00\uB85C \uC811\uC218\uD569\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD574 \uBC18\uB0A9\uD558\uACE0 \uD655\uC778\uC99D\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uC0AC\uC6A9\uB8CC \uC911\uB2E8\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD574\uC9C0 \uD56D\uBAA9\uBCC4 \uCC98\uB9AC", "head": ["\uD56D\uBAA9", "\uD560 \uC77C", "\uC99D\uBE59"], "rows": [["\uD504\uB85C\uADF8\uB7A8", "\uC0AC\uC6A9 \uD574\uC9C0 \uC2E0\uCCAD", "\uD574\uC9C0 \uD655\uC778\uC11C"], ["\uC784\uB300 \uAE30\uAE30", "\uCD08\uAE30\uD654\xB7\uBC18\uB0A9", "\uBC18\uB0A9 \uD655\uC778\uC99D"], ["\uB9E4\uCD9C \uC790\uB8CC", "\uBC31\uC5C5", "\uD30C\uC77C \uBCF4\uAD00"], ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "\uBCC4\uB3C4 \uD574\uC9C0", "\uBCC4\uB3C4 \uD655\uC778\uC11C"]] }, "faq": [["\uD574\uC9C0\uD558\uBA74 \uB9E4\uCD9C \uC790\uB8CC\uB97C \uBCFC \uC218 \uC5C6\uB098\uC694?", "\uB300\uBD80\uBD84 \uC811\uADFC\uC774 \uB04A\uAE41\uB2C8\uB2E4. \uD574\uC9C0 \uC804\uC5D0 \uB0B4\uB824\uBC1B\uACE0 \uBCF4\uAD00 \uAE30\uAC04\uC744 \uD655\uC778\uD569\uB2C8\uB2E4. \uBCF4\uAD00 \uAE30\uAC04\uC774 \uC9C0\uB098\uBA74 \uBCF5\uAD6C\uAC00 \uC548 \uB418\uBBC0\uB85C \uAE30\uAC04 \uC548\uC5D0 \uB0B4\uB824\uBC1B\uC2B5\uB2C8\uB2E4."], ["\uAD6C\uB9E4\uD55C \uD3EC\uC2A4\uAE30\uB3C4 \uBC18\uB0A9\uD558\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uD504\uB85C\uADF8\uB7A8\uB9CC \uD574\uC9C0\uD558\uBA74 \uB429\uB2C8\uB2E4."], ["\uC57D\uC815\uC774 \uB0A8\uC558\uB294\uB370 \uD3D0\uC5C5\uD558\uBA74 \uC704\uC57D\uAE08\uC774 \uC788\uB098\uC694?", "\uC57D\uC815\uC11C \uC870\uD56D\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uD3D0\uC5C5 \uC99D\uBE59\uC73C\uB85C \uC870\uAC74\uC774 \uB2EC\uB77C\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC5C5\uCCB4\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD574\uC9C0 \uB4A4\uC5D0\uB3C4 \uC0AC\uC6A9\uB8CC\uAC00 \uBE60\uC838\uB098\uAC00\uBA74\uC694?", "\uD574\uC9C0 \uD655\uC778\uC11C\uC640 \uC811\uC218 \uBC88\uD638\uB97C \uB4E4\uACE0 \uBC14\uB85C \uBB38\uC758\uD569\uB2C8\uB2E4. \uC790\uB3D9\uC774\uCCB4\uAC00 \uACC4\uC18D\uB418\uBA74 \uC740\uD589\uC5D0 \uC790\uB3D9\uC774\uCCB4 \uD574\uC9C0\uB3C4 \uAC19\uC774 \uC694\uCCAD\uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC784\uB300", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08", "\uD3EC\uC2A4\uAE30\uAD50\uCCB4\uC2DC\uAE30"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uC911\uACE0\uD3EC\uC2A4\uAE30", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uC911\uACE0 \uD3EC\uC2A4\uAE30", "title": "\uC911\uACE0 \uD3EC\uC2A4\uAE30\uB97C \uC368\uB3C4 \uAD1C\uCC2E\uB098\uC694? \u2014 \uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0\uACFC \uBCF4\uC99D\uC744 \uBA3C\uC800 \uBCF4\uB294 \uC774\uC720", "desc": "\uC911\uACE0 \uD3EC\uC2A4\uAE30\uB97C \uC4F8 \uB54C \uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uC5EC\uBD80, \uC6B4\uC601\uCCB4\uC81C \uBC84\uC804, \uC8FC\uBCC0\uAE30\uAE30 \uD638\uD658, \uBCF4\uC99D\uACFC \uC218\uB9AC \uC870\uAC74\uC744 \uD655\uC778\uD558\uB294 \uBC29\uBC95\uACFC \uC911\uACE0\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uACFC \uD53C\uD574\uC57C \uD560 \uACBD\uC6B0, \uAD6C\uC785 \uB4A4 \uCD08\uAE30\uD654\uC640 \uD14C\uC2A4\uD2B8 \uC21C\uC11C, \uC0C8 \uAE30\uAE30 \uC784\uB300\uC640\uC758 \uBE44\uAD50 \uAE30\uC900\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC911\uACE0 \uD3EC\uC2A4\uAE30\uB294 \uD504\uB85C\uADF8\uB7A8\uC774 \uADF8 \uAE30\uAE30\uB97C \uC9C0\uC6D0\uD558\uACE0 \uC8FC\uBCC0\uAE30\uAE30\uAC00 \uC5F0\uACB0\uB418\uBA74 \uC4F8 \uC218 \uC788\uC9C0\uB9CC, \uBCF4\uC99D\uC774 \uC5C6\uC5B4 \uACE0\uC7A5 \uC218\uB9AC \uBE44\uC6A9\uC744 \uB9E4\uC7A5\uC774 \uBAA8\uB450 \uBD80\uB2F4\uD558\uAC8C \uB429\uB2C8\uB2E4. \uAE30\uAE30\uAC12\uC774 \uB0AE\uC740 \uB300\uC2E0 \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uBE44\uC640 \uC0AC\uC6A9\uB8CC\uB294 \uC0C8 \uAE30\uAE30\uC640 \uAC19\uC73C\uBBC0\uB85C \uCD1D\uBE44\uC6A9\uC73C\uB85C \uD310\uB2E8\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC911\uACE0 \uAE30\uAE30\uC5D0\uC11C \uBA3C\uC800 \uD655\uC778\uD560 \uAC83\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC774 \uADF8 \uAE30\uAE30 \uBAA8\uB378\uACFC \uC6B4\uC601\uCCB4\uC81C \uBC84\uC804\uC744 \uC9C0\uC6D0\uD558\uB294\uC9C0 \uC9C0\uC6D0 \uBAA9\uB85D\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD654\uBA74 \uD130\uCE58 \uBD88\uB7C9, \uD3EC\uD2B8 \uC190\uC0C1, \uC800\uC7A5 \uC7A5\uCE58 \uC0C1\uD0DC\uB97C \uC9C1\uC811 \uCF1C\uC11C \uBD05\uB2C8\uB2E4.", "\uD504\uB9B0\uD130\uC640 \uB3C8\uD1B5, \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC5F0\uACB0 \uD3EC\uD2B8\uAC00 \uB9E4\uC7A5 \uAE30\uAE30\uC640 \uB9DE\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC774\uC804 \uB9E4\uC7A5\uC758 \uC790\uB8CC\uAC00 \uC9C0\uC6CC\uC84C\uB294\uC9C0, \uD504\uB85C\uADF8\uB7A8 \uB77C\uC774\uC120\uC2A4\uAC00 \uC774\uC804 \uAC00\uB2A5\uD55C\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC804\uC6D0 \uC5B4\uB311\uD130\uC640 \uCF00\uC774\uBE14\uC774 \uD568\uAED8 \uC624\uB294\uC9C0 \uD488\uBAA9\uC744 \uC801\uC2B5\uB2C8\uB2E4.", "\uC81C\uC870 \uC5F0\uB3C4\uAC00 \uC624\uB798\uB418\uBA74 \uBD80\uD488 \uC218\uAE09\uC774 \uC5B4\uB824\uC6CC \uACE0\uC7A5 \uB54C \uC218\uB9AC\uAC00 \uC548 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD310\uB9E4\uC790\uC5D0\uAC8C \uC791\uB3D9 \uC601\uC0C1\uC774\uB098 \uD604\uC7A5 \uC2DC\uC5F0\uC744 \uC694\uCCAD\uD574 \uCF1C\uC9C0\uB294 \uAC83 \uC774\uC0C1\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD6C\uC785 \uC804\uC5D0 \uAE30\uAE30 \uBAA8\uB378\uBA85\uC73C\uB85C \uD504\uB85C\uADF8\uB7A8 \uC5C5\uCCB4\uC5D0 \uC9C0\uC6D0 \uC5EC\uBD80\uB97C \uC9C1\uC811 \uBB3B\uB294 \uAC83\uC774 \uD310\uB9E4\uC790 \uB9D0\uBCF4\uB2E4 \uD655\uC2E4\uD569\uB2C8\uB2E4.", "\uC6B4\uC601\uCCB4\uC81C\uAC00 \uC624\uB798\uB41C \uAE30\uAE30\uB294 \uBCF4\uC548 \uC5C5\uB370\uC774\uD2B8\uAC00 \uB04A\uACA8 \uACB0\uC81C \uC5F0\uB3D9\uC774 \uAC70\uBD80\uB420 \uC218 \uC788\uC73C\uB2C8 \uBC84\uC804\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD310\uB9E4\uC790\uC5D0\uAC8C \uAD6C\uC785 \uC2DC\uAE30\uC640 \uC0AC\uC6A9 \uAE30\uAC04\uC744 \uBB3C\uC5B4 \uBCF4\uC99D \uC794\uC5EC \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD130\uCE58 \uD328\uB110\uC740 \uBAA8\uC11C\uB9AC\uAE4C\uC9C0 \uB20C\uB7EC \uBCF4\uACE0, \uD654\uBA74 \uD55C\uCABD\uC774 \uBC18\uC751\uD558\uC9C0 \uC54A\uC73C\uBA74 \uAD50\uCCB4 \uBE44\uC6A9\uC774 \uD06C\uBBC0\uB85C \uADF8 \uC790\uB9AC\uC5D0\uC11C \uAC70\uB985\uB2C8\uB2E4."] }, { "h": "\uC911\uACE0\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uC9E7\uAC8C \uC6B4\uC601\uD560 \uD31D\uC5C5\uC774\uB098 \uC784\uC2DC \uB9E4\uC7A5\uC5D0\uC11C \uAE30\uAE30\uAC12\uC744 \uC904\uC774\uACE0 \uC2F6\uC744 \uB54C \uB9DE\uC2B5\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uB85C \uD55C \uB300 \uB354 \uB450\uB824\uB294 \uB9E4\uC7A5\uB3C4 \uC911\uACE0\uAC00 \uC4F8\uBAA8 \uC788\uC2B5\uB2C8\uB2E4.", "\uC774\uBBF8 \uAC19\uC740 \uBAA8\uB378\uC744 \uC4F0\uACE0 \uC788\uC5B4 \uBD80\uD488\uACFC \uC124\uC815\uC744 \uC544\uB294 \uB9E4\uC7A5\uC740 \uC704\uD5D8\uC774 \uC801\uC2B5\uB2C8\uB2E4.", "\uBC18\uB300\uB85C \uD558\uB8E8 \uC885\uC77C \uBC14\uC05C \uB9E4\uC7A5\uC740 \uACE0\uC7A5 \uB54C \uC190\uC2E4\uC774 \uCEE4\uC11C \uBCF4\uC99D \uC788\uB294 \uC0C8 \uAE30\uAE30\uAC00 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uB294 \uC911\uACE0\uB77C\uB3C4 \uAC19\uC73C\uBBC0\uB85C \uC0AC\uC6A9\uB8CC\uAC00 \uD070 \uBE44\uC911\uC774\uBA74 \uC911\uACE0\uC758 \uC774\uC810\uC774 \uC791\uC2B5\uB2C8\uB2E4.", "\uC911\uACE0 \uAE30\uAE30\uAC12\uACFC \uC0C8 \uAE30\uAE30 \uC784\uB300\uB8CC\uB97C \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uB85C \uBE44\uAD50\uD574 \uBCF4\uBA74 \uC5B4\uB290 \uCABD\uC774 \uC801\uC740\uC9C0 \uBC14\uB85C \uB098\uC635\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uB85C \uB458 \uB54C\uB294 \uAC19\uC740 \uBAA8\uB378\uC774\uC5B4\uC57C \uC124\uC815\uC744 \uADF8\uB300\uB85C \uC62E\uAE38 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30 \uC6A9\uB3C4\uB77C\uBA74 \uD654\uBA74 \uC0C1\uD0DC\uBCF4\uB2E4 \uD3EC\uD2B8\uC640 \uC804\uC6D0\uBD80 \uC0C1\uD0DC\uAC00 \uB354 \uC911\uC694\uD569\uB2C8\uB2E4."] }, { "h": "\uBCF4\uC99D\uACFC \uC218\uB9AC\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uAC1C\uC778 \uAC04 \uAC70\uB798 \uC911\uACE0\uB294 \uBCF4\uC99D\uC774 \uC5C6\uACE0, \uC5C5\uCCB4\uAC00 \uC815\uBE44\uD55C \uC911\uACE0\uB294 \uC9E7\uC740 \uBCF4\uC99D\uC774 \uBD99\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C \uC218\uB9AC\uB97C \uBC1B\uC544 \uC8FC\uB294 \uACF3\uC774 \uC788\uB294\uC9C0 \uC0AC\uAE30 \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBD80\uD488 \uAD50\uCCB4 \uBE44\uC6A9\uACFC \uAE30\uAC04\uC740 \uAE30\uAE30 \uC138\uB300\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBCF4\uC99D\uC774 \uC5C6\uB294 \uAE30\uAE30\uB294 \uC608\uBE44 \uAE30\uAE30 \uC5C6\uC774 \uC6B4\uC601\uD558\uBA74 \uBA48\uCDC4\uC744 \uB54C \uACB0\uC81C\uAC00 \uB04A\uAE30\uBBC0\uB85C \uB300\uC548\uC744 \uB461\uB2C8\uB2E4.", "\uC815\uBE44 \uC911\uACE0\uB97C \uD30C\uB294 \uC5C5\uCCB4\uB294 \uC124\uCE58\uC640 \uD504\uB85C\uADF8\uB7A8 \uC5F0\uACB0\uAE4C\uC9C0 \uD574 \uC8FC\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uBE44\uAD50\uD574 \uBD05\uB2C8\uB2E4.", "\uC218\uB9AC \uCC3D\uAD6C\uAC00 \uC5C6\uB294 \uBAA8\uB378\uC740 \uACE0\uC7A5\uC774 \uACE7 \uAD50\uCCB4\uC774\uBBC0\uB85C \uCC98\uC74C\uBD80\uD130 \uC608\uBE44 \uAE30\uAE30 \uBE44\uC6A9\uAE4C\uC9C0 \uB123\uC5B4 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uC911\uACE0 \uC5C5\uCCB4 \uBCF4\uC99D\uC740 \uAE30\uAC04\uC774 \uC9E7\uC544\uB3C4 \uCD08\uAE30 \uBD88\uB7C9\uC744 \uAC70\uB97C \uC218 \uC788\uC5B4 \uAC1C\uC778 \uAC70\uB798\uBCF4\uB2E4 \uC548\uC804\uD55C \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC218\uB9AC \uCC3D\uAD6C \uC720\uBB34\uB294 \uBAA8\uB378\uBA85\uC73C\uB85C \uC81C\uC870\uC0AC\uC5D0 \uC9C1\uC811 \uBB3C\uC5B4 \uBCF4\uB294 \uAC83\uC774 \uD655\uC2E4\uD569\uB2C8\uB2E4.", "\uBCF4\uC99D\uC774 \uC5C6\uB294 \uAE30\uAE30\uB294 \uACE0\uC7A5 \uB54C \uACB0\uC81C \uACF5\uBC31\uC774 \uACE7 \uB9E4\uCD9C \uC190\uC2E4\uC774\uB77C \uD558\uB8E8 \uB9E4\uCD9C\uACFC \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uAC19\uC774 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uC815\uBE44 \uC911\uACE0 \uBCF4\uC99D\uC740 \uBCF4\uD1B5 \uC9E7\uC740 \uAE30\uAC04\uC774\uB77C \uBC1B\uC740 \uB0A0 \uBC14\uB85C \uC804\uCCB4 \uD14C\uC2A4\uD2B8\uB97C \uB05D\uB0B4\uB294 \uAC83\uC774 \uC911\uC694\uD569\uB2C8\uB2E4."] }, { "h": "\uAD6C\uC785 \uB4A4\uC5D0\uB294 \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uD504\uB85C\uADF8\uB7A8\uC744 \uC0C8\uB85C \uC124\uCE58\uD558\uACE0 \uB9E4\uC7A5 \uC815\uBCF4\uB85C \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4.", "\uC8FC\uBCC0\uAE30\uAE30\uB97C \uC5F0\uACB0\uD574 \uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uCD9C\uB825\xB7\uB9C8\uAC10 \uD55C \uBC14\uD034\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB300\uBE44\uB85C \uC124\uC815\uAC12\uACFC \uBA54\uB274 \uC790\uB8CC\uB97C \uBC31\uC5C5\uD574 \uB461\uB2C8\uB2E4.", "\uC0AC\uC6A9 \uC911 \uC774\uC0C1\uC774 \uC788\uC73C\uBA74 \uCD08\uAE30\uC5D0 \uAD50\uD658 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uD310\uB9E4\uC790\uC640 \uC815\uD55C \uB0B4\uC6A9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uB4A4 \uC774\uC0C1\uC774 \uC5C6\uC73C\uBA74 \uAD6C\uC785 \uC601\uC218\uC99D\uACFC \uAD6C\uC131\uD488 \uBAA9\uB85D\uC744 \uBCF4\uAD00\uD574 \uB098\uC911\uC5D0 \uB418\uD314 \uB54C \uC501\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8\uB294 \uC601\uC5C5 \uC804 \uD55C\uAC00\uD55C \uC2DC\uAC04\uC5D0 \uC2E4\uC81C \uBA54\uB274\uB85C \uD574\uC57C \uC8FC\uBCC0\uAE30\uAE30 \uBB38\uC81C\uAE4C\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8\uC5D0\uC11C \uBC1C\uACAC\uD55C \uBB38\uC81C\uB294 \uC0AC\uC9C4\uACFC \uD568\uAED8 \uD310\uB9E4\uC790\uC5D0\uAC8C \uC54C\uB824 \uAD50\uD658 \uC870\uAC74\uC744 \uC801\uC6A9\uBC1B\uC2B5\uB2C8\uB2E4.", "\uAD6C\uC131\uD488 \uBAA9\uB85D\uC5D0 \uC5B4\uB311\uD130 \uADDC\uACA9\uACFC \uCF00\uC774\uBE14 \uC885\uB958\uB97C \uC801\uC5B4 \uB450\uBA74 \uB098\uC911\uC5D0 \uBD84\uC2E4\uD588\uC744 \uB54C \uAC19\uC740 \uADDC\uACA9\uC744 \uC27D\uAC8C \uAD6C\uD569\uB2C8\uB2E4.", "\uC218\uB9AC \uCC3D\uAD6C\uAC00 \uC788\uB294 \uBAA8\uB378\uC774\uB77C\uB3C4 \uBD80\uD488 \uC7AC\uACE0\uAC00 \uC5C6\uC73C\uBA74 \uAE30\uAC04\uC774 \uAE38\uC5B4\uC9C0\uB2C8 \uC7AC\uACE0 \uC5EC\uBD80\uAE4C\uC9C0 \uBB3C\uC5B4 \uB461\uB2C8\uB2E4.", "\uCD08\uAE30\uD654 \uB4A4 \uB9E4\uC7A5 \uC815\uBCF4\uB85C \uC7AC\uC124\uC815\uD558\uACE0 \uBC31\uC5C5\uC744 \uB9CC\uB4ED\uB2C8\uB2E4."] }], "steps": { "h": "\uC911\uACE0 \uAD6C\uC785 \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uBAA8\uB378\uC778\uC9C0 \uBAA9\uB85D\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uC0C1\uD0DC\uC640 \uD3EC\uD2B8, \uAD6C\uC131\uD488\uC744 \uC9C1\uC811 \uBD05\uB2C8\uB2E4.", "\uBCF4\uC99D\uACFC \uC218\uB9AC \uAC00\uB2A5 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC124\uCE58 \uB4A4 \uC804\uCCB4 \uD14C\uC2A4\uD2B8\uB97C \uD569\uB2C8\uB2E4.", "\uAD6C\uC785 \uC601\uC218\uC99D\uACFC \uAD6C\uC131\uD488 \uBAA9\uB85D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC911\uACE0\uC640 \uC0C8 \uAE30\uAE30 \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uC911\uACE0", "\uC0C8 \uAE30\uAE30"], "rows": [["\uAE30\uAE30\uAC12", "\uB0AE\uC74C", "\uB192\uC74C"], ["\uBCF4\uC99D", "\uC5C6\uAC70\uB098 \uC9E7\uC74C", "\uC788\uC74C"], ["\uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC", "\uAC19\uC74C", "\uAC19\uC74C"], ["\uBD80\uD488 \uC218\uAE09", "\uC138\uB300\uC5D0 \uB530\uB77C", "\uC6D0\uD65C"], ["\uC124\uCE58 \uC9C0\uC6D0", "\uC5C5\uCCB4 \uC911\uACE0\uB9CC", "\uD3EC\uD568"]] }, "faq": [["\uC911\uACE0 \uD3EC\uC2A4\uAE30\uC5D0 \uD504\uB85C\uADF8\uB7A8\uC744 \uC0C8\uB85C \uAE54 \uC218 \uC788\uB098\uC694?", "\uC9C0\uC6D0 \uBAA8\uB378\uC774\uBA74 \uB429\uB2C8\uB2E4. \uB77C\uC774\uC120\uC2A4\uB294 \uB9E4\uC7A5 \uBA85\uC758\uB85C \uC0C8\uB85C \uBC1C\uAE09\uBC1B\uC2B5\uB2C8\uB2E4."], ["\uC911\uACE0 \uAE30\uAE30\uC5D0 \uB0A8\uC740 \uC774\uC804 \uB9E4\uC7A5 \uC790\uB8CC\uB294\uC694?", "\uAD6C\uC785 \uC804\uC5D0 \uCD08\uAE30\uD654\uB97C \uD655\uC778\uD558\uACE0, \uC9C1\uC811 \uB2E4\uC2DC \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4. \uCD08\uAE30\uD654 \uB4A4\uC5D0\uB3C4 \uC800\uC7A5 \uC7A5\uCE58\uC5D0 \uC790\uB8CC\uAC00 \uB0A8\uC744 \uC218 \uC788\uC73C\uB2C8 \uD504\uB85C\uADF8\uB7A8 \uC5C5\uCCB4\uC5D0 \uCD08\uAE30\uD654 \uBC29\uBC95\uC744 \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uC911\uACE0 \uAE30\uAE30\uB3C4 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC640 \uC5F0\uB3D9\uB418\uB098\uC694?", "\uD504\uB85C\uADF8\uB7A8\uC774 \uC9C0\uC6D0\uD558\uBA74 \uB429\uB2C8\uB2E4. \uD3EC\uD2B8\uC640 \uC5F0\uACB0 \uBC29\uC2DD\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC911\uACE0 \uAD6C\uC785\uACFC \uC784\uB300 \uC911 \uC5B4\uB290 \uCABD\uC774 \uB098\uC740\uAC00\uC694?", "\uC6B4\uC601 \uAE30\uAC04\uACFC \uACE0\uC7A5 \uB300\uC751\uC744 \uAE30\uC900\uC73C\uB85C \uBD05\uB2C8\uB2E4. \uBCF4\uC99D\uC774 \uD544\uC694\uD558\uBA74 \uC784\uB300\uAC00 \uD3B8\uD569\uB2C8\uB2E4. \uBCF4\uC99D \uC5C6\uC774 \uC6B4\uC601\uD560 \uB9E4\uC7A5\uC740 \uC608\uBE44 \uAE30\uAE30 \uBE44\uC6A9\uAE4C\uC9C0 \uB123\uC5B4 \uBE44\uAD50\uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58\uBE44\uC6A9", "\uD3EC\uC2A4\uAE30\uC784\uB300", "\uD3EC\uC2A4\uAE30\uAD50\uCCB4\uC2DC\uAE30"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD3EC\uC2A4\uAE30\uAD50\uCCB4\uC2DC\uAE30", "product": "\uD3EC\uC2A4\uAE30", "tail": "\uAD50\uCCB4 \uC2DC\uAE30", "title": "\uD3EC\uC2A4\uAE30\uB294 \uC5B8\uC81C \uAD50\uCCB4\uD558\uB098\uC694? \u2014 \uB290\uB824\uC9D0\xB7\uC9C0\uC6D0 \uC885\uB8CC\xB7\uB9AC\uBAA8\uB378\uB9C1\uC758 \uC138 \uAC00\uC9C0 \uC2E0\uD638", "desc": "\uD3EC\uC2A4\uAE30\uB97C \uAD50\uCCB4\uD560 \uC2DC\uC810\uC744 \uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uC885\uB8CC, \uAE30\uAE30 \uC131\uB2A5 \uC800\uD558, \uB9AC\uBAA8\uB378\uB9C1\uC774\uB098 \uC5C5\uC885 \uBCC0\uACBD\uC758 \uC138 \uAC00\uC9C0 \uC2E0\uD638\uB85C \uB098\uB204\uACE0, \uAD50\uCCB4 \uC804\uC5D0 \uC790\uB8CC\uB97C \uC62E\uAE30\uB294 \uBC29\uBC95\uACFC \uAD50\uCCB4 \uB2F9\uC77C \uC601\uC5C5 \uACF5\uBC31\uC744 \uC904\uC774\uB294 \uC21C\uC11C, \uAD50\uCCB4 \uB9D0\uACE0 \uAC00\uB2A5\uD55C \uB300\uC548\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD3EC\uC2A4\uAE30 \uAD50\uCCB4 \uC2DC\uC810\uC740 \uD504\uB85C\uADF8\uB7A8\uC774 \uB354 \uC774\uC0C1 \uADF8 \uAE30\uAE30\uB97C \uC9C0\uC6D0\uD558\uC9C0 \uC54A\uC744 \uB54C, \uC8FC\uBB38 \uCC98\uB9AC\uAC00 \uB290\uB824\uC838 \uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC904\uC774 \uC0DD\uAE38 \uB54C, \uB9AC\uBAA8\uB378\uB9C1\uC774\uB098 \uC5C5\uC885 \uBCC0\uACBD\uC73C\uB85C \uAE30\uB2A5\uC774 \uBC14\uB014 \uB54C \uC138 \uAC00\uC9C0\uC785\uB2C8\uB2E4. \uACE0\uC7A5 \uB4A4\uC5D0 \uBC14\uAFB8\uBA74 \uC601\uC5C5 \uACF5\uBC31\uC774 \uC0DD\uAE30\uBBC0\uB85C \uC2E0\uD638\uAC00 \uBCF4\uC77C \uB54C \uBBF8\uB9AC \uC900\uBE44\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uAD50\uCCB4 \uC2E0\uD638\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8\uAC00 \uB354 \uC774\uC0C1 \uADF8 \uAE30\uAE30\uC5D0 \uC81C\uACF5\uB418\uC9C0 \uC54A\uB294\uB2E4\uB294 \uC548\uB0B4\uAC00 \uC624\uBA74 \uCCAB \uC2E0\uD638\uC785\uB2C8\uB2E4.", "\uC8FC\uBB38 \uD654\uBA74 \uC804\uD658\uC774 \uB290\uB824\uC9C0\uAC70\uB098 \uD53C\uD06C \uC2DC\uAC04\uC5D0 \uBA48\uCD94\uB294 \uC77C\uC774 \uC7A6\uC544\uC9C0\uBA74 \uC131\uB2A5 \uD55C\uACC4\uC785\uB2C8\uB2E4.", "\uD130\uCE58 \uBD88\uB7C9\uC774\uB098 \uD3EC\uD2B8 \uC811\uCD09 \uBD88\uB7C9\uC774 \uBC18\uBCF5\uB418\uBA74 \uC218\uB9AC\uBCF4\uB2E4 \uAD50\uCCB4\uAC00 \uB098\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774\uB098 \uAC04\uD3B8\uACB0\uC81C \uAC19\uC740 \uC0C8 \uAE30\uB2A5\uC774 \uAD6C\uD615 \uAE30\uAE30\uC5D0\uC11C \uC548 \uB418\uBA74 \uB9E4\uC7A5 \uC6B4\uC601\uC5D0 \uC81C\uC57D\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uB9AC\uBAA8\uB378\uB9C1\uC73C\uB85C \uCE74\uC6B4\uD130 \uC704\uCE58\uAC00 \uBC14\uB00C\uAC70\uB098 \uC5C5\uC885\uC774 \uBC14\uB00C\uBA74 \uAE30\uAE30 \uC885\uB958 \uC790\uCCB4\uB97C \uB2E4\uC2DC \uC815\uD569\uB2C8\uB2E4.", "\uBD80\uD488 \uC218\uAE09\uC774 \uB04A\uACA8 \uC218\uB9AC \uAE30\uAC04\uC774 \uAE38\uC5B4\uC9C0\uB294 \uAC83\uB3C4 \uAD50\uCCB4 \uC2E0\uD638\uC785\uB2C8\uB2E4.", "\uAE30\uAE30 \uC0AC\uC6A9 \uC5F0\uC218\uB294 \uCC38\uACE0\uC77C \uBFD0\uC774\uACE0, \uC704 \uC2E0\uD638\uAC00 \uC5C6\uC73C\uBA74 \uC624\uB798 \uC368\uB3C4 \uB429\uB2C8\uB2E4.", "\uC2E0\uD638\uAC00 \uB450 \uAC00\uC9C0 \uC774\uC0C1 \uACB9\uCE58\uBA74 \uC218\uB9AC\uBCF4\uB2E4 \uAD50\uCCB4 \uCABD\uC774 \uBE44\uC6A9\uC774 \uC801\uC740 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uC885\uB8CC \uC548\uB0B4\uBB38\uC740 \uBCF4\uAD00\uD574 \uB450\uBA74 \uAD50\uCCB4 \uC2DC\uC810\uC744 \uC815\uD560 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC8FC\uBB38 \uD654\uBA74\uC774 \uBA48\uCD94\uB294 \uD69F\uC218\uB97C \uC77C\uC8FC\uC77C \uC801\uC5B4 \uBCF4\uBA74 \uC131\uB2A5 \uD55C\uACC4\uC778\uC9C0 \uC77C\uC2DC\uC801 \uBB38\uC81C\uC778\uC9C0 \uAD6C\uBD84\uB429\uB2C8\uB2E4."] }, { "h": "\uAD50\uCCB4 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uC900\uBE44\uD558\uB098\uC694?", "p": ["\uBA54\uB274, \uB9E4\uCD9C \uC790\uB8CC, \uACE0\uAC1D \uC815\uBCF4\uB97C \uB0B4\uB824\uBC1B\uC544 \uC0C8 \uAE30\uAE30\uC5D0 \uC62E\uAE38 \uC218 \uC788\uAC8C \uD569\uB2C8\uB2E4.", "\uC0C8 \uD504\uB85C\uADF8\uB7A8\uC774 \uAE30\uC874 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC640 \uD504\uB9B0\uD130\uB97C \uC9C0\uC6D0\uD558\uB294\uC9C0 \uD655\uC778\uD574 \uC8FC\uBCC0\uAE30\uAE30\uAE4C\uC9C0 \uBC14\uAFC0\uC9C0 \uC815\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB2F9\uC77C \uC601\uC5C5\uC744 \uC274 \uC218 \uC5C6\uC73C\uBA74 \uC601\uC5C5 \uC804\uC774\uB098 \uB9C8\uAC10 \uB4A4 \uC2DC\uAC04\uB300\uB85C \uC124\uCE58\uB97C \uC7A1\uC2B5\uB2C8\uB2E4.", "\uC9C1\uC6D0\uC774 \uC0C8 \uD654\uBA74\uC5D0 \uC801\uC751\uD560 \uC2DC\uAC04\uC744 \uB450\uACE0, \uBC14\uB00C\uB294 \uC870\uC791 \uC21C\uC11C\uB97C \uD55C \uC7A5\uC73C\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uAE30\uC874 \uAE30\uAE30\uB97C \uC784\uB300 \uC911\uC774\uBA74 \uBC18\uB0A9\uACFC \uC0C8 \uC57D\uC815\uC744 \uD55C \uB0A0\uB85C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uAD50\uCCB4 \uBE44\uC6A9\uACFC \uC77C\uC815\uC740 \uAD6C\uC131\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uC4F0\uC9C0 \uC54A\uC744 \uAE30\uC874 \uAE30\uAE30\uB294 \uCD08\uAE30\uD654\uD574 \uBCF4\uAD00\uD558\uAC70\uB098 \uC911\uACE0\uB85C \uB118\uAE30\uB418, \uC784\uB300 \uAE30\uAE30\uB294 \uBC18\uB0A9\uD569\uB2C8\uB2E4.", "\uC0C8 \uD504\uB85C\uADF8\uB7A8\uC774 \uAE30\uC874 \uBA54\uB274 \uC790\uB8CC \uD615\uC2DD\uC744 \uC77D\uB294\uC9C0 \uBBF8\uB9AC \uD655\uC778\uD558\uBA74 \uC7AC\uC785\uB825 \uC2DC\uAC04\uC744 \uC904\uC785\uB2C8\uB2E4.", "\uAD50\uCCB4 \uC804\uC5D0 \uAE30\uC874 \uAE30\uAE30\uC758 \uC124\uC815\uAC12(\uD504\uB9B0\uD130 \uBD84\uB958\xB7\uAD8C\uD55C)\uC744 \uD654\uBA74 \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uAE30\uBA74 \uC0C8 \uAE30\uAE30\uC5D0 \uC62E\uAE30\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC0C8 \uAE30\uAE30\uAC00 \uC624\uAE30 \uC804\uC5D0 \uBA54\uB274 \uC790\uB8CC \uD615\uC2DD\uC744 \uC5C5\uCCB4\uC5D0 \uBCF4\uB0B4 \uBCC0\uD658\uC774 \uB418\uB294\uC9C0 \uBBF8\uB9AC \uD655\uC778\uD558\uBA74 \uAD50\uCCB4 \uB2F9\uC77C \uC785\uB825 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uAD50\uCCB4 \uB2F9\uC77C\uC5D0\uB294 \uC5B4\uB5BB\uAC8C \uC9C4\uD589\uB418\uB098\uC694?", "p": ["\uC0C8 \uAE30\uAE30\uB97C \uC124\uCE58\uD558\uACE0 \uBA54\uB274 \uC790\uB8CC\uB97C \uC62C\uB9B0 \uB4A4 \uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uCD9C\uB825\xB7\uB9C8\uAC10\uC744 \uD55C \uBC14\uD034 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uAE30\uC874 \uAE30\uAE30\uB294 \uC790\uB8CC \uBC31\uC5C5\uC774 \uB05D\uB09C \uAC83\uC744 \uD655\uC778\uD55C \uB4A4 \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uC5F0\uB3D9\uACFC \uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774 \uC0C8 \uAE30\uAE30\uC5D0\uC11C \uB418\uB294\uC9C0 \uC2E4\uC81C \uC8FC\uBB38\uC73C\uB85C \uBD05\uB2C8\uB2E4.", "\uB2F9\uC77C \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB97C \uCD9C\uB825\uD574 \uB9E4\uCD9C\uC774 \uBE60\uC9D0\uC5C6\uC774 \uC7A1\uD614\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uCCAB \uC8FC\uB294 \uC9C1\uC6D0 \uBB38\uC758\uAC00 \uB298\uC5B4\uB098\uBBC0\uB85C \uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uB97C \uB208\uC5D0 \uB744\uAC8C \uB461\uB2C8\uB2E4.", "\uB2F9\uC77C \uC601\uC5C5 \uC911\uC5D0 \uAD50\uCCB4\uD574\uC57C \uD558\uBA74 \uD53C\uD06C \uC2DC\uAC04\uC744 \uD53C\uD558\uACE0 \uC784\uC2DC\uB85C \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uB2E8\uB3C5 \uACB0\uC81C\uB97C \uC5F4\uC5B4 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB2F9\uC77C \uC9C1\uC6D0\uC774 \uBC14\uB010 \uD654\uBA74\uC744 \uBCF4\uACE0 \uC9C8\uBB38\uD560 \uC218 \uC788\uB3C4\uB85D \uC124\uCE58 \uAE30\uC0AC\uAC00 \uB5A0\uB098\uAE30 \uC804 \uC2DC\uC5F0\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4."] }, { "h": "\uAD50\uCCB4 \uB9D0\uACE0 \uB2E4\uB978 \uBC29\uBC95\uC740 \uC5C6\uB098\uC694?", "p": ["\uB290\uB824\uC9D0\uC774 \uC800\uC7A5 \uC7A5\uCE58 \uB54C\uBB38\uC774\uBA74 \uBD80\uD488 \uAD50\uCCB4\uB85C \uD574\uACB0\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8\uB9CC \uBC14\uAFB8\uB294 \uBC29\uBC95\uB3C4 \uC788\uC9C0\uB9CC \uAE30\uAE30 \uC9C0\uC6D0 \uC5EC\uBD80\uB97C \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uB97C \uB450\uACE0 \uACE0\uC7A5 \uB54C\uB9CC \uBC14\uAFB8\uB294 \uBC29\uC2DD\uC740 \uD53C\uD06C \uC2DC\uAC04\uC774 \uAE34 \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uB9AC\uBAA8\uB378\uB9C1 \uB54C \uC7A5\uBE44\uB97C \uB2E4\uC2DC \uC4F0\uB294 \uD310\uB2E8\uC740 \uAE30\uC874 \uAE00 '\uB9AC\uBAA8\uB378\uB9C1 \uB54C \uC7A5\uBE44\uB294 \uC5B4\uB5BB\uAC8C \uD558\uB098'\uC5D0\uC11C \uC774\uC5B4\uC9D1\uB2C8\uB2E4.", "\uBD80\uD488 \uAD50\uCCB4\uB85C \uD574\uACB0\uB418\uB294\uC9C0 \uD310\uB2E8\uD558\uB824\uBA74 \uC99D\uC0C1\uC744 \uC801\uC5B4 \uACE0\uAC1D\uC13C\uD130\uC5D0 \uBA3C\uC800 \uBB3B\uB294 \uAC83\uC774 \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uC544\uB07C\uB294 \uAE38\uC785\uB2C8\uB2E4.", "\uAD50\uCCB4 \uC804\uD6C4 \uB9E4\uCD9C \uC790\uB8CC\uAC00 \uB098\uB258\uC9C0 \uC54A\uB3C4\uB85D \uAC19\uC740 \uD504\uB85C\uADF8\uB7A8\uC774\uBA74 \uC790\uB8CC\uB97C \uC774\uC5B4 \uBD99\uC774\uACE0, \uB2E4\uB978 \uD504\uB85C\uADF8\uB7A8\uC774\uBA74 \uAE30\uAC04\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30 \uC6B4\uC601\uC740 \uC124\uC815\uAC12\uC744 \uBBF8\uB9AC \uB9DE\uCDB0 \uB450\uC5B4\uC57C \uACE0\uC7A5 \uB54C \uBC14\uB85C \uBC14\uAFC0 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBD80\uD488 \uAD50\uCCB4\uB85C \uBC84\uD2F8 \uC218 \uC788\uB294 \uAE30\uAC04\uACFC \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uBE44\uAD50\uD574 \uC5B4\uB290 \uCABD\uC774 \uB9E4\uC7A5\uC5D0 \uB9DE\uB294\uC9C0 \uC815\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uAE30\uC874 \uAE30\uAE30 \uC790\uB8CC\uB294 \uC138\uBB34 \uBCF4\uAD00 \uAE30\uAC04\uC774 \uC9C0\uB0A0 \uB54C\uAE4C\uC9C0 \uBC31\uC5C5 \uD30C\uC77C\uB85C \uB0A8\uACA8 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uCCAB \uC8FC \uC9C1\uC6D0 \uBB38\uC758\uB97C \uBAA8\uC544 \uC124\uC815\uC744 \uC870\uC815\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4\uD55C \uB0A0\uC9DC\uC640 \uBAA8\uB378\uBA85\uC744 \uC801\uC5B4 \uB2E4\uC74C \uAD50\uCCB4 \uC2DC\uC810 \uD310\uB2E8\uC5D0 \uC501\uB2C8\uB2E4."] }], "steps": { "h": "\uAD50\uCCB4 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uAD50\uCCB4 \uC2E0\uD638\uB97C \uD655\uC778\uD558\uACE0 \uC790\uB8CC\uB97C \uBC31\uC5C5\uD569\uB2C8\uB2E4.", "\uC0C8 \uAE30\uAE30\xB7\uD504\uB85C\uADF8\uB7A8\uC774 \uAE30\uC874 \uC8FC\uBCC0\uAE30\uAE30\uB97C \uC9C0\uC6D0\uD558\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC5C5 \uACF5\uBC31\uC774 \uC801\uC740 \uC2DC\uAC04\uB300\uB85C \uC124\uCE58\uB97C \uC7A1\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uC804\uCCB4 \uD14C\uC2A4\uD2B8\uC640 \uB9C8\uAC10 \uB300\uC870\uB97C \uD569\uB2C8\uB2E4.", "\uAE30\uC874 \uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD574 \uBC18\uB0A9\uD558\uAC70\uB098 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uAD50\uCCB4 \uC2E0\uD638\uC640 \uB300\uC751", "head": ["\uC2E0\uD638", "\uC6D0\uC778", "\uB300\uC751"], "rows": [["\uC5C5\uB370\uC774\uD2B8 \uC911\uB2E8", "\uAE30\uAE30 \uC9C0\uC6D0 \uC885\uB8CC", "\uAD50\uCCB4"], ["\uB290\uB824\uC9D0", "\uC131\uB2A5\xB7\uC800\uC7A5 \uC7A5\uCE58", "\uBD80\uD488 \uAD50\uCCB4 \uB610\uB294 \uAD50\uCCB4"], ["\uC5F0\uB3D9 \uBD88\uAC00", "\uAD6C\uD615 \uD3EC\uD2B8\xB7\uD504\uB85C\uADF8\uB7A8", "\uAD50\uCCB4"], ["\uB9AC\uBAA8\uB378\uB9C1", "\uBC30\uCE58\xB7\uAE30\uB2A5 \uBCC0\uACBD", "\uAD6C\uC131 \uC7AC\uAC80\uD1A0"]] }, "faq": [["\uD3EC\uC2A4\uAE30\uB294 \uBCF4\uD1B5 \uBA87 \uB144 \uC4F0\uB098\uC694?", "\uAE30\uAE30\uC640 \uC0AC\uC6A9\uB7C9\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC815\uD574\uC9C4 \uAE30\uAC04\uC740 \uC5C6\uC2B5\uB2C8\uB2E4. \uC9C0\uC6D0 \uC885\uB8CC\uC640 \uC131\uB2A5 \uC2E0\uD638\uB97C \uAE30\uC900\uC73C\uB85C \uBD05\uB2C8\uB2E4."], ["\uAD50\uCCB4\uD558\uBA74 \uBA54\uB274\uB97C \uB2E4\uC2DC \uC785\uB825\uD574\uC57C \uD558\uB098\uC694?", "\uC790\uB8CC\uB97C \uB0B4\uBCF4\uB0B4 \uC0C8 \uAE30\uAE30\uC5D0 \uC62C\uB9AC\uBA74 \uB2E4\uC2DC \uC785\uB825\uD558\uC9C0 \uC54A\uC544\uB3C4 \uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uD504\uB85C\uADF8\uB7A8\uC774 \uBC14\uB00C\uBA74 \uD615\uC2DD \uBCC0\uD658\uC774 \uD544\uC694\uD569\uB2C8\uB2E4."], ["\uAD50\uCCB4 \uC911\uC5D0 \uC601\uC5C5\uC744 \uC26C\uC5B4\uC57C \uD558\uB098\uC694?", "\uC601\uC5C5 \uC804\uC774\uB098 \uB9C8\uAC10 \uB4A4 \uC2DC\uAC04\uB300\uC5D0 \uC124\uCE58\uD558\uBA74 \uC26C\uC9C0 \uC54A\uC544\uB3C4 \uB429\uB2C8\uB2E4."], ["\uAE30\uC874 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB294 \uADF8\uB300\uB85C \uC4F0\uB098\uC694?", "\uC0C8 \uD504\uB85C\uADF8\uB7A8\uC774 \uC9C0\uC6D0\uD558\uBA74 \uADF8\uB300\uB85C \uC501\uB2C8\uB2E4. \uC9C0\uC6D0 \uBAA9\uB85D\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4. \uC9C0\uC6D0 \uBAA9\uB85D\uC5D0 \uC5C6\uC73C\uBA74 \uB2E8\uB9D0\uAE30 \uAD50\uCCB4 \uBE44\uC6A9\uAE4C\uC9C0 \uB123\uC5B4 \uCD1D\uBE44\uC6A9\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4."]], "related": ["\uD3EC\uC2A4\uAE30\uC124\uCE58", "\uC911\uACE0\uD3EC\uC2A4\uAE30", "\uD3EC\uC2A4\uAE30\uD574\uC9C0\uBC18\uB0A9"], "posts": ["/post/remodeling-devices/"], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uC124\uCE58\uBE44\uC6A9", "title": "\uD0A4\uC624\uC2A4\uD06C \uC124\uCE58\uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uB098\uB258\uB098\uC694? \u2014 \uBCF8\uCCB4\xB7\uACB0\uC81C\uBAA8\uB4C8\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uC124\uCE58\uBE44\uC758 \uB124 \uD56D\uBAA9", "desc": "\uD0A4\uC624\uC2A4\uD06C \uC124\uCE58\uBE44\uC6A9\uC774 \uBCF8\uCCB4 \uAE30\uAE30\uAC12, \uCE74\uB4DC\uACB0\uC81C \uBAA8\uB4C8, \uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC, \uC124\uCE58 \uCD9C\uC7A5\uBE44\uB85C \uB098\uB258\uB294 \uAD6C\uC870\uC640 \uB9E4\uC7A5 \uADDC\uBAA8\uC640 \uBA54\uB274 \uC218\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uB294 \uD56D\uBAA9, \uC784\uB300\uC640 \uAD6C\uB9E4\uC5D0\uC11C\uC758 \uCC28\uC774, \uACAC\uC801\uC11C \uD655\uC778 \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD0A4\uC624\uC2A4\uD06C \uC124\uCE58\uBE44\uC6A9\uC740 \uBCF8\uCCB4 \uAE30\uAE30\uAC12, \uCE74\uB4DC\uACB0\uC81C \uBAA8\uB4C8\uACFC \uAC00\uB9F9\uC810 \uB4F1\uB85D, \uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8 \uC124\uCE58\uBE44\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC, \uC124\uCE58 \uCD9C\uC7A5\uBE44 \uB124 \uD56D\uBAA9\uC73C\uB85C \uB098\uB258\uBA70 \uAE08\uC561\uC740 \uAE30\uAE30 \uD06C\uAE30\uC640 \uAD6C\uC131\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC838 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uD3EC\uC2A4\uAE30\uC640 \uB2EC\uB9AC \uACB0\uC81C \uBAA8\uB4C8\uC774 \uBCF8\uCCB4\uC5D0 \uD568\uAED8 \uB4E4\uC5B4\uAC00\uBBC0\uB85C \uCE74\uB4DC\uB2E8\uB9D0\uAE30 \uD56D\uBAA9\uC774 \uC548\uC5D0 \uBB36\uC5EC \uC788\uB294\uC9C0 \uB530\uB85C\uC778\uC9C0 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uBE44\uC6A9 \uD56D\uBAA9\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uBCF8\uCCB4\uB294 \uD654\uBA74 \uD06C\uAE30\uC640 \uAC70\uCE58 \uBC29\uC2DD(\uC2A4\uD0E0\uB4DC\uD615\xB7\uBCBD\uAC78\uC774\uD615\xB7\uD0C1\uC0C1\uD615)\uC5D0 \uB530\uB77C \uAE30\uAE30\uAC12\uC774 \uB2EC\uB77C\uC9C0\uACE0, \uD654\uBA74\uC774 \uD074\uC218\uB85D \uC190\uB2D8\uC774 \uBCF4\uAE30 \uD3B8\uD55C \uB300\uC2E0 \uC790\uB9AC\uB97C \uB354 \uCC28\uC9C0\uD569\uB2C8\uB2E4.", "\uCE74\uB4DC\uACB0\uC81C \uBAA8\uB4C8\uC740 \uBCF8\uCCB4\uC5D0 \uB0B4\uC7A5\uB418\uAC70\uB098 \uC678\uBD80 \uB2E8\uB9D0\uAE30\uB97C \uBD99\uC774\uB294 \uBC29\uC2DD\uC774 \uC788\uC73C\uBA70, \uC5B4\uB290 \uCABD\uC774\uB4E0 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uD568\uAED8 \uD544\uC694\uD558\uBBC0\uB85C \uADF8 \uC808\uCC28\uAC00 \uBE44\uC6A9 \uD56D\uBAA9 \uC548\uC5D0 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8\uC740 \uC124\uCE58\uBE44\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC\uB85C \uB098\uB258\uACE0, \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uBA54\uB274 \uC218\uC815\uACFC \uC6D0\uACA9 \uC9C0\uC6D0\uC774 \uD3EC\uD568\uC778\uC9C0\uAC00 \uB4A4\uC5D0 \uB098\uAC00\uB294 \uB3C8\uC744 \uC88C\uC6B0\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uCD9C\uC7A5\uBE44\uB294 \uAE30\uAE30\uB97C \uC138\uC6B0\uACE0 \uC804\uC6D0\uACFC \uD1B5\uC2E0\uC744 \uC5F0\uACB0\uD558\uBA70 \uBA54\uB274\uB97C \uC785\uB825\uD558\uB294 \uC791\uC5C5\uC758 \uAC12\uC73C\uB85C, \uBA54\uB274 \uC785\uB825 \uB300\uD589\uC774 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uD504\uB9B0\uD130\uC640 \uD638\uCD9C\uBCA8, \uBC14\uCF54\uB4DC \uB9AC\uB354\uCC98\uB7FC \uC120\uD0DD \uC7A5\uCE58\uB294 \uAC01\uAC01 \uBCC4\uB3C4 \uD56D\uBAA9\uC774\uBBC0\uB85C \uB9E4\uC7A5\uC5D0 \uD544\uC694\uD55C \uAC83\uB9CC \uACE0\uB985\uB2C8\uB2E4.", "\uD604\uAE08 \uACB0\uC81C\uB97C \uBC1B\uB294 \uBAA8\uB378\uC740 \uC9C0\uD3D0 \uC778\uC2DD\uAE30\uAC00 \uCD94\uAC00\uB3FC \uAE30\uAE30\uAC12\uC774 \uC62C\uB77C\uAC00\uBBC0\uB85C \uCE74\uB4DC \uC804\uC6A9\uC73C\uB85C \uD560\uC9C0 \uBA3C\uC800 \uC815\uD569\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uB124 \uD56D\uBAA9\uC774 \uB098\uB258\uC5B4 \uC788\uC9C0 \uC54A\uC73C\uBA74 \uB098\uB220 \uB2EC\uB77C\uACE0 \uD574\uC57C \uC784\uB300\xB7\uAD6C\uB9E4 \uBE44\uAD50\uC640 \uB098\uC911 \uCCAD\uAD6C\uC11C \uB300\uC870\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uB9E4\uC7A5\uC5D0 \uB530\uB77C \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uBA54\uB274\uAC00 \uB9CE\uACE0 \uC635\uC158\uC774 \uBCF5\uC7A1\uD55C \uB9E4\uC7A5\uC740 \uBA54\uB274 \uC785\uB825 \uC2DC\uAC04\uC774 \uAE38\uC5B4 \uC124\uCE58\uBE44\uAC00 \uC62C\uB77C\uAC00\uACE0, \uC0AC\uC9C4\uC744 \uB123\uC73C\uB824\uBA74 \uC0AC\uC9C4 \uC900\uBE44\uB3C4 \uB9E4\uC7A5 \uBAAB\uC785\uB2C8\uB2E4.", "\uC190\uB2D8 \uD68C\uC804\uC774 \uBE60\uB978 \uB9E4\uC7A5\uC740 \uAE30\uAE30\uB97C \uB450 \uB300 \uC774\uC0C1 \uB450\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uAE30\uAE30\uAC12\uC774 \uB300\uC218\uB9CC\uD07C \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30\uC640 \uC5F0\uB3D9\uD574 \uC8FC\uBC29 \uCD9C\uB825\uAE4C\uC9C0 \uD558\uB824\uBA74 \uC5F0\uB3D9 \uC124\uC815 \uC791\uC5C5\uC774 \uB354\uD574\uC9C0\uBBC0\uB85C \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC744 \uBBF8\uB9AC \uC54C\uB824 \uB461\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC8FC\uBB38\uACFC \uD0A4\uC624\uC2A4\uD06C \uC8FC\uBB38\uC744 \uD55C \uD654\uBA74\uC5D0\uC11C \uBCF4\uB824\uBA74 \uD1B5\uD569 \uAE30\uB2A5\uC774 \uC6D4 \uC0AC\uC6A9\uB8CC \uD56D\uBAA9\uC73C\uB85C \uBD99\uC2B5\uB2C8\uB2E4.", "\uBCBD\uAC78\uC774\uD615\uC740 \uBCBD \uBCF4\uAC15\uC774\uB098 \uBC30\uC120 \uB9E4\uB9BD\uC774 \uD544\uC694\uD560 \uC218 \uC788\uC5B4 \uC2DC\uACF5 \uD56D\uBAA9\uC774 \uC0DD\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uD504\uB79C\uCC28\uC774\uC988\uB294 \uBCF8\uC0AC \uC9C0\uC815 \uAE30\uAE30\uC640 \uD504\uB85C\uADF8\uB7A8\uC774 \uC788\uC5B4 \uD56D\uBAA9\uC774 \uACE0\uC815\uB418\uB294 \uC77C\uC774 \uB9CE\uC73C\uB2C8 \uBCF8\uC0AC \uC9C0\uCE68\uC744 \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uC784\uB300\uC640 \uAD6C\uB9E4\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uC784\uB300\uB294 \uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC744 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uB098\uB204\uACE0 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uC640 \uD569\uCCD0 \uCCAD\uAD6C\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544, \uC6D4 \uCCAD\uAD6C\uC11C\uC5D0 \uB450 \uD56D\uBAA9\uC774 \uBD84\uB9AC\uB3FC \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB294 \uBCF8\uCCB4\uB97C \uCC98\uC74C\uC5D0 \uCE58\uB974\uACE0 \uC6D4\uC5D0\uB294 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uB8CC\uB9CC \uB0A8\uC2B5\uB2C8\uB2E4.", "\uC784\uB300 \uC57D\uC815\uC5D0\uB294 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uBD99\uC73C\uBBC0\uB85C \uC6B4\uC601 \uAE30\uAC04\uC774 \uBD88\uD655\uC2E4\uD55C \uB9E4\uC7A5\uC740 \uADF8 \uC870\uD56D\uC744 \uBA3C\uC800 \uC77D\uC2B5\uB2C8\uB2E4.", "\uACE0\uC7A5 \uAD50\uCCB4\uAC00 \uC784\uB300 \uC870\uAC74\uC5D0 \uD3EC\uD568\uB418\uBA74 \uC6B4\uC601 \uC911 \uBD80\uB2F4\uC774 \uC904\uC9C0\uB9CC, \uAD6C\uB9E4\uB294 \uBCF4\uC99D \uAE30\uAC04 \uB4A4 \uC218\uB9AC \uBE44\uC6A9\uC774 \uB9E4\uC7A5 \uBAAB\uC785\uB2C8\uB2E4.", "\uC9C0\uC6D0\uAE08\uC744 \uBC1B\uC544 \uAD6C\uB9E4\uD558\uB294 \uACBD\uC6B0 \uC9C0\uC6D0 \uC870\uAC74\uC5D0 \uAE30\uAE30 \uC0AC\uC591\uACFC \uC0AC\uC6A9 \uAE30\uAC04 \uC694\uAC74\uC774 \uC788\uC73C\uBBC0\uB85C \uADF8 \uC694\uAC74\uC744 \uACAC\uC801 \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCD1D\uBE44\uC6A9\uC740 \uC6B4\uC601 \uC608\uC815 \uAC1C\uC6D4 \uC218\uB85C \uB450 \uBC29\uC2DD\uC744 \uACC4\uC0B0\uD574 \uBE44\uAD50\uD558\uACE0, \uC815\uD655\uD55C \uAE08\uC561\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uACAC\uC801\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uC77D\uB098\uC694?", "p": ["\uAE30\uAE30 \uBAA8\uB378\uBA85\uACFC \uD654\uBA74 \uD06C\uAE30, \uACB0\uC81C \uBAA8\uB4C8 \uBC29\uC2DD, \uD504\uB85C\uADF8\uB7A8 \uC774\uB984\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uAC19\uC740 \uC870\uAC74\uB07C\uB9AC \uBE44\uAD50\uB429\uB2C8\uB2E4.", "\uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB41C \uC11C\uBE44\uC2A4(\uBA54\uB274 \uC218\uC815\xB7\uC6D0\uACA9 \uC9C0\uC6D0\xB7\uC5C5\uB370\uC774\uD2B8)\uB97C \uD56D\uBAA9\uC73C\uB85C \uD45C\uC2DC\uD574 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uCD9C\uC7A5\uBE44\uC5D0 \uBA54\uB274 \uC785\uB825\uC774 \uD3EC\uD568\uC778\uC9C0, \uD3EC\uD568\uC774\uBA74 \uBA54\uB274 \uC218 \uC81C\uD55C\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04, \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74, \uACE0\uC7A5 \uAD50\uCCB4 \uC870\uAC74\uC774 \uACAC\uC801\uC11C\uB098 \uBCC4\uC9C0\uC5D0 \uAE00\uB85C \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uB450 \uC5C5\uCCB4 \uACAC\uC801\uC744 \uAC19\uC740 \uD56D\uBAA9 \uC21C\uC11C\uB85C \uB2E4\uC2DC \uC801\uC5B4 \uBCF4\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC5D0\uC11C \uCC28\uC774\uAC00 \uB098\uB294\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uACAC\uC801 \uC720\uD6A8 \uAE30\uAC04\uC744 \uC801\uC5B4 \uB450\uACE0 \uADF8 \uC548\uC5D0 \uACB0\uC815\uD558\uAC70\uB098, \uC9C0\uB098\uBA74 \uC0C8 \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uC801\uD78C \uC6D4 \uC0AC\uC6A9\uB8CC\uC758 \uCCAD\uAD6C \uC2DC\uC791\uC77C\uC774 \uC124\uCE58\uC77C\uC778\uC9C0 \uACC4\uC57D\uC77C\uC778\uC9C0\uB3C4 \uD655\uC778\uD574 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uACAC\uC801\uC744 \uBC1B\uB294 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uB9E4\uC7A5 \uBA54\uB274 \uC218, \uC190\uB2D8 \uD68C\uC804, \uD3EC\uC2A4 \uC5F0\uB3D9 \uC5EC\uBD80\uB97C \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uBCF8\uCCB4\xB7\uACB0\uC81C \uBAA8\uB4C8\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uCD9C\uC7A5\uBE44\uB85C \uB098\uB25C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4 \uC870\uAC74\uC73C\uB85C \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uC5D0 \uB9DE\uCDB0 \uCD1D\uBE44\uC6A9\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0\uAE08 \uC694\uAC74\uC774 \uC788\uC73C\uBA74 \uAE30\uAE30 \uC0AC\uC591\uC774 \uB9DE\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC11C\uBA85 \uC804\uC5D0 \uC57D\uC815\uC11C\uC758 \uBAA8\uB378\uBA85\xB7\uD654\uBA74 \uD06C\uAE30\xB7\uD56D\uBAA9\uBCC4 \uAE08\uC561\uC744 \uACAC\uC801\uC11C\uC640 \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD0A4\uC624\uC2A4\uD06C \uBE44\uC6A9 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "1\uD68C \uBE44\uC6A9", "\uC6D4 \uBE44\uC6A9"], "rows": [["\uBCF8\uCCB4", "\uAD6C\uB9E4 \uC2DC", "\uC784\uB300 \uC2DC"], ["\uACB0\uC81C \uBAA8\uB4C8\xB7\uAC00\uB9F9\uC810 \uB4F1\uB85D", "\uC124\uCE58 \uC2DC", "\uC5C6\uC74C"], ["\uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8", "\uC124\uCE58\uBE44", "\uC0AC\uC6A9\uB8CC"], ["\uC124\uCE58 \uCD9C\uC7A5\uBE44", "\uC791\uC5C5\uBE44", "\uC5C6\uC74C"], ["\uC120\uD0DD \uC7A5\uCE58(\uD504\uB9B0\uD130\xB7\uD638\uCD9C\uBCA8)", "\uAE30\uAE30\uAC12", "\uC5C6\uC74C"]] }, "faq": [["\uD0A4\uC624\uC2A4\uD06C\uC5D0 \uCE74\uB4DC\uB2E8\uB9D0\uAE30\uB97C \uB530\uB85C \uC0AC\uC57C \uD558\uB098\uC694?", "\uBCF8\uCCB4\uC5D0 \uACB0\uC81C \uBAA8\uB4C8\uC774 \uB0B4\uC7A5\uB41C \uBAA8\uB378\uC740 \uB530\uB85C \uD544\uC694 \uC5C6\uACE0, \uC678\uBD80 \uB2E8\uB9D0\uAE30\uB97C \uBD99\uC774\uB294 \uBAA8\uB378\uC740 \uB2E8\uB9D0\uAE30 \uD56D\uBAA9\uC774 \uCD94\uAC00\uB429\uB2C8\uB2E4. \uC5B4\uB290 \uBC29\uC2DD\uC778\uC9C0 \uACAC\uC801\uC11C\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBA54\uB274 \uC0AC\uC9C4\uC740 \uB204\uAC00 \uC900\uBE44\uD558\uB098\uC694?", "\uB300\uBD80\uBD84 \uB9E4\uC7A5\uC774 \uC900\uBE44\uD569\uB2C8\uB2E4. \uC0AC\uC9C4 \uCD2C\uC601\uC774\uB098 \uD3B8\uC9D1\uC744 \uC5C5\uCCB4\uAC00 \uD558\uBA74 \uBCC4\uB3C4 \uD56D\uBAA9\uC774 \uB418\uBBC0\uB85C \uD3EC\uD568 \uC5EC\uBD80\uB97C \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uC791\uC740 \uB9E4\uC7A5\uC740 \uD0C1\uC0C1\uD615\uC774 \uC2FC\uAC00\uC694?", "\uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC740 \uB0AE\uC740 \uD3B8\uC774\uC9C0\uB9CC \uACB0\uC81C \uBAA8\uB4C8\uACFC \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uAC19\uC2B5\uB2C8\uB2E4. \uCD1D\uBE44\uC6A9\uC73C\uB85C \uBE44\uAD50\uD569\uB2C8\uB2E4."], ["\uC9C0\uC6D0\uAE08\uC744 \uBC1B\uC73C\uBA74 \uC124\uCE58\uBE44\uC6A9\uC774 \uC904\uC5B4\uB4DC\uB098\uC694?", "\uC9C0\uC6D0 \uC694\uAC74\uC5D0 \uB9DE\uB294 \uAE30\uAE30\uC640 \uC0AC\uC6A9 \uAE30\uAC04 \uC870\uAC74\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC694\uAC74\uACFC \uD55C\uB3C4\uB294 \uC5F0\uB3C4\uBCC4 \uACF5\uACE0 \uAE30\uC900\uC774\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC9C0\uC6D0\uAE08", "\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8", "\uD0A4\uC624\uC2A4\uD06C\uD14C\uC774\uBE14\uC624\uB354\uBE44\uAD50"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uC9C0\uC6D0\uAE08", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uC9C0\uC6D0\uAE08(\uC2A4\uB9C8\uD2B8\uC0C1\uC810)", "title": "\uD0A4\uC624\uC2A4\uD06C \uC9C0\uC6D0\uAE08\uC740 \uB204\uAC00 \uC5B4\uB5BB\uAC8C \uBC1B\uB098\uC694? \u2014 \uC2A4\uB9C8\uD2B8\uC0C1\uC810 \uAE30\uC220\uBCF4\uAE09\uC0AC\uC5C5 \uC2E0\uCCAD \uD750\uB984", "desc": "\uD0A4\uC624\uC2A4\uD06C \uC124\uCE58\uC5D0 \uC4F8 \uC218 \uC788\uB294 \uC18C\uC0C1\uACF5\uC778 \uC2A4\uB9C8\uD2B8\uC0C1\uC810 \uAE30\uC220\uBCF4\uAE09\uC0AC\uC5C5\uC758 \uC2E0\uCCAD \uC790\uACA9\uACFC \uC808\uCC28, \uC9C0\uC815 \uACF5\uAE09\uC0AC\uC640 \uAE30\uAE30 \uC694\uAC74, \uC790\uBD80\uB2F4\uACFC \uC0AC\uD6C4 \uC758\uBB34, \uACF5\uACE0 \uC2DC\uAE30\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uB294 \uC870\uAC74\uACFC \uC2E0\uCCAD \uC804\uC5D0 \uC900\uBE44\uD560 \uC11C\uB958\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD0A4\uC624\uC2A4\uD06C \uC9C0\uC6D0\uAE08\uC740 \uC18C\uC0C1\uACF5\uC778\uC2DC\uC7A5\uC9C4\uD765\uACF5\uB2E8\uC758 \uC2A4\uB9C8\uD2B8\uC0C1\uC810 \uAE30\uC220\uBCF4\uAE09\uC0AC\uC5C5\uCC98\uB7FC \uC5F0\uB3C4\uBCC4 \uACF5\uACE0\uB85C \uC5F4\uB9AC\uB294 \uC9C0\uC6D0\uC0AC\uC5C5\uC744 \uD1B5\uD574 \uBC1B\uC73C\uBA70, \uC790\uACA9\uC740 \uC18C\uC0C1\uACF5\uC778 \uAE30\uC900 \uCDA9\uC871\uACFC \uC9C0\uC815 \uACF5\uAE09\uC0AC \uAE30\uAE30 \uC120\uD0DD\uC774 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uC9C0\uC6D0 \uBE44\uC728\uACFC \uD55C\uB3C4\uB294 \uACF5\uACE0\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uACE0, \uACF5\uACE0 \uC804\uC5D0 \uC0AC\uC5C5\uC790 \uC694\uAC74\uACFC \uC11C\uB958\uB97C \uBBF8\uB9AC \uB9DE\uCDB0 \uB450\uB294 \uAC83\uC774 \uAC00\uC7A5 \uC911\uC694\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC2E0\uCCAD \uC790\uACA9\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC18C\uC0C1\uACF5\uC778 \uAE30\uC900(\uC5C5\uC885\uBCC4 \uC0C1\uC2DC \uADFC\uB85C\uC790 \uC218\uC640 \uB9E4\uCD9C)\uC744 \uCDA9\uC871\uD558\uB294 \uC0AC\uC5C5\uC790\uAC00 \uB300\uC0C1\uC774\uBA70, \uC77C\uBD80 \uC5C5\uC885\uC740 \uC81C\uC678\uB418\uBBC0\uB85C \uACF5\uACE0\uC758 \uC81C\uC678 \uC5C5\uC885 \uBAA9\uB85D\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC774 \uB418\uC5B4 \uC788\uACE0 \uC601\uC5C5 \uC911\uC778 \uB9E4\uC7A5\uC774\uC5B4\uC57C \uD558\uBA70, \uD734\uC5C5\uC774\uB098 \uD3D0\uC5C5 \uC608\uC815 \uB9E4\uC7A5\uC740 \uB300\uC0C1\uC774 \uC544\uB2D9\uB2C8\uB2E4.", "\uAC19\uC740 \uC0AC\uC5C5\uC73C\uB85C \uC774\uBBF8 \uC9C0\uC6D0\uBC1B\uC740 \uC774\uB825\uC774 \uC788\uC73C\uBA74 \uC7AC\uC2E0\uCCAD\uC774 \uC81C\uD55C\uB418\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uACFC\uAC70 \uC218\uD61C \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC138\uAE08 \uCCB4\uB0A9\uC774\uB098 \uC81C\uC7AC \uC774\uB825\uC774 \uC788\uC73C\uBA74 \uC2EC\uC0AC\uC5D0\uC11C \uC81C\uC678\uB420 \uC218 \uC788\uC73C\uBBC0\uB85C \uB0A9\uC138 \uC0C1\uD0DC\uB97C \uC815\uB9AC\uD574 \uB461\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uB300\uC0C1 \uAE30\uAE30\uB294 \uACF5\uACE0\uC5D0\uC11C \uC815\uD55C \uC9C0\uC815 \uACF5\uAE09\uC0AC \uC81C\uD488\uC774\uC5B4\uC57C \uD558\uBBC0\uB85C \uC544\uBB34 \uAE30\uAE30\uB098 \uC0B0 \uB4A4 \uC2E0\uCCAD\uD560 \uC218\uB294 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC790\uACA9 \uC694\uAC74\uC740 \uC5F0\uB3C4\uB9C8\uB2E4 \uC870\uAE08\uC529 \uBC14\uB00C\uBBC0\uB85C \uC9C0\uB09C\uD574 \uAE30\uC900\uC744 \uADF8\uB300\uB85C \uBBFF\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC790\uACA9\uC774 \uC560\uB9E4\uD558\uBA74 \uC18C\uC0C1\uACF5\uC778\uC9C0\uC6D0\uC13C\uD130\uC5D0 \uC0AC\uC5C5\uC790\uBC88\uD638\uB85C \uC0AC\uC804 \uBB38\uC758\uD558\uBA74 \uB429\uB2C8\uB2E4.", "\uC2E0\uCCAD \uC0AC\uC774\uD2B8 \uC811\uC218\uB294 \uACF5\uACE0 \uAE30\uAC04 \uC548\uC5D0\uB9CC \uC5F4\uB9AC\uBBC0\uB85C \uAE30\uAC04 \uCCAB\uB0A0\uACFC \uB9C8\uC9C0\uB9C9 \uB0A0\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uACF5\uACE0\uB9C8\uB2E4 \uC9C0\uC6D0 \uB300\uC0C1 \uAE30\uC220(\uD0A4\uC624\uC2A4\uD06C\xB7\uD14C\uC774\uBE14\uC624\uB354\xB7\uD3EC\uC2A4 \uB4F1)\uC758 \uBC94\uC704\uAC00 \uB2EC\uB77C \uD0A4\uC624\uC2A4\uD06C\uAC00 \uADF8 \uD574 \uB300\uC0C1\uC778\uC9C0 \uBA3C\uC800 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC2E0\uCCAD \uC808\uCC28\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uACF5\uACE0\uAC00 \uC5F4\uB9AC\uBA74 \uC2E0\uCCAD \uC0AC\uC774\uD2B8\uC5D0\uC11C \uC0AC\uC5C5\uC790 \uC815\uBCF4\uC640 \uB9E4\uC7A5 \uC815\uBCF4\uB97C \uC785\uB825\uD558\uACE0 \uC11C\uB958\uB97C \uC62C\uB9BD\uB2C8\uB2E4.", "\uC11C\uB958\uB294 \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D, \uB9E4\uCD9C \uC99D\uBE59, \uC784\uB300\uCC28\uACC4\uC57D\uC11C\uCC98\uB7FC \uB9E4\uC7A5 \uC6B4\uC601\uC744 \uC99D\uBA85\uD558\uB294 \uAC83\uC774 \uC911\uC2EC\uC774\uACE0, \uACF5\uACE0\uBCC4 \uCD94\uAC00 \uC11C\uB958\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC120\uC815\uB418\uBA74 \uC9C0\uC815 \uACF5\uAE09\uC0AC \uAC00\uC6B4\uB370 \uAE30\uAE30\uB97C \uACE0\uB974\uACE0 \uC124\uCE58 \uACC4\uC57D\uC744 \uB9FA\uC73C\uBA70, \uC790\uBD80\uB2F4 \uAE08\uC561\uC744 \uC5C5\uCCB4\uC5D0 \uCE58\uB985\uB2C8\uB2E4.", "\uC124\uCE58\uAC00 \uB05D\uB098\uBA74 \uC124\uCE58 \uD655\uC778 \uC11C\uB958\uC640 \uC0AC\uC9C4\uC744 \uC81C\uCD9C\uD574\uC57C \uC9C0\uC6D0\uAE08\uC774 \uC815\uC0B0\uB418\uBBC0\uB85C \uC124\uCE58 \uB2F9\uC77C \uC0AC\uC9C4\uC744 \uCC0D\uC5B4 \uB461\uB2C8\uB2E4.", "\uC9C0\uC6D0\uAE08\uC740 \uBCF4\uD1B5 \uB9E4\uC7A5\uC774 \uC544\uB2C8\uB77C \uACF5\uAE09\uC0AC\uC5D0 \uC9C0\uAE09\uB418\uB294 \uAD6C\uC870\uC774\uBBC0\uB85C \uB9E4\uC7A5\uC740 \uC790\uBD80\uB2F4\uB9CC \uB0B4\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC120\uC815 \uB4A4 \uC124\uCE58 \uAE30\uD55C\uC774 \uC815\uD574\uC838 \uC788\uC5B4 \uAE30\uD55C\uC744 \uB118\uAE30\uBA74 \uCDE8\uC18C\uB420 \uC218 \uC788\uC73C\uB2C8 \uACF5\uAE09\uC0AC \uC77C\uC815\uC744 \uBC14\uB85C \uC7A1\uC2B5\uB2C8\uB2E4.", "\uC808\uCC28\uC640 \uAE30\uD55C\uC740 \uACF5\uACE0 \uBCF8\uBB38\uC5D0 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uACF5\uACE0 PDF\uB97C \uBC1B\uC544 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC790\uBD80\uB2F4 \uAE08\uC561\uC740 \uC120\uC815 \uB4A4 \uACF5\uAE09\uC0AC \uACAC\uC801\uC73C\uB85C \uD655\uC815\uB418\uBBC0\uB85C \uC120\uC815 \uC804\uC5D0 \uACF5\uAE09\uC0AC \uBA87 \uACF3\uC758 \uAE30\uAE30 \uC0AC\uC591\uC744 \uBBF8\uB9AC \uBE44\uAD50\uD574 \uB461\uB2C8\uB2E4.", "\uC120\uC815 \uD1B5\uBCF4 \uB4A4 \uACF5\uAE09\uC0AC \uACC4\uC57D\uC11C\uC5D0 \uC790\uBD80\uB2F4 \uAE08\uC561\uACFC \uC9C0\uC6D0\uAE08 \uCC98\uB9AC \uBC29\uC2DD\uC774 \uC801\uD600 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uBC1B\uC740 \uB4A4 \uC9C0\uCF1C\uC57C \uD560 \uAC83\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC77C\uC815 \uAE30\uAC04 \uAE30\uAE30\uB97C \uC720\uC9C0\uD574\uC57C \uD558\uB294 \uC758\uBB34\uAC00 \uC788\uC5B4 \uADF8 \uAE30\uAC04 \uC548\uC5D0 \uD3D0\uC5C5\uD558\uAC70\uB098 \uAE30\uAE30\uB97C \uCC98\uBD84\uD558\uBA74 \uD658\uC218\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC0AC\uD6C4 \uC810\uAC80\uC774\uB098 \uC774\uC6A9 \uD604\uD669 \uC870\uC0AC\uC5D0 \uC751\uD574\uC57C \uD558\uB294 \uC870\uAC74\uC774 \uBD99\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uB2E4\uB978 \uB9E4\uC7A5\uC73C\uB85C \uC62E\uAE30\uAC70\uB098 \uC591\uB3C4\uD558\uB294 \uAC83\uB3C4 \uC81C\uD55C\uB420 \uC218 \uC788\uC5B4 \uC774\uC804 \uACC4\uD68D\uC774 \uC788\uC73C\uBA74 \uBBF8\uB9AC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04\uACFC \uD658\uC218 \uC870\uAC74\uC740 \uACF5\uACE0\uC640 \uD611\uC57D\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uD611\uC57D\uC11C\uB97C \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC720\uC9C0\uBCF4\uC218\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC\uB294 \uC9C0\uC6D0 \uB300\uC0C1\uC774 \uC544\uB2CC \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uC124\uCE58 \uB4A4 \uC6D4 \uBE44\uC6A9\uC740 \uB9E4\uC7A5 \uBAAB\uC785\uB2C8\uB2E4.", "\uC758\uBB34 \uC0AC\uD56D\uC740 \uACF5\uAE09\uC0AC\uC640 \uB9E4\uC7A5 \uBAA8\uB450\uC5D0\uAC8C \uC788\uC5B4 \uACF5\uAE09\uC0AC\uAC00 \uD3D0\uC5C5\uD558\uBA74 \uC720\uC9C0\uBCF4\uC218 \uCC3D\uAD6C\uB97C \uD655\uC778\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04 \uC548 \uAE30\uAE30 \uACE0\uC7A5\uC73C\uB85C \uAD50\uCCB4\uD558\uB294 \uACBD\uC6B0\uB294 \uD658\uC218 \uB300\uC0C1\uC774 \uC544\uB2CC \uAC83\uC774 \uBCF4\uD1B5\uC774\uC9C0\uB9CC \uC13C\uD130\uC5D0 \uC54C\uB824 \uAE30\uB85D\uC744 \uB0A8\uAE41\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04 \uC911 \uC0AC\uC5C5\uC790 \uC815\uBCF4(\uC0C1\uD638\xB7\uB300\uD45C\uC790)\uAC00 \uBC14\uB00C\uBA74 \uC13C\uD130\uC5D0 \uC54C\uB824\uC57C \uD611\uC57D\uC774 \uC720\uC9C0\uB429\uB2C8\uB2E4."] }, { "h": "\uC9C0\uC6D0\uAE08 \uC5C6\uC774 \uD560 \uB54C\uC640 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uC9C0\uC6D0\uC744 \uBC1B\uC73C\uBA74 \uC790\uBD80\uB2F4\uC774 \uC904\uC9C0\uB9CC \uAE30\uAE30 \uC120\uD0DD\uC774 \uC9C0\uC815 \uACF5\uAE09\uC0AC\uB85C \uC881\uD600\uC9D1\uB2C8\uB2E4.", "\uACF5\uACE0 \uC2DC\uAE30\uB97C \uAE30\uB2E4\uB824\uC57C \uD558\uBBC0\uB85C \uB2F9\uC7A5 \uC124\uCE58\uAC00 \uD544\uC694\uD55C \uB9E4\uC7A5\uC740 \uC77C\uC815\uC774 \uB9DE\uC9C0 \uC54A\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uC5C6\uC774 \uC124\uCE58\uD558\uBA74 \uAE30\uAE30\uC640 \uC5C5\uCCB4\uB97C \uC790\uC720\uB86D\uAC8C \uACE0\uB974\uACE0 \uC758\uBB34 \uAE30\uAC04\uB3C4 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uB450 \uBC29\uC2DD\uC744 \uC6B4\uC601 \uAE30\uAC04\uACFC \uC124\uCE58 \uC2DC\uAE09\uC131\uC73C\uB85C \uBE44\uAD50\uD574 \uC815\uD558\uACE0, \uACF5\uACE0 \uC77C\uC815\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uAE30\uAE30\uB3C4 \uACB0\uAD6D \uB9E4\uC7A5\uC774 \uC4F0\uB294 \uAC83\uC774\uBBC0\uB85C \uAE30\uAE30 \uC0AC\uC591\uACFC \uC720\uC9C0\uBCF4\uC218 \uC870\uAC74\uC740 \uC9C0\uC6D0 \uC5EC\uBD80\uC640 \uAD00\uACC4\uC5C6\uC774 \uB611\uAC19\uC774 \uBD05\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uAE30\uAE30\uB77C\uB3C4 \uC124\uCE58 \uB4A4 \uC6B4\uC601\uC740 \uC77C\uBC18 \uAE30\uAE30\uC640 \uAC19\uC73C\uBBC0\uB85C \uBA54\uB274 \uC785\uB825\uACFC \uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC740 \uB611\uAC19\uC774 \uCC59\uAE41\uB2C8\uB2E4.", "\uC120\uC815\xB7\uC124\uCE58\xB7\uC815\uC0B0 \uB2E8\uACC4\uB9C8\uB2E4 \uBC1B\uC740 \uC11C\uB958\uB97C \uD55C \uD3F4\uB354\uC5D0 \uBAA8\uC74D\uB2C8\uB2E4."] }], "steps": { "h": "\uC2E0\uCCAD \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uACF5\uACE0\uB97C \uD655\uC778\uD558\uACE0 \uC790\uACA9 \uC694\uAC74\uACFC \uC81C\uC678 \uC5C5\uC885\uC744 \uBD05\uB2C8\uB2E4.", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\xB7\uB9E4\uCD9C \uC99D\uBE59\xB7\uC784\uB300\uCC28\uACC4\uC57D\uC11C\uB97C \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uC2E0\uCCAD \uC0AC\uC774\uD2B8\uC5D0\uC11C \uC811\uC218\uD558\uACE0 \uC120\uC815 \uACB0\uACFC\uB97C \uAE30\uB2E4\uB9BD\uB2C8\uB2E4.", "\uC9C0\uC815 \uACF5\uAE09\uC0AC\uC640 \uACC4\uC57D\uD574 \uC124\uCE58\uD558\uACE0 \uC124\uCE58 \uD655\uC778 \uC11C\uB958\uB97C \uB0C5\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04\uACFC \uD658\uC218 \uC870\uAC74\uC744 \uD611\uC57D\uC11C\uB85C \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC9C0\uC6D0 \uC2E0\uCCAD \uC804 \uC810\uAC80\uD45C", "head": ["\uD56D\uBAA9", "\uD655\uC778 \uB0B4\uC6A9", "\uC5C6\uC73C\uBA74"], "rows": [["\uC18C\uC0C1\uACF5\uC778 \uAE30\uC900", "\uADFC\uB85C\uC790 \uC218\xB7\uB9E4\uCD9C", "\uC13C\uD130 \uBB38\uC758"], ["\uC81C\uC678 \uC5C5\uC885", "\uACF5\uACE0 \uBAA9\uB85D", "\uC2E0\uCCAD \uBD88\uAC00"], ["\uC9C0\uC815 \uACF5\uAE09\uC0AC", "\uAE30\uAE30 \uBAA9\uB85D", "\uD574\uB2F9 \uAE30\uAE30\uB85C \uBCC0\uACBD"], ["\uC11C\uB958", "\uB4F1\uB85D\uC99D\xB7\uB9E4\uCD9C\xB7\uC784\uB300\uCC28", "\uBBF8\uB9AC \uC900\uBE44"], ["\uC758\uBB34 \uAE30\uAC04", "\uD611\uC57D\uC11C", "\uD658\uC218 \uC870\uAC74 \uD655\uC778"]] }, "faq": [["\uC9C0\uC6D0\uAE08\uC740 \uB9E4\uC7A5 \uD1B5\uC7A5\uC73C\uB85C \uB4E4\uC5B4\uC624\uB098\uC694?", "\uBCF4\uD1B5 \uACF5\uAE09\uC0AC\uC5D0 \uC9C0\uAE09\uB418\uACE0 \uB9E4\uC7A5\uC740 \uC790\uBD80\uB2F4\uB9CC \uB0C5\uB2C8\uB2E4. \uC9C0\uAE09 \uBC29\uC2DD\uC740 \uACF5\uACE0\uB9C8\uB2E4 \uB2EC\uB77C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC774\uBBF8 \uC124\uCE58\uD55C \uD0A4\uC624\uC2A4\uD06C\uB3C4 \uC9C0\uC6D0\uBC1B\uC744 \uC218 \uC788\uB098\uC694?", "\uB300\uBD80\uBD84 \uC120\uC815 \uB4A4 \uC124\uCE58\uD55C \uAE30\uAE30\uB9CC \uB300\uC0C1\uC785\uB2C8\uB2E4. \uC124\uCE58 \uC804\uC5D0 \uACF5\uACE0\uB97C \uBA3C\uC800 \uBD05\uB2C8\uB2E4."], ["\uC9C0\uC6D0 \uBE44\uC728\uACFC \uD55C\uB3C4\uB294 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uC5F0\uB3C4\uBCC4 \uACF5\uACE0 \uAE30\uC900\uC774\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC758\uBB34 \uAE30\uAC04 \uC911 \uD3D0\uC5C5\uD558\uBA74 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "\uD611\uC57D\uC11C\uC758 \uD658\uC218 \uC870\uD56D\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uD3D0\uC5C5 \uC804\uC5D0 \uC13C\uD130\uC5D0 \uBB38\uC758\uD569\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8", "\uD0A4\uC624\uC2A4\uD06C\uC18C\uD615\uB9E4\uC7A5"], "posts": [], "sources": ["\uC18C\uC0C1\uACF5\uC778\uC2DC\uC7A5\uC9C4\uD765\uACF5\uB2E8 \uC2A4\uB9C8\uD2B8\uC0C1\uC810 \uAE30\uC220\uBCF4\uAE09\uC0AC\uC5C5 \uACF5\uACE0(\uC5F0\uB3C4\uBCC4)"], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uC784\uB300\xB7\uB80C\uD0C8", "title": "\uD0A4\uC624\uC2A4\uD06C \uC784\uB300\uC640 \uB80C\uD0C8\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694? \u2014 \uC57D\uC815 \uAE30\uAC04\uACFC \uC720\uC9C0\uBCF4\uC218 \uD3EC\uD568 \uBC94\uC704", "desc": "\uD0A4\uC624\uC2A4\uD06C \uC784\uB300\xB7\uB80C\uD0C8 \uC57D\uC815\uC758 \uC6D4 \uC774\uC6A9\uB8CC \uD3EC\uD568 \uD56D\uBAA9, \uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74, \uACE0\uC7A5 \uAD50\uCCB4\uC640 \uC18C\uBAA8\uD488 \uCC98\uB9AC, \uC57D\uC815 \uC885\uB8CC \uB4A4 \uAE30\uAE30 \uCC98\uB9AC \uBC29\uC2DD\uC744 \uC815\uB9AC\uD558\uACE0 \uB80C\uD0C8\uC774 \uB9DE\uB294 \uB9E4\uC7A5\uACFC \uAD6C\uB9E4\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC744 \uB098\uB234\uC2B5\uB2C8\uB2E4.", "answer": "\uD0A4\uC624\uC2A4\uD06C \uC784\uB300\uC640 \uB80C\uD0C8\uC740 \uBD80\uB974\uB294 \uB9D0\uB9CC \uB2E4\uB97C \uBFD0 \uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC744 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uB098\uB220 \uB0B4\uB294 \uC57D\uC815\uC774\uBA70, \uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uC640 \uC720\uC9C0\uBCF4\uC218\uAC00 \uD3EC\uD568\uC778\uC9C0\uAC00 \uC870\uAC74\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uC57D\uC815 \uAE30\uAC04\uC774 \uAE38\uC218\uB85D \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB0AE\uC544\uC9C0\uB294 \uB300\uC2E0 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uBB34\uAC70\uC6CC\uC9C0\uBBC0\uB85C \uC6B4\uC601 \uAE30\uAC04\uC744 \uBA3C\uC800 \uC815\uD558\uACE0 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC6D4 \uC774\uC6A9\uB8CC\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uBCF8\uCCB4 \uAE30\uAE30\uAC12\uC774 \uAE30\uBCF8\uC774\uACE0 \uACB0\uC81C \uBAA8\uB4C8\uC774 \uB0B4\uC7A5\uB41C \uBAA8\uB378\uC740 \uADF8 \uAC12\uB3C4 \uD568\uAED8 \uB4E4\uC5B4\uAC11\uB2C8\uB2E4.", "\uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uD569\uCCD0\uC838 \uC788\uB294\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uCCAD\uAD6C\uC11C \uD56D\uBAA9\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uAE30\uAE30\uC640 \uBC29\uBB38 \uC218\uB9AC\uAC00 \uD3EC\uD568\uC778\uC9C0, \uD69F\uC218 \uC81C\uD55C\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC6A9\uC9C0 \uAC19\uC740 \uC18C\uBAA8\uD488\uC740 \uD3EC\uD568\uB418\uC9C0 \uC54A\uB294 \uAC83\uC774 \uC77C\uBC18\uC801\uC774\uACE0, \uD504\uB9B0\uD130 \uD5E4\uB4DC \uAC19\uC740 \uC18C\uBAA8 \uBD80\uD488\uB3C4 \uBCC4\uB3C4\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274 \uC218\uC815\uACFC \uD654\uBA74 \uB514\uC790\uC778 \uBCC0\uACBD\uC774 \uBB34\uC0C1\uC778\uC9C0 \uD69F\uC218 \uC81C\uD55C\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uD68C\uC120\uC740 \uB9E4\uC7A5 \uC778\uD130\uB137\uC744 \uC4F0\uBA74 \uBE60\uC9C0\uACE0, \uC804\uC6A9 \uD68C\uC120\uC744 \uC4F0\uBA74 \uC6D4 \uC694\uAE08\uC774 \uB354\uD574\uC9D1\uB2C8\uB2E4.", "\uD3EC\uD568 \uD56D\uBAA9\uC774 \uB9CE\uC73C\uBA74 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB192\uC73C\uBBC0\uB85C \uB9E4\uC7A5\uC5D0 \uD544\uC694\uD55C \uD56D\uBAA9\uB9CC \uB0A8\uACA8 \uC870\uC815\uD569\uB2C8\uB2E4.", "\uC6D4 \uC774\uC6A9\uB8CC \uCCAD\uAD6C \uC2DC\uC791\uC77C\uACFC \uC124\uCE58\uC77C\uC774 \uB2E4\uB974\uBA74 \uCCAB \uB2EC\uC774 \uC774\uC911 \uCCAD\uAD6C\uB420 \uC218 \uC788\uC5B4 \uB0A0\uC9DC\uB97C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uC720\uC9C0\uBCF4\uC218 \uD3EC\uD568 \uBC94\uC704\uC5D0 \uC18C\uD504\uD2B8\uC6E8\uC5B4 \uC624\uB958 \uB300\uC751\uACFC \uD558\uB4DC\uC6E8\uC5B4 \uC218\uB9AC\uAC00 \uBAA8\uB450 \uB4E4\uC5B4\uAC00\uB294\uC9C0 \uB098\uB220\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815 \uAE30\uAC04\uC744 \uC815\uD560 \uB54C \uBB34\uC5C7\uC744 \uB530\uC9C0\uB098\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04\uC774 \uAE38\uC218\uB85D \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB0AE\uC544\uC9C0\uC9C0\uB9CC \uC911\uB3C4 \uD574\uC9C0 \uB54C \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uCEE4\uC9D1\uB2C8\uB2E4.", "\uC911\uB3C4 \uD574\uC9C0 \uC0B0\uC815 \uBC29\uC2DD\uC774 \uC57D\uC815\uC11C \uC870\uD56D\uC5D0 \uC788\uC5B4\uC57C \uD558\uACE0, \uC5C6\uC73C\uBA74 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC774 \uB05D\uB098\uBA74 \uBC18\uB0A9\uC778\uC9C0, \uC5F0\uC7A5\uC778\uC9C0, \uC18C\uC720\uAD8C\uC774 \uB118\uC5B4\uC624\uB294\uC9C0 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5 \uC870\uD56D\uC774 \uC788\uC73C\uBA74 \uC885\uB8CC \uC804\uC5D0 \uD574\uC9C0 \uC758\uC0AC\uB97C \uAE00\uB85C \uB0A8\uACA8\uC57C \uD569\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774\uB098 \uC774\uC804 \uB54C \uC2B9\uACC4\uB098 \uC870\uAE30 \uC885\uB8CC \uC870\uAC74\uC774 \uC788\uB294\uC9C0\uB3C4 \uBD05\uB2C8\uB2E4.", "\uD574\uC9C0 \uC870\uAC74\uC758 \uACC4\uC0B0\uBC95\uACFC \uAE08\uC561\uC740 \uB80C\uD0C8 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2E4\uB974\uB2C8 \uACC4\uC57D \uC804\uC5D0 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC758 \uD574\uC9C0 \uC870\uD56D\uC740 \uAE30\uAE30\uC640 \uD504\uB85C\uADF8\uB7A8 \uAC01\uAC01\uC5D0 \uC788\uC744 \uC218 \uC788\uC73C\uB2C8 \uB450 \uC870\uD56D\uC744 \uBAA8\uB450 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04 \uC911 \uC5C5\uCCB4\uAC00 \uAE30\uAE30 \uBAA8\uB378\uC744 \uB2E8\uC885\uD558\uBA74 \uAD50\uCCB4 \uAE30\uAE30\uAC00 \uC5B4\uB5A4 \uBAA8\uB378\uC778\uC9C0\uB3C4 \uC870\uD56D\uC5D0 \uC788\uC73C\uBA74 \uC88B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04 \uC548\uC5D0 \uAE30\uAE30\uAC00 \uB2E8\uC885\uB418\uBA74 \uC5B4\uB5A4 \uBAA8\uB378\uB85C \uAD50\uCCB4\uB418\uB294\uC9C0 \uC870\uD56D\uC5D0 \uC788\uC73C\uBA74 \uC720\uC9C0\uBCF4\uC218 \uAC71\uC815\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uB80C\uD0C8\uC774 \uB9DE\uB294 \uB9E4\uC7A5\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uAC1C\uC5C5 \uC9C1\uD6C4\uB77C \uC6B4\uC601\uC774 \uBD88\uD655\uC2E4\uD558\uAC70\uB098 \uCD08\uAE30 \uC790\uAE08\uC744 \uC544\uB07C\uB824\uB294 \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uACE0\uC7A5\uC744 \uC9C1\uC811 \uCC98\uB9AC\uD558\uAE30 \uC5B4\uB824\uC6B4 \uB9E4\uC7A5\uC740 \uC720\uC9C0\uBCF4\uC218 \uD3EC\uD568 \uB80C\uD0C8\uC774 \uD3B8\uD569\uB2C8\uB2E4.", "\uBA54\uB274\uC640 \uD654\uBA74\uC744 \uC790\uC8FC \uBC14\uAFB8\uB294 \uB9E4\uC7A5\uC740 \uC218\uC815\uC774 \uD3EC\uD568\uB41C \uC57D\uC815\uC774 \uC720\uB9AC\uD569\uB2C8\uB2E4.", "\uBC18\uB300\uB85C \uBA87 \uB144 \uC774\uC0C1 \uC6B4\uC601\uD560 \uB9E4\uC7A5\uC740 \uAD6C\uB9E4 \uCABD \uCD1D\uBE44\uC6A9\uC774 \uB0AE\uC544\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC9C0\uC6D0\uAE08\uC73C\uB85C \uAD6C\uB9E4\uD558\uB294 \uAE38\uC774 \uC5F4\uB824 \uC788\uC73C\uBA74 \uB80C\uD0C8\uBCF4\uB2E4 \uADF8\uCABD\uC744 \uBA3C\uC800 \uAC80\uD1A0\uD569\uB2C8\uB2E4.", "\uB80C\uD0C8 \uC5C5\uCCB4\uAC00 \uD3D0\uC5C5\uD558\uBA74 \uC720\uC9C0\uBCF4\uC218 \uCC3D\uAD6C\uAC00 \uC0AC\uB77C\uC9C0\uBBC0\uB85C \uC5C5\uCCB4\uC758 \uC6B4\uC601 \uAE30\uAC04\uACFC \uB300\uC751 \uCCB4\uACC4\uB3C4 \uBD05\uB2C8\uB2E4.", "\uACC4\uC808 \uC601\uC5C5 \uB9E4\uC7A5\uC740 \uBE44\uC218\uAE30 \uC77C\uC2DC \uC815\uC9C0 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBB3C\uC5B4 \uC6D4 \uC774\uC6A9\uB8CC\uB97C \uC904\uC77C \uC218 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uB80C\uD0C8\uC774 \uB9DE\uB294\uC9C0 \uD310\uB2E8\uD560 \uB54C \uC9C0\uC6D0\uAE08 \uACF5\uACE0 \uC2DC\uAE30\uAC00 \uAC00\uAE4C\uC6B0\uBA74 \uC7A0\uC2DC \uAE30\uB2E4\uB9AC\uB294 \uCABD\uC774 \uBE44\uC6A9\uC744 \uC904\uC774\uAE30\uB3C4 \uD569\uB2C8\uB2E4.", "\uB80C\uD0C8 \uC911 \uAE30\uAE30 \uAD50\uCCB4\uB97C \uC694\uCCAD\uD560 \uB54C \uB9E4\uC7A5 \uC0AC\uC815\uC774\uBA74 \uC720\uC0C1\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uACE0\uC7A5 \uAD50\uCCB4\uC640 \uAD6C\uBD84\uD574 \uBB3B\uC2B5\uB2C8\uB2E4."] }, { "h": "\uB80C\uD0C8 \uC911 \uBC14\uAFC0 \uC218 \uC788\uB294 \uAC83\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uD654\uBA74 \uD06C\uAE30\uB098 \uAC70\uCE58 \uBC29\uC2DD\uC744 \uBC14\uAFB8\uB294 \uAE30\uAE30 \uAD50\uCCB4\uB294 \uC0C8 \uC57D\uC815\uC774 \uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uAE30\uB2A5 \uCD94\uAC00\uB294 \uC57D\uC815 \uC911\uC5D0\uB3C4 \uB418\uC9C0\uB9CC \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uBC14\uB01D\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC774\uC804 \uB54C \uAE30\uAE30 \uC774\uC124 \uC791\uC5C5\uC774 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB80C\uD0C8\uC5D0\uC11C \uAD6C\uB9E4\uB85C \uC804\uD658\uD558\uB294 \uC870\uAC74\uC774 \uC788\uC73C\uBA74 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4.", "\uBCC0\uACBD\uC740 \uAE00\uB85C \uC694\uCCAD\uD558\uACE0 \uBC14\uB010 \uC6D4 \uC774\uC6A9\uB8CC\uB97C \uC11C\uBA74\uC73C\uB85C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uC774\uC124 \uC791\uC5C5\uC740 \uC804\uC6D0\xB7\uD1B5\uC2E0 \uACF5\uC0AC\uAC00 \uB2E4\uC2DC \uD544\uC694\uD558\uBA74 \uBE44\uC6A9\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC0C8 \uB9E4\uC7A5 \uC870\uAC74\uC744 \uC54C\uB824 \uC90D\uB2C8\uB2E4.", "\uC804\uD658 \uC870\uAC74\uC774 \uC788\uC73C\uBA74 \uC804\uD658 \uC2DC\uC810\uC758 \uAE30\uAE30 \uC794\uC874 \uAC00\uCE58\uAC00 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uB418\uB294\uC9C0\uB3C4 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uC774\uC124 \uB4A4\uC5D0\uB294 \uC0C8 \uC790\uB9AC\uC5D0\uC11C \uACB0\uC81C\xB7\uC8FC\uBB38 \uD14C\uC2A4\uD2B8\uB97C \uB2E4\uC2DC \uD558\uACE0 \uAC00\uB9F9\uC810 \uC8FC\uC18C \uBCC0\uACBD\uC744 \uD568\uAED8 \uCC98\uB9AC\uD569\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB85C \uC804\uD658\uD558\uBA74 \uC720\uC9C0\uBCF4\uC218 \uC870\uAC74\uC774 \uBCF4\uC99D \uAE30\uC900\uC73C\uB85C \uBC14\uB00C\uBBC0\uB85C \uC804\uD658 \uB4A4 \uC218\uB9AC \uCC3D\uAD6C\uB97C \uB2E4\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC6D4 \uCCAD\uAD6C\uC11C\uAC00 \uCC98\uC74C \uC624\uBA74 \uD3EC\uD568 \uD56D\uBAA9\uACFC \uAE08\uC561\uC744 \uC57D\uC815\uC11C\uC640 \uB300\uC870\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uB80C\uD0C8 \uACC4\uC57D\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uD544\uC694\uD55C \uAE30\uAE30\uC640 \uAE30\uB2A5\uC744 \uC815\uB9AC\uD574 \uD3EC\uD568 \uD56D\uBAA9\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uBCC4 \uB80C\uD0C8\uB8CC\uC640 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC744 \uAE00\uB85C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC720\uC9C0\uBCF4\uC218\xB7\uBA54\uB274 \uC218\uC815\xB7\uC18C\uBAA8\uD488 \uD3EC\uD568 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uC885\uB8CC \uB4A4 \uCC98\uB9AC \uBC29\uC2DD\uC744 \uD655\uC778\uD558\uACE0 \uC11C\uBA85\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC640 \uD3EC\uD568 \uD56D\uBAA9 \uBAA9\uB85D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uB80C\uD0C8 \uC870\uAC74 \uD655\uC778\uD45C", "head": ["\uD56D\uBAA9", "\uD655\uC778\uD560 \uAC83", "\uC5C6\uC73C\uBA74"], "rows": [["\uD3EC\uD568 \uD56D\uBAA9", "\uAE30\uAE30\xB7\uD504\uB85C\uADF8\uB7A8\xB7\uC720\uC9C0\uBCF4\uC218", "\uD488\uBAA9 \uBA85\uC2DC \uC694\uCCAD"], ["\uC57D\uC815 \uAE30\uAC04", "\uAC1C\uC6D4 \uC218\xB7\uC790\uB3D9 \uC5F0\uC7A5", "\uC11C\uBA74 \uC694\uCCAD"], ["\uC911\uB3C4 \uD574\uC9C0", "\uC0B0\uC815 \uBC29\uC2DD", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"], ["\uBA54\uB274 \uC218\uC815", "\uD69F\uC218\xB7\uBE44\uC6A9", "\uC57D\uC815\uC11C \uCD94\uAC00"], ["\uC885\uB8CC \uB4A4", "\uBC18\uB0A9\xB7\uC5F0\uC7A5\xB7\uC18C\uC720\uAD8C", "\uC11C\uBA74 \uC694\uCCAD"]] }, "faq": [["\uC784\uB300\uC640 \uB80C\uD0C8\uC740 \uB2E4\uB978 \uAC74\uAC00\uC694?", "\uAC19\uC740 \uC57D\uC815\uC744 \uBD80\uB974\uB294 \uB9D0\uC774 \uB2E4\uB97C \uBFD0\uC785\uB2C8\uB2E4. \uC870\uAC74\uC740 \uC57D\uC815\uC11C \uB0B4\uC6A9\uC73C\uB85C \uBD05\uB2C8\uB2E4."], ["\uB80C\uD0C8 \uAE30\uAE30\uAC00 \uACE0\uC7A5 \uB098\uBA74 \uC601\uC5C5\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uAD50\uCCB4 \uAE30\uAE30\uAC00 \uC624\uB294 \uAE30\uAC04\uC744 \uC57D\uC815\uC11C\uC5D0\uC11C \uBCF4\uACE0, \uADF8\uB3D9\uC548\uC740 \uCE74\uC6B4\uD130 \uACB0\uC81C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4."], ["\uB80C\uD0C8\uB8CC\uC5D0 \uD1B5\uC2E0\uBE44\uAC00 \uB4E4\uC5B4\uAC00\uB098\uC694?", "\uB9E4\uC7A5 \uC778\uD130\uB137\uC744 \uC4F0\uBA74 \uC548 \uB4E4\uC5B4\uAC00\uACE0, \uC804\uC6A9 \uD68C\uC120\uC774\uBA74 \uC6D4 \uC694\uAE08\uC774 \uB354\uD574\uC9D1\uB2C8\uB2E4."], ["\uC57D\uC815 \uC911\uC5D0 \uB9E4\uC7A5\uC744 \uC62E\uAE30\uBA74\uC694?", "\uC774\uC124 \uC870\uAC74\uACFC \uBE44\uC6A9\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4. \uC5C6\uC73C\uBA74 \uC5C5\uCCB4\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uD574\uC9C0\uC704\uC57D\uAE08", "\uD0A4\uC624\uC2A4\uD06C\uC720\uC9C0\uBCF4\uC218AS"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uD14C\uC774\uBE14\uC624\uB354\uBE44\uAD50", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uD14C\uC774\uBE14\uC624\uB354\uC640 \uBE44\uAD50", "title": "\uD0A4\uC624\uC2A4\uD06C\uC640 \uD14C\uC774\uBE14\uC624\uB354 \uC911 \uBB34\uC5C7\uC774 \uB9DE\uB098\uC694? \u2014 \uC190\uB2D8 \uB3D9\uC120\uC73C\uB85C \uAC00\uB974\uB294 \uC120\uD0DD", "desc": "\uD0A4\uC624\uC2A4\uD06C\uC640 \uD14C\uC774\uBE14\uC624\uB354\uB97C \uC190\uB2D8 \uB3D9\uC120, \uC88C\uC11D \uC218, \uBA54\uB274 \uAD6C\uC131, \uACB0\uC81C \uC2DC\uC810, \uBE44\uC6A9 \uAD6C\uC870\uB85C \uBE44\uAD50\uD574 \uD3EC\uC7A5\xB7\uD68C\uC804\uD615 \uB9E4\uC7A5\uACFC \uC88C\uC11D\uD615 \uC2DD\uB2F9\uC5D0 \uAC01\uAC01 \uC5B4\uB290 \uCABD\uC774 \uB9DE\uB294\uC9C0, \uB458\uC744 \uD568\uAED8 \uC4F0\uB294 \uACBD\uC6B0\uC640 \uC120\uD0DD \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC190\uB2D8\uC774 \uC785\uAD6C\uC5D0\uC11C \uC8FC\uBB38\uD558\uACE0 \uAE30\uB2E4\uB9AC\uB294 \uB9E4\uC7A5\uC740 \uD0A4\uC624\uC2A4\uD06C, \uC790\uB9AC\uC5D0 \uC549\uC544 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC740 \uC2DD\uB2F9\uC740 \uD14C\uC774\uBE14\uC624\uB354\uAC00 \uB9DE\uC2B5\uB2C8\uB2E4. \uB458\uC740 \uC8FC\uBB38\uC744 \uBC1B\uB294 \uC790\uB9AC\uAC00 \uB2E4\uB97C \uBFD0 \uACB0\uC81C\uC640 \uC8FC\uBC29 \uC804\uB2EC \uAE30\uB2A5\uC740 \uBE44\uC2B7\uD558\uBBC0\uB85C, \uC190\uB2D8\uC774 \uC5B4\uB514\uC11C \uC8FC\uBB38\uD558\uB294 \uAC83\uC774 \uC790\uC5F0\uC2A4\uB7EC\uC6B4\uC9C0 \uB3D9\uC120\uC73C\uB85C \uAC00\uB985\uB2C8\uB2E4.", "sections": [{ "h": "\uD0A4\uC624\uC2A4\uD06C\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uD3EC\uC7A5 \uBE44\uC911\uC774 \uB192\uACE0 \uC190\uB2D8\uC774 \uC904\uC744 \uC11C\uC11C \uC8FC\uBB38\uD558\uB294 \uB9E4\uC7A5\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274\uAC00 \uC815\uD574\uC838 \uC788\uACE0 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uB4DC\uBB38 \uCE74\uD398, \uBD84\uC2DD, \uD328\uC2A4\uD2B8\uD478\uB4DC\uD615 \uB9E4\uC7A5\uC5D0\uC11C \uD6A8\uACFC\uAC00 \uD07D\uB2C8\uB2E4.", "\uC785\uAD6C\uC5D0 \uAE30\uAE30\uB97C \uB450\uBA74 \uC9C1\uC6D0\uC774 \uC8FC\uBB38\uC744 \uBC1B\uB294 \uC2DC\uAC04\uC774 \uC904\uC5B4 \uCE74\uC6B4\uD130 \uC778\uB825\uC774 \uACB0\uC81C \uB300\uC2E0 \uC81C\uC870\uC5D0 \uC9D1\uC911\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE30\uAE30 \uC55E\uC5D0\uC11C \uBA54\uB274\uB97C \uACE0\uB974\uB294 \uC2DC\uAC04\uC774 \uAE38\uBA74 \uC904\uC774 \uC0DD\uAE30\uBBC0\uB85C \uBA54\uB274 \uAD6C\uC131\uC744 \uB2E8\uC21C\uD558\uAC8C \uB461\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uC801\uAC70\uB098 \uD68C\uC804\uC774 \uBE60\uB978 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uD55C \uB300\uB85C\uB3C4 \uCDA9\uBD84\uD55C \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uD604\uAE08 \uACB0\uC81C\uAC00 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uC9C0\uD3D0 \uC778\uC2DD\uAE30 \uBAA8\uB378\uC744 \uACE0\uB974\uAC70\uB098 \uCE74\uC6B4\uD130 \uACB0\uC81C\uB97C \uB0A8\uACA8 \uB461\uB2C8\uB2E4.", "\uAE30\uAE30 \uD55C \uB300\uAC00 \uBA48\uCD94\uBA74 \uC8FC\uBB38 \uC790\uCCB4\uAC00 \uB9C9\uD788\uBBC0\uB85C \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC744 \uB300\uC548\uC73C\uB85C \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\uD0A4\uC624\uC2A4\uD06C\uB294 \uC785\uAD6C\uC5D0 \uC11C \uC788\uB294 \uC190\uB2D8\uC758 \uACB0\uC81C\uAE4C\uC9C0 \uB05D\uB0B4\uBBC0\uB85C \uCE74\uC6B4\uD130 \uC9C1\uC6D0\uC774 \uC790\uB9AC\uB97C \uBE44\uC6CC\uB3C4 \uC8FC\uBB38\uC774 \uBA48\uCD94\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC7A5 \uC190\uB2D8\uACFC \uB9E4\uC7A5 \uC190\uB2D8\uC758 \uBE44\uC728\uC744 \uC77C\uC8FC\uC77C\uB9CC \uC138\uC5B4 \uBCF4\uBA74 \uC5B4\uB290 \uCABD\uC774 \uB9DE\uB294\uC9C0 \uC218\uCE58\uB85C \uBCF4\uC785\uB2C8\uB2E4.", "\uC785\uAD6C \uAE30\uAE30\uB294 \uC904\uC774 \uBCF4\uC774\uB294 \uC704\uCE58\uC5D0 \uB450\uC5B4\uC57C \uC190\uB2D8\uC774 \uC8FC\uBB38 \uBC29\uC2DD\uC744 \uBC14\uB85C \uC54C\uC544\uCC28\uB9BD\uB2C8\uB2E4."] }, { "h": "\uD14C\uC774\uBE14\uC624\uB354\uAC00 \uB9DE\uB294 \uB9E4\uC7A5\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uC88C\uC11D\uC5D0 \uC549\uC544 \uC2DD\uC0AC\uD558\uBA70 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC740 \uACE0\uAE43\uC9D1, \uC8FC\uC810, \uC2DD\uB2F9\uC5D0 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uB9C8\uB2E4 \uD0DC\uBE14\uB9BF\uC774 \uC788\uC5B4 \uC9C1\uC6D0 \uD638\uCD9C \uC5C6\uC774 \uC8FC\uBB38\uC774 \uB4E4\uC5B4\uAC00\uACE0 \uC8FC\uBC29\uC73C\uB85C \uBC14\uB85C \uC804\uB2EC\uB429\uB2C8\uB2E4.", "\uACB0\uC81C\uB97C \uC790\uB9AC\uC5D0\uC11C \uD558\uBA74 \uACC4\uC0B0\uB300 \uC904\uC774 \uC0AC\uB77C\uC9C0\uACE0, \uC120\uACB0\uC81C \uC124\uC815\uB3C4 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "\uC88C\uC11D \uC218\uB9CC\uD07C \uAE30\uAE30\uAC00 \uD544\uC694\uD558\uBBC0\uB85C \uC88C\uC11D\uC774 \uB9CE\uC744\uC218\uB85D \uAE30\uAE30 \uB300\uC218\uC640 \uC6D4 \uBE44\uC6A9\uC774 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uBA54\uB274 \uC0AC\uC9C4\uACFC \uC124\uBA85\uC744 \uBCF4\uBA70 \uACE0\uB974\uBBC0\uB85C \uBA54\uB274 \uC124\uBA85\uC774 \uAE34 \uB9E4\uC7A5\uC5D0 \uC720\uB9AC\uD569\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF \uBD84\uC2E4\xB7\uD30C\uC190 \uAD00\uB9AC\uAC00 \uD544\uC694\uD558\uACE0, \uADF8 \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC2B5\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uC624\uB354\uB294 \uC190\uB2D8\uC774 \uC790\uB9AC\uC5D0\uC11C \uBA54\uB274\uB97C \uCC9C\uCC9C\uD788 \uBCF4\uAE30 \uB54C\uBB38\uC5D0 \uAC1D\uB2E8\uAC00\uAC00 \uC624\uB974\uB294 \uB9E4\uC7A5\uC774 \uC788\uC9C0\uB9CC \uC5C5\uC885\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uC624\uB354\uB294 \uC190\uB2D8\uC774 \uBA54\uB274\uB97C \uC77D\uB294 \uC2DC\uAC04\uC774 \uAE38\uC5B4\uC838 \uD68C\uC804\uC774 \uB290\uB824\uC9C8 \uC218 \uC788\uC73C\uBBC0\uB85C \uD68C\uC804\uC774 \uC911\uC694\uD55C \uB9E4\uC7A5\uC740 \uC8FC\uC758\uD569\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uC624\uB354\uB294 \uC9C1\uC6D0 \uD638\uCD9C \uAE30\uB2A5\uC774 \uD568\uAED8 \uB4E4\uC5B4\uC624\uBBC0\uB85C \uD638\uCD9C \uC54C\uB9BC\uC744 \uC5B4\uB290 \uAE30\uAE30\uB85C \uBC1B\uC744\uC9C0 \uC815\uD569\uB2C8\uB2E4."] }, { "h": "\uBE44\uC6A9 \uAD6C\uC870\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uD0A4\uC624\uC2A4\uD06C\uB294 \uAE30\uAE30 \uD55C\uB450 \uB300\uC5D0 \uBE44\uC6A9\uC774 \uC9D1\uC911\uB418\uACE0, \uD14C\uC774\uBE14\uC624\uB354\uB294 \uC88C\uC11D \uC218\uB9CC\uD07C \uAE30\uAE30\uC640 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uB458 \uB2E4 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uC788\uC73C\uBA70 \uD3EC\uC2A4 \uC5F0\uB3D9\uACFC \uBC30\uB2EC \uC571 \uC5F0\uB3D9\uC774 \uCD94\uAC00 \uD56D\uBAA9\uC73C\uB85C \uBD99\uC2B5\uB2C8\uB2E4.", "\uD0A4\uC624\uC2A4\uD06C\uB294 \uBCF8\uCCB4 \uAC12\uC774 \uD06C\uACE0, \uD14C\uC774\uBE14\uC624\uB354\uB294 \uB300\uC218\uAC00 \uB9CE\uC544 \uCD1D\uC561\uC774 \uCEE4\uC9C0\uB294 \uAD6C\uC870\uC785\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4 \uC120\uD0DD\uC740 \uB450 \uAE30\uAE30 \uBAA8\uB450 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uB429\uB2C8\uB2E4.", "\uC815\uD655\uD55C \uAE08\uC561\uC740 \uB300\uC218\uC640 \uAD6C\uC131\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB450 \uAE30\uAE30 \uBAA8\uB450 \uC190\uB2D8\uC774 \uC4F0\uB294 \uAE30\uAE30\uB77C \uD654\uBA74 \uC548\uB0B4 \uBB38\uAD6C\uC640 \uC9C1\uC6D0 \uC548\uB0B4\uAC00 \uCD08\uAE30 \uC801\uC751\uC744 \uC88C\uC6B0\uD569\uB2C8\uB2E4.", "\uB458 \uB2E4 \uD504\uB85C\uADF8\uB7A8 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uC788\uC73C\uBBC0\uB85C \uAE30\uAE30\uAC12\uB9CC \uBE44\uAD50\uD558\uBA74 \uCD1D\uBE44\uC6A9\uC774 \uC5B4\uAE0B\uB0A9\uB2C8\uB2E4.", "\uAE30\uAE30 \uC218\uAC00 \uB2E4\uB974\uB2C8 \uC124\uCE58 \uACF5\uC0AC \uBC94\uC704(\uC804\uC6D0\xB7\uD1B5\uC2E0 \uBC30\uC120)\uB3C4 \uB2EC\uB77C\uC838 \uC124\uCE58\uBE44 \uD56D\uBAA9\uC744 \uB530\uB85C \uBE44\uAD50\uD569\uB2C8\uB2E4"] }, { "h": "\uB458\uC744 \uAC19\uC774 \uC4F0\uB294 \uACBD\uC6B0\uB294 \uC5B8\uC81C\uC778\uAC00\uC694?", "p": ["\uD3EC\uC7A5\uACFC \uB9E4\uC7A5 \uC2DD\uC0AC\uAC00 \uC11E\uC778 \uB9E4\uC7A5\uC740 \uC785\uAD6C \uD0A4\uC624\uC2A4\uD06C\uC640 \uC88C\uC11D \uD14C\uC774\uBE14\uC624\uB354\uB97C \uD568\uAED8 \uB450\uAE30\uB3C4 \uD569\uB2C8\uB2E4.", "\uB450 \uAE30\uAE30\uAC00 \uAC19\uC740 \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC5D0 \uC5F0\uACB0\uB3FC\uC57C \uC8FC\uBB38\uC774 \uD55C \uD654\uBA74\uC5D0 \uBAA8\uC774\uBBC0\uB85C \uC5F0\uB3D9 \uAC00\uB2A5\uD55C \uC870\uD569\uC744 \uACE0\uB985\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0\uB294 \uD55C \uAC00\uC9C0\uB85C \uC2DC\uC791\uD558\uACE0 \uC190\uB2D8 \uB3D9\uC120\uC744 \uBCF8 \uB4A4 \uCD94\uAC00\uD558\uB294 \uC21C\uC11C\uAC00 \uBE44\uC6A9\uC744 \uC544\uB08D\uB2C8\uB2E4.", "\uB450 \uAE30\uAE30\uB97C \uD568\uAED8 \uC4F0\uBA74 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uAC01\uAC01 \uBD99\uC73C\uBBC0\uB85C \uCCAD\uAD6C\uC11C \uD56D\uBAA9\uC744 \uB098\uB220 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD568\uAED8 \uC4F8 \uB54C\uB294 \uC785\uAD6C \uAE30\uAE30\uC5D0\uC11C \uC88C\uC11D \uBC88\uD638\uB97C \uACE0\uB974\uAC8C \uD574 \uC8FC\uBB38\uC774 \uD14C\uC774\uBE14\uB85C \uC774\uC5B4\uC9C0\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCC98\uC74C\uBD80\uD130 \uB458 \uB2E4 \uB450\uBA74 \uC6D4 \uBE44\uC6A9\uC774 \uB450 \uBC30\uB85C \uC2DC\uC791\uD558\uB2C8 \uD55C \uAC00\uC9C0\uB85C \uC2DC\uC791\uD558\uB294 \uCABD\uC774 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uD568\uAED8 \uC4F8 \uB54C \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uAE30\uAE30 \uC885\uB958\uBCC4\uB85C \uB530\uB85C \uBD99\uB294\uC9C0 \uD558\uB098\uB85C \uBB36\uC774\uB294\uC9C0 \uD655\uC778\uD558\uBA74 \uBE44\uC6A9 \uC608\uCE21\uC774 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC120\uD0DD \uB4A4 \uD55C \uB2EC \uC6B4\uC601 \uC790\uB8CC\uB85C \uCD94\uAC00 \uC5EC\uBD80\uB97C \uB2E4\uC2DC \uD310\uB2E8\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uC120\uD0DD \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uC190\uB2D8\uC774 \uC8FC\uBB38\uD558\uB294 \uC790\uB9AC(\uC785\uAD6C\xB7\uC88C\uC11D)\uB97C \uBD05\uB2C8\uB2E4.", "\uD3EC\uC7A5 \uBE44\uC911\uACFC \uCD94\uAC00 \uC8FC\uBB38 \uBE48\uB3C4\uB97C \uC149\uB2C8\uB2E4.", "\uC88C\uC11D \uC218\uC5D0 \uB530\uB978 \uAE30\uAE30 \uB300\uC218\uB97C \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9 \uAC00\uB2A5\uD55C \uC870\uD569\uC73C\uB85C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD55C \uAC00\uC9C0\uB85C \uC2DC\uC791\uD574 \uB3D9\uC120\uC744 \uBCF4\uACE0 \uCD94\uAC00 \uC5EC\uBD80\uB97C \uC815\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD0A4\uC624\uC2A4\uD06C\uC640 \uD14C\uC774\uBE14\uC624\uB354 \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uD0A4\uC624\uC2A4\uD06C", "\uD14C\uC774\uBE14\uC624\uB354"], "rows": [["\uC8FC\uBB38 \uC790\uB9AC", "\uC785\uAD6C", "\uC88C\uC11D"], ["\uB9DE\uB294 \uB9E4\uC7A5", "\uD3EC\uC7A5\xB7\uD68C\uC804\uD615", "\uC88C\uC11D\xB7\uCD94\uAC00 \uC8FC\uBB38\uD615"], ["\uAE30\uAE30 \uC218", "1~2\uB300", "\uC88C\uC11D \uC218\uB9CC\uD07C"], ["\uACB0\uC81C \uC2DC\uC810", "\uC8FC\uBB38 \uB54C", "\uC790\uB9AC\uC5D0\uC11C\xB7\uC120\uACB0\uC81C \uAC00\uB2A5"], ["\uC6D4 \uBE44\uC6A9 \uAD6C\uC870", "\uB300\uB2F9 \uC9D1\uC911", "\uB300\uC218 \uBE44\uB840"]] }, "faq": [["\uC791\uC740 \uC2DD\uB2F9\uC740 \uC5B4\uB290 \uCABD\uC774 \uB098\uC740\uAC00\uC694?", "\uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC73C\uBA74 \uD14C\uC774\uBE14\uC624\uB354, \uC8FC\uBB38\uC774 \uB2E8\uC21C\uD558\uBA74 \uD0A4\uC624\uC2A4\uD06C\uC785\uB2C8\uB2E4. \uC88C\uC11D \uC218\uAC00 \uC801\uC73C\uBA74 \uD14C\uC774\uBE14\uC624\uB354 \uB300\uC218\uB3C4 \uC801\uC2B5\uB2C8\uB2E4."], ["\uB458 \uB2E4 \uD3EC\uC2A4\uAE30\uAC00 \uD544\uC694\uD55C\uAC00\uC694?", "\uC8FC\uBC29 \uCD9C\uB825\uACFC \uB9E4\uCD9C \uAD00\uB9AC\uB97C \uD558\uB824\uBA74 \uD3EC\uC2A4 \uC5F0\uB3D9\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uB2E8\uB3C5\uC73C\uB85C \uC4F0\uB294 \uBAA8\uB378\uB3C4 \uC788\uC9C0\uB9CC \uB9E4\uCD9C \uC790\uB8CC\uAC00 \uB098\uB269\uB2C8\uB2E4."], ["\uD0A4\uC624\uC2A4\uD06C\uAC00 \uBA48\uCD94\uBA74 \uC8FC\uBB38\uC744 \uBABB \uBC1B\uB098\uC694?", "\uCE74\uC6B4\uD130 \uC8FC\uBB38\uC744 \uB0A8\uACA8 \uB450\uBA74 \uB429\uB2C8\uB2E4. \uAE30\uAE30 \uD55C \uB300\uB9CC \uC4F0\uB294 \uB9E4\uC7A5\uC740 \uB300\uC548\uC744 \uB461\uB2C8\uB2E4."], ["\uD14C\uC774\uBE14\uC624\uB354\uB294 \uC88C\uC11D\uB9C8\uB2E4 \uAF2D \uB450\uC5B4\uC57C \uD558\uB098\uC694?", "\uC88C\uC11D \uC77C\uBD80\uB9CC \uB450\uACE0 \uB098\uBA38\uC9C0\uB294 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uD558\uB294 \uB9E4\uC7A5\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uB300\uC218\uB294 \uC870\uC815\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "\uD14C\uC774\uBE14\uC624\uB354\uC2DD\uB2F9\uB3C4\uC785\uD6A8\uACFC"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uC18C\uD615\uB9E4\uC7A5", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uC18C\uD615 \uB9E4\uC7A5 \uD0A4\uC624\uC2A4\uD06C", "title": "\uC791\uC740 \uB9E4\uC7A5\uC5D0\uB3C4 \uD0A4\uC624\uC2A4\uD06C\uAC00 \uB9DE\uB098\uC694? \u2014 \uC790\uB9AC\xB7\uC778\uB825\xB7\uC8FC\uBB38\uB7C9\uC73C\uB85C \uBCF4\uB294 \uD310\uB2E8", "desc": "\uC791\uC740 \uB9E4\uC7A5\uC5D0\uC11C \uD0A4\uC624\uC2A4\uD06C\uB97C \uB458 \uB54C \uC790\uB9AC \uD655\uBCF4, \uC778\uB825 \uC808\uAC10 \uD6A8\uACFC, \uD558\uB8E8 \uC8FC\uBB38\uB7C9, \uBA54\uB274 \uC218, \uD0C1\uC0C1\uD615\xB7\uBCBD\uAC78\uC774\uD615 \uC120\uD0DD\uC744 \uC5B4\uB5BB\uAC8C \uD310\uB2E8\uD558\uB294\uC9C0\uC640 \uC18C\uD615 \uB9E4\uC7A5\uC5D0 \uB9DE\uB294 \uAD6C\uC131, \uB3C4\uC785 \uB4A4 \uB2EC\uB77C\uC9C0\uB294 \uC6B4\uC601 \uBC29\uC2DD\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC791\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30\uB97C \uB193\uC744 \uC790\uB9AC\uAC00 \uC788\uACE0 \uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC8FC\uBB38 \uC904\uC774 \uC0DD\uAE34\uB2E4\uBA74 \uD0A4\uC624\uC2A4\uD06C\uAC00 \uB9DE\uACE0, \uC8FC\uBB38\uC774 \uB4DC\uBB3C\uACE0 \uC190\uB2D8\uACFC \uB300\uD654\uAC00 \uC911\uC694\uD55C \uB9E4\uC7A5\uC774\uBA74 \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC774 \uB0AB\uC2B5\uB2C8\uB2E4. \uD0C1\uC0C1\uD615\uC774\uB098 \uBCBD\uAC78\uC774\uD615\uC73C\uB85C \uC790\uB9AC\uB97C \uC904\uC77C \uC218 \uC788\uC73C\uBBC0\uB85C \uACF5\uAC04\uBCF4\uB2E4 \uC8FC\uBB38\uB7C9\uACFC \uC778\uB825 \uC0C1\uD669\uC73C\uB85C \uD310\uB2E8\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC5B4\uB5A4 \uC18C\uD615 \uB9E4\uC7A5\uC5D0 \uD6A8\uACFC\uAC00 \uC788\uB098\uC694?", "p": ["\uD63C\uC790 \uC6B4\uC601\uD558\uB294 \uCE74\uD398\uB098 \uBD84\uC2DD\uC9D1\uCC98\uB7FC \uC81C\uC870\uC640 \uC8FC\uBB38\uC744 \uD55C \uC0AC\uB78C\uC774 \uD558\uB294 \uB9E4\uC7A5\uC5D0\uC11C \uC8FC\uBB38 \uC2DC\uAC04\uC744 \uB35C\uC5B4 \uC90D\uB2C8\uB2E4.", "\uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC904\uC774 \uC0DD\uAE30\uACE0 \uADF8 \uC678 \uC2DC\uAC04\uC740 \uD55C\uAC00\uD55C \uB9E4\uC7A5\uC740 \uAE30\uAE30\uAC00 \uD53C\uD06C\uB97C \uBC1B\uC544 \uC90D\uB2C8\uB2E4.", "\uBA54\uB274\uAC00 \uC5F4 \uAC1C \uC548\uD30E\uC73C\uB85C \uB2E8\uC21C\uD558\uBA74 \uC190\uB2D8\uC774 \uBE68\uB9AC \uACE0\uB974\uACE0 \uC785\uB825 \uC624\uB958\uB3C4 \uC801\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC7A5 \uC190\uB2D8\uC774 \uB9CE\uC544 \uACB0\uC81C\uAC00 \uC9E7\uAC8C \uB05D\uB098\uB294 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uD55C \uB300\uB85C \uCDA9\uBD84\uD569\uB2C8\uB2E4.", "\uC678\uAD6D\uC778 \uC190\uB2D8\uC774 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uB2E4\uAD6D\uC5B4 \uD654\uBA74\uC774 \uC8FC\uBB38 \uC624\uB958\uB97C \uC904\uC785\uB2C8\uB2E4.", "\uBC18\uB300\uB85C \uB2E8\uACE8\uACFC \uB300\uD654\uAC00 \uB9E4\uCD9C\uB85C \uC774\uC5B4\uC9C0\uB294 \uB9E4\uC7A5\uC740 \uAE30\uAE30\uAC00 \uADF8 \uC811\uC810\uC744 \uC904\uC77C \uC218 \uC788\uC5B4 \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC744 \uB0A8\uAE41\uB2C8\uB2E4.", "\uC8FC\uBB38\uC774 \uD558\uB8E8 \uBA87 \uAC74 \uC218\uC900\uC774\uBA74 \uC6D4 \uC0AC\uC6A9\uB8CC \uB300\uBE44 \uD6A8\uACFC\uAC00 \uC791\uC73C\uBBC0\uB85C \uC8FC\uBB38\uB7C9\uC744 \uBA3C\uC800 \uC149\uB2C8\uB2E4.", "\uC8FC\uBB38 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4E0 \uB9CC\uD07C \uC81C\uC870 \uC18D\uB3C4\uAC00 \uB530\uB77C\uC624\uB294\uC9C0 \uBCF4\uACE0, \uC548 \uB530\uB77C\uC624\uBA74 \uAE30\uAE30 \uD6A8\uACFC\uAC00 \uC791\uAC8C \uB290\uAEF4\uC9D1\uB2C8\uB2E4.", "\uC8FC\uBB38\uB7C9\uC774 \uC801\uB354\uB77C\uB3C4 \uC9C1\uC6D0\uC774 \uC790\uB9AC\uB97C \uBE44\uC6B0\uB294 \uC2DC\uAC04\uC774 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30\uAC00 \uC8FC\uBB38\uC744 \uBC1B\uC544 \uC8FC\uB294 \uD6A8\uACFC\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uD6A8\uACFC\uB294 \uC8FC\uBB38 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4E0 \uB9CC\uD07C \uC81C\uC870 \uC18D\uB3C4\uAC00 \uB530\uB77C\uC62C \uB54C \uB098\uBBC0\uB85C \uC81C\uC870 \uB3D9\uC120\uB3C4 \uAC19\uC774 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC790\uB9AC\uB294 \uC5B4\uB5BB\uAC8C \uB9C8\uB828\uD558\uB098\uC694?", "p": ["\uD0C1\uC0C1\uD615\uC740 \uCE74\uC6B4\uD130 \uC704\uC5D0 \uC62C\uB824 \uBC14\uB2E5 \uC790\uB9AC\uB97C \uC4F0\uC9C0 \uC54A\uACE0, \uBCBD\uAC78\uC774\uD615\uC740 \uBCBD\uC5D0 \uBD99\uC5EC \uD1B5\uB85C\uB97C \uBE44\uC6C1\uB2C8\uB2E4.", "\uC2A4\uD0E0\uB4DC\uD615\uC740 \uC785\uAD6C \uCABD \uBC14\uB2E5 \uACF5\uAC04\uC774 \uD544\uC694\uD558\uBBC0\uB85C \uC190\uB2D8 \uB3D9\uC120\uC744 \uB9C9\uC9C0 \uC54A\uB294 \uC704\uCE58\uB97C \uACE0\uB985\uB2C8\uB2E4.", "\uC804\uC6D0 \uCF58\uC13C\uD2B8\uC640 \uC778\uD130\uB137\uC774 \uB2FF\uB294 \uC704\uCE58\uC5EC\uC57C \uD558\uACE0, \uC5C6\uC73C\uBA74 \uBC30\uC120 \uC791\uC5C5\uC774 \uCD94\uAC00\uB429\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uD504\uB9B0\uD130\uB97C \uC4F0\uBA74 \uADF8 \uC790\uB9AC\uB3C4 \uD544\uC694\uD558\uBBC0\uB85C \uC804\uC790 \uC601\uC218\uC99D\uC73C\uB85C \uB300\uC2E0\uD558\uB294 \uBC29\uBC95\uC774 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uD654\uBA74\uC774 \uD587\uBE5B\uC5D0 \uBC18\uC0AC\uB418\uBA74 \uC190\uB2D8\uC774 \uBCF4\uAE30 \uC5B4\uB824\uC6B0\uB2C8 \uCC3D\uAC00\uB294 \uD53C\uD569\uB2C8\uB2E4.", "\uC790\uB9AC \uC120\uD0DD\uC740 \uC124\uCE58 \uC804\uC5D0 \uAE30\uC0AC\uAC00 \uC640\uC11C \uBCF4\uB294 \uAC83\uC774 \uC548\uC804\uD558\uBBC0\uB85C \uBC29\uBB38 \uC2E4\uCE21 \uC5EC\uBD80\uB97C \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD0C1\uC0C1\uD615\uC740 \uCE74\uC6B4\uD130 \uB192\uC774\uC5D0 \uB530\uB77C \uC190\uB2D8\uC774 \uD654\uBA74\uC744 \uBCF4\uAE30 \uC5B4\uB824\uC6B8 \uC218 \uC788\uC5B4 \uC124\uCE58 \uC804\uC5D0 \uB192\uC774\uB97C \uC7AC \uBD05\uB2C8\uB2E4.", "\uBCBD\uAC78\uC774\uD615\uC740 \uBCBD \uC7AC\uC9C8\uC5D0 \uB530\uB77C \uBCF4\uAC15\uC774 \uD544\uC694\uD560 \uC218 \uC788\uC5B4 \uC124\uCE58 \uC804\uC5D0 \uBCBD \uC0C1\uD0DC\uB97C \uC54C\uB824 \uC90D\uB2C8\uB2E4.", "\uC804\uC6D0\uC774 \uBA40\uBA74 \uC5F0\uC7A5\uC120\uC744 \uBC14\uB2E5\uC5D0 \uAE54\uAC8C \uB418\uBBC0\uB85C \uC190\uB2D8 \uB3D9\uC120\uACFC \uACB9\uCE58\uC9C0 \uC54A\uB294 \uACBD\uB85C\uB97C \uBA3C\uC800 \uADF8\uB824 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC18C\uD615 \uB9E4\uC7A5\uC5D0 \uB9DE\uB294 \uAD6C\uC131\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uD654\uBA74\uC774 \uC791\uC740 \uD0C1\uC0C1\uD615 \uBCF8\uCCB4\uC5D0 \uACB0\uC81C \uBAA8\uB4C8 \uB0B4\uC7A5\uD615\uC774\uBA74 \uC678\uBD80 \uB2E8\uB9D0\uAE30 \uC790\uB9AC\uAC00 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uD604\uAE08 \uACB0\uC81C\uB97C \uBC1B\uC9C0 \uC54A\uC73C\uBA74 \uC9C0\uD3D0 \uC778\uC2DD\uAE30\uB97C \uBE7C\uC11C \uAE30\uAE30\uAC12\uACFC \uC790\uB9AC\uB97C \uC904\uC785\uB2C8\uB2E4.", "\uC8FC\uBC29 \uCD9C\uB825\uC774 \uC5C6\uB294 \uB9E4\uC7A5\uC740 \uD3EC\uC2A4 \uC5F0\uB3D9 \uC5C6\uC774 \uB2E8\uB3C5\uC73C\uB85C \uC368\uB3C4 \uB418\uC9C0\uB9CC \uB9E4\uCD9C \uC790\uB8CC\uAC00 \uB098\uB258\uB294 \uC810\uC744 \uAC10\uC548\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uC218\uC815\uC740 \uB9E4\uC7A5\uC774 \uC9C1\uC811 \uD558\uB294 \uD504\uB85C\uADF8\uB7A8\uC744 \uACE0\uB974\uBA74 \uC6D4 \uBE44\uC6A9\uC744 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAD6C\uC131\uACFC \uBE44\uC6A9\uC740 \uB9E4\uC7A5\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB2E8\uB3C5 \uC6B4\uC601 \uBAA8\uB378\uC740 \uB9E4\uCD9C \uC790\uB8CC\uB97C \uB530\uB85C \uB0B4\uB824\uBC1B\uC544 \uD3EC\uC2A4 \uC790\uB8CC\uC640 \uD569\uCCD0\uC57C \uD558\uBBC0\uB85C \uB9C8\uAC10 \uC808\uCC28\uAC00 \uD558\uB098 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uD604\uAE08 \uACB0\uC81C\uAC00 \uC804\uD600 \uC5C6\uB2E4\uBA74 \uCE74\uB4DC \uC804\uC6A9 \uBAA8\uB378\uB85C \uAD6C\uC131\uC744 \uB2E8\uC21C\uD558\uAC8C \uB461\uB2C8\uB2E4.", "\uC18C\uD615 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uACE0\uC7A5 \uB54C \uBC14\uB85C \uB300\uC548\uC774 \uC5C6\uC73C\uBBC0\uB85C \uAD50\uCCB4 \uAE30\uAE30 \uC81C\uACF5 \uC870\uAC74\uC774 \uC788\uB294 \uC57D\uC815\uC744 \uACE0\uB974\uB294 \uD3B8\uC774 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uC218\uC815\uC744 \uB9E4\uC7A5\uC774 \uC9C1\uC811 \uD558\uB294 \uD504\uB85C\uADF8\uB7A8\uC740 \uC124\uCE58 \uB54C \uC218\uC815 \uBC29\uBC95\uC744 \uD55C \uBC88 \uBC30\uC6CC \uB450\uBA74 \uB4A4\uC5D0 \uBE44\uC6A9\uC774 \uB4E4\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uB3C4\uC785 \uB4A4 \uC6B4\uC601\uC740 \uC5B4\uB5BB\uAC8C \uBC14\uB00C\uB098\uC694?", "p": ["\uC190\uB2D8\uC774 \uAE30\uAE30\uC5D0\uC11C \uC8FC\uBB38\uD558\uBA74 \uC9C1\uC6D0\uC740 \uC81C\uC870\uC640 \uC804\uB2EC\uC5D0 \uC9D1\uC911\uD558\uAC8C \uB418\uACE0, \uD53C\uD06C \uC2DC\uAC04 \uC904\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uAE30 \uC0AC\uC6A9\uC774 \uC5B4\uB824\uC6B4 \uC190\uB2D8\uC744 \uC704\uD574 \uCE74\uC6B4\uD130 \uC8FC\uBB38 \uC548\uB0B4\uB97C \uBD99\uC5EC \uB461\uB2C8\uB2E4.", "\uBA54\uB274\uAC00 \uBC14\uB00C\uBA74 \uBC14\uB85C \uBC18\uC601\uD574\uC57C \uC190\uB2D8\uC774 \uC5C6\uB294 \uBA54\uB274\uB97C \uACE0\uB974\uC9C0 \uC54A\uC73C\uBBC0\uB85C \uC218\uC815 \uBC29\uBC95\uC744 \uC775\uD600 \uB461\uB2C8\uB2E4.", "\uAE30\uAE30 \uB9E4\uCD9C\uACFC \uCE74\uC6B4\uD130 \uB9E4\uCD9C\uC744 \uB9C8\uAC10 \uB54C \uD569\uCCD0 \uBCF4\uB294 \uC2B5\uAD00\uC744 \uB4E4\uC785\uB2C8\uB2E4.", "\uCE74\uC6B4\uD130 \uC8FC\uBB38\uACFC \uAE30\uAE30 \uC8FC\uBB38\uC758 \uBE44\uC728\uC744 \uCCAB \uB2EC\uC5D0 \uC801\uC5B4 \uB450\uBA74 \uAE30\uAE30\uB97C \uB354 \uB458\uC9C0 \uD310\uB2E8\uD558\uB294 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uCCAB \uB2EC\uC5D0\uB294 \uAE30\uAE30 \uC8FC\uBB38\uACFC \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC758 \uBE44\uC728\uC744 \uC801\uC5B4 \uD6A8\uACFC\uB97C \uC218\uCE58\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC548\uB0B4 \uBB38\uAD6C\uB294 \uD070 \uAE00\uC528\uB85C '\uCE74\uC6B4\uD130 \uC8FC\uBB38\uB3C4 \uAC00\uB2A5\uD569\uB2C8\uB2E4' \uD55C \uC904\uC774\uBA74 \uCDA9\uBD84\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uB9E4\uCD9C\uACFC \uCE74\uC6B4\uD130 \uB9E4\uCD9C\uC744 \uD569\uCCD0 \uBCF4\uBA74 \uC190\uB2D8\uC774 \uC5B4\uB290 \uCABD\uC744 \uB354 \uC4F0\uB294\uC9C0 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4.", "\uCCAB \uB2EC \uC8FC\uBB38 \uBE44\uC728\uC744 \uC801\uC5B4 \uAE30\uAE30 \uCD94\uAC00 \uC5EC\uBD80\uB97C \uC815\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uB3C4\uC785 \uD310\uB2E8\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uD558\uB8E8 \uC8FC\uBB38 \uAC74\uC218\uC640 \uD53C\uD06C \uC2DC\uAC04 \uC904 \uAE38\uC774\uB97C \uC149\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uB193\uC744 \uC790\uB9AC\uC640 \uC804\uC6D0\xB7\uD1B5\uC2E0\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD0C1\uC0C1\uD615\xB7\uBCBD\uAC78\uC774\uD615\xB7\uC2A4\uD0E0\uB4DC\uD615 \uC911 \uC790\uB9AC\uC5D0 \uB9DE\uB294 \uD615\uD0DC\uB97C \uACE0\uB985\uB2C8\uB2E4.", "\uD544\uC694\uD55C \uAE30\uB2A5\uB9CC \uB123\uC740 \uAD6C\uC131\uC73C\uB85C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uCE74\uC6B4\uD130 \uC8FC\uBB38\uC744 \uB0A8\uAE38\uC9C0 \uC815\uD558\uACE0 \uC124\uCE58\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC18C\uD615 \uB9E4\uC7A5 \uAE30\uAE30 \uD615\uD0DC \uBE44\uAD50", "head": ["\uD615\uD0DC", "\uC790\uB9AC", "\uB9DE\uB294 \uACBD\uC6B0"], "rows": [["\uD0C1\uC0C1\uD615", "\uCE74\uC6B4\uD130 \uC704", "\uACF5\uAC04\uC774 \uC881\uC740 \uB9E4\uC7A5"], ["\uBCBD\uAC78\uC774\uD615", "\uBCBD\uBA74", "\uD1B5\uB85C\uB97C \uBE44\uC6CC\uC57C \uD560 \uB54C"], ["\uC2A4\uD0E0\uB4DC\uD615", "\uC785\uAD6C \uBC14\uB2E5", "\uC904\uC774 \uAE38\uAC8C \uC11C\uB294 \uB9E4\uC7A5"]] }, "faq": [["\uD63C\uC790 \uC6B4\uC601\uD558\uB294 \uB9E4\uC7A5\uC5D0\uB3C4 \uD6A8\uACFC\uAC00 \uC788\uB098\uC694?", "\uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC8FC\uBB38\uC744 \uBC1B\uC544 \uC8FC\uBBC0\uB85C \uC81C\uC870\uC5D0 \uC9D1\uC911\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC8FC\uBB38\uB7C9\uC774 \uC801\uC73C\uBA74 \uD6A8\uACFC\uAC00 \uC791\uC2B5\uB2C8\uB2E4."], ["\uC790\uB9AC\uAC00 \uC815\uB9D0 \uC5C6\uC73C\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uD0C1\uC0C1\uD615\uC774\uB098 \uBCBD\uAC78\uC774\uD615\uC73C\uB85C \uC904\uC774\uACE0, \uADF8\uB798\uB3C4 \uC5B4\uB824\uC6B0\uBA74 \uD14C\uC774\uBE14 \uD0DC\uBE14\uB9BF \uD55C \uB300\uB85C \uB300\uC2E0\uD558\uB294 \uBC29\uBC95\uC774 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC18C\uD615 \uB9E4\uC7A5\uC740 \uC6D4 \uC0AC\uC6A9\uB8CC\uAC00 \uC2FC\uAC00\uC694?", "\uAE30\uAE30 \uD06C\uAE30\uC640 \uBB34\uAD00\uD558\uAC8C \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uBE44\uC2B7\uD569\uB2C8\uB2E4. \uAD6C\uC131\uC73C\uB85C \uC870\uC815\uD569\uB2C8\uB2E4."], ["\uC190\uB2D8\uC774 \uAE30\uAE30\uB97C \uC5B4\uB824\uC6CC\uD558\uBA74\uC694?", "\uCE74\uC6B4\uD130 \uC8FC\uBB38\uC744 \uB0A8\uACA8 \uB450\uACE0 \uD654\uBA74\uC5D0 \uC548\uB0B4 \uBB38\uAD6C\uB97C \uB123\uC73C\uBA74 \uB429\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uD14C\uC774\uBE14\uC624\uB354\uBE44\uAD50", "\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uD574\uC9C0\uC704\uC57D\uAE08", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uD574\uC9C0\xB7\uC704\uC57D\uAE08", "title": "\uD0A4\uC624\uC2A4\uD06C \uD574\uC9C0 \uB54C \uC704\uC57D\uAE08\uC740 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694? \u2014 \uC57D\uC815 \uAE30\uAC04\xB7\uC9C0\uC6D0\uAE08\xB7\uBC18\uB0A9\uC758 \uC138 \uAC00\uC9C0 \uD655\uC778", "desc": "\uD0A4\uC624\uC2A4\uD06C \uD574\uC9C0 \uB54C \uC704\uC57D\uAE08\uC774 \uC0DD\uAE30\uB294 \uC57D\uC815 \uAE30\uAC04 \uC870\uAC74, \uC9C0\uC6D0\uAE08\uC73C\uB85C \uC124\uCE58\uD55C \uAE30\uAE30\uC758 \uC758\uBB34 \uAE30\uAC04\uACFC \uD658\uC218, \uC784\uB300 \uAE30\uAE30 \uBC18\uB0A9\uACFC \uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0, \uACB0\uC81C \uBAA8\uB4C8 \uAC00\uB9F9\uC810 \uC815\uB9AC, \uC790\uB8CC \uBC31\uC5C5\uAE4C\uC9C0 \uD574\uC9C0 \uC804\uD6C4\uC5D0 \uD655\uC778\uD560 \uD56D\uBAA9\uACFC \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD0A4\uC624\uC2A4\uD06C \uD574\uC9C0 \uC704\uC57D\uAE08\uC740 \uC784\uB300\xB7\uB80C\uD0C8 \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC558\uC744 \uB54C \uC0DD\uAE30\uACE0, \uC9C0\uC6D0\uAE08\uC73C\uB85C \uC124\uCE58\uD55C \uAE30\uAE30\uB294 \uC758\uBB34 \uAE30\uAC04 \uC548\uC5D0 \uD574\uC9C0\uD558\uBA74 \uD658\uC218 \uC870\uAC74\uC774 \uB530\uB85C \uBD99\uC2B5\uB2C8\uB2E4. \uC57D\uC815\uC11C\uC758 \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uACFC \uC9C0\uC6D0 \uD611\uC57D\uC11C\uC758 \uC758\uBB34 \uAE30\uAC04 \uB450 \uBB38\uC11C\uB97C \uBA3C\uC800 \uCC3E\uC544 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC704\uC57D\uAE08\uC774 \uC0DD\uAE30\uB294 \uC870\uAC74\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC784\uB300\xB7\uB80C\uD0C8 \uC57D\uC815 \uAE30\uAC04 \uC548\uC5D0 \uD574\uC9C0\uD558\uBA74 \uB0A8\uC740 \uAE30\uAC04\uC5D0 \uB300\uD55C \uC870\uAC74\uC774 \uC57D\uC815\uC11C \uC870\uD56D\uB300\uB85C \uBD99\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4\uD55C \uAE30\uAE30\uB294 \uC704\uC57D\uAE08\uC774 \uC5C6\uC9C0\uB9CC \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9 \uC57D\uC815\uC774 \uB530\uB85C \uC788\uC73C\uBA74 \uADF8\uCABD \uC870\uAC74\uC744 \uBD05\uB2C8\uB2E4.", "\uC124\uCE58\uBE44 \uC9C0\uC6D0\uC774\uB098 \uC0AC\uC740\uD488\uC744 \uBC1B\uC740 \uC870\uAC74\uC774 \uC788\uC73C\uBA74 \uBC18\uD658 \uC870\uD56D\uC774 \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uC9C0 \uC54A\uAC70\uB098 \uD30C\uC190 \uC0C1\uD0DC\uBA74 \uAE30\uAE30\uAC12 \uC870\uD56D\uC774 \uBD99\uC2B5\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5\uB41C \uC57D\uC815\uC740 \uC5F0\uC7A5 \uB4A4 \uC870\uAC74\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4 \uD604\uC7AC \uC57D\uC815 \uC0C1\uD0DC\uB97C \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC0B0\uC815 \uBC29\uC2DD\uC774 \uC57D\uC815\uC11C\uC5D0 \uC5C6\uC73C\uBA74 \uC694\uAD6C\uBC1B\uC740 \uAE08\uC561\uC758 \uADFC\uAC70\uB97C \uAE00\uB85C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC704\uC57D \uC870\uAC74\uC758 \uACC4\uC0B0 \uBC29\uC2DD\uACFC \uAE08\uC561\uC740 \uC57D\uC815\uC11C\uC640 \uC5C5\uCCB4\uC5D0 \uB530\uB77C \uB2E4\uB974\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC804\uC5D0 \uACB0\uC81C \uBAA8\uB4C8\uC758 \uAC00\uB9F9\uC810 \uD574\uC9C0\uB3C4 \uB530\uB85C \uD574\uC57C \uCE74\uB4DC\uC0AC \uCABD \uB4F1\uB85D\uC774 \uC815\uB9AC\uB429\uB2C8\uB2E4.", "\uD574\uC9C0 \uC804\uC5D0 \uC57D\uC815\uC11C\uC640 \uD611\uC57D\uC11C \uB450 \uBB38\uC11C\uC758 \uD574\uC9C0\xB7\uC758\uBB34 \uC870\uD56D\uC744 \uBCF5\uC0AC\uD574 \uB450\uBA74 \uC5C5\uCCB4\uC640 \uC13C\uD130\uC5D0 \uAC01\uAC01 \uC124\uBA85\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uD1B5\uC9C0\uB97C \uBCF4\uB0B8 \uB0A0\uC9DC\uC640 \uBC29\uBC95\uC744 \uAE30\uB85D\uD574 \uB450\uBA74 \uC790\uB3D9 \uC5F0\uC7A5 \uBD84\uC7C1\uC774 \uC0DD\uACBC\uC744 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uC9C0\uC6D0\uAE08 \uAE30\uAE30\uB294 \uBB34\uC5C7\uC774 \uB2E4\uB978\uAC00\uC694?", "p": ["\uC2A4\uB9C8\uD2B8\uC0C1\uC810 \uAC19\uC740 \uC9C0\uC6D0\uC0AC\uC5C5\uC73C\uB85C \uC124\uCE58\uD55C \uAE30\uAE30\uB294 \uD611\uC57D\uC11C\uC5D0 \uC758\uBB34 \uC0AC\uC6A9 \uAE30\uAC04\uC774 \uC788\uC2B5\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04 \uC548\uC5D0 \uD3D0\uC5C5\uD558\uAC70\uB098 \uAE30\uAE30\uB97C \uCC98\uBD84\uD558\uBA74 \uC9C0\uC6D0\uAE08 \uD658\uC218 \uB300\uC0C1\uC774 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD658\uC218 \uC870\uAC74\uACFC \uBE44\uC728\uC740 \uACF5\uACE0\uC640 \uD611\uC57D\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uD611\uC57D\uC11C\uB97C \uBA3C\uC800 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774 \uBD88\uAC00\uD53C\uD558\uBA74 \uC13C\uD130\uC5D0 \uBBF8\uB9AC \uC54C\uB824 \uC808\uCC28\uB97C \uBB3B\uB294 \uAC83\uC774 \uD658\uC218 \uBC94\uC704\uB97C \uC904\uC774\uB294 \uAE38\uC785\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uB2E4\uB978 \uB9E4\uC7A5\uC73C\uB85C \uC62E\uAE30\uB294 \uAC83\uB3C4 \uC2B9\uC778 \uB300\uC0C1\uC77C \uC218 \uC788\uC5B4 \uC774\uC804 \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uAE30\uAE30\uC758 \uD574\uC9C0\uB294 \uC5C5\uCCB4 \uC57D\uC815\uACFC \uC9C0\uC6D0 \uD611\uC57D \uB450 \uAC00\uC9C0\uB97C \uBAA8\uB450 \uC815\uB9AC\uD574\uC57C \uB05D\uB0A9\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uD611\uC57D\uC11C\uB294 \uC124\uCE58 \uB54C \uBC1B\uC740 \uC11C\uB958 \uBB36\uC74C \uC548\uC5D0 \uC788\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uADF8 \uBB36\uC74C\uBD80\uD130 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uC9C0\uC6D0\uAE08 \uD658\uC218\uAC00 \uC0DD\uAE30\uBA74 \uD658\uC218 \uAE08\uC561\uACFC \uB0A9\uBD80 \uAE30\uD55C\uC774 \uD1B5\uC9C0\uB418\uBBC0\uB85C \uD1B5\uC9C0\uBB38\uC744 \uBCF4\uAD00\uD558\uACE0 \uAE30\uD55C\uC744 \uC9C0\uD0B5\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04\uC774 \uB05D\uB09C \uB4A4\uC758 \uD574\uC9C0\uB294 \uD658\uC218 \uC5C6\uC774 \uC5C5\uCCB4 \uC57D\uC815 \uC870\uAC74\uB9CC \uBCF4\uBA74 \uB418\uBBC0\uB85C \uC885\uB8CC\uC77C\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC758\uBB34 \uAE30\uAC04 \uC911 \uAE30\uAE30\uAC00 \uACE0\uC7A5 \uB098 \uAD50\uCCB4\uD558\uB294 \uACBD\uC6B0\uB294 \uBCF4\uD1B5 \uD658\uC218\uC640 \uBB34\uAD00\uD558\uC9C0\uB9CC \uC13C\uD130\uC5D0 \uC54C\uB824 \uAE30\uB85D\uC744 \uB0A8\uAE41\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uC8FC\uBB38 \uC790\uB8CC\uC640 \uBA54\uB274, \uB9E4\uCD9C \uBCF4\uACE0\uC11C\uB97C \uB0B4\uB824\uBC1B\uC544 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0\uC11C \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D, \uBC18\uB0A9 \uD488\uBAA9, \uBC18\uB0A9 \uAE30\uD55C\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9 \uD574\uC9C0\uC640 \uAE30\uAE30 \uBC18\uB0A9\uC744 \uB530\uB85C \uC2E0\uCCAD\uD574\uC57C \uC6D4 \uBE44\uC6A9\uC774 \uBA48\uCDA5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD574 \uB9E4\uC7A5 \uC815\uBCF4\uC640 \uACB0\uC81C \uC124\uC815\uC774 \uB0A8\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC740 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uCD08\uAE30\uD654 \uC804\uC5D0 \uC8FC\uBB38 \uC790\uB8CC\uC640 \uBA54\uB274\uB97C \uB0B4\uB824\uBC1B\uC558\uB294\uC9C0 \uB2E4\uC2DC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uACB0\uC81C \uBAA8\uB4C8 \uAC00\uB9F9\uC810 \uD574\uC9C0\uB294 \uCE74\uB4DC\uC0AC\uBCC4\uB85C \uC9C4\uD589\uB418\uBBC0\uB85C \uC5B4\uB290 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC774 \uB0A8\uC544 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC11C\uC5D0 \uBC18\uB0A9 \uC608\uC815\uC77C\uACFC \uCD08\uAE30\uD654 \uC644\uB8CC \uC5EC\uBD80\uB97C \uD568\uAED8 \uC801\uC73C\uBA74 \uC5C5\uCCB4 \uD655\uC778 \uC808\uCC28\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uD574\uC9C0 \uC608\uC815\uC77C \uC804\uC5D0 \uB9C8\uC9C0\uB9C9 \uC601\uC5C5\uC77C \uC8FC\uBB38 \uC790\uB8CC\uB97C \uB0B4\uB824\uBC1B\uC544\uC57C \uADF8\uB0A0 \uB9E4\uCD9C\uC774 \uC790\uB8CC\uC5D0 \uB0A8\uC2B5\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD488\uBAA9\uC5D0 \uAC70\uCE58\uB300\uB098 \uD504\uB9B0\uD130\uAC00 \uD3EC\uD568\uB3FC \uC788\uC73C\uBA74 \uD568\uAED8 \uBC18\uB0A9\uD574\uC57C \uD488\uBAA9 \uB300\uAE08\uC774 \uCCAD\uAD6C\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0\uAC00 \uB05D\uB09C \uB4A4 \uB0A8\uB294 \uC77C\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0 \uC6D4 \uC774\uC6A9\uB8CC\uC640 \uC0AC\uC6A9\uB8CC\uAC00 \uBE60\uC84C\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD655\uC778\uC99D\uACFC \uD574\uC9C0 \uD655\uC778\uC11C\uB97C \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uAE30\uAE30\uC600\uB2E4\uBA74 \uC13C\uD130\uC5D0 \uCC98\uB9AC \uACB0\uACFC\uB97C \uC54C\uB824 \uC758\uBB34 \uC774\uD589 \uAE30\uB85D\uC744 \uB0A8\uAE41\uB2C8\uB2E4.", "\uC790\uB3D9\uC774\uCCB4\uAC00 \uACC4\uC18D\uB418\uBA74 \uC811\uC218 \uBC88\uD638\uB85C \uBB38\uC758\uD558\uACE0 \uC740\uD589 \uC790\uB3D9\uC774\uCCB4\uB3C4 \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uC13C\uD130\uC5D0 \uC81C\uCD9C\uD55C \uCC98\uB9AC \uACB0\uACFC \uBB38\uC11C\uB294 \uC0AC\uBCF8\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uCC98\uB9AC \uAE30\uAC04 \uB3D9\uC548\uC758 \uC6D4 \uC774\uC6A9\uB8CC \uCCAD\uAD6C \uC5EC\uBD80\uB3C4 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uB2C8 \uD568\uAED8 \uBD05\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4 \uAC00\uB9F9\uC810 \uD574\uC9C0 \uD655\uC778\uC740 \uCE74\uB4DC\uC0AC \uC548\uB0B4\uBB38\uC73C\uB85C \uBC1B\uC544 \uB450\uBA74 \uBBF8\uC815\uC0B0 \uBB38\uC758 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4 \uBA87 \uB2EC\uC774 \uC9C0\uB098\uB3C4 \uCCAD\uAD6C\uAC00 \uC624\uBA74 \uD574\uC9C0 \uD655\uC778\uC11C \uC0AC\uBCF8\uC744 \uBCF4\uB0B4 \uC815\uC815\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uAE30\uAE30\uC600\uB2E4\uBA74 \uC13C\uD130\uC5D0 \uCC98\uB9AC \uACB0\uACFC\uB97C \uC54C\uB9AC\uACE0 \uC0AC\uBCF8\uC744 \uBCF4\uAD00\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uD574\uC9C0 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uC57D\uC815\uC11C\uC640 \uC9C0\uC6D0 \uD611\uC57D\uC11C\uC5D0\uC11C \uD574\uC9C0\xB7\uC758\uBB34 \uC870\uD56D\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uC790\uB8CC\uB97C \uBC31\uC5C5\uD558\uACE0 \uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0\uC640 \uAE30\uAE30 \uBC18\uB0A9\uC744 \uAC01\uAC01 \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD655\uC778\uC99D\uACFC \uD574\uC9C0 \uD655\uC778\uC11C\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uBE44\uC6A9 \uC911\uB2E8\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD574\uC9C0 \uC0C1\uD669\uBCC4 \uD655\uC778", "head": ["\uC0C1\uD669", "\uD655\uC778 \uBB38\uC11C", "\uBE44\uC6A9"], "rows": [["\uC57D\uC815 \uAE30\uAC04 \uC911", "\uC57D\uC815\uC11C \uD574\uC9C0 \uC870\uD56D", "\uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74"], ["\uC57D\uC815 \uC885\uB8CC \uB4A4", "\uC57D\uC815\uC11C \uC885\uB8CC \uC870\uD56D", "\uC5C6\uC74C"], ["\uC9C0\uC6D0\uAE08 \uAE30\uAE30", "\uC9C0\uC6D0 \uD611\uC57D\uC11C", "\uD658\uC218 \uC870\uAC74"], ["\uAD6C\uB9E4 \uAE30\uAE30", "\uD504\uB85C\uADF8\uB7A8 \uC57D\uC815", "\uC0AC\uC6A9\uB8CC \uD574\uC9C0\uB9CC"]] }, "faq": [["\uC9C0\uC6D0\uAE08\uC73C\uB85C \uC124\uCE58\uD55C \uAE30\uAE30\uB97C \uD3D0\uC5C5 \uB54C \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uD611\uC57D\uC11C\uC758 \uC758\uBB34 \uAE30\uAC04\uACFC \uD658\uC218 \uC870\uD56D\uC744 \uBCF4\uACE0 \uC13C\uD130\uC5D0 \uBA3C\uC800 \uBB38\uC758\uD569\uB2C8\uB2E4."], ["\uC704\uC57D\uAE08\uC740 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uB418\uB098\uC694?", "\uB0A8\uC740 \uC57D\uC815 \uAC1C\uC6D4 \uC218\uB97C \uAE30\uC900\uC73C\uB85C \uACC4\uC0B0\uD558\uB294 \uC57D\uC815\uC774 \uB9CE\uC9C0\uB9CC \uC9C0\uC6D0 \uAE30\uAE30\uB294 \uD658\uC218 \uC870\uAC74\uC774 \uB354\uD574\uC9D1\uB2C8\uB2E4. \uB450 \uAE08\uC561 \uBAA8\uB450 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD504\uB85C\uADF8\uB7A8\uB9CC \uD574\uC9C0\uD558\uACE0 \uAE30\uAE30\uB294 \uB458 \uC218 \uC788\uB098\uC694?", "\uAD6C\uB9E4 \uAE30\uAE30\uBA74 \uAC00\uB2A5\uD558\uC9C0\uB9CC \uD504\uB85C\uADF8\uB7A8 \uC5C6\uC774\uB294 \uC8FC\uBB38 \uAE30\uB2A5\uC774 \uBA48\uCDA5\uB2C8\uB2E4."], ["\uBC18\uB0A9 \uB54C \uAE30\uAE30 \uC0C1\uD0DC\uB294 \uC5B4\uB5BB\uAC8C \uBCF4\uB098\uC694?", "\uD30C\uC190 \uC5EC\uBD80\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uAE30\uACE0 \uBC18\uB0A9 \uD655\uC778\uC99D\uC5D0 \uC0C1\uD0DC\uB97C \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8", "\uD0A4\uC624\uC2A4\uD06C\uC9C0\uC6D0\uAE08", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uC720\uC9C0\uBCF4\uC218AS", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uC720\uC9C0\uBCF4\uC218\xB7AS", "title": "\uD0A4\uC624\uC2A4\uD06C \uC720\uC9C0\uBCF4\uC218\uC640 AS\uB294 \uC5B4\uB5BB\uAC8C \uBC1B\uB098\uC694? \u2014 \uACE0\uC7A5 \uC720\uD615\uBCC4 \uB300\uC751 \uCC3D\uAD6C", "desc": "\uD0A4\uC624\uC2A4\uD06C \uACE0\uC7A5\uC744 \uD654\uBA74\xB7\uACB0\uC81C\xB7\uD504\uB9B0\uD130\xB7\uD504\uB85C\uADF8\uB7A8\uC758 \uB124 \uC720\uD615\uC73C\uB85C \uB098\uB220 \uAC01\uAC01 \uC5B4\uB514\uC5D0 \uC5F0\uB77D\uD558\uACE0 \uB9E4\uC7A5\uC774 \uBA3C\uC800 \uD560 \uC218 \uC788\uB294 \uC870\uCE58\uB294 \uBB34\uC5C7\uC778\uC9C0, \uC57D\uC815\uC11C\uC758 \uC720\uC9C0\uBCF4\uC218 \uC870\uAC74\uACFC \uC18C\uBAA8\uD488 \uAD50\uCCB4, \uC815\uAE30 \uC810\uAC80 \uD56D\uBAA9\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD0A4\uC624\uC2A4\uD06C \uACE0\uC7A5\uC740 \uD654\uBA74\xB7\uD130\uCE58, \uACB0\uC81C \uBAA8\uB4C8, \uD504\uB9B0\uD130, \uD504\uB85C\uADF8\uB7A8 \uB124 \uC720\uD615\uC73C\uB85C \uB098\uB258\uACE0 \uC720\uD615\uB9C8\uB2E4 \uC5F0\uB77D\uD560 \uCC3D\uAD6C\uAC00 \uB2E4\uB974\uBBC0\uB85C \uC57D\uC815\uC11C\uC5D0 \uC801\uD78C \uCC3D\uAD6C\uB97C \uC720\uD615\uBCC4\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4. \uC784\uB300 \uC57D\uC815\uC740 \uAD50\uCCB4 \uAE30\uAE30 \uC870\uAC74\uC774 \uD3EC\uD568\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uACE0, \uAD6C\uB9E4 \uAE30\uAE30\uB294 \uBCF4\uC99D \uAE30\uAC04 \uB4A4 \uC218\uB9AC \uBE44\uC6A9\uC774 \uB9E4\uC7A5 \uBAAB\uC774\uB77C \uBCF4\uC99D \uAE30\uAC04\uC744 \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uACE0\uC7A5\uC740 \uC5B4\uB5BB\uAC8C \uB098\uB258\uB098\uC694?", "p": ["\uD654\uBA74\uC774 \uAEBC\uC9C0\uAC70\uB098 \uD130\uCE58\uAC00 \uC548 \uB418\uB294 \uBCF8\uCCB4 \uACE0\uC7A5\uC740 \uAE30\uAE30 \uC5C5\uCCB4 \uCC3D\uAD6C\uC785\uB2C8\uB2E4.", "\uCE74\uB4DC\uAC00 \uC77D\uD788\uC9C0 \uC54A\uAC70\uB098 \uC2B9\uC778\uC774 \uC548 \uB418\uB294 \uACB0\uC81C \uACE0\uC7A5\uC740 \uACB0\uC81C \uBAA8\uB4C8 \uC5C5\uCCB4\uB098 \uBC34\uC0AC \uCC3D\uAD6C\uC785\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC774 \uC548 \uB098\uC624\uB294 \uD504\uB9B0\uD130 \uACE0\uC7A5\uC740 \uC6A9\uC9C0 \uAC78\uB9BC\uC774\uB098 \uD5E4\uB4DC \uC624\uC5FC\uCC98\uB7FC \uB9E4\uC7A5\uC774 \uBA3C\uC800 \uBCFC \uC218 \uC788\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274\uAC00 \uC548 \uB728\uAC70\uB098 \uC8FC\uBB38\uC774 \uD3EC\uC2A4\uB85C \uC548 \uB118\uC5B4\uAC00\uB294 \uD504\uB85C\uADF8\uB7A8 \uACE0\uC7A5\uC740 \uC6D0\uACA9 \uC9C0\uC6D0\uC73C\uB85C \uD574\uACB0\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uB124\uD2B8\uC6CC\uD06C \uB04A\uAE40\uC740 \uB124 \uC720\uD615 \uBAA8\uB450\uC5D0 \uC601\uD5A5\uC744 \uC8FC\uBBC0\uB85C \uACF5\uC720\uAE30\uC640 \uD68C\uC120\uBD80\uD130 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uC720\uD615\uBCC4 \uCC3D\uAD6C\uC640 \uB300\uC751 \uC2DC\uAC04\uC774 \uC801\uD600 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uC5C6\uC73C\uBA74 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uC99D\uC0C1\uC744 \uC0AC\uC9C4\uACFC \uC2DC\uAC04\uC73C\uB85C \uAE30\uB85D\uD574 \uB450\uBA74 \uCC3D\uAD6C\uC5D0 \uC124\uBA85\uC774 \uBE60\uB985\uB2C8\uB2E4.", "\uC99D\uC0C1 \uAE30\uB85D\uC5D0\uB294 \uB0A0\uC9DC\xB7\uC2DC\uAC04\xB7\uC190\uB2D8 \uC0C1\uD669\uC744 \uD568\uAED8 \uC801\uC73C\uBA74 \uC6D0\uC778 \uD30C\uC545\uC774 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uC6A9\uC9C0\uB294 \uADDC\uACA9\uC774 \uB9DE\uC9C0 \uC54A\uC73C\uBA74 \uAC78\uB9BC\uC774 \uBC18\uBCF5\uB418\uBBC0\uB85C \uC124\uCE58 \uB54C \uBC1B\uC740 \uADDC\uACA9\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uB124\uD2B8\uC6CC\uD06C \uB04A\uAE40\uC740 \uACF5\uC720\uAE30 \uC7AC\uC2DC\uC791\uC73C\uB85C \uD574\uACB0\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uACF5\uC720\uAE30 \uC704\uCE58\uC640 \uC804\uC6D0 \uC2A4\uC704\uCE58\uB97C \uC9C1\uC6D0\uC774 \uC54C\uAC8C \uD569\uB2C8\uB2E4.", "\uAC19\uC740 \uC99D\uC0C1\uC774 \uBC18\uBCF5\uB418\uBA74 \uBD80\uD488 \uB178\uD654\uC77C \uC218 \uC788\uC5B4 \uAD50\uCCB4 \uC5EC\uBD80\uB97C \uC5C5\uCCB4\uC640 \uC0C1\uC758\uD569\uB2C8\uB2E4."] }, { "h": "\uB9E4\uC7A5\uC774 \uBA3C\uC800 \uD560 \uC218 \uC788\uB294 \uC870\uCE58\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC804\uC6D0\uC744 \uAED0\uB2E4 \uCF1C\uACE0 \uB124\uD2B8\uC6CC\uD06C \uC5F0\uACB0\uC744 \uD655\uC778\uD558\uB294 \uAC83\uC774 \uCCAB \uC870\uCE58\uC785\uB2C8\uB2E4.", "\uD504\uB9B0\uD130\uB294 \uC6A9\uC9C0\uB97C \uB2E4\uC2DC \uB123\uACE0 \uD5E4\uB4DC\uB97C \uB2E6\uC544 \uBCF4\uBA74 \uD574\uACB0\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uBAA8\uB4C8\uC740 \uCE74\uB4DC \uD22C\uC785\uAD6C\uC5D0 \uC774\uBB3C\uC9C8\uC774 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uC548 \uB418\uBA74 \uCE74\uC6B4\uD130 \uB2E8\uB9D0\uAE30\uB85C \uACB0\uC81C\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC624\uB958\uB294 \uC7AC\uC2DC\uC791 \uB4A4\uC5D0\uB3C4 \uB0A8\uC73C\uBA74 \uC6D0\uACA9 \uC9C0\uC6D0\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE30\uB2E4\uB9AC\uC9C0 \uC54A\uB3C4\uB85D '\uCE74\uC6B4\uD130\uC5D0\uC11C \uC8FC\uBB38\uD574 \uC8FC\uC138\uC694' \uC548\uB0B4\uBB38\uC744 \uAE30\uAE30 \uC606\uC5D0 \uC900\uBE44\uD574 \uB461\uB2C8\uB2E4.", "\uC870\uCE58 \uC21C\uC11C\uB97C \uD55C \uC7A5\uC73C\uB85C \uC801\uC5B4 \uC9C1\uC6D0\uC774 \uBCFC \uC218 \uC788\uAC8C \uBD99\uC785\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC870\uCE58\uB85C \uD574\uACB0\uB41C \uACBD\uC6B0\uB3C4 \uAE30\uB85D\uD574 \uB450\uBA74 \uBC18\uBCF5\uB418\uB294 \uC6D0\uC778\uC744 \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uBAA8\uB4C8 \uC624\uB958\uB294 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uBC34\uC0AC \uCC3D\uAD6C\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uBC88\uD638\uB97C \uD1B5\uC77C\uD574 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC190\uB2D8 \uC55E\uC5D0\uC11C \uAE30\uAE30\uAC00 \uBA48\uCD94\uBA74 \uCE74\uC6B4\uD130 \uC8FC\uBB38 \uC548\uB0B4\uAC00 \uBA3C\uC800\uC774\uACE0 \uC870\uCE58\uB294 \uADF8\uB2E4\uC74C\uC774\uB77C\uB294 \uC21C\uC11C\uB97C \uC9C1\uC6D0\uC5D0\uAC8C \uC54C\uB824 \uB461\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC870\uCE58 \uB4A4\uC5D0\uB3C4 \uC548 \uB418\uBA74 \uC190\uB2D8 \uACB0\uC81C\uB97C \uCE74\uC6B4\uD130\uB85C \uB3CC\uB9AC\uACE0, \uAE30\uAE30 \uC804\uC6D0\uC740 \uCF1C \uB454 \uCC44 \uC5C5\uCCB4 \uC548\uB0B4\uB97C \uAE30\uB2E4\uB9BD\uB2C8\uB2E4.", "\uAE30\uBCF8 \uC870\uCE58 \uC21C\uC11C\uB294 \uC804\uC6D0\u2192\uB124\uD2B8\uC6CC\uD06C\u2192\uC6A9\uC9C0\u2192\uC7AC\uC2DC\uC791\uC758 \uB124 \uB2E8\uACC4\uB85C \uC678\uC6B0\uAE30 \uC27D\uAC8C \uB461\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815\uC11C\uC758 \uC720\uC9C0\uBCF4\uC218 \uC870\uAC74\uC740 \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uAD50\uCCB4 \uAE30\uAE30 \uC81C\uACF5 \uC5EC\uBD80\uC640 \uAC78\uB9AC\uB294 \uC2DC\uAC04, \uBC29\uBB38 \uC218\uB9AC\uC758 \uC720\uC0C1\xB7\uBB34\uC0C1 \uAD6C\uBD84\uC744 \uBD05\uB2C8\uB2E4.", "\uC18C\uBAA8 \uBD80\uD488(\uD504\uB9B0\uD130 \uD5E4\uB4DC\xB7\uD130\uCE58 \uD328\uB110)\uC774 \uBCF4\uC99D \uB300\uC0C1\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC6D0\uACA9 \uC9C0\uC6D0 \uAC00\uB2A5 \uC2DC\uAC04\uACFC \uC57C\uAC04\xB7\uC8FC\uB9D0 \uB300\uC751 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC815\uAE30 \uC810\uAC80\uC774 \uD3EC\uD568\uC774\uBA74 \uC8FC\uAE30\uC640 \uD56D\uBAA9\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uBCF4\uC99D \uAE30\uAC04\uC774 \uB05D\uB09C \uB4A4 \uC218\uB9AC \uBE44\uC6A9 \uAE30\uC900\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC720\uC9C0\uBCF4\uC218 \uC870\uAC74\uC740 \uC784\uB300\uC640 \uAD6C\uB9E4\uC5D0\uC11C \uB2E4\uB974\uBBC0\uB85C \uC790\uC2E0\uC758 \uC57D\uC815 \uC720\uD615\uBD80\uD130 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC29\uBB38 \uC218\uB9AC \uB54C \uCD9C\uC7A5\uBE44\uAC00 \uC720\uC0C1\uC774\uBA74 \uAE30\uC900\uC774 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC5B4\uC57C \uD558\uBBC0\uB85C \uC5C6\uC73C\uBA74 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uBCF4\uC99D \uAE30\uAC04 \uC548\uC5D0 \uC0DD\uAE34 \uACE0\uC7A5\uB3C4 \uC0AC\uC6A9\uC790 \uACFC\uC2E4\uB85C \uBCF4\uBA74 \uC720\uC0C1\uC774 \uB418\uBBC0\uB85C \uACFC\uC2E4 \uAE30\uC900\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC815\uAE30 \uC810\uAC80\uC740 \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uD654\uBA74 \uD130\uCE58 \uBC18\uC751, \uCE74\uB4DC \uD22C\uC785\uAD6C \uC0C1\uD0DC, \uD504\uB9B0\uD130 \uCD9C\uB825 \uC0C1\uD0DC\uB97C \uC8FC\uAE30\uC801\uC73C\uB85C \uBD05\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8\uAC00 \uBC00\uB824 \uC788\uC9C0 \uC54A\uC740\uC9C0, \uBA54\uB274\uAC00 \uD604\uC7AC \uD310\uB9E4 \uBA54\uB274\uC640 \uB9DE\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC804\uC6D0 \uCF00\uC774\uBE14\uACFC \uB124\uD2B8\uC6CC\uD06C \uCF00\uC774\uBE14 \uC811\uCD09 \uC0C1\uD0DC\uB97C \uC810\uAC80\uD569\uB2C8\uB2E4.", "\uC810\uAC80 \uAE30\uB85D\uC744 \uB0A8\uACA8 \uB450\uBA74 \uACE0\uC7A5 \uB54C \uC6D0\uC778\uC744 \uCC3E\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC810\uAC80\uC740 \uC601\uC5C5 \uC804 \uD55C\uAC00\uD55C \uC2DC\uAC04\uC5D0 \uD558\uBA74 \uC190\uB2D8\uC5D0\uAC8C \uC601\uD5A5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC810\uAC80 \uAE30\uB85D\uC5D0 \uC5C5\uB370\uC774\uD2B8 \uB0A0\uC9DC\uB97C \uD568\uAED8 \uC801\uC73C\uBA74 \uC624\uB958\uAC00 \uC5C5\uB370\uC774\uD2B8 \uB4A4 \uC0DD\uACBC\uB294\uC9C0 \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC815\uAE30 \uC810\uAC80\uC740 \uC6D4 1\uD68C \uC815\uB3C4 \uACE0\uC815 \uC694\uC77C\uC5D0 \uD558\uBA74 \uBE60\uB728\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC810\uAC80 \uB54C \uBA54\uB274\uC640 \uAC00\uACA9\uC774 \uD604\uC7AC \uD310\uB9E4 \uAE30\uC900\uACFC \uB9DE\uB294\uC9C0\uB3C4 \uAC19\uC774 \uBCF4\uBA74 \uC190\uB2D8 \uBB38\uC758\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC720\uD615\uBCC4 \uCC3D\uAD6C \uBC88\uD638\uB97C \uAE30\uAE30 \uC606\uC5D0 \uBD99\uC5EC \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uACE0\uC7A5 \uB54C \uB300\uC751 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uC99D\uC0C1\uC744 \uB124 \uC720\uD615 \uC911 \uD558\uB098\uB85C \uBD84\uB958\uD569\uB2C8\uB2E4.", "\uC804\uC6D0\xB7\uB124\uD2B8\uC6CC\uD06C\xB7\uC6A9\uC9C0 \uAC19\uC740 \uAE30\uBCF8 \uC870\uCE58\uB97C \uD569\uB2C8\uB2E4.", "\uD574\uB2F9 \uC720\uD615\uC758 \uCC3D\uAD6C\uC5D0 \uC99D\uC0C1\uACFC \uC0AC\uC9C4\uC744 \uBCF4\uB0C5\uB2C8\uB2E4.", "\uAD50\uCCB4\xB7\uC218\uB9AC \uC77C\uC815\uC744 \uBC1B\uACE0 \uADF8\uB3D9\uC548 \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC73C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4.", "\uCC98\uB9AC \uACB0\uACFC\uC640 \uAC78\uB9B0 \uC2DC\uAC04\uC744 \uAE30\uB85D\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uACE0\uC7A5 \uC720\uD615\uBCC4 \uCC3D\uAD6C", "head": ["\uC720\uD615", "\uC99D\uC0C1", "\uCC3D\uAD6C"], "rows": [["\uBCF8\uCCB4", "\uD654\uBA74\xB7\uD130\uCE58 \uBD88\uB7C9", "\uAE30\uAE30 \uC5C5\uCCB4"], ["\uACB0\uC81C", "\uCE74\uB4DC \uC778\uC2DD\xB7\uC2B9\uC778 \uBD88\uAC00", "\uACB0\uC81C \uBAA8\uB4C8\xB7\uBC34\uC0AC"], ["\uD504\uB9B0\uD130", "\uC601\uC218\uC99D \uBBF8\uCD9C\uB825", "\uB9E4\uC7A5 \uC870\uCE58 \uD6C4 \uAE30\uAE30 \uC5C5\uCCB4"], ["\uD504\uB85C\uADF8\uB7A8", "\uBA54\uB274\xB7\uC8FC\uBB38 \uC624\uB958", "\uC6D0\uACA9 \uC9C0\uC6D0"]] }, "faq": [["\uACE0\uC7A5 \uC911\uC5D0\uB294 \uC601\uC5C5\uC744 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uCE74\uC6B4\uD130 \uC8FC\uBB38\uACFC \uB2E8\uB9D0\uAE30 \uACB0\uC81C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4. \uC548\uB0B4\uBB38\uC744 \uBBF8\uB9AC \uC900\uBE44\uD574 \uB461\uB2C8\uB2E4."], ["\uAD50\uCCB4 \uAE30\uAE30\uB294 \uBA70\uCE60 \uB9CC\uC5D0 \uC624\uB098\uC694?", "\uC57D\uC815\uC11C\uC758 \uB300\uC751 \uC2DC\uAC04 \uC870\uAC74\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uC870\uAC74\uC774 \uC5C6\uC73C\uBA74 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBCF4\uC99D \uAE30\uAC04\uC774 \uC9C0\uB098\uBA74 \uC218\uB9AC\uBE44\uB294 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uBD80\uD488\uACFC \uC791\uC5C5\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD504\uB85C\uADF8\uB7A8 \uC5C5\uB370\uC774\uD2B8\uB294 \uC790\uB3D9\uC778\uAC00\uC694?", "\uB300\uBD80\uBD84 \uC6D0\uACA9\uC73C\uB85C \uB418\uC9C0\uB9CC \uC7AC\uC2DC\uC791\uC774 \uD544\uC694\uD55C \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uC5C5\uB370\uC774\uD2B8 \uB4A4 \uC8FC\uBB38\uC744 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8", "\uD0A4\uC624\uC2A4\uD06C\uBA54\uB274\uBCC0\uACBD\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD0A4\uC624\uC2A4\uD06C\uBA54\uB274\uBCC0\uACBD\uBE44\uC6A9", "product": "\uD0A4\uC624\uC2A4\uD06C", "tail": "\uBA54\uB274 \uBCC0\uACBD \uBE44\uC6A9", "title": "\uD0A4\uC624\uC2A4\uD06C \uBA54\uB274 \uBCC0\uACBD\uC5D0 \uBE44\uC6A9\uC774 \uB4DC\uB098\uC694? \u2014 \uC9C1\uC811 \uC218\uC815\uACFC \uC5C5\uCCB4 \uC218\uC815\uC758 \uCC28\uC774", "desc": "\uD0A4\uC624\uC2A4\uD06C \uBA54\uB274\uB97C \uBC14\uAFC0 \uB54C \uB9E4\uC7A5\uC774 \uC9C1\uC811 \uC218\uC815\uD558\uB294 \uBC29\uC2DD\uACFC \uC5C5\uCCB4\uC5D0 \uB9E1\uAE30\uB294 \uBC29\uC2DD\uC758 \uCC28\uC774, \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB418\uB294 \uC218\uC815 \uBC94\uC704, \uC0AC\uC9C4\uACFC \uD654\uBA74 \uB514\uC790\uC778 \uBCC0\uACBD \uBE44\uC6A9, \uACC4\uC808 \uBA54\uB274\uC640 \uD488\uC808 \uCC98\uB9AC\uB97C \uBE60\uB974\uAC8C \uD558\uB294 \uBC29\uBC95\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBA54\uB274 \uC774\uB984\uACFC \uAC00\uACA9, \uD488\uC808 \uCC98\uB9AC\uCC98\uB7FC \uAC04\uB2E8\uD55C \uBCC0\uACBD\uC740 \uB9E4\uC7A5\uC774 \uAD00\uB9AC \uD654\uBA74\uC5D0\uC11C \uC9C1\uC811 \uD558\uBA74 \uBE44\uC6A9\uC774 \uB4E4\uC9C0 \uC54A\uACE0, \uC0AC\uC9C4 \uAD50\uCCB4\uB098 \uD654\uBA74 \uB514\uC790\uC778 \uBCC0\uACBD\uCC98\uB7FC \uC5C5\uCCB4 \uC791\uC5C5\uC774 \uD544\uC694\uD55C \uD56D\uBAA9\uC740 \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9D1\uB2C8\uB2E4. \uC218\uC815 \uBC94\uC704\uC640 \uD69F\uC218 \uC81C\uD55C\uC740 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uC9C1\uC811 \uC218\uC815\uD560 \uC218 \uC788\uB294 \uBC94\uC704\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uBA54\uB274 \uC774\uB984, \uAC00\uACA9, \uC635\uC158, \uD488\uC808 \uD45C\uC2DC\uB294 \uB300\uBD80\uBD84 \uD504\uB85C\uADF8\uB7A8\uC758 \uAD00\uB9AC \uD654\uBA74\uC5D0\uC11C \uB9E4\uC7A5\uC774 \uBC14\uB85C \uBC14\uAFC0 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uCE74\uD14C\uACE0\uB9AC \uC21C\uC11C\uB098 \uCD94\uCC9C \uBA54\uB274 \uC704\uCE58\uB3C4 \uAD00\uB9AC \uD654\uBA74\uC5D0\uC11C \uC870\uC815\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC601\uC5C5 \uC2DC\uAC04\uB300\uBCC4 \uBA54\uB274(\uC544\uCE68\xB7\uC810\uC2EC)\uB97C \uC124\uC815\uD558\uB294 \uAE30\uB2A5\uC774 \uC788\uC73C\uBA74 \uC9C1\uC811 \uC804\uD658\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC9C1\uC811 \uC218\uC815 \uBC29\uBC95\uC740 \uC124\uCE58 \uB2F9\uC77C \uBC30\uC6CC \uB450\uACE0, \uC9C1\uC6D0\uB3C4 \uD560 \uC218 \uC788\uAC8C \uACC4\uC815\uC744 \uB098\uB215\uB2C8\uB2E4.", "\uC218\uC815 \uB4A4\uC5D0\uB294 \uAE30\uAE30\uC5D0\uC11C \uC2E4\uC81C \uD654\uBA74\uC744 \uC5F4\uC5B4 \uBC18\uC601\uB410\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD00\uB9AC \uD654\uBA74 \uC811\uADFC \uAD8C\uD55C\uC774 \uB9E4\uC7A5\uC5D0 \uC788\uB294\uC9C0 \uC124\uCE58 \uB54C \uD655\uC778\uD558\uACE0, \uC5C6\uC73C\uBA74 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC9C1\uC811 \uC218\uC815 \uBC94\uC704\uB294 \uD504\uB85C\uADF8\uB7A8\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC218\uC815 \uB4A4\uC5D0\uB294 \uD0A4\uC624\uC2A4\uD06C \uD654\uBA74\uACFC \uD3EC\uC2A4 \uD654\uBA74\uC744 \uAC19\uC740 \uBA54\uB274\uB85C \uC5F4\uC5B4 \uAC00\uACA9\uC774 \uAC19\uC740\uC9C0 \uB208\uC73C\uB85C \uB300\uC870\uD569\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uACC4\uC815\uC73C\uB85C \uC218\uC815 \uAD8C\uD55C\uC744 \uB098\uB20C \uB54C \uAC00\uACA9 \uC218\uC815\uC740 \uAD00\uB9AC\uC790\uB9CC \uD558\uB3C4\uB85D \uB450\uBA74 \uC2E4\uC218\uB97C \uC904\uC785\uB2C8\uB2E4.", "\uBA54\uB274 \uC21C\uC11C\uB97C \uBC14\uAFB8\uB294 \uAC83\uB9CC\uC73C\uB85C\uB3C4 \uC798 \uB098\uAC00\uB294 \uBA54\uB274 \uB178\uCD9C\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC9C1\uC811 \uC218\uC815 \uBC94\uC704\uC5D0 \uC21C\uC11C \uBCC0\uACBD\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC5C5\uCCB4 \uC791\uC5C5\uC774 \uD544\uC694\uD55C \uD56D\uBAA9\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uBA54\uB274 \uC0AC\uC9C4 \uCD2C\uC601\uACFC \uD3B8\uC9D1, \uD654\uBA74 \uC804\uCCB4 \uB514\uC790\uC778 \uBCC0\uACBD\uC740 \uC5C5\uCCB4 \uC791\uC5C5\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC0C8 \uCE74\uD14C\uACE0\uB9AC \uAD6C\uC870\uB97C \uB9CC\uB4E4\uAC70\uB098 \uB2E4\uAD6D\uC5B4 \uBA54\uB274\uB97C \uCD94\uAC00\uD558\uB294 \uC791\uC5C5\uB3C4 \uC5C5\uCCB4\uC5D0 \uB9E1\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4\uC640 \uC5F0\uB3D9\uB41C \uBA54\uB274 \uCF54\uB4DC \uBCC0\uACBD\uC740 \uC591\uCABD\uC744 \uB9DE\uCDB0\uC57C \uD558\uBBC0\uB85C \uC5C5\uCCB4\uAC00 \uD568\uAED8 \uBD05\uB2C8\uB2E4.", "\uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB41C \uC218\uC815 \uD69F\uC218\uB97C \uB118\uAE30\uBA74 \uAC74\uB2F9 \uBE44\uC6A9\uC774 \uC0DD\uAE30\uB294 \uC57D\uC815\uC774 \uC788\uC2B5\uB2C8\uB2E4.", "\uC791\uC5C5 \uBE44\uC6A9\uACFC \uAE30\uAC04\uC740 \uBC94\uC704\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5C5\uCCB4 \uC791\uC5C5\uC774 \uD544\uC694\uD55C \uD56D\uBAA9\uC740 \uC694\uCCAD \uB4A4 \uBC18\uC601\uAE4C\uC9C0 \uAE30\uAC04\uC774 \uC788\uC73C\uB2C8 \uBA54\uB274 \uAC1C\uD3B8 \uB0A0\uC9DC\uBCF4\uB2E4 \uC55E\uC11C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uB2E4\uAD6D\uC5B4 \uBA54\uB274\uB294 \uBC88\uC5ED \uC791\uC5C5\uC774 \uB4E4\uC5B4\uAC00 \uC5C5\uCCB4 \uC791\uC5C5\uC774 \uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC73C\uB2C8 \uCC98\uC74C \uC785\uB825 \uB54C \uD568\uAED8 \uB123\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4\uC640 \uC5F0\uB3D9\uB41C \uB9E4\uC7A5\uC740 \uD0A4\uC624\uC2A4\uD06C\uC5D0\uC11C\uB9CC \uAC00\uACA9\uC744 \uBC14\uAFB8\uBA74 \uD3EC\uC2A4\uC640 \uC5B4\uAE0B\uB098\uBBC0\uB85C \uC5C5\uCCB4\uAC00 \uC591\uCABD\uC744 \uD568\uAED8 \uBC14\uAFB8\uB294 \uBC29\uC2DD\uC778\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5C5\uCCB4 \uC791\uC5C5 \uC694\uCCAD\uC740 \uBA54\uC77C\uC774\uB098 \uBA54\uC2DC\uC9C0\uB85C \uB0A8\uACA8 \uC791\uC5C5 \uC644\uB8CC \uB4A4 \uD655\uC778 \uADFC\uAC70\uB97C \uB461\uB2C8\uB2E4."] }, { "h": "\uBE44\uC6A9\uC744 \uC904\uC774\uB294 \uBC29\uBC95\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uACC4\uC808 \uBA54\uB274\uB098 \uD55C\uC815 \uBA54\uB274\uB294 \uBBF8\uB9AC \uB4F1\uB85D\uD574 \uB450\uACE0 \uD488\uC808\xB7\uD310\uB9E4 \uC804\uD658\uB9CC \uC9C1\uC811 \uD558\uBA74 \uC5C5\uCCB4 \uC791\uC5C5\uC774 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC9C4\uC740 \uAC19\uC740 \uAD6C\uB3C4\uB85C \uB9E4\uC7A5\uC5D0\uC11C \uCC0D\uC5B4 \uADDC\uACA9\uB9CC \uB9DE\uCDB0 \uC62C\uB9AC\uBA74 \uCD2C\uC601 \uBE44\uC6A9\uC774 \uBE60\uC9D1\uB2C8\uB2E4.", "\uBA54\uB274 \uAC1C\uD3B8\uC740 \uD55C \uBC88\uC5D0 \uBAA8\uC544\uC11C \uC694\uCCAD\uD558\uBA74 \uAC74\uB2F9 \uBE44\uC6A9\uBCF4\uB2E4 \uC801\uAC8C \uB4DC\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uAC31\uC2E0 \uB54C \uC218\uC815 \uD3EC\uD568 \uD69F\uC218\uB97C \uB298\uB9AC\uB294 \uC870\uAC74\uC744 \uB123\uC744 \uC218 \uC788\uB294\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC790\uC8FC \uBC14\uB00C\uB294 \uBA54\uB274\uAC00 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uC9C1\uC811 \uC218\uC815 \uBC94\uC704\uAC00 \uB113\uC740 \uD504\uB85C\uADF8\uB7A8\uC744 \uACE0\uB974\uB294 \uAC83\uC774 \uC7A5\uAE30\uC801\uC73C\uB85C \uBE44\uC6A9\uC744 \uC904\uC785\uB2C8\uB2E4.", "\uC0AC\uC9C4 \uADDC\uACA9\uACFC \uC6A9\uB7C9 \uAE30\uC900\uC744 \uC124\uCE58 \uB54C \uBC1B\uC544 \uB450\uBA74 \uB9E4\uC7A5\uC5D0\uC11C \uCC0D\uC740 \uC0AC\uC9C4\uC73C\uB85C \uBC14\uB85C \uAD50\uCCB4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274 \uAC1C\uD3B8\uC744 \uBAA8\uC544\uC11C \uC694\uCCAD\uD560 \uB54C\uB294 \uBC14\uB00C\uB294 \uD56D\uBAA9\uC744 \uD45C\uB85C \uC815\uB9AC\uD574 \uB118\uAE30\uBA74 \uC791\uC5C5 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uACC4\uC808 \uBA54\uB274 \uB4F1\uB85D\uC740 \uC0AC\uC9C4\uAE4C\uC9C0 \uBBF8\uB9AC \uB123\uC5B4 \uB450\uBA74 \uD310\uB9E4 \uC804\uD658\uB9CC\uC73C\uB85C \uBC14\uB85C \uB178\uCD9C\uB429\uB2C8\uB2E4.", "\uC9C1\uC811 \uC218\uC815 \uBC94\uC704\uAC00 \uB113\uC740 \uD504\uB85C\uADF8\uB7A8\uC740 \uC124\uCE58\uBE44\uAC00 \uC870\uAE08 \uB192\uC544\uB3C4 \uC6B4\uC601 \uC911 \uC218\uC815 \uBE44\uC6A9\uC774 \uAC70\uC758 \uC5C6\uC5B4 \uC7A5\uAE30\uC801\uC73C\uB85C \uC774\uC775\uC785\uB2C8\uB2E4."] }, { "h": "\uBCC0\uACBD\uD560 \uB54C \uBB34\uC5C7\uC744 \uC8FC\uC758\uD558\uB098\uC694?", "p": ["\uAC00\uACA9\uC744 \uBC14\uAFB8\uBA74 \uD3EC\uC2A4\uC640 \uD0A4\uC624\uC2A4\uD06C\uC5D0 \uB3D9\uC2DC\uC5D0 \uBC18\uC601\uB410\uB294\uC9C0 \uD655\uC778\uD574 \uB450 \uAE30\uAE30 \uAC00\uACA9\uC774 \uB2E4\uB974\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD488\uC808 \uCC98\uB9AC\uB97C \uC78A\uC73C\uBA74 \uC190\uB2D8\uC774 \uC5C6\uB294 \uBA54\uB274\uB97C \uACB0\uC81C\uD558\uBBC0\uB85C \uB9C8\uAC10 \uB54C \uD488\uC808 \uBAA9\uB85D\uC744 \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uC0AC\uC9C4\uC744 \uBC14\uAFC0 \uB54C \uADDC\uACA9\uC774 \uB9DE\uC9C0 \uC54A\uC73C\uBA74 \uD654\uBA74\uC774 \uAE68\uC9C0\uBBC0\uB85C \uD504\uB85C\uADF8\uB7A8\uC774 \uC694\uAD6C\uD558\uB294 \uD06C\uAE30\uB97C \uC9C0\uD0B5\uB2C8\uB2E4.", "\uBCC0\uACBD \uB0B4\uC5ED\uC744 \uB0A0\uC9DC\uC640 \uD568\uAED8 \uC801\uC5B4 \uB450\uBA74 \uB9E4\uCD9C \uBCC0\uD654\uB97C \uBCFC \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uBCC0\uACBD \uAE30\uB85D\uC740 \uB9E4\uCD9C \uBCC0\uD654\uB97C \uBCFC \uB54C\uBFD0 \uC544\uB2C8\uB77C \uC5C5\uCCB4\uC640 \uC218\uC815 \uD69F\uC218\uB97C \uB530\uC9C8 \uB54C\uB3C4 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uBCC0\uACBD \uB4A4 \uCCAB \uC601\uC5C5\uC77C\uC5D0\uB294 \uC190\uB2D8\uC774 \uACE0\uB974\uB294 \uBA54\uB274\uAC00 \uD654\uBA74\uACFC \uAC19\uC740\uC9C0 \uC8FC\uBB38 \uBA87 \uAC74\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBCC0\uACBD \uB0B4\uC5ED \uAE30\uB85D\uC5D0 \uB9E4\uCD9C \uBCC0\uD654\uB3C4 \uD568\uAED8 \uC801\uC73C\uBA74 \uC5B4\uB5A4 \uBCC0\uACBD\uC774 \uD6A8\uACFC\uAC00 \uC788\uC5C8\uB294\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uBCC0\uACBD \uB4A4 \uCCAB \uC601\uC5C5\uC77C\uC5D0 \uC8FC\uBB38 \uBA87 \uAC74\uC73C\uB85C \uBC18\uC601\uC744 \uD655\uC778\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uBA54\uB274 \uBCC0\uACBD\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uBC14\uAFC0 \uD56D\uBAA9\uC744 \uC9C1\uC811 \uC218\uC815 \uAC00\uB2A5 \uC5EC\uBD80\uB85C \uB098\uB215\uB2C8\uB2E4.", "\uC9C1\uC811 \uAC00\uB2A5\uD55C \uD56D\uBAA9\uC740 \uAD00\uB9AC \uD654\uBA74\uC5D0\uC11C \uC218\uC815\uD558\uACE0 \uAE30\uAE30\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5C5\uCCB4 \uC791\uC5C5 \uD56D\uBAA9\uC740 \uBAA8\uC544\uC11C \uD55C \uBC88\uC5D0 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9 \uB9E4\uC7A5\uC740 \uC591\uCABD \uAC00\uACA9\uC774 \uAC19\uC740\uC9C0 \uB300\uC870\uD569\uB2C8\uB2E4.", "\uBCC0\uACBD \uB0B4\uC5ED\uC744 \uB0A0\uC9DC\uC640 \uD568\uAED8 \uAE30\uB85D\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uBA54\uB274 \uBCC0\uACBD \uD56D\uBAA9\uBCC4 \uCC98\uB9AC", "head": ["\uD56D\uBAA9", "\uCC98\uB9AC \uC8FC\uCCB4", "\uBE44\uC6A9"], "rows": [["\uC774\uB984\xB7\uAC00\uACA9\xB7\uD488\uC808", "\uB9E4\uC7A5 \uC9C1\uC811", "\uC5C6\uC74C"], ["\uC0AC\uC9C4 \uAD50\uCCB4", "\uB9E4\uC7A5 \uB610\uB294 \uC5C5\uCCB4", "\uC5C5\uCCB4 \uC2DC \uBCC4\uB3C4"], ["\uD654\uBA74 \uB514\uC790\uC778", "\uC5C5\uCCB4", "\uC57D\uC815\uC5D0 \uB530\uB984"], ["\uCE74\uD14C\uACE0\uB9AC \uAD6C\uC870", "\uB9E4\uC7A5 \uB610\uB294 \uC5C5\uCCB4", "\uD504\uB85C\uADF8\uB7A8\uC5D0 \uB530\uB984"], ["\uD3EC\uC2A4 \uC5F0\uB3D9 \uCF54\uB4DC", "\uC5C5\uCCB4", "\uC791\uC5C5\uBE44 \uD655\uC778"]] }, "faq": [["\uAC00\uACA9 \uBCC0\uACBD\uB3C4 \uC5C5\uCCB4\uC5D0 \uB9E1\uACA8\uC57C \uD558\uB098\uC694?", "\uB300\uBD80\uBD84 \uAD00\uB9AC \uD654\uBA74\uC5D0\uC11C \uC9C1\uC811 \uBC14\uAFC0 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAD8C\uD55C\uC774 \uC5C6\uC73C\uBA74 \uC694\uCCAD\uD569\uB2C8\uB2E4."], ["\uC0AC\uC9C4\uC740 \uC5B4\uB5A4 \uADDC\uACA9\uC73C\uB85C \uC900\uBE44\uD558\uB098\uC694?", "\uD504\uB85C\uADF8\uB7A8\uB9C8\uB2E4 \uC694\uAD6C \uD06C\uAE30\uAC00 \uC788\uC5B4 \uC124\uCE58 \uB54C \uBC1B\uC544 \uB461\uB2C8\uB2E4."], ["\uC218\uC815 \uD69F\uC218 \uC81C\uD55C\uC774 \uC788\uB098\uC694?", "\uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uB41C \uD69F\uC218\uAC00 \uC815\uD574\uC9C4 \uC57D\uC815\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC57D\uC815\uC11C\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBA54\uB274\uB97C \uBC14\uAFB8\uBA74 \uC601\uC5C5 \uC911\uC5D0\uB3C4 \uBC18\uC601\uB418\uB098\uC694?", "\uB300\uBD80\uBD84 \uBC14\uB85C \uBC18\uC601\uB418\uC9C0\uB9CC \uC7AC\uC2DC\uC791\uC774 \uD544\uC694\uD55C \uD504\uB85C\uADF8\uB7A8\uB3C4 \uC788\uC73C\uB2C8 \uD55C\uAC00\uD55C \uC2DC\uAC04\uC5D0 \uBC14\uAFC9\uB2C8\uB2E4."]], "related": ["\uD0A4\uC624\uC2A4\uD06C\uC720\uC9C0\uBCF4\uC218AS", "\uD0A4\uC624\uC2A4\uD06C\uC124\uCE58\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uC784\uB300\uB80C\uD0C8"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uC6D4 \uBE44\uC6A9", "title": "\uD14C\uC774\uBE14\uC624\uB354 \uC6D4 \uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uACC4\uC0B0\uB418\uB098\uC694? \u2014 \uC88C\uC11D \uC218\uC5D0 \uBE44\uB840\uD558\uB294 \uAD6C\uC870", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uC6D4 \uBE44\uC6A9\uC774 \uD0DC\uBE14\uB9BF \uB300\uC218\uC5D0 \uB530\uB978 \uAE30\uAE30 \uC774\uC6A9\uB8CC, \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC, \uD1B5\uC2E0\uBE44, \uAC70\uCE58\uB300\xB7\uCDA9\uC804 \uC7A5\uBE44\uB85C \uAD6C\uC131\uB418\uB294 \uBC29\uC2DD\uACFC \uC88C\uC11D \uC218\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uB294 \uACC4\uC0B0\uBC95, \uC784\uB300\uC640 \uAD6C\uB9E4\uC758 \uCC28\uC774, \uC6D4 \uBE44\uC6A9\uC744 \uC904\uC774\uB294 \uAD6C\uC131\uACFC \uCCAD\uAD6C\uC11C \uD655\uC778 \uD56D\uBAA9\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD14C\uC774\uBE14\uC624\uB354 \uC6D4 \uBE44\uC6A9\uC740 \uD0DC\uBE14\uB9BF \uB300\uC218\uC5D0 \uBE44\uB840\uD558\uB294 \uAE30\uAE30 \uC774\uC6A9\uB8CC\uC640 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uC911\uC2EC\uC774\uACE0, \uC5EC\uAE30\uC5D0 \uD1B5\uC2E0\uBE44\uC640 \uCDA9\uC804 \uC7A5\uBE44\uAC00 \uB354\uD574\uC9C0\uBA70 \uAE08\uC561\uC740 \uB300\uC218\uC640 \uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC838 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uC88C\uC11D\uB9C8\uB2E4 \uAE30\uAE30\uAC00 \uB4E4\uC5B4\uAC00\uBBC0\uB85C \uC88C\uC11D \uC218\uB97C \uBA3C\uC800 \uC138\uACE0 \uC804\uBD80 \uB458\uC9C0 \uC77C\uBD80\uB9CC \uB458\uC9C0 \uC815\uD558\uB294 \uAC83\uC774 \uC6D4 \uBE44\uC6A9\uC744 \uC815\uD558\uB294 \uCCAB \uB2E8\uACC4\uC785\uB2C8\uB2E4.", "sections": [{ "h": "\uC6D4 \uBE44\uC6A9\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uD0DC\uBE14\uB9BF \uBCF8\uCCB4\uB97C \uC784\uB300\uD558\uBA74 \uB300\uB2F9 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uBD99\uACE0, \uAD6C\uB9E4\uD558\uBA74 \uAE30\uAE30\uAC12\uC744 \uCC98\uC74C\uC5D0 \uCE58\uB974\uB294 \uB300\uC2E0 \uC6D4\uC5D0\uB294 \uBE60\uC9D1\uB2C8\uB2E4.", "\uC8FC\uBB38 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uB9E4\uC7A5 \uB2E8\uC704\uB85C \uB9E4\uAE30\uB294 \uACBD\uC6B0\uC640 \uB300\uB2F9\uC73C\uB85C \uB9E4\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC5B4\uB290 \uBC29\uC2DD\uC778\uC9C0 \uBA3C\uC800 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF\uC774 \uB9E4\uC7A5 \uC640\uC774\uD30C\uC774\uB97C \uC4F0\uBA74 \uD1B5\uC2E0\uBE44\uAC00 \uBE60\uC9C0\uACE0, LTE \uC720\uC2EC\uC744 \uC4F0\uBA74 \uB300\uB2F9 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB354\uD574\uC9D1\uB2C8\uB2E4.", "\uD14C\uC774\uBE14 \uAC70\uCE58\uB300\uC640 \uCDA9\uC804 \uC7A5\uBE44\uB294 \uCC98\uC74C\uC5D0 \uC0AC\uB294 \uD488\uBAA9\uC774\uC9C0\uB9CC \uD30C\uC190 \uAD50\uCCB4\uAC00 \uC7A6\uC73C\uBA74 \uC6B4\uC601\uBE44\uB85C \uBD10\uC57C \uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9\uC774\uB098 \uC8FC\uBC29 \uD504\uB9B0\uD130 \uC5F0\uACB0\uC774 \uC0AC\uC6A9\uB8CC\uC5D0 \uD3EC\uD568\uC778\uC9C0 \uCD94\uAC00 \uD56D\uBAA9\uC778\uC9C0\uC5D0 \uB530\uB77C \uC6D4 \uCCAD\uAD6C\uAC00 \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF \uBD84\uC2E4\xB7\uD30C\uC190 \uBCF4\uD5D8\uC774 \uC57D\uC815\uC5D0 \uD3EC\uD568\uB418\uBA74 \uADF8 \uBCF4\uD5D8\uB8CC\uAC00 \uC6D4 \uBE44\uC6A9\uC5D0 \uB4E4\uC5B4 \uC788\uB294 \uAC83\uC774\uBBC0\uB85C \uD56D\uBAA9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCCAD\uAD6C\uC11C\uC5D0 \uAE30\uAE30 \uC774\uC6A9\uB8CC, \uC0AC\uC6A9\uB8CC, \uD1B5\uC2E0\uBE44, \uBD80\uAC00 \uC11C\uBE44\uC2A4\uAC00 \uB098\uB258\uC5B4 \uC788\uB294\uC9C0 \uBCF4\uACE0 \uD569\uCCD0\uC838 \uC788\uC73C\uBA74 \uBD84\uB9AC\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC6D4 \uCCAD\uAD6C\uC11C\uC5D0 \uB300\uC218\uC640 \uD14C\uC774\uBE14 \uBC88\uD638\uAC00 \uD568\uAED8 \uC801\uD600 \uC788\uB294\uC9C0 \uBCF4\uBA74 \uBE60\uC9C4 \uAE30\uAE30\uB098 \uC911\uBCF5 \uCCAD\uAD6C\uB97C \uBC14\uB85C \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC88C\uC11D \uC218\uC5D0 \uB530\uB77C \uC5B4\uB5BB\uAC8C \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC88C\uC11D\uB9C8\uB2E4 \uD55C \uB300\uC529 \uB450\uBA74 \uB300\uC218\uAC00 \uC88C\uC11D \uC218\uC640 \uAC19\uC544\uC838 \uAE30\uAE30 \uC774\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uBE44\uAC00 \uADF8\uB9CC\uD07C \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "4\uC778\uC11D \uC704\uC8FC \uB9E4\uC7A5\uC740 \uD14C\uC774\uBE14\uB2F9 \uD55C \uB300\uB85C \uCDA9\uBD84\uD558\uC9C0\uB9CC, \uB2E8\uCCB4\uC11D\uC740 \uB450 \uB300\uB97C \uB450\uB294 \uB9E4\uC7A5\uB3C4 \uC788\uC5B4 \uD14C\uC774\uBE14 \uAD6C\uC131\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uD68C\uC804\uC774 \uBE60\uB978 \uC2DC\uAC04\uB300\uC5D0\uB9CC \uC4F0\uB294 \uC88C\uC11D\uC740 \uAE30\uAE30\uB97C \uBE7C\uACE0 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uB450\uBA74 \uB300\uC218\uB97C \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB298\uBA74 \uB300\uB2F9 \uC694\uAE08\uC774 \uB0B4\uB824\uAC00\uB294 \uC870\uAC74\uC774 \uC788\uB294 \uC5C5\uCCB4\uB3C4 \uC788\uC73C\uBBC0\uB85C \uAD6C\uAC04\uBCC4 \uC694\uAE08\uC744 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0\uB294 \uC88C\uC11D \uC77C\uBD80\uB9CC \uB450\uACE0 \uC190\uB2D8 \uBC18\uC751\uC744 \uBCF8 \uB4A4 \uB298\uB9AC\uB294 \uBC29\uC2DD\uC774 \uC6D4 \uBE44\uC6A9\uC744 \uC11C\uC11C\uD788 \uC62C\uB9BD\uB2C8\uB2E4.", "\uC88C\uC11D \uC218\uAC00 \uBC14\uB00C\uB294 \uB9AC\uBAA8\uB378\uB9C1\uC774 \uC608\uC815\uB3FC \uC788\uC73C\uBA74 \uC57D\uC815 \uB300\uC218 \uBCC0\uACBD \uC870\uAC74\uB3C4 \uD568\uAED8 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uACC4\uC808\uB9C8\uB2E4 \uBC14\uB00C\uB294 \uB9E4\uC7A5\uC740 \uB300\uC218 \uBCC0\uACBD \uC870\uAC74\uC774 \uC6D4 \uBE44\uC6A9\uC744 \uC88C\uC6B0\uD558\uBBC0\uB85C \uADF8 \uC870\uD56D\uC744 \uD568\uAED8 \uBD05\uB2C8\uB2E4.", "\uC88C\uC11D\uBCC4 \uD68C\uC804\uC728\uC744 \uC801\uC5B4 \uB450\uBA74 \uC5B4\uB290 \uD14C\uC774\uBE14\uC774 \uAE30\uAE30 \uC5C6\uC774\uB3C4 \uB418\uB294\uC9C0 \uD310\uB2E8\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "\uD0DC\uBE14\uB9BF\uC744 \uBE4C\uB9B4 \uB54C\uC640 \uC0B4 \uB54C \uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uAC08\uB9AC\uB098\uC694?", "p": ["\uC784\uB300\uB294 \uB300\uB2F9 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uC788\uACE0 \uC57D\uC815 \uAE30\uAC04\uC774 \uBD99\uC73C\uBA70, \uACE0\uC7A5\xB7\uD30C\uC190 \uAD50\uCCB4 \uC870\uAC74\uC774 \uD3EC\uD568\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB294 \uD0DC\uBE14\uB9BF\uC744 \uB9E4\uC7A5\uC774 \uC18C\uC720\uD574 \uC6D4\uC5D0\uB294 \uC0AC\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uBE44\uB9CC \uB0A8\uC9C0\uB9CC, \uD30C\uC190 \uB54C \uAD50\uCCB4 \uBE44\uC6A9\uC774 \uB9E4\uC7A5 \uBAAB\uC785\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF\uC740 \uC190\uB2D8\uC774 \uB9CC\uC9C0\uB294 \uAE30\uAE30\uB77C \uD30C\uC190 \uBE48\uB3C4\uAC00 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uBCF4\uB2E4 \uB192\uC544 \uAD50\uCCB4 \uC870\uAC74\uC774 \uC6D4 \uBE44\uC6A9 \uD310\uB2E8\uC5D0 \uD07D\uB2C8\uB2E4.", "\uC6B4\uC601 \uAE30\uAC04\uC774 \uAE38\uACE0 \uD30C\uC190\uC774 \uC801\uC740 \uB9E4\uC7A5\uC740 \uAD6C\uB9E4\uAC00, \uAE30\uAC04\uC774 \uC9E7\uAC70\uB098 \uD30C\uC190\uC774 \uC7A6\uC744 \uAC83 \uAC19\uC73C\uBA74 \uC784\uB300\uAC00 \uB9DE\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uB450 \uBC29\uC2DD \uBAA8\uB450 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uAC19\uC73C\uBBC0\uB85C \uAE30\uAE30 \uBE44\uC6A9 \uBD80\uBD84\uB9CC \uBE44\uAD50\uD558\uBA74 \uB429\uB2C8\uB2E4.", "\uD30C\uC190 \uAD50\uCCB4\uAC00 \uC7A6\uC73C\uBA74 \uBCF4\uD5D8 \uD3EC\uD568 \uC57D\uC815\uC758 \uC790\uAE30\uBD80\uB2F4\uACFC \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uBE44\uAD50\uD574 \uC5B4\uB290 \uCABD\uC774 \uC801\uC740\uC9C0 \uBD05\uB2C8\uB2E4."] }, { "h": "\uC6D4 \uBE44\uC6A9\uC744 \uC904\uC774\uB824\uBA74 \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uB9E4\uC7A5 \uC640\uC774\uD30C\uC774\uB85C \uD1B5\uC2E0\uD558\uBA74 \uB300\uB2F9 \uD1B5\uC2E0\uBE44\uAC00 \uBE60\uC9C0\uC9C0\uB9CC, \uC640\uC774\uD30C\uC774\uAC00 \uBD88\uC548\uC815\uD558\uBA74 \uC8FC\uBB38\uC774 \uB04A\uAE30\uBBC0\uB85C \uACF5\uC720\uAE30 \uC704\uCE58\uB97C \uBA3C\uC800 \uC810\uAC80\uD569\uB2C8\uB2E4.", "\uC4F0\uC9C0 \uC54A\uB294 \uBD80\uAC00 \uAE30\uB2A5(\uBA64\uBC84\uC2ED\xB7\uAC8C\uC784\xB7\uAD11\uACE0 \uD654\uBA74)\uC774 \uC0AC\uC6A9\uB8CC\uC5D0 \uBB36\uC5EC \uC788\uC73C\uBA74 \uBE7C \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF \uBCF4\uD638 \uCF00\uC774\uC2A4\uC640 \uAC70\uCE58\uB300 \uACE0\uC815\uC73C\uB85C \uD30C\uC190\uC744 \uC904\uC774\uBA74 \uAD50\uCCB4 \uBE44\uC6A9\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC57D\uC815 \uAC31\uC2E0 \uB54C \uB300\uC218\uC640 \uC694\uAE08\uC744 \uB2E4\uC2DC \uD611\uC758\uD560 \uC218 \uC788\uC73C\uBBC0\uB85C \uAC31\uC2E0 \uB2EC\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC815\uD655\uD55C \uAE08\uC561\uC740 \uB300\uC218\uC640 \uC57D\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uB418, \uD56D\uBAA9 \uAD6C\uC870\uB97C \uC54C\uACE0 \uAC00\uBA74 \uC5B4\uB514\uC11C \uC904\uC77C\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uC6D4 \uBE44\uC6A9\uC740 \uB300\uC218\uB97C \uC815\uD55C \uB4A4\uC5D0\uC57C \uBE44\uAD50\uAC00 \uB418\uBBC0\uB85C \uC88C\uC11D \uBC30\uCE58\uB3C4\uB97C \uBA3C\uC800 \uB9CC\uB4E4\uACE0 \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC640 \uCCAB \uCCAD\uAD6C\uC11C\uC758 \uD56D\uBAA9 \uC774\uB984\uC774 \uB2E4\uB974\uBA74 \uAC19\uC740 \uD56D\uBAA9\uC778\uC9C0 \uC5C5\uCCB4\uC5D0 \uD655\uC778\uD574 \uB461\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774\uB85C \uBC14\uAFB8\uBA74\uC11C \uD1B5\uC2E0\uBE44\uB97C \uC904\uC600\uB2E4\uBA74 \uACF5\uC720\uAE30 \uC131\uB2A5\uC774 \uC8FC\uBB38\uB7C9\uC744 \uAC10\uB2F9\uD558\uB294\uC9C0 \uD53C\uD06C \uC2DC\uAC04\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCCAD\uAD6C\uC11C\uC758 \uB300\uC218\uC640 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB9E4\uB2EC \uB300\uC870\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uBE44\uC6A9 \uACC4\uC0B0\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uD14C\uC774\uBE14 \uC218\uC640 \uAE30\uAE30\uB97C \uB458 \uC88C\uC11D\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uB300\uB2F9 \uAE30\uAE30 \uC774\uC6A9\uB8CC\xB7\uC0AC\uC6A9\uB8CC\xB7\uD1B5\uC2E0\uBE44 \uD56D\uBAA9\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF \uC784\uB300\uC640 \uAD6C\uB9E4\uB97C \uB300\uC218\uC640 \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uB85C \uACF1\uD574 \uCD1D\uBE44\uC6A9\uC744 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uD30C\uC190 \uAD50\uCCB4 \uC870\uAC74\uACFC \uBD80\uAC00 \uC11C\uBE44\uC2A4 \uD3EC\uD568 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCCAD\uAD6C\uC11C \uD56D\uBAA9\uC774 \uACAC\uC801\uACFC \uAC19\uC740\uC9C0 \uCCAB \uB2EC\uC5D0 \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC6D4 \uBE44\uC6A9 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "\uACC4\uC0B0 \uB2E8\uC704", "\uC904\uC774\uB294 \uBC29\uBC95"], "rows": [["\uAE30\uAE30 \uC774\uC6A9\uB8CC", "\uB300\uB2F9", "\uC88C\uC11D \uC77C\uBD80\uB9CC \uC124\uCE58"], ["\uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC", "\uB9E4\uC7A5 \uB610\uB294 \uB300\uB2F9", "\uBD80\uAC00 \uAE30\uB2A5 \uC815\uB9AC"], ["\uD1B5\uC2E0\uBE44", "\uB300\uB2F9(LTE)", "\uB9E4\uC7A5 \uC640\uC774\uD30C\uC774"], ["\uD30C\uC190 \uAD50\uCCB4", "\uAC74\uB2F9 \uB610\uB294 \uBCF4\uD5D8", "\uCF00\uC774\uC2A4\xB7\uAC70\uCE58\uB300"], ["\uD3EC\uC2A4 \uC5F0\uB3D9", "\uB9E4\uC7A5 \uB2E8\uC704", "\uC124\uCE58 \uB54C \uD3EC\uD568 \uD655\uC778"]] }, "faq": [["\uC88C\uC11D \uC804\uBD80\uC5D0 \uB450\uC5B4\uC57C \uD558\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uB2E8\uCCB4\uC11D\uC774\uB098 \uD68C\uC804\uC11D\uC740 \uBE7C\uACE0 \uC2DC\uC791\uD558\uB294 \uB9E4\uC7A5\uC774 \uB9CE\uC2B5\uB2C8\uB2E4. \uB300\uC218\uB294 \uB098\uC911\uC5D0 \uB298\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], ["\uD0DC\uBE14\uB9BF\uC774 \uAE68\uC9C0\uBA74 \uB204\uAC00 \uBD80\uB2F4\uD558\uB098\uC694?", "\uC784\uB300\uB294 \uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB974\uACE0, \uAD6C\uB9E4\uB294 \uB9E4\uC7A5 \uBD80\uB2F4\uC785\uB2C8\uB2E4. \uBCF4\uD5D8 \uD3EC\uD568 \uC5EC\uBD80\uB97C \uBD05\uB2C8\uB2E4."], ["\uD1B5\uC2E0\uBE44\uB97C \uC548 \uB0B4\uB294 \uBC29\uBC95\uC774 \uC788\uB098\uC694?", "\uB9E4\uC7A5 \uC640\uC774\uD30C\uC774\uB97C \uC4F0\uBA74 \uB429\uB2C8\uB2E4. \uB2E4\uB9CC \uB04A\uAE40\uC774 \uC7A6\uC73C\uBA74 \uC8FC\uBB38 \uB204\uB77D\uC774 \uC0DD\uAE30\uBBC0\uB85C \uACF5\uC720\uAE30\uB97C \uC810\uAC80\uD569\uB2C8\uB2E4."], ["\uC6D4 \uBE44\uC6A9\uC774 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uB300\uC218\uC640 \uC57D\uC815 \uC870\uAC74\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC124\uCE58\uC808\uCC28", "\uD14C\uC774\uBE14\uC624\uB354\uC784\uB300\uC57D\uC815", "\uD14C\uC774\uBE14\uC624\uB354\uC18C\uADDC\uBAA8\uB9E4\uC7A5"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uC124\uCE58\uC808\uCC28", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uC124\uCE58 \uC808\uCC28", "title": "\uD14C\uC774\uBE14\uC624\uB354 \uC124\uCE58\uB294 \uC5B4\uB5BB\uAC8C \uC9C4\uD589\uB418\uB098\uC694? \u2014 \uC88C\uC11D \uBC30\uCE58\uBD80\uD130 \uCCAB \uC8FC\uBB38\uAE4C\uC9C0", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uC124\uCE58\uAC00 \uC88C\uC11D \uBC30\uCE58\uB3C4 \uD655\uC778, \uC640\uC774\uD30C\uC774 \uC810\uAC80, \uBA54\uB274 \uC785\uB825, \uD0DC\uBE14\uB9BF \uAC70\uCE58, \uD3EC\uC2A4\xB7\uC8FC\uBC29 \uC5F0\uB3D9, \uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC758 \uC21C\uC11C\uB85C \uC9C4\uD589\uB418\uB294 \uACFC\uC815\uACFC \uB9E4\uC7A5\uC774 \uC124\uCE58 \uC804\uC5D0 \uC900\uBE44\uD560 \uAC83, \uC124\uCE58 \uB2F9\uC77C \uC810\uAC80 \uD56D\uBAA9, \uC124\uCE58 \uB4A4 \uCCAB \uC8FC\uC5D0 \uBCFC \uAC83\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD14C\uC774\uBE14\uC624\uB354 \uC124\uCE58\uB294 \uC88C\uC11D \uBC30\uCE58\uB3C4\uB85C \uB300\uC218\uB97C \uC815\uD558\uACE0 \uC640\uC774\uD30C\uC774\uB97C \uC810\uAC80\uD55C \uB4A4 \uBA54\uB274\uB97C \uC785\uB825\uD558\uACE0 \uD0DC\uBE14\uB9BF\uC744 \uAC70\uCE58\uD574 \uD3EC\uC2A4\uC640 \uC8FC\uBC29 \uD504\uB9B0\uD130\uC5D0 \uC5F0\uACB0\uD558\uACE0 \uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC73C\uB85C \uB05D\uB0A9\uB2C8\uB2E4. \uAE30\uAE30\uB97C \uB193\uB294 \uC77C\uBCF4\uB2E4 \uC640\uC774\uD30C\uC774 \uC0C1\uD0DC\uC640 \uBA54\uB274 \uC785\uB825\uC774 \uC124\uCE58\uC77C\uC744 \uC88C\uC6B0\uD558\uBBC0\uB85C \uADF8 \uB450 \uAC00\uC9C0\uB97C \uBA3C\uC800 \uC900\uBE44\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC124\uCE58 \uC804\uC5D0 \uBB34\uC5C7\uC744 \uC900\uBE44\uD558\uB098\uC694?", "p": ["\uD14C\uC774\uBE14 \uBC88\uD638\uAC00 \uC801\uD78C \uC88C\uC11D \uBC30\uCE58\uB3C4\uB97C \uB9CC\uB4E4\uC5B4 \uC5B4\uB290 \uD14C\uC774\uBE14\uC5D0 \uAE30\uAE30\uB97C \uB458\uC9C0 \uD45C\uC2DC\uD569\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC640\uC774\uD30C\uC774\uAC00 \uBAA8\uB4E0 \uC88C\uC11D\uC5D0 \uB2FF\uB294\uC9C0 \uC2A4\uB9C8\uD2B8\uD3F0\uC73C\uB85C \uC790\uB9AC\uB9C8\uB2E4 \uD655\uC778\uD558\uACE0, \uC57D\uD55C \uACF3\uC740 \uACF5\uC720\uAE30 \uCD94\uAC00\uB97C \uACC4\uD68D\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uC774\uB984, \uAC00\uACA9, \uC635\uC158, \uC0AC\uC9C4\uC744 \uD45C\uB85C \uC815\uB9AC\uD574 \uB450\uBA74 \uC785\uB825\uC774 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uACFC \uC8FC\uBC29 \uD504\uB9B0\uD130 \uBAA8\uB378\uBA85\uC744 \uC54C\uB824 \uC8FC\uC5B4\uC57C \uC5F0\uB3D9 \uAC00\uB2A5\uD55C \uAD6C\uC131\uC73C\uB85C \uC811\uC218\uB429\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uB9C8\uB2E4 \uC804\uC6D0\uC774 \uB2FF\uB294\uC9C0 \uBCF4\uACE0, \uC548 \uB2FF\uC73C\uBA74 \uCDA9\uC804\uC2DD \uAC70\uCE58\uB300\uB85C \uD560\uC9C0 \uC815\uD569\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uD638\uCD9C, \uC120\uACB0\uC81C, \uBD84\uD560 \uACB0\uC81C \uAC19\uC740 \uAE30\uB2A5 \uC911 \uB9E4\uC7A5\uC5D0\uC11C \uC4F8 \uAC83\uC744 \uBBF8\uB9AC \uC815\uD574 \uB461\uB2C8\uB2E4.", "\uAC1C\uC5C5 \uC804 \uC124\uCE58\uB77C\uBA74 \uC9C1\uC6D0 \uC5F0\uC2B5 \uC2DC\uAC04\uC744 \uD558\uB8E8 \uC774\uC0C1 \uB450\uB3C4\uB85D \uC124\uCE58\uC77C\uC744 \uC7A1\uC2B5\uB2C8\uB2E4.", "\uC88C\uC11D \uBC30\uCE58\uB3C4\uC5D0 \uC804\uC6D0 \uCF58\uC13C\uD2B8 \uC704\uCE58\uAE4C\uC9C0 \uD45C\uC2DC\uD558\uBA74 \uCDA9\uC804 \uBC29\uC2DD\uC744 \uC815\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uAC1C\uC5C5 \uC804 \uC124\uCE58\uB294 \uBA54\uB274 \uC0AC\uC9C4 \uC900\uBE44\uAC00 \uB2A6\uC5B4\uC9C0\uAE30 \uC26C\uC6B0\uB2C8 \uC0AC\uC9C4 \uC5C6\uB294 \uBA54\uB274\uB85C \uBA3C\uC800 \uC5F4\uACE0 \uC0AC\uC9C4\uC740 \uB4A4\uC5D0 \uB123\uB294 \uBC29\uBC95\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uAC70\uCE58 \uC704\uCE58\uB294 \uC190\uB2D8\uC774 \uC74C\uC2DD\uC744 \uB193\uB294 \uC790\uB9AC\uC640 \uACB9\uCE58\uC9C0 \uC54A\uAC8C \uD14C\uC774\uBE14 \uC548\uCABD \uBAA8\uC11C\uB9AC\uB85C \uC815\uD569\uB2C8\uB2E4.", "\uD14C\uC774\uBE14 \uBC88\uD638\uB294 \uD3EC\uC2A4\uC640 \uD14C\uC774\uBE14\uC624\uB354\uC5D0\uC11C \uAC19\uC740 \uBC88\uD638 \uCCB4\uACC4\uB97C \uC368\uC57C \uC8FC\uBB38\uC774 \uB9DE\uAC8C \uB4E4\uC5B4\uAC11\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB2F9\uC77C \uC791\uC5C5\uC740 \uC5B4\uB5BB\uAC8C \uC774\uC5B4\uC9C0\uB098\uC694?", "p": ["\uAE30\uC0AC\uAC00 \uD0DC\uBE14\uB9BF\uC744 \uD14C\uC774\uBE14\uC5D0 \uAC70\uCE58\uD558\uACE0 \uC640\uC774\uD30C\uC774\uC5D0 \uC5F0\uACB0\uD55C \uB4A4 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uAE30\uAE30\uB9C8\uB2E4 \uB4F1\uB85D\uD569\uB2C8\uB2E4.", "\uBA54\uB274\uB97C \uC62C\uB9AC\uACE0 \uD3EC\uC2A4\uC640 \uC8FC\uBC29 \uD504\uB9B0\uD130\uC5D0 \uC5F0\uACB0\uD574 \uC8FC\uBB38\uC774 \uC8FC\uBC29\uC73C\uB85C \uCD9C\uB825\uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD14C\uC774\uBE14 \uD55C \uACF3\uC5D0\uC11C \uC8FC\uBB38 \u2192 \uC8FC\uBC29 \uCD9C\uB825 \u2192 \uACB0\uC81C \u2192 \uD3EC\uC2A4 \uB9E4\uCD9C \uBC18\uC601\uAE4C\uC9C0 \uD55C \uBC14\uD034\uB97C \uC2E4\uC81C\uB85C \uB3CC\uB9BD\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uD638\uCD9C \uAE30\uB2A5\uACFC \uACB0\uC81C \uBC29\uC2DD(\uC120\uACB0\uC81C\xB7\uD6C4\uACB0\uC81C)\uC744 \uB9E4\uC7A5 \uBC29\uC2DD\uC5D0 \uB9DE\uCDB0 \uC124\uC815\uD569\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uC8FC\uBB38\uC740 \uB2F9\uC77C \uCDE8\uC18C\uD574 \uB9E4\uCD9C \uC790\uB8CC\uC5D0 \uB0A8\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uBCC4 \uD14C\uC774\uBE14 \uBC88\uD638\uAC00 \uB9DE\uB294\uC9C0 \uBAA8\uB4E0 \uD14C\uC774\uBE14\uC5D0\uC11C \uD55C \uBC88\uC529 \uD654\uBA74\uC744 \uC5F4\uC5B4 \uBD05\uB2C8\uB2E4.", "\uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uC640 \uC6D0\uACA9 \uC9C0\uC6D0 \uBC29\uBC95\uC744 \uBC1B\uC544 \uCE74\uC6B4\uD130\uC5D0 \uBD99\uC5EC \uB461\uB2C8\uB2E4.", "\uD14C\uC774\uBE14 \uBC88\uD638 \uB4F1\uB85D\uC774 \uD2C0\uB9AC\uBA74 \uC8FC\uBB38\uC774 \uB2E4\uB978 \uD14C\uC774\uBE14\uB85C \uAC00\uBBC0\uB85C \uBAA8\uB4E0 \uD14C\uC774\uBE14\uC5D0\uC11C \uD55C \uBC88\uC529 \uD655\uC778\uD558\uB294 \uAC83\uC774 \uAC00\uC7A5 \uC911\uC694\uD569\uB2C8\uB2E4.", "\uD638\uCD9C \uAE30\uB2A5\uC740 \uC5B4\uB290 \uC9C1\uC6D0 \uAE30\uAE30\uB85C \uC54C\uB9BC\uC774 \uAC00\uB294\uC9C0\uAE4C\uC9C0 \uC124\uC815\uD574\uC57C \uD638\uCD9C\uC774 \uBB3B\uD788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58 \uB4A4 \uCCAB \uC8FC\uC5D0\uB294 \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uC640\uC774\uD30C\uC774 \uB04A\uAE40\uC73C\uB85C \uC8FC\uBB38\uC774 \uB204\uB77D\uB418\uB294 \uD14C\uC774\uBE14\uC774 \uC788\uB294\uC9C0 \uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC9C0\uCF1C\uBD05\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE30\uAE30 \uC0AC\uC6A9\uC744 \uC5B4\uB824\uC6CC\uD558\uB294 \uC9C0\uC810(\uC635\uC158 \uC120\uD0DD\xB7\uACB0\uC81C \uD654\uBA74)\uC744 \uC9C1\uC6D0\uC774 \uC801\uC5B4 \uB450\uBA74 \uD654\uBA74 \uAC1C\uC120 \uC694\uCCAD\uC5D0 \uC501\uB2C8\uB2E4.", "\uC8FC\uBC29 \uCD9C\uB825\uC774 \uBC00\uB9AC\uAC70\uB098 \uC21C\uC11C\uAC00 \uC11E\uC774\uB294\uC9C0 \uBCF4\uACE0, \uC11E\uC774\uBA74 \uCD9C\uB825 \uC124\uC815\uC744 \uC870\uC815\uD569\uB2C8\uB2E4.", "\uD0DC\uBE14\uB9BF \uBC30\uD130\uB9AC\uAC00 \uC601\uC5C5 \uC911\uC5D0 \uB5A8\uC5B4\uC9C0\uB294\uC9C0 \uD655\uC778\uD574 \uCDA9\uC804 \uBC29\uC2DD\uC744 \uBC14\uAFC9\uB2C8\uB2E4.", "\uCCAB \uC8FC \uB9E4\uCD9C\uC774 \uD3EC\uC2A4\uC5D0 \uBE60\uC9D0\uC5C6\uC774 \uC7A1\uD614\uB294\uC9C0 \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB85C \uB300\uC870\uD569\uB2C8\uB2E4.", "\uC124\uC815 \uBCC0\uACBD \uC694\uCCAD\uC740 \uCCAB \uC8FC\uC5D0 \uBAA8\uC544\uC11C \uD55C \uBC88\uC5D0 \uB118\uAE30\uBA74 \uCC98\uB9AC\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uC8FC\uBB38 \uB204\uB77D\uC774 \uC0DD\uAE34 \uD14C\uC774\uBE14\uC740 \uC640\uC774\uD30C\uC774 \uC2E0\uD638\uB97C \uADF8 \uC790\uB9AC\uC5D0\uC11C \uB2E4\uC2DC \uC7AC \uBCF4\uACE0 \uACF5\uC720\uAE30 \uC704\uCE58\uB97C \uC870\uC815\uD569\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE30\uAE30 \uC0AC\uC6A9\uC744 \uC5B4\uB824\uC6CC\uD558\uB294 \uC9C0\uC810\uC740 \uD654\uBA74 \uBB38\uAD6C\uB97C \uBC14\uAFB8\uAC70\uB098 \uCCAB \uD654\uBA74\uC5D0 \uC548\uB0B4\uB97C \uB123\uC5B4 \uD574\uACB0\uD569\uB2C8\uB2E4.", "\uC8FC\uBB38 \uB204\uB77D\uC740 \uC190\uB2D8\uC774 \uC8FC\uBB38\uD588\uB2E4\uACE0 \uD558\uB294\uB370 \uC8FC\uBC29\uC5D0 \uC548 \uB098\uC628 \uAC74\uC218\uB97C \uC801\uC5B4 \uB450\uBA74 \uC6D0\uC778\uC744 \uCC3E\uAE30 \uC27D\uC2B5\uB2C8\uB2E4."] }, { "h": "\uC124\uCE58\uC77C\uC774 \uBC00\uB9AC\uB294 \uC6D0\uC778\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC640\uC774\uD30C\uC774\uAC00 \uC88C\uC11D \uC77C\uBD80\uC5D0 \uB2FF\uC9C0 \uC54A\uC544 \uACF5\uC720\uAE30 \uACF5\uC0AC\uAC00 \uBA3C\uC800 \uD544\uC694\uD55C \uACBD\uC6B0\uAC00 \uAC00\uC7A5 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uBA54\uB274 \uC790\uB8CC\uAC00 \uC900\uBE44\uB418\uC9C0 \uC54A\uC544 \uC785\uB825\uC774 \uBC00\uB9AC\uB294 \uACBD\uC6B0\uB3C4 \uD754\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC774 \uD14C\uC774\uBE14\uC624\uB354\uC640 \uC5F0\uB3D9\uB418\uC9C0 \uC54A\uB294 \uC870\uD569\uC774\uBA74 \uD504\uB85C\uADF8\uB7A8\uC744 \uBC14\uAFB8\uAC70\uB098 \uB2E8\uB3C5 \uC6B4\uC601\uC73C\uB85C \uBC14\uAFD4\uC57C \uD569\uB2C8\uB2E4.", "\uAE30\uC0AC \uBC29\uBB38 \uC77C\uC815\uC740 \uC9C0\uC5ED\uACFC \uB300\uC218\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB9CE\uC73C\uBA74 \uC124\uCE58\uC5D0 \uD558\uB8E8 \uC774\uC0C1 \uAC78\uB9B4 \uC218 \uC788\uC5B4 \uC601\uC5C5 \uC2DC\uAC04\uC744 \uD53C\uD574 \uB098\uB220 \uC7A1\uC2B5\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uC124\uCE58\uB97C \uAD6C\uC5ED\uBCC4\uB85C \uB098\uB220 \uC601\uC5C5 \uC2DC\uAC04\uC744 \uD53C\uD574 \uBA70\uCE60\uC5D0 \uAC78\uCCD0 \uC7A1\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58\uAC00 \uBBF8\uB904\uC9C0\uBA74 \uC9C1\uC6D0 \uAD50\uC721 \uC77C\uC815\uB3C4 \uD568\uAED8 \uBC00\uB9AC\uBBC0\uB85C \uAC1C\uC5C5\uC77C \uAE30\uC900\uC73C\uB85C \uC5EC\uC720\uB97C \uB461\uB2C8\uB2E4.", "\uD14C\uC774\uBE14 \uBC88\uD638 \uB4F1\uB85D\uC744 \uBAA8\uB4E0 \uD14C\uC774\uBE14\uC5D0\uC11C \uD655\uC778\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uC124\uCE58 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uC88C\uC11D \uBC30\uCE58\uB3C4\uB85C \uB300\uC218\uB97C \uC815\uD558\uACE0 \uC640\uC774\uD30C\uC774\uB97C \uC810\uAC80\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uC790\uB8CC\uC640 \uD3EC\uC2A4\xB7\uD504\uB9B0\uD130 \uBAA8\uB378\uBA85\uC744 \uB118\uAE41\uB2C8\uB2E4.", "\uAE30\uC0AC\uAC00 \uD0DC\uBE14\uB9BF\uC744 \uAC70\uCE58\uD558\uACE0 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB4F1\uB85D\uD569\uB2C8\uB2E4.", "\uC8FC\uBB38\xB7\uCD9C\uB825\xB7\uACB0\uC81C\xB7\uB9E4\uCD9C \uBC18\uC601\uC744 \uD55C \uBC14\uD034 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uCCAB \uC8FC \uB3D9\uC548 \uB204\uB77D\xB7\uB04A\uAE40\uC744 \uD655\uC778\uD558\uACE0 \uC124\uC815\uC744 \uC870\uC815\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC124\uCE58 \uC804 \uC900\uBE44 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "\uC900\uBE44 \uB0B4\uC6A9", "\uC5C6\uC73C\uBA74"], "rows": [["\uC88C\uC11D \uBC30\uCE58\uB3C4", "\uD14C\uC774\uBE14 \uBC88\uD638\xB7\uC124\uCE58 \uC88C\uC11D", "\uB2F9\uC77C \uD63C\uC120"], ["\uC640\uC774\uD30C\uC774", "\uC88C\uC11D\uBCC4 \uC2E0\uD638 \uD655\uC778", "\uACF5\uC720\uAE30 \uCD94\uAC00"], ["\uBA54\uB274 \uC790\uB8CC", "\uC774\uB984\xB7\uAC00\uACA9\xB7\uC635\uC158\xB7\uC0AC\uC9C4", "\uC785\uB825 \uC9C0\uC5F0"], ["\uD3EC\uC2A4\xB7\uD504\uB9B0\uD130", "\uBAA8\uB378\uBA85", "\uC5F0\uB3D9 \uBD88\uAC00 \uAC00\uB2A5"], ["\uC804\uC6D0", "\uD14C\uC774\uBE14\uBCC4 \uCF58\uC13C\uD2B8", "\uCDA9\uC804\uC2DD \uAC70\uCE58\uB300"]] }, "faq": [["\uC124\uCE58\uC5D0 \uBA70\uCE60 \uAC78\uB9AC\uB098\uC694?", "\uC640\uC774\uD30C\uC774\uC640 \uBA54\uB274\uAC00 \uC900\uBE44\uB3FC \uC788\uC73C\uBA74 \uB300\uC218\uC5D0 \uB530\uB77C \uD558\uB8E8 \uC548\uD30E\uC785\uB2C8\uB2E4. \uC77C\uC815\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC640\uC774\uD30C\uC774\uAC00 \uC57D\uD55C \uC790\uB9AC\uB294 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uACF5\uC720\uAE30\uB97C \uCD94\uAC00\uD558\uAC70\uB098 LTE \uC720\uC2EC \uAE30\uAE30\uB85C \uBC14\uAFC9\uB2C8\uB2E4. \uC124\uCE58 \uC804\uC5D0 \uC2E0\uD638\uB97C \uC790\uB9AC\uB9C8\uB2E4 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD3EC\uC2A4\uAE30\uAC00 \uC5C6\uC5B4\uB3C4 \uC124\uCE58\uB418\uB098\uC694?", "\uB2E8\uB3C5\uC73C\uB85C\uB3C4 \uB418\uC9C0\uB9CC \uC8FC\uBC29 \uCD9C\uB825\uACFC \uB9E4\uCD9C \uD1B5\uD569\uC774 \uC548 \uB429\uB2C8\uB2E4. \uD3EC\uC2A4 \uC5F0\uB3D9\uC744 \uAD8C\uD569\uB2C8\uB2E4."], ["\uC601\uC5C5 \uC911\uC5D0 \uC124\uCE58\uD560 \uC218 \uC788\uB098\uC694?", "\uAC00\uB2A5\uD558\uC9C0\uB9CC \uC190\uB2D8 \uC790\uB9AC\uB97C \uBE44\uC6CC\uC57C \uD558\uBBC0\uB85C \uC601\uC5C5 \uC804\uC774\uB098 \uB9C8\uAC10 \uB4A4\uAC00 \uB0AB\uC2B5\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "\uD14C\uC774\uBE14\uC624\uB354\uBC30\uB2EC\uC571\uC5F0\uB3D9", "\uD3EC\uC2A4\uAE30\uC124\uCE58"], "posts": ["/post/install-day-prep/"], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uC784\uB300\uC57D\uC815", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uC784\uB300\xB7\uC57D\uC815", "title": "\uD14C\uC774\uBE14\uC624\uB354 \uC784\uB300 \uC57D\uC815\uC740 \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694? \u2014 \uB300\uC218 \uBCC0\uACBD\uACFC \uD30C\uC190 \uC870\uAC74\uC774 \uD575\uC2EC", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uC784\uB300 \uC57D\uC815\uC5D0\uC11C \uC6D4 \uC774\uC6A9\uB8CC \uD3EC\uD568 \uD56D\uBAA9, \uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0, \uB300\uC218\uB97C \uB298\uB9AC\uAC70\uB098 \uC904\uC77C \uB54C\uC758 \uC870\uAC74, \uD0DC\uBE14\uB9BF \uD30C\uC190\xB7\uBD84\uC2E4 \uCC98\uB9AC, \uC57D\uC815 \uC885\uB8CC \uB4A4 \uBC18\uB0A9\uACFC \uC18C\uC720\uAD8C, \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uACFC\uC758 \uAD00\uACC4\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD14C\uC774\uBE14\uC624\uB354 \uC784\uB300 \uC57D\uC815\uC740 \uD0DC\uBE14\uB9BF \uB300\uC218\uC5D0 \uBE44\uB840\uD558\uB294 \uC6D4 \uC774\uC6A9\uB8CC\uC640 \uC57D\uC815 \uAE30\uAC04\uC774 \uAE30\uBCF8\uC774\uACE0, \uB300\uC218 \uBCC0\uACBD \uC870\uAC74\uACFC \uD30C\uC190\xB7\uBD84\uC2E4 \uCC98\uB9AC \uC870\uAC74\uC774 \uB2E4\uB978 \uAE30\uAE30 \uC57D\uC815\uBCF4\uB2E4 \uC911\uC694\uD569\uB2C8\uB2E4. \uC88C\uC11D\uC774 \uBC14\uB00C\uAC70\uB098 \uAE30\uAE30\uAC00 \uAE68\uC9C0\uB294 \uC77C\uC774 \uC7A6\uAE30 \uB54C\uBB38\uC5D0 \uADF8 \uB450 \uC870\uD56D\uC774 \uC57D\uC815\uC11C\uC5D0 \uAE00\uB85C \uC788\uB294\uC9C0 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uB300\uB2F9 \uC774\uC6A9\uB8CC\uC5D0\uB294 \uBB34\uC5C7\uC774 \uB4E4\uC5B4\uAC00\uB098\uC694?", "p": ["\uD0DC\uBE14\uB9BF \uBCF8\uCCB4 \uC774\uC6A9\uB8CC\uAC00 \uB300\uB2F9\uC73C\uB85C \uBD99\uACE0, \uAC70\uCE58\uB300\uC640 \uCDA9\uC804 \uC7A5\uBE44\uAC00 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uD569\uCCD0\uC838 \uC788\uB294\uC9C0 \uB530\uB85C \uCCAD\uAD6C\uB418\uB294\uC9C0 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2E4\uB974\uBBC0\uB85C \uD56D\uBAA9\uD45C\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD30C\uC190\xB7\uBD84\uC2E4 \uBCF4\uD5D8\uC774 \uD3EC\uD568\uC774\uBA74 \uADF8 \uC870\uAC74(\uC790\uAE30\uBD80\uB2F4\xB7\uD69F\uC218)\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uACE0\uC7A5 \uB54C \uAD50\uCCB4 \uAE30\uAE30 \uC81C\uACF5\uACFC \uBC29\uBB38 \uC218\uB9AC\uAC00 \uD3EC\uD568\uC778\uC9C0, \uD69F\uC218 \uC81C\uD55C\uC774 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9\uACFC \uC8FC\uBC29 \uD504\uB9B0\uD130 \uC5F0\uACB0\uC774 \uC0AC\uC6A9\uB8CC \uC548\uC5D0 \uC788\uB294\uC9C0 \uCD94\uAC00 \uD56D\uBAA9\uC778\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774 \uB300\uC2E0 LTE \uC720\uC2EC\uC744 \uC4F0\uBA74 \uD1B5\uC2E0\uBE44\uAC00 \uB300\uB2F9 \uB354\uD574\uC9C0\uBBC0\uB85C \uD3EC\uD568 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD3EC\uD568 \uD56D\uBAA9 \uBAA9\uB85D\uC744 \uC57D\uC815\uC11C \uBCC4\uC9C0\uB85C \uBC1B\uC544 \uB450\uBA74 \uB098\uC911\uC5D0 \uBE60\uC9C4 \uD488\uBAA9\uC744 \uB530\uC9C8 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uD3EC\uD568 \uD56D\uBAA9 \uBCC4\uC9C0\uC5D0 \uAC70\uCE58\uB300\uC640 \uCDA9\uC804\uAE30 \uC218\uB7C9\uAE4C\uC9C0 \uC801\uD600 \uC788\uC5B4\uC57C \uBC18\uB0A9 \uB54C \uD488\uBAA9 \uB2E4\uD23C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uAC70\uCE58\uB300\uC640 \uCDA9\uC804\uAE30\uAC00 \uC18C\uBAA8\uD488\uC73C\uB85C \uBD84\uB958\uB3FC \uAD50\uCCB4\uAC00 \uC720\uC0C1\uC778 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uC18C\uBAA8\uD488 \uBAA9\uB85D\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4."] }, { "h": "\uB300\uC218 \uBCC0\uACBD \uC870\uAC74\uC740 \uC5B4\uB5BB\uAC8C \uBCF4\uB098\uC694?", "p": ["\uC88C\uC11D\uC774 \uB298\uC5B4 \uB300\uC218\uB97C \uCD94\uAC00\uD560 \uB54C \uAC19\uC740 \uC57D\uC815 \uC870\uAC74\uC73C\uB85C \uBD99\uB294\uC9C0, \uC0C8 \uC57D\uC815\uC774 \uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC88C\uC11D\uC744 \uC904\uC5EC \uB300\uC218\uB97C \uBE7C\uBA74 \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uB294 \uC5C5\uCCB4\uAC00 \uC788\uC5B4 \uAC10\uCD95 \uC870\uD56D\uC744 \uBD05\uB2C8\uB2E4.", "\uB9AC\uBAA8\uB378\uB9C1\uC73C\uB85C \uC7A0\uC2DC \uAE30\uAE30\uB97C \uCE58\uC6B8 \uB54C \uC77C\uC2DC \uC815\uC9C0\uAC00 \uB418\uB294\uC9C0\uB3C4 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB9CE\uC544\uC9C0\uBA74 \uB300\uB2F9 \uC694\uAE08\uC774 \uB0B4\uB824\uAC00\uB294 \uAD6C\uAC04\uC774 \uC788\uB294\uC9C0 \uD655\uC778\uD574 \uCC98\uC74C\uBD80\uD130 \uC801\uC6A9\uBC1B\uC2B5\uB2C8\uB2E4.", "\uBCC0\uACBD\uC740 \uAE00\uB85C \uC694\uCCAD\uD558\uACE0 \uBC14\uB010 \uB300\uC218\uC640 \uC6D4 \uC774\uC6A9\uB8CC\uB97C \uC11C\uBA74\uC73C\uB85C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uBCC0\uACBD \uC870\uAC74\uC740 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAC10\uCD95 \uC694\uCCAD \uB4A4 \uB0A8\uC740 \uB300\uC218\uC758 \uB300\uB2F9 \uC694\uAE08\uC774 \uC62C\uB77C\uAC00\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uBC14\uB010 \uCCAD\uAD6C \uC608\uC815\uC561\uC744 \uC11C\uBA74\uC73C\uB85C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB9AC\uBAA8\uB378\uB9C1 \uC77C\uC2DC \uC815\uC9C0 \uC911 \uAE30\uAE30 \uBCF4\uAD00\uC744 \uC5C5\uCCB4\uAC00 \uD558\uB294\uC9C0 \uB9E4\uC7A5\uC774 \uD558\uB294\uC9C0\uB3C4 \uC870\uAC74\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4.", "\uB300\uC218 \uBCC0\uACBD \uB4A4 \uBC14\uB010 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0 \uB9DE\uAC8C \uBC18\uC601\uB410\uB294\uC9C0 \uB300\uC870\uD569\uB2C8\uB2E4."] }, { "h": "\uD30C\uC190\uACFC \uBD84\uC2E4\uC740 \uC5B4\uB5BB\uAC8C \uCC98\uB9AC\uB418\uB098\uC694?", "p": ["\uC190\uB2D8\uC774 \uB9CC\uC9C0\uB294 \uAE30\uAE30\uB77C \uD30C\uC190\uC774 \uC7A6\uC73C\uBBC0\uB85C \uAD50\uCCB4 \uAE30\uC900\uACFC \uC790\uAE30\uBD80\uB2F4\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uBD84\uC2E4\uC740 \uC2E0\uACE0 \uC989\uC2DC \uAE30\uAE30\uB97C \uC7A0\uADF8\uACE0 \uAD50\uCCB4 \uC808\uCC28\uB97C \uBC1F\uC73C\uBA70, \uBE44\uC6A9 \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uB530\uB985\uB2C8\uB2E4.", "\uBCF4\uD638 \uCF00\uC774\uC2A4\uC640 \uACE0\uC815 \uAC70\uCE58\uB300\uB97C \uC4F0\uBA74 \uD30C\uC190\uC774 \uC904\uACE0, \uC77C\uBD80 \uC5C5\uCCB4\uB294 \uCF00\uC774\uC2A4 \uC0AC\uC6A9\uC744 \uBCF4\uD5D8 \uC870\uAC74\uC73C\uB85C \uB461\uB2C8\uB2E4.", "\uD30C\uC190 \uAD50\uCCB4 \uAE30\uAC04 \uB3D9\uC548 \uADF8 \uD14C\uC774\uBE14\uC740 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uC774\uC5B4\uAC00\uBBC0\uB85C \uC608\uBE44 \uAE30\uAE30 \uD55C \uB300\uB97C \uB450\uB294 \uB9E4\uC7A5\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uD30C\uC190 \uC0C1\uD0DC\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uACA8 \uB450\uBA74 \uAD50\uCCB4 \uBE44\uC6A9 \uB2E4\uD23C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uD30C\uC190 \uAD50\uCCB4 \uAE30\uAC04\uC774 \uC57D\uC815\uC11C\uC5D0 \uC5C6\uC73C\uBA74 \uAD50\uCCB4\uAE4C\uC9C0 \uBA70\uCE60\uC774 \uAC78\uB9B4\uC9C0 \uC54C \uC218 \uC5C6\uC73C\uBBC0\uB85C \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uB97C \uC57D\uC815 \uB300\uC218\uC5D0 \uB123\uC73C\uBA74 \uAD50\uCCB4 \uAE30\uAC04 \uACF5\uBC31\uC774 \uC0AC\uB77C\uC9C0\uC9C0\uB9CC \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uD55C \uB300\uBD84 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uBCF4\uD5D8 \uC870\uAC74\uC5D0 \uCF00\uC774\uC2A4 \uC0AC\uC6A9\uC774 \uB4E4\uC5B4 \uC788\uC73C\uBA74 \uCF00\uC774\uC2A4\uB97C \uBE7C\uACE0 \uC4F0\uB2E4 \uD30C\uC190\uB410\uC744 \uB54C \uBCF4\uC0C1\uC774 \uC548 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBD84\uC2E4 \uB4A4 \uAD50\uCCB4 \uAE30\uAE30\uC5D0\uB294 \uC0C8 \uAE30\uAE30 \uBC88\uD638\uAC00 \uBD99\uC73C\uBBC0\uB85C \uC7A5\uBD80\uC640 \uD14C\uC774\uBE14 \uBC88\uD638 \uB4F1\uB85D\uC744 \uAC31\uC2E0\uD569\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815 \uC885\uB8CC\uC640 \uD574\uC9C0\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uC57D\uC815 \uAE30\uAC04\uC774 \uB05D\uB098\uBA74 \uBC18\uB0A9\uC778\uC9C0, \uC5F0\uC7A5\uC778\uC9C0, \uC18C\uC720\uAD8C\uC774 \uB118\uC5B4\uC624\uB294\uC9C0 \uC801\uD600 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5 \uC870\uD56D\uC774 \uC788\uC73C\uBA74 \uC885\uB8CC \uC804\uC5D0 \uD574\uC9C0 \uC758\uC0AC\uB97C \uAE00\uB85C \uB0A8\uAE41\uB2C8\uB2E4.", "\uC911\uB3C4 \uD574\uC9C0 \uB54C \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uB300\uC218 \uC804\uCCB4\uC5D0 \uC801\uC6A9\uB418\uBBC0\uB85C \uB300\uC218\uAC00 \uB9CE\uC744\uC218\uB85D \uC870\uAC74\uC774 \uCEE4\uC9D1\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uC774 \uAE30\uAE30 \uC57D\uC815\uACFC \uBCC4\uB3C4\uBA74 \uB450 \uC885\uB8CC\uC77C\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4 \uD568\uAED8 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uD3D0\uC5C5\xB7\uC774\uC804 \uB54C \uC2B9\uACC4\uB098 \uC870\uAE30 \uC885\uB8CC \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uC5C6\uC73C\uBA74 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC885\uB8CC \uC804 \uD574\uC9C0 \uC758\uC0AC\uB97C \uB0A8\uAE38 \uAE30\uD55C\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uC73C\uB2C8 \uADF8 \uAE30\uD55C\uC744 \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC2B9\uACC4 \uC870\uAC74\uC774 \uC5C6\uC73C\uBA74 \uC591\uB3C4 \uB54C \uC0C8 \uC6B4\uC601\uC790\uAC00 \uC0C8 \uC57D\uC815\uC744 \uB9FA\uC5B4\uC57C \uD558\uBBC0\uB85C \uC591\uB3C4 \uACC4\uD68D\uC774 \uC788\uC73C\uBA74 \uBBF8\uB9AC \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815 \uC885\uB8CC \uB4A4 \uC18C\uC720\uAD8C\uC774 \uB118\uC5B4\uC624\uB294 \uC870\uAC74\uC774\uBA74 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uACC4\uC18D \uB098\uAC00\uBBC0\uB85C \uADF8 \uAE08\uC561\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC758\uC0AC \uD1B5\uC9C0 \uAE30\uD55C\uC744 \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }], "steps": { "h": "\uC784\uB300 \uACC4\uC57D\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uC124\uCE58\uD560 \uC88C\uC11D \uC218\uC640 \uB300\uC218\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uB300\uB2F9 \uC6D4 \uC774\uC6A9\uB8CC\uC640 \uD3EC\uD568 \uD56D\uBAA9\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB300\uC218 \uBCC0\uACBD\xB7\uD30C\uC190\xB7\uBD84\uC2E4 \uC870\uD56D\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uACFC \uC885\uB8CC \uB4A4 \uCC98\uB9AC \uBC29\uC2DD\uC744 \uD655\uC778\uD558\uACE0 \uC11C\uBA85\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC640 \uD3EC\uD568 \uD56D\uBAA9 \uBCC4\uC9C0\uB97C \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC784\uB300 \uC57D\uC815 \uD655\uC778\uD45C", "head": ["\uD56D\uBAA9", "\uD655\uC778\uD560 \uAC83", "\uC5C6\uC73C\uBA74"], "rows": [["\uC6D4 \uC774\uC6A9\uB8CC", "\uB300\uB2F9\xB7\uD3EC\uD568 \uD56D\uBAA9", "\uD56D\uBAA9\uD45C \uC694\uCCAD"], ["\uB300\uC218 \uBCC0\uACBD", "\uCD94\uAC00\xB7\uAC10\uCD95\xB7\uC77C\uC2DC \uC815\uC9C0", "\uC11C\uBA74 \uC694\uCCAD"], ["\uD30C\uC190\xB7\uBD84\uC2E4", "\uAD50\uCCB4 \uAE30\uC900\xB7\uC790\uAE30\uBD80\uB2F4", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"], ["\uACE0\uC7A5", "\uAD50\uCCB4 \uAE30\uAE30\xB7\uAE30\uAC04", "\uC57D\uC815\uC11C \uCD94\uAC00"], ["\uC885\uB8CC", "\uBC18\uB0A9\xB7\uC5F0\uC7A5\xB7\uC18C\uC720\uAD8C", "\uC11C\uBA74 \uC694\uCCAD"]] }, "faq": [["\uC88C\uC11D\uC744 \uC904\uC774\uBA74 \uB300\uC218\uB3C4 \uC904\uC77C \uC218 \uC788\uB098\uC694?", "\uAC10\uCD95 \uC870\uD56D\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uACC4\uC57D \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD0DC\uBE14\uB9BF\uC774 \uAE68\uC9C0\uBA74 \uBC14\uB85C \uAD50\uCCB4\uB418\uB098\uC694?", "\uAD50\uCCB4 \uAE30\uC900\uACFC \uAE30\uAC04\uC774 \uC57D\uC815\uC11C\uC5D0 \uC788\uC2B5\uB2C8\uB2E4. \uADF8\uB3D9\uC548\uC740 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4."], ["\uBCF4\uD5D8\uC740 \uAF2D \uB4E4\uC5B4\uC57C \uD558\uB098\uC694?", "\uC758\uBB34\uB294 \uC544\uB2C8\uC9C0\uB9CC \uD30C\uC190\uC774 \uC7A6\uC740 \uB9E4\uC7A5\uC740 \uBCF4\uD5D8 \uD3EC\uD568 \uC57D\uC815\uC774 \uBE44\uC6A9\uC744 \uC608\uCE21\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4."], ["\uD504\uB85C\uADF8\uB7A8\uB9CC \uB2E4\uB978 \uC5C5\uCCB4\uB85C \uBC14\uAFC0 \uC218 \uC788\uB098\uC694?", "\uD0DC\uBE14\uB9BF\uACFC \uD504\uB85C\uADF8\uB7A8\uC774 \uD55C \uC57D\uC815\uC73C\uB85C \uBB36\uC5EC \uC788\uC73C\uBA74 \uD504\uB85C\uADF8\uB7A8\uB9CC \uBC14\uAFB8\uAE30 \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uBB36\uC5EC \uC788\uB294\uC9C0 \uACC4\uC57D \uC804\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "\uD14C\uC774\uBE14\uC624\uB354\uD574\uC9C0\uC704\uC57D\uAE08", "\uD14C\uC774\uBE14\uC624\uB354\uD0DC\uBE14\uB9BF\uBD84\uC2E4\uD30C\uC190"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uBC30\uB2EC\uC571\uC5F0\uB3D9", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uBC30\uB2EC\uC571 \uC5F0\uB3D9", "title": "\uD14C\uC774\uBE14\uC624\uB354\uC640 \uBC30\uB2EC\uC571\uC744 \uD568\uAED8 \uC4F0\uBA74 \uC8FC\uBB38\uC774 \uC5B4\uB5BB\uAC8C \uBAA8\uC774\uB098\uC694? \u2014 \uD55C \uD654\uBA74\uC5D0\uC11C \uBC1B\uB294 \uC870\uAC74", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uC8FC\uBB38\uACFC \uBC30\uB2EC\uC571 \uC8FC\uBB38\uC744 \uD3EC\uC2A4 \uD55C \uD654\uBA74\uC5D0\uC11C \uBC1B\uB294 \uC5F0\uB3D9 \uAD6C\uC870, \uC5F0\uB3D9\uC5D0 \uD544\uC694\uD55C \uD504\uB85C\uADF8\uB7A8 \uC870\uAC74, \uC8FC\uBC29 \uCD9C\uB825 \uC21C\uC11C \uC124\uC815, \uBA54\uB274\uC640 \uAC00\uACA9\uC744 \uB450 \uCC44\uB110\uC5D0\uC11C \uB9DE\uCD94\uB294 \uBC29\uBC95, \uC5F0\uB3D9 \uBE44\uC6A9\uACFC \uC815\uC0B0 \uACBD\uB85C\uC758 \uCC28\uC774\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD14C\uC774\uBE14\uC624\uB354 \uC8FC\uBB38\uACFC \uBC30\uB2EC\uC571 \uC8FC\uBB38\uC740 \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC774 \uB458 \uB2E4 \uC5F0\uB3D9\uC744 \uC9C0\uC6D0\uD560 \uB54C \uD55C \uD654\uBA74\uACFC \uD55C \uC8FC\uBC29 \uD504\uB9B0\uD130\uB85C \uBAA8\uC774\uBA70, \uC5F0\uB3D9\uC774 \uC5C6\uC73C\uBA74 \uBC30\uB2EC\uC571 \uC804\uC6A9 \uAE30\uAE30\uC5D0\uC11C \uC8FC\uBB38\uC744 \uB530\uB85C \uBC1B\uC544 \uC8FC\uBC29\uC5D0 \uC804\uB2EC\uD574\uC57C \uD569\uB2C8\uB2E4. \uC5F0\uB3D9\uC740 \uD3EC\uC2A4\uB97C \uC911\uC2EC\uC73C\uB85C \uC774\uB904\uC9C0\uBBC0\uB85C \uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC758 \uC9C0\uC6D0 \uBAA9\uB85D\uC744 \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uC8FC\uBB38\uC774 \uD55C \uD654\uBA74\uC5D0 \uBAA8\uC774\uBA74 \uBB34\uC5C7\uC774 \uD3B8\uD574\uC9C0\uB098\uC694?", "p": ["\uB9E4\uC7A5 \uC88C\uC11D \uC8FC\uBB38\uACFC \uBC30\uB2EC \uC8FC\uBB38\uC774 \uD3EC\uC2A4 \uD55C \uD654\uBA74\uC5D0 \uB4E4\uC5B4\uC640 \uC9C1\uC6D0\uC774 \uAE30\uAE30\uB97C \uC5EC\uB7EC \uAC1C \uBCFC \uD544\uC694\uAC00 \uC5C6\uC5B4\uC9D1\uB2C8\uB2E4.", "\uC8FC\uBC29 \uD504\uB9B0\uD130\uC5D0 \uB450 \uCC44\uB110 \uC8FC\uBB38\uC774 \uC2DC\uAC04 \uC21C\uC11C\uB85C \uCD9C\uB825\uB3FC \uC870\uB9AC \uC21C\uC11C\uAC00 \uC11E\uC774\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uB9E4\uCD9C \uC790\uB8CC\uAC00 \uD3EC\uC2A4\uC5D0 \uBAA8\uC5EC \uB9C8\uAC10 \uB54C \uCC44\uB110\uBCC4 \uB9E4\uCD9C\uC744 \uD55C \uBCF4\uACE0\uC11C\uB85C \uBD05\uB2C8\uB2E4.", "\uD488\uC808 \uCC98\uB9AC\uB97C \uD3EC\uC2A4\uC5D0\uC11C \uD558\uBA74 \uD14C\uC774\uBE14\uC624\uB354\uC640 \uBC30\uB2EC\uC571\uC5D0 \uAC19\uC774 \uBC18\uC601\uB418\uB294 \uAD6C\uC870\uAC00 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uC8FC\uBB38 \uC811\uC218\uC640 \uC870\uB9AC \uC644\uB8CC \uCC98\uB9AC\uB3C4 \uD3EC\uC2A4\uC5D0\uC11C \uD558\uBA74 \uBC30\uB2EC\uC571 \uAE30\uAE30\uB97C \uB530\uB85C \uC870\uC791\uD558\uC9C0 \uC54A\uC544\uB3C4 \uB429\uB2C8\uB2E4.", "\uC5F0\uB3D9\uC774 \uC5C6\uC744 \uB54C\uB294 \uBC30\uB2EC\uC571 \uAE30\uAE30\uC5D0\uC11C \uC8FC\uBB38\uC744 \uBCF4\uACE0 \uC190\uC73C\uB85C \uC8FC\uBC29\uC5D0 \uC804\uB2EC\uD558\uAC70\uB098 \uBCC4\uB3C4 \uD504\uB9B0\uD130\uB97C \uB461\uB2C8\uB2E4.", "\uC815\uC0B0\uC740 \uC5F0\uB3D9\uACFC \uBB34\uAD00\uD558\uAC8C \uBC30\uB2EC\uC571 \uC815\uC0B0\uC11C\uB85C \uB530\uB85C \uB4E4\uC5B4\uC624\uBBC0\uB85C \uB9E4\uCD9C \uD1B5\uD569\uACFC \uC815\uC0B0 \uD1B5\uD569\uC740 \uB2E4\uB978 \uBB38\uC81C\uC785\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uB4A4 \uCCAB \uC8FC\uB294 \uBC30\uB2EC \uC8FC\uBB38\uC774 \uC8FC\uBC29\uC5D0 \uB450 \uBC88 \uCD9C\uB825\uB418\uAC70\uB098 \uBE60\uC9C0\uB294\uC9C0 \uD655\uC778\uD574 \uCD9C\uB825 \uC124\uC815\uC744 \uC870\uC815\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4\uC5D0\uC11C \uD488\uC808 \uCC98\uB9AC\uB97C \uD558\uBA74 \uD14C\uC774\uBE14\uC624\uB354\uC640 \uBC30\uB2EC\uC571\uC5D0 \uBC18\uC601\uB418\uAE30\uAE4C\uC9C0 \uC2DC\uCC28\uAC00 \uC788\uB294\uC9C0 \uD655\uC778\uD574 \uB461\uB2C8\uB2E4.", "\uB9E4\uCD9C \uBCF4\uACE0\uC11C\uC5D0 \uCC44\uB110 \uAD6C\uBD84\uC774 \uC788\uC73C\uBA74 \uB9E4\uC7A5 \uC8FC\uBB38\uACFC \uBC30\uB2EC \uC8FC\uBB38\uC758 \uBE44\uC911 \uBCC0\uD654\uB97C \uB9E4\uB2EC \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uB4A4 \uBC30\uB2EC \uC8FC\uBB38 \uC811\uC218 \uC2DC\uAC04\uC774 \uD3EC\uC2A4\uC5D0 \uB0A8\uC73C\uBBC0\uB85C \uBC30\uB2EC \uC9C0\uC5F0 \uBD84\uC7C1 \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uC5F0\uB3D9\uC5D0 \uD544\uC694\uD55C \uC870\uAC74\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC774 \uD14C\uC774\uBE14\uC624\uB354\uC640 \uBC30\uB2EC\uC571 \uC591\uCABD\uC744 \uC9C0\uC6D0\uD574\uC57C \uD558\uBA70, \uC9C0\uC6D0 \uBAA9\uB85D\uC740 \uD504\uB85C\uADF8\uB7A8\uB9C8\uB2E4 \uB2E4\uB985\uB2C8\uB2E4.", "\uBC30\uB2EC\uC571 \uCABD \uC5F0\uB3D9\uC740 \uC571\uB9C8\uB2E4 \uB530\uB85C \uC2E0\uCCAD\uD558\uACE0 \uC2B9\uC778\uBC1B\uB294 \uC808\uCC28\uAC00 \uC788\uC5B4 \uC571 \uACC4\uC815 \uC815\uBCF4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uCF54\uB4DC\uAC00 \uD3EC\uC2A4\xB7\uD14C\uC774\uBE14\uC624\uB354\xB7\uBC30\uB2EC\uC571\uC5D0\uC11C \uAC19\uC544\uC57C \uC8FC\uBB38\uC774 \uB9DE\uAC8C \uB4E4\uC5B4\uC624\uBBC0\uB85C \uBA54\uB274 \uD1B5\uC77C \uC791\uC5C5\uC774 \uC120\uD589\uB429\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uAE30\uB2A5\uC740 \uC6D4 \uC0AC\uC6A9\uB8CC\uC5D0 \uCD94\uAC00 \uD56D\uBAA9\uC73C\uB85C \uBD99\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uC571\uBCC4 \uBE44\uC6A9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774\uB098 \uC778\uD130\uB137\uC774 \uB04A\uAE30\uBA74 \uB450 \uCC44\uB110 \uBAA8\uB450 \uC601\uD5A5\uC744 \uBC1B\uC73C\uBBC0\uB85C \uD68C\uC120 \uC548\uC815\uC131\uC774 \uC804\uC81C\uC785\uB2C8\uB2E4.", "\uC9C0\uC6D0 \uC5EC\uBD80\uC640 \uBE44\uC6A9\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC\uC571 \uC5F0\uB3D9 \uC2B9\uC778\uC740 \uC571\uB9C8\uB2E4 \uAE30\uAC04\uC774 \uB2EC\uB77C \uAC1C\uC5C5\uC77C\uBCF4\uB2E4 \uC55E\uC11C \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uC2E0\uCCAD \uB54C \uC571 \uACC4\uC815 \uBE44\uBC00\uBC88\uD638\uB97C \uC5C5\uCCB4\uC5D0 \uB118\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uC2E0\uCCAD \uB4A4 \uBE44\uBC00\uBC88\uD638\uB97C \uBC14\uAFC9\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uC2B9\uC778 \uB4A4 \uC571 \uCABD \uBA54\uB274\uB97C \uBC14\uAFB8\uBA74 \uD3EC\uC2A4\uC5D0 \uBC18\uC601\uB418\uB294\uC9C0, \uD3EC\uC2A4\uC5D0\uC11C \uBC14\uAFB8\uBA74 \uC571\uC5D0 \uBC18\uC601\uB418\uB294\uC9C0 \uBC29\uD5A5\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uBA54\uB274\uC640 \uAC00\uACA9\uC740 \uC5B4\uB5BB\uAC8C \uB9DE\uCD94\uB098\uC694?", "p": ["\uBC30\uB2EC \uBA54\uB274\uC640 \uB9E4\uC7A5 \uBA54\uB274\uAC00 \uB2E4\uB974\uBA74 \uCC44\uB110\uBCC4 \uBA54\uB274\uD310\uC744 \uB530\uB85C \uB450\uB418, \uACF5\uD1B5 \uBA54\uB274\uB294 \uCF54\uB4DC\uB97C \uAC19\uAC8C \uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uAC00\uACA9\uC744 \uB9E4\uC7A5 \uAC00\uACA9\uACFC \uB2E4\uB974\uAC8C \uB458 \uB54C \uD3EC\uC2A4\uC5D0\uC11C \uCC44\uB110\uBCC4 \uAC00\uACA9 \uC124\uC815\uC774 \uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD488\uC808\uACFC \uAC00\uACA9 \uBCC0\uACBD\uC744 \uD55C \uACF3\uC5D0\uC11C \uD558\uBA74 \uCC44\uB110\uBCC4\uB85C \uB530\uB85C \uBC14\uAFB8\uB294 \uC2E4\uC218\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC635\uC158 \uAD6C\uC131\uC774 \uC571\uB9C8\uB2E4 \uB2E4\uB974\uBA74 \uC8FC\uBB38\uC774 \uC5B4\uAE0B\uB098\uBBC0\uB85C \uC635\uC158 \uC774\uB984\uB3C4 \uD1B5\uC77C\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uAC1C\uD3B8 \uB54C\uB294 \uC138 \uCC44\uB110\uC744 \uAC19\uC740 \uB0A0 \uBC14\uAFB8\uACE0 \uAC01\uAC01 \uC8FC\uBB38 \uD55C \uBC88\uC529 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uCC44\uB110\uBCC4 \uAC00\uACA9\uC774 \uB2E4\uB974\uBA74 \uC190\uB2D8 \uBB38\uC758\uAC00 \uC0DD\uAE30\uBBC0\uB85C \uAC00\uACA9 \uCC28\uC774 \uC774\uC720\uB97C \uC9C1\uC6D0\uC774 \uC124\uBA85\uD560 \uC218 \uC788\uAC8C \uD574 \uB461\uB2C8\uB2E4.", "\uBC30\uB2EC \uC804\uC6A9 \uBA54\uB274\uB294 \uB9E4\uC7A5 \uD654\uBA74\uC5D0 \uB728\uC9C0 \uC54A\uB3C4\uB85D \uCC44\uB110 \uC124\uC815\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC635\uC158 \uC774\uB984\uC774 \uC870\uAE08\uB9CC \uB2EC\uB77C\uB3C4 \uB2E4\uB978 \uBA54\uB274\uB85C \uB4E4\uC5B4\uC624\uBBC0\uB85C \uD1B5\uC77C \uC791\uC5C5\uC740 \uD45C\uB97C \uB9CC\uB4E4\uC5B4 \uD569\uB2C8\uB2E4."] }, { "h": "\uC8FC\uBC29 \uCD9C\uB825\uC740 \uC5B4\uB5BB\uAC8C \uC124\uC815\uD558\uB098\uC694?", "p": ["\uBC30\uB2EC \uC8FC\uBB38\uACFC \uB9E4\uC7A5 \uC8FC\uBB38\uC744 \uAC19\uC740 \uD504\uB9B0\uD130\uC5D0 \uC2DC\uAC04 \uC21C\uC11C\uB85C \uB0BC\uC9C0, \uD504\uB9B0\uD130\uB97C \uB098\uB20C\uC9C0 \uC815\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uC8FC\uBB38 \uCD9C\uB825\uC9C0\uC5D0 \uBC30\uB2EC \uBC88\uD638\uC640 \uC694\uCCAD \uC0AC\uD56D\uC774 \uCC0D\uD788\uB3C4\uB85D \uC591\uC2DD\uC744 \uC124\uC815\uD569\uB2C8\uB2E4.", "\uD53C\uD06C \uC2DC\uAC04\uC5D0 \uCD9C\uB825\uC774 \uBC00\uB9AC\uBA74 \uD504\uB9B0\uD130\uB97C \uCD94\uAC00\uD558\uAC70\uB098 \uC870\uB9AC \uAD6C\uC5ED\uBCC4\uB85C \uB098\uB215\uB2C8\uB2E4.", "\uCD9C\uB825 \uC591\uC2DD\uC740 \uC124\uCE58 \uB54C \uD55C \uBC88 \uC815\uD558\uACE0, \uCCAB \uC8FC \uC6B4\uC601\uC744 \uBCF8 \uB4A4 \uC870\uC815\uD569\uB2C8\uB2E4.", "\uCD9C\uB825 \uC591\uC2DD\uC5D0 \uCC44\uB110 \uD45C\uC2DC(\uB9E4\uC7A5\xB7\uBC30\uB2EC)\uB97C \uB123\uC73C\uBA74 \uC8FC\uBC29\uC5D0\uC11C \uD3EC\uC7A5 \uC5EC\uBD80\uB97C \uBC14\uB85C \uC555\uB2C8\uB2E4.", "\uD504\uB9B0\uD130\uB97C \uB098\uB20C \uB54C\uB294 \uBC30\uB2EC \uC804\uD45C\uAC00 \uD3EC\uC7A5 \uB2F4\uB2F9\uC5D0\uAC8C \uBC14\uB85C \uAC00\uB3C4\uB85D \uC704\uCE58\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uCD9C\uB825 \uC124\uC815\uC744 \uBC14\uAFBC \uB4A4\uC5D0\uB294 \uB9E4\uC7A5 \uC8FC\uBB38\uACFC \uBC30\uB2EC \uC8FC\uBB38\uC744 \uD55C \uBC88\uC529 \uB123\uC5B4 \uCD9C\uB825 \uC704\uCE58\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5F0\uB3D9 \uB4A4 \uCCAB \uC8FC \uC8FC\uBC29 \uCD9C\uB825 \uB204\uB77D\xB7\uC911\uBCF5\uC744 \uD655\uC778\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uC5F0\uB3D9 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8\uC758 \uD14C\uC774\uBE14\uC624\uB354\xB7\uBC30\uB2EC\uC571 \uC9C0\uC6D0 \uBAA9\uB85D\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBA54\uB274 \uCF54\uB4DC\uC640 \uC635\uC158\uC744 \uC138 \uCC44\uB110\uC5D0\uC11C \uD1B5\uC77C\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC\uC571\uBCC4 \uC5F0\uB3D9\uC744 \uC2E0\uCCAD\uD558\uACE0 \uC2B9\uC778\uBC1B\uC2B5\uB2C8\uB2E4.", "\uC8FC\uBC29 \uCD9C\uB825 \uC591\uC2DD\uACFC \uD504\uB9B0\uD130 \uAD6C\uC131\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uCC44\uB110\uBCC4 \uC8FC\uBB38\uC744 \uD55C \uBC88\uC529 \uD14C\uC2A4\uD2B8\uD558\uACE0 \uB9C8\uAC10 \uBCF4\uACE0\uC11C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC5F0\uB3D9 \uC5EC\uBD80\uC5D0 \uB530\uB978 \uCC28\uC774", "head": ["\uD56D\uBAA9", "\uC5F0\uB3D9 \uC2DC", "\uBBF8\uC5F0\uB3D9 \uC2DC"], "rows": [["\uC8FC\uBB38 \uD654\uBA74", "\uD3EC\uC2A4 \uD558\uB098", "\uCC44\uB110\uBCC4 \uAE30\uAE30"], ["\uC8FC\uBC29 \uCD9C\uB825", "\uD55C \uD504\uB9B0\uD130\xB7\uC2DC\uAC04\uC21C", "\uC218\uAE30 \uC804\uB2EC \uB610\uB294 \uBCC4\uB3C4 \uD504\uB9B0\uD130"], ["\uB9E4\uCD9C \uC790\uB8CC", "\uD3EC\uC2A4 \uD1B5\uD569", "\uCC44\uB110\uBCC4 \uB530\uB85C"], ["\uD488\uC808 \uCC98\uB9AC", "\uD55C \uBC88", "\uCC44\uB110\uBCC4 \uAC01\uAC01"], ["\uC815\uC0B0", "\uC571 \uC815\uC0B0\uC11C \uBCC4\uB3C4", "\uC571 \uC815\uC0B0\uC11C \uBCC4\uB3C4"]] }, "faq": [["\uBC30\uB2EC\uC571 \uC5F0\uB3D9\uC740 \uBAA8\uB4E0 \uC571\uC774 \uB418\uB098\uC694?", "\uD3EC\uC2A4 \uD504\uB85C\uADF8\uB7A8 \uC9C0\uC6D0 \uBAA9\uB85D\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4. \uC4F0\uB294 \uC571 \uC774\uB984\uC744 \uC8FC\uACE0 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC5F0\uB3D9 \uBE44\uC6A9\uC774 \uB530\uB85C \uB4DC\uB098\uC694?", "\uC571\uBCC4 \uCD94\uAC00 \uD56D\uBAA9\uC73C\uB85C \uBD99\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uD56D\uBAA9\uBCC4 \uAE08\uC561\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC815\uC0B0\uB3C4 \uD3EC\uC2A4\uB85C \uD569\uCCD0\uC9C0\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uBC30\uB2EC\uC571 \uC815\uC0B0\uC740 \uC571 \uC815\uC0B0\uC11C\uB85C \uB530\uB85C \uB4E4\uC5B4\uC624\uACE0, \uD3EC\uC2A4\uB294 \uB9E4\uCD9C \uC790\uB8CC\uB9CC \uD1B5\uD569\uD569\uB2C8\uB2E4."], ["\uC5F0\uB3D9\uC774 \uB04A\uAE30\uBA74 \uBC30\uB2EC \uC8FC\uBB38\uC744 \uB193\uCE58\uB098\uC694?", "\uBC30\uB2EC\uC571 \uAE30\uAE30\uC5D0\uC11C \uC9C1\uC811 \uBCF4\uBA74 \uB429\uB2C8\uB2E4. \uB04A\uAE40\uC5D0 \uB300\uBE44\uD574 \uC571 \uAE30\uAE30\uB97C \uCE58\uC6B0\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC124\uCE58\uC808\uCC28", "\uD3EC\uC2A4\uAE30\uD504\uB85C\uADF8\uB7A8\uC6D4\uC0AC\uC6A9\uB8CC", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uBB34\uC120"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uC2DD\uB2F9\uB3C4\uC785\uD6A8\uACFC", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uC2DD\uB2F9 \uB3C4\uC785 \uD6A8\uACFC", "title": "\uC2DD\uB2F9\uC5D0 \uD14C\uC774\uBE14\uC624\uB354\uB97C \uB450\uBA74 \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694? \u2014 \uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uC778\uB825\uC758 \uC138 \uAC00\uC9C0 \uBCC0\uD654", "desc": "\uC2DD\uB2F9\uC5D0 \uD14C\uC774\uBE14\uC624\uB354\uB97C \uB3C4\uC785\uD588\uC744 \uB54C \uC8FC\uBB38 \uBC1B\uB294 \uC2DC\uAC04, \uCD94\uAC00 \uC8FC\uBB38 \uBE48\uB3C4, \uACC4\uC0B0\uB300 \uC904, \uC9C1\uC6D0 \uB3D9\uC120, \uC8FC\uBB38 \uC624\uB958\uC5D0\uC11C \uB2EC\uB77C\uC9C0\uB294 \uC810\uACFC \uD6A8\uACFC\uAC00 \uD070 \uC2DD\uB2F9\uACFC \uC791\uC740 \uC2DD\uB2F9\uC758 \uCC28\uC774, \uB3C4\uC785 \uB4A4 \uC6B4\uC601 \uBC29\uC2DD\uC744 \uBC14\uAFD4\uC57C \uD558\uB294 \uBD80\uBD84\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC2DD\uB2F9\uC5D0 \uD14C\uC774\uBE14\uC624\uB354\uB97C \uB450\uBA74 \uC9C1\uC6D0\uC774 \uC8FC\uBB38\uC744 \uBC1B\uC73C\uB7EC \uAC00\uB294 \uD69F\uC218\uAC00 \uC904\uACE0 \uC190\uB2D8\uC774 \uCD94\uAC00 \uC8FC\uBB38\uC744 \uBC14\uB85C \uB123\uC73C\uBA70 \uACC4\uC0B0\uB300 \uC904\uC774 \uC0AC\uB77C\uC9C0\uB294 \uC138 \uAC00\uC9C0 \uBCC0\uD654\uAC00 \uC0DD\uAE41\uB2C8\uB2E4. \uD6A8\uACFC\uB294 \uC88C\uC11D\uC774 \uB9CE\uACE0 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC740 \uC2DD\uB2F9\uC5D0\uC11C \uD06C\uACE0, \uB2E8\uD488 \uC704\uC8FC\uB85C \uD55C \uBC88 \uC8FC\uBB38\uD558\uB294 \uC2DD\uB2F9\uC5D0\uC11C\uB294 \uC791\uC2B5\uB2C8\uB2E4.", "sections": [{ "h": "\uC8FC\uBB38\uC740 \uC5B4\uB5BB\uAC8C \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC190\uB2D8\uC774 \uC790\uB9AC\uC5D0\uC11C \uBA54\uB274\uB97C \uBCF4\uACE0 \uBC14\uB85C \uB123\uC73C\uBBC0\uB85C \uC9C1\uC6D0\uC774 \uC8FC\uBB38\uC744 \uBC1B\uC73C\uB7EC \uAC00\uB294 \uD69F\uC218\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uCD94\uAC00 \uC8FC\uBB38\uC774 \uC9C1\uC6D0 \uD638\uCD9C \uC5C6\uC774 \uB4E4\uC5B4\uAC00 \uACE0\uAE43\uC9D1\uC774\uB098 \uC8FC\uC810\uCC98\uB7FC \uCD94\uAC00\uAC00 \uC7A6\uC740 \uC2DD\uB2F9\uC5D0\uC11C \uD6A8\uACFC\uAC00 \uD07D\uB2C8\uB2E4.", "\uC8FC\uBB38 \uB0B4\uC6A9\uC774 \uADF8\uB300\uB85C \uC8FC\uBC29\uC5D0 \uCD9C\uB825\uB418\uBBC0\uB85C \uB4E3\uACE0 \uC801\uB294 \uACFC\uC815\uC758 \uC624\uB958\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC0AC\uC9C4\uACFC \uC124\uBA85\uC744 \uBCF4\uBA70 \uACE0\uB974\uAE30 \uB54C\uBB38\uC5D0 \uBA54\uB274 \uC124\uBA85 \uC2DC\uAC04\uC774 \uC904\uACE0, \uCD94\uCC9C \uBA54\uB274 \uB178\uCD9C\uB85C \uC120\uD0DD\uC774 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uC678\uAD6D\uC778 \uC190\uB2D8\uC740 \uB2E4\uAD6D\uC5B4 \uD654\uBA74\uC73C\uB85C \uC8FC\uBB38\uD574 \uC758\uC0AC\uC18C\uD1B5 \uBD80\uB2F4\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE30\uAE30 \uC0AC\uC6A9\uC744 \uC5B4\uB824\uC6CC\uD558\uB294 \uACBD\uC6B0\uB97C \uC704\uD574 \uC9C1\uC6D0 \uC8FC\uBB38\uB3C4 \uB0A8\uACA8 \uB450\uC5B4\uC57C \uD569\uB2C8\uB2E4.", "\uD53C\uD06C \uC2DC\uAC04\uC5D0 \uC8FC\uBB38\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uB4E4\uC5B4\uC624\uBA74 \uC8FC\uBC29 \uCD9C\uB825\uC774 \uBC00\uB9B4 \uC218 \uC788\uC5B4 \uCD9C\uB825 \uAD6C\uC131\uC744 \uC870\uC815\uD569\uB2C8\uB2E4.", "\uB3C4\uC785 \uCCAB \uB2EC\uC5D0\uB294 \uC190\uB2D8\uC774 \uAE30\uAE30\uC5D0\uC11C \uC8FC\uBB38\uD558\uB294 \uBE44\uC728\uC744 \uC801\uC5B4 \uB450\uBA74 \uD6A8\uACFC\uB97C \uC218\uCE58\uB85C \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC8FC\uBB38\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uBAB0\uB9AC\uB294 \uC2DC\uAC04\uB300\uC5D0\uB294 \uC8FC\uBC29\uC5D0\uC11C \uC804\uD45C \uC21C\uC11C\uB97C \uC9C0\uD0A4\uB3C4\uB85D \uCD9C\uB825 \uC591\uC2DD\uC5D0 \uC2DC\uAC04\uC744 \uD06C\uAC8C \uB123\uC2B5\uB2C8\uB2E4.", "\uC8FC\uBB38 \uC624\uB958\uAC00 \uC904\uBA74 \uC7AC\uC870\uB9AC\uC640 \uD658\uBD88\uC774 \uC904\uC5B4 \uADF8 \uBE44\uC6A9\uB3C4 \uD568\uAED8 \uC904\uC5B4\uB4DC\uB294 \uD6A8\uACFC\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uC8FC\uBB38\uC774 \uBC14\uB85C \uC8FC\uBC29\uC73C\uB85C \uAC00\uBBC0\uB85C \uC8FC\uBB38 \uB4A4 \uC74C\uC2DD\uC774 \uB098\uC624\uAE30\uAE4C\uC9C0 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4DC\uB294 \uB9E4\uC7A5\uC774 \uB9CE\uC2B5\uB2C8\uB2E4."] }, { "h": "\uACB0\uC81C\uB294 \uC5B4\uB5BB\uAC8C \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC790\uB9AC\uC5D0\uC11C \uACB0\uC81C\uD558\uBA74 \uACC4\uC0B0\uB300 \uC904\uC774 \uC0AC\uB77C\uC9C0\uACE0 \uB9C8\uAC10 \uB54C \uBBF8\uACB0\uC81C \uD14C\uC774\uBE14\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC120\uACB0\uC81C \uC124\uC815\uC744 \uD558\uBA74 \uC8FC\uBB38\uACFC \uB3D9\uC2DC\uC5D0 \uACB0\uC81C\uAC00 \uB05D\uB098 \uBA39\uACE0 \uB098\uAC00\uB294 \uC190\uB2D8 \uBB38\uC81C\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uBD84\uD560 \uACB0\uC81C\uB97C \uAE30\uAE30\uC5D0\uC11C \uCC98\uB9AC\uD560 \uC218 \uC788\uC5B4 \uB2E8\uCCB4 \uC190\uB2D8 \uACC4\uC0B0\uC774 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uACB0\uC81C \uC790\uB8CC\uAC00 \uD14C\uC774\uBE14\uBCC4\uB85C \uB0A8\uC544 \uD658\uBD88\uC774\uB098 \uBD84\uC7C1 \uB54C \uCC3E\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uD604\uAE08 \uC190\uB2D8\uC740 \uCE74\uC6B4\uD130\uC5D0\uC11C \uBC1B\uC544\uC57C \uD558\uBBC0\uB85C \uCE74\uC6B4\uD130 \uACB0\uC81C\uB97C \uC644\uC804\uD788 \uC5C6\uC560\uC9C0\uB294 \uC54A\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uBC29\uC2DD \uC124\uC815(\uC120\uACB0\uC81C\xB7\uD6C4\uACB0\uC81C)\uC740 \uB9E4\uC7A5 \uC6B4\uC601 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uC124\uCE58 \uB54C \uC815\uD569\uB2C8\uB2E4.", "\uC120\uACB0\uC81C\uB85C \uBC14\uAFB8\uBA74 \uC190\uB2D8\uC774 \uACB0\uC81C\uB97C \uBA3C\uC800 \uD558\uB294 \uB370 \uC775\uC219\uD574\uC9C8 \uC2DC\uAC04\uC774 \uD544\uC694\uD558\uBBC0\uB85C \uC548\uB0B4 \uBB38\uAD6C\uB97C \uB461\uB2C8\uB2E4.", "\uBD84\uD560 \uACB0\uC81C \uC124\uC815\uC740 \uC778\uC6D0 \uC218\uB300\uB85C \uB098\uB204\uAE30\uC640 \uAE08\uC561 \uC9C0\uC815 \uB098\uB204\uAE30 \uC911 \uB9E4\uC7A5\uC5D0 \uB9DE\uB294 \uBC29\uC2DD\uC73C\uB85C \uB461\uB2C8\uB2E4.", "\uC120\uACB0\uC81C \uB9E4\uC7A5\uC740 \uC190\uB2D8\uC774 \uCD94\uAC00 \uC8FC\uBB38 \uB54C\uB9C8\uB2E4 \uACB0\uC81C\uD558\uAC8C \uB418\uBBC0\uB85C \uCD94\uAC00 \uC8FC\uBB38\uC744 \uBAA8\uC544 \uD6C4\uACB0\uC81C\uB85C \uB450\uB294 \uBC29\uC2DD\uB3C4 \uBE44\uAD50\uD569\uB2C8\uB2E4."] }, { "h": "\uC778\uB825\uACFC \uB3D9\uC120\uC740 \uC5B4\uB5BB\uAC8C \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC8FC\uBB38 \uBC1B\uAE30\uC640 \uACC4\uC0B0\uC5D0 \uC4F0\uB358 \uC2DC\uAC04\uC774 \uC904\uC5B4 \uAC19\uC740 \uC778\uC6D0\uC73C\uB85C \uC11C\uBE59\uACFC \uC815\uB9AC\uC5D0 \uC9D1\uC911\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uD638\uCD9C\uC774 \uAE30\uAE30\uB85C \uB4E4\uC5B4\uC640 \uC5B4\uB290 \uD14C\uC774\uBE14\uC774 \uBD80\uB974\uB294\uC9C0 \uBC14\uB85C \uBCF4\uC5EC \uB3D9\uC120\uC774 \uC9E7\uC544\uC9D1\uB2C8\uB2E4.", "\uC2E0\uC785 \uC9C1\uC6D0\uC774 \uBA54\uB274\uB97C \uB2E4 \uC678\uC6B0\uAE30 \uC804\uC5D0\uB3C4 \uC8FC\uBB38 \uC624\uB958\uAC00 \uC0DD\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uB2E4\uB9CC \uAE30\uAE30 \uC548\uB0B4\uC640 \uACE0\uC7A5 \uB300\uC751\uC774 \uC0C8 \uC5C5\uBB34\uB85C \uC0DD\uAE30\uBBC0\uB85C \uB2F4\uB2F9\uC744 \uC815\uD574 \uB461\uB2C8\uB2E4.", "\uC778\uB825 \uBCC0\uD654\uC758 \uD06C\uAE30\uB294 \uB9E4\uC7A5 \uADDC\uBAA8\uC640 \uC6B4\uC601 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uC548\uB0B4 \uB2F4\uB2F9\uC744 \uC815\uD558\uBA74 \uCCAB \uC8FC \uC190\uB2D8 \uBB38\uC758\uAC00 \uC904\uACE0 \uC9C1\uC6D0 \uBD80\uB2F4\uC774 \uD55C \uC0AC\uB78C\uC5D0\uAC8C \uBAB0\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uC548\uB0B4 \uB2F4\uB2F9\uC740 \uCCAB \uB2EC\uB9CC \uB450\uC5B4\uB3C4 \uC190\uB2D8 \uC801\uC751\uC774 \uB05D\uB098\uB294 \uB9E4\uC7A5\uC774 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uC548\uB0B4\uB294 \uCCAB \uBC29\uBB38 \uC190\uB2D8\uC5D0\uAC8C \uD55C \uBC88\uB9CC \uD558\uBA74 \uC7AC\uBC29\uBB38 \uB54C\uB294 \uC2A4\uC2A4\uB85C \uC4F0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uD638\uCD9C \uC54C\uB9BC\uC744 \uBC1B\uB294 \uAE30\uAE30\uB97C \uC815\uD574 \uB450\uBA74 \uD638\uCD9C\uC774 \uC5EC\uB7EC \uC9C1\uC6D0\uC5D0\uAC8C \uB3D9\uC2DC\uC5D0 \uAC00\uC11C \uD63C\uC120\uC774 \uC0DD\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uD6A8\uACFC\uAC00 \uC791\uC740 \uC2DD\uB2F9\uC740 \uC5B4\uB514\uC778\uAC00\uC694?", "p": ["\uD55C \uBC88 \uC8FC\uBB38\uD558\uACE0 \uB05D\uB098\uB294 \uB2E8\uD488 \uC2DD\uB2F9\uC740 \uCD94\uAC00 \uC8FC\uBB38 \uD6A8\uACFC\uAC00 \uAC70\uC758 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uC801\uACE0 \uD68C\uC804\uC774 \uBE60\uB978 \uB9E4\uC7A5\uC740 \uD0A4\uC624\uC2A4\uD06C \uD55C \uB300\uAC00 \uB354 \uB9DE\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uB2E8\uACE8\uACFC\uC758 \uB300\uD654\uAC00 \uB9E4\uCD9C\uC5D0 \uC911\uC694\uD55C \uB9E4\uC7A5\uC740 \uAE30\uAE30\uAC00 \uC811\uC810\uC744 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774\uAC00 \uBD88\uC548\uC815\uD55C \uB9E4\uC7A5\uC740 \uC8FC\uBB38 \uB204\uB77D\uC774 \uC0DD\uACA8 \uD6A8\uACFC\uBCF4\uB2E4 \uBD88\uD3B8\uC774 \uD074 \uC218 \uC788\uC73C\uB2C8 \uD68C\uC120\uBD80\uD130 \uC810\uAC80\uD569\uB2C8\uB2E4.", "\uD6A8\uACFC\uAC00 \uC791\uAC8C \uB290\uAEF4\uC9C0\uB294 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uC218\uB97C \uC904\uC774\uAC70\uB098 \uD0A4\uC624\uC2A4\uD06C\uB85C \uBC14\uAFB8\uB294 \uC120\uD0DD\uB3C4 \uAC00\uB2A5\uD558\uBBC0\uB85C \uC57D\uC815\uC758 \uBCC0\uACBD \uC870\uAC74\uC744 \uBD05\uB2C8\uB2E4.", "\uB3C4\uC785 \uC804\uD6C4 \uBE44\uAD50\uB294 \uAC19\uC740 \uC694\uC77C \uAC19\uC740 \uC2DC\uAC04\uB300\uB85C \uB9DE\uCDB0\uC57C \uCC28\uC774\uAC00 \uBC14\uB974\uAC8C \uBCF4\uC785\uB2C8\uB2E4.", "\uD6A8\uACFC\uAC00 \uC791\uC73C\uBA74 \uC57D\uC815\uC758 \uB300\uC218 \uBCC0\uACBD\uC774\uB098 \uC77C\uC2DC \uC815\uC9C0 \uC870\uAC74\uC73C\uB85C \uBE44\uC6A9\uC744 \uC904\uC774\uB294 \uAE38\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uCCAB \uB2EC \uAE30\uAE30 \uC8FC\uBB38 \uBE44\uC728\uACFC \uB300\uAE30 \uC904 \uBCC0\uD654\uB97C \uAE30\uB85D\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uB3C4\uC785 \uD310\uB2E8\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uD558\uB098\uC694?", "items": ["\uCD94\uAC00 \uC8FC\uBB38 \uBE48\uB3C4\uC640 \uACC4\uC0B0\uB300 \uC904 \uAE38\uC774\uB97C \uC77C\uC8FC\uC77C \uC801\uC5B4 \uBD05\uB2C8\uB2E4.", "\uC88C\uC11D \uC218\uC640 \uD14C\uC774\uBE14 \uAD6C\uC131\uC73C\uB85C \uB300\uC218\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uC120\uACB0\uC81C\xB7\uD6C4\uACB0\uC81C, \uC9C1\uC6D0 \uD638\uCD9C \uB4F1 \uC4F8 \uAE30\uB2A5\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uC77C\uBD80 \uC88C\uC11D\uC5D0 \uBA3C\uC800 \uB450\uACE0 \uC190\uB2D8 \uBC18\uC751\uC744 \uBD05\uB2C8\uB2E4.", "\uD6A8\uACFC\uB97C \uBCF4\uACE0 \uB300\uC218\uB97C \uB298\uB9AC\uAC70\uB098 \uC870\uC815\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uB3C4\uC785 \uC804\uD6C4 \uBCC0\uD654", "head": ["\uD56D\uBAA9", "\uB3C4\uC785 \uC804", "\uB3C4\uC785 \uB4A4"], "rows": [["\uC8FC\uBB38 \uBC1B\uAE30", "\uC9C1\uC6D0 \uBC29\uBB38", "\uC190\uB2D8 \uC9C1\uC811 \uC785\uB825"], ["\uCD94\uAC00 \uC8FC\uBB38", "\uC9C1\uC6D0 \uD638\uCD9C \uD544\uC694", "\uAE30\uAE30\uC5D0\uC11C \uBC14\uB85C"], ["\uACC4\uC0B0", "\uACC4\uC0B0\uB300 \uC904", "\uC790\uB9AC\uC5D0\uC11C \uACB0\uC81C"], ["\uC8FC\uBB38 \uC624\uB958", "\uB4E3\uACE0 \uC801\uB294 \uACFC\uC815", "\uC785\uB825 \uADF8\uB300\uB85C \uCD9C\uB825"], ["\uC0C8 \uC5C5\uBB34", "\uC5C6\uC74C", "\uAE30\uAE30 \uC548\uB0B4\xB7\uACE0\uC7A5 \uB300\uC751"]] }, "faq": [["\uC791\uC740 \uC2DD\uB2F9\uB3C4 \uD6A8\uACFC\uAC00 \uC788\uB098\uC694?", "\uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC73C\uBA74 \uC788\uC2B5\uB2C8\uB2E4. \uB2E8\uD488 \uC704\uC8FC\uBA74 \uD0A4\uC624\uC2A4\uD06C\uAC00 \uB354 \uB9DE\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC190\uB2D8\uC774 \uAE30\uAE30\uB97C \uC2EB\uC5B4\uD558\uBA74\uC694?", "\uC9C1\uC6D0 \uC8FC\uBB38\uC744 \uB0A8\uACA8 \uB450\uACE0 \uCCAB \uBC29\uBB38 \uC190\uB2D8\uC5D0\uAC8C \uC0AC\uC6A9\uBC95\uC744 \uC548\uB0B4\uD558\uBA74 \uB429\uB2C8\uB2E4."], ["\uC9C1\uC6D0\uC744 \uC904\uC77C \uC218 \uC788\uB098\uC694?", "\uC8FC\uBB38\xB7\uACC4\uC0B0 \uC2DC\uAC04\uC774 \uC904\uC5B4 \uAC19\uC740 \uC778\uC6D0\uC73C\uB85C \uB354 \uB9CE\uC740 \uD14C\uC774\uBE14\uC744 \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uADDC\uBAA8\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD6A8\uACFC\uB97C \uC5B4\uB5BB\uAC8C \uCE21\uC815\uD558\uB098\uC694?", "\uB3C4\uC785 \uC804\uD6C4 \uD14C\uC774\uBE14\uB2F9 \uD3C9\uADE0 \uC8FC\uBB38 \uD69F\uC218\uC640 \uD53C\uD06C \uC2DC\uAC04 \uB300\uAE30 \uC904\uC744 \uBE44\uAD50\uD569\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uD14C\uC774\uBE14\uC624\uB354\uBE44\uAD50", "\uD14C\uC774\uBE14\uC624\uB354\uC18C\uADDC\uBAA8\uB9E4\uC7A5"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uD574\uC9C0\uC704\uC57D\uAE08", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uD574\uC9C0\xB7\uC704\uC57D\uAE08", "title": "\uD14C\uC774\uBE14\uC624\uB354 \uD574\uC9C0\uD558\uBA74 \uC704\uC57D\uAE08\uC774 \uC5BC\uB9C8\uB098 \uB418\uB098\uC694? \u2014 \uB300\uC218\uC5D0 \uB530\uB77C \uCEE4\uC9C0\uB294 \uAD6C\uC870", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uD574\uC9C0 \uB54C \uC704\uC57D\uAE08\uC774 \uD0DC\uBE14\uB9BF \uB300\uC218\uC5D0 \uBE44\uB840\uD574 \uCEE4\uC9C0\uB294 \uAD6C\uC870\uC640 \uC57D\uC815\uC11C\uC5D0\uC11C \uCC3E\uC744 \uC870\uD56D, \uC77C\uBD80 \uB300\uC218\uB9CC \uC904\uC774\uB294 \uAC10\uCD95\uACFC \uC804\uCCB4 \uD574\uC9C0\uC758 \uCC28\uC774, \uBC18\uB0A9 \uC808\uCC28\uC640 \uD30C\uC190 \uAE30\uAE30 \uCC98\uB9AC, \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815 \uD574\uC9C0\uC640 \uC790\uB8CC \uBC31\uC5C5\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD14C\uC774\uBE14\uC624\uB354 \uC704\uC57D\uAE08\uC740 \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC558\uC744 \uB54C \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uD0DC\uBE14\uB9BF \uB300\uC218 \uC804\uCCB4\uC5D0 \uC801\uC6A9\uB418\uBBC0\uB85C \uB300\uC218\uAC00 \uB9CE\uC744\uC218\uB85D \uCEE4\uC9C0\uACE0, \uAE08\uC561\uC740 \uC57D\uC815\uC11C\uC758 \uC0B0\uC815 \uBC29\uC2DD\uC744 \uB530\uB974\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uC804\uCCB4 \uD574\uC9C0\uBCF4\uB2E4 \uB300\uC218 \uAC10\uCD95 \uC870\uD56D\uC744 \uBA3C\uC800 \uBCF4\uBA74 \uBE44\uC6A9\uC774 \uB2EC\uB77C\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "sections": [{ "h": "\uC704\uC57D\uAE08\uC740 \uC5B4\uB5BB\uAC8C \uCEE4\uC9C0\uB098\uC694?", "p": ["\uC57D\uC815\uC11C\uC758 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uB300\uB2F9\uC73C\uB85C \uC801\uC6A9\uB418\uBBC0\uB85C \uC5F4 \uB300\uBA74 \uC5F4 \uB300\uBD84\uC774 \uB429\uB2C8\uB2E4.", "\uAD6C\uB9E4\uD55C \uD0DC\uBE14\uB9BF\uC740 \uC704\uC57D\uAE08\uC774 \uC5C6\uACE0 \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uB9CC \uC815\uB9AC\uD558\uBA74 \uB429\uB2C8\uB2E4.", "\uC124\uCE58\uBE44 \uC9C0\uC6D0\uC774\uB098 \uAC70\uCE58\uB300 \uC81C\uACF5 \uAC19\uC740 \uC870\uAC74\uC744 \uBC1B\uC558\uB2E4\uBA74 \uBC18\uD658 \uC870\uD56D\uC774 \uB530\uB85C \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD30C\uC190\uB41C \uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uBA74 \uAE30\uAE30\uAC12 \uC870\uD56D\uC774 \uB354\uD574\uC9C0\uBBC0\uB85C \uBC18\uB0A9 \uC804 \uC0C1\uD0DC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC790\uB3D9 \uC5F0\uC7A5\uB41C \uC57D\uC815\uC740 \uC5F0\uC7A5 \uB4A4 \uC870\uAC74\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4 \uD604\uC7AC \uC57D\uC815 \uC0C1\uD0DC\uB97C \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uC0B0\uC815 \uBC29\uC2DD\uC774 \uC57D\uC815\uC11C\uC5D0 \uC5C6\uC73C\uBA74 \uCCAD\uAD6C \uADFC\uAC70\uB97C \uAE00\uB85C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uB300\uC218\uC640 \uC57D\uC815\uC5D0 \uB530\uB77C \uAE08\uC561\uC774 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uD574\uC9C0 \uC804\uC5D0 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAC10\uCD95 \uC870\uD56D\uC774 \uC5C6\uACE0 \uC804\uCCB4 \uD574\uC9C0\uB9CC \uAC00\uB2A5\uD55C \uC57D\uC815\uB3C4 \uC788\uC5B4 \uACC4\uC57D \uB54C \uAC10\uCD95 \uAC00\uB2A5 \uC5EC\uBD80\uB97C \uBC18\uB4DC\uC2DC \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC804\uCCB4 \uD574\uC9C0 \uC804\uC5D0 \uAC10\uCD95\uC73C\uB85C \uB300\uC218\uB97C \uC904\uC774\uBA74\uC11C \uC6B4\uC601\uC744 \uC774\uC5B4\uAC00\uB294 \uBC29\uBC95\uC774 \uBE44\uC6A9\uC774 \uC801\uC740 \uACBD\uC6B0\uB3C4 \uC788\uC5B4 \uB450 \uAC00\uC9C0\uB97C \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB77C\uB3C4 \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uC5D0 \uCD5C\uC18C \uC0AC\uC6A9 \uAE30\uAC04\uC774 \uC788\uC73C\uBA74 \uADF8 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uC2B5\uB2C8\uB2E4.", "\uC704\uC57D \uC870\uAC74\uC740 \uB300\uB2F9\uC73C\uB85C \uC801\uC6A9\uB418\uBBC0\uB85C \uB300\uC218\uAC00 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uD574\uC9C0 \uC804\uC5D0 \uAC10\uCD95 \uAC00\uB2A5 \uC5EC\uBD80\uB97C \uBA3C\uC800 \uBB3B\uB294 \uAC83\uC774 \uBE44\uC6A9\uC744 \uC904\uC785\uB2C8\uB2E4.", "\uC704\uC57D \uC0B0\uC815\uC5D0 \uB300\uC218\uC640 \uB0A8\uC740 \uAC1C\uC6D4 \uC218\uAC00 \uBAA8\uB450 \uB4E4\uC5B4\uAC00\uBBC0\uB85C \uB450 \uC22B\uC790\uB97C \uC57D\uC815\uC11C\uC5D0\uC11C \uD655\uC778\uD574 \uACC4\uC0B0\uD574 \uBD05\uB2C8\uB2E4."] }, { "h": "\uAC10\uCD95\uACFC \uC804\uCCB4 \uD574\uC9C0\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?", "p": ["\uC88C\uC11D\uC744 \uC904\uC5EC \uC77C\uBD80 \uB300\uC218\uB9CC \uBE7C\uB294 \uAC10\uCD95\uC740 \uBCC4\uB3C4 \uC870\uD56D\uC774 \uC788\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uACE0, \uC870\uAC74\uC774 \uC804\uCCB4 \uD574\uC9C0\uBCF4\uB2E4 \uAC00\uBCBC\uC6B4 \uC5C5\uCCB4\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5C5\uC885 \uBCC0\uACBD\uC774\uB098 \uB9AC\uBAA8\uB378\uB9C1\uC73C\uB85C \uC7A0\uC2DC \uAE30\uAE30\uB97C \uCE58\uC6B8 \uB54C\uB294 \uC77C\uC2DC \uC815\uC9C0 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC804\uCCB4 \uD574\uC9C0\uB294 \uAE30\uAE30\uC640 \uD504\uB85C\uADF8\uB7A8\uC744 \uBAA8\uB450 \uC815\uB9AC\uD558\uB294 \uAC83\uC774\uB77C \uB450 \uC57D\uC815\uC744 \uAC01\uAC01 \uD574\uC9C0\uD569\uB2C8\uB2E4.", "\uAC10\uCD95 \uB4A4 \uB0A8\uC740 \uB300\uC218\uC758 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB300\uB2F9 \uC694\uAE08 \uAD6C\uAC04 \uBCC0\uACBD\uC73C\uB85C \uC624\uB97C \uC218 \uC788\uC73C\uB2C8 \uBC14\uB010 \uAE08\uC561\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uAC10\uCD95 \uC694\uCCAD\uB3C4 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uAC10\uCD95\uC774 \uC548 \uB418\uB294 \uC57D\uC815\uC774\uBA74 \uB0A8\uC740 \uAE30\uAE30\uB97C \uC608\uBE44\uB85C \uB450\uB294 \uBC29\uBC95\uB3C4 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uC77C\uC2DC \uC815\uC9C0 \uC911\uC5D0\uB3C4 \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uB098\uAC00\uB294\uC9C0 \uD655\uC778\uD574\uC57C \uB9AC\uBAA8\uB378\uB9C1 \uAE30\uAC04 \uBE44\uC6A9\uC774 \uC608\uCE21\uB429\uB2C8\uB2E4.", "\uC0AC\uC740\uD488 \uBC18\uD658 \uC870\uD56D\uC740 \uBC1B\uC740 \uD488\uBAA9\uACFC \uAE08\uC561\uC774 \uC801\uD600 \uC788\uC5B4\uC57C \uD558\uBBC0\uB85C \uADFC\uAC70\uAC00 \uC5C6\uC73C\uBA74 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uAC10\uCD95 \uB4A4 \uB0A8\uC740 \uAE30\uAE30\uC758 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB2E4\uC2DC \uC815\uB9AC\uD574 \uC190\uB2D8 \uC8FC\uBB38\uC774 \uC5C9\uB6B1\uD55C \uD14C\uC774\uBE14\uB85C \uAC00\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uAC10\uCD95\uD55C \uAE30\uAE30\uB294 \uBC18\uB0A9\uD558\uACE0 \uB0A8\uC740 \uAE30\uAE30\uC758 \uC57D\uC815 \uC870\uAC74\uC774 \uBC14\uB00C\uC9C0 \uC54A\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uC2E0\uCCAD \uC804 \uC900\uBE44\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC8FC\uBB38 \uC790\uB8CC\uC640 \uBA54\uB274, \uB9E4\uCD9C \uBCF4\uACE0\uC11C\uB97C \uBC31\uC5C5\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0\uC11C \uC911\uB3C4 \uD574\uC9C0\xB7\uAC10\uCD95\xB7\uBC18\uB0A9 \uC870\uD56D\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uCD08\uAE30\uD654\uD574 \uB9E4\uC7A5 \uC815\uBCF4\uC640 \uACB0\uC81C \uC124\uC815\uC744 \uC9C0\uC6C1\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD488\uBAA9(\uD0DC\uBE14\uB9BF\xB7\uAC70\uCE58\uB300\xB7\uCDA9\uC804\uAE30)\uC744 \uC57D\uC815\uC11C \uD488\uBAA9\uACFC \uB300\uC870\uD569\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uD574\uC9C0 \uC2E0\uCCAD\uACFC \uD0DC\uBE14\uB9BF \uBC18\uB0A9 \uC2E0\uCCAD\uC744 \uB530\uB85C \uB123\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uBC18\uB0A9 \uC804\uC5D0 \uD0DC\uBE14\uB9BF \uC548 \uC190\uB2D8 \uACB0\uC81C \uAE30\uB85D\uC774 \uB0A8\uC544 \uC788\uC9C0 \uC54A\uC740\uC9C0 \uCD08\uAE30\uD654\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD488\uBAA9 \uC911 \uAC70\uCE58\uB300\uC640 \uCDA9\uC804\uAE30\uAC00 \uBE60\uC9C0\uBA74 \uD488\uBAA9 \uB300\uAE08\uC774 \uCCAD\uAD6C\uB420 \uC218 \uC788\uC5B4 \uD558\uB098\uC529 \uC149\uB2C8\uB2E4.", "\uBC31\uC5C5 \uC790\uB8CC\uC5D0\uB294 \uD14C\uC774\uBE14\uBCC4 \uC8FC\uBB38 \uB0B4\uC5ED\uACFC \uACB0\uC81C \uB0B4\uC5ED\uC774 \uD3EC\uD568\uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC11C\uC5D0 \uBC18\uB0A9 \uC608\uC815\uC77C\uACFC \uD488\uBAA9 \uC218\uB97C \uC801\uC73C\uBA74 \uC5C5\uCCB4 \uD655\uC778 \uC808\uCC28\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uCC98\uB9AC \uB4A4 \uCCAD\uAD6C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uBCF4\uB098\uC694?", "p": ["\uB300\uC218\uBCC4 \uBC18\uB0A9 \uD655\uC778\uC99D\uACFC \uD574\uC9C0 \uD655\uC778\uC11C\uB97C \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0 \uB300\uB2F9 \uC774\uC6A9\uB8CC\uC640 \uC0AC\uC6A9\uB8CC\uAC00 \uBE60\uC84C\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9\uC744 \uC37C\uB2E4\uBA74 \uD3EC\uC2A4 \uCABD \uC5F0\uB3D9 \uC124\uC815\uB3C4 \uC815\uB9AC\uD574 \uC624\uB958 \uBA54\uC2DC\uC9C0\uAC00 \uB728\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4\uC5D0\uB3C4 \uB300\uB2F9 \uC774\uC6A9\uB8CC\uAC00 \uBE60\uC838\uB098\uAC00\uBA74 \uC811\uC218 \uBC88\uD638\uB85C \uBB38\uC758\uD558\uACE0 \uC790\uB3D9\uC774\uCCB4\uB97C \uBA48\uCDA5\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9 \uC124\uC815\uC744 \uC9C0\uC6B0\uC9C0 \uC54A\uC73C\uBA74 \uD3EC\uC2A4 \uD654\uBA74\uC5D0 \uC624\uB958\uAC00 \uACC4\uC18D \uB728\uBBC0\uB85C \uD574\uC9C0 \uB4A4 \uD3EC\uC2A4 \uC5C5\uCCB4\uC5D0\uB3C4 \uC54C\uB9BD\uB2C8\uB2E4.", "\uD574\uC9C0 \uD655\uC778\uC11C\uC5D0 \uD574\uC9C0\uC77C\uACFC \uB0A8\uC740 \uCCAD\uAD6C \uAE08\uC561\uC774 \uC801\uD600 \uC788\uB294\uC9C0 \uBCF4\uACE0 \uC5C6\uC73C\uBA74 \uC801\uC5B4 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5C5\uCCB4\uC5D0 \uC5F0\uB3D9 \uD574\uC81C\uB97C \uC694\uCCAD\uD560 \uB54C \uD14C\uC774\uBE14\uC624\uB354 \uD574\uC9C0\uC77C\uC744 \uD568\uAED8 \uC54C\uB9AC\uBA74 \uC124\uC815 \uC815\uB9AC\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uB9C8\uC9C0\uB9C9 \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uD574\uC9C0\uC77C \uC774\uD6C4 \uCCAD\uAD6C\uAC00 \uC5C6\uB294\uC9C0 \uBCF4\uACE0, \uC788\uC73C\uBA74 \uD574\uC9C0 \uD655\uC778\uC11C\uB85C \uC815\uC815\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uB4A4 \uD3EC\uC2A4 \uD654\uBA74\uC5D0 \uB0A8\uC740 \uD14C\uC774\uBE14\uC624\uB354 \uBA54\uB274 \uD56D\uBAA9\uC774 \uC788\uC73C\uBA74 \uD568\uAED8 \uC9C0\uC6CC\uC57C \uC9C1\uC6D0\uC774 \uD63C\uB3D9\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9 \uC124\uC815 \uC815\uB9AC\uB97C \uD3EC\uC2A4 \uC5C5\uCCB4\uC5D0 \uC694\uCCAD\uD558\uB294 \uAC83\uC73C\uB85C \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uD574\uC9C0 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uC57D\uC815\uC11C\uC5D0\uC11C \uD574\uC9C0\xB7\uAC10\uCD95 \uC870\uD56D\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uD14C\uC774\uBE14\uBCC4 \uC8FC\uBB38 \uC790\uB8CC\uB97C \uBC31\uC5C5\uD558\uACE0 \uD0DC\uBE14\uB9BF\uC744 \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4.", "\uAC10\uCD95\uC778\uC9C0 \uC804\uCCB4 \uD574\uC9C0\uC778\uC9C0 \uC815\uD574 \uAE00\uB85C \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uACE0 \uD655\uC778\uC99D\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uB300\uB2F9 \uC774\uC6A9\uB8CC\uC640 \uC0AC\uC6A9\uB8CC\uAC00 \uBAA8\uB450 \uBE60\uC84C\uB294\uC9C0 \uBD05\uB2C8\uB2E4."] }, "table": { "caption": "\uD574\uC9C0 \uC720\uD615\uBCC4 \uD655\uC778", "head": ["\uC720\uD615", "\uC801\uC6A9 \uC870\uD56D", "\uBE44\uC6A9"], "rows": [["\uC804\uCCB4 \uD574\uC9C0", "\uC911\uB3C4 \uD574\uC9C0", "\uB300\uC218 \uC804\uCCB4 \uC870\uAC74"], ["\uB300\uC218 \uAC10\uCD95", "\uAC10\uCD95 \uC870\uD56D", "\uAC10\uCD95\uBD84 \uC870\uAC74"], ["\uC77C\uC2DC \uC815\uC9C0", "\uC815\uC9C0 \uC870\uD56D", "\uC5C5\uCCB4\uC5D0 \uB530\uB77C"], ["\uC57D\uC815 \uC885\uB8CC \uB4A4", "\uC885\uB8CC \uC870\uD56D", "\uC5C6\uC74C"]] }, "faq": [["\uB300\uC218\uB97C \uBC18\uC73C\uB85C \uC904\uC774\uBA74 \uC704\uC57D\uAE08\uB3C4 \uBC18\uC778\uAC00\uC694?", "\uAC10\uCD95 \uC870\uD56D\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4. \uB300\uB2F9 \uC870\uAC74\uC774\uBA74 \uC904\uC778 \uB300\uC218\uB9CC\uD07C \uC801\uC6A9\uB429\uB2C8\uB2E4."], ["\uAD6C\uB9E4\uD55C \uD0DC\uBE14\uB9BF\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uBC18\uB0A9\uD560 \uD544\uC694\uAC00 \uC5C6\uACE0 \uD504\uB85C\uADF8\uB7A8 \uC57D\uC815\uB9CC \uD574\uC9C0\uD569\uB2C8\uB2E4."], ["\uAE68\uC9C4 \uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uBA74\uC694?", "\uAE30\uAE30\uAC12 \uC870\uD56D\uC774 \uBD99\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC0C1\uD0DC\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uAE30\uACE0 \uD655\uC778\uC99D\uC5D0 \uAE30\uB85D\uD569\uB2C8\uB2E4."], ["\uD574\uC9C0 \uB4A4 \uD3EC\uC2A4\uAE30\uB294 \uADF8\uB300\uB85C \uC368\uB3C4 \uB418\uB098\uC694?", "\uB429\uB2C8\uB2E4. \uD3EC\uC2A4 \uCABD \uD14C\uC774\uBE14\uC624\uB354 \uC5F0\uB3D9 \uC124\uC815\uB9CC \uC815\uB9AC\uD569\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC784\uB300\uC57D\uC815", "\uD14C\uC774\uBE14\uC624\uB354\uD0DC\uBE14\uB9BF\uBD84\uC2E4\uD30C\uC190", "\uD0A4\uC624\uC2A4\uD06C\uD574\uC9C0\uC704\uC57D\uAE08"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uD0DC\uBE14\uB9BF\uBD84\uC2E4\uD30C\uC190", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uD0DC\uBE14\uB9BF \uBD84\uC2E4\xB7\uD30C\uC190", "title": "\uD14C\uC774\uBE14\uC624\uB354 \uD0DC\uBE14\uB9BF\uC774 \uAE68\uC9C0\uAC70\uB098 \uC5C6\uC5B4\uC9C0\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694? \u2014 \uC2E0\uACE0\xB7\uAD50\uCCB4\xB7\uC608\uBC29\uC758 \uC21C\uC11C", "desc": "\uD14C\uC774\uBE14\uC624\uB354 \uD0DC\uBE14\uB9BF\uC774 \uD30C\uC190\uB418\uAC70\uB098 \uBD84\uC2E4\uB410\uC744 \uB54C \uAE30\uAE30 \uC7A0\uAE08\uACFC \uC2E0\uACE0, \uAD50\uCCB4 \uC808\uCC28, \uC57D\uC815\uC11C\uC758 \uBE44\uC6A9 \uC870\uAC74, \uAD50\uCCB4 \uAE30\uAC04\uC758 \uC6B4\uC601 \uBC29\uBC95\uACFC \uD30C\uC190\uC744 \uC904\uC774\uB294 \uAC70\uCE58\uB300\xB7\uCF00\uC774\uC2A4\xB7\uBC30\uCE58 \uBC29\uBC95, \uB9C8\uAC10 \uB54C \uAE30\uAE30 \uC218\uB97C \uC138\uB294 \uADDC\uCE59\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD0DC\uBE14\uB9BF\uC774 \uAE68\uC9C0\uBA74 \uC57D\uC815\uC11C\uC758 \uD30C\uC190 \uC870\uD56D\uC5D0 \uB530\uB77C \uAD50\uCCB4\uB97C \uC2E0\uCCAD\uD558\uACE0, \uC5C6\uC5B4\uC9C0\uBA74 \uBA3C\uC800 \uAE30\uAE30\uB97C \uC7A0\uADFC \uB4A4 \uBD84\uC2E4 \uC2E0\uACE0\uB97C \uD558\uB294 \uC21C\uC11C\uC774\uBA70 \uBE44\uC6A9 \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uB530\uB974\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4. \uC190\uB2D8\uC774 \uB9CC\uC9C0\uB294 \uAE30\uAE30\uB77C \uD30C\uC190\uC774 \uB2E4\uB978 \uC7A5\uBE44\uBCF4\uB2E4 \uC7A6\uC73C\uBBC0\uB85C \uC608\uBC29 \uC7A5\uBE44\uC640 \uC2E0\uACE0 \uC21C\uC11C\uB97C \uBBF8\uB9AC \uC815\uD574 \uB461\uB2C8\uB2E4.", "sections": [{ "h": "\uD30C\uC190\uB410\uC744 \uB54C \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uAE68\uC9C4 \uC0C1\uD0DC\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uAE30\uACE0 \uD14C\uC774\uBE14 \uBC88\uD638\uC640 \uC2DC\uAC04\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC758 \uD30C\uC190 \uC870\uD56D\uC5D0\uC11C \uAD50\uCCB4 \uAE30\uC900\uACFC \uC790\uAE30\uBD80\uB2F4\uC774 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5C5\uCCB4\uC5D0 \uAD50\uCCB4\uB97C \uC2E0\uCCAD\uD558\uACE0 \uAD50\uCCB4 \uAE30\uAE30 \uB3C4\uCC29 \uAE30\uAC04\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAC04 \uB3D9\uC548 \uADF8 \uD14C\uC774\uBE14\uC740 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uC6B4\uC601\uD558\uACE0 \uC608\uBE44 \uAE30\uAE30\uAC00 \uC788\uC73C\uBA74 \uBC14\uAFD4 \uB461\uB2C8\uB2E4.", "\uD654\uBA74\uB9CC \uAE68\uC9C0\uACE0 \uC791\uB3D9\uD558\uBA74 \uBCF4\uD638 \uD544\uB984\uC744 \uBD99\uC5EC \uC784\uC2DC\uB85C \uC4F8 \uC218 \uC788\uC9C0\uB9CC \uD130\uCE58 \uC624\uC791\uB3D9\uC774 \uC0DD\uAE30\uBA74 \uCE58\uC6C1\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uAE68\uB728\uB9B0 \uACBD\uC6B0 \uBC30\uC0C1 \uC694\uAD6C\uB294 \uB9E4\uC7A5 \uD310\uB2E8\uC774\uBA70, \uC57D\uC815\uC0C1 \uBE44\uC6A9\uC740 \uB9E4\uC7A5\uACFC \uC5C5\uCCB4 \uC0AC\uC774\uC758 \uBB38\uC81C\uC785\uB2C8\uB2E4.", "\uD30C\uC190\uC774 \uD2B9\uC815 \uD14C\uC774\uBE14\uC5D0\uC11C \uBC18\uBCF5\uB418\uBA74 \uAC70\uCE58 \uBC29\uC2DD\uC774\uB098 \uC704\uCE58\uB97C \uBC14\uAFC9\uB2C8\uB2E4.", "\uD30C\uC190 \uC0AC\uC9C4\uC5D0\uB294 \uD14C\uC774\uBE14 \uBC88\uD638\uAC00 \uBCF4\uC774\uAC8C \uCC0D\uC5B4 \uB450\uBA74 \uC5B4\uB290 \uAE30\uAE30\uC778\uC9C0 \uC99D\uBE59\uC774 \uB429\uB2C8\uB2E4.", "\uC784\uC2DC\uB85C \uC4F8 \uB54C\uB294 \uAE68\uC9C4 \uD654\uBA74 \uC870\uAC01\uC774 \uC190\uB2D8\uC5D0\uAC8C \uB2FF\uC9C0 \uC54A\uB3C4\uB85D \uBCF4\uD638 \uD544\uB984 \uC704\uC5D0 \uD14C\uC774\uD504\uB97C \uB367\uB311\uB2C8\uB2E4.", "\uD30C\uC190 \uAD50\uCCB4 \uC2E0\uCCAD\uC11C\uC5D0 \uD14C\uC774\uBE14 \uBC88\uD638\xB7\uAE30\uAE30 \uBC88\uD638\xB7\uD30C\uC190 \uC77C\uC2DC\uB97C \uC801\uC73C\uBA74 \uCC98\uB9AC\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uD30C\uC190\uC774 \uC7A6\uC740 \uD14C\uC774\uBE14\uC740 \uAC70\uCE58 \uAC01\uB3C4\uB97C \uB0AE\uCD94\uAC70\uB098 \uCF00\uC774\uC2A4\uB97C \uB450\uAEBC\uC6B4 \uAC83\uC73C\uB85C \uBC14\uAFC9\uB2C8\uB2E4.", "\uD30C\uC190 \uC811\uC218 \uB4A4 \uAD50\uCCB4 \uAE30\uAE30\uAC00 \uC62C \uB54C\uAE4C\uC9C0\uC758 \uAE30\uAC04\uC744 \uAE30\uB85D\uD574 \uB450\uBA74 \uC57D\uC815 \uC870\uAC74\uACFC \uBE44\uAD50\uD560 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4."] }, { "h": "\uBD84\uC2E4\uB410\uC744 \uB54C \uBB34\uC5C7\uC744 \uD558\uB098\uC694?", "p": ["\uAD00\uB9AC \uD654\uBA74\uC774\uB098 \uC5C5\uCCB4 \uCC3D\uAD6C\uC5D0\uC11C \uAE30\uAE30\uB97C \uC7A0\uAC00 \uACB0\uC81C\uC640 \uC8FC\uBB38 \uAE30\uB2A5\uC744 \uB9C9\uC2B5\uB2C8\uB2E4.", "\uBD84\uC2E4 \uC2E0\uACE0\uB97C \uAE00\uB85C \uB0A8\uAE30\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC758 \uBD84\uC2E4 \uC870\uD56D\uC5D0\uC11C \uAE30\uAE30\uAC12 \uCCAD\uAD6C \uC870\uAC74\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAE30\uB97C \uC2E0\uCCAD\uD558\uACE0 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB2E4\uC2DC \uB4F1\uB85D\uD569\uB2C8\uB2E4.", "\uBCF4\uD5D8\uC774 \uD3EC\uD568\uB41C \uC57D\uC815\uC774\uBA74 \uBCF4\uD5D8 \uCC98\uB9AC \uC808\uCC28\uC640 \uC790\uAE30\uBD80\uB2F4\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4\uC774 \uC7A6\uC73C\uBA74 \uAC70\uCE58\uB300 \uC7A0\uAE08 \uC7A5\uCE58\uB97C \uB2EC\uAC70\uB098 \uC601\uC5C5 \uC885\uB8CC \uB54C \uAE30\uAE30\uB97C \uC218\uAC70\uD558\uB294 \uADDC\uCE59\uC744 \uB461\uB2C8\uB2E4.", "\uBD84\uC2E4 \uC2E0\uACE0 \uB4A4 \uAD50\uCCB4 \uAE30\uAE30\uAC00 \uC62C \uB54C\uAE4C\uC9C0 \uADF8 \uD14C\uC774\uBE14\uC758 \uC8FC\uBB38\uC744 \uC9C1\uC6D0\uC774 \uBC1B\uB3C4\uB85D \uB2F4\uB2F9\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC544 \uB450\uBA74 \uBCF4\uD5D8 \uCC98\uB9AC\uB098 \uBE44\uC6A9 \uB2E4\uD23C \uB54C \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uBD84\uC2E4\uC774 \uC601\uC5C5 \uC911\uC5D0 \uD655\uC778\uB418\uBA74 \uC989\uC2DC \uC7A0\uADF8\uACE0, \uB9C8\uAC10 \uB54C \uD655\uC778\uB418\uBA74 \uB2E4\uC74C \uC601\uC5C5 \uC804\uC5D0 \uAD50\uCCB4\uB97C \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4 \uC2E0\uACE0 \uB4A4 \uAE30\uAE30\uAC00 \uB3CC\uC544\uC624\uBA74 \uC7A0\uAE08 \uD574\uC81C\uC640 \uC7AC\uB4F1\uB85D\uC744 \uC5C5\uCCB4\uC5D0 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4 \uAE30\uAE30\uAC00 \uACB0\uC81C \uAE30\uB2A5\uC774 \uC7A0\uAE34 \uB4A4\uC5D0\uB3C4 \uC8FC\uBB38 \uD654\uBA74\uC740 \uC5F4\uB9B4 \uC218 \uC788\uC73C\uB2C8 \uD14C\uC774\uBE14 \uBC88\uD638 \uB4F1\uB85D\uC744 \uD574\uC81C\uD574 \uB461\uB2C8\uB2E4."] }, { "h": "\uC608\uBC29\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uBAA8\uC11C\uB9AC\uB97C \uAC10\uC2F8\uB294 \uBCF4\uD638 \uCF00\uC774\uC2A4\uC640 \uD14C\uC774\uBE14\uC5D0 \uACE0\uC815\uB418\uB294 \uAC70\uCE58\uB300\uB97C \uC501\uB2C8\uB2E4.", "\uCDA9\uC804 \uCF00\uC774\uBE14\uC774 \uB2F9\uACA8\uC838 \uB5A8\uC5B4\uC9C0\uC9C0 \uC54A\uB3C4\uB85D \uCF00\uC774\uBE14 \uAE38\uC774\uC640 \uC704\uCE58\uB97C \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uC601\uC5C5 \uC885\uB8CC \uB54C \uAE30\uAE30 \uC218\uB97C \uC138\uB294 \uB9C8\uAC10 \uD56D\uBAA9\uC744 \uB450\uBA74 \uBD84\uC2E4\uC744 \uBE68\uB9AC \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC190\uB2D8\uC5D0\uAC8C \uAE30\uAE30\uB97C \uB4E4\uC5B4 \uC62C\uB9AC\uC9C0 \uC54A\uC544\uB3C4 \uBCF4\uC774\uB294 \uAC01\uB3C4\uB85C \uAC70\uCE58\uD569\uB2C8\uB2E4.", "\uC220\uC744 \uB2E4\uB8E8\uB294 \uB9E4\uC7A5\uC740 \uC561\uCCB4 \uD53C\uD574\uAC00 \uC7A6\uC544 \uBC29\uC218 \uCF00\uC774\uC2A4\uB97C \uACE0\uB824\uD569\uB2C8\uB2E4.", "\uC608\uBC29 \uC7A5\uBE44 \uBE44\uC6A9\uACFC \uAD50\uCCB4 \uC870\uAC74\uC744 \uBE44\uAD50\uD558\uBA74 \uC5B4\uB290 \uCABD\uC774 \uC801\uC740\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uC608\uBC29 \uC7A5\uBE44\uB294 \uC124\uCE58 \uB54C \uD568\uAED8 \uB123\uC73C\uBA74 \uAC70\uCE58 \uC791\uC5C5\uC774 \uD55C \uBC88\uC5D0 \uB05D\uB0A9\uB2C8\uB2E4.", "\uCF00\uC774\uC2A4 \uC0C9\uC744 \uD14C\uC774\uBE14 \uBC88\uD638\uBCC4\uB85C \uB2E4\uB974\uAC8C \uD558\uBA74 \uAD50\uB300 \uB54C \uAE30\uAE30 \uC218\uB97C \uC138\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uBC29\uC218 \uCF00\uC774\uC2A4\uB294 \uC74C\uB8CC\uAC00 \uC3DF\uC544\uC9C0\uB294 \uB9E4\uC7A5\uC5D0\uC11C \uAD50\uCCB4 \uBE44\uC6A9\uC744 \uD06C\uAC8C \uC904\uC785\uB2C8\uB2E4.", "\uBCF4\uD638 \uCF00\uC774\uC2A4\uB294 \uAE30\uAE30 \uBAA8\uB378\uC5D0 \uB9DE\uB294 \uADDC\uACA9\uC774\uC5B4\uC57C \uACB0\uC81C \uBAA8\uB4C8\uACFC \uCDA9\uC804 \uB2E8\uC790\uB97C \uAC00\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uCDA9\uC804 \uCF00\uC774\uBE14\uC740 \uD14C\uC774\uBE14 \uC544\uB798\uB85C \uACE0\uC815\uD574 \uC190\uB2D8 \uBC1C\uC5D0 \uAC78\uB9AC\uC9C0 \uC54A\uAC8C \uD558\uBA74 \uB099\uD558 \uD30C\uC190\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uAD50\uCCB4 \uAE30\uAC04\uC5D0\uB294 \uC5B4\uB5BB\uAC8C \uC6B4\uC601\uD558\uB098\uC694?", "p": ["\uD574\uB2F9 \uD14C\uC774\uBE14\uC740 \uC9C1\uC6D0\uC774 \uC8FC\uBB38\uC744 \uBC1B\uC544 \uD3EC\uC2A4\uC5D0 \uB123\uACE0 \uC8FC\uBC29 \uCD9C\uB825\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uAC00 \uC788\uC73C\uBA74 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uBC14\uAFD4 \uB4F1\uB85D\uD574 \uBC14\uB85C \uC501\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAC04\uC774 \uAE38\uC5B4\uC9C0\uBA74 \uC5C5\uCCB4\uC5D0 \uAE30\uAC04\uC744 \uB2E4\uC2DC \uD655\uC778\uD558\uACE0 \uAE30\uB85D\uD574 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uC0C8 \uAE30\uAE30\uC5D0\uC11C \uC8FC\uBB38\xB7\uACB0\uC81C\xB7\uD638\uCD9C\uC744 \uD55C \uBC88\uC529 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAE30\uB294 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB2E4\uC2DC \uB4F1\uB85D\uD574\uC57C \uD558\uBBC0\uB85C \uB4F1\uB85D \uB4A4 \uC8FC\uBB38 \uD55C \uBC88\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAC04\uC774 \uC57D\uC815\uC11C \uC870\uAC74\uBCF4\uB2E4 \uAE38\uC5B4\uC9C0\uBA74 \uAE30\uB85D\uC744 \uADFC\uAC70\uB85C \uC5C5\uCCB4\uC5D0 \uC870\uCE58\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uC5D0\uB294 \uBBF8\uB9AC \uD504\uB85C\uADF8\uB7A8\uC744 \uAE54\uC544 \uB450\uACE0 \uD14C\uC774\uBE14 \uBC88\uD638\uB9CC \uBC14\uAFB8\uBA74 \uB418\uAC8C \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAE30 \uB3C4\uCC29 \uC804\uAE4C\uC9C0\uC758 \uAE30\uAC04\uC740 \uC57D\uC815\uC11C \uC870\uAC74\uACFC \uBE44\uAD50\uD574 \uAE30\uB85D\uD574 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uCCAB \uC601\uC5C5\uC77C\uC5D0 \uADF8 \uD14C\uC774\uBE14 \uC8FC\uBB38\uC774 \uC8FC\uBC29\uC5D0 \uC815\uC0C1 \uCD9C\uB825\uB418\uB294\uC9C0 \uD55C \uBC88 \uB354 \uBD05\uB2C8\uB2E4.", "\uB9C8\uAC10 \uB54C \uAE30\uAE30 \uC218\uB97C \uC138\uB294 \uD56D\uBAA9\uC744 \uB9C8\uAC10\uD45C\uC5D0 \uB123\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uC2E0\uACE0\uC640 \uAD50\uCCB4\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uD30C\uC190\uC740 \uC0AC\uC9C4, \uBD84\uC2E4\uC740 \uAE30\uAE30 \uC7A0\uAE08\uC744 \uBA3C\uC800 \uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC758 \uD30C\uC190\xB7\uBD84\uC2E4 \uC870\uD56D\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5C5\uCCB4\uC5D0 \uAE00\uB85C \uC2E0\uACE0\uD558\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAE30\uB97C \uBC1B\uC544 \uD14C\uC774\uBE14 \uBC88\uD638\uB97C \uB4F1\uB85D\uD558\uACE0 \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uC6D0\uC778\uC744 \uC801\uC5B4 \uC608\uBC29 \uC7A5\uBE44\uB098 \uBC30\uCE58\uB97C \uBC14\uAFC9\uB2C8\uB2E4."] }, "table": { "caption": "\uD30C\uC190\xB7\uBD84\uC2E4 \uCC98\uB9AC \uBE44\uAD50", "head": ["\uC0C1\uD669", "\uCCAB \uC870\uCE58", "\uBE44\uC6A9"], "rows": [["\uD30C\uC190(\uC791\uB3D9\uD568)", "\uC0AC\uC9C4\xB7\uC784\uC2DC \uC0AC\uC6A9", "\uC57D\uC815 \uC870\uD56D"], ["\uD30C\uC190(\uC791\uB3D9 \uC548 \uD568)", "\uC0AC\uC9C4\xB7\uAD50\uCCB4 \uC2E0\uCCAD", "\uC57D\uC815 \uC870\uD56D"], ["\uBD84\uC2E4", "\uAE30\uAE30 \uC7A0\uAE08\xB7\uC2E0\uACE0", "\uBD84\uC2E4 \uC870\uD56D"], ["\uBCF4\uD5D8 \uD3EC\uD568", "\uBCF4\uD5D8 \uC811\uC218", "\uC790\uAE30\uBD80\uB2F4 \uD655\uC778"]] }, "faq": [["\uC190\uB2D8\uC774 \uAE68\uB728\uB9AC\uBA74 \uC190\uB2D8\uC5D0\uAC8C \uCCAD\uAD6C\uD558\uB098\uC694?", "\uB9E4\uC7A5 \uD310\uB2E8\uC785\uB2C8\uB2E4. \uC5C5\uCCB4\uC640\uC758 \uBE44\uC6A9\uC740 \uC57D\uC815 \uC870\uD56D\uC5D0 \uB530\uB985\uB2C8\uB2E4."], ["\uAD50\uCCB4\uAE4C\uC9C0 \uBA70\uCE60 \uAC78\uB9AC\uB098\uC694?", "\uC57D\uC815\uC11C\uC758 \uAD50\uCCB4 \uAE30\uAC04 \uC870\uAC74\uC5D0 \uB530\uB974\uBA70, \uC5C6\uC73C\uBA74 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBD84\uC2E4 \uAE30\uAE30\uB85C \uACB0\uC81C\uAC00 \uB420 \uC218 \uC788\uB098\uC694?", "\uC7A0\uADF8\uC9C0 \uC54A\uC73C\uBA74 \uAC00\uB2A5\uD558\uBBC0\uB85C \uC7A0\uAE08\uC774 \uCCAB \uC870\uCE58\uC785\uB2C8\uB2E4."], ["\uC608\uBE44 \uAE30\uAE30\uB97C \uB450\uB294 \uAC8C \uB098\uC740\uAC00\uC694?", "\uD30C\uC190\uC774 \uC7A6\uAC70\uB098 \uC88C\uC11D\uC774 \uB9CE\uC740 \uB9E4\uC7A5\uC740 \uD55C \uB300 \uB450\uB294 \uD3B8\uC774 \uC601\uC5C5 \uACF5\uBC31\uC744 \uC904\uC785\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC784\uB300\uC57D\uC815", "\uD14C\uC774\uBE14\uC624\uB354\uD574\uC9C0\uC704\uC57D\uAE08", "\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uD14C\uC774\uBE14\uC624\uB354\uC18C\uADDC\uBAA8\uB9E4\uC7A5", "product": "\uD14C\uC774\uBE14\uC624\uB354", "tail": "\uC18C\uADDC\uBAA8 \uB9E4\uC7A5", "title": "\uC791\uC740 \uC2DD\uB2F9\uB3C4 \uD14C\uC774\uBE14\uC624\uB354\uB97C \uB458 \uC218 \uC788\uB098\uC694? \u2014 \uC88C\uC11D \uBA87 \uAC1C\uBD80\uD130 \uD6A8\uACFC\uAC00 \uB098\uB294\uC9C0", "desc": "\uC88C\uC11D\uC774 \uC801\uC740 \uC2DD\uB2F9\uC5D0\uC11C \uD14C\uC774\uBE14\uC624\uB354\uB97C \uB458 \uB54C \uB300\uC218 \uC0B0\uC815, \uC640\uC774\uD30C\uC774\uC640 \uC804\uC6D0, \uC6D4 \uBE44\uC6A9 \uB300\uBE44 \uD6A8\uACFC, \uC77C\uBD80 \uC88C\uC11D\uB9CC \uB450\uB294 \uBC29\uC2DD, \uD0A4\uC624\uC2A4\uD06C\uC640\uC758 \uC120\uD0DD, \uD63C\uC790 \uC6B4\uC601\uD558\uB294 \uB9E4\uC7A5\uC5D0\uC11C \uB2EC\uB77C\uC9C0\uB294 \uC810\uACFC \uB3C4\uC785 \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uC791\uC740 \uC2DD\uB2F9\uB3C4 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uACE0 \uC9C1\uC6D0\uC774 \uC8FC\uBB38\uC744 \uBC1B\uAE30 \uC5B4\uB824\uC6B4 \uC2DC\uAC04\uB300\uAC00 \uC788\uC73C\uBA74 \uD14C\uC774\uBE14\uC624\uB354\uAC00 \uB9DE\uACE0, \uC88C\uC11D \uC218\uAC00 \uC801\uC5B4 \uB300\uC218\uAC00 \uC801\uC740 \uB9CC\uD07C \uC6D4 \uBE44\uC6A9\uB3C4 \uC791\uC2B5\uB2C8\uB2E4. \uBAA8\uB4E0 \uC88C\uC11D\uC5D0 \uB450\uC9C0 \uC54A\uACE0 \uCD94\uAC00 \uC8FC\uBB38\uC774 \uB9CE\uC740 \uD14C\uC774\uBE14\uBD80\uD130 \uB450\uBA74 \uBE44\uC6A9\uC744 \uB354 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "sections": [{ "h": "\uC5B4\uB5A4 \uC791\uC740 \uB9E4\uC7A5\uC5D0 \uB9DE\uB098\uC694?", "p": ["\uC9C1\uC6D0 \uD55C\uB450 \uBA85\uC774 \uC11C\uBE59\uACFC \uC8FC\uBC29\uC744 \uAC19\uC774 \uBCF4\uB294 \uB9E4\uC7A5\uC5D0\uC11C \uC8FC\uBB38 \uBC1B\uB294 \uC2DC\uAC04\uC744 \uB35C\uC5B4 \uC90D\uB2C8\uB2E4.", "\uACE0\uAE43\uC9D1\uC774\uB098 \uC8FC\uC810\uCC98\uB7FC \uC790\uB9AC\uC5D0\uC11C \uCD94\uAC00 \uC8FC\uBB38\uC774 \uC7A6\uC740 \uC5C5\uC885\uC740 \uC88C\uC11D\uC774 \uC801\uC5B4\uB3C4 \uD6A8\uACFC\uAC00 \uB0A9\uB2C8\uB2E4.", "\uB2E8\uD488\uC744 \uD55C \uBC88 \uC8FC\uBB38\uD558\uB294 \uB9E4\uC7A5\uC740 \uD6A8\uACFC\uAC00 \uC791\uC544 \uD0A4\uC624\uC2A4\uD06C\uB098 \uCE74\uC6B4\uD130 \uC8FC\uBB38\uC774 \uB098\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uC624\uB798 \uBA38\uBB34\uB294 \uB9E4\uC7A5\uC740 \uD638\uCD9C \uAE30\uB2A5\uC73C\uB85C \uC9C1\uC6D0 \uB3D9\uC120\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uBA87 \uAC1C\uB4E0 \uC640\uC774\uD30C\uC774\uAC00 \uBAA8\uB4E0 \uC790\uB9AC\uC5D0 \uB2FF\uB294\uC9C0\uAC00 \uC804\uC81C\uC785\uB2C8\uB2E4.", "\uD6A8\uACFC\uB97C \uAC00\uB2A0\uD558\uB824\uBA74 \uC77C\uC8FC\uC77C \uB3D9\uC548 \uD14C\uC774\uBE14\uB2F9 \uCD94\uAC00 \uC8FC\uBB38 \uD69F\uC218\uB97C \uC801\uC5B4 \uBD05\uB2C8\uB2E4.", "\uD6A8\uACFC\uAC00 \uC560\uB9E4\uD558\uBA74 \uD14C\uC774\uBE14 \uB450\uC138 \uACF3\uC5D0\uB9CC \uB450\uACE0 \uC2DC\uC791\uD569\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uC801\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uD55C \uB300\uAC00 \uBA48\uCDB0\uB3C4 \uC601\uD5A5\uC774 \uD06C\uBBC0\uB85C \uAD50\uCCB4 \uC870\uAC74\uC744 \uB354 \uAF3C\uAF3C\uD788 \uBD05\uB2C8\uB2E4.", "\uD6A8\uACFC\uB97C \uAC00\uB2A0\uD560 \uB54C\uB294 \uD14C\uC774\uBE14\uB2F9 \uCD94\uAC00 \uC8FC\uBB38 \uD69F\uC218\uBFD0 \uC544\uB2C8\uB77C \uC9C1\uC6D0\uC774 \uC8FC\uBB38 \uBC1B\uC73C\uB7EC \uAC04 \uD69F\uC218\uB3C4 \uAC19\uC774 \uC149\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uC624\uB798 \uBA38\uBB34\uB294 \uB9E4\uC7A5\uC740 \uD638\uCD9C \uD69F\uC218\uAC00 \uB9CE\uC544 \uAE30\uAE30\uB85C \uBC1B\uB294 \uD6A8\uACFC\uAC00 \uCEE4\uC9D1\uB2C8\uB2E4.", "\uD6A8\uACFC\uAC00 \uD655\uC778\uB418\uBA74 \uBA54\uB274 \uC0AC\uC9C4\uACFC \uC124\uBA85\uC744 \uBCF4\uAC15\uD574 \uAE30\uAE30\uC5D0\uC11C \uACE0\uB974\uB294 \uC2DC\uAC04\uC744 \uC904\uC785\uB2C8\uB2E4.", "\uC88C\uC11D\uC774 \uC801\uC740 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uD55C \uB300\uC758 \uD6A8\uACFC\uAC00 \uC804\uCCB4 \uB9E4\uCD9C\uC5D0 \uBC14\uB85C \uBCF4\uC774\uBBC0\uB85C \uCCAB \uB2EC \uBE44\uAD50\uAC00 \uC27D\uC2B5\uB2C8\uB2E4."] }, { "h": "\uB300\uC218\uC640 \uBE44\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uC815\uD558\uB098\uC694?", "p": ["\uCD94\uAC00 \uC8FC\uBB38\uC774 \uB9CE\uC740 \uD14C\uC774\uBE14\uBD80\uD130 \uAE30\uAE30\uB97C \uB450\uACE0 \uB098\uBA38\uC9C0\uB294 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uB461\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uC801\uC73C\uBA74 \uB300\uB2F9 \uC774\uC6A9\uB8CC \uD569\uACC4\uB3C4 \uC801\uC9C0\uB9CC, \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uB9E4\uC7A5 \uB2E8\uC704\uBA74 \uADF8 \uBD80\uBD84\uC740 \uAC19\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC640\uC774\uD30C\uC774\uB97C \uC4F0\uBA74 \uD1B5\uC2E0\uBE44\uAC00 \uBE60\uC9C0\uBBC0\uB85C \uACF5\uC720\uAE30 \uC704\uCE58\uB97C \uBA3C\uC800 \uC810\uAC80\uD569\uB2C8\uB2E4.", "\uAC70\uCE58\uB300\uC640 \uCF00\uC774\uC2A4\uB294 \uB300\uC218\uB9CC\uD07C \uD544\uC694\uD558\uBBC0\uB85C \uCC98\uC74C \uAD6C\uC131\uC5D0 \uB123\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9\uC740 \uB9E4\uC7A5 \uADDC\uBAA8\uC640 \uBB34\uAD00\uD558\uAC8C \uC8FC\uBC29 \uCD9C\uB825\uACFC \uB9E4\uCD9C \uD1B5\uD569\uC5D0 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uAD6C\uC131\uACFC \uAE08\uC561\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCD94\uAC00 \uC8FC\uBB38\uC774 \uB9CE\uC740 \uD14C\uC774\uBE14\uBD80\uD130 \uB450\uBA74 \uD6A8\uACFC\uAC00 \uBA3C\uC800 \uBCF4\uC774\uACE0, \uD6A8\uACFC\uAC00 \uD655\uC778\uB418\uBA74 \uB098\uBA38\uC9C0 \uC88C\uC11D\uC5D0 \uB298\uB9BD\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uC801\uC5B4\uB3C4 \uAC70\uCE58\uB300\uC640 \uCF00\uC774\uC2A4\uB294 \uAF2D \uB123\uC5B4 \uD30C\uC190 \uAD50\uCCB4\uB97C \uC904\uC785\uB2C8\uB2E4.", "\uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uAC00 \uB9E4\uC7A5 \uB2E8\uC704\uBA74 \uB300\uC218\uB97C \uC904\uC5EC\uB3C4 \uADF8 \uBD80\uBD84\uC740 \uAC19\uC73C\uBBC0\uB85C \uC6D4 \uBE44\uC6A9 \uD45C\uC5D0\uC11C \uAD6C\uBD84\uD574 \uB461\uB2C8\uB2E4.", "\uAC70\uCE58\uB300\uC640 \uCF00\uC774\uC2A4\uB294 \uB300\uC218\uC5D0 \uBE44\uB840\uD558\uBBC0\uB85C \uC18C\uADDC\uBAA8 \uB9E4\uC7A5\uC740 \uADF8 \uBE44\uC6A9\uC774 \uC791\uC2B5\uB2C8\uB2E4."] }, { "h": "\uD63C\uC790 \uC6B4\uC601\uD558\uBA74 \uBB34\uC5C7\uC774 \uB2EC\uB77C\uC9C0\uB098\uC694?", "p": ["\uC8FC\uBB38\uC744 \uBC1B\uC73C\uB7EC \uAC00\uC9C0 \uC54A\uC544\uB3C4 \uB418\uBBC0\uB85C \uC870\uB9AC \uC911\uC5D0 \uC8FC\uBB38\uC774 \uB4E4\uC5B4\uC635\uB2C8\uB2E4.", "\uACB0\uC81C\uB97C \uC790\uB9AC\uC5D0\uC11C \uBC1B\uC73C\uBA74 \uC870\uB9AC\uB97C \uBA48\uCD94\uACE0 \uACC4\uC0B0\uB300\uB85C \uAC00\uB294 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uAE30 \uACE0\uC7A5 \uB54C \uB300\uC751\uC774 \uC5B4\uB824\uC6B0\uBBC0\uB85C \uC6D0\uACA9 \uC9C0\uC6D0\uC774 \uD3EC\uD568\uB41C \uC57D\uC815\uC774 \uD3B8\uD569\uB2C8\uB2E4.", "\uC190\uB2D8 \uC548\uB0B4\uB97C \uD560 \uC0AC\uB78C\uC774 \uC5C6\uC73C\uB2C8 \uD654\uBA74 \uC548\uB0B4 \uBB38\uAD6C\uC640 \uD14C\uC774\uBE14 \uC548\uB0B4\uD310\uC744 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC\uAE4C\uC9C0 \uACB8\uD558\uBA74 \uBC30\uB2EC\uC571 \uC5F0\uB3D9\uC73C\uB85C \uC8FC\uBB38 \uD654\uBA74\uC744 \uD558\uB098\uB85C \uBAA8\uC74D\uB2C8\uB2E4.", "\uD63C\uC790 \uC6B4\uC601\uD558\uB294 \uB9E4\uC7A5\uC740 \uD638\uCD9C \uAE30\uB2A5\uC744 \uCF1C \uB450\uBA74 \uC190\uB2D8\uC774 \uAE30\uB2E4\uB9AC\uB294 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uC6D0\uACA9 \uC9C0\uC6D0 \uC2DC\uAC04\uC774 \uC601\uC5C5 \uC2DC\uAC04\uACFC \uB9DE\uB294\uC9C0 \uD655\uC778\uD574\uC57C \uC800\uB141 \uC7A5\uC0AC \uC911 \uACE0\uC7A5\uC5D0 \uB300\uC751\uB429\uB2C8\uB2E4.", "\uD63C\uC790 \uC6B4\uC601\uD558\uBA74 \uAE30\uAE30 \uACE0\uC7A5 \uB54C \uC190\uB2D8 \uC751\uB300\uC640 \uC5C5\uCCB4 \uC5F0\uB77D\uC744 \uAC19\uC774 \uD574\uC57C \uD558\uBBC0\uB85C \uACE0\uAC1D\uC13C\uD130 \uBC88\uD638\uB97C \uB208\uC5D0 \uB744\uAC8C \uB461\uB2C8\uB2E4.", "\uBC30\uB2EC \uACB8\uC5C5 \uB9E4\uC7A5\uC740 \uBC30\uB2EC\uC571 \uC5F0\uB3D9\uC744 \uCC98\uC74C\uBD80\uD130 \uB123\uC5B4\uC57C \uC8FC\uBB38 \uD654\uBA74\uC774 \uB458\uB85C \uB098\uB258\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uD0A4\uC624\uC2A4\uD06C\uC640 \uC5B4\uB290 \uCABD\uC744 \uACE0\uB974\uB098\uC694?", "p": ["\uD3EC\uC7A5 \uC190\uB2D8\uC774 \uB9CE\uACE0 \uD55C \uBC88 \uC8FC\uBB38\uD558\uBA74 \uB05D\uB098\uB294 \uB9E4\uC7A5\uC740 \uD0A4\uC624\uC2A4\uD06C \uD55C \uB300\uAC00 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uC549\uC544\uC11C \uCD94\uAC00 \uC8FC\uBB38\uD558\uB294 \uB9E4\uC7A5\uC740 \uC88C\uC11D \uC218\uAC00 \uC801\uC5B4\uB3C4 \uD14C\uC774\uBE14\uC624\uB354\uAC00 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uB458 \uB2E4 \uC560\uB9E4\uD558\uBA74 \uC190\uB2D8\uC774 \uC8FC\uBB38\uD558\uB294 \uC790\uB9AC\uAC00 \uC785\uAD6C\uC778\uC9C0 \uC88C\uC11D\uC778\uC9C0\uB85C \uAC00\uB985\uB2C8\uB2E4.", "\uCC98\uC74C \uD55C \uAC00\uC9C0\uB97C \uB450\uACE0 \uB3D9\uC120\uC744 \uBCF8 \uB4A4 \uBC14\uAFB8\uAC70\uB098 \uCD94\uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC7A5 \uC190\uB2D8\uC774 \uB298\uC5B4\uB098\uB294 \uCD94\uC138\uB77C\uBA74 \uD0A4\uC624\uC2A4\uD06C \uCD94\uAC00\uB97C \uB2E4\uC74C \uB2E8\uACC4\uB85C \uB450\uACE0 \uD14C\uC774\uBE14\uC624\uB354\uBD80\uD130 \uC2DC\uC791\uD569\uB2C8\uB2E4.", "\uB3D9\uC120 \uD310\uB2E8\uC774 \uC5B4\uB824\uC6B0\uBA74 \uC190\uB2D8\uC5D0\uAC8C \uC5B4\uB514\uC11C \uC8FC\uBB38\uD558\uACE0 \uC2F6\uC740\uC9C0 \uBB3C\uC5B4\uBCF4\uB294 \uAC83\uB3C4 \uBC29\uBC95\uC785\uB2C8\uB2E4.", "\uB3D9\uC120 \uD310\uB2E8\uC740 \uC190\uB2D8\uC774 \uC790\uB9AC\uC5D0 \uC549\uC740 \uB4A4 \uBA54\uB274\uD310\uC744 \uCC3E\uB294\uC9C0, \uC785\uAD6C\uC5D0\uC11C \uC8FC\uBB38\uD558\uB824 \uD558\uB294\uC9C0\uB85C\uB3C4 \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC190\uB2D8 \uB3D9\uC120\uC744 \uBC14\uAFC0 \uC218 \uC5C6\uB294 \uB9E4\uC7A5\uC740 \uAE30\uAE30 \uC704\uCE58\uB97C \uB3D9\uC120\uC5D0 \uB9DE\uCD94\uB294 \uCABD\uC774 \uAC04\uB2E8\uD569\uB2C8\uB2E4.", "\uD6A8\uACFC\uAC00 \uD655\uC778\uB418\uBA74 \uB098\uBA38\uC9C0 \uC88C\uC11D\uC73C\uB85C \uB298\uB9BD\uB2C8\uB2E4."] }], "steps": { "h": "\uB3C4\uC785 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD14C\uC774\uBE14\uB2F9 \uCD94\uAC00 \uC8FC\uBB38 \uD69F\uC218\uB97C \uC77C\uC8FC\uC77C \uC801\uC2B5\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774\uC640 \uC804\uC6D0\uC774 \uB2FF\uB294 \uC88C\uC11D\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCD94\uAC00 \uC8FC\uBB38\uC774 \uB9CE\uC740 \uD14C\uC774\uBE14\uBD80\uD130 \uB300\uC218\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uD3EC\uC2A4 \uC5F0\uB3D9\uACFC \uD544\uC694\uD55C \uAE30\uB2A5\uB9CC \uB123\uC5B4 \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uB4A4 \uC190\uB2D8 \uBC18\uC751\uC744 \uBCF4\uACE0 \uB300\uC218\uB97C \uC870\uC815\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uC18C\uADDC\uBAA8 \uB9E4\uC7A5 \uAD6C\uC131 \uC608", "head": ["\uC88C\uC11D \uC0C1\uD669", "\uAD8C\uC7A5 \uAD6C\uC131", "\uBE44\uACE0"], "rows": [["4~6\uC11D\xB7\uCD94\uAC00 \uC8FC\uBB38 \uC7A6\uC74C", "\uC804 \uC88C\uC11D", "\uB300\uC218 \uC801\uC5B4 \uC6D4 \uBE44\uC6A9 \uC791\uC74C"], ["8~10\uC11D\xB7\uC77C\uBD80\uB9CC \uC624\uB798 \uBA38\uBB3E", "\uCD94\uAC00 \uC8FC\uBB38 \uB9CE\uC740 \uC88C\uC11D\uB9CC", "\uB098\uBA38\uC9C0 \uC9C1\uC6D0 \uC8FC\uBB38"], ["\uD3EC\uC7A5 \uC704\uC8FC", "\uD0A4\uC624\uC2A4\uD06C 1\uB300", "\uD14C\uC774\uBE14\uC624\uB354\uBCF4\uB2E4 \uC801\uD569"], ["\uD63C\uC790 \uC6B4\uC601", "\uC804 \uC88C\uC11D+\uC6D0\uACA9 \uC9C0\uC6D0", "\uC548\uB0B4 \uBB38\uAD6C \uC900\uBE44"]] }, "faq": [["\uC88C\uC11D\uC774 \uBA87 \uAC1C \uC774\uC0C1\uC774\uC5B4\uC57C \uD558\uB098\uC694?", "\uC815\uD574\uC9C4 \uAE30\uC900\uC740 \uC5C6\uC2B5\uB2C8\uB2E4. \uCD94\uAC00 \uC8FC\uBB38 \uBE48\uB3C4\uAC00 \uAE30\uC900\uC774\uBA70 \uB450\uC138 \uD14C\uC774\uBE14\uBD80\uD130 \uC2DC\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC791\uC740 \uB9E4\uC7A5\uC740 \uC6D4 \uBE44\uC6A9\uC774 \uB354 \uC2FC\uAC00\uC694?", "\uB300\uC218\uAC00 \uC801\uC5B4 \uAE30\uAE30 \uC774\uC6A9\uB8CC\uB294 \uC801\uC9C0\uB9CC \uD504\uB85C\uADF8\uB7A8 \uC0AC\uC6A9\uB8CC\uB294 \uB9E4\uC7A5 \uB2E8\uC704\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAD6C\uC131\uC73C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uD63C\uC790 \uC6B4\uC601\uD558\uB294\uB370 \uACE0\uC7A5 \uB098\uBA74\uC694?", "\uC6D0\uACA9 \uC9C0\uC6D0\uACFC \uAD50\uCCB4 \uC870\uAC74\uC774 \uD3EC\uD568\uB41C \uC57D\uC815\uC744 \uACE0\uB974\uACE0, \uAD50\uCCB4 \uAE30\uAC04\uC5D4 \uC9C1\uC6D0 \uC8FC\uBB38\uC73C\uB85C \uC6B4\uC601\uD569\uB2C8\uB2E4."], ["\uB098\uC911\uC5D0 \uC88C\uC11D\uC744 \uB298\uB9AC\uBA74\uC694?", "\uB300\uC218 \uCD94\uAC00 \uC870\uAC74\uC5D0 \uB530\uB77C \uAC19\uC740 \uC57D\uC815\uC73C\uB85C \uBD99\uAC70\uB098 \uC0C8 \uC57D\uC815\uC774 \uB429\uB2C8\uB2E4. \uACC4\uC57D \uB54C \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uD14C\uC774\uBE14\uC624\uB354\uC6D4\uBE44\uC6A9", "\uD0A4\uC624\uC2A4\uD06C\uD14C\uC774\uBE14\uC624\uB354\uBE44\uAD50", "\uD14C\uC774\uBE14\uC624\uB354\uC2DD\uB2F9\uB3C4\uC785\uD6A8\uACFC"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uBC30\uB2EC\uC6A9", "title": "\uBC30\uB2EC\uC6A9 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB294 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uACE0\uB974\uB098\uC694? \u2014 \uD1B5\uC2E0\xB7\uBC30\uD130\uB9AC\xB7\uC601\uC218\uC99D\uC758 \uC138 \uAC00\uC9C0", "desc": "\uBC30\uB2EC \uAE30\uC0AC\uAC00 \uB4E4\uACE0 \uB098\uAC00\uB294 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uACE0\uB97C \uB54C LTE\uC640 \uBE14\uB8E8\uD22C\uC2A4 \uD1B5\uC2E0 \uBC29\uC2DD, \uBC30\uD130\uB9AC \uC0AC\uC6A9 \uC2DC\uAC04\uACFC \uCDA9\uC804 \uBC29\uC2DD, \uC601\uC218\uC99D \uCD9C\uB825 \uBC29\uC2DD, \uD06C\uAE30\uC640 \uBB34\uAC8C, \uBD84\uC2E4\xB7\uD30C\uC190 \uC870\uAC74\uC744 \uC5B4\uB5BB\uAC8C \uB530\uC9C0\uB294\uC9C0\uC640 \uBC30\uB2EC \uAC74\uC218\uC5D0 \uB530\uB978 \uB300\uC218 \uC0B0\uC815, \uAE30\uC0AC \uAD50\uB300 \uB54C \uAD00\uB9AC \uADDC\uCE59\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBC30\uB2EC\uC6A9 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB294 LTE \uD1B5\uC2E0\uC73C\uB85C \uC2A4\uB9C8\uD2B8\uD3F0 \uC5C6\uC774 \uB2E8\uB3C5 \uACB0\uC81C\uAC00 \uB418\uACE0 \uD558\uB8E8 \uBC30\uB2EC\uC744 \uBC84\uD2F0\uB294 \uBC30\uD130\uB9AC\uC5D0 \uC601\uC218\uC99D \uBC29\uC2DD\uC774 \uB9E4\uC7A5 \uC5C5\uC885\uC5D0 \uB9DE\uB294 \uAE30\uAE30\uAC00 \uAE30\uBCF8\uC774\uBA70, \uB300\uC218\uB294 \uAC19\uC740 \uC2DC\uAC04\uC5D0 \uB098\uAC00\uB294 \uAE30\uC0AC \uC218\uB85C \uC815\uD569\uB2C8\uB2E4. \uAE30\uAE30\uAC12\uACFC \uD1B5\uC2E0 \uC694\uAE08\uC740 \uBAA8\uB378\uACFC \uC57D\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uACE0, \uBD84\uC2E4\xB7\uD30C\uC190 \uC870\uAC74\uC740 \uB9E4\uC7A5 \uBC16\uC5D0\uC11C \uC4F0\uB294 \uAE30\uAE30\uB77C \uC57D\uC815\uC11C\uC5D0\uC11C \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uD1B5\uC2E0 \uBC29\uC2DD\uC740 \uBB34\uC5C7\uC744 \uACE0\uB974\uB098\uC694?", "p": ["LTE \uBC29\uC2DD\uC740 \uAE30\uAE30 \uC548\uC5D0 \uC720\uC2EC\uC774 \uB4E4\uC5B4\uAC00 \uC2A4\uB9C8\uD2B8\uD3F0 \uC5C6\uC774 \uC5B4\uB514\uC11C\uB098 \uACB0\uC81C\uAC00 \uB418\uBBC0\uB85C \uBC30\uB2EC \uAE30\uC0AC\uAC00 \uBC14\uB00C\uC5B4\uB3C4 \uC124\uC815\uC774 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uAE30\uC0AC \uC2A4\uB9C8\uD2B8\uD3F0\uACFC \uC9DD\uC744 \uC774\uB904 \uACB0\uC81C\uD558\uBBC0\uB85C \uAE30\uC0AC\uB9C8\uB2E4 \uC571 \uC124\uCE58\uC640 \uC5F0\uACB0 \uC124\uC815\uC774 \uD544\uC694\uD558\uACE0, \uAE30\uC0AC\uAC00 \uC790\uC8FC \uBC14\uB00C\uB294 \uB9E4\uC7A5\uC5D0\uB294 \uBC88\uAC70\uB86D\uC2B5\uB2C8\uB2E4.", "\uC640\uC774\uD30C\uC774 \uBC29\uC2DD\uC740 \uB9E4\uC7A5 \uC548\uC5D0\uC11C\uB9CC \uC4F8 \uC218 \uC788\uC5B4 \uBC30\uB2EC\uC6A9\uC73C\uB85C\uB294 \uB9DE\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "LTE \uBC29\uC2DD\uC740 \uB300\uB2F9 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB9E4\uB2EC \uB098\uAC00\uBBC0\uB85C \uB300\uC218\uB97C \uC815\uD560 \uB54C \uC6D4 \uBE44\uC6A9\uC5D0 \uB123\uC2B5\uB2C8\uB2E4.", "\uD1B5\uC2E0\uC774 \uC57D\uD55C \uC9C0\uD558 \uC0C1\uAC00\uB098 \uC2E0\uCD95 \uC544\uD30C\uD2B8 \uBC30\uB2EC\uC774 \uB9CE\uC73C\uBA74 \uAE30\uC0AC\uC5D0\uAC8C \uACB0\uC81C \uC704\uCE58\uB97C \uC870\uAE08 \uC62E\uAE30\uB3C4\uB85D \uC54C\uB824 \uB461\uB2C8\uB2E4.", "\uD1B5\uC2E0\uC0AC \uBCC0\uACBD\uC774 \uAC00\uB2A5\uD55C \uAE30\uAE30\uC778\uC9C0\uB3C4 \uD655\uC778\uD558\uBA74 \uD2B9\uC815 \uC9C0\uC5ED \uC2E0\uD638 \uBB38\uC81C\uC5D0 \uB300\uC751\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uACB0\uC81C \uC2B9\uC778 \uC18D\uB3C4\uAC00 \uCCB4\uAC10\uB420 \uB9CC\uD07C \uB2E4\uB974\uC9C0\uB294 \uC54A\uC73C\uBBC0\uB85C \uC6B4\uC601 \uD3B8\uC758\uB85C \uACE0\uB985\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB294 \uD1B5\uC2E0\uC0AC \uC804\uD30C\uAC00 \uB2FF\uB294 \uACF3\uC774\uBA74 \uB418\uBBC0\uB85C \uBC30\uB2EC \uBC18\uACBD\uC774 \uB113\uC740 \uB9E4\uC7A5\uC5D0 \uD2B9\uD788 \uB9DE\uC2B5\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB3C4 \uC9C0\uD558 \uC8FC\uCC28\uC7A5\uC774\uB098 \uC5D8\uB9AC\uBCA0\uC774\uD130 \uC548\uC5D0\uC11C\uB294 \uC2E0\uD638\uAC00 \uC57D\uD574 \uACB0\uC81C\uB97C \uBC16\uC5D0\uC11C \uD558\uB3C4\uB85D \uC548\uB0B4\uD569\uB2C8\uB2E4."] }, { "h": "\uBC30\uD130\uB9AC\uC640 \uC601\uC218\uC99D\uC740 \uC5B4\uB5BB\uAC8C \uBCF4\uB098\uC694?", "p": ["\uD558\uB8E8 \uBC30\uB2EC \uAC74\uC218\uC640 \uC6B4\uD589 \uC2DC\uAC04\uC744 \uAE30\uC900\uC73C\uB85C \uBC30\uD130\uB9AC \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uCDA9\uBD84\uD55C\uC9C0 \uBCF4\uACE0, \uBD80\uC871\uD558\uBA74 \uC608\uBE44 \uBC30\uD130\uB9AC\uB098 \uCC28\uB7C9 \uCDA9\uC804 \uBC29\uC2DD\uC744 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uAC70\uCE58\uB300 \uCDA9\uC804\uC2DD\uC740 \uAE30\uC0AC\uAC00 \uB3CC\uC544\uC62C \uB54C\uB9C8\uB2E4 \uAF42\uC544 \uB450\uBA74 \uB418\uACE0, \uCF00\uC774\uBE14 \uCDA9\uC804\uC2DD\uC740 \uCF00\uC774\uBE14 \uBD84\uC2E4\uC774 \uC7A6\uC544 \uC5EC\uBD84\uC744 \uB461\uB2C8\uB2E4.", "\uC601\uC218\uC99D\uC744 \uBC18\uB4DC\uC2DC \uC918\uC57C \uD558\uB294 \uC5C5\uC885\uC740 \uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC744 \uACE0\uB974\uACE0, \uC544\uB2C8\uBA74 \uBB38\uC790\uB098 \uC571\uC73C\uB85C \uBCF4\uB0B4\uB294 \uC804\uC790 \uC601\uC218\uC99D \uAE30\uAE30\uAC00 \uAC00\uBCCD\uC2B5\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC740 \uC6A9\uC9C0\uAC00 \uB5A8\uC5B4\uC9C0\uBA74 \uACB0\uC81C\uAC00 \uB9C9\uD790 \uC218 \uC788\uC5B4 \uAE30\uC0AC \uAC00\uBC29\uC5D0 \uC5EC\uBD84 \uC6A9\uC9C0\uB97C \uB123\uC5B4 \uB461\uB2C8\uB2E4.", "\uACA8\uC6B8\uCCA0 \uC800\uC628\uC5D0\uC11C \uBC30\uD130\uB9AC\uAC00 \uBE68\uB9AC \uB2F3\uC73C\uBBC0\uB85C \uBCF4\uC628 \uD30C\uC6B0\uCE58\uB97C \uC4F0\uB294 \uB9E4\uC7A5\uB3C4 \uC788\uC2B5\uB2C8\uB2E4.", "\uBC30\uD130\uB9AC \uAD50\uCCB4\uAC00 \uB418\uB294 \uBAA8\uB378\uC778\uC9C0, \uB0B4\uC7A5\uD615\uC774\uBA74 \uAD50\uCCB4 \uBE44\uC6A9\uC774 \uC5BC\uB9C8\uC778\uC9C0\uB294 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uC6A9\uC9C0 \uADDC\uACA9\uC744 \uAE30\uC0AC \uAC00\uBC29 \uC548 \uBA54\uBAA8\uC5D0 \uC801\uC5B4 \uB450\uBA74 \uC678\uBD80\uC5D0\uC11C \uAE09\uD788 \uC0B4 \uB54C \uD2C0\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC740 \uC6A9\uC9C0 \uAD50\uCCB4 \uBC29\uBC95\uC744 \uAE30\uC0AC \uAD50\uC721\uC5D0 \uB123\uC5B4\uC57C \uD604\uC7A5\uC5D0\uC11C \uB2F9\uD669\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uB300\uC218\uB294 \uC5B4\uB5BB\uAC8C \uC815\uD558\uB098\uC694?", "p": ["\uAC19\uC740 \uC2DC\uAC04\uC5D0 \uB098\uAC00\uB294 \uAE30\uC0AC \uC218\uAC00 \uAE30\uAE30 \uB300\uC218\uC758 \uAE30\uC900\uC774\uBA70, \uD53C\uD06C \uC2DC\uAC04 \uAE30\uC0AC \uC218\uB97C \uC149\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C \uBE44\uC911\uC774 \uB0AE\uC73C\uBA74 \uAE30\uAE30 \uD55C \uB300\uB97C \uACF5\uC6A9\uC73C\uB85C \uB450\uACE0 \uD604\uC7A5 \uACB0\uC81C \uC8FC\uBB38\uC5D0\uB9CC \uB4E4\uACE0 \uB098\uAC11\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30 \uD55C \uB300\uB97C \uCDA9\uC804\uD574 \uB450\uBA74 \uBC30\uD130\uB9AC \uBC29\uC804\uC774\uB098 \uACE0\uC7A5 \uB54C \uACB0\uC81C\uB97C \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB298\uBA74 \uD1B5\uC2E0 \uC694\uAE08\uB3C4 \uB300\uC218\uB9CC\uD07C \uB298\uC5B4\uB098\uBBC0\uB85C \uC6D4 \uBE44\uC6A9\uD45C\uC5D0 \uD568\uAED8 \uC801\uC2B5\uB2C8\uB2E4.", "\uC571 \uC120\uACB0\uC81C \uBE44\uC911\uC774 \uB192\uC544\uC9C0\uBA74 \uB300\uC218\uB97C \uC904\uC77C \uC218 \uC788\uC73C\uB2C8 \uBD84\uAE30\uB9C8\uB2E4 \uD604\uC7A5 \uACB0\uC81C \uAC74\uC218\uB97C \uB2E4\uC2DC \uC149\uB2C8\uB2E4.", "\uB300\uC218 \uBCC0\uACBD \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uC801\uD600 \uC788\uC73C\uB2C8 \uCC98\uC74C\uBD80\uD130 \uB9CE\uC774 \uB450\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uB294 \uC601\uC5C5 \uC2DC\uC791 \uC804\uC5D0 \uCDA9\uC804 \uC0C1\uD0DC\uB97C \uD655\uC778\uD558\uB294 \uD56D\uBAA9\uC73C\uB85C \uB461\uB2C8\uB2E4.", "\uB300\uC218 \uC0B0\uC815 \uB4A4\uC5D0\uB3C4 \uD53C\uD06C \uC694\uC77C(\uAE08\xB7\uD1A0)\uC5D0 \uAE30\uC0AC\uAC00 \uB298\uC5B4\uB098\uBA74 \uADF8 \uC694\uC77C\uB9CC \uC608\uBE44 \uAE30\uAE30\uB97C \uB354 \uAEBC\uB0B4 \uC501\uB2C8\uB2E4.", "\uC608\uBE44 \uAE30\uAE30\uAE4C\uC9C0 \uD3EC\uD568\uD55C \uB300\uC218\uB85C \uD1B5\uC2E0 \uC694\uAE08\uC744 \uACC4\uC0B0\uD574 \uC6D4 \uBE44\uC6A9\uC744 \uC815\uD569\uB2C8\uB2E4."] }, { "h": "\uAE30\uC0AC \uAD50\uB300\uC640 \uBD84\uC2E4\uC740 \uC5B4\uB5BB\uAC8C \uAD00\uB9AC\uD558\uB098\uC694?", "p": ["\uAE30\uAE30\uB9C8\uB2E4 \uBC88\uD638\uB97C \uBD99\uC774\uACE0 \uB204\uAC00 \uC5B8\uC81C \uB4E4\uACE0 \uB098\uAC14\uB294\uC9C0 \uC801\uB294 \uC7A5\uBD80\uB97C \uB461\uB2C8\uB2E4.", "\uAD50\uB300 \uC2DC\uAC04\uC5D0 \uAE30\uAE30\uB97C \uB118\uAE30\uB294 \uC790\uB9AC\uB97C \uC815\uD574 \uB450\uBA74 \uBD84\uC2E4\uACFC \uBC29\uC804\uC774 \uD568\uAED8 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uBD84\uC2E4 \uC2E0\uACE0 \uC989\uC2DC \uAE30\uAE30\uB97C \uC815\uC9C0\uC2DC\uCF1C\uC57C \uD558\uBBC0\uB85C \uC815\uC9C0 \uC694\uCCAD \uCC3D\uAD6C\uB97C \uAE30\uC0AC\uB3C4 \uC54C\uAC8C \uD569\uB2C8\uB2E4.", "\uBD84\uC2E4\xB7\uD30C\uC190 \uBE44\uC6A9 \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uC788\uACE0, \uBCF4\uD5D8 \uD3EC\uD568 \uC5EC\uBD80\uB3C4 \uD568\uAED8 \uBD05\uB2C8\uB2E4.", "\uAE30\uC0AC \uD1F4\uC0AC \uB54C \uAE30\uAE30 \uBC18\uB0A9\uC744 \uD655\uC778\uD558\uB294 \uD56D\uBAA9\uC744 \uD1F4\uC0AC \uC808\uCC28\uC5D0 \uB123\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uCDE8\uC18C\uB294 \uAC19\uC740 \uAE30\uAE30\uC5D0\uC11C \uD574\uC57C \uD558\uBBC0\uB85C \uCDE8\uC18C \uBC29\uBC95\uC744 \uAE30\uC0AC \uAD50\uC721\uC5D0 \uD3EC\uD568\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uC7A5\uBD80\uC5D0 \uCDA9\uC804 \uC0C1\uD0DC\uB97C \uD568\uAED8 \uC801\uAC8C \uD558\uBA74 \uBC29\uC804\uB41C \uAE30\uAE30\uB97C \uB4E4\uACE0 \uB098\uAC00\uB294 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uC0AC \uAD50\uC721 \uB54C \uBD84\uC2E4 \uC2E0\uACE0 \uC21C\uC11C\uB97C \uC54C\uB824 \uB450\uBA74 \uC2E0\uACE0\uAC00 \uB2A6\uC5B4 \uACB0\uC81C\uAC00 \uC2DC\uB3C4\uB418\uB294 \uC77C\uC744 \uB9C9\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uB3C4\uC785 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD55C \uB2EC \uCE58 \uD604\uC7A5 \uACB0\uC81C \uAC74\uC218\uC640 \uD53C\uD06C \uC2DC\uAC04 \uAE30\uC0AC \uC218\uB97C \uC149\uB2C8\uB2E4.", "LTE \uBC29\uC2DD\uACFC \uC601\uC218\uC99D \uBC29\uC2DD\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uB300\uC218\uC640 \uC608\uBE44 \uAE30\uAE30, \uCDA9\uC804 \uBC29\uC2DD\uC744 \uC815\uD574 \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810\uC73C\uB85C \uB4F1\uB85D\uD558\uACE0 \uACB0\uC81C\xB7\uCDE8\uC18C\uB97C \uD14C\uC2A4\uD2B8\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uBC88\uD638\xB7\uC7A5\uBD80\xB7\uAD50\uB300 \uADDC\uCE59\uC744 \uC815\uD574 \uAE30\uC0AC\uC5D0\uAC8C \uC54C\uB9BD\uB2C8\uB2E4."] }, "table": { "caption": "\uBC30\uB2EC\uC6A9 \uAE30\uAE30 \uC120\uD0DD \uAE30\uC900", "head": ["\uD56D\uBAA9", "\uAD8C\uC7A5", "\uC774\uC720"], "rows": [["\uD1B5\uC2E0", "LTE", "\uAE30\uC0AC \uAD50\uCCB4\uC5D0\uB3C4 \uC124\uC815 \uBD88\uD544\uC694"], ["\uBC30\uD130\uB9AC", "\uD558\uB8E8 \uC6B4\uD589 \uC774\uC0C1", "\uC608\uBE44 \uBC30\uD130\uB9AC \uB610\uB294 \uAC70\uCE58 \uCDA9\uC804"], ["\uC601\uC218\uC99D", "\uC5C5\uC885\uC5D0 \uB530\uB77C \uB0B4\uC7A5\xB7\uC804\uC790", "\uC6A9\uC9C0 \uAD00\uB9AC \uBD80\uB2F4 \uCC28\uC774"], ["\uB300\uC218", "\uD53C\uD06C \uAE30\uC0AC \uC218+\uC608\uBE44 1", "\uBC29\uC804\xB7\uACE0\uC7A5 \uB300\uBE44"], ["\uBD84\uC2E4", "\uC57D\uC815 \uC870\uD56D \uD655\uC778", "\uB9E4\uC7A5 \uBC16 \uC0AC\uC6A9"]] }, "faq": [["\uAE30\uC0AC \uC2A4\uB9C8\uD2B8\uD3F0\uC73C\uB85C \uACB0\uC81C\uD558\uBA74 \uC548 \uB418\uB098\uC694?", "\uBE14\uB8E8\uD22C\uC2A4\uB098 \uC571 \uBC29\uC2DD\uC774 \uC788\uC9C0\uB9CC \uAE30\uC0AC\uB9C8\uB2E4 \uC124\uC815\uC774 \uD544\uC694\uD558\uACE0 \uBD84\uC2E4 \uB54C \uAD00\uB9AC\uAC00 \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uAE30\uC0AC\uAC00 \uACE0\uC815\uB41C \uB9E4\uC7A5\uC5D0\uB9CC \uB9DE\uC2B5\uB2C8\uB2E4."], ["\uD1B5\uC2E0 \uC694\uAE08\uC740 \uB9E4\uC7A5\uC774 \uB0B4\uB098\uC694?", "\uB9E4\uC7A5 \uAC00\uB9F9\uC810 \uAE30\uAE30\uC774\uBBC0\uB85C \uB9E4\uC7A5\uC774 \uB0C5\uB2C8\uB2E4. \uAE08\uC561\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uBC30\uD130\uB9AC\uAC00 \uB098\uAC00\uBA74 \uACB0\uC81C\uB97C \uBABB \uD558\uB098\uC694?", "\uC608\uBE44 \uAE30\uAE30\uB098 \uC804\uD654 \uACB0\uC81C\uB85C \uC774\uC5B4\uAC11\uB2C8\uB2E4. \uC190\uB2D8 \uC5F0\uB77D\uCC98\uB97C \uBC1B\uC544 \uB450\uBA74 \uB429\uB2C8\uB2E4."], ["\uC601\uC218\uC99D\uC744 \uC548 \uC918\uB3C4 \uB418\uB098\uC694?", "\uC5C5\uC885\uACFC \uC190\uB2D8 \uC694\uCCAD\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4. \uC804\uC790 \uC601\uC218\uC99D \uAE30\uAE30\uB294 \uBB38\uC790\uB85C \uBCF4\uB0BC \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uBB34\uC120", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uD130\uB9AC\uAD50\uCCB4"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uC124\uCE58\uBE44\uC6A9", "title": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uC740 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uBB34\uC5C7\uC774 \uB2E4\uB978\uAC00\uC694? \u2014 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB354\uD574\uC9C0\uB294 \uAD6C\uC870", "desc": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uC774 \uAE30\uAE30\uAC12, \uC720\uC2EC \uAC1C\uD1B5\uBE44, \uC6D4 \uD1B5\uC2E0 \uC694\uAE08\uC73C\uB85C \uAD6C\uC131\uB3FC \uB9E4\uC7A5 \uC720\uC120 \uB2E8\uB9D0\uAE30\uC640 \uB2EC\uB77C\uC9C0\uB294 \uC810\uACFC \uC784\uB300\xB7\uAD6C\uB9E4 \uCC28\uC774, \uB300\uC218\uC5D0 \uB530\uB978 \uBE44\uC6A9 \uC99D\uAC00, \uBC30\uD130\uB9AC\xB7\uAC70\uCE58\uB300 \uAC19\uC740 \uBD80\uC18D\uD488 \uD56D\uBAA9, \uACAC\uC801\uC11C\uC5D0\uC11C \uD655\uC778\uD560 \uAC83\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uC124\uCE58\uBE44\uC6A9\uC740 \uAE30\uAE30\uAC12\uACFC \uC720\uC2EC \uAC1C\uD1B5\uBE44\uC5D0 \uB9E4\uB2EC \uB098\uAC00\uB294 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB354\uD574\uC9C0\uB294 \uAD6C\uC870\uB85C, \uB9E4\uC7A5 \uC720\uC120 \uB2E8\uB9D0\uAE30\uC640 \uB2EC\uB9AC \uCD9C\uC7A5 \uC124\uCE58\uAC00 \uC5C6\uAC70\uB098 \uAC04\uB2E8\uD55C \uB300\uC2E0 \uC6D4 \uD1B5\uC2E0\uBE44\uAC00 \uB300\uC218\uB9CC\uD07C \uACC4\uC18D \uB098\uAC11\uB2C8\uB2E4. \uAE08\uC561\uC740 \uBAA8\uB378\uACFC \uC57D\uC815\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uB418, \uAE30\uAE30\uAC12\xB7\uAC1C\uD1B5\uBE44\xB7\uD1B5\uC2E0\uBE44 \uC138 \uD56D\uBAA9\uC774 \uACAC\uC801\uC11C\uC5D0 \uB098\uB258\uC5B4 \uC788\uB294\uC9C0\uBD80\uD130 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uBE44\uC6A9 \uD56D\uBAA9\uC740 \uC5B4\uB5BB\uAC8C \uB098\uB258\uB098\uC694?", "p": ["\uAE30\uAE30\uAC12\uC740 LTE \uBAA8\uB4C8\uACFC \uBC30\uD130\uB9AC, \uD504\uB9B0\uD130 \uB0B4\uC7A5 \uC5EC\uBD80\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9C0\uACE0, \uC784\uB300\uBA74 \uC6D4 \uC774\uC6A9\uB8CC\uB85C \uBC14\uB01D\uB2C8\uB2E4.", "\uC720\uC2EC \uAC1C\uD1B5\uBE44\uB294 \uAE30\uAE30\uB9C8\uB2E4 \uD68C\uC120\uC744 \uC5EC\uB294 \uBE44\uC6A9\uC774\uBA70 \uB300\uC218\uB9CC\uD07C \uB4E4\uC5B4\uAC11\uB2C8\uB2E4.", "\uC6D4 \uD1B5\uC2E0 \uC694\uAE08\uC740 \uD68C\uC120\uBCC4\uB85C \uB9E4\uB2EC \uB098\uAC00\uB294 \uD56D\uBAA9\uC774\uB77C \uC6B4\uC601 \uAE30\uAC04\uC774 \uAE38\uC218\uB85D \uBE44\uC911\uC774 \uCEE4\uC9D1\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uB2EC\uB9AC \uAE30\uC0AC\uAC00 \uC640\uC11C \uC5F0\uACB0\uD560 \uC77C\uC774 \uC801\uC5B4 \uCD9C\uC7A5\uBE44\uAC00 \uBE60\uC9C0\uAC70\uB098 \uC791\uC740 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAC70\uCE58\uB300, \uC608\uBE44 \uBC30\uD130\uB9AC, \uBCF4\uD638 \uCF00\uC774\uC2A4 \uAC19\uC740 \uBD80\uC18D\uD488\uC740 \uBCC4\uB3C4 \uD56D\uBAA9\uC774\uBBC0\uB85C \uD544\uC694\uD55C \uAC83\uB9CC \uACE0\uB985\uB2C8\uB2E4.", "\uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uBB36\uC774\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uCD94\uAC00 \uB4F1\uB85D\uBE44\uAC00 \uB4DC\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uC138 \uD56D\uBAA9\uC774 \uD569\uCCD0\uC838 \uC788\uC73C\uBA74 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uC57D\uC815\uC5D0 \uBB36\uC600\uB294\uC9C0 \uC54C \uC218 \uC5C6\uC73C\uB2C8 \uBD84\uB9AC\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uC758 \uC6D4 \uC774\uC6A9\uB8CC\uC5D0 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0\uC5D0 \uB530\uB77C \uC6D4 \uCCAD\uAD6C\uAC00 \uB2EC\uB77C\uC9C0\uBBC0\uB85C \uBD84\uB9AC \uD45C\uAE30\uB97C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uB0B4\uC7A5 \uC5EC\uBD80\uB294 \uAE30\uAE30\uAC12 \uCC28\uC774\uAC00 \uD06C\uBBC0\uB85C \uC601\uC218\uC99D \uC694\uCCAD\uC774 \uC2E4\uC81C\uB85C \uC5BC\uB9C8\uB098 \uC788\uB294\uC9C0 \uC138\uC5B4 \uBCF4\uACE0 \uC815\uD569\uB2C8\uB2E4.", "\uC720\uC2EC \uAC1C\uD1B5\uBE44\uB294 \uD68C\uC120\uB2F9 \uD55C \uBC88\uC774\uC9C0\uB9CC \uAE30\uAE30\uB97C \uAD50\uCCB4\uD558\uBA74 \uB2E4\uC2DC \uB4E4 \uC218 \uC788\uC5B4 \uC720\uC2EC \uC774\uC804 \uAC00\uB2A5 \uC5EC\uBD80\uB97C \uBD05\uB2C8\uB2E4."] }, { "h": "\uBB34\uC120\uAE30 \uC784\uB300\uC640 \uAD6C\uB9E4\uC758 \uCC28\uC774\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC784\uB300\uB294 \uAE30\uAE30\uAC12\uC774 \uC6D4 \uC774\uC6A9\uB8CC\uAC00 \uB418\uACE0 \uD1B5\uC2E0 \uC694\uAE08\uACFC \uD569\uCCD0 \uCCAD\uAD6C\uB418\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4\uB294 \uAE30\uAE30\uAC12\uC744 \uCC98\uC74C\uC5D0 \uCE58\uB974\uACE0 \uC6D4\uC5D0\uB294 \uD1B5\uC2E0 \uC694\uAE08\uB9CC \uB0A8\uC2B5\uB2C8\uB2E4.", "\uBB34\uC120\uAE30\uB294 \uB9E4\uC7A5 \uBC16\uC5D0\uC11C \uC4F0\uC5EC \uD30C\uC190\xB7\uBD84\uC2E4\uC774 \uC7A6\uC73C\uBBC0\uB85C \uAD50\uCCB4 \uC870\uAC74\uC774 \uD3EC\uD568\uB41C \uC784\uB300\uAC00 \uD3B8\uD55C \uB9E4\uC7A5\uC774 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB294 \uD30C\uC190 \uB54C \uC218\uB9AC\uB098 \uAD50\uCCB4 \uBE44\uC6A9\uC774 \uB9E4\uC7A5 \uBAAB\uC774\uB77C \uC608\uBE44 \uAE30\uAE30 \uBE44\uC6A9\uAE4C\uC9C0 \uB123\uC5B4 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uC57D\uC815 \uAE30\uAC04\uACFC \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC740 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uB418\uBBC0\uB85C \uC870\uD56D\uC744 \uC77D\uC2B5\uB2C8\uB2E4.", "\uC6B4\uC601 \uAE30\uAC04\uC774 \uC9E7\uAC70\uB098 \uBC30\uB2EC \uBE44\uC911\uC774 \uBC14\uB014 \uC218 \uC788\uB294 \uB9E4\uC7A5\uC740 \uC784\uB300 \uCABD\uC774 \uC870\uC815\uC774 \uC27D\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB294 \uC720\uC2EC \uD68C\uC120 \uC57D\uC815\uB9CC \uB0A8\uC73C\uBBC0\uB85C \uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uC774 \uACE7 \uAE30\uAE30 \uCC98\uBD84 \uC870\uAC74\uC774 \uB429\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uC758 \uAD50\uCCB4 \uC870\uAC74\uC5D0 \uBC30\uD130\uB9AC \uAD50\uCCB4\uAC00 \uD3EC\uD568\uC778\uC9C0\uB3C4 \uD655\uC778\uD558\uBA74 \uB4A4\uC5D0 \uB4DC\uB294 \uBE44\uC6A9\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uB300\uC218\uC5D0 \uB530\uB77C \uC5B4\uB5BB\uAC8C \uB298\uC5B4\uB098\uB098\uC694?", "p": ["\uAE30\uAE30\uAC12, \uAC1C\uD1B5\uBE44, \uD1B5\uC2E0 \uC694\uAE08\uC774 \uBAA8\uB450 \uB300\uB2F9\uC73C\uB85C \uBD99\uC5B4 \uB300\uC218\uC5D0 \uBE44\uB840\uD574 \uB298\uC5B4\uB0A9\uB2C8\uB2E4.", "\uAC19\uC740 \uC2DC\uAC04\uC5D0 \uB098\uAC00\uB294 \uAE30\uC0AC \uC218\uB85C \uB300\uC218\uB97C \uC815\uD558\uACE0 \uC608\uBE44 \uAE30\uAE30 \uD55C \uB300\uB97C \uB354\uD558\uB294 \uBC29\uC2DD\uC774 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4.", "\uB300\uC218\uAC00 \uB9CE\uC73C\uBA74 \uB300\uB2F9 \uC694\uAE08\uC774 \uB0B4\uB824\uAC00\uB294 \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uB300\uC218\uB97C \uC904\uC77C \uB54C \uD1B5\uC2E0 \uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uC774 \uB530\uB85C \uC788\uC73C\uBBC0\uB85C \uADF8 \uC870\uD56D\uB3C4 \uBD05\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0\uB294 \uC801\uAC8C \uB450\uACE0 \uD604\uC7A5 \uACB0\uC81C\uAC00 \uB298\uBA74 \uCD94\uAC00\uD558\uB294 \uCABD\uC774 \uC6D4 \uBE44\uC6A9\uC744 \uC11C\uC11C\uD788 \uC62C\uB9BD\uB2C8\uB2E4.", "\uBC30\uB2EC \uBE44\uC911\uC774 \uB298\uC5B4 \uB300\uC218\uB97C \uCD94\uAC00\uD560 \uB54C \uAC19\uC740 \uBAA8\uB378\uB85C \uB9DE\uCD94\uBA74 \uBC30\uD130\uB9AC\uC640 \uCDA9\uC804\uAE30\uB97C \uACF5\uC720\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uB300\uC218 \uCD94\uAC00 \uB54C \uAC1C\uD1B5\uBE44\uAC00 \uB2E4\uC2DC \uB4DC\uB294\uC9C0, \uBB36\uC74C \uD560\uB2F9\uC774 \uAC00\uB2A5\uD55C\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB300\uC218\uB97C \uB298\uB9B4 \uB54C \uAC19\uC740 \uBAA8\uB378\uC744 \uC720\uC9C0\uD558\uBA74 \uAE30\uC0AC \uAD50\uC721\uC744 \uB2E4\uC2DC \uD558\uC9C0 \uC54A\uC544\uB3C4 \uB429\uB2C8\uB2E4."] }, { "h": "\uACAC\uC801\uC11C\uC5D0\uC11C \uBB34\uC5C7\uC744 \uD655\uC778\uD558\uB098\uC694?", "p": ["\uAE30\uAE30 \uBAA8\uB378\uBA85, \uD1B5\uC2E0 \uBC29\uC2DD, \uD504\uB9B0\uD130 \uB0B4\uC7A5 \uC5EC\uBD80\uAC00 \uC801\uD600 \uC788\uC5B4\uC57C \uAC19\uC740 \uC870\uAC74\uB07C\uB9AC \uBE44\uAD50\uB429\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uC694\uAE08\uC774 \uC57D\uC815 \uAE30\uAC04\uACFC \uBB36\uC600\uB294\uC9C0, \uAE30\uAE30\uC640 \uB530\uB85C \uD574\uC9C0\uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4\xB7\uD30C\uC190 \uAD50\uCCB4 \uC870\uAC74\uACFC \uC790\uAE30\uBD80\uB2F4\uC774 \uACAC\uC801\uC11C\uB098 \uC57D\uC815\uC11C\uC5D0 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC608\uBE44 \uBC30\uD130\uB9AC\uC640 \uAC70\uCE58\uB300\uAC00 \uD3EC\uD568\uC778\uC9C0 \uBCC4\uB3C4\uC778\uC9C0 \uD488\uBAA9\uC73C\uB85C \uD45C\uC2DC\uD574 \uB2EC\uB77C\uACE0 \uD569\uB2C8\uB2E4.", "\uC815\uD655\uD55C \uAE08\uC561\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uC9C0\uB9CC \uD56D\uBAA9 \uAD6C\uC870\uB97C \uC54C\uBA74 \uC5B4\uB290 \uD56D\uBAA9\uC774 \uD070\uC9C0 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4.", "\uACAC\uC801\uC744 \uBC1B\uC740 \uB0A0\uC9DC\uC640 \uB2F4\uB2F9\uC790 \uC5F0\uB77D\uCC98\uB97C \uC801\uC5B4 \uB450\uBA74 \uC124\uCE58 \uB4A4 \uCCAD\uAD6C\uC11C \uBB38\uC758\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uC801\uD78C \uAE30\uAE30 \uBC88\uD638\uC640 \uC2E4\uC81C \uBC1B\uC740 \uAE30\uAE30 \uBC88\uD638\uB97C \uB300\uC870\uD574 \uB450\uBA74 \uBC18\uB0A9 \uB54C \uD63C\uC120\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uD1B5\uC2E0\uC0AC \uC774\uB984\uC774 \uC801\uD600 \uC788\uC73C\uBA74 \uBC30\uB2EC \uC9C0\uC5ED \uC2E0\uD638\uB97C \uADF8 \uD1B5\uC2E0\uC0AC \uAE30\uC900\uC73C\uB85C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACAC\uC801\uC11C\uC5D0 \uBD84\uC2E4 \uC2DC \uAE30\uAE30\uAC12\uC774 \uC801\uD600 \uC788\uC73C\uBA74 \uBD84\uC2E4 \uC870\uAC74\uC774 \uBD84\uBA85\uD574 \uBD84\uC7C1\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }], "steps": { "h": "\uACAC\uC801\uC740 \uC5B4\uB5A4 \uC21C\uC11C\uB85C \uBC1B\uB098\uC694?", "items": ["\uD544\uC694\uD55C \uB300\uC218\uC640 \uC601\uC218\uC99D \uBC29\uC2DD\uC744 \uC815\uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uAC12\xB7\uAC1C\uD1B5\uBE44\xB7\uD1B5\uC2E0 \uC694\uAE08\uC73C\uB85C \uB098\uB25C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uC784\uB300\uC640 \uAD6C\uB9E4\uB85C \uC6B4\uC601 \uAC1C\uC6D4 \uC218\uC5D0 \uB9DE\uCDB0 \uCD1D\uBE44\uC6A9\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4\xB7\uD30C\uC190 \uC870\uAC74\uACFC \uBD80\uC18D\uD488 \uD3EC\uD568 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0 \uD56D\uBAA9\uBCC4 \uAE08\uC561\uC774 \uC801\uD614\uB294\uC9C0 \uC11C\uBA85 \uC804\uC5D0 \uB300\uC870\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uC640 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uBE44\uC6A9 \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uBB34\uC120\uB2E8\uB9D0\uAE30", "\uB9E4\uC7A5 \uC720\uC120 \uB2E8\uB9D0\uAE30"], "rows": [["\uAE30\uAE30\uAC12", "\uC788\uC74C(LTE\xB7\uBC30\uD130\uB9AC)", "\uC788\uC74C"], ["\uAC1C\uD1B5\uBE44", "\uC720\uC2EC \uD68C\uC120", "\uC778\uD130\uB137 \uD68C\uC120(\uAE30\uC874 \uAC00\uB2A5)"], ["\uC6D4 \uD1B5\uC2E0\uBE44", "\uB300\uB2F9", "\uD68C\uC120 1\uAC1C"], ["\uCD9C\uC7A5 \uC124\uCE58", "\uC5C6\uAC70\uB098 \uAC04\uB2E8", "\uC788\uC74C"], ["\uD30C\uC190 \uC704\uD5D8", "\uB192\uC74C", "\uB0AE\uC74C"]] }, "faq": [["\uD1B5\uC2E0 \uC694\uAE08\uC744 \uC548 \uB0B4\uB294 \uBC29\uBC95\uC774 \uC788\uB098\uC694?", "\uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uAE30\uC0AC \uC2A4\uB9C8\uD2B8\uD3F0 \uB370\uC774\uD130\uB97C \uC4F0\uC9C0\uB9CC \uC124\uC815 \uBD80\uB2F4\uC774 \uC788\uC2B5\uB2C8\uB2E4. LTE \uBC29\uC2DD\uC740 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uD544\uC218\uC785\uB2C8\uB2E4."], ["\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAC00\uB9F9\uC810\uC73C\uB85C \uC4F0\uB098\uC694?", "\uB300\uBD80\uBD84 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uB4F1\uB85D\uD574 \uC815\uC0B0\uC774 \uD558\uB098\uB85C \uB4E4\uC5B4\uC635\uB2C8\uB2E4. \uB4F1\uB85D \uBC29\uC2DD\uC740 \uC811\uC218 \uB54C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uC124\uCE58 \uAE30\uC0AC\uAC00 \uC624\uB098\uC694?", "\uAE30\uAE30\uB97C \uBC1B\uC544 \uC804\uC6D0\uC744 \uCF1C\uBA74 \uBC14\uB85C \uC4F0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uC124\uC815\uC774 \uD544\uC694\uD558\uBA74 \uC6D0\uACA9\uC73C\uB85C \uB3C4\uC640\uC90D\uB2C8\uB2E4."], ["\uB300\uC218\uB97C \uC904\uC774\uBA74 \uD1B5\uC2E0 \uC694\uAE08\uB3C4 \uBC14\uB85C \uBE60\uC9C0\uB098\uC694?", "\uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC558\uC73C\uBA74 \uC870\uAC74\uC774 \uBD99\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uD1B5\uC2E0\uBE44\xB7\uC720\uC2EC", "title": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uD1B5\uC2E0\uBE44\uC640 \uC720\uC2EC\uC740 \uC5B4\uB5BB\uAC8C \uCC98\uB9AC\uB418\uB098\uC694? \u2014 \uD68C\uC120 \uAC1C\uD1B5\uBD80\uD130 \uD574\uC9C0\uAE4C\uC9C0", "desc": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uC5D0 \uB4E4\uC5B4\uAC00\uB294 \uC720\uC2EC \uAC1C\uD1B5 \uC808\uCC28, \uC6D4 \uD1B5\uC2E0\uBE44\uC758 \uCCAD\uAD6C \uBC29\uC2DD, \uD1B5\uC2E0\uC0AC \uC120\uD0DD\uACFC \uC2E0\uD638\uAC00 \uC57D\uD55C \uC9C0\uC5ED\uC758 \uB300\uC751, \uB370\uC774\uD130 \uC0AC\uC6A9\uB7C9, \uAE30\uAE30 \uAD50\uCCB4\xB7\uD574\uC9C0 \uB54C \uD68C\uC120 \uCC98\uB9AC, \uD1B5\uC2E0\uBE44\uB97C \uC904\uC774\uB294 \uBC29\uBC95\uACFC \uD68C\uC120 \uAD00\uB9AC \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uD1B5\uC2E0\uBE44\uB294 \uAE30\uAE30\uB9C8\uB2E4 \uB4E4\uC5B4\uAC00\uB294 \uC720\uC2EC \uD68C\uC120\uC758 \uC6D4 \uC694\uAE08\uC774\uBA70 \uAE30\uAE30 \uC57D\uC815\uACFC \uBCC4\uB3C4\uB85C \uCCAD\uAD6C\uB418\uAC70\uB098 \uD569\uCCD0\uC838 \uCCAD\uAD6C\uB418\uBBC0\uB85C \uC5B4\uB290 \uBC29\uC2DD\uC778\uC9C0 \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4. \uACB0\uC81C \uB370\uC774\uD130\uB294 \uC591\uC774 \uC801\uC5B4 \uC694\uAE08\uC81C\uB294 \uC18C\uB7C9\uC774\uBA74 \uCDA9\uBD84\uD558\uC9C0\uB9CC \uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uC774 \uAE30\uAE30 \uD574\uC9C0\uC640 \uB530\uB85C \uC788\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uADF8 \uC870\uD56D\uC744 \uBD05\uB2C8\uB2E4.", "sections": [{ "h": "\uC720\uC2EC \uAC1C\uD1B5\uC740 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uAE30\uAE30\uC5D0 \uB9DE\uB294 \uC720\uC2EC\uC744 \uC5C5\uCCB4\uAC00 \uD568\uAED8 \uBCF4\uB0B4 \uC8FC\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uACE0, \uAC1C\uD1B5\uC740 \uC0AC\uC5C5\uC790 \uBA85\uC758\uB85C \uC9C4\uD589\uB429\uB2C8\uB2E4.", "\uAC1C\uD1B5\uC5D0\uB294 \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\uACFC \uB300\uD45C\uC790 \uC2E0\uBD84\uC99D\uC774 \uD544\uC694\uD558\uBA70 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uC811\uC218 \uC11C\uB958\uC640 \uAC19\uC2B5\uB2C8\uB2E4.", "\uD68C\uC120\uC740 \uB300\uB2F9 \uD558\uB098\uC529 \uB4E4\uC5B4\uAC00\uBBC0\uB85C \uB300\uC218\uB9CC\uD07C \uAC1C\uD1B5\uBE44\uC640 \uC6D4 \uC694\uAE08\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uAC1C\uD1B5 \uB4A4 \uCCAB \uACB0\uC81C \uD14C\uC2A4\uD2B8\uB85C \uD1B5\uC2E0\uC774 \uB418\uB294\uC9C0 \uD655\uC778\uD558\uACE0, \uC548 \uB418\uBA74 \uC720\uC2EC \uC7A5\uCC29 \uBC29\uD5A5\uACFC \uC124\uC815\uBD80\uD130 \uBD05\uB2C8\uB2E4.", "\uC720\uC2EC\uC774 \uB4E4\uC5B4 \uC788\uB294 \uAE30\uAE30\uB97C \uBD84\uC2E4\uD558\uBA74 \uD68C\uC120 \uC815\uC9C0\uB3C4 \uD568\uAED8 \uC694\uCCAD\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uAC1C\uD1B5 \uC808\uCC28\uC640 \uBE44\uC6A9\uC740 \uC5C5\uCCB4\uC640 \uD1B5\uC2E0\uC0AC\uC5D0 \uB530\uB77C \uB2E4\uB974\uBBC0\uB85C \uC811\uC218 \uB54C \uD568\uAED8 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uD1B5\uC2E0\uC0AC \uBA85\uC758 \uBCC0\uACBD\uC774\uB098 \uC591\uB3C4\uB294 \uC81C\uD55C\uB420 \uC218 \uC788\uC5B4 \uD3D0\uC5C5\xB7\uC591\uB3C4 \uB54C \uBBF8\uB9AC \uBB3B\uC2B5\uB2C8\uB2E4.", "\uC720\uC2EC \uC7A5\uCC29 \uB4A4 \uAE30\uAE30 \uD654\uBA74\uC5D0 \uD1B5\uC2E0\uC0AC \uC2E0\uD638\uAC00 \uB728\uB294\uC9C0 \uD655\uC778\uD558\uB294 \uAC83\uC774 \uAC1C\uD1B5 \uD655\uC778\uC758 \uCCAB \uB2E8\uACC4\uC785\uB2C8\uB2E4.", "\uC720\uC2EC \uAC1C\uD1B5 \uB4A4 \uAE30\uAE30 \uBC88\uD638\uC640 \uD68C\uC120 \uBC88\uD638\uB97C \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uACA8 \uB450\uBA74 \uBD84\uC2E4 \uB54C \uC815\uC9C0 \uC694\uCCAD\uC774 \uBE60\uB985\uB2C8\uB2E4.", "\uAC1C\uD1B5 \uD655\uC778\uC740 \uACB0\uC81C \uD14C\uC2A4\uD2B8\uAE4C\uC9C0 \uD574\uC57C \uB05D\uB098\uBBC0\uB85C \uC720\uC2EC \uC7A5\uCC29 \uB4A4 \uC18C\uC561 \uACB0\uC81C\uC640 \uCDE8\uC18C\uB97C \uD55C \uBC88 \uD569\uB2C8\uB2E4."] }, { "h": "\uC6D4 \uD1B5\uC2E0\uBE44\uB294 \uC5B4\uB5BB\uAC8C \uCCAD\uAD6C\uB418\uB098\uC694?", "p": ["\uAE30\uAE30 \uC784\uB300\uB8CC\uC640 \uD569\uCCD0 \uD55C \uCCAD\uAD6C\uC11C\uB85C \uC624\uB294 \uBC29\uC2DD\uACFC \uD1B5\uC2E0\uC0AC\uC5D0\uC11C \uB530\uB85C \uC624\uB294 \uBC29\uC2DD\uC774 \uC788\uC2B5\uB2C8\uB2E4.", "\uD569\uCCD0 \uC624\uBA74 \uD56D\uBAA9\uC774 \uB098\uB258\uC5B4 \uC788\uB294\uC9C0 \uBCF4\uACE0, \uB530\uB85C \uC624\uBA74 \uB450 \uCCAD\uAD6C\uC11C\uB97C \uD569\uCCD0 \uC6D4 \uBE44\uC6A9\uC73C\uB85C \uC801\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uB370\uC774\uD130\uB294 \uC18C\uB7C9\uC774\uB77C \uC800\uC6A9\uB7C9 \uC694\uAE08\uC81C\uB85C \uCDA9\uBD84\uD55C \uACBD\uC6B0\uAC00 \uB9CE\uC9C0\uB9CC, \uC601\uC218\uC99D \uC804\uC1A1\uC774\uB098 \uC571 \uC5F0\uB3D9\uC774 \uB9CE\uC73C\uBA74 \uC0AC\uC6A9\uB7C9\uC774 \uB298 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC694\uAE08\uC81C \uBCC0\uACBD\uC774 \uAC00\uB2A5\uD55C\uC9C0, \uBC14\uAFC0 \uB54C \uC870\uAC74\uC774 \uC788\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD1B5\uC2E0\uBE44\uAC00 \uAE30\uAE30 \uC57D\uC815 \uAE30\uAC04\uACFC \uBB36\uC5EC \uC788\uC73C\uBA74 \uAE30\uAE30 \uD574\uC9C0 \uB54C \uD68C\uC120 \uC704\uC57D \uC870\uAC74\uC774 \uD568\uAED8 \uBD99\uC2B5\uB2C8\uB2E4.", "\uCCAD\uAD6C\uC11C\uC5D0\uC11C \uD68C\uC120 \uBC88\uD638\uC640 \uAE30\uAE30 \uBC88\uD638\uB97C \uB9DE\uCDB0 \uB450\uBA74 \uC5B4\uB290 \uAE30\uAE30 \uC694\uAE08\uC778\uC9C0 \uBC14\uB85C \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBCC4\uB3C4 \uCCAD\uAD6C \uBC29\uC2DD\uC774\uBA74 \uD1B5\uC2E0\uC0AC \uCCAD\uAD6C\uC11C\uC758 \uBA85\uC758\uAC00 \uC0AC\uC5C5\uC790\uC778\uC9C0 \uD655\uC778\uD574 \uC138\uBB34 \uCC98\uB9AC\uC5D0 \uB123\uC2B5\uB2C8\uB2E4.", "\uC694\uAE08\uC81C\uB97C \uBC14\uAFB8\uBA74 \uC801\uC6A9 \uC2DC\uC810\uC774 \uB2E4\uC74C \uB2EC\uC778 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uBC14\uB010 \uB2EC \uCCAD\uAD6C\uC11C\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBCC4\uB3C4 \uCCAD\uAD6C \uBC29\uC2DD\uC774\uBA74 \uD1B5\uC2E0\uC0AC \uC694\uAE08 \uBCC0\uACBD \uD1B5\uC9C0\uAC00 \uB9E4\uC7A5\uC73C\uB85C \uC624\uB294\uC9C0 \uD655\uC778\uD574 \uB461\uB2C8\uB2E4."] }, { "h": "\uC2E0\uD638\uAC00 \uC57D\uD558\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uC9C0\uD558 \uB9E4\uC7A5, \uC2E0\uCD95 \uB2E8\uC9C0, \uC0B0\uAC04 \uC9C0\uC5ED\uC740 \uD2B9\uC815 \uD1B5\uC2E0\uC0AC \uC2E0\uD638\uAC00 \uC57D\uD560 \uC218 \uC788\uC5B4 \uBC30\uB2EC \uC9C0\uC5ED\uC758 \uC2E0\uD638\uB97C \uBA3C\uC800 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uAC00 \uD1B5\uC2E0\uC0AC \uBCC0\uACBD\uC744 \uC9C0\uC6D0\uD558\uBA74 \uC720\uC2EC\uB9CC \uBC14\uAFD4 \uB300\uC751\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C\uAC00 \uC548 \uB420 \uB54C\uB294 \uAE30\uC0AC\uAC00 \uBA87 \uAC78\uC74C \uC774\uB3D9\uD574 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uB3C4\uB85D \uC54C\uB824 \uB461\uB2C8\uB2E4.", "\uBC18\uBCF5\uB418\uB294 \uC9C0\uC5ED\uC774 \uC788\uC73C\uBA74 \uADF8 \uC9C0\uC5ED\uC740 \uC571 \uC120\uACB0\uC81C\uB098 \uB9C1\uD06C \uACB0\uC81C\uB85C \uC720\uB3C4\uD569\uB2C8\uB2E4.", "\uC2E0\uD638 \uBB38\uC81C\uB294 \uAE30\uAE30 \uACE0\uC7A5\uACFC \uAD6C\uBD84\uB418\uBBC0\uB85C \uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uC2A4\uB9C8\uD2B8\uD3F0 \uC2E0\uD638\uC640 \uBE44\uAD50\uD574 \uBD05\uB2C8\uB2E4.", "\uBC30\uB2EC \uC9C0\uC5ED\uC758 \uC2E0\uD638 \uC9C0\uB3C4\uB294 \uAE30\uC0AC \uBCF4\uACE0\uB97C \uC77C\uC8FC\uC77C\uB9CC \uBAA8\uC544\uB3C4 \uADF8\uB9BC\uC774 \uADF8\uB824\uC9D1\uB2C8\uB2E4.", "\uC2E0\uD638\uAC00 \uC57D\uD55C \uC9C0\uC5ED\uC744 \uAE30\uC0AC\uC5D0\uAC8C \uC54C\uB824 \uACB0\uC81C \uC804\uC5D0 \uC2E0\uD638\uB97C \uD655\uC778\uD558\uB294 \uC2B5\uAD00\uC744 \uB4E4\uC774\uAC8C \uD569\uB2C8\uB2E4.", "\uC2E0\uD638\uAC00 \uC57D\uD55C \uC9C0\uC5ED\uC774 \uBC30\uB2EC \uAD6C\uC5ED\uC758 \uD070 \uBE44\uC911\uC774\uBA74 \uD1B5\uC2E0\uC0AC \uBCC0\uACBD\uC774 \uAC00\uB2A5\uD55C \uAE30\uAE30\uB85C \uBC14\uAFB8\uB294 \uCABD\uC774 \uB0AB\uC2B5\uB2C8\uB2E4."] }, { "h": "\uAE30\uAE30 \uAD50\uCCB4\uC640 \uD574\uC9C0 \uB54C \uD68C\uC120\uC740 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uAE30\uAE30\uB97C \uBC14\uAFB8\uBA74 \uC720\uC2EC\uC744 \uC62E\uACA8 \uC4F0\uAC70\uB098 \uC0C8 \uD68C\uC120\uC744 \uAC1C\uD1B5\uD558\uBBC0\uB85C \uC5B4\uB290 \uCABD\uC778\uC9C0 \uC5C5\uCCB4\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uD574\uC9C0\uD574\uB3C4 \uD68C\uC120 \uC57D\uC815\uC774 \uB0A8\uC73C\uBA74 \uD1B5\uC2E0\uBE44\uAC00 \uACC4\uC18D \uB098\uAC00\uBBC0\uB85C \uD68C\uC120 \uD574\uC9C0\uB97C \uB530\uB85C \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC740 \uAE00\uB85C \uB0A8\uAE30\uACE0 \uB2E4\uC74C \uB2EC \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uC694\uAE08\uC774 \uBE60\uC84C\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4 \uAE30\uAE30\uC758 \uD68C\uC120\uC740 \uC815\uC9C0 \uB4A4 \uD574\uC9C0 \uB610\uB294 \uC0C8 \uAE30\uAE30\uB85C \uC774\uC804\uC744 \uC120\uD0DD\uD569\uB2C8\uB2E4.", "\uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uACFC \uC704\uC57D \uC5EC\uBD80\uB294 \uC57D\uC815\uC11C\uC640 \uD1B5\uC2E0\uC0AC \uC870\uAC74\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD68C\uC120 \uD574\uC9C0 \uD655\uC778\uC740 \uD1B5\uC2E0\uC0AC \uBA85\uC758 \uD655\uC778\uC11C\uB098 \uC5C5\uCCB4 \uD574\uC9C0 \uD655\uC778\uC11C\uB85C \uBC1B\uC544 \uB450\uBA74 \uB4A4\uC5D0 \uCCAD\uAD6C\uAC00 \uC640\uB3C4 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uC720\uC2EC \uC774\uC804\uC774 \uAC00\uB2A5\uD558\uBA74 \uC0C8 \uAE30\uAE30 \uAC1C\uD1B5\uBE44\uAC00 \uBE60\uC9C0\uBBC0\uB85C \uAD50\uCCB4 \uB54C \uBA3C\uC800 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uB54C \uC720\uC2EC\uC744 \uC62E\uAE30\uBA74 \uD68C\uC120 \uBC88\uD638\uAC00 \uC720\uC9C0\uB418\uBBC0\uB85C \uC7A5\uBD80\uB3C4 \uADF8\uB300\uB85C \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD68C\uC120 \uD574\uC9C0 \uB4A4 \uC720\uC2EC\uC744 \uD30C\uAE30\uD560 \uB54C\uB294 \uC0AC\uC9C4\uC73C\uB85C \uB0A8\uACA8 \uB450\uBA74 \uC7AC\uC0AC\uC6A9 \uC758\uC2EC\uC744 \uBC1B\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uD68C\uC120 \uAD00\uB9AC \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uAC1C\uD1B5 \uB54C \uD68C\uC120 \uBC88\uD638\uC640 \uAE30\uAE30 \uBC88\uD638\uB97C \uC9DD\uC9C0\uC5B4 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uCCAD\uAD6C \uBC29\uC2DD(\uD569\uC0B0\xB7\uBCC4\uB3C4)\uC744 \uD655\uC778\uD558\uACE0 \uC6D4 \uBE44\uC6A9\uC5D0 \uB123\uC2B5\uB2C8\uB2E4.", "\uC2E0\uD638\uAC00 \uC57D\uD55C \uC9C0\uC5ED\uC744 \uAE30\uC0AC \uBCF4\uACE0\uB85C \uBAA8\uC544 \uB461\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uB54C \uC720\uC2EC \uC774\uC804 \uC5EC\uBD80\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uB54C \uAE30\uAE30\uC640 \uD68C\uC120\uC744 \uAC01\uAC01 \uC2E0\uCCAD\uD558\uACE0 \uCCAD\uAD6C\uC11C\uB85C \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD1B5\uC2E0\uBE44 \uAD00\uB828 \uD655\uC778 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "\uD655\uC778\uD560 \uAC83", "\uC5C6\uC73C\uBA74"], "rows": [["\uAC1C\uD1B5 \uC11C\uB958", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC99D\xB7\uC2E0\uBD84\uC99D", "\uC811\uC218 \uC9C0\uC5F0"], ["\uCCAD\uAD6C \uBC29\uC2DD", "\uD569\uC0B0\xB7\uBCC4\uB3C4", "\uD56D\uBAA9 \uBD84\uB9AC \uC694\uCCAD"], ["\uC694\uAE08\uC81C", "\uB370\uC774\uD130 \uC6A9\uB7C9\xB7\uBCC0\uACBD \uC870\uAC74", "\uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778"], ["\uD68C\uC120 \uC57D\uC815", "\uAE30\uAE30 \uC57D\uC815\uACFC \uBB36\uC784 \uC5EC\uBD80", "\uC57D\uC815\uC11C \uD655\uC778"], ["\uD574\uC9C0", "\uAE30\uAE30\xB7\uD68C\uC120 \uAC01\uAC01", "\uC694\uAE08 \uACC4\uC18D \uCCAD\uAD6C"]] }, "faq": [["\uD1B5\uC2E0\uBE44\uB294 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uC694\uAE08\uC81C\uC640 \uB300\uC218\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uB0B4 \uC2A4\uB9C8\uD2B8\uD3F0 \uC720\uC2EC\uC744 \uB123\uC5B4\uB3C4 \uB418\uB098\uC694?", "\uAE30\uAE30\uC640 \uC694\uAE08\uC81C \uD638\uD658\uC774 \uB9DE\uC544\uC57C \uD558\uACE0 \uC0AC\uC5C5\uC790 \uBA85\uC758 \uBB38\uC81C\uAC00 \uC788\uC5B4 \uAD8C\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC5C5\uCCB4 \uC81C\uACF5 \uC720\uC2EC\uC774 \uC548\uC804\uD569\uB2C8\uB2E4."], ["\uB370\uC774\uD130\uAC00 \uBD80\uC871\uD558\uBA74 \uACB0\uC81C\uAC00 \uC548 \uB418\uB098\uC694?", "\uACB0\uC81C \uB370\uC774\uD130\uB294 \uC18C\uB7C9\uC774\uB77C \uB4DC\uBB3C\uC9C0\uB9CC, \uC601\uC218\uC99D \uC804\uC1A1\uC774 \uB9CE\uC73C\uBA74 \uC0AC\uC6A9\uB7C9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uAE30\uAE30\uB97C \uD574\uC9C0\uD588\uB294\uB370 \uD1B5\uC2E0\uBE44\uAC00 \uB098\uC640\uC694.", "\uD68C\uC120 \uD574\uC9C0\uAC00 \uB530\uB85C \uC548 \uB41C \uACBD\uC6B0\uC785\uB2C8\uB2E4. \uC811\uC218 \uBC88\uD638\uB97C \uB4E4\uACE0 \uD68C\uC120 \uD574\uC9C0\uB97C \uC2E0\uCCAD\uD569\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uC124\uCE58\uBE44\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD574\uC9C0\uBC18\uB0A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBE14\uB8E8\uD22C\uC2A4LTE"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBE14\uB8E8\uD22C\uC2A4LTE", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uBE14\uB8E8\uD22C\uC2A4 vs LTE", "title": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uB294 \uBE14\uB8E8\uD22C\uC2A4\uC640 LTE \uC911 \uBB34\uC5C7\uC774 \uB9DE\uB098\uC694? \u2014 \uC2A4\uB9C8\uD2B8\uD3F0 \uC758\uC874 \uC5EC\uBD80\uB85C \uAC00\uB974\uAE30", "desc": "\uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uACFC LTE \uBC29\uC2DD \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uC2A4\uB9C8\uD2B8\uD3F0 \uC758\uC874, \uC124\uC815 \uBD80\uB2F4, \uD1B5\uC2E0 \uC694\uAE08, \uAE30\uC0AC \uAD50\uCCB4 \uB300\uC751, \uACB0\uC81C \uC548\uC815\uC131, \uB9E4\uC7A5 \uC548 \uC0AC\uC6A9\uC73C\uB85C \uBE44\uAD50\uD574 \uBC30\uB2EC \uB9E4\uC7A5\xB7\uD589\uC0AC\xB7\uB9E4\uC7A5 \uB0B4 \uC774\uB3D9 \uACB0\uC81C\uC5D0 \uAC01\uAC01 \uC5B4\uB290 \uCABD\uC774 \uB9DE\uB294\uC9C0 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "LTE \uBC29\uC2DD\uC740 \uAE30\uAE30 \uC548 \uC720\uC2EC\uC73C\uB85C \uB2E8\uB3C5 \uACB0\uC81C\uAC00 \uB418\uC5B4 \uAE30\uC0AC \uAD50\uCCB4\uC640 \uBD84\uC2E4 \uB300\uC751\uC774 \uC27D\uACE0, \uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uC2A4\uB9C8\uD2B8\uD3F0\uACFC \uC9DD\uC744 \uC774\uB904 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uC5C6\uC9C0\uB9CC \uAE30\uC0AC\uB9C8\uB2E4 \uC124\uC815\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uAE30\uC0AC\uAC00 \uC790\uC8FC \uBC14\uB00C\uAC70\uB098 \uC5EC\uB7EC \uBA85\uC774\uBA74 LTE, \uC0AC\uC7A5\uC774 \uC9C1\uC811 \uB4E4\uACE0 \uB2E4\uB2C8\uB294 \uC18C\uADDC\uBAA8 \uB9E4\uC7A5\uC774\uBA74 \uBE14\uB8E8\uD22C\uC2A4\uAC00 \uB9DE\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "sections": [{ "h": "\uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uC5B4\uB5A4 \uD2B9\uC9D5\uC774 \uC788\uB098\uC694?", "p": ["\uC2A4\uB9C8\uD2B8\uD3F0 \uC571\uACFC \uC5F0\uACB0\uD574 \uACB0\uC81C\uD558\uBBC0\uB85C \uAE30\uAE30 \uC790\uCCB4\uC5D0\uB294 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uAE30\uC0AC\uB9C8\uB2E4 \uC571\uC744 \uAE54\uACE0 \uC5F0\uACB0 \uC124\uC815\uC744 \uD574\uC57C \uD558\uBBC0\uB85C \uAE30\uC0AC\uAC00 \uBC14\uB014 \uB54C\uB9C8\uB2E4 \uC124\uC815 \uC791\uC5C5\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uC2A4\uB9C8\uD2B8\uD3F0 \uBC30\uD130\uB9AC\uC640 \uB370\uC774\uD130\uC5D0 \uC758\uC874\uD558\uBBC0\uB85C \uC2A4\uB9C8\uD2B8\uD3F0\uC774 \uAEBC\uC9C0\uBA74 \uACB0\uC81C\uAC00 \uBA48\uCDA5\uB2C8\uB2E4.", "\uAE30\uAE30\uAC00 \uC791\uACE0 \uAC00\uBCBC\uC6CC \uC0AC\uC7A5\uC774 \uC9C1\uC811 \uBC30\uB2EC\uD558\uAC70\uB098 \uD589\uC0AC\uC5D0\uC11C \uC7A0\uAE50 \uC4F0\uAE30\uC5D0 \uD3B8\uD569\uB2C8\uB2E4.", "\uC5F0\uACB0\uC774 \uB04A\uAE30\uBA74 \uC7AC\uC5F0\uACB0\uC5D0 \uC2DC\uAC04\uC774 \uAC78\uB824 \uC190\uB2D8 \uC55E\uC5D0\uC11C \uC9C0\uC5F0\uC774 \uC0DD\uAE38 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC571 \uACB0\uC81C \uBC29\uC2DD\uC774\uB77C \uC601\uC218\uC99D\uC740 \uBB38\uC790\uB098 \uC571\uC73C\uB85C \uBCF4\uB0B4\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uAC1C\uC778 \uC2A4\uB9C8\uD2B8\uD3F0\uC5D0 \uB9E4\uC7A5 \uACB0\uC81C \uC571\uC774 \uB4E4\uC5B4\uAC00\uBBC0\uB85C \uD1F4\uC0AC \uB54C \uC571 \uC0AD\uC81C\uC640 \uACC4\uC815 \uC815\uB9AC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uAE30\uAE30\uB294 \uC2A4\uB9C8\uD2B8\uD3F0 \uC6B4\uC601\uCCB4\uC81C \uC5C5\uB370\uC774\uD2B8 \uB4A4 \uC5F0\uACB0\uC774 \uB04A\uAE30\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uC5C5\uB370\uC774\uD2B8 \uB4A4 \uACB0\uC81C \uD14C\uC2A4\uD2B8\uB97C \uD569\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uAE30\uAE30\uB294 \uC791\uC544\uC11C \uBD84\uC2E4\uC774 \uC7A6\uC73C\uB2C8 \uBCF4\uAD00 \uC7A5\uC18C\uB97C \uC815\uD574 \uB461\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uAE30\uAE30\uB294 \uC2A4\uB9C8\uD2B8\uD3F0 \uC571 \uBC84\uC804\uC5D0 \uB530\uB77C \uACB0\uC81C \uD654\uBA74\uC774 \uB2EC\uB77C\uC838 \uAE30\uC0AC \uAD50\uC721 \uC790\uB8CC\uB97C \uC790\uC8FC \uBC14\uAFD4\uC57C \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uAE30\uAE30\uB294 \uB9E4\uC7A5 \uC2A4\uB9C8\uD2B8\uD3F0\uC744 \uACB0\uC81C \uC804\uC6A9\uC73C\uB85C \uB450\uBA74 \uAC1C\uC778 \uAE30\uAE30 \uBB38\uC81C\uB97C \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."] }, { "h": "LTE \uBC29\uC2DD\uC740 \uC5B4\uB5A4 \uD2B9\uC9D5\uC774 \uC788\uB098\uC694?", "p": ["\uAE30\uAE30 \uC548 \uC720\uC2EC\uC73C\uB85C \uB2E8\uB3C5 \uACB0\uC81C\uAC00 \uB418\uC5B4 \uB204\uAC00 \uB4E4\uACE0 \uB098\uAC00\uB3C4 \uC124\uC815\uC774 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uB300\uB2F9 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB9E4\uB2EC \uB098\uAC00\uBBC0\uB85C \uB300\uC218\uB9CC\uD07C \uC6D4 \uBE44\uC6A9\uC774 \uC0DD\uAE41\uB2C8\uB2E4.", "\uAE30\uAE30 \uBC30\uD130\uB9AC\uB9CC \uAD00\uB9AC\uD558\uBA74 \uB418\uACE0 \uC2A4\uB9C8\uD2B8\uD3F0 \uC0C1\uD0DC\uC640 \uBB34\uAD00\uD569\uB2C8\uB2E4.", "\uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC774 \uB9CE\uC544 \uC601\uC218\uC99D\uC744 \uBC14\uB85C \uC904 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBD84\uC2E4 \uB54C \uD68C\uC120 \uC815\uC9C0\uB85C \uAE30\uAE30\uB97C \uBC14\uB85C \uB9C9\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uAC00 \uBE14\uB8E8\uD22C\uC2A4\uD615\uBCF4\uB2E4 \uD06C\uACE0 \uBB34\uAC70\uC6B4 \uD3B8\uC774\uB77C \uAE30\uC0AC \uAC00\uBC29\uC5D0 \uB9DE\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uBE14\uB8E8\uD22C\uC2A4 \uBC29\uC2DD\uC740 \uAE30\uC0AC \uAC1C\uC778 \uC2A4\uB9C8\uD2B8\uD3F0 \uB370\uC774\uD130 \uC694\uAE08\uC774 \uB298 \uC218 \uC788\uC5B4 \uADF8 \uBD80\uB2F4\uC744 \uB204\uAC00 \uC9C0\uB294\uC9C0 \uC815\uD574 \uB461\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB294 \uD1B5\uC2E0 \uC694\uAE08\uC774 \uB098\uAC00\uB294 \uB300\uC2E0 \uACB0\uC81C \uCC45\uC784\uC774 \uAE30\uAE30\uC5D0 \uC788\uC5B4 \uAE30\uC0AC \uAC1C\uC778 \uAE30\uAE30 \uBB38\uC81C\uC640 \uBD84\uB9AC\uB429\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB294 \uAE30\uAE30 \uBC88\uD638\uC640 \uD68C\uC120 \uBC88\uD638\uB97C \uD568\uAED8 \uAD00\uB9AC\uD574\uC57C \uBD84\uC2E4 \uB54C \uC815\uC9C0\uAC00 \uBE60\uB985\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB294 \uD1B5\uC2E0\uC0AC \uC810\uAC80\uC774\uB098 \uC7A5\uC560 \uACF5\uC9C0\uB97C \uBC1B\uC744 \uC5F0\uB77D\uCC98\uB97C \uB4F1\uB85D\uD574 \uB461\uB2C8\uB2E4."] }, { "h": "\uC5B4\uB5A4 \uB9E4\uC7A5\uC5D0 \uC5B4\uB290 \uCABD\uC774 \uB9DE\uB098\uC694?", "p": ["\uBC30\uB2EC \uAE30\uC0AC\uAC00 \uC5EC\uB7EC \uBA85\uC774\uAC70\uB098 \uC790\uC8FC \uBC14\uB00C\uB294 \uB9E4\uC7A5\uC740 \uC124\uC815 \uBD80\uB2F4\uC774 \uC5C6\uB294 LTE\uAC00 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC7A5\uC774\uB098 \uACE0\uC815 \uC9C1\uC6D0 \uD55C \uBA85\uC774 \uB4E4\uACE0 \uB2E4\uB2C8\uB294 \uB9E4\uC7A5\uC740 \uBE14\uB8E8\uD22C\uC2A4\uB85C \uD1B5\uC2E0 \uC694\uAE08\uC744 \uC544\uB084 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD589\uC0AC\uB098 \uD478\uB4DC\uD2B8\uB7ED\uCC98\uB7FC \uAC00\uB054 \uC4F0\uB294 \uACBD\uC6B0\uB294 \uBE14\uB8E8\uD22C\uC2A4\uAC00 \uAC00\uBCCD\uACE0, \uB9E4\uC77C \uC4F0\uBA74 LTE\uAC00 \uC548\uC815\uC801\uC785\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC548\uC5D0\uC11C \uD14C\uC774\uBE14\uB85C \uAC00\uC838\uAC00 \uACB0\uC81C\uD558\uB294 \uC6A9\uB3C4\uB294 \uC640\uC774\uD30C\uC774 \uBC29\uC2DD\uB3C4 \uAC00\uB2A5\uD558\uBBC0\uB85C \uAD6C\uBD84\uD569\uB2C8\uB2E4.", "\uB450 \uBC29\uC2DD\uC758 \uAE30\uAE30\uAC12\uACFC \uC6D4 \uBE44\uC6A9\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uB294 \uD1B5\uC2E0\uC0AC \uC810\uAC80 \uC2DC\uAC04\uC5D0 \uACB0\uC81C\uAC00 \uC7A0\uC2DC \uC548 \uB420 \uC218 \uC788\uC73C\uB2C8 \uACF5\uC9C0\uAC00 \uC624\uBA74 \uAE30\uC0AC\uC5D0\uAC8C \uC54C\uB9BD\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC548\uD30E\uC744 \uC624\uAC00\uB294 \uACB0\uC81C\uAC00 \uBAA8\uB450 \uD544\uC694\uD558\uBA74 LTE \uAE30\uAE30 \uD558\uB098\uB85C \uB458 \uB2E4 \uD574\uACB0\uB429\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC548\uD30E \uACB8\uC6A9\uC774\uBA74 \uC640\uC774\uD30C\uC774\uC640 LTE\uB97C \uC790\uB3D9\uC73C\uB85C \uBC14\uAFB8\uB294 \uAE30\uAE30\uAC00 \uD3B8\uD569\uB2C8\uB2E4.", "\uB450 \uBC29\uC2DD\uC758 \uACB0\uC81C \uC18D\uB3C4 \uCC28\uC774\uB294 \uAC70\uC758 \uC5C6\uC73C\uBBC0\uB85C \uC6B4\uC601 \uD3B8\uC758\uC640 \uBE44\uC6A9\uC73C\uB85C \uC815\uD569\uB2C8\uB2E4.", "\uC6A9\uB3C4\uBCC4\uB85C \uAE30\uAE30\uB97C \uB098\uB204\uBA74 \uD1B5\uC2E0 \uC694\uAE08\uC740 LTE \uB300\uC218\uC5D0\uB9CC \uBD99\uC5B4 \uC6D4 \uBE44\uC6A9\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4."] }, { "h": "\uBC14\uAFC0 \uB54C\uB294 \uBB34\uC5C7\uC744 \uBCF4\uB098\uC694?", "p": ["\uBE14\uB8E8\uD22C\uC2A4\uC5D0\uC11C LTE\uB85C \uBC14\uAFB8\uBA74 \uD68C\uC120 \uAC1C\uD1B5\uC774 \uD544\uC694\uD558\uACE0 \uC6D4 \uD1B5\uC2E0\uBE44\uAC00 \uC0DD\uAE41\uB2C8\uB2E4.", "LTE\uC5D0\uC11C \uBE14\uB8E8\uD22C\uC2A4\uB85C \uBC14\uAFB8\uBA74 \uD68C\uC120 \uD574\uC9C0 \uC870\uAC74\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uAC00\uB9F9\uC810 \uBC88\uD638\uB294 \uAC19\uC740 \uB9E4\uC7A5\uC774\uBA74 \uADF8\uB300\uB85C \uC4F0\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uBC14\uAFBC \uB4A4 \uACB0\uC81C\xB7\uCDE8\uC18C \uD14C\uC2A4\uD2B8\uB97C \uD558\uACE0 \uAE30\uC0AC \uAD50\uC721\uC744 \uB2E4\uC2DC \uD569\uB2C8\uB2E4.", "\uBC14\uAFBC \uB4A4 \uCCAB \uC8FC\uB294 \uAE30\uC0AC \uBCF4\uACE0\uB85C \uACB0\uC81C \uC2E4\uD328 \uAC74\uC218\uB97C \uBAA8\uC544 \uBC29\uC2DD \uC120\uD0DD\uC774 \uB9DE\uC558\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "LTE \uAE30\uAE30\uC758 \uC720\uC2EC\uC740 \uAE30\uAE30\uC640 \uBB36\uC778 \uD68C\uC120\uC774\uB77C \uAE30\uC0AC \uAC1C\uC778 \uC2A4\uB9C8\uD2B8\uD3F0\uC5D0 \uAF42\uC544 \uC4F0\uBA74 \uC548 \uB429\uB2C8\uB2E4.", "\uBC29\uC2DD\uC744 \uBC14\uAFB8\uBA74 \uC601\uC218\uC99D \uC804\uC1A1 \uBC29\uC2DD\uB3C4 \uB2EC\uB77C\uC9C8 \uC218 \uC788\uC5B4 \uC190\uB2D8 \uC548\uB0B4 \uBB38\uAD6C\uB97C \uD568\uAED8 \uBC14\uAFC9\uB2C8\uB2E4.", "\uBC29\uC2DD\uC744 \uBC14\uAFBC \uB4A4 \uC190\uB2D8 \uC601\uC218\uC99D \uC548\uB0B4 \uBB38\uAD6C(\uBB38\uC790 \uC804\uC1A1\xB7\uCD9C\uB825)\uB3C4 \uD568\uAED8 \uBC14\uAFC9\uB2C8\uB2E4.", "\uBC14\uAFBC \uB4A4 \uCCAB \uC8FC \uACB0\uC81C \uC2E4\uD328 \uAC74\uC218\uB97C \uAE30\uC0AC \uBCF4\uACE0\uB85C \uBAA8\uC74D\uB2C8\uB2E4."] }], "steps": { "h": "\uC120\uD0DD \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uAE30\uAE30\uB97C \uB4E4\uACE0 \uB098\uAC00\uB294 \uC0AC\uB78C \uC218\uC640 \uAD50\uCCB4 \uBE48\uB3C4\uB97C \uBD05\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uCD9C\uB825\uC774 \uD544\uC694\uD55C\uC9C0 \uC815\uD569\uB2C8\uB2E4.", "\uD1B5\uC2E0 \uC694\uAE08\uACFC \uC124\uC815 \uBD80\uB2F4 \uC911 \uBB34\uC5C7\uC774 \uB354 \uD070\uC9C0 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uD544\uC694\uD55C \uB300\uC218\uB85C \uACAC\uC801\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD14C\uC2A4\uD2B8 \uACB0\uC81C \uB4A4 \uAE30\uC0AC \uAD50\uC721\uC744 \uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uBE14\uB8E8\uD22C\uC2A4\uC640 LTE \uBE44\uAD50", "head": ["\uD56D\uBAA9", "\uBE14\uB8E8\uD22C\uC2A4", "LTE"], "rows": [["\uC2A4\uB9C8\uD2B8\uD3F0 \uC758\uC874", "\uC788\uC74C", "\uC5C6\uC74C"], ["\uD1B5\uC2E0 \uC694\uAE08", "\uC5C6\uC74C", "\uB300\uB2F9 \uC6D4 \uC694\uAE08"], ["\uAE30\uC0AC \uAD50\uCCB4", "\uC124\uC815 \uD544\uC694", "\uC124\uC815 \uBD88\uD544\uC694"], ["\uC601\uC218\uC99D", "\uC804\uC790 \uC704\uC8FC", "\uB0B4\uC7A5 \uD504\uB9B0\uD130 \uAC00\uB2A5"], ["\uBD84\uC2E4 \uB300\uC751", "\uC571 \uACC4\uC815 \uC815\uB9AC", "\uD68C\uC120 \uC815\uC9C0"]] }, "faq": [["\uBE14\uB8E8\uD22C\uC2A4 \uAE30\uAE30\uB3C4 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uD544\uC694\uD55C\uAC00\uC694?", "\uD544\uC694\uD569\uB2C8\uB2E4. \uACB0\uC81C\uB294 \uB9E4\uC7A5 \uAC00\uB9F9\uC810\uC73C\uB85C \uC2B9\uC778\uB429\uB2C8\uB2E4."], ["LTE \uAE30\uAE30\uB294 \uC640\uC774\uD30C\uC774\uC5D0\uC11C\uB3C4 \uB418\uB098\uC694?", "\uAE30\uAE30\uC5D0 \uB530\uB77C \uB429\uB2C8\uB2E4. \uB9E4\uC7A5 \uC548\uC5D0\uC11C\uB294 \uC640\uC774\uD30C\uC774, \uBC16\uC5D0\uC11C\uB294 LTE\uB85C \uC4F0\uB294 \uBAA8\uB378\uC774 \uC788\uC2B5\uB2C8\uB2E4."], ["\uB450 \uBC29\uC2DD\uC744 \uC11E\uC5B4 \uC368\uB3C4 \uB418\uB098\uC694?", "\uB429\uB2C8\uB2E4. \uACE0\uC815 \uC9C1\uC6D0\uC740 \uBE14\uB8E8\uD22C\uC2A4, \uAD50\uB300 \uAE30\uC0AC\uB294 LTE\uB85C \uB098\uB204\uB294 \uB9E4\uC7A5\uB3C4 \uC788\uC2B5\uB2C8\uB2E4."], ["\uC5B4\uB290 \uCABD\uC774 \uB354 \uC2FC\uAC00\uC694?", "\uCD08\uAE30 \uBE44\uC6A9\uACFC \uC6D4 \uD1B5\uC2E0\uBE44 \uAD6C\uC870\uAC00 \uB2EC\uB77C \uC6B4\uC601 \uAE30\uAC04\uC73C\uB85C \uACC4\uC0B0\uD569\uB2C8\uB2E4. \uCD08\uAE30 \uAE30\uAE30\uAC12\uACFC \uC6D4 \uD1B5\uC2E0\uBE44\uB97C \uB098\uB780\uD788 \uB193\uACE0 \uACC4\uC0B0\uD55C \uAC12\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uBC1B\uC2B5\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD589\uC0AC\uD478\uB4DC\uD2B8\uB7ED"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD589\uC0AC\uD478\uB4DC\uD2B8\uB7ED", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uD589\uC0AC\xB7\uD478\uB4DC\uD2B8\uB7ED", "title": "\uD589\uC0AC\uB098 \uD478\uB4DC\uD2B8\uB7ED\uC5D0\uC11C\uB294 \uC5B4\uB5A4 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uC4F0\uB098\uC694? \u2014 \uC804\uC6D0\xB7\uD1B5\uC2E0\xB7\uB2E8\uAE30 \uC0AC\uC6A9\uC758 \uC870\uAC74", "desc": "\uD589\uC0AC\uC7A5, \uD50C\uB9AC\uB9C8\uCF13, \uD478\uB4DC\uD2B8\uB7ED\uCC98\uB7FC \uB9E4\uC7A5 \uBC16\uC5D0\uC11C \uC9E7\uAC8C \uACB0\uC81C\uB97C \uBC1B\uC744 \uB54C \uBB34\uC120\uB2E8\uB9D0\uAE30\uC758 \uD1B5\uC2E0 \uBC29\uC2DD, \uBC30\uD130\uB9AC\uC640 \uC804\uC6D0, \uB2E8\uAE30 \uC784\uB300 \uAC00\uB2A5 \uC5EC\uBD80, \uAC00\uB9F9\uC810 \uB4F1\uB85D \uC8FC\uC18C, \uD604\uC7A5 \uACB0\uC81C \uD750\uB984\uACFC \uC815\uC0B0, \uD589\uC0AC \uC900\uBE44 \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uD589\uC0AC\uC640 \uD478\uB4DC\uD2B8\uB7ED\uC5D0\uC11C\uB294 \uC804\uC6D0\uC774 \uC5C6\uB294 \uACF3\uC5D0\uC11C \uD558\uB8E8\uB97C \uBC84\uD2F0\uB294 \uBC30\uD130\uB9AC\uC640 LTE \uB2E8\uB3C5 \uD1B5\uC2E0\uC774 \uB418\uB294 \uBB34\uC120\uB2E8\uB9D0\uAE30\uAC00 \uB9DE\uACE0, \uBA70\uCE60\uB9CC \uC4F4\uB2E4\uBA74 \uB2E8\uAE30 \uC784\uB300\uAC00 \uAC00\uB2A5\uD55C\uC9C0 \uBA3C\uC800 \uBB3B\uC2B5\uB2C8\uB2E4. \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uC0AC\uC5C5\uC790 \uC8FC\uC18C \uAE30\uC900\uC774\uBBC0\uB85C \uD589\uC0AC\uC7A5 \uC704\uCE58\uC640 \uBB34\uAD00\uD558\uAC8C \uC4F8 \uC218 \uC788\uC9C0\uB9CC \uC5C5\uC885\uACFC \uC601\uC5C5 \uD615\uD0DC\uB294 \uB4F1\uB85D \uC815\uBCF4\uC640 \uB9DE\uC544\uC57C \uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uD589\uC0AC \uACB0\uC81C\uC5D0 \uB9DE\uB294 \uAE30\uAE30\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC804\uC6D0 \uCF58\uC13C\uD2B8\uAC00 \uC5C6\uB294 \uACF3\uC774 \uB9CE\uC544 \uBC30\uD130\uB9AC \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uAE34 \uAE30\uAE30\uC640 \uC608\uBE44 \uBC30\uD130\uB9AC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "LTE \uBC29\uC2DD\uC774\uBA74 \uC2A4\uB9C8\uD2B8\uD3F0 \uC5C6\uC774 \uACB0\uC81C\uAC00 \uB418\uC5B4 \uC5EC\uB7EC \uC0AC\uB78C\uC774 \uBC88\uAC08\uC544 \uBC1B\uAE30 \uD3B8\uD569\uB2C8\uB2E4.", "\uC190\uB2D8\uC774 \uB9CE\uC740 \uD589\uC0AC\uB294 \uACB0\uC81C \uC18D\uB3C4\uAC00 \uC911\uC694\uD558\uBBC0\uB85C \uD130\uCE58 \uACB0\uC81C\uC640 \uC0BD\uC785 \uACB0\uC81C\uAC00 \uBAA8\uB450 \uB418\uB294 \uAE30\uAE30\uB97C \uACE0\uB985\uB2C8\uB2E4.", "\uC601\uC218\uC99D \uCD9C\uB825\uC744 \uC694\uAD6C\uD558\uB294 \uC190\uB2D8\uC774 \uB9CE\uC73C\uBA74 \uD504\uB9B0\uD130 \uB0B4\uC7A5\uD615\uC744, \uC544\uB2C8\uBA74 \uC804\uC790 \uC601\uC218\uC99D\uC73C\uB85C \uB300\uC2E0\uD569\uB2C8\uB2E4.", "\uC57C\uC678\uB294 \uD587\uBE5B\uC5D0 \uD654\uBA74\uC774 \uC548 \uBCF4\uC77C \uC218 \uC788\uC5B4 \uD654\uBA74 \uBC1D\uAE30 \uC870\uC808\uC774 \uB418\uB294 \uAE30\uAE30\uAC00 \uD3B8\uD569\uB2C8\uB2E4.", "\uBE44\uB098 \uBA3C\uC9C0\uAC00 \uC788\uB294 \uD658\uACBD\uC774\uBA74 \uBCF4\uD638 \uCF00\uC774\uC2A4\uB97C \uD568\uAED8 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uAC12\uACFC \uB2E8\uAE30 \uC784\uB300 \uC870\uAC74\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC5EC\uB7EC \uBA85\uC774 \uACB0\uC81C\uB97C \uBC1B\uC73C\uBA74 \uAE30\uAE30 \uBC88\uD638\uBCC4\uB85C \uB2F4\uB2F9\uC744 \uC815\uD574 \uC601\uC218\uC99D \uAD00\uB9AC\uAC00 \uC11E\uC774\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD130\uCE58 \uACB0\uC81C\uAC00 \uB418\uB294 \uAE30\uAE30\uB294 \uC190\uB2D8\uC774 \uCE74\uB4DC\uB97C \uAEBC\uB0B4\uB294 \uC2DC\uAC04\uC744 \uC904\uC5EC \uC904\uC774 \uBE68\uB9AC \uBE60\uC9D1\uB2C8\uB2E4.", "\uD587\uBE5B\uC774 \uAC15\uD55C \uC57C\uC678\uB294 \uD654\uBA74 \uBC1D\uAE30\uB97C \uBBF8\uB9AC \uC62C\uB824 \uB450\uBA74 \uC190\uB2D8\uC774 \uAE08\uC561\uC744 \uBC14\uB85C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uB450 \uB300\uB97C \uC900\uBE44\uD558\uBA74 \uD55C \uB300\uAC00 \uCDA9\uC804 \uC911\uC77C \uB54C\uB3C4 \uACB0\uC81C\uAC00 \uC774\uC5B4\uC9D1\uB2C8\uB2E4."] }, { "h": "\uB2E8\uAE30 \uC0AC\uC6A9\uC740 \uC5B4\uB5BB\uAC8C \uC900\uBE44\uD558\uB098\uC694?", "p": ["\uBA70\uCE60\uB9CC \uC4F8 \uB54C\uB294 \uB2E8\uAE30 \uC784\uB300\uAC00 \uB418\uB294\uC9C0, \uB418\uBA74 \uCD5C\uC18C \uAE30\uAC04\uC774 \uC5BC\uB9C8\uC778\uC9C0 \uBB3B\uC2B5\uB2C8\uB2E4.", "\uAE30\uC874 \uB9E4\uC7A5 \uAE30\uAE30\uB97C \uB4E4\uACE0 \uAC00\uB294 \uBC29\uBC95\uB3C4 \uC788\uC9C0\uB9CC \uADF8\uB3D9\uC548 \uB9E4\uC7A5 \uACB0\uC81C\uAC00 \uBE44\uBBC0\uB85C \uC608\uBE44 \uAE30\uAE30\uB97C \uB461\uB2C8\uB2E4.", "\uD589\uC0AC \uC804\uB0A0 \uACB0\uC81C\xB7\uCDE8\uC18C \uD14C\uC2A4\uD2B8\uC640 \uC644\uCDA9\uC744 \uB9C8\uCE58\uACE0, \uB2F9\uC77C \uC544\uCE68 \uD1B5\uC2E0 \uC0C1\uD0DC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD589\uC0AC\uC7A5 \uD1B5\uC2E0 \uC2E0\uD638\uAC00 \uC57D\uD55C \uACF3\uC774\uBA74 \uBBF8\uB9AC \uD604\uC7A5\uC5D0\uC11C \uC2A4\uB9C8\uD2B8\uD3F0 \uC2E0\uD638\uB97C \uD655\uC778\uD574 \uBD05\uB2C8\uB2E4.", "\uD604\uAE08\uACFC \uACC4\uC88C\uC774\uCCB4\uB97C \uD568\uAED8 \uBC1B\uB294\uB2E4\uBA74 \uD604\uAE08\uC601\uC218\uC99D \uBC1C\uAE09 \uBC29\uBC95\uB3C4 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uD589\uC0AC \uB4A4 \uBC18\uB0A9 \uAE30\uD55C\uACFC \uBC29\uBC95\uC744 \uBC1B\uC544 \uB450\uACE0 \uBC18\uB0A9 \uD655\uC778\uC99D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD589\uC0AC \uC8FC\uCD5C \uCE21\uC774 \uACB0\uC81C \uBC29\uC2DD\uC744 \uC9C0\uC815\uD558\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uCC38\uAC00 \uC548\uB0B4\uBB38\uC758 \uACB0\uC81C \uC870\uD56D\uC744 \uBA3C\uC800 \uC77D\uC2B5\uB2C8\uB2E4.", "\uD589\uC0AC \uC804\uB0A0 \uD14C\uC2A4\uD2B8 \uACB0\uC81C\uB294 \uC2B9\uC778 \uB4A4 \uCDE8\uC18C\uAE4C\uC9C0 \uD574 \uC601\uC218\uC99D \uB450 \uC7A5\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uB2E8\uAE30 \uC784\uB300 \uAE30\uAE30\uB294 \uBC1B\uC740 \uB0A0 \uACB0\uC81C \uD14C\uC2A4\uD2B8\uB97C \uD574 \uC791\uB3D9 \uC5EC\uBD80\uB97C \uD655\uC778\uD558\uACE0 \uBB38\uC81C\uAC00 \uC788\uC73C\uBA74 \uBC14\uB85C \uAD50\uD658\uC744 \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD589\uC0AC \uAE30\uAC04\uC774 \uAE38\uBA74 \uB2E8\uAE30 \uC784\uB300\uBCF4\uB2E4 \uC6D4 \uC784\uB300\uAC00 \uC801\uAC8C \uB4DC\uB294 \uACBD\uC6B0\uAC00 \uC788\uC5B4 \uAE30\uAC04\uC73C\uB85C \uBE44\uAD50\uD569\uB2C8\uB2E4."] }, { "h": "\uAC00\uB9F9\uC810 \uB4F1\uB85D\uC740 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uAC00\uB9F9\uC810\uC740 \uC0AC\uC5C5\uC790\uB4F1\uB85D \uC8FC\uC18C\uB85C \uB4F1\uB85D\uB418\uBBC0\uB85C \uD589\uC0AC\uC7A5 \uC704\uCE58\uAC00 \uB2EC\uB77C\uB3C4 \uAC19\uC740 \uAC00\uB9F9\uC810\uC73C\uB85C \uACB0\uC81C\uB429\uB2C8\uB2E4.", "\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC774 \uC5C6\uB294 \uAC1C\uC778\uC740 \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uC548 \uB418\uBBC0\uB85C \uD589\uC0AC \uC8FC\uCD5C \uCE21 \uACB0\uC81C \uC2DC\uC2A4\uD15C\uC744 \uC4F0\uAC70\uB098 \uB4F1\uB85D\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uC5C5\uC885\uC774 \uB4F1\uB85D \uC815\uBCF4\uC640 \uD06C\uAC8C \uB2E4\uB974\uBA74 \uAC00\uB9F9\uC810 \uC2EC\uC0AC\uC5D0\uC11C \uBB38\uC81C\uAC00 \uB420 \uC218 \uC788\uC5B4 \uBBF8\uB9AC \uD655\uC778\uD569\uB2C8\uB2E4.", "\uD478\uB4DC\uD2B8\uB7ED\uC740 \uC601\uC5C5 \uD5C8\uAC00 \uC9C0\uC5ED\uACFC \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC774 \uC788\uC5B4\uC57C \uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uB429\uB2C8\uB2E4.", "\uC815\uC0B0\uC740 \uB9E4\uC7A5 \uAC00\uB9F9\uC810 \uC815\uC0B0\uC11C\uB85C \uB4E4\uC5B4\uC624\uBBC0\uB85C \uD589\uC0AC \uB9E4\uCD9C\uC744 \uB530\uB85C \uC801\uC5B4 \uB450\uBA74 \uAD6C\uBD84\uC774 \uB429\uB2C8\uB2E4.", "\uB2E8\uAE30 \uC784\uB300 \uAE30\uAE30\uB294 \uBC18\uB0A9 \uAE30\uD55C\uC744 \uB118\uAE30\uBA74 \uCD94\uAC00 \uC774\uC6A9\uB8CC\uAC00 \uBD99\uC73C\uBBC0\uB85C \uD589\uC0AC \uB2E4\uC74C \uB0A0 \uBC14\uB85C \uBCF4\uB0C5\uB2C8\uB2E4.", "\uD589\uC0AC \uC8FC\uCD5C \uCE21 \uBD80\uC2A4 \uBC88\uD638\uB098 \uC7A5\uC18C\uB97C \uACB0\uC81C \uBA54\uBAA8\uC5D0 \uB0A8\uAE38 \uC218 \uC788\uB294 \uAE30\uAE30\uBA74 \uC815\uC0B0 \uAD6C\uBD84\uC774 \uC27D\uC2B5\uB2C8\uB2E4.", "\uC5C5\uC885\uC774 \uB2E4\uB978 \uD589\uC0AC(\uC608: \uC2DD\uD488 \uC678 \uD310\uB9E4)\uC5D0 \uCC38\uC5EC\uD558\uBA74 \uAC00\uB9F9\uC810 \uC5C5\uC885\uACFC \uB2EC\uB77C \uC2EC\uC0AC\uC5D0\uC11C \uBB3B\uB294 \uACBD\uC6B0\uAC00 \uC788\uC73C\uB2C8 \uBBF8\uB9AC \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uD604\uC7A5 \uC6B4\uC601\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uACB0\uC81C \uB2F4\uB2F9\uC790\uB97C \uC815\uD558\uACE0 \uCDE8\uC18C \uBC29\uBC95\uC744 \uC54C\uB824 \uB450\uC5B4 \uC904\uC774 \uBC00\uB9B4 \uB54C\uB3C4 \uCC98\uB9AC\uAC00 \uB429\uB2C8\uB2E4.", "\uAE30\uAE30 \uB450 \uB300\uB97C \uBC88\uAC08\uC544 \uC4F0\uBA74 \uBC30\uD130\uB9AC\uC640 \uACE0\uC7A5\uC5D0 \uB300\uBE44\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uC601\uC218\uC99D \uBB36\uC74C\uC744 \uB0A0\uC9DC\uBCC4\uB85C \uBCF4\uAD00\uD574 \uC815\uC0B0\uC11C\uC640 \uB300\uC870\uD569\uB2C8\uB2E4.", "\uD589\uC0AC \uC911 \uAE30\uAE30\uAC00 \uBA48\uCD94\uBA74 \uC804\uC6D0 \uC7AC\uC2DC\uC791\uACFC \uD1B5\uC2E0 \uD655\uC778\uC744 \uBA3C\uC800 \uD558\uACE0, \uC548 \uB418\uBA74 \uC608\uBE44 \uAE30\uAE30\uB85C \uBC14\uAFC9\uB2C8\uB2E4.", "\uD589\uC0AC \uC815\uC0B0\uC11C\uC5D0\uC11C \uC2B9\uC778 \uAC74\uC218\uC640 \uC601\uC218\uC99D \uBB36\uC74C \uC218\uB97C \uB9DE\uCDB0 \uBCF4\uBA74 \uB204\uB77D \uACB0\uC81C\uAC00 \uBC14\uB85C \uBCF4\uC785\uB2C8\uB2E4.", "\uD604\uC7A5\uC5D0\uC11C \uACB0\uC81C\uAC00 \uC548 \uB420 \uB54C\uB97C \uB300\uBE44\uD574 \uACC4\uC88C\uC774\uCCB4 \uC548\uB0B4\uBB38\uC744 \uC900\uBE44\uD569\uB2C8\uB2E4.", "\uACB0\uC81C \uB2F4\uB2F9\uC774 \uBC14\uB014 \uB54C \uAE30\uAE30 \uBC88\uD638\uC640 \uC601\uC218\uC99D \uBB36\uC74C\uC744 \uD568\uAED8 \uB118\uAE30\uB3C4\uB85D \uC815\uD569\uB2C8\uB2E4.", "\uD589\uC0AC\uAC00 \uB05D\uB098\uBA74 \uAE30\uAE30 \uBC88\uD638\uBCC4 \uC601\uC218\uC99D \uBB36\uC74C\uACFC \uC815\uC0B0\uC11C\uB97C \uB300\uC870\uD574 \uB204\uB77D \uACB0\uC81C\uB97C \uCC3E\uC2B5\uB2C8\uB2E4.", "\uD589\uC0AC \uB4A4 \uBC18\uB0A9 \uC804\uC5D0 \uAE30\uAE30 \uC548 \uC601\uC218\uC99D \uB0B4\uC5ED\uC744 \uCD9C\uB825\uD558\uAC70\uB098 \uC804\uC1A1\uD574 \uB450\uBA74 \uC815\uC0B0 \uB300\uC870\uAC00 \uC27D\uC2B5\uB2C8\uB2E4."] }], "steps": { "h": "\uD589\uC0AC \uC900\uBE44 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uD589\uC0AC \uAE30\uAC04\uACFC \uC608\uC0C1 \uACB0\uC81C \uAC74\uC218\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uB2E8\uAE30 \uC784\uB300 \uB610\uB294 \uC608\uBE44 \uAE30\uAE30 \uC900\uBE44 \uC5EC\uBD80\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uC804\uB0A0 \uC644\uCDA9\xB7\uD14C\uC2A4\uD2B8 \uACB0\uC81C\xB7\uC6A9\uC9C0 \uC900\uBE44\uB97C \uD569\uB2C8\uB2E4.", "\uB2F9\uC77C \uD1B5\uC2E0 \uC0C1\uD0DC\uB97C \uD655\uC778\uD558\uACE0 \uACB0\uC81C \uB2F4\uB2F9\uC790\uB97C \uC815\uD569\uB2C8\uB2E4.", "\uD589\uC0AC \uB4A4 \uBC18\uB0A9\uACFC \uC815\uC0B0\uC11C \uB300\uC870\uB97C \uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD589\uC0AC \uACB0\uC81C \uC900\uBE44 \uD56D\uBAA9", "head": ["\uD56D\uBAA9", "\uC900\uBE44", "\uC5C6\uC73C\uBA74"], "rows": [["\uC804\uC6D0", "\uC644\uCDA9+\uC608\uBE44 \uBC30\uD130\uB9AC", "\uC624\uD6C4 \uACB0\uC81C \uC911\uB2E8"], ["\uD1B5\uC2E0", "LTE\xB7\uD604\uC7A5 \uC2E0\uD638 \uD655\uC778", "\uACB0\uC81C \uC9C0\uC5F0"], ["\uC601\uC218\uC99D", "\uB0B4\uC7A5 \uD504\uB9B0\uD130 \uB610\uB294 \uC804\uC790", "\uC190\uB2D8 \uC694\uCCAD \uB300\uC751 \uBD88\uAC00"], ["\uC608\uBE44 \uAE30\uAE30", "1\uB300", "\uACE0\uC7A5 \uB54C \uACB0\uC81C \uBD88\uAC00"], ["\uBC18\uB0A9", "\uAE30\uD55C\xB7\uBC29\uBC95\xB7\uD655\uC778\uC99D", "\uCD94\uAC00 \uCCAD\uAD6C"]] }, "faq": [["\uC0AC\uC5C5\uC790\uB4F1\uB85D \uC5C6\uC774 \uD589\uC0AC\uC5D0\uC11C \uCE74\uB4DC\uB97C \uBC1B\uC744 \uC218 \uC788\uB098\uC694?", "\uAC00\uB9F9\uC810 \uB4F1\uB85D\uC774 \uC548 \uB418\uBBC0\uB85C \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uC8FC\uCD5C \uCE21 \uC2DC\uC2A4\uD15C\uC774\uB098 \uC0AC\uC5C5\uC790\uB4F1\uB85D\uC774 \uD544\uC694\uD569\uB2C8\uB2E4."], ["\uD558\uB8E8\uB9CC \uBE4C\uB9B4 \uC218 \uC788\uB098\uC694?", "\uB2E8\uAE30 \uC784\uB300 \uCD5C\uC18C \uAE30\uAC04\uC740 \uC5C5\uCCB4\uB9C8\uB2E4 \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."], ["\uB9E4\uC7A5 \uAE30\uAE30\uB97C \uB4E4\uACE0 \uB098\uAC00\uB3C4 \uB418\uB098\uC694?", "\uB429\uB2C8\uB2E4. \uADF8\uB3D9\uC548 \uB9E4\uC7A5 \uACB0\uC81C\uAC00 \uBE44\uBBC0\uB85C \uC608\uBE44 \uAE30\uAE30\uB97C \uB461\uB2C8\uB2E4."], ["\uD589\uC0AC \uB9E4\uCD9C\uC740 \uC815\uC0B0\uC774 \uB530\uB85C \uC624\uB098\uC694?", "\uAC19\uC740 \uAC00\uB9F9\uC810\uC774\uBA74 \uB9E4\uC7A5 \uC815\uC0B0\uC11C\uB85C \uD569\uCCD0 \uB4E4\uC5B4\uC635\uB2C8\uB2E4. \uD589\uC0AC \uB9E4\uCD9C\uC744 \uB530\uB85C \uC801\uC5B4 \uB450\uBA74 \uAD6C\uBD84\uB429\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBE14\uB8E8\uD22C\uC2A4LTE", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uD130\uB9AC\uAD50\uCCB4"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD574\uC9C0\uBC18\uB0A9", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uD574\uC9C0\xB7\uBC18\uB0A9", "title": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uD574\uC9C0\uC640 \uBC18\uB0A9\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694? \u2014 \uAE30\uAE30\xB7\uD68C\uC120\xB7\uAC00\uB9F9\uC810 \uC138 \uAC00\uC9C0 \uC815\uB9AC", "desc": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uD574\uC9C0\uD560 \uB54C \uAE30\uAE30 \uC57D\uC815 \uD574\uC9C0, \uD1B5\uC2E0 \uD68C\uC120 \uD574\uC9C0, \uAC00\uB9F9\uC810 \uC815\uB9AC\uB97C \uAC01\uAC01 \uCC98\uB9AC\uD558\uB294 \uC21C\uC11C\uC640 \uBC18\uB0A9 \uD488\uBAA9, \uC57D\uC815 \uC911 \uD574\uC9C0 \uC870\uAC74, \uBBF8\uC815\uC0B0 \uB9E4\uCD9C\uACFC \uB9C8\uC9C0\uB9C9 \uCCAD\uAD6C\uC11C \uD655\uC778, \uAE30\uC0AC\uC5D0\uAC8C \uB098\uAC04 \uAE30\uAE30 \uD68C\uC218 \uBC29\uBC95\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uD574\uC9C0\uB294 \uAE30\uAE30 \uC57D\uC815 \uD574\uC9C0, \uD1B5\uC2E0 \uD68C\uC120 \uD574\uC9C0, \uD544\uC694\uD558\uBA74 \uAC00\uB9F9\uC810 \uC815\uB9AC \uC138 \uAC00\uC9C0\uB97C \uB530\uB85C \uD574\uC57C \uB05D\uB098\uBA70, \uD68C\uC120\uC744 \uBE7C\uBA39\uC73C\uBA74 \uD1B5\uC2E0\uBE44\uAC00 \uACC4\uC18D \uB098\uAC11\uB2C8\uB2E4. \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC558\uC73C\uBA74 \uAE30\uAE30\uC640 \uD68C\uC120 \uAC01\uAC01\uC5D0 \uC911\uB3C4 \uD574\uC9C0 \uC870\uAC74\uC774 \uC788\uC744 \uC218 \uC788\uC73C\uBBC0\uB85C \uB450 \uC870\uD56D\uC744 \uCC3E\uC544 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uD68C\uC218\uC640 \uD655\uC778\uC740 \uBB34\uC5C7\uBD80\uD130 \uD558\uB098\uC694?", "p": ["\uAE30\uC0AC\uC5D0\uAC8C \uB098\uAC00 \uC788\uB294 \uAE30\uAE30\uB97C \uBAA8\uB450 \uD68C\uC218\uD574 \uB300\uC218\uC640 \uC0C1\uD0DC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0\uC11C \uAE30\uAE30 \uC911\uB3C4 \uD574\uC9C0 \uC870\uD56D\uACFC \uD68C\uC120 \uD574\uC9C0 \uC870\uD56D\uC744 \uAC01\uAC01 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uBBF8\uC815\uC0B0 \uB9E4\uCD9C\uC774 \uB0A8\uC544 \uC788\uB294\uC9C0 \uC815\uC0B0\uC11C\uB85C \uBCF4\uACE0, \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uAE4C\uC9C0 \uD1B5\uC7A5\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD488\uBAA9(\uAE30\uAE30\xB7\uBC30\uD130\uB9AC\xB7\uCDA9\uC804\uAE30\xB7\uC720\uC2EC)\uC744 \uC57D\uC815\uC11C \uD488\uBAA9\uACFC \uB300\uC870\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uC548 \uACB0\uC81C \uC124\uC815\uACFC \uB9E4\uC7A5 \uC815\uBCF4\uB97C \uCD08\uAE30\uD654\uD569\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAC00\uB9F9\uC810\uC744 \uC4F0\uACE0 \uC788\uB2E4\uBA74 \uAC00\uB9F9\uC810\uC740 \uC720\uC9C0\uD558\uACE0 \uAE30\uAE30 \uC57D\uC815\uB9CC \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC0AC\uC720\uAC00 \uD3D0\uC5C5\uC774\uBA74 \uC138\uBB34\uC11C \uD3D0\uC5C5 \uC2E0\uACE0\uC640 \uC21C\uC11C\uB97C \uB9DE\uCDA5\uB2C8\uB2E4.", "\uAE30\uAE30 \uD68C\uC218 \uB54C \uBC30\uD130\uB9AC\uC640 \uCDA9\uC804\uAE30\uB3C4 \uD568\uAED8 \uBC1B\uC544\uC57C \uBC18\uB0A9 \uD488\uBAA9\uC774 \uB9DE\uC2B5\uB2C8\uB2E4.", "\uD68C\uC218\uD55C \uAE30\uAE30\uB294 \uB9C8\uC9C0\uB9C9 \uACB0\uC81C \uB0A0\uC9DC\uB97C \uD655\uC778\uD574 \uADF8 \uB4A4 \uACB0\uC81C\uAC00 \uC5C6\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uD68C\uC218 \uB54C \uAE30\uAE30 \uC678\uAD00 \uC0AC\uC9C4\uC744 \uCC0D\uC5B4 \uB450\uBA74 \uBC18\uB0A9 \uB4A4 \uD30C\uC190 \uB2E4\uD23C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uAE30\uC0AC\uC5D0\uAC8C \uB098\uAC04 \uAE30\uAE30 \uC218\uC640 \uC7A5\uBD80 \uC218\uAC00 \uB2E4\uB974\uBA74 \uBA3C\uC800 \uBD84\uC2E4 \uC5EC\uBD80\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uD68C\uC218 \uB4A4 \uBC30\uD130\uB9AC\uB97C \uBD84\uB9AC\uD574 \uBCF4\uAD00\uD558\uBA74 \uBC18\uB0A9\uAE4C\uC9C0\uC758 \uAE30\uAC04 \uB3D9\uC548 \uBC30\uD130\uB9AC \uC190\uC0C1\uC744 \uB9C9\uC2B5\uB2C8\uB2E4.", "\uD68C\uC218\uD55C \uAE30\uAE30\uC758 \uB9C8\uC9C0\uB9C9 \uCDA9\uC804 \uC0C1\uD0DC\uB97C \uD655\uC778\uD558\uACE0 \uBC18\uB0A9 \uC804\uAE4C\uC9C0 \uC804\uC6D0\uC744 \uAEBC \uB461\uB2C8\uB2E4."] }, { "h": "\uD574\uC9C0 \uC2E0\uCCAD\uC740 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uAE30\uAE30 \uC57D\uC815 \uD574\uC9C0\uC640 \uD68C\uC120 \uD574\uC9C0\uB97C \uAC01\uAC01 \uAE00\uB85C \uC2E0\uCCAD\uD558\uACE0 \uC811\uC218 \uBC88\uD638\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uC608\uC815\uC77C\uC744 \uC815\uD574 \uADF8\uB0A0\uAE4C\uC9C0 \uC774\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uBE44\uAC00 \uC815\uC0B0\uB418\uB3C4\uB85D \uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uBC29\uBC95(\uD0DD\uBC30\xB7\uBC29\uBB38 \uD68C\uC218)\uACFC \uAE30\uD55C\uC744 \uBC1B\uC544 \uB450\uACE0 \uBC18\uB0A9 \uD655\uC778\uC99D\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uBD84\uC2E4 \uAE30\uAE30\uAC00 \uC788\uC73C\uBA74 \uBD84\uC2E4 \uCC98\uB9AC\uC640 \uBE44\uC6A9 \uC870\uAC74\uC744 \uD568\uAED8 \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uD655\uC778\uC11C\uC5D0 \uD574\uC9C0\uC77C\uACFC \uB0A8\uC740 \uCCAD\uAD6C \uAE08\uC561\uC774 \uC801\uD600 \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uC870\uAC74\uACFC \uBE44\uC6A9\uC740 \uC5C5\uCCB4\uC640 \uD1B5\uC2E0\uC0AC\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC18\uB0A9 \uC804 \uAE30\uAE30 \uBC88\uD638\uC640 \uD68C\uC120 \uBC88\uD638\uB97C \uC9DD\uC9C0\uC5B4 \uC801\uC5B4 \uB450\uBA74 \uC5B4\uB290 \uD68C\uC120\uC774 \uD574\uC9C0\uB410\uB294\uC9C0 \uD655\uC778\uD558\uAE30 \uC27D\uC2B5\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD\uC11C\uC5D0 \uAE30\uAE30 \uBC88\uD638\uC640 \uD68C\uC120 \uBC88\uD638\uB97C \uBAA8\uB450 \uC801\uC73C\uBA74 \uD55C\uCABD\uC774 \uB204\uB77D\uB418\uB294 \uC77C\uC774 \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", "\uD574\uC9C0 \uC608\uC815\uC77C \uC804\uB0A0\uAE4C\uC9C0 \uD604\uC7A5 \uACB0\uC81C\uB97C \uBC1B\uACE0 \uADF8\uB0A0 \uC774\uD6C4 \uACB0\uC81C\uB294 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB85C \uBC1B\uB3C4\uB85D \uAE30\uC0AC\uC5D0\uAC8C \uC54C\uB9BD\uB2C8\uB2E4.", "\uD574\uC9C0 \uC2E0\uCCAD \uC811\uC218 \uBC88\uD638\uB294 \uAE30\uAE30 \uC57D\uC815\uACFC \uD68C\uC120 \uC57D\uC815 \uAC01\uAC01 \uB530\uB85C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uD574\uC9C0 \uC608\uC815\uC77C\uC744 \uAE30\uC0AC \uC804\uC6D0\uC5D0\uAC8C \uC54C\uB824 \uADF8\uB0A0 \uC774\uD6C4 \uAE30\uAE30\uB97C \uB4E4\uACE0 \uB098\uAC00\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4."] }, { "h": "\uC57D\uC815 \uC911 \uD574\uC9C0\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "p": ["\uAE30\uAE30 \uC57D\uC815 \uAE30\uAC04\uC774 \uB0A8\uC73C\uBA74 \uB0A8\uC740 \uAE30\uAC04 \uC870\uAC74\uC774 \uBD99\uACE0, \uD68C\uC120 \uC57D\uC815\uB3C4 \uB530\uB85C \uC870\uAC74\uC774 \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC740\uD488\uC774\uB098 \uAC1C\uD1B5\uBE44 \uC9C0\uC6D0\uC744 \uBC1B\uC558\uB2E4\uBA74 \uBC18\uD658 \uC870\uD56D\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uB300\uC218 \uC77C\uBD80\uB9CC \uC904\uC774\uB294 \uAC10\uCD95\uC740 \uC870\uAC74\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4 \uAC10\uCD95 \uC870\uD56D\uC744 \uBA3C\uC800 \uBD05\uB2C8\uB2E4.", "\uD3D0\uC5C5 \uC99D\uBE59\uC73C\uB85C \uC870\uAC74\uC774 \uB2EC\uB77C\uC9C0\uB294 \uC5C5\uCCB4\uAC00 \uC788\uC73C\uB2C8 \uC0AC\uC720\uB97C \uC54C\uB9BD\uB2C8\uB2E4.", "\uC0B0\uC815 \uBC29\uC2DD\uC774 \uC5C6\uB294 \uCCAD\uAD6C\uB294 \uADFC\uAC70\uB97C \uAE00\uB85C \uC694\uCCAD\uD569\uB2C8\uB2E4.", "\uD574\uC9C0 \uC0AC\uC720\uAC00 \uBC30\uB2EC \uC911\uB2E8\uC774\uBA74 \uAC00\uB9F9\uC810\uC740 \uC720\uC9C0\uD558\uACE0 \uAE30\uAE30\xB7\uD68C\uC120\uB9CC \uC815\uB9AC\uD574 \uB098\uC911\uC5D0 \uC7AC\uAC1C\uD558\uAE30 \uC27D\uAC8C \uB461\uB2C8\uB2E4.", "\uAC10\uCD95\uACFC \uC804\uCCB4 \uD574\uC9C0\uC758 \uC870\uAC74\uC744 \uBE44\uAD50\uD574 \uBC30\uB2EC\uC744 \uC904\uC774\uB294 \uB9E4\uC7A5\uC740 \uAC10\uCD95\uC73C\uB85C \uB450\uB294 \uCABD\uC774 \uC7AC\uAC1C\uAC00 \uC27D\uC2B5\uB2C8\uB2E4.", "\uD3D0\uC5C5\uC774 \uC0AC\uC720\uBA74 \uC138\uBB34\uC11C \uD3D0\uC5C5 \uC2E0\uACE0 \uB4A4 \uD3D0\uC5C5\uC0AC\uC2E4\uC99D\uBA85\uC6D0\uC744 \uC5C5\uCCB4\uC5D0 \uB0B4\uBA74 \uC870\uAC74\uC774 \uB2EC\uB77C\uC9C0\uB294 \uACBD\uC6B0\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", "\uAC10\uCD95\uACFC \uC804\uCCB4 \uD574\uC9C0\uC758 \uC704\uC57D \uC870\uAC74\uC774 \uB2E4\uB974\uBA74 \uB450 \uAE08\uC561\uC744 \uBC1B\uC544 \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uC704\uC57D \uC870\uAC74\uC774 \uC5C6\uB294 \uC57D\uC815 \uC885\uB8CC \uB4A4 \uD574\uC9C0\uB294 \uBC18\uB0A9\uACFC \uD68C\uC120 \uD574\uC9C0\uB9CC \uD558\uBA74 \uB05D\uB0A9\uB2C8\uB2E4."] }, { "h": "\uD68C\uC120\xB7\uAE30\uAE30 \uD574\uC9C0 \uB4A4 \uBB34\uC5C7\uC744 \uCC59\uAE30\uB098\uC694?", "p": ["\uB2E4\uC74C \uB2EC \uCCAD\uAD6C\uC11C\uC5D0 \uC774\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uBE44\uAC00 \uBE60\uC84C\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uBC18\uB0A9 \uD655\uC778\uC99D, \uD574\uC9C0 \uD655\uC778\uC11C, \uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uC11C\uB97C \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4.", "\uD1B5\uC2E0\uBE44\uB098 \uC774\uC6A9\uB8CC\uAC00 \uD574\uC9C0 \uB4A4\uC5D0\uB3C4 \uBE60\uC838\uB098\uAC00\uBA74 \uC811\uC218 \uBC88\uD638\uB97C \uB4E4\uACE0 \uBB38\uC758\uD558\uACE0 \uC790\uB3D9\uC774\uCCB4\uB97C \uC815\uB9AC\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uC6B4\uC601\uC744 \uACC4\uC18D\uD55C\uB2E4\uBA74 \uC571 \uC120\uACB0\uC81C\uC640 \uB9C1\uD06C \uACB0\uC81C\uB85C \uD604\uC7A5 \uACB0\uC81C\uB97C \uB300\uC2E0\uD560 \uBC29\uBC95\uC744 \uB461\uB2C8\uB2E4.", "\uAC10\uCD95\uC774\uBA74 \uB0A8\uC740 \uAE30\uAE30\uC758 \uD1B5\uC2E0 \uC694\uAE08\uACFC \uC774\uC6A9\uB8CC\uAC00 \uBC14\uB00C\uB294\uC9C0 \uBC14\uB010 \uCCAD\uAD6C \uC608\uC815\uC561\uC744 \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uC7AC\uAC1C\uD560 \uB54C\uB294 \uAC00\uB9F9\uC810\uC774 \uC0B4\uC544 \uC788\uC73C\uBA74 \uAE30\uAE30\uB9CC \uB2E4\uC2DC \uBC1B\uC544 \uB4F1\uB85D\uD558\uBA74 \uB429\uB2C8\uB2E4.", "\uC7AC\uAC1C \uAC00\uB2A5\uC131\uC774 \uC788\uC73C\uBA74 \uAE30\uAE30 \uC57D\uC815\uB9CC \uD574\uC9C0\uD558\uACE0 \uAC00\uB9F9\uC810\uC744 \uC720\uC9C0\uD558\uB294 \uCABD\uC774 \uC808\uCC28\uAC00 \uC9E7\uC2B5\uB2C8\uB2E4.", "\uB9C8\uC9C0\uB9C9 \uC815\uC0B0\uC11C\uAC00 \uB4E4\uC5B4\uC628 \uB4A4 \uD1B5\uC7A5\uC744 \uC815\uB9AC\uD558\uBA74 \uBBF8\uC815\uC0B0 \uB9E4\uCD9C\uC744 \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC7AC\uAC1C\uD560 \uB54C\uB97C \uB300\uBE44\uD574 \uAE30\uC0AC \uAD50\uC721 \uC790\uB8CC\uC640 \uAE30\uAE30 \uC7A5\uBD80 \uC591\uC2DD\uC744 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uD574\uC9C0 \uC808\uCC28\uB294 \uC5B4\uB5A4 \uC21C\uC11C\uC778\uAC00\uC694?", "items": ["\uAE30\uC0AC\uC5D0\uAC8C \uB098\uAC04 \uAE30\uAE30\uB97C \uD68C\uC218\uD558\uACE0 \uC0C1\uD0DC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC57D\uC815\uC11C\uC5D0\uC11C \uAE30\uAE30\xB7\uD68C\uC120 \uD574\uC9C0 \uC870\uD56D\uC744 \uCC3E\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30 \uD574\uC9C0\uC640 \uD68C\uC120 \uD574\uC9C0\uB97C \uAC01\uAC01 \uC2E0\uCCAD\uD569\uB2C8\uB2E4.", "\uCD08\uAE30\uD654\uD55C \uAE30\uAE30\uB97C \uBC18\uB0A9\uD558\uACE0 \uD655\uC778\uC99D\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.", "\uB2E4\uC74C \uCCAD\uAD6C\uC11C\uC5D0\uC11C \uAE30\uAE30 \uC774\uC6A9\uB8CC\uC640 \uD1B5\uC2E0\uBE44\uAC00 \uD568\uAED8 \uBE60\uC84C\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uD574\uC9C0 \uD56D\uBAA9\uBCC4 \uCC98\uB9AC", "head": ["\uD56D\uBAA9", "\uC2E0\uCCAD\uCC98", "\uC99D\uBE59"], "rows": [["\uAE30\uAE30 \uC57D\uC815", "\uC124\uCE58\uC5C5\uCCB4\xB7\uBC34\uC0AC", "\uD574\uC9C0 \uD655\uC778\uC11C"], ["\uD1B5\uC2E0 \uD68C\uC120", "\uC5C5\uCCB4 \uB610\uB294 \uD1B5\uC2E0\uC0AC", "\uD68C\uC120 \uD574\uC9C0 \uD655\uC778"], ["\uAC00\uB9F9\uC810", "\uC720\uC9C0 \uB610\uB294 \uCE74\uB4DC\uC0AC \uD574\uC9C0", "\uCE74\uB4DC\uC0AC \uC548\uB0B4"], ["\uBC18\uB0A9", "\uC5C5\uCCB4", "\uBC18\uB0A9 \uD655\uC778\uC99D"]] }, "faq": [["\uAE30\uAE30\uB9CC \uD574\uC9C0\uD558\uBA74 \uD1B5\uC2E0\uBE44\uB3C4 \uBA48\uCD94\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uD68C\uC120 \uD574\uC9C0\uB97C \uB530\uB85C \uD574\uC57C \uD569\uB2C8\uB2E4."], ["\uAE30\uC0AC\uAC00 \uAE30\uAE30\uB97C \uC548 \uB3CC\uB824\uC8FC\uBA74\uC694?", "\uBD84\uC2E4 \uCC98\uB9AC\uB85C \uD68C\uC120\uC744 \uC815\uC9C0\uD558\uACE0 \uBE44\uC6A9 \uC870\uAC74\uC740 \uC57D\uC815\uC11C\uC5D0 \uB530\uB985\uB2C8\uB2E4."], ["\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB294 \uADF8\uB300\uB85C \uB450\uACE0 \uBB34\uC120\uAE30\uB9CC \uD574\uC9C0\uB418\uB098\uC694?", "\uB429\uB2C8\uB2E4. \uAC19\uC740 \uAC00\uB9F9\uC810\uC774\uBA74 \uAC00\uB9F9\uC810\uC740 \uC720\uC9C0\uD569\uB2C8\uB2E4."], ["\uD574\uC9C0 \uB4A4 \uBC30\uB2EC \uD604\uC7A5 \uACB0\uC81C\uB294 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "\uC571 \uC120\uACB0\uC81C\uB098 \uB9C1\uD06C \uACB0\uC81C\uB85C \uB300\uC2E0\uD558\uAC70\uB098 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uB85C \uB3CC\uC544\uC640 \uBC1B\uC2B5\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uD574\uC9C0\uC704\uC57D\uAE08", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD1B5\uC2E0\uBE44\uC720\uC2EC", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uD130\uB9AC\uAD50\uCCB4", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uBC30\uD130\uB9AC\xB7\uAD50\uCCB4", "title": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uBC30\uD130\uB9AC\uB294 \uC5B8\uC81C \uAD50\uCCB4\uD558\uB098\uC694? \u2014 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4DC\uB294 \uC2E0\uD638\uC640 \uB300\uCC98", "desc": "\uBB34\uC120\uB2E8\uB9D0\uAE30 \uBC30\uD130\uB9AC\uC758 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4DC\uB294 \uC2E0\uD638, \uAD50\uCCB4 \uAC00\uB2A5 \uBAA8\uB378\uACFC \uB0B4\uC7A5\uD615\uC758 \uCC28\uC774, \uAD50\uCCB4 \uBE44\uC6A9 \uC870\uAC74, \uCDA9\uC804 \uC2B5\uAD00\uC73C\uB85C \uC218\uBA85\uC744 \uB298\uB9AC\uB294 \uBC29\uBC95, \uBC30\uD130\uB9AC \uC678\uC5D0 \uAE30\uAE30 \uC790\uCCB4\uB97C \uBC14\uAFD4\uC57C \uD558\uB294 \uACBD\uC6B0\uC640 \uC810\uAC80 \uC21C\uC11C\uB97C \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uBC30\uD130\uB9AC\uB294 \uC644\uCDA9 \uB4A4 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uCC98\uC74C\uBCF4\uB2E4 \uB208\uC5D0 \uB744\uAC8C \uC9E7\uC544\uC838 \uD558\uB8E8 \uBC30\uB2EC\uC744 \uBABB \uBC84\uD2F8 \uB54C \uAD50\uCCB4\uD558\uBA70, \uAD50\uCCB4\uD615 \uBAA8\uB378\uC740 \uBC30\uD130\uB9AC\uB9CC \uBC14\uAFB8\uACE0 \uB0B4\uC7A5\uD615\uC740 \uC5C5\uCCB4 \uC218\uB9AC\uB098 \uAE30\uAE30 \uAD50\uCCB4\uAC00 \uB429\uB2C8\uB2E4. \uAD50\uCCB4 \uBE44\uC6A9\uACFC \uC870\uAC74\uC740 \uC57D\uC815\uACFC \uBAA8\uB378\uC5D0 \uB530\uB77C \uB2EC\uB77C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD558\uACE0, \uAD50\uCCB4 \uC804\uC5D0 \uCDA9\uC804 \uC2B5\uAD00\uACFC \uAC70\uCE58 \uBC29\uC2DD\uBD80\uD130 \uC810\uAC80\uD569\uB2C8\uB2E4.", "sections": [{ "h": "\uBC30\uD130\uB9AC\uB97C \uBC14\uAFC0 \uB54C\uAC00 \uB410\uB2E4\uB294 \uC2E0\uD638\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC644\uCDA9\uD574\uB3C4 \uC624\uD6C4\uC5D0 \uAEBC\uC9C0\uB294 \uC77C\uC774 \uBC18\uBCF5\uB418\uBA74 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4E0 \uAC83\uC785\uB2C8\uB2E4.", "\uCDA9\uC804 \uD45C\uC2DC\uAC00 100\uC5D0 \uAC00\uAE4C\uC6B4\uB370 \uAE08\uBC29 \uB5A8\uC5B4\uC9C0\uAC70\uB098, \uCD94\uC6B4 \uB0A0 \uAE09\uACA9\uD788 \uAEBC\uC9C0\uBA74 \uBC30\uD130\uB9AC \uB178\uD654 \uC2E0\uD638\uC785\uB2C8\uB2E4.", "\uAE30\uAE30 \uB4B7\uBA74\uC774 \uBD80\uD480\uAC70\uB098 \uC5F4\uC774 \uB9CE\uC774 \uB098\uBA74 \uBC14\uB85C \uC0AC\uC6A9\uC744 \uBA48\uCD94\uACE0 \uC5C5\uCCB4\uC5D0 \uC54C\uB9BD\uB2C8\uB2E4.", "\uCDA9\uC804\uC774 \uB418\uC9C0 \uC54A\uC73C\uBA74 \uCF00\uC774\uBE14\uACFC \uCDA9\uC804\uAE30\uBD80\uD130 \uBC14\uAFD4 \uBCF4\uACE0, \uADF8\uB798\uB3C4 \uC548 \uB418\uBA74 \uBC30\uD130\uB9AC\uB098 \uCDA9\uC804\uBD80 \uBB38\uC81C\uC785\uB2C8\uB2E4.", "\uD558\uB8E8 \uBC30\uB2EC \uAC74\uC218\uAC00 \uB298\uC5B4 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uBD80\uC871\uD55C \uACBD\uC6B0\uB294 \uB178\uD654\uAC00 \uC544\uB2C8\uB77C \uC6A9\uB7C9 \uBB38\uC81C\uC774\uBBC0\uB85C \uC608\uBE44 \uBC30\uD130\uB9AC\uB85C \uD574\uACB0\uD569\uB2C8\uB2E4.", "\uAE30\uC0AC\uBCC4\uB85C \uAE30\uAE30 \uC0AC\uC6A9 \uC2DC\uAC04\uC744 \uC801\uC5B4 \uB450\uBA74 \uC5B4\uB290 \uAE30\uAE30\uAC00 \uBA3C\uC800 \uAD50\uCCB4 \uB300\uC0C1\uC778\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uC2E0\uD638\uAC00 \uBCF4\uC774\uBA74 \uAD50\uCCB4 \uC804\uC5D0 \uC608\uBE44 \uAE30\uAE30\uB97C \uBA3C\uC800 \uC900\uBE44\uD574 \uACB0\uC81C \uACF5\uBC31\uC744 \uB9C9\uC2B5\uB2C8\uB2E4.", "\uC0AC\uC6A9 \uC2DC\uAC04 \uAE30\uB85D\uC740 \uAE30\uC0AC \uAD50\uB300 \uC7A5\uBD80\uC5D0 \uC644\uCDA9 \uC2DC\uAC01\uACFC \uAEBC\uC9C4 \uC2DC\uAC01\uC744 \uC801\uC73C\uBA74 \uB429\uB2C8\uB2E4.", "\uC0AC\uC6A9 \uC2DC\uAC04 \uAE30\uB85D\uC740 \uC644\uCDA9 \uC2DC\uAC01\uACFC \uAEBC\uC9C4 \uC2DC\uAC01 \uB450 \uAC1C\uB9CC \uC801\uC5B4\uB3C4 \uCDA9\uBD84\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uAC74\uC218\uAC00 \uB298\uC5B4 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uBD80\uC871\uD55C \uACBD\uC6B0\uB294 \uB178\uD654\uAC00 \uC544\uB2C8\uB77C \uC6A9\uB7C9 \uBB38\uC81C\uC774\uBBC0\uB85C \uC608\uBE44 \uBC30\uD130\uB9AC\uAC00 \uB2F5\uC785\uB2C8\uB2E4.", "\uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC904\uC5B4\uB4DC\uB294 \uC18D\uB3C4\uAC00 \uAE30\uAE30\uB9C8\uB2E4 \uB2E4\uB974\uBBC0\uB85C \uAC00\uC7A5 \uBA3C\uC800 \uC904\uC5B4\uB4E0 \uAE30\uAE30\uBD80\uD130 \uAD50\uCCB4 \uC21C\uC11C\uB97C \uC815\uD569\uB2C8\uB2E4."] }, { "h": "\uAD50\uCCB4\uB294 \uC5B4\uB5BB\uAC8C \uD558\uB098\uC694?", "p": ["\uAD50\uCCB4\uD615 \uBAA8\uB378\uC740 \uC815\uD488 \uBC30\uD130\uB9AC\uB97C \uBC1B\uC544 \uB9E4\uC7A5\uC5D0\uC11C \uBC14\uAFC0 \uC218 \uC788\uACE0, \uBE44\uC815\uD488\uC740 \uC548\uC804\uACFC \uBCF4\uC99D \uBB38\uC81C\uAC00 \uC788\uC5B4 \uD53C\uD569\uB2C8\uB2E4.", "\uB0B4\uC7A5\uD615\uC740 \uC5C5\uCCB4\uC5D0 \uBCF4\uB0B4 \uAD50\uCCB4\uD558\uAC70\uB098 \uAE30\uAE30 \uC790\uCCB4\uB97C \uBC14\uAFB8\uB294 \uBC29\uC2DD\uC774\uB77C \uAE30\uAC04\uC774 \uAC78\uB9BD\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB294 \uAD50\uCCB4\uAC00 \uC57D\uC815\uC5D0 \uD3EC\uD568\uC778\uC9C0, \uC18C\uBAA8\uD488\uC774\uB77C \uC720\uC0C1\uC778\uC9C0 \uC57D\uC815\uC11C\uC5D0\uC11C \uBD05\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uB294 \uBCF4\uC99D \uAE30\uAC04 \uC548\uC774\uBA74 \uC870\uAC74\uC744 \uD655\uC778\uD558\uACE0, \uC9C0\uB098\uBA74 \uBE44\uC6A9\uC774 \uB9E4\uC7A5 \uBAAB\uC785\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAC04 \uB3D9\uC548 \uC4F8 \uC608\uBE44 \uAE30\uAE30\uB098 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uACB0\uC81C\uB85C \uC774\uC5B4\uAC08 \uBC29\uBC95\uC744 \uB461\uB2C8\uB2E4.", "\uAD50\uCCB4 \uBE44\uC6A9\uACFC \uAE30\uAC04\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4\uD615 \uBC30\uD130\uB9AC\uB294 \uC5EC\uBD84 \uD55C \uAC1C\uB97C \uB450\uBA74 \uAD50\uCCB4 \uC2E0\uD638\uAC00 \uBCF4\uC5EC\uB3C4 \uBC14\uB85C \uB300\uC751\uB429\uB2C8\uB2E4.", "\uC5C5\uCCB4\uC5D0 \uBCF4\uB0BC \uB54C \uC6B4\uC1A1 \uC911 \uD30C\uC190\uC744 \uB9C9\uAE30 \uC704\uD574 \uC644\uCDA9\uC7AC\uB97C \uB123\uACE0 \uC1A1\uC7A5 \uBC88\uD638\uB97C \uB0A8\uAE41\uB2C8\uB2E4.", "\uAD50\uCCB4\uD615 \uBC30\uD130\uB9AC\uB294 \uC815\uD488 \uBC88\uD638\uB97C \uD655\uC778\uD558\uACE0, \uB0B4\uC7A5\uD615\uC740 \uC5C5\uCCB4 \uC218\uB9AC \uAE30\uAC04 \uB3D9\uC548 \uC4F8 \uC608\uBE44 \uAE30\uAE30\uB97C \uBA3C\uC800 \uD655\uBCF4\uD569\uB2C8\uB2E4.", "\uAD50\uCCB4 \uB4A4 \uBC1B\uC740 \uBC30\uD130\uB9AC \uBCF4\uC99D\uC11C\uB294 \uAE30\uAE30 \uBCF4\uC99D\uC11C\uC640 \uD568\uAED8 \uBCF4\uAD00\uD569\uB2C8\uB2E4."] }, { "h": "\uC218\uBA85\uC744 \uB298\uB9AC\uB294 \uBC29\uBC95\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uC644\uC804\uD788 \uBC29\uC804\uB41C \uB4A4 \uCDA9\uC804\uD558\uB294 \uC2B5\uAD00\uBCF4\uB2E4 \uAC70\uCE58\uB300\uC5D0 \uC790\uC8FC \uC62C\uB824 \uB450\uB294 \uD3B8\uC774 \uBC30\uD130\uB9AC\uC5D0 \uB0AB\uC2B5\uB2C8\uB2E4.", "\uACE0\uC628 \uCC28\uB7C9 \uC548\uC774\uB098 \uC9C1\uC0AC\uAD11\uC120 \uC544\uB798 \uB450\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uACA8\uC6B8\uCCA0\uC5D0\uB294 \uBCF4\uC628 \uD30C\uC6B0\uCE58\uB098 \uC548\uC8FC\uBA38\uB2C8\uC5D0 \uB123\uC5B4 \uC800\uC628\uC744 \uD53C\uD569\uB2C8\uB2E4.", "\uCDA9\uC804\uC740 \uAE30\uAE30 \uC815\uD488 \uC5B4\uB311\uD130\uB85C \uD558\uACE0, \uCF00\uC774\uBE14 \uC190\uC0C1\uC774 \uC788\uC73C\uBA74 \uBC14\uB85C \uBC14\uAFC9\uB2C8\uB2E4.", "\uC601\uC5C5 \uC885\uB8CC \uB54C \uC644\uCDA9\uD574 \uB450\uACE0 \uC544\uCE68\uC5D0 \uBC14\uB85C \uC4F0\uB294 \uB8E8\uD2F4\uC744 \uB9CC\uB4E4\uBA74 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC548\uC815\uB429\uB2C8\uB2E4.", "\uB0B4\uC7A5\uD615 \uAE30\uAE30\uB97C \uC5C5\uCCB4\uC5D0 \uBCF4\uB0BC \uB54C\uB294 \uAE30\uAE30 \uBC88\uD638\uC640 \uC99D\uC0C1\uC744 \uC801\uC740 \uBA54\uBAA8\uB97C \uAC19\uC774 \uB123\uC2B5\uB2C8\uB2E4.", "\uCDA9\uC804\uAE30\uB294 \uAE30\uAE30 \uC815\uD488\uC744 \uC4F0\uACE0, \uBCF4\uC870\uBC30\uD130\uB9AC\uB85C \uCDA9\uC804\uD560 \uB54C\uB294 \uCD9C\uB825 \uADDC\uACA9\uC744 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uCDA9\uC804 \uB8E8\uD2F4\uC740 \uAE30\uAE30 \uAC70\uCE58\uB300 \uC606\uC5D0 \uBD99\uC5EC \uB450\uBA74 \uC9C1\uC6D0\uC774 \uBC14\uB00C\uC5B4\uB3C4 \uC720\uC9C0\uB429\uB2C8\uB2E4.", "\uCDA9\uC804 \uC911 \uAE30\uAE30\uB97C \uC4F0\uBA74 \uBC30\uD130\uB9AC\uC5D0 \uBB34\uB9AC\uAC00 \uAC00\uBBC0\uB85C \uCDA9\uC804\uC740 \uACB0\uC81C\uAC00 \uC5C6\uB294 \uC2DC\uAC04\uC5D0 \uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uB97C \uAC70\uCE58\uB300\uC5D0 \uC62C\uB824 \uB458 \uB54C \uC811\uC810\uC774 \uB354\uB7EC\uC6B0\uBA74 \uCDA9\uC804\uC774 \uC548 \uB418\uBBC0\uB85C \uC811\uC810\uC744 \uC8FC\uAE30\uC801\uC73C\uB85C \uB2E6\uC2B5\uB2C8\uB2E4."] }, { "h": "\uAE30\uAE30 \uC790\uCCB4\uB97C \uBC14\uAFD4\uC57C \uD558\uB294 \uACBD\uC6B0\uB294 \uC5B8\uC81C\uC778\uAC00\uC694?", "p": ["\uBC30\uD130\uB9AC\uB97C \uBC14\uAFD4\uB3C4 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uC9E7\uC73C\uBA74 \uAE30\uAE30 \uC804\uC6D0\uBD80 \uBB38\uC81C\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACB0\uC81C \uADDC\uACA9\uC774\uB098 \uBCF4\uC548 \uC778\uC99D\uC774 \uBC14\uB00C\uC5B4 \uAD6C\uD615 \uAE30\uAE30\uAC00 \uB4F1\uB85D\uB418\uC9C0 \uC54A\uC73C\uBA74 \uAD50\uCCB4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uD504\uB9B0\uD130\uB098 \uD654\uBA74 \uACE0\uC7A5\uC774 \uBC30\uD130\uB9AC\uC640 \uD568\uAED8 \uC624\uBA74 \uC218\uB9AC\uBCF4\uB2E4 \uAD50\uCCB4\uAC00 \uC801\uC740 \uACBD\uC6B0\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4.", "\uC784\uB300 \uAE30\uAE30\uB294 \uC57D\uC815 \uAD50\uCCB4 \uC870\uAC74\uC744, \uAD6C\uB9E4 \uAE30\uAE30\uB294 \uC0C8 \uAE30\uAE30 \uBE44\uC6A9\uACFC \uBE44\uAD50\uD574 \uC815\uD569\uB2C8\uB2E4.", "\uCDA9\uC804 \uB8E8\uD2F4\uC744 \uAE30\uC0AC \uAD50\uB300 \uB54C \uD568\uAED8 \uC801\uC6A9\uD558\uBA74 \uAE30\uAE30\uBCC4 \uC0AC\uC6A9 \uC2DC\uAC04\uC774 \uACE0\uB974\uAC8C \uC720\uC9C0\uB429\uB2C8\uB2E4.", "\uBCF4\uC99D \uC870\uAC74\uC5D0 \uBC30\uD130\uB9AC\uAC00 \uC18C\uBAA8\uD488\uC73C\uB85C \uC81C\uC678\uB3FC \uC788\uB294\uC9C0 \uBCF4\uC99D\uC11C\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uD310\uB2E8\uC5D0\uB294 \uAD50\uCCB4 \uAE30\uAC04 \uB3D9\uC548\uC758 \uB9E4\uCD9C \uC190\uC2E4\uB3C4 \uB123\uC5B4 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uAE30\uAE30 \uAD50\uCCB4 \uD310\uB2E8\uC5D0\uB294 \uBC30\uD130\uB9AC\uAC12, \uC218\uB9AC \uAE30\uAC04, \uC0C8 \uAE30\uAE30\uAC12, \uAD50\uCCB4 \uAE30\uAC04 \uB9E4\uCD9C \uC190\uC2E4 \uB124 \uAC00\uC9C0\uB97C \uB123\uC2B5\uB2C8\uB2E4.", "\uAD6C\uB9E4 \uAE30\uAE30\uC758 \uBCF4\uC99D\uC774 \uB05D\uB0AC\uC73C\uBA74 \uC218\uB9AC\uC640 \uAD50\uCCB4 \uACAC\uC801\uC744 \uD568\uAED8 \uBC1B\uC544 \uBE44\uAD50\uD569\uB2C8\uB2E4."] }], "steps": { "h": "\uBC30\uD130\uB9AC \uC810\uAC80 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uAE30\uAE30\uBCC4 \uC644\uCDA9 \uB4A4 \uC0AC\uC6A9 \uC2DC\uAC04\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uCDA9\uC804\uAE30\xB7\uCF00\uC774\uBE14\uC744 \uBA3C\uC800 \uBC14\uAFD4 \uBD05\uB2C8\uB2E4.", "\uAD50\uCCB4\uD615\uC774\uBA74 \uC815\uD488 \uBC30\uD130\uB9AC\uB97C \uBC1B\uACE0, \uB0B4\uC7A5\uD615\uC774\uBA74 \uC5C5\uCCB4\uC5D0 \uBCF4\uB0C5\uB2C8\uB2E4.", "\uAD50\uCCB4 \uAE30\uAC04 \uB3D9\uC548 \uC608\uBE44 \uAE30\uAE30\uB85C \uC6B4\uC601\uD569\uB2C8\uB2E4.", "\uCDA9\uC804 \uC2B5\uAD00\uACFC \uAC70\uCE58 \uBC29\uC2DD\uC744 \uC815\uB9AC\uD569\uB2C8\uB2E4."] }, "table": { "caption": "\uBC30\uD130\uB9AC \uBB38\uC81C \uB300\uC751", "head": ["\uC99D\uC0C1", "\uC6D0\uC778", "\uB300\uC751"], "rows": [["\uC0AC\uC6A9 \uC2DC\uAC04 \uAE09\uAC10", "\uB178\uD654", "\uAD50\uCCB4"], ["\uBD80\uD480\uC74C\xB7\uBC1C\uC5F4", "\uC190\uC0C1", "\uC0AC\uC6A9 \uC911\uC9C0\xB7\uC5C5\uCCB4 \uC5F0\uB77D"], ["\uCDA9\uC804 \uC548 \uB428", "\uCF00\uC774\uBE14\xB7\uCDA9\uC804\uBD80", "\uCF00\uC774\uBE14 \uAD50\uCCB4 \uD6C4 \uC810\uAC80"], ["\uAC74\uC218 \uC99D\uAC00\uB85C \uBD80\uC871", "\uC6A9\uB7C9", "\uC608\uBE44 \uBC30\uD130\uB9AC\xB7\uB300\uC218 \uC870\uC815"]] }, "faq": [["\uBC30\uD130\uB9AC \uAD50\uCCB4\uB294 \uB9E4\uC7A5\uC5D0\uC11C \uD560 \uC218 \uC788\uB098\uC694?", "\uAD50\uCCB4\uD615 \uBAA8\uB378\uC740 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uB0B4\uC7A5\uD615\uC740 \uC5C5\uCCB4\uC5D0 \uBCF4\uB0C5\uB2C8\uB2E4."], ["\uAD50\uCCB4 \uBE44\uC6A9\uC740 \uB204\uAC00 \uB0B4\uB098\uC694?", "\uC784\uB300\uB294 \uC57D\uC815 \uC870\uAC74, \uAD6C\uB9E4\uB294 \uBCF4\uC99D \uAE30\uAC04\uC5D0 \uB530\uB985\uB2C8\uB2E4. \uAD50\uCCB4 \uBD80\uD488\uAC12\uACFC \uC791\uC5C5\uBE44\uB294 \uBAA8\uB378\uBCC4\uB85C \uB2EC\uB77C \uC5C5\uCCB4\uC5D0 \uBB3B\uC2B5\uB2C8\uB2E4."], ["\uBE44\uC815\uD488 \uBC30\uD130\uB9AC\uB97C \uC368\uB3C4 \uB418\uB098\uC694?", "\uC548\uC804\uACFC \uBCF4\uC99D \uBB38\uC81C\uAC00 \uC788\uC5B4 \uAD8C\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."], ["\uBC30\uD130\uB9AC\uAC00 \uBD80\uD480\uC5C8\uB294\uB370 \uADF8\uB0E5 \uC368\uB3C4 \uB418\uB098\uC694?", "\uC548 \uB429\uB2C8\uB2E4. \uC0AC\uC6A9\uC744 \uBA48\uCD94\uACE0 \uBC14\uB85C \uC5C5\uCCB4\uC5D0 \uC54C\uB9BD\uB2C8\uB2E4."]], "related": ["\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD589\uC0AC\uD478\uB4DC\uD2B8\uB7ED", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uD574\uC9C0\uBC18\uB0A9"], "posts": [], "sources": [], "date": "2026-10-15" }, { "slug": "\uBB34\uC120\uB2E8\uB9D0\uAE30\uAC04\uC774\uACFC\uC138\uC790\uC218\uC218\uB8CC", "product": "\uBB34\uC120\uB2E8\uB9D0\uAE30", "tail": "\uAC04\uC774\uACFC\uC138\uC790 \uC218\uC218\uB8CC", "title": "\uAC04\uC774\uACFC\uC138\uC790\uAC00 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uC4F0\uBA74 \uC218\uC218\uB8CC\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694? \u2014 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAE30\uC900", "desc": "\uAC04\uC774\uACFC\uC138\uC790 \uB9E4\uC7A5\uC774 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB85C \uBC30\uB2EC\xB7\uD604\uC7A5 \uACB0\uC81C\uB97C \uBC1B\uC744 \uB54C \uC218\uC218\uB8CC\uAC00 \uACFC\uC138 \uC720\uD615\uC774 \uC544\uB2C8\uB77C \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uB294 \uC810, \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAC00\uB9F9\uC810\uC73C\uB85C \uBB36\uC77C \uB54C\uC758 \uC815\uC0B0, \uBE44\uB300\uBA74 \uB9C1\uD06C \uACB0\uC81C\uC640\uC758 \uBE44\uC728 \uCC28\uC774, \uC815\uC0B0\uC11C \uD655\uC778\uBC95\uC744 \uC815\uB9AC\uD588\uC2B5\uB2C8\uB2E4.", "answer": "\uAC04\uC774\uACFC\uC138\uC790\uAC00 \uBB34\uC120\uB2E8\uB9D0\uAE30\uB85C \uBC1B\uB294 \uACB0\uC81C\uB3C4 \uC218\uC218\uB8CC\uB294 \uAC00\uB9F9\uC810 \uB9E4\uCD9C \uAD6C\uAC04\uC73C\uB85C \uC815\uD574\uC9C0\uBBC0\uB85C \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uBE44\uC728\uC774 \uC801\uC6A9\uB418\uACE0, \uACFC\uC138 \uC720\uD615\uC740 \uBE44\uC728\uC5D0 \uC601\uD5A5\uC744 \uC8FC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uBB34\uC120\uAE30\uAC00 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uBB36\uC5EC \uC788\uC73C\uBA74 \uC815\uC0B0\uC11C\uB3C4 \uD558\uB098\uB85C \uB4E4\uC5B4\uC624\uBBC0\uB85C, \uD604\uC7A5 \uACB0\uC81C\uC640 \uB9C1\uD06C \uACB0\uC81C\uC758 \uACBD\uB85C \uCC28\uC774\uB9CC \uB098\uB220 \uBCF4\uBA74 \uB429\uB2C8\uB2E4.", "sections": [{ "h": "\uC218\uC218\uB8CC\uB294 \uC5B4\uB5BB\uAC8C \uC815\uD574\uC9C0\uB098\uC694?", "p": ["\uCE74\uB4DC\uC0AC\uAC00 \uAC00\uB9F9\uC810\uC758 \uC5F0\uB9E4\uCD9C \uAD6C\uAC04\uC744 \uC815\uD558\uACE0 \uADF8 \uAD6C\uAC04\uC758 \uBE44\uC728\uC744 \uC801\uC6A9\uD558\uBA70, \uAE30\uAE30 \uC885\uB958\uB098 \uBB34\uC120 \uC5EC\uBD80\uB294 \uBE44\uC728\uC744 \uBC14\uAFB8\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC601\uC138\xB7\uC911\uC18C \uAC00\uB9F9\uC810 \uC6B0\uB300 \uAD6C\uAC04\uC740 \uB9E4\uCD9C \uAE30\uC900\uC774\uBBC0\uB85C \uAC04\uC774\uACFC\uC138\uC790\uB3C4 \uB9E4\uCD9C\uC774 \uAE30\uC900 \uC548\uC774\uBA74 \uC801\uC6A9\uB429\uB2C8\uB2E4.", "\uAD6C\uAC04 \uAE30\uC900\uACFC \uBE44\uC728\uC740 \uAE08\uC735\uB2F9\uAD6D \uACE0\uC2DC\uC5D0 \uB530\uB77C \uBC14\uB00C\uBBC0\uB85C \uD604\uC7AC \uAC12\uC740 \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4.", "\uAC1C\uC5C5 \uC9C1\uD6C4\uB294 \uB9E4\uCD9C \uC790\uB8CC\uAC00 \uC5C6\uC5B4 \uC77C\uBC18 \uAD6C\uAC04\uC73C\uB85C \uC2DC\uC791\uD588\uB2E4\uAC00 \uB2E4\uC74C \uC0B0\uC815 \uB54C \uBC14\uB014 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uB97C \uCD94\uAC00\uD574\uB3C4 \uAC00\uB9F9\uC810\uC774 \uAC19\uC73C\uBA74 \uAD6C\uAC04\uC740 \uAC19\uC740 \uB9E4\uCD9C \uC790\uB8CC\uB85C \uC815\uD574\uC9D1\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uC120\uACB0\uC81C\uB294 \uC571 \uC218\uC218\uB8CC \uCCB4\uACC4\uAC00 \uB530\uB85C\uC774\uBBC0\uB85C \uCE74\uB4DC \uC218\uC218\uB8CC\uC640 \uC11E\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC218\uC218\uB8CC \uAD6C\uAC04 \uD750\uB984\uC740 \uAE30\uC874 \uAE00 '\uCE74\uB4DC \uC218\uC218\uB8CC\uB294 \uC5B4\uB514\uC11C \uAC08\uB9AC\uB098'\uC5D0\uC11C \uC774\uC5B4\uC9D1\uB2C8\uB2E4.", "\uAD6C\uAC04 \uC0B0\uC815 \uC2DC\uAE30(\uBC18\uAE30)\uB97C \uB2EC\uB825\uC5D0 \uC801\uC5B4 \uB450\uBA74 \uD1B5\uC9C0\uBB38\uC774 \uC548 \uC654\uC744 \uB54C \uCE74\uB4DC\uC0AC\uC5D0 \uBB3C\uC744 \uC2DC\uC810\uC744 \uC555\uB2C8\uB2E4.", "\uBB34\uC120\uAE30 \uCD94\uAC00\uB85C \uAC00\uB9F9\uC810\uC774 \uB298\uC5B4\uB098\uB294 \uAC83\uC774 \uC544\uB2C8\uBBC0\uB85C \uAD6C\uAC04 \uC0B0\uC815\uC5D0 \uAE30\uAE30 \uC218\uB294 \uC601\uD5A5\uC744 \uC8FC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uCE74\uB4DC\uC0AC\uBCC4 \uAD6C\uAC04 \uD1B5\uC9C0\uB294 \uB530\uB85C \uC624\uBBC0\uB85C \uD1B5\uC9C0\uBB38\uC774 \uC628 \uCE74\uB4DC\uC0AC\uC640 \uC548 \uC628 \uCE74\uB4DC\uC0AC\uB97C \uAD6C\uBD84\uD574 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uB9E4\uCD9C \uAD6C\uAC04\uC740 \uC0AC\uC5C5\uC790 \uB2E8\uC704\uB85C \uC815\uD574\uC9C0\uBBC0\uB85C \uAC19\uC740 \uC0AC\uC5C5\uC790\uAC00 \uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uB450\uBA74 \uD569\uC0B0 \uB9E4\uCD9C\uC774 \uAE30\uC900\uC774 \uB429\uB2C8\uB2E4."] }, { "h": "\uC815\uC0B0\uC740 \uC5B4\uB5BB\uAC8C \uB4E4\uC5B4\uC624\uB098\uC694?", "p": ["\uBB34\uC120\uAE30\uAC00 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uBA74 \uC815\uC0B0\uC11C\uAC00 \uD558\uB098\uB85C \uB4E4\uC5B4\uC640 \uAE30\uAE30\uBCC4 \uAD6C\uBD84\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uBCC4 \uB9E4\uCD9C\uC744 \uBCF4\uACE0 \uC2F6\uC73C\uBA74 \uAE30\uAE30 \uBC88\uD638\uBCC4 \uC2B9\uC778 \uB0B4\uC5ED\uC744 \uB530\uB85C \uBC1B\uC544 \uB461\uB2C8\uB2E4.", "\uD604\uC7A5 \uACB0\uC81C\uB294 \uB300\uBA74 \uACBD\uB85C\uB77C \uB9E4\uC7A5 \uACB0\uC81C\uC640 \uAC19\uC740 \uBE44\uC728\uC774\uACE0, \uB9C1\uD06C \uACB0\uC81C\uB294 \uBE44\uB300\uBA74 \uACBD\uB85C\uB77C \uBE44\uC728\uC774 \uB2E4\uB97C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC815\uC0B0 \uC8FC\uAE30\uB294 \uCE74\uB4DC\uC0AC\uB9C8\uB2E4 \uB2EC\uB77C \uC785\uAE08\uC77C\uC774 \uD769\uC5B4\uC9C0\uBBC0\uB85C \uC6D4 \uB2E8\uC704\uB85C \uD569\uCCD0 \uBD05\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C\uC758 \uC2B9\uC778 \uCD1D\uC561\xB7\uACF5\uC81C \uCD1D\uC561\xB7\uC785\uAE08\uC561\uC744 \uB9E4\uB2EC \uAC19\uC740 \uD45C\uC5D0 \uC801\uC73C\uBA74 \uBB34\uC120\uAE30 \uCD94\uAC00 \uB4A4 \uBE44\uC728\uC774 \uBCC0\uD588\uB294\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uAC04\uC774\uACFC\uC138\uC790\uB294 \uC785\uAE08\uC561\uC774 \uC544\uB2C8\uB77C \uC2B9\uC778 \uCD1D\uC561\uC774 \uB9E4\uCD9C\uC774\uBBC0\uB85C \uC2E0\uACE0 \uB54C \uD63C\uB3D9\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uBCC4 \uC2B9\uC778 \uB0B4\uC5ED\uC740 \uBC34\uC0AC \uAC00\uB9F9\uC810 \uD654\uBA74\uC774\uB098 \uACE0\uAC1D\uC13C\uD130\uC5D0\uC11C \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAE30\uAE30\uBCC4 \uC2B9\uC778 \uB0B4\uC5ED\uC5D0\uB294 \uAE30\uAE30 \uBC88\uD638\uAC00 \uCC0D\uD788\uBBC0\uB85C \uC7A5\uBD80\uC758 \uAE30\uAE30 \uBC88\uD638\uC640 \uB9DE\uCDB0 \uB461\uB2C8\uB2E4.", "\uC815\uC0B0 \uC8FC\uAE30\uAC00 \uB2E4\uB978 \uCE74\uB4DC\uC0AC \uC785\uAE08\uC744 \uC6D4\uBCC4\uB85C \uD569\uCE58\uBA74 \uC218\uC218\uB8CC \uBE44\uC728\uC774 \uC6D4\uB9C8\uB2E4 \uBE44\uC2B7\uD558\uAC8C \uC720\uC9C0\uB418\uB294\uC9C0 \uBCF4\uC785\uB2C8\uB2E4.", "\uBB34\uC120\uAE30 \uC2B9\uC778 \uB0B4\uC5ED\uACFC \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30 \uC2B9\uC778 \uB0B4\uC5ED\uC744 \uD569\uCE5C \uAC12\uC774 \uC815\uC0B0\uC11C \uC2B9\uC778 \uCD1D\uC561\uACFC \uB9DE\uB294\uC9C0 \uC6D4\uB9D0\uC5D0 \uD655\uC778\uD569\uB2C8\uB2E4."] }, { "h": "\uAC04\uC774\uACFC\uC138\uC790\uAC00 \uC8FC\uC758\uD560 \uC810\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?", "p": ["\uCE74\uB4DC \uB9E4\uCD9C\uC740 \uAD6D\uC138\uCCAD\uC5D0 \uC9D1\uACC4\uB418\uBBC0\uB85C \uBB34\uC120\uAE30 \uB9E4\uCD9C\uB3C4 \uC2E0\uACE0 \uC790\uB8CC\uC5D0 \uADF8\uB300\uB85C \uBC18\uC601\uB429\uB2C8\uB2E4.", "\uB9E4\uCD9C\uC774 \uB298\uC5B4 \uACFC\uC138 \uC720\uD615\uC774 \uBC14\uB00C\uC5B4\uB3C4 \uB2E8\uB9D0\uAE30\uC640 \uAC00\uB9F9\uC810\uC740 \uADF8\uB300\uB85C \uC4F0\uACE0 \uC0AC\uC5C5\uC790 \uC815\uBCF4\uB9CC \uAC31\uC2E0\uD569\uB2C8\uB2E4.", "\uD604\uAE08 \uACB0\uC81C\uAC00 \uB9CE\uC740 \uBC30\uB2EC\uC740 \uD604\uAE08\uC601\uC218\uC99D \uBC1C\uAE09 \uC694\uCCAD\uC774 \uC624\uBBC0\uB85C \uBB34\uC120\uAE30\uC5D0\uC11C \uBC1C\uAE09\uB418\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uBC30\uB2EC \uC571 \uB9E4\uCD9C, \uCE74\uB4DC \uB9E4\uCD9C, \uD604\uAE08 \uB9E4\uCD9C\uC744 \uB098\uB220 \uC801\uC5B4 \uB450\uBA74 \uACFC\uC138 \uC720\uD615 \uD310\uC815 \uAE30\uC900\uC778 \uCD1D\uB9E4\uCD9C\uC744 \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\uC138\uBB34 \uC2E0\uACE0 \uBC29\uC2DD \uCC28\uC774\uB294 \uC138\uBB34 \uB300\uB9AC\uC778\uACFC \uB9DE\uCDA5\uB2C8\uB2E4.", "\uB9C1\uD06C \uACB0\uC81C \uBE44\uC911\uC774 \uB298\uBA74 \uBE44\uB300\uBA74 \uACBD\uB85C \uBE44\uC728 \uB54C\uBB38\uC5D0 \uC804\uCCB4 \uBE44\uC728\uC774 \uBC14\uB00C\uBBC0\uB85C \uACBD\uB85C\uBCC4\uB85C \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uACFC\uC138 \uC720\uD615 \uBCC0\uACBD \uD1B5\uC9C0\uAC00 \uC624\uBA74 \uCE74\uB4DC\uC0AC \uAC00\uB9F9\uC810 \uC815\uBCF4\uB3C4 \uAC19\uC774 \uAC31\uC2E0\uD574 \uC815\uC0B0\uC774 \uB04A\uAE30\uC9C0 \uC54A\uAC8C \uD569\uB2C8\uB2E4.", "\uD604\uAE08 \uB9E4\uCD9C \uC7A5\uBD80\uC640 \uCE74\uB4DC \uC815\uC0B0\uC11C\uB97C \uC6D4\uB9D0\uC5D0 \uD569\uCCD0 \uCD1D\uB9E4\uCD9C\uC744 \uD655\uC778\uD558\uBA74 \uACFC\uC138 \uC720\uD615 \uD310\uC815 \uAE30\uC900\uC744 \uB193\uCE58\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."] }, { "h": "\uBB34\uC5C7\uC744 \uB9E4\uB2EC \uD655\uC778\uD558\uB098\uC694?", "p": ["\uC815\uC0B0\uC11C \uC138 \uC904\uC744 \uC801\uACE0 \uC804\uC6D4\uACFC \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\uAE30\uAE30\uBCC4 \uC2B9\uC778 \uB0B4\uC5ED\uC73C\uB85C \uD604\uC7A5 \uACB0\uC81C \uBE44\uC911\uC744 \uBD05\uB2C8\uB2E4.", "\uCE74\uB4DC\uC0AC \uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uC774 \uC624\uBA74 \uBCF4\uAD00\uD558\uACE0 \uC801\uC6A9 \uC2DC\uC791\uC77C\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4.", "\uACF5\uC81C \uD56D\uBAA9\uC5D0 \uC218\uC218\uB8CC \uC678 \uBA85\uBAA9\uC774 \uC11E\uC5EC \uC788\uB294\uC9C0 \uBD05\uB2C8\uB2E4.", "\uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uACFC \uC815\uC0B0\uC11C\uB97C \uAC19\uC740 \uD3F4\uB354\uC5D0 \uB450\uBA74 \uBC18\uAE30\uB9C8\uB2E4 \uBE44\uC728 \uBCC0\uD654\uB97C \uC124\uBA85\uD560 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uD604\uAE08\uC601\uC218\uC99D \uBC1C\uAE09 \uB0B4\uC5ED\uC740 \uAD6D\uC138\uCCAD\uC73C\uB85C \uBC14\uB85C \uC804\uC1A1\uB418\uBBC0\uB85C \uBB34\uC120\uAE30\uC5D0\uC11C\uB3C4 \uBC1C\uAE09 \uAE30\uB2A5\uC744 \uCF1C \uB461\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C \uC138 \uC904\uACFC \uACBD\uB85C\uBCC4 \uBE44\uC911\uC744 \uAC19\uC740 \uD45C\uC5D0 \uC801\uC73C\uBA74 \uBC18\uAE30 \uC0B0\uC815 \uB54C \uBE44\uC728 \uBCC0\uD654\uAC00 \uC124\uBA85\uB429\uB2C8\uB2E4.", "\uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uC740 \uC801\uC6A9 \uC2DC\uC791\uC77C\uACFC \uD568\uAED8 \uBCF4\uAD00\uD574 \uBC18\uAE30\uB9C8\uB2E4 \uBE44\uC728 \uBCC0\uD654\uB97C \uC124\uBA85\uD560 \uADFC\uAC70\uB85C \uC501\uB2C8\uB2E4."] }], "steps": { "h": "\uD655\uC778 \uC21C\uC11C\uB294 \uC5B4\uB5BB\uAC8C \uB418\uB098\uC694?", "items": ["\uCE74\uB4DC\uC0AC \uC548\uB0B4\uBB38\uC5D0\uC11C \uD604\uC7AC \uC218\uC218\uB8CC \uAD6C\uAC04\uC744 \uBD05\uB2C8\uB2E4.", "\uBB34\uC120\uAE30\uAC00 \uAC19\uC740 \uAC00\uB9F9\uC810 \uBC88\uD638\uB85C \uB4F1\uB85D\uB410\uB294\uC9C0 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC815\uC0B0\uC11C \uC138 \uC904\uC744 \uB9E4\uB2EC \uC801\uC5B4 \uBE44\uC728\uC744 \uACC4\uC0B0\uD569\uB2C8\uB2E4.", "\uB300\uBA74\xB7\uBE44\uB300\uBA74 \uACBD\uB85C\uB97C \uB098\uB220 \uBD05\uB2C8\uB2E4.", "\uAD6C\uAC04 \uD1B5\uC9C0\uBB38\uC744 \uBCF4\uAD00\uD558\uACE0 \uC801\uC6A9\uC77C\uC744 \uC801\uC5B4 \uB461\uB2C8\uB2E4."] }, "table": { "caption": "\uACB0\uC81C \uACBD\uB85C\uBCC4 \uC218\uC218\uB8CC \uC801\uC6A9", "head": ["\uACBD\uB85C", "\uAE30\uAE30", "\uBE44\uC728 \uAE30\uC900"], "rows": [["\uB9E4\uC7A5 \uB300\uBA74", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30", "\uAC00\uB9F9\uC810 \uAD6C\uAC04"], ["\uD604\uC7A5 \uB300\uBA74", "\uBB34\uC120\uB2E8\uB9D0\uAE30", "\uAC00\uB9F9\uC810 \uAD6C\uAC04(\uAC19\uC74C)"], ["\uB9C1\uD06C\xB7\uBE44\uB300\uBA74", "\uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\xB7\uC571", "\uBE44\uB300\uBA74 \uACBD\uB85C"], ["\uC571 \uC120\uACB0\uC81C", "\uC5C6\uC74C", "\uC571 \uC218\uC218\uB8CC \uCCB4\uACC4"]] }, "faq": [["\uBB34\uC120\uAE30 \uACB0\uC81C\uB294 \uC218\uC218\uB8CC\uAC00 \uB354 \uB192\uB098\uC694?", "\uC544\uB2D9\uB2C8\uB2E4. \uAC19\uC740 \uAC00\uB9F9\uC810 \uAD6C\uAC04\uC774\uBA74 \uB9E4\uC7A5 \uB2E8\uB9D0\uAE30\uC640 \uAC19\uC2B5\uB2C8\uB2E4."], ["\uAC04\uC774\uACFC\uC138\uC790\uB77C\uC11C \uC6B0\uB300\uB97C \uBABB \uBC1B\uB098\uC694?", "\uC6B0\uB300\uB294 \uB9E4\uCD9C \uAE30\uC900\uC774\uBBC0\uB85C \uB9E4\uCD9C\uC774 \uAE30\uC900 \uC548\uC774\uBA74 \uBC1B\uC2B5\uB2C8\uB2E4."], ["\uC815\uC0B0\uC11C\uC5D0 \uBB34\uC120\uAE30 \uB9E4\uCD9C\uC774 \uB530\uB85C \uB098\uC624\uB098\uC694?", "\uAC19\uC740 \uAC00\uB9F9\uC810\uC774\uBA74 \uD569\uCCD0 \uB098\uC635\uB2C8\uB2E4. \uAE30\uAE30\uBCC4 \uC2B9\uC778 \uB0B4\uC5ED\uC744 \uB530\uB85C \uBC1B\uC73C\uBA74 \uAD6C\uBD84\uB429\uB2C8\uB2E4."], ["\uAD6C\uAC04 \uBE44\uC728\uC740 \uC5BC\uB9C8\uC778\uAC00\uC694?", "\uACE0\uC2DC\uC5D0 \uB530\uB77C \uBC14\uB00C\uBBC0\uB85C \uC0C1\uB2F4\uC5D0\uC11C \uD655\uC778\uD569\uB2C8\uB2E4."]], "related": ["\uCE74\uB4DC\uB2E8\uB9D0\uAE30\uC218\uC218\uB8CC", "\uAC04\uC774\uACFC\uC138\uC790\uCE74\uB4DC\uB2E8\uB9D0\uAE30", "\uBB34\uC120\uB2E8\uB9D0\uAE30\uBC30\uB2EC\uC6A9"], "posts": ["/post/fee-tiers/"], "sources": ["\uC5EC\uC2E0\uC804\uBB38\uAE08\uC735\uC5C5\uBC95 \uC81C18\uC870\uC7583(\uC6B0\uB300\uC218\uC218\uB8CC\uC728)"], "date": "2026-10-15" }];
