  const CI = {
    cafe: [{ desc: "\uCE74\uC6B4\uD130 \uC704\uC758 \uD604\uAE08\uACFC POS, \uC785\uAD6C\uC758 \uACE0\uAC1D \uCD9C\uC785, \uC88C\uC11D \uAD6C\uC5ED\uC758 \uBD84\uC2E4\uBB3C \uC0AC\uACE0\uAC00 \uCE74\uD398 CCTV\uC758 \uD575\uC2EC \uAC10\uC2DC \uB300\uC0C1\uC785\uB2C8\uB2E4. \uD2B9\uD788 \uB178\uD2B8\uBD81\xB7\uD0DC\uBE14\uB9BF\uC744 \uB193\uACE0 \uC790\uB9AC\uB97C \uBE44\uC6B0\uB294 \uACE0\uAC1D\uC774 \uB9CE\uC544 \uBD84\uC2E4\uBB3C \uAD00\uB828 \uBBFC\uC6D0\uC774 \uBE48\uBC88\uD569\uB2C8\uB2E4.", tip: "\uBC14\uB9AC\uC2A4\uD0C0 \uC791\uC5C5 \uACF5\uAC04\uC5D0\uB294 \uC704\uC0DD \uBAA8\uB2C8\uD130\uB9C1\uC744, \uD14C\uC774\uD06C\uC544\uC6C3 \uAD6C\uC5ED\uC5D0\uB294 \uD63C\uC7A1 \uAC10\uC2DC\uB97C \uACB8\uD560 \uC218 \uC788\uC5B4 \uC6B4\uC601 \uD6A8\uC728\uB3C4 \uC62C\uB77C\uAC11\uB2C8\uB2E4.", review: "\uCD9C\uADFC \uC2DC\uAC04\uB300\uC5D0 \uB178\uD2B8\uBD81\uC744 \uB193\uACE0 \uAC04 \uC190\uB2D8\uC774 CCTV \uB355\uBD84\uC5D0 10\uBD84 \uB9CC\uC5D0 \uB418\uCC3E\uC558\uC5B4\uC694. \uC774\uC804\uC5D0\uB294 \uBD84\uC2E4\uBB3C \uCC98\uB9AC\uAC00 \uACE8\uCE58\uC600\uB294\uB370 \uC774\uC81C \uC601\uC0C1\uC73C\uB85C \uBC14\uB85C \uD655\uC778\uD569\uB2C8\uB2E4." }, { desc: "\uCE74\uD398 \uACF5\uAC04\uC740 \uC791\uC5C5 \uACF5\uAC04\uACFC \uACE0\uAC1D \uACF5\uAC04\uC774 \uACF5\uC874\uD558\uB294 \uBCF5\uD569 \uD658\uACBD\uC785\uB2C8\uB2E4. \uBC14\uB9AC\uC2A4\uD0C0 \uB4A4\uD3B8\uC758 \uC6D0\uC7AC\uB8CC \uCC3D\uACE0, \uACC4\uC0B0\uB300 \uD604\uAE08\uD568, \uC57C\uC678 \uD14C\uB77C\uC2A4 \uC88C\uC11D\uAE4C\uC9C0 \uBAA8\uB450 \uC11C\uB85C \uB2E4\uB978 \uAC10\uC2DC \uC804\uB7B5\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uD2B9\uD788 24\uC2DC\uAC04 \uCE74\uD398\uB294 \uC2EC\uC57C \uBB34\uC778 \uC2DC\uAC04\uB300 \uBCF4\uC548\uC774 \uCD5C\uC6B0\uC120 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "\uC5D0\uC2A4\uD504\uB808\uC18C \uBA38\uC2E0\uACFC \uB0C9\uC7A5\uACE0 \uC8FC\uBCC0\uC740 \uC218\uC99D\uAE30\xB7\uC2B5\uAE30\uB85C \uC778\uD574 \uC77C\uBC18 \uCE74\uBA54\uB77C\uAC00 \uACE0\uC7A5 \uB098\uAE30 \uC26C\uC6B0\uBBC0\uB85C \uBC29\uC218\uBC29\uC9C4 \uB4F1\uAE09\uC774 \uB192\uC740 \uBAA8\uB378\uC744 \uBC30\uCE58\uD558\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4. \uCE74\uC6B4\uD130 \uC704\uCABD\uC5D0\uB294 \uACE0\uD654\uC9C8 4K \uCE74\uBA54\uB77C\uB85C \uACB0\uC81C \uC7A5\uBA74\uC744 \uBA85\uD655\uD788 \uAE30\uB85D\uD558\uC138\uC694.", review: "\uC624\uB79C\uB9CC\uC5D0 \uB9E4\uCD9C\uC774 \uAC11\uC790\uAE30 \uC904\uC5B4\uC11C \uD655\uC778\uD574\uBCF4\uB2C8 \uC544\uB974\uBC14\uC774\uD2B8\uC0DD\uC774 \uCE74\uB4DC \uACB0\uC81C \uB300\uC2E0 \uD604\uAE08\uC744 \uBC1B\uACE0 \uD3EC\uC2A4\uC5D0 \uC785\uB825\uD558\uC9C0 \uC54A\uB294 \uD328\uD134\uC774\uC5C8\uC2B5\uB2C8\uB2E4. CCTV \uC601\uC0C1\uC73C\uB85C \uAC1D\uAD00\uC801 \uC99D\uAC70\uB97C \uD655\uBCF4\uD558\uACE0 \uC870\uC6A9\uD788 \uC815\uB9AC\uD560 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "\uD504\uB79C\uCC28\uC774\uC988 \uCE74\uD398\uC640 \uAC1C\uC778 \uCE74\uD398\uB294 CCTV \uC694\uAD6C \uC0AC\uD56D\uC774 \uD06C\uAC8C \uB2E4\uB985\uB2C8\uB2E4. \uD504\uB79C\uCC28\uC774\uC988\uB294 \uBCF8\uC0AC \uD45C\uC900\uC744 \uB9DE\uCDB0\uC57C \uD558\uACE0, \uAC1C\uC778 \uCE74\uD398\uB294 \uC6B4\uC601 \uD6A8\uC728 \uADF9\uB300\uD654\uAC00 \uC6B0\uC120\uC785\uB2C8\uB2E4. \uC591\uCABD \uBAA8\uB450 \uC778\uAC74\uBE44 \uC808\uAC10\uC744 \uC704\uD55C CCTV \uAE30\uBC18 \uC6D0\uACA9 \uAD00\uB9AC\uAC00 \uD2B8\uB80C\uB4DC\uAC00 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uACC4\uC808 \uBA54\uB274\xB7\uC2E0\uBA54\uB274 \uD504\uB85C\uBAA8\uC158 \uC2DC\uAE30\uC5D0 CCTV\uB85C \uC2E4\uC81C \uACE0\uAC1D \uBC18\uC751\uACFC \uC8FC\uBB38 \uD328\uD134\uC744 \uAD00\uCC30\uD558\uBA74 \uB9C8\uCF00\uD305 \uAC1C\uC120 \uD3EC\uC778\uD2B8\uAC00 \uBCF4\uC785\uB2C8\uB2E4. \uC9C4\uC5F4\uB300 \uC55E \uCCB4\uB958 \uC2DC\uAC04, \uBA54\uB274\uD310 \uC751\uC2DC \uC2DC\uAC04 \uB4F1\uC774 \uAC1D\uAD00\uC801 \uB370\uC774\uD130\uB85C \uCD95\uC801\uB429\uB2C8\uB2E4.", review: "\uC0AC\uC7A5 \uBD80\uC7AC \uC2DC \uC54C\uBC14\uC0DD \uAD00\uB9AC\uAC00 \uC5B4\uB824\uC6E0\uB294\uB370, \uC2A4\uB9C8\uD2B8\uD3F0\uC73C\uB85C \uC2E4\uC2DC\uAC04 \uB9E4\uC7A5\uC744 \uBCFC \uC218 \uC788\uC73C\uB2C8 \uAC71\uC815\uC774 \uC0AC\uB77C\uC84C\uC5B4\uC694. \uBD88\uD544\uC694\uD55C \uAC04\uC12D \uC5C6\uC774\uB3C4 \uB9E4\uC7A5 \uC6B4\uC601 \uC0C1\uD0DC\uAC00 \uD55C\uB208\uC5D0 \uD30C\uC545\uB429\uB2C8\uB2E4." }, { desc: "\uB514\uC800\uD2B8 \uCE74\uD398\uC640 \uBCA0\uC774\uCEE4\uB9AC \uCE74\uD398\uB294 \uACE0\uAC00 \uC81C\uD488\uC758 \uC9C4\uC5F4 \uAD00\uB9AC\uAC00 \uCD94\uAC00\uC801\uC778 \uACFC\uC81C\uC785\uB2C8\uB2E4. \uB9C8\uCE74\uB871\xB7\uCF00\uC774\uD06C\xB7\uD55C\uC815\uD310 \uC2DC\uC98C \uC0C1\uD488\uCC98\uB7FC \uB2E8\uAC00\uAC00 \uB192\uC740 \uC0C1\uD488\uC740 \uC808\uB3C4 \uC704\uD5D8\uC774 \uC788\uACE0, \uCF00\uC774\uD06C \uC9C4\uC5F4 \uB0C9\uC7A5\uACE0\uB294 \uC628\uB3C4 \uAD00\uB9AC \uBAA8\uB2C8\uD130\uB9C1\uB3C4 \uD544\uC694\uD569\uB2C8\uB2E4.", tip: "\uC81C\uACFC \uC791\uC5C5\uC2E4\uC740 \uC624\uBE10 \uC8FC\uBCC0\uC758 \uD654\uC7AC \uC608\uBC29, \uC704\uC0DD \uBCF5\uC7A5 \uC900\uC218 \uC5EC\uBD80, \uC7AC\uB8CC \uC7AC\uACE0 \uC2E4\uC2DC\uAC04 \uD655\uC778 \uB4F1 \uB2E4\uBAA9\uC801 \uD65C\uC6A9\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uC8FC\uBC29 \uC2A4\uD0DC\uD504\uC758 \uB3D9\uC120\uC774 \uD6A8\uC728\uC801\uC778\uC9C0\uB3C4 \uD568\uAED8 \uCCB4\uD06C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uCF00\uC774\uD06C \uC9C4\uC5F4 \uB0C9\uC7A5\uACE0 \uC628\uB3C4\uAC00 \uC774\uC0C1\uD574\uC11C \uD655\uC778\uD558\uB2C8 \uBB38\uC774 \uC81C\uB300\uB85C \uC548 \uB2EB\uD78C \uC0C1\uD0DC\uC600\uC5B4\uC694. CCTV\uB85C \uBC14\uB85C \uBC1C\uACAC\uD558\uACE0 \uCF00\uC774\uD06C\uB97C \uC0B4\uB9B4 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4. \uB9E4\uCD9C 20\uB9CC\uC6D0 \uC190\uC2E4\uC744 \uB9C9\uC740 \uC148\uC785\uB2C8\uB2E4." }, { desc: "\uC2A4\uD130\uB514\uCE74\uD398\xB7\uBD81\uCE74\uD398\xB7\uBCF4\uB4DC\uAC8C\uC784\uCE74\uD398 \uAC19\uC740 \uBCF5\uD569 \uACF5\uAC04\uD615 \uCE74\uD398\uB294 \uC77C\uBC18 \uCE74\uD398\uBCF4\uB2E4 \uC138\uBD84\uD654\uB41C \uBCF4\uC548\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uAC1C\uBCC4 \uC88C\uC11D\uC758 \uC0AC\uC801 \uACF5\uAC04\uACFC \uACF5\uC6A9 \uACF5\uAC04, \uD2B9\uD788 24\uC2DC\uAC04 \uC6B4\uC601 \uC2DC \uBB34\uC778 \uC2DC\uAC04\uB300 \uAD00\uB9AC\uAC00 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uC88C\uC11D\uBCC4 \uC774\uC6A9 \uC2DC\uAC04 \uAD00\uB9AC\uC640 \uC5F0\uB3D9\uD558\uBA74 \uC790\uB3D9 \uACFC\uAE08\uACFC \uC774\uC6A9 \uD328\uD134 \uBD84\uC11D\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uBD84\uC7C1 \uBC1C\uC0DD \uC2DC(\uC608: \uC88C\uC11D \uC120\uC810 \uB2E4\uD23C) \uC601\uC0C1\uC73C\uB85C \uAC1D\uAD00\uC801 \uD310\uB2E8\uC774 \uAC00\uB2A5\uD574 \uC6B4\uC601 \uBD80\uB2F4\uC774 \uD06C\uAC8C \uC904\uC5B4\uB4ED\uB2C8\uB2E4.", review: "\uC2A4\uD130\uB514\uCE74\uD398\uB97C \uBB34\uC778 \uC6B4\uC601\uD558\uB294\uB370 \uC2EC\uC57C\uC5D0 \uC220 \uCDE8\uD55C \uC190\uB2D8\uC774 \uC18C\uB780 \uD53C\uC6B0\uB294 \uC601\uC0C1\uC774 AI \uC54C\uB9BC\uC73C\uB85C \uBC14\uB85C \uC654\uC5B4\uC694. \uC6D0\uACA9\uC73C\uB85C \uACBD\uCC30\uC5D0 \uC2E0\uACE0\uD588\uACE0 \uB2E4\uB978 \uC190\uB2D8\uB4E4 \uD53C\uD574\uB97C \uCD5C\uC18C\uD654\uD560 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4." }],
    food: [{ desc: "\uC8FC\uBC29\uC758 \uD654\uC7AC \uC704\uD5D8, \uD640\uC758 \uACE0\uAC1D \uBD84\uC7C1, \uCE74\uC6B4\uD130\uC758 \uC815\uC0B0 \uAC80\uC99D\uC774 \uC74C\uC2DD\uC810 CCTV\uC758 3\uB300 \uD544\uC218 \uAC10\uC2DC \uD3EC\uC778\uD2B8\uC785\uB2C8\uB2E4.", tip: "\uC870\uB9AC \uACFC\uC815 \uC601\uC0C1\uC744 \uC800\uC7A5\uD558\uBA74 \uC704\uC0DD \uAC10\uC0AC \uB300\uBE44\uC640 \uC9C1\uC6D0 \uAD50\uC721 \uC790\uB8CC\uB85C \uD65C\uC6A9\uD560 \uC218 \uC788\uC5B4 \uC77C\uC11D\uC774\uC870\uC785\uB2C8\uB2E4.", review: "\uC8FC\uBC29\uC5D0\uC11C \uAC00\uC2A4 \uBD88\uC744 \uC548 \uB044\uACE0 \uD1F4\uADFC\uD55C \uC801\uC774 \uC788\uC5C8\uB294\uB370, CCTV \uC571 \uC54C\uB9BC \uB355\uBD84\uC5D0 \uBC14\uB85C \uBC1C\uACAC\uD558\uACE0 \uB300\uC751\uD588\uC2B5\uB2C8\uB2E4. \uD654\uC7AC \uD55C \uAC74 \uB9C9\uC740 \uAC70\uC608\uC694." }, { desc: "\uD55C\uC2DD\xB7\uC591\uC2DD\xB7\uC77C\uC2DD\xB7\uC911\uC2DD \uAC01 \uC74C\uC2DD\uC810\uC740 \uC8FC\uBC29 \uAD6C\uC870\uAC00 \uB2E4\uB974\uAE30 \uB54C\uBB38\uC5D0 CCTV \uBC30\uCE58 \uC804\uB7B5\uB3C4 \uB2E4\uB985\uB2C8\uB2E4. \uD654\uAD6C\uAC00 \uB9CE\uC740 \uD55C\uC2DD \uC8FC\uBC29\uC740 \uD654\uC7AC \uAC10\uC9C0 \uCE74\uBA54\uB77C\uAC00 \uC911\uC694\uD558\uACE0, \uC2DD\uAE30 \uC138\uCC99 \uACF5\uAC04\uC740 \uC218\uC99D\uAE30 \uB300\uC751 \uBC29\uC218 \uCE74\uBA54\uB77C, \uD50C\uB808\uC774\uD305 \uACF5\uAC04\uC740 \uACE0\uD654\uC9C8 \uCE74\uBA54\uB77C\uB85C \uC704\uC0DD \uAD00\uB9AC\uB97C \uAE30\uB85D\uD569\uB2C8\uB2E4.", tip: "\uD3EC\uC2A4\uAE30\uC640 \uC5F0\uB3D9\uD558\uBA74 \uACB0\uC81C \uC2DC\uC810 \uC601\uC0C1\uC744 \uC790\uB3D9 \uB9E4\uCE6D\uD560 \uC218 \uC788\uC5B4 \uC8FC\uBB38 \uC624\uB958\uB098 \uD658\uBD88 \uBD84\uC7C1 \uC2DC \uBE60\uB974\uAC8C \uD655\uC778 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uC8FC\uBB38 \uB0B4\uC6A9\uACFC \uC2E4\uC81C \uB098\uAC04 \uC74C\uC2DD\uC774 \uC77C\uCE58\uD558\uB294\uC9C0\uB3C4 \uD6C4\uC18D \uAC80\uC99D\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uCDE8\uC18C \uC8FC\uBB38\uC774 \uB4E4\uC5B4\uC654\uB294\uB370 \uC774\uBBF8 \uC870\uB9AC\uB41C \uC74C\uC2DD\uC5D0 \uB300\uD55C \uC774\uC57C\uAE30\uAC00 \uC560\uB9E4\uD574\uC11C \uACE0\uAC1D\uACFC \uAC08\uB4F1\uC774 \uB420 \uBED4\uD588\uC5B4\uC694. CCTV\uB85C \uC870\uB9AC \uC2DC\uC810\uC744 \uD655\uC778\uD558\uB2C8 \uCDE8\uC18C \uC804 \uC774\uBBF8 \uC644\uC131\uB41C \uC0C1\uD0DC\uC600\uACE0, \uACE0\uAC1D\uB3C4 \uC218\uAE0D\uD558\uACE0 \uACB0\uC81C\uD558\uC168\uC2B5\uB2C8\uB2E4." }, { desc: "\uBC30\uB2EC \uC8FC\uBB38 \uBE44\uC911\uC774 \uB192\uC740 \uC74C\uC2DD\uC810\uC740 \uBC30\uB2EC \uAE30\uC0AC \uCD9C\uC785 \uAD00\uB9AC\uAC00 \uCD94\uAC00 \uACFC\uC81C\uC785\uB2C8\uB2E4. \uC678\uBD80\uC5D0\uC11C \uC790\uC8FC \uB4DC\uB098\uB4DC\uB294 \uBC30\uB2EC \uAE30\uC0AC\uB4E4\uC774 \uB9CE\uC544 \uC8FC\uBC29 \uB4B7\uBB38\xB7\uD53D\uC5C5 \uC874\uC758 \uBCF4\uC548\uACFC \uB3D9\uC2DC\uC5D0 \uBC30\uB2EC \uC74C\uC2DD\uC774 \uC81C\uB300\uB85C \uC804\uB2EC\uB410\uB294\uC9C0 \uAE30\uB85D\uD558\uB294 \uAC83\uC774 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: '\uD53D\uC5C5 \uC874\uC5D0 \uC804\uC6A9 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uBA74 "\uC74C\uC2DD\uC744 \uBC1B\uC9C0 \uBABB\uD588\uB2E4"\uB294 \uD074\uB808\uC784\uC5D0 \uC601\uC0C1\uC73C\uB85C \uC99D\uBE59 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uBC30\uB2EC \uAE30\uC0AC\uAC00 \uD53D\uC5C5\uD558\uB294 \uC2DC\uC810\uACFC \uBC30\uB2EC\uC571 \uD0C0\uC784\uC2A4\uD0EC\uD504\uB97C \uB9E4\uCE6D\uD558\uBA74 \uBD84\uC7C1\uC774 \uAC70\uC758 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4.', review: "\uBC30\uB2EC\uC571 \uACE0\uAC1D\uC774 \uC74C\uC2DD\uC744 \uBABB \uBC1B\uC558\uB2E4\uACE0 \uD658\uBD88\uC744 \uC694\uCCAD\uD588\uB294\uB370, \uD53D\uC5C5 \uC874 \uC601\uC0C1\uC5D0 \uAE30\uC0AC\uAC00 \uC815\uC0C1\uC801\uC73C\uB85C \uD53D\uC5C5\uD558\uB294 \uBAA8\uC2B5\uC774 \uCC0D\uD600\uC788\uC5C8\uC2B5\uB2C8\uB2E4. \uC601\uC0C1 \uC99D\uBE59\uC73C\uB85C \uC798\uBABB\uB41C \uD658\uBD88\uC744 \uB9C9\uC744 \uC218 \uC788\uC5C8\uC5B4\uC694." }, { desc: "24\uC2DC\uAC04 \uC6B4\uC601 \uC2DD\uB2F9\xB7\uC2EC\uC57C\uC2DD\uB2F9\uC740 \uC0C8\uBCBD \uC2DC\uAC04\uB300 \uACE0\uAC1D \uBD84\uC7C1\uACFC \uCE68\uC785 \uC704\uD5D8\uC774 \uC77C\uBC18 \uC2DD\uB2F9\uBCF4\uB2E4 \uD6E8\uC52C \uB192\uC2B5\uB2C8\uB2E4. \uCDE8\uAC1D \uB300\uC751, \uBB34\uB2E8 \uCDE8\uC2DD, \uC8FC\uBC29 \uCE68\uC785 \uAC19\uC740 \uC0C1\uD669\uC5D0 \uB300\uBE44\uD55C \uAC15\uB825\uD55C \uC57C\uAC04 \uAC10\uC2DC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", tip: "AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0\uC640 \uC74C\uC131 \uAC10\uC9C0\uB97C \uBCD1\uD589\uD558\uBA74 \uC0C8\uBCBD \uC2DC\uAC04\uB300 \uC774\uC0C1 \uC0C1\uD669\uC744 \uC989\uC2DC \uC54C\uB9BC\uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD2B9\uD788 \uC8FC\uBC29 \uB4B7\uBB38\uC758 \uC2EC\uC57C \uCE68\uC785\uC740 \uC0AC\uC7A5\uC5D0\uAC8C \uC9C1\uC811 \uD478\uC2DC \uC54C\uB9BC\uC73C\uB85C \uC804\uB2EC\uB418\uC5B4\uC57C \uBE60\uB978 \uB300\uC751\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", review: "\uC0C8\uBCBD 3\uC2DC\uC5D0 \uB9E4\uC7A5 \uB4B7\uBB38 \uC774\uC0C1 \uC54C\uB9BC\uC774 \uC654\uC5B4\uC694. \uD655\uC778\uD574\uBCF4\uB2C8 \uC9C1\uC6D0\uC774 \uC544\uB2CC \uC0AC\uB78C\uC774 \uCC3D\uACE0\uB97C \uB4A4\uC9C0\uACE0 \uC788\uC5C8\uACE0, \uC989\uC2DC \uACBD\uCC30 \uC2E0\uACE0\uB85C \uAC80\uAC70\uD588\uC2B5\uB2C8\uB2E4. CCTV\uAC00 \uC5C6\uC5C8\uC73C\uBA74 \uB9E4\uC77C \uC7AC\uB8CC\uAC00 \uC870\uAE08\uC529 \uC0AC\uB77C\uC9C0\uB294 \uAC78 \uBAB0\uB790\uC744 \uAC70\uC608\uC694." }, { desc: "\uC18C\uADDC\uBAA8 \uAC00\uC871 \uC2DD\uB2F9\uACFC \uC911\uB300\uD615 \uC74C\uC2DD\uC810\uC740 CCTV \uD544\uC694 \uC2A4\uD399\uC774 \uB2E4\uB985\uB2C8\uB2E4. \uC18C\uADDC\uBAA8\uB294 2~4\uCC44\uB110 \uAE30\uBCF8 \uBAA8\uB378\uB85C \uCDA9\uBD84\uD558\uC9C0\uB9CC, \uC911\uB300\uD615\uC740 8~16\uCC44\uB110\uC5D0 \uC57C\uC678 \uC8FC\uCC28\uC7A5 \uAC10\uC2DC\uAE4C\uC9C0 \uACE0\uB824\uD574\uC57C \uD569\uB2C8\uB2E4. \uC608\uC0B0\uACFC \uADDC\uBAA8\uC5D0 \uB9DE\uB294 \uB9DE\uCDA4 \uC124\uACC4\uAC00 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: "\uC8FC\uCC28\uC7A5 \uAC10\uC2DC\uB294 \uCC28\uB7C9 \uBC88\uD638\uD310 \uC2DD\uBCC4 \uAC00\uB2A5\uD55C \uD574\uC0C1\uB3C4\uAC00 \uD544\uC218\uC774\uBA70, 4K \uCE74\uBA54\uB77C\uC5D0 LPR(\uBC88\uD638\uD310 \uC778\uC2DD) \uAE30\uB2A5\uC744 \uCD94\uAC00\uD558\uBA74 \uCC28\uB7C9 \uAD00\uB9AC\uAE4C\uC9C0 \uC790\uB3D9\uD654\uB429\uB2C8\uB2E4. \uB300\uD615 \uB9E4\uC7A5\uC758 \uC8FC\uCC28\uC7A5 \uBD84\uC7C1\uC774 \uD06C\uAC8C \uAC10\uC18C\uD569\uB2C8\uB2E4.", review: "\uC8FC\uCC28\uC7A5\uC5D0\uC11C \uACE0\uAC1D \uCC28\uB7C9 \uC811\uCD09 \uC0AC\uACE0\uAC00 \uB0AC\uB294\uB370 \uAC00\uD574 \uCC28\uB7C9\uC774 \uB3C4\uC8FC\uD588\uC5B4\uC694. \uBC88\uD638\uD310 \uC2DD\uBCC4 \uCE74\uBA54\uB77C \uB355\uBD84\uC5D0 \uBC88\uD638\uB97C \uD2B9\uC815\uD574\uC11C \uBCF4\uD5D8 \uCC98\uB9AC\uB97C \uD560 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4. \uC77C\uBC18 \uCE74\uBA54\uB77C\uC600\uB2E4\uBA74 \uBD88\uAC00\uB2A5\uD588\uC744 \uC0C1\uD669\uC785\uB2C8\uB2E4." }],
    bar: [{ desc: "\uC57C\uAC04 \uC601\uC5C5 \uC2DC \uC8FC\uCDE8 \uACE0\uAC1D\uC758 \uC2DC\uBE44, \uD604\uAE08 \uBD84\uC2E4, \uAE30\uBB3C \uD30C\uC190\uC774 \uC8FC\uC810 CCTV\uC758 \uD575\uC2EC \uACFC\uC81C\uC785\uB2C8\uB2E4. \uC0C8\uBCBD \uC2DC\uAC04\uB300 \uD480\uCEEC\uB7EC \uC57C\uAC04 \uCD2C\uC601\uC774 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uC18C\uB780\uC774 \uBC1C\uC0DD\uD55C \uC2DC\uC810\uC758 \uC601\uC0C1\uC744 \uC989\uC2DC \uCD94\uCD9C\uD560 \uC218 \uC788\uC5B4 \uACBD\uCC30 \uC2E0\uACE0\uB098 \uBCF4\uD5D8 \uCCAD\uAD6C \uC2DC \uACB0\uC815\uC801 \uC99D\uAC70\uAC00 \uB429\uB2C8\uB2E4.", review: "\uC0C8\uBCBD\uC5D0 \uCDE8\uAC1D\uC774 \uD14C\uC774\uBE14\uC744 \uBD80\uC218\uACE0 \uB3C4\uC8FC\uD588\uB294\uB370 CCTV\uC5D0 \uC5BC\uAD74\uC774 \uC120\uBA85\uD558\uAC8C \uCC0D\uD600\uC11C \uACBD\uCC30\uC774 \uBC14\uB85C \uD2B9\uC815\uD588\uC5B4\uC694. \uC5C6\uC5C8\uC73C\uBA74 \uC218\uB9AC\uBE44 \uC790\uBD80\uB2F4\uC774\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "\uC640\uC778\uBC14\xB7\uC704\uC2A4\uD0A4\uBC14\xB7\uCE75\uD14C\uC77C\uBC14 \uAC19\uC740 \uACE0\uAE09 \uC8FC\uC810\uC740 \uBD84\uC704\uAE30 \uC720\uC9C0\uB97C \uC704\uD574 \uB208\uC5D0 \uB744\uC9C0 \uC54A\uB294 \uB3C4\uC5B4\uD615\xB7\uB3D4\uD615 \uCE74\uBA54\uB77C\uAC00 \uC120\uD638\uB429\uB2C8\uB2E4. \uBCF4\uC548\uC740 \uC720\uC9C0\uD558\uB418 \uACE0\uAC1D\uC5D0\uAC8C \uBD88\uD3B8\uD568\uC744 \uC8FC\uC9C0 \uC54A\uB294 \uBC30\uCE58\uAC00 \uBE0C\uB79C\uB4DC \uC774\uBBF8\uC9C0\uC640 \uC9C1\uACB0\uB429\uB2C8\uB2E4.", tip: "\uACE0\uAC00 \uC8FC\uB958 \uBCF4\uAD00 \uACF5\uAC04\uC5D0 \uBCC4\uB3C4 \uACE0\uD654\uC9C8 \uCE74\uBA54\uB77C\uB97C \uB450\uBA74 \uB3C4\uB09C\uACFC \uC7AC\uACE0 \uAD00\uB9AC\uB97C \uB3D9\uC2DC\uC5D0 \uCC98\uB9AC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD2B9\uD788 \uC624\uD508 \uBCF4\uD2C0 \uC0C1\uD0DC\uC758 \uACE0\uAC00 \uC704\uC2A4\uD0A4\uB294 \uAD00\uB9AC\uAC00 \uC18C\uD640\uD558\uBA74 \uC9C1\uC6D0\uC758 \uBB34\uB2E8 \uC2DC\uC74C \uB4F1 \uC228\uC740 \uC190\uC2E4\uC774 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.", review: "40\uB144\uC0B0 \uC704\uC2A4\uD0A4\uB97C \uD55C \uC794\uC529 \uD310\uB9E4\uD588\uB294\uB370 \uBCD1 \uC794\uB7C9\uACFC \uB9E4\uCD9C\uC774 \uC548 \uB9DE\uC558\uC5B4\uC694. CCTV\uB85C \uBCF4\uB2C8 \uC9C1\uC6D0\uC774 \uC190\uB2D8\uC5D0\uAC8C \uBB34\uB8CC\uB85C \uB098\uB220\uC8FC\uACE0 \uC788\uC5C8\uC2B5\uB2C8\uB2E4. \uC7AC\uACE0 \uAD00\uB9AC\uAC00 \uBA85\uD655\uD574\uC9C0\uB2C8 \uC6D4 \uC190\uC2E4\uC561\uC774 \uC218\uBC31\uB9CC\uC6D0 \uC904\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "\uD638\uD504\uC9D1\xB7\uD3EC\uCC28\xB7\uC2E4\uB0B4\uD3EC\uCC28 \uAC19\uC740 \uCE90\uC8FC\uC5BC\uD55C \uC8FC\uC810\uC740 \uC88C\uC11D\uC218\uAC00 \uB9CE\uACE0 \uD68C\uC804\uC728\uC774 \uB192\uC544 \uBD84\uC7C1 \uBC1C\uC0DD \uBE48\uB3C4\uAC00 \uB192\uC740 \uD3B8\uC785\uB2C8\uB2E4. \uD14C\uC774\uBE14 \uBC88\uD638\uBCC4 \uC8FC\uBB38\uACFC \uACB0\uC81C \uB9E4\uCE6D, \uC88C\uC11D \uC774\uB3D9 \uCD94\uC801, \uC601\uC218\uC99D \uBD84\uC7C1 \uB300\uC751\uC774 \uC8FC\uC694 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "\uD14C\uC774\uBE14 \uBC88\uD638\uAC00 CCTV\uC5D0 \uD568\uAED8 \uAE30\uB85D\uB418\uBA74 \uC8FC\uBB38 \uBC88\uD638\uC640 \uD14C\uC774\uBE14\uC774 \uC790\uB3D9 \uB9E4\uCE6D\uB418\uC5B4 \uC815\uC0B0 \uC624\uB958\uAC00 \uC904\uC5B4\uB4ED\uB2C8\uB2E4. \uD2B9\uD788 \uBC14\uC05C \uC2DC\uAC04\uB300\uC5D0 \uD14C\uC774\uBE14 \uC774\uB3D9\uC774 \uC7A6\uC740 \uACBD\uC6B0 \uC774 \uAE30\uB2A5\uC774 \uD06C\uAC8C \uC720\uC6A9\uD569\uB2C8\uB2E4.", review: "4\uC778 \uD14C\uC774\uBE14\uC774 8\uBA85 \uB2E8\uCCB4\uB85C \uB298\uC5B4\uB09C \uAC83\uC744 \uC9C1\uC6D0\uC774 \uB193\uCCD0\uC11C \uCD94\uAC00 \uBA54\uB274\uAC00 \uB204\uB77D\uB410\uC5B4\uC694. \uC601\uC0C1\uC744 \uB3CC\uB824\uBCF4\uB2C8 \uBA85\uD655\uD574\uC11C \uB2E4\uC74C\uB0A0 \uC815\uC911\uD788 \uCD94\uAC00 \uC815\uC0B0\uC744 \uC694\uCCAD\uD588\uACE0, \uC190\uB2D8\uB3C4 \uC774\uD574\uD558\uACE0 \uACB0\uC81C\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uC774\uC790\uCE74\uC57C\xB7\uC77C\uC2DD \uC8FC\uC810\uC740 \uCE74\uC6B4\uD130\uC11D\uACFC \uD14C\uC774\uBE14\uC11D\uC774 \uBD84\uB9AC\uB41C \uAD6C\uC870\uAC00 \uB9CE\uC2B5\uB2C8\uB2E4. \uCE74\uC6B4\uD130 \uC704\uC758 \uC870\uB9AC \uACFC\uC815\uC744 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uBCF4\uC5EC\uC8FC\uB294 \uAC83\uC774 \uB9E4\uB825 \uD3EC\uC778\uD2B8\uB77C CCTV\uB294 \uC624\uD788\uB824 \uCF58\uD150\uCE20 \uB9C8\uCF00\uD305\uC6A9\uC73C\uB85C \uD65C\uC6A9 \uAC00\uB2A5\uD55C \uD2B9\uC774\uD55C \uC5C5\uC885\uC785\uB2C8\uB2E4.", tip: "\uCE74\uC6B4\uD130 \uC870\uB9AC \uC601\uC0C1\uC744 SNS \uB77C\uC774\uBE0C \uC2A4\uD2B8\uB9AC\uBC0D\uACFC \uC5F0\uB3D9\uD558\uBA74 \uB9E4\uC7A5 \uD64D\uBCF4 \uD6A8\uACFC\uAE4C\uC9C0 \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACE0\uAC1D\uB3C4 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uC694\uB9AC\uB418\uB294 \uACFC\uC815\uC744 \uBCF4\uBA74\uC11C \uAE30\uB2E4\uB9AC\uB294 \uC7AC\uBBF8\uB97C \uB290\uB08D\uB2C8\uB2E4.", review: "\uCE74\uC6B4\uD130\uC5D0\uC11C \uC0DD\uC120 \uC190\uC9C8\uD558\uB294 \uC7A5\uBA74\uC744 \uC720\uD29C\uBE0C \uC1FC\uCE20\uB85C \uD3B8\uC9D1\uD574 \uC62C\uB838\uB354\uB2C8 \uC601\uC0C1 \uD558\uB098\uB85C \uB9E4\uC7A5 \uC778\uC9C0\uB3C4\uAC00 \uC62C\uB77C\uAC14\uC5B4\uC694. CCTV\uAC00 \uBCF4\uC548 \uC7A5\uBE44\uC5D0\uC11C \uCF58\uD150\uCE20 \uC18C\uC2A4\uB85C \uBC14\uB010 \uC88B\uC740 \uC0AC\uB840\uC785\uB2C8\uB2E4." }, { desc: "\uB178\uB798\uC8FC\uC810\xB7\uB8F8\uC0B4\uB871\xB7\uAC10\uC131\uC8FC\uC810 \uAC19\uC740 \uB8F8\uC774 \uC788\uB294 \uC8FC\uC810\uC740 \uAC1C\uC778\uC815\uBCF4 \uBCF4\uD638\uAC00 \uD2B9\uD788 \uC911\uC694\uD569\uB2C8\uB2E4. \uB8F8 \uB0B4\uBD80\uB294 \uB179\uD654\uD560 \uC218 \uC5C6\uACE0 \uACF5\uC6A9 \uACF5\uAC04\uB9CC \uAC00\uB2A5\uD558\uBBC0\uB85C \uBC95\uC801 \uAC00\uC774\uB4DC\uB77C\uC778\uC744 \uC815\uD655\uD788 \uC9C0\uCF1C\uC57C \uBD84\uC7C1\uC744 \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uB8F8 \uC678\uBD80 \uBCF5\uB3C4\uC640 \uCD9C\uC785\uAD6C\uB9CC \uCD2C\uC601\uD558\uACE0, \uB8F8 \uB0B4\uBD80\uB294 \uC74C\uC131\uB179\uC74C\uB3C4 \uC81C\uC678\uD558\uB294 \uAC83\uC774 \uC548\uC804\uD569\uB2C8\uB2E4. \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC704\uBC18 \uC2DC \uACFC\uD0DC\uB8CC\uC640 \uC601\uC5C5 \uC911\uB2E8 \uCC98\uBD84\uAE4C\uC9C0 \uBC1B\uC744 \uC218 \uC788\uC5B4 \uCD08\uAE30 \uC124\uACC4 \uB2E8\uACC4\uC5D0\uC11C \uC804\uBB38\uAC00 \uC0C1\uB2F4\uC774 \uD544\uC218\uC785\uB2C8\uB2E4.", review: "CCTV \uC124\uCE58 \uC804\uC5D0 \uBCC0\uD638\uC0AC \uC790\uBB38\uC744 \uBC1B\uC544 \uB8F8 \uB0B4\uBD80\uB294 \uC81C\uC678\uD588\uB294\uB370 \uB355\uBD84\uC5D0 \uBBFC\uC6D0 \uB4E4\uC5B4\uC654\uC744 \uB54C\uB3C4 \uD569\uBC95 \uBC94\uC704 \uB0B4 \uC124\uCE58\uC600\uB2E4\uB294 \uC99D\uBA85\uC774 \uAC00\uB2A5\uD588\uC5B4\uC694. \uCD08\uAE30 \uBE44\uC6A9\uC744 \uC544\uB07C\uC9C0 \uB9D0\uC544\uC57C \uD558\uB294 \uBD80\uBD84\uC785\uB2C8\uB2E4." }],
    leisure: [{ desc: "\uC2DC\uC124\uBB3C \uC548\uC804\uC0AC\uACE0, \uB3C4\uB09C, \uC774\uC6A9 \uC2DC\uAC04 \uBD84\uC7C1\uC774 \uB808\uC800 \uC5C5\uC885 CCTV\uC758 \uC8FC\uC694 \uAC10\uC2DC \uB300\uC0C1\uC785\uB2C8\uB2E4. \uB113\uC740 \uACF5\uAC04\uC740 \uC640\uC774\uB4DC \uC575\uAE00\uC774 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uC774\uC6A9 \uC2DC\uAC04 \uCD08\uACFC \uBD84\uC7C1\uC774 \uC0DD\uAE30\uBA74 CCTV \uD0C0\uC784\uC2A4\uD0EC\uD504\uB85C \uC785\uC7A5\xB7\uD1F4\uC7A5 \uC2DC\uAC04\uC744 \uAC1D\uAD00\uC801\uC73C\uB85C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uB77D\uCEE4\uB8F8 \uC55E\uC5D0 \uCE74\uBA54\uB77C\uB97C \uC124\uCE58\uD55C \uB4A4\uB85C \uBB3C\uAC74 \uBD84\uC2E4 \uBBFC\uC6D0\uC774 \uC0AC\uB77C\uC84C\uC5B4\uC694. \uB204\uAC00 \uC5B8\uC81C \uB4E4\uC5B4\uC654\uB294\uC9C0 \uC601\uC0C1\uC73C\uB85C \uB2E4 \uD655\uC778\uB429\uB2C8\uB2E4." }, { desc: "\uD5EC\uC2A4\uC7A5\xB7\uD544\uB77C\uD14C\uC2A4\xB7\uC694\uAC00\uC6D0\uC740 \uD0C8\uC758\uC2E4\xB7\uC0E4\uC6CC\uC2E4\uC758 \uAC1C\uC778\uC815\uBCF4 \uC774\uC288\uAC00 \uD2B9\uD788 \uBBFC\uAC10\uD569\uB2C8\uB2E4. \uACF5\uC6A9 \uACF5\uAC04(\uB85C\uBE44\xB7\uC6B4\uB3D9 \uAD6C\uC5ED)\uB9CC \uCD2C\uC601\uD558\uACE0 \uB77C\uCEE4\uB8F8 \uB0B4\uBD80\uB294 \uC808\uB300 \uD3EC\uD568\uC2DC\uD0A4\uC9C0 \uB9D0\uC544\uC57C \uD569\uB2C8\uB2E4.", tip: "\uC6B4\uB3D9 \uAE30\uAD6C \uC8FC\uBCC0\uC5D0 \uC548\uC804\uC0AC\uACE0 \uB300\uC751\uC6A9\uC73C\uB85C \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uBA74 \uBD80\uC0C1 \uC0AC\uACE0 \uC2DC \uCC45\uC784 \uC18C\uC7AC\uB97C \uBA85\uD655\uD788 \uD560 \uC218 \uC788\uC5B4 \uBCF4\uD5D8 \uCC98\uB9AC\uC640 PT\uC0F5 \uC6B4\uC601 \uB9AC\uC2A4\uD06C \uAD00\uB9AC\uC5D0 \uACB0\uC815\uC801\uC785\uB2C8\uB2E4.", review: "\uB7EC\uB2DD\uBA38\uC2E0\uC5D0\uC11C \uB118\uC5B4\uC9C4 \uD68C\uC6D0\uC774 \uD2B8\uB808\uC774\uB108 \uBD80\uC8FC\uC758\uB77C\uACE0 \uC8FC\uC7A5\uD588\uB294\uB370, CCTV\uC5D0 \uBCF8\uC778\uC774 \uC74C\uC545 \uB4E3\uB290\uB77C \uC8FC\uC758\uB97C \uAE30\uC6B8\uC774\uC9C0 \uC54A\uC740 \uC7A5\uBA74\uC774 \uCC0D\uD600\uC788\uC5C8\uC5B4\uC694. \uC5B5\uC6B8\uD55C \uC18C\uC1A1\uC744 \uB9C9\uC744 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "PC\uBC29\xB7\uBCF4\uB4DC\uAC8C\uC784\uCE74\uD398 \uAC19\uC740 \uC2DC\uAC04\uC81C \uC5C5\uC885\uC740 \uC774\uC6A9 \uC2DC\uAC04 \uAD00\uB9AC\uAC00 \uB9E4\uCD9C\uACFC \uC9C1\uACB0\uB429\uB2C8\uB2E4. \uC88C\uC11D\uBCC4 \uC785\uC7A5\xB7\uD1F4\uC7A5 \uC2DC\uAC04\uC774 \uC815\uD655\uD788 \uAE30\uB85D\uB418\uC5B4\uC57C \uACFC\uAE08 \uBD84\uC7C1\uC774 \uC5C6\uACE0, \uC2EC\uC57C \uBB34\uC778 \uC2DC\uAC04\uB300\uC758 \uBCF4\uC548\uB3C4 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: "\uD3EC\uC2A4 \uACB0\uC81C \uC2DC\uC2A4\uD15C\uACFC CCTV\uB97C \uC5F0\uB3D9\uD558\uBA74 \uC88C\uC11D \uBC88\uD638\xB7\uC785\uC7A5 \uC2DC\uAC01\xB7\uACB0\uC81C \uAE08\uC561\uC774 \uC601\uC0C1\uACFC \uB9E4\uCE6D\uB418\uC5B4 \uBD84\uC7C1 \uAC00\uB2A5\uC131\uC774 \uAC70\uC758 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4. \uBB34\uC778 \uC6B4\uC601 \uC2DC \uD2B9\uD788 \uC720\uC6A9\uD569\uB2C8\uB2E4.", review: "\uC2EC\uC57C\uC5D0 \uACB0\uC81C \uC5C6\uC774 \uAC8C\uC784\uD558\uB2E4 \uB3C4\uC8FC\uD55C \uACE0\uAC1D\uC774 \uC788\uC5C8\uB294\uB370 CCTV\uB85C \uC5BC\uAD74\uC744 \uD2B9\uC815\uD558\uACE0 \uACB0\uC81C \uAE30\uB85D\uACFC \uC5F0\uB3D9\uD574 \uB2E4\uC74C \uBC29\uBB38 \uC2DC \uCD94\uAC00 \uACB0\uC81C \uBC1B\uC558\uC5B4\uC694. \uBB34\uC778 \uC6B4\uC601\uC758 \uD544\uC218 \uC7A5\uBE44\uC785\uB2C8\uB2E4." }, { desc: "\uC2A4\uD06C\uB9B0\uACE8\uD504\xB7\uB2F9\uAD6C\uC7A5\xB7\uBCFC\uB9C1\uC7A5 \uAC19\uC740 \uC2E4\uB0B4 \uC2A4\uD3EC\uCE20 \uC5C5\uC885\uC740 \uC7A5\uBE44 \uAD00\uB9AC\uC640 \uACE0\uAC1D \uC548\uC804\uC774 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uACE0\uAC00\uC758 \uACE8\uD504\uD074\uB7FD\xB7\uD050\uB300\xB7\uBCFC\uB9C1\uACF5\uC740 \uB3C4\uB09C \uC704\uD5D8\uC774 \uC788\uACE0, \uBD80\uC0C1 \uC0AC\uACE0 \uBC1C\uC0DD \uC2DC \uC601\uC0C1 \uC99D\uAC70\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uAC01 \uB8F8\xB7\uB808\uC778\uBCC4\uB85C \uB3C5\uB9BD \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uBA74 \uC774\uC6A9 \uC2DC\uAC04 \uC790\uB3D9 \uACC4\uC0B0\uACFC \uC7A5\uBE44 \uC0C1\uD0DC \uC810\uAC80\uC744 \uB3D9\uC2DC\uC5D0 \uCC98\uB9AC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB8F8 \uB0B4 \uD504\uB77C\uC774\uBC84\uC2DC\uB294 \uBCF4\uC7A5\uD558\uB418 \uC785\uCD9C\uC785\uB9CC \uAE30\uB85D\uD558\uB294 \uBC29\uC2DD\uC774 \uBC95\uC801\uC73C\uB85C \uC548\uC804\uD569\uB2C8\uB2E4.", review: "\uACE0\uAC1D\uC774 \uC2A4\uD06C\uB9B0\uACE8\uD504 \uC911 \uD654\uBA74\uC774 \uACE0\uC7A5\uB0AC\uB2E4\uACE0 \uD658\uBD88 \uC694\uCCAD\uD588\uB294\uB370, CCTV\uB97C \uBCF4\uB2C8 \uBCF8\uC778\uC774 \uACE8\uD504\uD074\uB7FD\uC73C\uB85C \uD654\uBA74\uC744 \uB54C\uB9B0 \uAC8C \uC6D0\uC778\uC774\uC5C8\uC5B4\uC694. \uC624\uD788\uB824 \uC218\uB9AC\uBE44 \uCCAD\uAD6C\uB85C \uC5ED\uC804\uB410\uC2B5\uB2C8\uB2E4." }, { desc: "\uD0A4\uC988\uCE74\uD398\xB7\uB180\uC774\uBC29\uC740 \uC544\uC774\uB4E4 \uC548\uC804\uC774 \uCD5C\uC6B0\uC120\uC774\uACE0 \uD559\uBD80\uBAA8 \uC548\uC2EC \uC694\uC18C\uAC00 \uB9E4\uCD9C\uC744 \uC88C\uC6B0\uD569\uB2C8\uB2E4. \uCE35\uACE0\uAC00 \uB192\uC740 \uB180\uC774 \uAE30\uAD6C, \uBCFC\uD480\uC7A5, \uD2B8\uB7A8\uD3F4\uB9B0 \uAC19\uC740 \uACE0\uC704\uD5D8 \uAD6C\uC5ED\uC740 \uD2B9\uD788 \uC138\uBC00\uD55C \uAC10\uC2DC\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uB180\uC774 \uAD6C\uC5ED \uC804\uCCB4\uB97C \uC0AC\uAC01\uC9C0\uB300 \uC5C6\uC774 \uCD2C\uC601\uD558\uACE0, \uD559\uBD80\uBAA8\uAC00 \uC694\uCCAD\uD558\uBA74 \uC790\uB140\uC758 \uC601\uC0C1\uB9CC \uC989\uC2DC \uCD94\uCD9C\uD574\uC11C \uBCF4\uC5EC\uC904 \uC218 \uC788\uC5B4\uC57C \uD569\uB2C8\uB2E4. \uC544\uC774\uB4E4 \uAC04 \uB2E4\uD23C\uC774\uB098 \uBD80\uC0C1 \uC0AC\uACE0 \uC2DC \uC0C1\uD669\uC744 \uC815\uD655\uD788 \uD30C\uC545\uD560 \uC218 \uC788\uC5B4 \uD559\uBD80\uBAA8 \uC2E0\uB8B0\uB3C4\uAC00 \uD06C\uAC8C \uC62C\uB77C\uAC11\uB2C8\uB2E4.", review: "\uC544\uC774\uAC00 \uB2E4\uB978 \uC544\uC774\uC5D0\uAC8C \uB9DE\uC558\uB2E4\uB294 \uD559\uBD80\uBAA8 \uBBFC\uC6D0\uC774 \uC788\uC5C8\uB294\uB370 \uC601\uC0C1\uC744 \uBCF4\uB2C8 \uC11C\uB85C \uC7A5\uB09C\uCE58\uB2E4\uAC00 \uAC19\uC774 \uB118\uC5B4\uC9C4 \uAC83\uC774\uC5C8\uC5B4\uC694. \uAC1D\uAD00\uC801\uC73C\uB85C \uBCF4\uC5EC\uB4DC\uB9AC\uB2C8 \uBC14\uB85C \uC624\uD574\uAC00 \uD480\uB838\uACE0 \uC624\uD788\uB824 \uB354 \uC2E0\uB8B0\uD558\uC2DC\uAC8C \uB410\uC2B5\uB2C8\uB2E4." }],
    edu: [{ desc: "\uD559\uC0DD \uC548\uC804, \uAC15\uC0AC \uC218\uC5C5 \uBAA8\uB2C8\uD130\uB9C1, \uCD9C\uC785 \uD1B5\uC81C\uAC00 \uD559\uC6D0 CCTV\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uD559\uBD80\uBAA8 \uC548\uC2EC \uD6A8\uACFC\uB3C4 \uD07D\uB2C8\uB2E4.", tip: "\uC218\uC5C5 \uC7A5\uBA74\uC744 \uB179\uD654\uD558\uBA74 \uAC15\uC0AC \uC5ED\uB7C9 \uD3C9\uAC00\uC640 \uD559\uBD80\uBAA8 \uC0C1\uB2F4 \uC790\uB8CC\uB85C \uD65C\uC6A9\uB418\uC5B4 \uD559\uC6D0 \uC2E0\uB8B0\uB3C4\uAC00 \uC62C\uB77C\uAC11\uB2C8\uB2E4.", review: "\uC544\uC774\uAC00 \uB2E4\uCCE4\uB2E4\uB294 \uBBFC\uC6D0\uC774 \uB4E4\uC5B4\uC654\uC744 \uB54C CCTV\uB85C \uC0C1\uD669\uC744 \uD655\uC778\uD558\uB2C8 \uC624\uD574\uC600\uC5B4\uC694. \uC601\uC0C1 \uC99D\uAC70\uAC00 \uD559\uC6D0\uACFC \uAC15\uC0AC\uB97C \uBCF4\uD638\uD569\uB2C8\uB2E4." }, { desc: "\uCD08\uB4F1 \uC800\uD559\uB144 \uB300\uC0C1 \uD559\uC6D0\xB7\uACF5\uBD80\uBC29\uC740 \uC544\uC774\uB4E4\uC774 \uD63C\uC790 \uB4F1\uD558\uC6D0\uD558\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uCD9C\uC785\uBB38\uACFC \uACC4\uB2E8 \uC601\uC5ED\uC758 \uC548\uC804 \uAC10\uC2DC\uAC00 \uD2B9\uD788 \uC911\uC694\uD569\uB2C8\uB2E4. \uB300\uD615 \uD559\uC6D0\uC740 \uD559\uB144\uBCC4 \uAD50\uC2E4\uC774 \uBD84\uC0B0\uB418\uC5B4 \uC788\uC5B4 \uD1B5\uD569 \uAD00\uC81C \uC2DC\uC2A4\uD15C\uC774 \uC720\uC6A9\uD569\uB2C8\uB2E4.", tip: "\uB4F1\uD558\uC6D0 \uC2DC\uAC04\uB300\uC5D0 \uD559\uBD80\uBAA8\uC5D0\uAC8C \uC544\uC774\uC758 \uC785\uCD9C\uC785 \uC601\uC0C1\uC744 \uC790\uB3D9\uC73C\uB85C \uC54C\uB9BC\uD1A1\uC73C\uB85C \uBC1C\uC1A1\uD558\uBA74 \uD559\uBD80\uBAA8 \uB9CC\uC871\uB3C4\uAC00 \uAE09\uC0C1\uC2B9\uD569\uB2C8\uB2E4. \uAC1C\uC778\uC815\uBCF4 \uB3D9\uC758\uB97C \uBC1B\uACE0 \uD574\uB2F9 \uC544\uC774\uB9CC \uC120\uBCC4\uD574\uC11C \uC804\uC1A1\uD558\uB294 \uC2DC\uC2A4\uD15C\uC774 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uD558\uAD50 \uD6C4 \uC544\uC774\uAC00 \uD559\uC6D0\uC5D0 \uB3C4\uCC29\uD558\uC790\uB9C8\uC790 \uC54C\uB9BC\uC774 \uC640\uC11C \uC548\uC2EC\uB410\uC5B4\uC694. \uC608\uC804\uC5D0\uB294 \uC804\uD654\uB85C \uD655\uC778\uD574\uC57C \uD588\uB294\uB370 \uC774\uC81C\uB294 \uC601\uC0C1 \uD55C \uC7A5\uC774\uBA74 \uCDA9\uBD84\uD569\uB2C8\uB2E4. \uB2E4\uB978 \uD559\uBD80\uBAA8\uB4E4\uB3C4 \uC774 \uAE30\uB2A5 \uB54C\uBB38\uC5D0 \uB4F1\uB85D\uD558\uC2DC\uB354\uAD70\uC694." }, { desc: "\uACE0\uB4F1\uBD80 \uC785\uC2DC\uD559\uC6D0\xB7\uB300\uD559 \uD3B8\uC785\uD559\uC6D0\uC740 \uD559\uC0DD\uB4E4\uC774 \uC7A5\uC2DC\uAC04 \uBA38\uBB34\uB294 \uB3C5\uC11C\uC2E4 \uACF5\uAC04\uC774 \uB9CE\uC2B5\uB2C8\uB2E4. \uC9D1\uC911 \uD559\uC2B5 \uD658\uACBD \uC720\uC9C0\uC640 \uB3C4\uB09C \uBC29\uC9C0\uAC00 \uACFC\uC81C\uC785\uB2C8\uB2E4. \uD559\uC0DD \uAC04 \uBB3C\uAC74 \uBD84\uC2E4 \uBD84\uC7C1\uC774 \uC758\uC678\uB85C \uC790\uC8FC \uBC1C\uC0DD\uD569\uB2C8\uB2E4.", tip: "\uB3C5\uC11C\uC2E4\uD615 \uD559\uC6D0\uC740 \uC88C\uC11D\uBCC4 \uCE74\uBA54\uB77C\uAC00 \uC544\uB2CC \uACF5\uC6A9 \uACF5\uAC04 \uC704\uC8FC\uB85C\uB9CC \uCD2C\uC601\uD574\uC57C \uAC1C\uC778\uC815\uBCF4 \uBB38\uC81C\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uAC00\uBC29 \uBCF4\uAD00\uC18C, \uD734\uAC8C \uACF5\uAC04, \uCD9C\uC785\uAD6C \uC911\uC2EC\uC73C\uB85C \uBC30\uCE58\uD558\uC138\uC694.", review: "\uB178\uD2B8\uBD81\uC744 \uB450\uACE0 \uAC04 \uD559\uC0DD\uC774 \uC5C6\uC5B4\uC84C\uB2E4\uACE0 \uD574\uC11C \uD655\uC778\uD558\uB2C8 \uCE5C\uAD6C\uAC00 \uC7A5\uB09C\uC73C\uB85C \uC62E\uAE34 \uAC70\uC600\uC5B4\uC694. \uC601\uC0C1\uC73C\uB85C \uBC14\uB85C \uD655\uC778\uB418\uB2C8 \uC4F8\uB370\uC5C6\uB294 \uC758\uC2EC\uC774 \uC0DD\uAE30\uC9C0 \uC54A\uACE0 \uBE60\uB974\uAC8C \uD574\uACB0\uB410\uC2B5\uB2C8\uB2E4." }, { desc: "\uD53C\uC544\uB178\xB7\uBBF8\uC220\xB7\uB304\uC2A4\uD559\uC6D0 \uB4F1 \uC608\uCCB4\uB2A5 \uD559\uC6D0\uC740 \uACE0\uAC00\uC758 \uC7A5\uBE44\uC640 \uC545\uAE30 \uAD00\uB9AC\uAC00 \uCD94\uAC00 \uACFC\uC81C\uC785\uB2C8\uB2E4. 1:1 \uAC1C\uC778 \uB808\uC2A8\uC2E4\uC758 \uACBD\uC6B0 \uD559\uC0DD\xB7\uAC15\uC0AC \uAC04 \uC624\uD574 \uBC29\uC9C0\uC640 \uBD84\uC7C1 \uB300\uC751\uC744 \uC704\uD55C \uC601\uC0C1 \uAE30\uB85D\uC774 \uC11C\uB85C\uB97C \uBCF4\uD638\uD569\uB2C8\uB2E4.", tip: "\uAC1C\uC778 \uB808\uC2A8\uC2E4\uC740 \uBCF5\uB3C4\uC640 \uC785\uCD9C\uC785\uB9CC \uCD2C\uC601\uD558\uACE0 \uB0B4\uBD80\uB294 \uC81C\uC678\uD558\uB418, \uBD84\uC7C1 \uC2DC \uD559\uC0DD\xB7\uAC15\uC0AC \uAC04 \uB300\uD654 \uB0B4\uC6A9 \uD655\uC778\uC744 \uC704\uD574 \uC74C\uC131 \uB179\uC74C \uB3D9\uC758\uB97C \uC0AC\uC804\uC5D0 \uBC1B\uC544\uB450\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4.", review: "\uD53C\uC544\uB178 \uB808\uC2A8 \uC911 \uAC15\uC0AC\uAC00 \uC18C\uB9AC\uB97C \uC9C8\uB800\uB2E4\uB294 \uD559\uBD80\uBAA8 \uBBFC\uC6D0\uC774 \uC788\uC5C8\uB294\uB370, \uBCF5\uB3C4 CCTV \uC18C\uB9AC\uB85C\uB294 \uC77C\uBC18\uC801\uC778 \uC218\uC5C5 \uD1A4\uC774\uC5C8\uC5B4\uC694. \uBBF8\uC138\uD55C \uCC28\uC774\uC9C0\uB9CC \uC774\uB7F0 \uC99D\uAC70\uAC00 \uAC15\uC0AC \uBCF4\uD638\uC5D0 \uACB0\uC815\uC801\uC785\uB2C8\uB2E4." }, { desc: "\uC694\uB9AC\uD559\uC6D0\xB7\uACF5\uC608\uD559\uC6D0\xB7\uC2E4\uC6A9\uD559\uC6D0\uC740 \uC2E4\uC2B5 \uACFC\uC815\uC5D0\uC11C\uC758 \uC548\uC804\uC0AC\uACE0 \uC704\uD5D8\uC774 \uC77C\uBC18 \uD559\uC6D0\uBCF4\uB2E4 \uB192\uC2B5\uB2C8\uB2E4. \uAC00\uC2A4\uB808\uC778\uC9C0\xB7\uC624\uBE10\xB7\uACF5\uAD6C \uAC19\uC740 \uC704\uD5D8 \uC7A5\uBE44\uB97C \uC0AC\uC6A9\uD558\uB294 \uC218\uC5C5\uC5D0\uC11C CCTV\uB294 \uC0AC\uACE0 \uC608\uBC29\uACFC \uCC45\uC784 \uC18C\uC7AC \uBA85\uD655\uD654\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uC2E4\uC2B5 \uC218\uC5C5 \uC804 \uACFC\uC815\uC744 \uB179\uD654\uD574 \uB450\uBA74 \uC218\uAC15\uC0DD\uC774 \uC548\uC804 \uC218\uCE59\uC744 \uC9C0\uD0A4\uC9C0 \uC54A\uACE0 \uC0AC\uACE0\uAC00 \uB0AC\uC744 \uB54C \uD559\uC6D0 \uACFC\uC2E4\uC774 \uC544\uB2D8\uC744 \uC99D\uBA85\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBCF4\uD5D8 \uCCAD\uAD6C \uC2DC\uC5D0\uB3C4 \uACB0\uC815\uC801 \uC99D\uAC70\uAC00 \uB429\uB2C8\uB2E4.", review: "\uC694\uB9AC \uC2E4\uC2B5 \uC911 \uD559\uC0DD\uC774 \uC190\uC744 \uBCA0\uC5C8\uB294\uB370 \uD559\uC6D0 \uCC45\uC784\uC774\uB77C\uBA70 \uBC30\uC0C1\uC744 \uC694\uAD6C\uD588\uC5B4\uC694. CCTV \uC601\uC0C1\uC5D0 \uD559\uC6D0 \uC548\uC804 \uAD50\uC721\uC744 \uBC1B\uACE0\uB3C4 \uBCF8\uC778\uC774 \uC9C0\uC2DC\uB97C \uC5B4\uAE34 \uC7A5\uBA74\uC774 \uC788\uC5B4 \uC624\uD574 \uC5C6\uC774 \uD574\uACB0\uB410\uC2B5\uB2C8\uB2E4." }],
    beauty: [{ desc: "\uACE0\uAC00 \uD654\uC7A5\uD488\xB7\uC2DC\uC220 \uB3C4\uAD6C \uBCF4\uAD00, 1:1 \uC2DC\uC220 \uACF5\uAC04\uC758 \uBD84\uC7C1 \uB300\uBE44, \uC608\uC57D \uC5C6\uB294 \uBC29\uBB38\uC790 \uAD00\uB9AC\uAC00 \uBDF0\uD2F0 \uC5C5\uC885 CCTV\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: '\uC2DC\uC220 \uC804\uD6C4 \uC601\uC0C1\uC774 \uB0A8\uC73C\uBA74 \uACE0\uAC1D \uBD88\uB9CC("\uC2DC\uC220 \uACB0\uACFC\uAC00 \uB2E4\uB974\uB2E4") \uBC1C\uC0DD \uC2DC \uAC1D\uAD00\uC801 \uBE44\uAD50 \uC790\uB8CC\uAC00 \uB429\uB2C8\uB2E4.', review: "\uC2DC\uC220 \uD6C4 \uD53C\uBD80 \uD2B8\uB7EC\uBE14\uC744 \uC8FC\uC7A5\uD558\uB294 \uACE0\uAC1D\uC5D0\uAC8C \uC2DC\uC220 \uACFC\uC815 \uC601\uC0C1\uC744 \uBCF4\uC5EC\uB4DC\uB838\uB354\uB2C8 \uBC14\uB85C \uC624\uD574\uAC00 \uD480\uB838\uC2B5\uB2C8\uB2E4. \uC601\uC0C1\uC740 \uC591\uCABD \uBAA8\uB450\uB97C \uBCF4\uD638\uD569\uB2C8\uB2E4." }, { desc: "\uBBF8\uC6A9\uC2E4\xB7\uD5E4\uC5B4\uC0B4\uB871\uC740 \uAE34 \uC2DC\uC220 \uC2DC\uAC04\uACFC \uC5EC\uB7EC \uC2DC\uC220\uC774 \uB3D9\uC2DC \uC9C4\uD589\uB418\uB294 \uD658\uACBD\uC774\uB77C CCTV \uAD00\uB9AC \uB300\uC0C1\uC774 \uB9CE\uC2B5\uB2C8\uB2E4. \uCE74\uC6B4\uD130 \uACB0\uC81C \uAC80\uC99D, \uC2DC\uC220 \uACFC\uC815 \uAE30\uB85D, \uB300\uAE30\uC2E4 \uACE0\uAC1D \uC751\uB300\uAE4C\uC9C0 \uAC10\uC2DC \uC601\uC5ED\uC774 \uB113\uC2B5\uB2C8\uB2E4.", tip: "\uC2DC\uC220 \uC758\uC790\uBCC4 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uBA74 \uC2DC\uC220\uC790\uBCC4 \uC11C\uBE44\uC2A4 \uD488\uC9C8\uC744 \uBAA8\uB2C8\uD130\uB9C1\uD560 \uC218 \uC788\uACE0, \uC2DC\uC220 \uC2DC\uAC04\uB3C4 \uC790\uB3D9 \uAE30\uB85D\uB418\uC5B4 \uC694\uAE08 \uC815\uC0B0\uC5D0 \uAC1D\uAD00\uC801 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", review: "\uD30C\uB9C8 \uC2DC\uAC04\uC774 \uB108\uBB34 \uC9E7\uC558\uB2E4\uB294 \uACE0\uAC1D \uD56D\uC758\uC5D0 \uC2DC\uC220 \uC601\uC0C1\uC744 \uD0C0\uC784\uC2A4\uD0EC\uD504\uC640 \uD568\uAED8 \uBCF4\uC5EC\uB4DC\uB838\uB354\uB2C8 \uBCF8\uC778\uC774 \uC2DC\uAC04\uC744 \uC798\uBABB \uAE30\uC5B5\uD55C \uAC70\uC600\uC5B4\uC694. \uAC1D\uAD00\uC801 \uC601\uC0C1 \uC55E\uC5D0\uC11C\uB294 \uBD84\uC7C1\uC774 \uBE60\uB974\uAC8C \uD574\uACB0\uB429\uB2C8\uB2E4." }, { desc: "\uD53C\uBD80\uAD00\uB9AC\uC2E4\xB7\uC5D0\uC2A4\uD14C\uD2F1\uC740 \uACE0\uAC00\uC758 \uC2DC\uC220 \uC7A5\uBE44\uC640 \uD654\uC7A5\uD488 \uBCF4\uAD00\uC774 \uD575\uC2EC \uC790\uC0B0\uC785\uB2C8\uB2E4. \uD2B9\uD788 \uD504\uB9AC\uBBF8\uC5C4 \uBE0C\uB79C\uB4DC \uC81C\uD488\uC740 \uC18C\uC9C4\uB7C9 \uAD00\uB9AC\uAC00 \uC911\uC694\uD574\uC11C \uB0B4\uBD80 \uC808\uB3C4 \uBC29\uC9C0 \uBAA9\uC801\uC758 CCTV\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uC7AC\uACE0 \uBCF4\uAD00\uC2E4\uACFC \uC2DC\uC220\uC2E4\uC744 \uBD84\uB9AC\uD574\uC11C \uC7AC\uACE0\uC2E4\uC740 \uCD9C\uC785 \uAE30\uB85D\uACFC \uC601\uC0C1\uC744 \uBAA8\uB450 \uB0A8\uAE30\uC138\uC694. \uD654\uC7A5\uD488 \uC18C\uC9C4\uB7C9\uC774 \uBE44\uC815\uC0C1\uC801\uC73C\uB85C \uBE60\uB978 \uACBD\uC6B0 \uC601\uC0C1\uC744 \uB3CC\uB824\uBCF4\uBA74 \uC6D0\uC778\uC744 \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uC6D4\uB9D0 \uC7AC\uACE0 \uC815\uB9AC\uD558\uB2E4\uAC00 \uACE0\uAC00 \uC570\uD50C\uC774 30% \uC815\uB3C4 \uBE44\uB294 \uAC83\uC744 \uBC1C\uACAC\uD588\uC5B4\uC694. CCTV\uB97C \uB3CC\uB824\uBCF4\uB2C8 \uC77C\uBD80 \uC9C1\uC6D0\uC774 \uC2DC\uC220 \uD6C4 \uB0A8\uC740 \uC591\uC744 \uBC84\uB9AC\uC9C0 \uC54A\uACE0 \uAC00\uC838\uAC00\uB294 \uD328\uD134\uC774\uC5C8\uC2B5\uB2C8\uB2E4. \uC870\uC6A9\uD788 \uC815\uB9AC\uD558\uACE0 \uC7AC\uACE0 \uC720\uCD9C\uC774 \uBA48\uCDC4\uC2B5\uB2C8\uB2E4." }, { desc: "\uB124\uC77C\uC0F5\xB7\uC18D\uB208\uC379\uC0F5\xB7\uC641\uC2F1\uC0F5 \uAC19\uC740 \uC18C\uADDC\uBAA8 \uBDF0\uD2F0 \uC804\uBB38 \uB9E4\uC7A5\uC740 \uC608\uC57D\uC81C \uC6B4\uC601\uC774 \uB9CE\uC544 \uBC29\uBB38\uC790 \uAD00\uB9AC\uAC00 \uD2B9\uD788 \uC911\uC694\uD569\uB2C8\uB2E4. \uBB34\uC608\uC57D \uBC29\uBB38, \uB178\uC1FC, \uC2DC\uAC04 \uCC29\uC624 \uBD84\uC7C1\uC774 \uC790\uC8FC \uBC1C\uC0DD\uD569\uB2C8\uB2E4.", tip: "\uCD9C\uC785\uBB38 \uC804\uC6A9 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uACE0 \uC608\uC57D \uC2DC\uC2A4\uD15C\uACFC \uC5F0\uB3D9\uD558\uBA74 \uC608\uC57D \uC2DC\uAC04\uACFC \uC2E4\uC81C \uBC29\uBB38 \uC2DC\uAC01\uC744 \uC790\uB3D9 \uB9E4\uCE6D\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB178\uC1FC \uAE30\uB85D\uB3C4 \uAC1D\uAD00\uC801\uC73C\uB85C \uB0A8\uC544 \uAD00\uB9AC\uAC00 \uC27D\uC2B5\uB2C8\uB2E4.", review: "\uC608\uC57D\uC744 5\uBD84 \uC77C\uCC0D \uC628 \uACE0\uAC1D\uC774 \uC790\uAE30\uAC00 \uB2A6\uC740 \uAC8C \uC544\uB2C8\uB77C \uC9C1\uC6D0\uC774 \uB2A6\uC5C8\uB2E4\uACE0 \uC8FC\uC7A5\uD588\uB294\uB370, \uCD9C\uC785 CCTV\uC5D0 \uBA85\uD655\uD788 \uAE30\uB85D\uB418\uC5B4 \uBC14\uB85C \uD574\uACB0\uB410\uC5B4\uC694. \uC18C\uADDC\uBAA8 \uB9E4\uC7A5\uC5D0\uC11C \uC774\uB7F0 \uBD84\uC7C1\uC774 \uC758\uC678\uB85C \uC790\uC8FC \uC788\uC2B5\uB2C8\uB2E4." }, { desc: "\uBC18\uC601\uAD6C\uC0F5\xB7\uBA54\uC774\uD06C\uC5C5\uC0F5\xB7\uB4DC\uB808\uC2A4\uC0F5\uC740 \uC911\uC694\uD55C \uD589\uC0AC(\uACB0\uD63C\xB7\uBA74\uC811\xB7\uCD2C\uC601)\uC640 \uC5F0\uAD00\uB41C \uC11C\uBE44\uC2A4\uAC00 \uB9CE\uC544 \uACE0\uAC1D \uAE30\uB300\uCE58\uAC00 \uB9E4\uC6B0 \uB192\uC2B5\uB2C8\uB2E4. \uACB0\uACFC\uBB3C \uBD84\uC7C1\uC774 \uBC1C\uC0DD\uD558\uBA74 \uAE08\uC804 \uC190\uC2E4\uBFD0 \uC544\uB2C8\uB77C \uD3C9\uD310\uC5D0\uB3C4 \uC601\uD5A5\uC744 \uC90D\uB2C8\uB2E4.", tip: "\uC2DC\uC220 \uC804 \uBAA8\uC2B5\uACFC \uC2DC\uC220 \uD6C4 \uBAA8\uC2B5\uC744 \uAC01\uAC01 \uACE0\uD654\uC9C8\uB85C \uAE30\uB85D\uD574 \uB450\uBA74 \uACB0\uACFC\uBB3C \uBD84\uC7C1 \uC2DC \uC2DC\uAC04\uBCC4 \uBCC0\uD654\uB97C \uAC1D\uAD00\uC801\uC73C\uB85C \uBE44\uAD50\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACE0\uAC1D \uB3D9\uC758 \uD558\uC5D0 \uC0AC\uC9C4\uACFC \uC601\uC0C1\uC744 \uD568\uAED8 \uBCF4\uAD00\uD558\uC138\uC694.", review: "\uBC18\uC601\uAD6C \uB208\uC379 \uC2DC\uC220 \uD6C4 \uACB0\uACFC\uAC00 \uAE30\uB300\uC640 \uB2E4\uB974\uB2E4\uACE0 \uD658\uBD88 \uC694\uCCAD\uC774 \uC654\uB294\uB370, \uC2DC\uC220 \uC804\uD6C4 \uC601\uC0C1\uC5D0 \uC2DC\uC220 \uACFC\uC815\uACFC \uACE0\uAC1D \uC0AC\uC804 \uD655\uC778 \uC7A5\uBA74\uC774 \uBAA8\uB450 \uC788\uC5B4\uC11C \uACC4\uC57D \uC870\uAC74\uB300\uB85C \uC9C4\uD589\uB41C \uAC8C \uD655\uC778\uB410\uC5B4\uC694. \uC601\uC0C1\uC774 \uCD5C\uACE0\uC758 \uBCC0\uD638\uC0AC\uC785\uB2C8\uB2E4." }],
    medical: [{ desc: "\uC758\uC57D\uD488 \uBCF4\uAD00\uC2E4, \uC9C4\uB8CC\uC2E4 \uCD9C\uC785, \uC57C\uAC04 \uBB34\uC778 \uC2DC\uAC04\uB300 \uBCF4\uC548\uC774 \uC758\uB8CC\uAE30\uAD00 CCTV\uC758 \uD575\uC2EC \uAC10\uC2DC \uD3EC\uC778\uD2B8\uC785\uB2C8\uB2E4.", tip: "\uB9C8\uC57D\uB958 \uAD00\uB9AC \uC758\uBB34\uAC00 \uC788\uB294 \uC758\uB8CC\uAE30\uAD00\uC740 CCTV\uAC00 \uBC95\uC801 \uBCF4\uAD00 \uC99D\uBE59 \uC218\uB2E8\uC774 \uB420 \uC218 \uC788\uC5B4 \uC124\uCE58\uAC00 \uC0AC\uC2E4\uC0C1 \uD544\uC218\uC785\uB2C8\uB2E4.", review: "\uC57C\uAC04\uC5D0 \uCE68\uC785 \uC2DC\uB3C4 \uC54C\uB9BC\uC774 \uC571\uC73C\uB85C \uC654\uACE0, \uBC14\uB85C \uACBD\uBE44\uC5C5\uCCB4\uC5D0 \uC5F0\uB77D\uD574 \uD53C\uD574\uB97C \uB9C9\uC558\uC2B5\uB2C8\uB2E4. \uC758\uC57D\uD488\uC774 \uC788\uC5B4 \uBCF4\uC548\uC774 \uD2B9\uD788 \uC911\uC694\uD55C \uACF3\uC785\uB2C8\uB2E4." }, { desc: "\uBCD1\uC6D0\xB7\uC758\uC6D0\uC740 \uD658\uC790 \uAC1C\uC778\uC815\uBCF4 \uBCF4\uD638\uAC00 \uBC95\uC801 \uC758\uBB34\uC0AC\uD56D\uC774\uB77C CCTV \uC124\uCE58 \uC2DC \uAC00\uC774\uB4DC\uB77C\uC778\uC744 \uC5C4\uACA9\uD788 \uC9C0\uCF1C\uC57C \uD569\uB2C8\uB2E4. \uC9C4\uB8CC\uC2E4 \uB0B4\uBD80\uB294 \uC6D0\uCE59\uC801\uC73C\uB85C \uCD2C\uC601 \uBD88\uAC00, \uBCF5\uB3C4\xB7\uB300\uAE30\uC2E4\xB7\uC811\uC218\uCC98\uB9CC \uAC00\uB2A5\uD55C \uAD6C\uC870\uAC00 \uD45C\uC900\uC785\uB2C8\uB2E4.", tip: "\uB300\uAE30\uC2E4\uC5D0 CCTV \uC124\uCE58 \uACE0\uC9C0\uBB38\uC744 \uB208\uC5D0 \uC798 \uBCF4\uC774\uAC8C \uBD80\uCC29\uD558\uACE0, \uB179\uD654 \uB370\uC774\uD130\uB294 \uC811\uADFC \uAD8C\uD55C\uC744 \uC6D0\uC7A5\xB7\uAD00\uB9AC\uC790\uB9CC \uBC1B\uB3C4\uB85D \uC124\uC815\uD574\uC57C \uD569\uB2C8\uB2E4. \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uC704\uC6D0\uD68C \uAC10\uC0AC \uC2DC \uC774 \uBD80\uBD84\uC774 \uD575\uC2EC \uC810\uAC80 \uD56D\uBAA9\uC785\uB2C8\uB2E4.", review: "\uD658\uC790 \uD55C \uBD84\uC774 \uB300\uAE30 \uC911 \uAC00\uBC29\uC744 \uB3C4\uB09C\uB2F9\uD588\uB2E4\uACE0 \uC8FC\uC7A5\uD588\uB294\uB370 CCTV\uB97C \uD655\uC778\uD558\uB2C8 \uB300\uAE30\uC2E4\uC5D0\uC11C \uBCF8\uC778\uC774 \uAE5C\uBE61\uD55C \uCC44 \uC774\uB3D9\uD55C \uAC83\uC774\uC5C8\uC5B4\uC694. \uBCD1\uC6D0 \uC9C1\uC6D0 \uC758\uC2EC\uC744 \uBA74\uD558\uACE0 \uC2E0\uB8B0\uB3C4\uB97C \uC9C0\uD0AC \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "\uCE58\uACFC\xB7\uD53C\uBD80\uACFC\xB7\uC131\uD615\uC678\uACFC \uAC19\uC740 \uACE0\uAC00 \uC2DC\uC220 \uBCD1\uC6D0\uC740 \uC2DC\uC220 \uC804\uD6C4 \uAE30\uB85D\uACFC \uC758\uC57D\uD488 \uAD00\uB9AC\uAC00 \uD2B9\uD788 \uC911\uC694\uD569\uB2C8\uB2E4. \uC2DC\uC220 \uC7A5\uBE44\uB3C4 \uACE0\uAC00\uB77C \uC808\uB3C4 \uB300\uC751 \uCCB4\uACC4\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uC2DC\uC220 \uC804\uD6C4 \uC0AC\uC9C4\xB7\uC601\uC0C1\uC744 \uD658\uC790 \uAC1C\uBCC4 \uD3F4\uB354\uB85C \uC790\uB3D9 \uC800\uC7A5\uD558\uB294 \uC2DC\uC2A4\uD15C\uACFC CCTV\uB97C \uC5F0\uB3D9\uD558\uBA74 \uC758\uB8CC \uC0AC\uACE0 \uC2DC \uB300\uC751\uC774 \uBE60\uB985\uB2C8\uB2E4. \uD658\uC790 \uB3D9\uC758 \uD558\uC5D0 \uAE30\uB85D\uB41C \uC790\uB8CC\uB294 \uBCD1\uC6D0 \uBCF4\uD638\uC5D0\uB3C4 \uACB0\uC815\uC801\uC785\uB2C8\uB2E4.", review: "\uC2DC\uC220 \uACB0\uACFC\uAC00 \uAE30\uB300\uC640 \uB2E4\uB974\uB2E4\uBA70 \uC18C\uC1A1\uC744 \uAC78\uACA0\uB2E4\uB294 \uD658\uC790\uAC00 \uC788\uC5C8\uB294\uB370, \uC2DC\uC220 \uC804 \uC0C1\uB2F4 \uC601\uC0C1\uACFC \uC2DC\uC220 \uACFC\uC815 \uC601\uC0C1\uC744 \uC81C\uCD9C\uD558\uB2C8 \uC815\uC0C1 \uBC94\uC704 \uB0B4 \uACB0\uACFC\uC784\uC774 \uD655\uC778\uB418\uC5B4 \uC18C\uC1A1\uC774 \uCDE8\uD558\uB410\uC2B5\uB2C8\uB2E4. \uC601\uC0C1 \uAE30\uB85D\uC758 \uD798\uC785\uB2C8\uB2E4." }, { desc: "\uD55C\uC758\uC6D0\xB7\uC7AC\uD65C\uBCD1\uC6D0\uC740 \uC7A5\uC2DC\uAC04 \uCE58\uB8CC\uAC00 \uB9CE\uC544 \uD658\uC790 \uB300\uAE30 \uC2DC\uAC04\uACFC \uCE58\uB8CC \uACF5\uAC04 \uAD00\uB9AC\uAC00 \uD2B9\uC218\uD569\uB2C8\uB2E4. \uCE68\xB7\uB738 \uAC19\uC740 \uC2DC\uC220\uC758 \uC548\uC804 \uAD00\uB9AC\uC640 \uCE68\uAD6C\uB958 \uC704\uC0DD \uAD00\uB9AC \uAC10\uC2DC\uAC00 \uCD94\uAC00 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "\uCE58\uB8CC \uCE68\uB300 \uC8FC\uBCC0\uC740 \uD658\uC790 \uD504\uB77C\uC774\uBC84\uC2DC\uB97C \uBCF4\uD638\uD574\uC57C \uD558\uBBC0\uB85C \uC9C1\uC811 \uCD2C\uC601\uC740 \uD53C\uD558\uACE0 \uBCF5\uB3C4\xB7\uB300\uAE30\uC2E4 \uC704\uC8FC\uB85C \uC124\uCE58\uD558\uC138\uC694. \uB300\uC2E0 \uC7AC\uB8CC\uC2E4\uACFC \uCE68\uAD6C \uBCF4\uAD00\uC2E4\uC740 \uC704\uC0DD \uAD00\uB9AC\uC6A9 \uCE74\uBA54\uB77C\uAC00 \uC720\uC6A9\uD569\uB2C8\uB2E4.", review: "\uCE68\uAD6C \uAD50\uCCB4\uB97C \uC81C\uB300\uB85C \uC548 \uD55C\uB2E4\uB294 \uD658\uC790 \uBBFC\uC6D0\uC774 \uC788\uC5C8\uB294\uB370, \uCE68\uAD6C \uBCF4\uAD00\uC2E4 \uCE74\uBA54\uB77C\uB85C \uD655\uC778\uD558\uB2C8 \uC9C1\uC6D0\uC774 \uB9E4\uBC88 \uAD50\uCCB4\uD558\uB294 \uC601\uC0C1\uC774 \uC788\uC5B4\uC11C \uC624\uD574\uAC00 \uD480\uB838\uC5B4\uC694. \uC2DC\uAC04\uBCC4 \uAD00\uB9AC \uAE30\uB85D\uC774 \uC2E0\uB8B0\uB3C4\uB97C \uB9CC\uB4ED\uB2C8\uB2E4." }, { desc: "\uB3D9\uBB3C\uBCD1\uC6D0\uC740 \uBC18\uB824\uB3D9\uBB3C \uAD00\uB9AC\uC758 \uD2B9\uC218\uC131 \uB54C\uBB38\uC5D0 \uC77C\uBC18 \uBCD1\uC6D0\uACFC \uB2E4\uB978 CCTV \uC694\uAD6C\uC0AC\uD56D\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC218\uC220\uC2E4\xB7\uC785\uC6D0\uC2E4\xB7\uBCF4\uD638\uC790 \uB300\uAE30\uC2E4\uC758 \uAC01\uAC01 \uB2E4\uB978 \uBCF4\uC548 \uACFC\uC81C\uAC00 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uC785\uC6D0 \uB3D9\uBB3C \uCF00\uC774\uC9C0 \uAD6C\uC5ED\uC5D0 24\uC2DC\uAC04 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uBA74 \uBCF4\uD638\uC790\uAC00 \uC6D0\uACA9\uC73C\uB85C \uBC18\uB824\uB3D9\uBB3C \uC0C1\uD0DC\uB97C \uD655\uC778\uD560 \uC218 \uC788\uC5B4 \uC11C\uBE44\uC2A4 \uCC28\uBCC4\uD654\uAC00 \uB429\uB2C8\uB2E4. \uC77C\uBD80 \uBCD1\uC6D0\uC740 \uC720\uB8CC \uC635\uC158\uC73C\uB85C \uC81C\uACF5\uD558\uAE30\uB3C4 \uD569\uB2C8\uB2E4.", review: "\uBC18\uB824\uACAC \uC785\uC6D0 \uC911 \uC798 \uBA39\uB294\uC9C0 \uAC71\uC815\uD558\uC2DC\uB294 \uBCF4\uD638\uC790\uC5D0\uAC8C \uC2E4\uC2DC\uAC04 \uC601\uC0C1\uC744 \uBCF4\uB0B4\uB4DC\uB9AC\uB2C8 \uC548\uC2EC\uD558\uC168\uC5B4\uC694. \uB2E8\uC21C\uD55C \uBCF4\uC548\uC744 \uB118\uC5B4 \uC11C\uBE44\uC2A4 \uD488\uC9C8\uC744 \uB192\uC774\uB294 \uB3C4\uAD6C\uAC00 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4." }],
    retail: [{ desc: "\uC9C4\uC5F4 \uC0C1\uD488 \uB3C4\uB09C, \uACC4\uC0B0\uB300 \uC815\uC0B0 \uAC80\uC99D, \uC785\uAD6C \uCD9C\uC785 \uAD00\uB9AC\uAC00 \uC18C\uB9E4\uC810 CCTV\uC758 \uAE30\uBCF8 \uAC10\uC2DC \uC601\uC5ED\uC785\uB2C8\uB2E4.", tip: "\uACE0\uAC1D \uB3D9\uC120 \uBD84\uC11D\uC73C\uB85C \uC778\uAE30 \uAD6C\uC5ED\uACFC \uC0AC\uAC01\uC9C0\uB300\uB97C \uD30C\uC545\uD558\uBA74 \uC0C1\uD488 \uBC30\uCE58\uB97C \uCD5C\uC801\uD654\uD558\uC5EC \uB9E4\uCD9C\uC744 \uB192\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uB9CC\uC778\uC758 \uB3C4\uB09C\uC774 \uC7A6\uC558\uB294\uB370 CCTV \uC124\uCE58 \uD6C4 \uD655\uC5F0\uD788 \uC904\uC5C8\uC5B4\uC694. \uCE74\uBA54\uB77C\uAC00 \uBCF4\uC778\uB2E4\uB294 \uAC83 \uC790\uCCB4\uAC00 \uC5B5\uC81C\uB825\uC785\uB2C8\uB2E4." }, { desc: "\uD3B8\uC758\uC810\xB7\uB9C8\uD2B8 \uAC19\uC740 \uC18C\uADDC\uBAA8 \uC18C\uB9E4\uC810\uC740 24\uC2DC\uAC04 \uC6B4\uC601\uACFC 1\uC778 \uADFC\uBB34 \uC2DC\uAC04\uB300\uAC00 \uB9CE\uC544 \uAC15\uB825\uD55C \uBCF4\uC548 \uC2DC\uC2A4\uD15C\uC774 \uD544\uC218\uC785\uB2C8\uB2E4. \uD2B9\uD788 \uC2EC\uC57C \uC2DC\uAC04\uB300 \uAC15\uB3C4 \uC704\uD5D8\uC5D0 \uB300\uBE44\uD55C \uACBD\uBCF4 \uC5F0\uB3D9 \uCE74\uBA54\uB77C\uAC00 \uD45C\uC900\uC774 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uD604\uAE08 \uCD9C\uB0A9\uAE30 \uC8FC\uBCC0\uACFC \uCD9C\uC785\uAD6C\uB294 \uACE0\uD654\uC9C8 4K \uCE74\uBA54\uB77C\uB85C, \uB9E4\uB300 \uAD6C\uC5ED\uC740 Full HD\uB85C \uBE44\uC6A9 \uD6A8\uC728\uC801 \uAD6C\uC131\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uAC15\uB3C4 \uB300\uC751\uC6A9 \uACBD\uCC30 \uC9C1\uD1B5 \uACBD\uBCF4 \uBC84\uD2BC\uB3C4 \uC5F0\uB3D9\uD558\uBA74 \uC548\uC804\uC131\uC774 \uD06C\uAC8C \uC62C\uB77C\uAC11\uB2C8\uB2E4.", review: "\uC2EC\uC57C \uADFC\uBB34 \uC911 \uC218\uC0C1\uD55C \uC0AC\uB78C\uC774 \uB4E4\uC5B4\uC654\uB294\uB370 CCTV \uB179\uD654 \uD45C\uC2DC\uB97C \uBCF4\uACE0 \uADF8\uB0E5 \uB098\uAC14\uC5B4\uC694. \uB2E8\uC21C\uD55C \uB179\uD654 \uD45C\uC2DC\uB9CC\uC73C\uB85C\uB3C4 \uBC94\uC8C4 \uC5B5\uC81C \uD6A8\uACFC\uAC00 \uD07D\uB2C8\uB2E4. \uC124\uCE58 \uC790\uCCB4\uAC00 \uBCF4\uC548\uC785\uB2C8\uB2E4." }, { desc: "\uC758\uB958\uB9E4\uC7A5\xB7\uC2E0\uBC1C\uB9E4\uC7A5\xB7\uD654\uC7A5\uD488\uB9E4\uC7A5 \uAC19\uC740 \uD328\uC158 \uC18C\uB9E4\uC810\uC740 \uC9C4\uC5F4 \uC0C1\uD488\uC758 \uB3C4\uB09C \uC704\uD5D8\uC774 \uD2B9\uD788 \uB192\uC2B5\uB2C8\uB2E4. \uD0DD \uC5C6\uB294 \uC81C\uD488 \uBC18\uCD9C, \uD0C8\uC758\uC2E4 \uB0B4 \uC808\uB3C4, \uC2DC\uCC29 \uC911 \uC2AC\uCA4D \uAC00\uC838\uAC00\uB294 \uC720\uD615\uAE4C\uC9C0 \uB2E4\uC591\uD55C \uC218\uBC95\uC774 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uD0C8\uC758\uC2E4 \uC8FC\uBCC0\uC5D0\uB294 \uCD9C\uC785\uAD6C\uB9CC \uCD2C\uC601\uD558\uB294 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uACE0, \uB9E4\uC7A5 \uC804\uCCB4\uB294 \uCC9C\uC7A5 \uB3D4\uD615 \uCE74\uBA54\uB77C\uB85C \uC0AC\uAC01\uC9C0\uB300 \uC5C6\uC774 \uCEE4\uBC84\uD558\uC138\uC694. RFID \uD0DC\uADF8\uC640 \uC5F0\uB3D9\uD558\uBA74 \uBBF8\uACB0\uC81C \uBC18\uCD9C \uC2DC \uC790\uB3D9 \uC54C\uB9BC\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", review: "\uD0C8\uC758\uC2E4\uC5D0\uC11C \uC637\uC744 \uC5EC\uB7EC \uBC8C \uB4E4\uACE0 \uB4E4\uC5B4\uAC00 \uD55C \uBC8C\uB9CC \uC785\uACE0 \uB098\uC624\uB294 \uACE0\uAC1D\uC774 \uC788\uC5C8\uB294\uB370, \uC785\uAD6C \uCE74\uBA54\uB77C\uC640 \uD0C8\uC758\uC2E4 \uCD9C\uC785 \uCE74\uBA54\uB77C\uB85C \uBE44\uAD50\uD558\uB2C8 \uBA85\uD655\uD588\uC5B4\uC694. \uC870\uC6A9\uD788 \uB2E4\uAC00\uAC00\uC11C \uD655\uC778\uD558\uB2C8 \uB3C4\uB09C \uC2DC\uB3C4\uAC00 \uB9DE\uC558\uC2B5\uB2C8\uB2E4." }, { desc: "\uC804\uC790\uC81C\uD488\xB7\uAC00\uAD6C\xB7\uACE0\uAC00\uD488 \uCDE8\uAE09 \uB9E4\uC7A5\uC740 \uB2E8\uAC00\uAC00 \uB192\uC740 \uB9CC\uD07C \uB3C4\uB09C 1\uAC74\uC758 \uC190\uC2E4\uC774 \uD07D\uB2C8\uB2E4. \uB9E4\uC7A5 \uB0B4\uBD80\uBFD0 \uC544\uB2C8\uB77C \uCC3D\uACE0\xB7\uC7AC\uACE0\uC2E4\xB7\uB9E4\uC7A5 \uB4B7\uBB38\uC758 \uBCF4\uC548\uAE4C\uC9C0 \uC885\uD569\uC801 \uC124\uACC4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", tip: "\uACE0\uAC00\uD488 \uC9C4\uC5F4\uB300\uC5D0\uB294 \uBCC4\uB3C4 \uACE0\uD654\uC9C8 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uACE0, \uC6C0\uC9C1\uC784 \uAC10\uC9C0\uAC00 \uD2B8\uB9AC\uAC70\uB418\uBA74 \uC989\uC2DC \uAD00\uB9AC\uC790\uC5D0\uAC8C \uC54C\uB9BC\uC774 \uAC00\uB3C4\uB85D \uC124\uC815\uD558\uC138\uC694. \uC57C\uAC04 \uBB34\uC778 \uC2DC\uAC04\uB300\uB294 \uD2B9\uD788 \uC5C4\uACA9\uD55C \uAC10\uC2DC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", review: "\uC601\uC5C5 \uC885\uB8CC \uD6C4 \uCC3D\uACE0\uC5D0\uC11C \uACE0\uAC00 \uCE74\uBA54\uB77C\uAC00 1\uB300 \uC0AC\uB77C\uC9C4 \uAC83\uC744 \uBC1C\uACAC\uD588\uC5B4\uC694. CCTV\uB97C \uB3CC\uB824\uBCF4\uB2C8 \uB9C8\uAC10 \uC9C1\uC6D0\uC774 \uD1F4\uADFC\uAE38\uC5D0 \uAC00\uC838\uAC04 \uC7A5\uBA74\uC774 \uC788\uC5B4\uC11C \uACBD\uCC30 \uC2E0\uACE0 \uD6C4 \uD68C\uC218\uD588\uC2B5\uB2C8\uB2E4. \uB0B4\uBD80 \uB3C4\uB09C\uC774 \uC758\uC678\uB85C \uB9CE\uC2B5\uB2C8\uB2E4." }, { desc: "\uD3B8\uC758\uC810\uD615 \uBB34\uC778\uB9E4\uC7A5\xB7\uC140\uD504\uACC4\uC0B0 \uB9E4\uC7A5\uC740 \uC9C1\uC6D0 \uC5C6\uC774 \uC6B4\uC601\uB418\uBBC0\uB85C CCTV\uAC00 \uC720\uC77C\uD55C \uBCF4\uC548 \uC218\uB2E8\uC785\uB2C8\uB2E4. \uB3C4\uB09C \uBC29\uC9C0\uBFD0 \uC544\uB2C8\uB77C \uBBF8\uACB0\uC81C \uC774\uD0C8, \uC0C1\uD488 \uD30C\uC190, \uC548\uC804\uC0AC\uACE0 \uB300\uC751\uAE4C\uC9C0 \uBAA8\uB4E0 \uC601\uC5ED\uC744 CCTV\uB85C \uAD00\uB9AC\uD569\uB2C8\uB2E4.", tip: "AI \uAE30\uBC18 \uC774\uC0C1\uD589\uB3D9 \uAC10\uC9C0 \uCE74\uBA54\uB77C\uB294 \uBB34\uC778\uB9E4\uC7A5 \uC6B4\uC601\uC758 \uD544\uC218 \uC7A5\uBE44\uC785\uB2C8\uB2E4. \uD2B9\uC815 \uB9E4\uB300 \uC55E\uC5D0\uC11C \uBE44\uC815\uC0C1\uC801\uC73C\uB85C \uC624\uB798 \uBA38\uBB3C\uAC70\uB098, \uBBF8\uACB0\uC81C \uCD9C\uC785\uC774 \uAC10\uC9C0\uB418\uBA74 \uC989\uC2DC \uAD00\uB9AC\uC790\uC5D0\uAC8C \uC54C\uB9BC\uC774 \uAC00\uB3C4\uB85D \uC124\uC815\uD558\uC138\uC694.", review: "\uBB34\uC778\uB9E4\uC7A5\uC744 \uC6B4\uC601\uD558\uB294\uB370 \uCD08\uAE30\uC5D0 \uB3C4\uB09C\uC774 \uC6D4 10\uAC74 \uB118\uAC8C \uBC1C\uC0DD\uD588\uC5B4\uC694. AI \uCE74\uBA54\uB77C \uB3C4\uC785 \uD6C4 \uAC10\uC9C0 \uC989\uC2DC \uC74C\uC131 \uACBD\uACE0\uAC00 \uB098\uAC00\uB3C4\uB85D \uC124\uC815\uD588\uB354\uB2C8 3\uAC1C\uC6D4 \uB9CC\uC5D0 \uB3C4\uB09C\uC774 \uC6D4 1\uAC74 \uC774\uD558\uB85C \uC904\uC5C8\uC2B5\uB2C8\uB2E4." }],
    service: [{ desc: "\uACE0\uAC1D \uBB3C\uD488 \uBCF4\uAD00, \uC791\uC5C5 \uACFC\uC815 \uAE30\uB85D, \uC785\uCD9C\uC785 \uAD00\uB9AC\uAC00 \uC11C\uBE44\uC2A4 \uC5C5\uC885 CCTV\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: '\uC791\uC5C5 \uC804\uD6C4\uB97C \uC601\uC0C1\uC73C\uB85C \uAE30\uB85D\uD558\uBA74 \uACE0\uAC1D \uD074\uB808\uC784("\uC6D0\uB798 \uC774\uB7F0 \uC0C1\uD0DC \uC544\uB2C8\uC5C8\uB2E4")\uC5D0 \uAC1D\uAD00\uC801\uC73C\uB85C \uB300\uC751\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.', review: "\uACE0\uAC1D\uC774 \uB9E1\uAE34 \uBB3C\uAC74\uC5D0 \uD760\uC9D1\uC774 \uC788\uC5C8\uB2E4\uACE0 \uD56D\uC758\uD588\uB294\uB370, \uC811\uC218 \uC2DC\uC810 \uC601\uC0C1\uC744 \uBCF4\uC5EC\uB4DC\uB9AC\uB2C8 \uC774\uBBF8 \uC788\uC5C8\uB358 \uD760\uC9D1\uC774\uC5C8\uC2B5\uB2C8\uB2E4. \uBD84\uC7C1 \uD574\uACB0\uC5D0 5\uBD84 \uAC78\uB838\uC5B4\uC694." }, { desc: "\uC138\uD0C1\uC18C\xB7\uBE68\uB798\uBC29\xB7\uC218\uC120\uC9D1\uC740 \uACE0\uAC1D \uC758\uB958 \uBCF4\uAD00\uACFC \uC791\uC5C5 \uACFC\uC815 \uAE30\uB85D\uC774 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uC624\uC5FC\xB7\uD6FC\uC190 \uCC45\uC784 \uC18C\uC7AC \uBD84\uC7C1\uC774 \uC790\uC8FC \uBC1C\uC0DD\uD558\uBBC0\uB85C \uC811\uC218 \uC2DC\uC810\uACFC \uCD9C\uACE0 \uC2DC\uC810 \uC601\uC0C1\uC774 \uBD84\uC7C1 \uD574\uACB0\uC758 \uACB0\uC815\uC801 \uC99D\uAC70\uAC00 \uB429\uB2C8\uB2E4.", tip: "\uC811\uC218\uB300\uC5D0 \uACE0\uD654\uC9C8 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uACE0 \uC758\uB958 \uC811\uC218 \uC7A5\uBA74\uC744 \uACE0\uAC1D\uC774 \uBCFC \uC218 \uC788\uB294 \uAC01\uB3C4\uB85C \uC124\uCE58\uD558\uBA74 \uACE0\uAC1D\uB3C4 \uC548\uC2EC\uD569\uB2C8\uB2E4. \uC791\uC5C5 \uACF5\uAC04\uC740 \uC138\uD0C1\uBB3C \uD63C\uB3D9 \uBC29\uC9C0\uB97C \uC704\uD55C \uAD00\uB9AC\uC6A9\uC73C\uB85C \uC720\uC6A9\uD569\uB2C8\uB2E4.", review: "\uACE0\uAC00 \uCF54\uD2B8\uAC00 \uC624\uC5FC\uB41C \uC0C1\uD0DC\uB85C \uC654\uB2E4\uACE0 \uC8FC\uC7A5\uD55C \uACE0\uAC1D\uC774 \uC788\uC5C8\uB294\uB370, \uC811\uC218 \uC601\uC0C1\uC5D0 \uC774\uBBF8 \uC5BC\uB8E9\uC774 \uC788\uB294 \uC0C1\uD0DC\uB85C \uBC1B\uC740 \uAC8C \uD655\uC778\uB410\uC5B4\uC694. 10\uB9CC\uC6D0 \uBC30\uC0C1 \uBD84\uC7C1\uC744 5\uBD84 \uB9CC\uC5D0 \uD574\uACB0\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uC778\uC1C4\uC18C\xB7\uD0DD\uBC30\uB300\uB9AC\uC810\xB7\uBCF5\uC0AC\uC9D1\uC740 \uACE0\uAC1D \uC790\uB8CC\uC758 \uAC1C\uC778\uC815\uBCF4 \uBCF4\uD638 \uCC45\uC784\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uC790\uB8CC \uCDE8\uAE09 \uACFC\uC815, \uCD9C\uB825\uBB3C \uBCF4\uAD00, \uBC29\uBB38\uC790 \uAE30\uB85D\uC774 CCTV \uAC10\uC2DC\uC758 \uC8FC\uC694 \uB300\uC0C1\uC785\uB2C8\uB2E4.", tip: "\uAC1C\uC778\uC815\uBCF4\uAC00 \uD3EC\uD568\uB41C \uC778\uC1C4\uBB3C\uC740 \uCE74\uBA54\uB77C \uB179\uD654 \uC601\uC5ED\uC5D0\uC11C \uB0B4\uC6A9\uC774 \uC2DD\uBCC4\uB418\uC9C0 \uC54A\uB3C4\uB85D \uAC01\uB3C4 \uC870\uC808\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uC5C5\uBB34 \uACF5\uAC04\uC740 \uCD2C\uC601\uD558\uB418 \uBB38\uC11C \uB0B4\uC6A9\uC740 \uBCF4\uC774\uC9C0 \uC54A\uAC8C \uD558\uB294 \uC124\uACC4\uAC00 \uD569\uBC95 \uAE30\uC900\uC785\uB2C8\uB2E4.", review: "\uC911\uC694 \uC11C\uB958 \uC778\uC1C4\uB97C \uB9E1\uACBC\uB294\uB370 \uC720\uCD9C\uB410\uB2E4\uB294 \uACE0\uAC1D \uC758\uC2EC\uC774 \uC788\uC5C8\uC5B4\uC694. \uC791\uC5C5 \uACF5\uAC04 CCTV\uB85C \uD0C0\uC778\uC774 \uC811\uADFC\uD55C \uC801 \uC5C6\uC74C\uC744 \uBCF4\uC5EC\uB4DC\uB9AC\uB2C8 \uC2E0\uB8B0\uB97C \uD68C\uBCF5\uD588\uC2B5\uB2C8\uB2E4. \uC624\uD574\uB97C \uD480 \uC218 \uC788\uB294 \uAC1D\uAD00\uC801 \uB3C4\uAD6C\uC785\uB2C8\uB2E4." }, { desc: "\uC774\uBCA4\uD2B8\uC5C5\uCCB4\xB7\uD589\uC0AC\uB300\uD589\uC5C5\xB7\uD035\uC11C\uBE44\uC2A4 \uAC19\uC740 \uC11C\uBE44\uC2A4\uC5C5\uC740 \uCC28\uB7C9\uACFC \uC791\uC5C5 \uD604\uC7A5 \uAD00\uB9AC\uAC00 \uD2B9\uC218\uD569\uB2C8\uB2E4. \uC0AC\uBB34\uC2E4\uACFC \uCC3D\uACE0\xB7\uCC28\uB7C9 \uC8FC\uCC28 \uAD6C\uC5ED \uAC01\uAC01\uC758 \uBCF4\uC548\uC774 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: "\uCC28\uB7C9 \uC8FC\uCC28 \uAD6C\uC5ED\uC5D0 LPR(\uBC88\uD638\uD310 \uC778\uC2DD) \uCE74\uBA54\uB77C\uB97C \uC124\uCE58\uD558\uBA74 \uCD9C\uC785 \uCC28\uB7C9\uC774 \uC790\uB3D9 \uAE30\uB85D\uB418\uC5B4 \uBC30\uC1A1 \uBD84\uC7C1\uC774\uB098 \uC5C5\uBB34 \uC2DC\uAC04 \uCD94\uC801\uC5D0 \uD65C\uC6A9\uB429\uB2C8\uB2E4. \uC678\uADFC \uCC28\uB7C9\uC758 \uC0AC\uC6A9 \uC2DC\uAC01\uB3C4 \uAC1D\uAD00\uC801\uC73C\uB85C \uAD00\uB9AC \uAC00\uB2A5\uD569\uB2C8\uB2E4.", review: "\uC9C1\uC6D0\uC774 \uD1F4\uADFC \uD6C4 \uC5C5\uBB34 \uCC28\uB7C9\uC744 \uAC1C\uC778 \uC6A9\uB3C4\uB85C \uC4F4\uB2E4\uB294 \uC758\uC2EC\uC774 \uC788\uC5C8\uB294\uB370, LPR \uCE74\uBA54\uB77C \uAE30\uB85D\uC73C\uB85C \uC8FC\uB9D0\uC5D0\uB3C4 \uCC28\uACE0\uC9C0\uB97C \uB4E4\uB77D\uAC70\uB9B0 \uAC8C \uD655\uC778\uB410\uC5B4\uC694. \uBA85\uD655\uD55C \uADFC\uAC70\uB85C \uC815\uC911\uD788 \uC9C0\uC801\uD558\uACE0 \uD574\uACB0\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uC7A5\uB840\uC2DD\uC7A5\xB7\uC6E8\uB529\uD640\xB7\uACF5\uC5F0\uC7A5 \uAC19\uC740 \uD589\uC0AC \uC11C\uBE44\uC2A4\uC5C5\uC740 \uB2E4\uC218 \uBC29\uBB38\uAC1D\uACFC \uACE0\uAC00 \uC124\uBE44 \uAD00\uB9AC\uAC00 \uB3D9\uC2DC\uC5D0 \uC774\uB8E8\uC5B4\uC9C0\uB294 \uD2B9\uC218 \uD658\uACBD\uC785\uB2C8\uB2E4. \uBC29\uBB38\uAC1D \uC548\uC804\uACFC \uC2DC\uC124\uBB3C \uBCF4\uC548, \uC5C5\uBB34 \uD488\uC9C8 \uAD00\uB9AC\uAC00 \uBAA8\uB450 \uD544\uC694\uD569\uB2C8\uB2E4.", tip: "\uC8FC\uC694 \uCD9C\uC785\uAD6C\xB7\uC8FC\uCC28\uC7A5\xB7\uB85C\uBE44\uC5D0 \uACE0\uD654\uC9C8 \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD558\uB418, \uC601\uAD6C \uBCF4\uC874 \uC2E4\uB0B4 \uD589\uC0AC \uACF5\uAC04\uC740 \uACE0\uAC1D \uD504\uB77C\uC774\uBC84\uC2DC\uB97C \uACE0\uB824\uD574 \uC81C\uD55C\uC801\uC73C\uB85C \uC124\uCE58\uD558\uC138\uC694. \uB300\uAE30\uC2E4\uACFC \uCE74\uC6B4\uD130 \uC911\uC2EC\uC774 \uC548\uC804\uD55C \uC124\uACC4\uC785\uB2C8\uB2E4.", review: "\uC608\uC2DD \uC911 \uCD95\uC758\uAE08 \uAC00\uBC29\uC774 \uC5C6\uC5B4\uC84C\uB2E4\uB294 \uBBFC\uC6D0\uC774 \uC788\uC5C8\uB294\uB370, \uB85C\uBE44 \uCE74\uBA54\uB77C\uB85C \uBCF4\uB2C8 \uC2E0\uBD80 \uCE21 \uAC00\uC871\uC774 \uC774\uBBF8 \uC218\uAC70\uD574 \uAC04 \uAC83\uC774\uC5C8\uC5B4\uC694. \uC2DC\uAC04\uC744 \uAC70\uC2AC\uB7EC \uC62C\uB77C\uAC00 \uD655\uC778\uD560 \uC218 \uC788\uC5B4\uC11C \uBE60\uB978 \uD574\uACB0\uC774 \uAC00\uB2A5\uD588\uC2B5\uB2C8\uB2E4." }],
    auto: [{ desc: "\uCC28\uB7C9 \uC785\uCD9C\uACE0, \uC815\uBE44 \uC791\uC5C5 \uACFC\uC815, \uBD80\uD488 \uBCF4\uAD00\uC18C \uBCF4\uC548\uC774 \uC790\uB3D9\uCC28 \uC5C5\uC885 CCTV\uC758 3\uB300 \uAC10\uC2DC \uD3EC\uC778\uD2B8\uC785\uB2C8\uB2E4.", tip: '\uC815\uBE44 \uACFC\uC815\uC774 \uC601\uC0C1\uC73C\uB85C \uB0A8\uC73C\uBA74 "\uC548 \uD558\uB358 \uC791\uC5C5\uC744 \uD574\uC11C \uACE0\uC7A5\uB0AC\uB2E4"\uB294 \uD074\uB808\uC784\uC5D0 \uAC1D\uAD00\uC801 \uC99D\uAC70\uAC00 \uB429\uB2C8\uB2E4.', review: "\uCD9C\uACE0 \uD6C4 \uC0DD\uAE34 \uD760\uC9D1\uC744 \uC6B0\uB9AC \uD0D3\uC774\uB77C\uACE0 \uD558\uC168\uB294\uB370, \uCD9C\uACE0 \uC2DC\uC810 \uC601\uC0C1\uC5D0 \uAE68\uB057\uD55C \uC0C1\uD0DC\uAC00 \uCC0D\uD600\uC788\uC5B4\uC11C \uBC14\uB85C \uD574\uACB0\uB410\uC2B5\uB2C8\uB2E4." }, { desc: "\uC815\uBE44\uC18C\xB7\uCE74\uC13C\uD130\uB294 \uCC28\uB7C9 \uC785\uCD9C\uACE0 \uC2DC\uC810 \uC0C1\uD0DC \uAE30\uB85D\uC774 \uBD84\uC7C1 \uBC29\uC9C0\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uC785\uACE0 \uC2DC \uC0C1\uCC98 \uC0C1\uD0DC, \uC791\uC5C5 \uACFC\uC815, \uCD9C\uACE0 \uC2DC \uCD5C\uC885 \uC0C1\uD0DC\uAE4C\uC9C0 3\uB2E8\uACC4\uB85C \uC601\uC0C1\uC744 \uB0A8\uAE30\uBA74 \uBD84\uC7C1\uC774 \uAC70\uC758 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4.", tip: "\uCC28\uB7C9 \uC8FC\uBCC0 360\uB3C4 \uCD2C\uC601\uC774 \uAC00\uB2A5\uD55C \uB3D4\uD615 \uCE74\uBA54\uB77C\uB97C \uC791\uC5C5 \uBCA0\uC774\uB9C8\uB2E4 \uBC30\uCE58\uD558\uBA74 \uC791\uC5C5 \uD488\uC9C8 \uAD00\uB9AC\uB3C4 \uB429\uB2C8\uB2E4. \uC791\uC5C5\uC790\uBCC4 \uC2DC\uAC04 \uAE30\uB85D\uACFC \uC5F0\uB3D9\uD558\uBA74 \uACF5\uC784 \uC0B0\uC815\uB3C4 \uAC1D\uAD00\uD654\uB429\uB2C8\uB2E4.", review: "\uBE0C\uB808\uC774\uD06C \uC815\uBE44 \uD6C4 \uC0C8 \uC18C\uC74C\uC774 \uB09C\uB2E4\uB294 \uACE0\uAC1D \uD074\uB808\uC784\uC774 \uC788\uC5C8\uB294\uB370, \uC791\uC5C5 \uC601\uC0C1\uC744 \uB3CC\uB824\uBCF4\uB2C8 \uC815\uC0C1\uC801\uC778 \uACF5\uC815\uC774\uC5C8\uACE0 \uC18C\uC74C \uC6D0\uC778\uC740 \uB2E4\uB978 \uBD80\uD488\uC774\uC5C8\uC5B4\uC694. \uC601\uC0C1 \uAE30\uBC18 \uC124\uBA85\uC73C\uB85C \uACE0\uAC1D\uB3C4 \uC218\uAE0D\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uC140\uD504\uC138\uCC28\uC7A5\xB7\uC8FC\uC720\uC18C\uB294 \uB113\uC740 \uC57C\uC678 \uACF5\uAC04\uC5D0 \uACE0\uAC1D \uCC28\uB7C9\uACFC \uD604\uAE08\uC774 \uD568\uAED8 \uC788\uC5B4 \uBCF4\uC548 \uB09C\uC774\uB3C4\uAC00 \uB192\uC2B5\uB2C8\uB2E4. \uC8FC\xB7\uC57C\uAC04 \uBAA8\uB450 \uC120\uBA85\uD55C \uC601\uC0C1\uC774 \uD544\uC218\uC774\uBA70 \uC678\uBD80 \uCE68\uC785 \uB300\uBE44\uB3C4 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: "\uC8FC\uC720\uAE30 \uC8FC\uBCC0\uACFC \uC138\uCC28\uAE30 \uC8FC\uBCC0\uC740 \uCC28\uB7C9 \uBC88\uD638 \uC778\uC2DD \uAC00\uB2A5\uD55C 4K \uCE74\uBA54\uB77C\uB85C, \uD1B5\uB85C\uC640 \uC678\uACFD\uC740 Full HD \uB3D4\uD615\uC73C\uB85C \uBE44\uC6A9 \uD6A8\uC728\uC801 \uAD6C\uC131\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uC57C\uAC04 \uD480\uCEEC\uB7EC \uCE74\uBA54\uB77C\uB294 \uC870\uBA85 \uC5C6\uB294 \uC2DC\uAC04\uB300 \uD544\uC218\uC785\uB2C8\uB2E4.", review: "\uC138\uCC28 \uC911 \uACE0\uAC1D\uC774 \uCC28\uB7C9 \uBC94\uD37C\uAC00 \uAE01\uD614\uB2E4\uACE0 \uBC30\uC0C1 \uC694\uAD6C\uD588\uB294\uB370 \uC785\uACE0 \uC2DC\uC810 \uC601\uC0C1\uC5D0 \uC774\uBBF8 \uC788\uB358 \uC2A4\uD06C\uB798\uCE58\uC600\uC5B4\uC694. \uC601\uC0C1 \uC99D\uAC70 \uC5C6\uC5C8\uC73C\uBA74 \uC218\uC2ED\uB9CC\uC6D0 \uBC30\uC0C1\uD588\uC744 \uC0C1\uD669\uC785\uB2C8\uB2E4." }, { desc: "\uC911\uACE0\uCC28\uB9E4\uC7A5\xB7\uC790\uB3D9\uCC28\uB9E4\uC7A5\uC740 \uB2E4\uC218\uC758 \uACE0\uAC00 \uCC28\uB7C9\uC774 \uC57C\uC678 \uC804\uC2DC\uB418\uC5B4 \uC788\uC5B4 24\uC2DC\uAC04 \uBCF4\uC548\uC774 \uD544\uC218\uC785\uB2C8\uB2E4. \uB3C4\uB09C\xB7\uD30C\uC190 \uC704\uD5D8\uACFC \uD568\uAED8 \uC2DC\uC2B9 \uACE0\uAC1D \uAD00\uB9AC, \uACC4\uC57D \uC0C1\uB2F4 \uAE30\uB85D\uB3C4 \uAC10\uC2DC \uB300\uC0C1\uC785\uB2C8\uB2E4.", tip: "\uC804\uC2DC \uCC28\uB7C9 \uAD6C\uC5ED \uC804\uCCB4\uB97C \uC0AC\uAC01\uC9C0\uB300 \uC5C6\uC774 \uCEE4\uBC84\uD558\uB294 \uAC83\uC774 \uAE30\uBCF8\uC774\uBA70, \uBC88\uD638\uD310 \uC778\uC2DD \uAE30\uB2A5\uC73C\uB85C \uC678\uBD80 \uCD9C\uC785 \uCC28\uB7C9\uC744 \uC790\uB3D9 \uAE30\uB85D\uD558\uC138\uC694. \uC2DC\uC2B9 \uCC28\uB7C9\uC740 GPS \uCD94\uC801\uACFC \uBCD1\uD589\uD558\uBA74 \uB354\uC6B1 \uC548\uC804\uD569\uB2C8\uB2E4.", review: "\uC8FC\uB9D0 \uC57C\uAC04\uC5D0 \uC804\uC2DC \uCC28\uB7C9 \uC720\uB9AC\uCC3D\uC774 \uAE68\uC838 \uC788\uB294 \uAC83\uC744 \uBC1C\uACAC\uD588\uC5B4\uC694. CCTV\uB85C \uD655\uC778\uD558\uB2C8 \uC220 \uCDE8\uD55C \uD589\uC778\uC774 \uC2E4\uC218\uB85C \uBD80\uB52A\uD78C \uC601\uC0C1\uC774 \uC788\uC5B4 \uACBD\uCC30 \uC2E0\uACE0\uB85C \uBCF4\uC0C1\uBC1B\uC558\uC2B5\uB2C8\uB2E4." }, { desc: "\uC624\uD1A0\uBC14\uC774\uC0F5\xB7\uC790\uC804\uAC70\uB9E4\uC7A5\uC740 \uACE0\uAC00 \uC81C\uD488\uC758 \uB3C4\uB09C \uC704\uD5D8\uC774 \uD2B9\uD788 \uB192\uACE0, \uC2DC\uC2B9 \uD6C4 \uB3C4\uC8FC \uAC19\uC740 \uD2B9\uC218 \uBC94\uC8C4 \uC720\uD615\uC5D0 \uB300\uBE44\uD574\uC57C \uD569\uB2C8\uB2E4. \uBC88\uD638\uD310\uC774 \uC5C6\uB294 \uC790\uC804\uAC70\uB294 \uCD94\uC801\uC774 \uC5B4\uB824\uC6CC \uC0AC\uC804 \uC608\uBC29\uC774 \uB354 \uC911\uC694\uD569\uB2C8\uB2E4.", tip: "\uACE0\uAC00 \uC790\uC804\uAC70\uB294 \uAC1C\uBCC4 \uD0DC\uADF8\uC640 CCTV\uB97C \uC5F0\uB3D9\uD558\uACE0, \uC2DC\uC2B9 \uC2DC \uACE0\uAC1D \uC2E0\uBD84\uC99D\uACFC CCTV \uAE30\uB85D\uC744 \uB3D9\uC2DC \uD655\uBCF4\uD558\uC138\uC694. \uC804\uAE30\uC790\uC804\uAC70 \uB9E4\uC7A5\uC740 \uBC30\uD130\uB9AC \uBD84\uB9AC\uD615\uC758 \uC808\uB3C4 \uB300\uC751\uB3C4 \uD544\uC694\uD569\uB2C8\uB2E4.", review: "\uC804\uAE30\uC790\uC804\uAC70 \uC2DC\uC2B9\uC744 \uB098\uAC04 \uACE0\uAC1D\uC774 \uB3CC\uC544\uC624\uC9C0 \uC54A\uC558\uC5B4\uC694. CCTV\uC5D0\uC11C \uC5BC\uAD74\uACFC \uBCF5\uC7A5\uC744 \uD655\uBCF4\uD558\uACE0 \uACBD\uCC30 \uC2E0\uACE0\uD588\uB354\uB2C8 \uC8FC\uBCC0 CCTV \uCD94\uC801\uC73C\uB85C \uD558\uB8E8 \uB9CC\uC5D0 \uAC80\uAC70\uB410\uC2B5\uB2C8\uB2E4. \uBC94\uC8C4\uC790\uB3C4 \uC774\uC81C CCTV\uB97C \uB450\uB824\uC6CC\uD569\uB2C8\uB2E4." }],
    office: [{ desc: "\uC11C\uB958\xB7\uACC4\uC57D\uC11C \uBCF4\uAD00, \uC57C\uAC04\xB7\uC8FC\uB9D0 \uBB34\uC778 \uC2DC\uAC04\uB300 \uBCF4\uC548, \uBC29\uBB38\uC790 \uCD9C\uC785 \uAE30\uB85D\uC774 \uC0AC\uBB34\uC2E4 CCTV\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uBC29\uBB38\uC790 \uCD9C\uC785 \uAE30\uB85D\uC744 \uC601\uC0C1\uC73C\uB85C \uB0A8\uAE30\uBA74 \uBCF4\uC548 \uAC10\uC0AC\uB098 \uAC1C\uC778\uC815\uBCF4 \uAD00\uB9AC \uC810\uAC80\uC5D0 \uC99D\uBE59 \uC790\uB8CC\uB85C \uD65C\uC6A9\uB429\uB2C8\uB2E4.", review: "\uC8FC\uB9D0\uC5D0 \uC0AC\uBB34\uC2E4 \uCD9C\uC785 \uC54C\uB9BC\uC774 \uC640\uC11C \uD655\uC778\uD558\uB2C8 \uC9C1\uC6D0\uC774 \uC11C\uB958\uB97C \uAC00\uC9C0\uB7EC \uC628 \uAC83\uC774\uC5C8\uC5B4\uC694. \uD655\uC778 \uC5C6\uC774 \uB118\uC5B4\uAC14\uC73C\uBA74 \uBD88\uC548\uD588\uC744 \uAC81\uB2C8\uB2E4." }, { desc: "\uBC95\uBB34\uBC95\uC778\xB7\uD68C\uACC4\uBC95\uC778\xB7\uCEE8\uC124\uD305\uD68C\uC0AC \uAC19\uC740 \uC804\uBB38\uC9C1 \uC0AC\uBB34\uC2E4\uC740 \uACE0\uAC1D \uC815\uBCF4 \uBCF4\uC548\uC774 \uC0DD\uBA85\uC785\uB2C8\uB2E4. \uC11C\uB958 \uBCF4\uAD00\uC2E4, \uD68C\uC758\uC2E4, \uC11C\uBC84\uC2E4\uAE4C\uC9C0 \uACC4\uCE35\uBCC4 \uC811\uADFC \uAD8C\uD55C \uAD00\uB9AC\uC640 \uC601\uC0C1 \uAE30\uB85D\uC774 \uBC95\uC801 \uCC45\uC784 \uAD00\uB9AC\uC5D0 \uD544\uC218\uC785\uB2C8\uB2E4.", tip: "\uAC01 \uACF5\uAC04\uBCC4 \uCC28\uB4F1 \uC811\uADFC \uC124\uC815\uACFC \uCD9C\uC785\uBB38\uB9C8\uB2E4 \uCE74\uBA54\uB77C \uBC30\uCE58\uB97C \uD45C\uC900\uD654\uD558\uC138\uC694. \uD2B9\uD788 \uC11C\uBC84\uC2E4\xB7\uC11C\uB958 \uBCF4\uAD00\uC2E4\uC740 365\uC77C \uAE30\uB85D + \uC6D0\uACA9 \uC54C\uB9BC \uC2DC\uC2A4\uD15C\uC774 \uD544\uC218\uC785\uB2C8\uB2E4. \uB0B4\uBD80\uC790\uC5D0 \uC758\uD55C \uC815\uBCF4 \uC720\uCD9C \uC608\uBC29\uC5D0\uB3C4 \uD6A8\uACFC\uC801\uC785\uB2C8\uB2E4.", review: "\uACE0\uAC1D \uC790\uB8CC \uC720\uCD9C \uC758\uC2EC \uC2E0\uACE0\uAC00 \uC788\uC5C8\uB294\uB370 CCTV \uAE30\uB85D\uC73C\uB85C \uD574\uB2F9 \uC2DC\uAC04\uB300 \uC790\uB8CC\uC2E4 \uCD9C\uC785\uC790\uB97C \uD2B9\uC815\uD574\uC11C \uB0B4\uBD80 \uAC10\uC0AC\uB85C \uC774\uC5B4\uC84C\uC5B4\uC694. \uC2E0\uC18D\uD55C \uC6D0\uC778 \uADDC\uBA85\uC774 \uAC00\uB2A5\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uACF5\uACF5\uAE30\uAD00\xB7\uAD00\uACF5\uC11C\xB7\uC8FC\uBBFC\uC13C\uD130\uB294 \uBBFC\uC6D0\uC778 \uB300\uC751\uACFC \uC9C1\uC6D0 \uC5C5\uBB34 \uAD00\uB9AC\uAC00 \uB3D9\uC2DC\uC5D0 \uC774\uB8E8\uC5B4\uC9D1\uB2C8\uB2E4. \uBBFC\uC6D0 \uCC3D\uAD6C\uC758 \uBD84\uC7C1 \uB300\uC751, \uB300\uAE30\uC2E4 \uC548\uC804, \uBB34\uC778 \uC218\uB0A9\uAE30 \uC8FC\uBCC0 \uBCF4\uC548\uC774 \uC8FC\uC694 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "\uBBFC\uC6D0 \uCC3D\uAD6C\uB294 \uACF5\uC2DD \uAE30\uB85D \uBAA9\uC801\uC73C\uB85C \uACE0\uD654\uC9C8 \uB179\uD654\uAC00 \uAC00\uB2A5\uD558\uB3C4\uB85D \uBC95\uC801 \uADFC\uAC70\uB97C \uD655\uBCF4\uD55C \uD6C4 \uC124\uCE58\uD574\uC57C \uD569\uB2C8\uB2E4. \uBBFC\uC6D0\uC778 \uC0AC\uC804 \uACE0\uC9C0\uC640 \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC900\uC218\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4.", review: "\uC545\uC131 \uBBFC\uC6D0\uC778\uC774 \uC9C1\uC6D0\uC5D0\uAC8C \uD3ED\uC5B8\uC744 \uD37C\uBD80\uC5C8\uB294\uB370 CCTV \uC601\uC0C1\uC73C\uB85C \uC99D\uAC70 \uD655\uBCF4 \uD6C4 \uCC98\uBC8C \uC808\uCC28\uB97C \uC9C4\uD589\uD588\uC5B4\uC694. \uC9C1\uC6D0 \uBCF4\uD638\uC5D0 \uACB0\uC815\uC801 \uC7A5\uCE58\uAC00 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4." }, { desc: "\uC544\uD30C\uD2B8 \uB2E8\uC9C0\xB7\uC624\uD53C\uC2A4\uD154\xB7\uC8FC\uC0C1\uBCF5\uD569\uC740 \uB300\uADDC\uBAA8 \uB2E4\uC138\uB300 \uAC74\uBB3C\uC758 \uBCF4\uC548 \uAD00\uB9AC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4. \uACF5\uC6A9 \uACF5\uAC04, \uC8FC\uCC28\uC7A5, \uC5D8\uB9AC\uBCA0\uC774\uD130, \uC5D8\uB9AC\uBCA0\uC774\uD130 \uD640 \uAC01\uAC01\uC758 \uBCF4\uC548 \uC124\uACC4\uC640 \uAD00\uB9AC\uC18C\uC758 \uD1B5\uD569 \uAD00\uC81C\uAC00 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uAD00\uB9AC\uC2E4\uC5D0 \uD1B5\uD569 \uAD00\uC81C \uBAA8\uB2C8\uD130\uB97C \uC124\uCE58\uD558\uACE0 AI \uC774\uC0C1\uD589\uB3D9 \uAC10\uC9C0\uB97C \uCD94\uAC00\uD558\uBA74 \uC785\uC8FC\uBBFC \uC548\uC804\uC774 \uD06C\uAC8C \uD5A5\uC0C1\uB429\uB2C8\uB2E4. \uD0DD\uBC30 \uBD84\uC2E4 \uBC29\uC9C0\uC6A9 \uC5D8\uB9AC\uBCA0\uC774\uD130 \uD640 \uCE74\uBA54\uB77C\uB3C4 \uC785\uC8FC\uBBFC \uB9CC\uC871\uB3C4\uB97C \uB192\uC774\uB294 \uAE30\uB2A5\uC785\uB2C8\uB2E4.", review: "\uC544\uD30C\uD2B8 \uC5D8\uB9AC\uBCA0\uC774\uD130 \uD640\uC5D0 \uD0DD\uBC30\uB97C \uB450\uACE0 \uAC04 \uD0DD\uBC30\uAE30\uC0AC\uAC00 \uC788\uC5C8\uB294\uB370, \uB2E4\uC74C \uC785\uC8FC\uBBFC\uC774 \uAC00\uC838\uAC00\uB294 \uC7A5\uBA74\uC774 CCTV\uB85C \uC7A1\uD600\uC11C \uBC18\uD658 \uC694\uCCAD\uC774 \uAC00\uB2A5\uD588\uC5B4\uC694. \uB2E8\uC21C\uD55C \uC624\uD574\uC600\uC9C0\uB9CC \uC601\uC0C1\uC774 \uBE60\uB974\uAC8C \uD574\uACB0\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uACF5\uC720\uC624\uD53C\uC2A4\xB7\uC2A4\uD130\uB514\uB8F8\xB7\uD68C\uC758\uC2E4\uB300\uC5EC\uB294 \uBD88\uD2B9\uC815 \uB2E4\uC218 \uC774\uC6A9\uC790 \uAD00\uB9AC\uAC00 \uACFC\uC81C\uC785\uB2C8\uB2E4. \uCD9C\uC785 \uAD00\uB9AC, \uC774\uC6A9 \uC2DC\uAC04 \uAE30\uB85D, \uAE30\uBB3C \uD30C\uC190 \uC2DC \uCC45\uC784 \uC18C\uC7AC \uD655\uC778\uC774 \uD575\uC2EC \uC6B4\uC601 \uC694\uC18C\uC785\uB2C8\uB2E4.", tip: "\uAC01 \uB8F8\uC758 \uC785\uCD9C\uC785 \uAE30\uB85D\uACFC \uACF5\uC6A9 \uACF5\uAC04 \uBAA8\uB2C8\uD130\uB9C1\uC744 \uBD84\uB9AC\uD574\uC11C \uAD00\uB9AC\uD558\uC138\uC694. \uC608\uC57D \uC2DC\uC2A4\uD15C\uACFC \uC5F0\uB3D9\uD558\uBA74 \uC815\uD655\uD55C \uC774\uC6A9 \uC2DC\uAC04\uACFC \uC2E4\uC81C \uC774\uC6A9\uC790\uAC00 \uC790\uB3D9 \uB9E4\uCE6D\uB418\uC5B4 \uBD84\uC7C1\uC774 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4.", review: "\uD68C\uC758\uC2E4 \uC0AC\uC6A9 \uD6C4 \uAE30\uBB3C \uD30C\uC190\uC774 \uC788\uC5C8\uB294\uB370 \uC0AC\uC6A9\uC790\uAC00 \uC790\uC2E0\uC758 \uC798\uBABB\uC774 \uC544\uB2C8\uB77C\uACE0 \uC8FC\uC7A5\uD588\uC5B4\uC694. \uADF8\uB7EC\uB098 \uC785\uC2E4 \uC804\uD6C4 \uC601\uC0C1\uC744 \uBE44\uAD50\uD558\uB2C8 \uD30C\uC190\uC774 \uC0AC\uC6A9 \uC911 \uBC1C\uC0DD\uD55C \uAC8C \uBA85\uD655\uD588\uACE0 \uBC30\uC0C1 \uCC98\uB9AC\uD588\uC2B5\uB2C8\uB2E4." }],
    stay: [{ desc: "\uD22C\uC219\uAC1D \uCD9C\uC785, \uBCF5\uB3C4\xB7\uB85C\uBE44 \uBCF4\uC548, \uADC0\uC911\uD488 \uBD84\uC2E4 \uB300\uBE44\uAC00 \uC219\uBC15\uC5C5 CCTV\uC758 \uD544\uC218 \uAC10\uC2DC \uC601\uC5ED\uC785\uB2C8\uB2E4.", tip: "\uCCB4\uD06C\uC778\xB7\uCCB4\uD06C\uC544\uC6C3 \uC2DC\uC810 \uC601\uC0C1\uC774 \uC788\uC73C\uBA74 \uD1F4\uC2E4 \uD6C4 \uAC1D\uC2E4 \uD30C\uC190\uC774\uB098 \uBB3C\uD488 \uBD84\uC2E4 \uBD84\uC7C1 \uC2DC \uAC1D\uAD00\uC801 \uC99D\uAC70\uAC00 \uB429\uB2C8\uB2E4.", review: "\uD1F4\uC2E4 \uD6C4 TV\uAC00 \uACE0\uC7A5\uB0AC\uB2E4\uACE0 \uC8FC\uC7A5\uD558\uC168\uB294\uB370, \uC785\uC2E4 \uC804 \uC810\uAC80 \uC601\uC0C1\uC5D0 \uC774\uBBF8 \uACE0\uC7A5 \uC0C1\uD0DC\uAC00 \uAE30\uB85D\uB3FC\uC788\uC5C8\uC5B4\uC694. \uC5B5\uC6B8\uD55C \uBC30\uC0C1\uC744 \uBA74\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uD2B9\uAE09\uD638\uD154\xB7\uBE44\uC988\uB2C8\uC2A4\uD638\uD154\uC740 VIP \uACE0\uAC1D \uD504\uB77C\uC774\uBC84\uC2DC\uC640 \uC5C4\uACA9\uD55C \uBCF4\uC548\uC774 \uB3D9\uC2DC\uC5D0 \uD544\uC694\uD569\uB2C8\uB2E4. \uB85C\uBE44\xB7\uC5D8\uB9AC\uBCA0\uC774\uD130\xB7\uC8FC\uCC28\uC7A5 \uB4F1 \uACF5\uC6A9 \uACF5\uAC04\uC740 \uCCA0\uC800\uD55C \uAC10\uC2DC, \uAC1D\uC2E4 \uCE35 \uBCF5\uB3C4\uB294 \uD504\uB77C\uC774\uBC84\uC2DC \uC911\uC2EC\uC758 \uBBF8\uB2C8\uBA40 \uC124\uACC4\uAC00 \uD45C\uC900\uC785\uB2C8\uB2E4.", tip: "\uADC0\uC911\uD488 \uB3C4\uB09C \uBD84\uC7C1\uC740 \uC219\uBC15\uC5C5\uC5D0\uC11C \uAC00\uC7A5 \uD070 \uB9AC\uC2A4\uD06C\uC785\uB2C8\uB2E4. \uAC1D\uC2E4 \uC785\uCD9C\uC785 \uAE30\uB85D\uACFC \uAE08\uACE0 \uC0AC\uC6A9 \uB85C\uADF8\uB97C CCTV\uC640 \uC5F0\uB3D9\uD558\uBA74 \uCC45\uC784 \uC18C\uC7AC\uAC00 \uBA85\uD655\uD574\uC9D1\uB2C8\uB2E4. VIP \uACE0\uAC1D \uCD9C\uC785 \uC2DC\uC5D0\uB294 \uD2B9\uBCC4 \uC54C\uB9BC \uC2DC\uC2A4\uD15C\uB3C4 \uC720\uC6A9\uD569\uB2C8\uB2E4.", review: "\uD22C\uC219\uAC1D\uC774 \uD604\uAE08\uC774 \uC5C6\uC5B4\uC84C\uB2E4\uACE0 \uD588\uB294\uB370 \uAC1D\uC2E4 \uC785\uCD9C\uC785 \uAE30\uB85D\uACFC CCTV \uAD50\uCC28 \uAC80\uC99D \uACB0\uACFC \uBCF8\uC778 \uC9C0\uC778\uC774 \uAC1D\uC2E4\uC5D0 \uB4E4\uB800\uB358 \uC0AC\uC2E4\uC774 \uD655\uC778\uB410\uC5B4\uC694. \uD638\uD154 \uCE21 \uCC45\uC784\uC774 \uC544\uB2D8\uC774 \uBD84\uBA85\uD588\uACE0 \uACE0\uAC1D\uB3C4 \uC218\uAE0D\uD558\uC168\uC2B5\uB2C8\uB2E4." }, { desc: "\uBAA8\uD154\xB7\uD39C\uC158\xB7\uAC8C\uC2A4\uD2B8\uD558\uC6B0\uC2A4\uB294 \uC18C\uADDC\uBAA8 \uBB34\uC778 \uCCB4\uD06C\uC778 \uD658\uACBD\uC774 \uB9CE\uC544 CCTV \uC758\uC874\uB3C4\uAC00 \uB9E4\uC6B0 \uB192\uC2B5\uB2C8\uB2E4. \uC57C\uAC04 \uBB34\uC778 \uC2DC\uAC04\uB300 \uC548\uC804 \uAD00\uB9AC\uC640 \uBD88\uBC95 \uD22C\uC219\xB7\uC7A5\uAE30 \uBB34\uB2E8 \uCCB4\uB958 \uAC19\uC740 \uD2B9\uC218 \uC0C1\uD669 \uB300\uC751\uC774 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "\uBB34\uC778 \uCCB4\uD06C\uC778\uAE30\uC640 CCTV\uB97C \uC5F0\uB3D9\uD558\uBA74 \uC2E0\uBD84\uC99D \uD655\uC778\uACFC \uC5BC\uAD74 \uC778\uC2DD\uC774 \uC790\uB3D9\uD654\uB429\uB2C8\uB2E4. \uBBF8\uB4F1\uB85D \uC778\uC6D0 \uB3D9\uBC18 \uD22C\uC219 \uAC19\uC740 \uBC95 \uC704\uBC18 \uC0C1\uD669\uC744 \uC0AC\uC804 \uBC29\uC9C0\uD560 \uC218 \uC788\uC5B4 \uC5C5\uC8FC \uB9AC\uC2A4\uD06C \uAD00\uB9AC\uC5D0 \uC911\uC694\uD569\uB2C8\uB2E4.", review: "\uBAA8\uD154\uC744 \uBB34\uC778 \uC6B4\uC601\uD558\uB294\uB370 \uBBF8\uC131\uB144\uC790 \uB3D9\uBC18 \uD22C\uC219 \uC758\uC2EC \uC0C1\uD669\uC774 CCTV\uB85C \uBC14\uB85C \uD655\uC778\uB410\uC5B4\uC694. \uC790\uB3D9 \uC54C\uB9BC\uC73C\uB85C \uD604\uC7A5 \uD655\uC778\uD574\uC11C \uC5C5\uC8FC \uCC45\uC784 \uBB38\uC81C\uB97C \uC0AC\uC804\uC5D0 \uB9C9\uC744 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4." }, { desc: "\uAE00\uB7A8\uD551\uC7A5\xB7\uCEA0\uD551\uC7A5\uC740 \uB113\uC740 \uC57C\uC678 \uACF5\uAC04\uC758 \uD2B9\uC218\uC131 \uB54C\uBB38\uC5D0 \uC77C\uBC18 \uC219\uBC15\uC5C5\uACFC \uB2E4\uB978 CCTV \uC124\uACC4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4. \uAC01 \uCEA0\uD551 \uC0AC\uC774\uD2B8\uC758 \uD504\uB77C\uC774\uBC84\uC2DC\uB294 \uBCF4\uD638\uD558\uB418, \uACF5\uC6A9 \uC2DC\uC124(\uC0E4\uC6CC\uC7A5\xB7\uC8FC\uCC28\uC7A5\xB7\uC785\uAD6C)\uC758 \uC548\uC804 \uAD00\uB9AC\uB294 \uCCA0\uC800\uD574\uC57C \uD569\uB2C8\uB2E4.", tip: "\uC57C\uC678 \uD658\uACBD\uC5D0 \uB9DE\uB294 \uBC29\uC218\xB7\uBC29\uC9C4 \uB4F1\uAE09 \uCE74\uBA54\uB77C\uC640 LTE \uC5F0\uACB0\uD615\uC744 \uBCD1\uD589\uD558\uC138\uC694. \uC57C\uAC04 \uD480\uCEEC\uB7EC \uCD2C\uC601 \uAE30\uB2A5\uC740 \uCEA0\uD551\uC7A5 \uD2B9\uC131\uC0C1 \uD544\uC218\uC774\uBA70, \uD574\uCDA9\xB7\uC57C\uC0DD\uB3D9\uBB3C \uAC10\uC9C0\uB85C\uB3C4 \uD65C\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", review: "\uAE00\uB7A8\uD551 \uC2DC\uC98C \uC131\uC218\uAE30\uC5D0 \uCC28\uB7C9 \uB3C4\uB09C \uC2DC\uB3C4\uAC00 \uC788\uC5C8\uB294\uB370 \uC8FC\uCC28\uC7A5 \uCE74\uBA54\uB77C\uB85C \uC989\uC2DC \uBC1C\uACAC\uD558\uACE0 \uACBD\uCC30 \uCD9C\uB3D9\uC744 \uC694\uCCAD\uD574 \uB9C9\uC558\uC5B4\uC694. \uC57C\uC678 \uCEA0\uD551\uC7A5\uC740 \uD2B9\uD788 \uC678\uBD80 \uCE68\uC785\uC5D0 \uCDE8\uC57D\uD574\uC11C CCTV\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4." }, { desc: "\uB9AC\uC870\uD2B8 \uC2DD\uC74C\uB9E4\uC7A5\xB7\uD638\uD154 \uB808\uC2A4\uD1A0\uB791\uC740 \uD638\uD154 \uBCF4\uC548\uACFC \uC5F0\uB3D9\uB41C \uD2B9\uC218 \uD658\uACBD\uC785\uB2C8\uB2E4. \uD22C\uC219\uAC1D \uC11C\uBE44\uC2A4\uC640 \uC678\uBD80 \uACE0\uAC1D \uC774\uC6A9\uC774 \uD63C\uC7AC\uB418\uC5B4 \uC788\uC5B4 \uAC1D\uC2E4 \uD0A4 \uC5F0\uB3D9 \uACB0\uC81C\uC640 \uC77C\uBC18 \uACB0\uC81C\uC758 \uAD6C\uBD84 \uAD00\uB9AC\uAC00 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uB808\uC2A4\uD1A0\uB791 \uC785\uAD6C\uC640 \uCE74\uC6B4\uD130\uB294 \uD638\uD154 \uD1B5\uD569 \uAD00\uC81C \uC2DC\uC2A4\uD15C\uC5D0 \uC5F0\uACB0\uD558\uACE0, \uAC1D\uC2E4 \uD0A4\uB85C \uACB0\uC81C\uD558\uB294 \uD22C\uC219\uAC1D\uC740 \uC790\uB3D9 \uC2DD\uBCC4\uD558\uB3C4\uB85D POS \uC5F0\uB3D9\uC744 \uAD6C\uCD95\uD558\uC138\uC694. \uC678\uBD80 \uACE0\uAC1D \uBD84\uC7C1 \uC2DC\uC5D0\uB3C4 \uC601\uC0C1 \uC99D\uAC70\uAC00 \uBE60\uB978 \uD574\uACB0\uC744 \uB3D5\uC2B5\uB2C8\uB2E4.", review: "\uD638\uD154 \uD22C\uC219\uAC1D\uC774 \uB808\uC2A4\uD1A0\uB791 \uACB0\uC81C\uB97C \uAC1D\uC2E4\uB85C \uC62C\uB838\uB294\uB370 \uCCB4\uD06C\uC544\uC6C3 \uC2DC \uBCF8\uC778\uC774 \uC8FC\uBB38\uD55C \uAC8C \uC544\uB2C8\uB77C\uACE0 \uD588\uC5B4\uC694. CCTV\uB85C \uB2F9\uC2DC \uD14C\uC774\uBE14 \uC0C1\uD669\uC744 \uD655\uC778\uD558\uB2C8 \uC77C\uD589\uC774 \uC8FC\uBB38\uD55C \uBA54\uB274\uC600\uACE0, \uAE54\uB054\uD558\uAC8C \uD574\uACB0\uB410\uC2B5\uB2C8\uB2E4." }],
    unmanned: [{ desc: "24\uC2DC\uAC04 \uBB34\uC778 \uC6B4\uC601\uC5D0\uC11C CCTV\uB294 \uC9C1\uC6D0\uC758 \uB208\uC744 \uB300\uC2E0\uD569\uB2C8\uB2E4. \uB3C4\uB09C \uAC10\uC9C0, \uC774\uC0C1 \uD589\uB3D9 \uC54C\uB9BC, \uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1\uC774 \uBB34\uC778\uB9E4\uC7A5 \uC0DD\uC874\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0\uC640 \uACB0\uC81C \uC2DC\uC2A4\uD15C\uC744 \uC5F0\uB3D9\uD558\uBA74 \uBBF8\uACB0\uC81C \uC774\uD0C8\uC744 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uAC10\uC9C0\uD558\uC5EC \uC989\uC2DC \uC54C\uB9BC\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uC0C8\uBCBD\uC5D0 \uACB0\uC81C \uC5C6\uC774 \uC0C1\uD488\uC744 \uAC00\uC838\uAC00\uB294 \uC0AC\uB78C\uC744 AI \uC54C\uB9BC\uC73C\uB85C \uAC10\uC9C0\uD588\uC5B4\uC694. \uC601\uC0C1\uC744 \uACBD\uCC30\uC5D0 \uC81C\uCD9C\uD574\uC11C \uBC14\uB85C \uD574\uACB0\uB410\uC2B5\uB2C8\uB2E4." }, { desc: "\uBB34\uC778\uD3B8\uC758\uC810\xB7\uBB34\uC778\uC544\uC774\uC2A4\uD06C\uB9BC\uC810\xB7\uBB34\uC778\uBC00\uD0A4\uD2B8\uB9E4\uC7A5 \uB4F1 \uBB34\uC778 \uC6B4\uC601 \uB9E4\uC7A5\uC740 CCTV\uAC00 \uC720\uC77C\uD55C \uBCF4\uC548 \uC790\uC0B0\uC785\uB2C8\uB2E4. \uB3C4\uB09C \uBC29\uC9C0 + \uC774\uC0C1 \uC0C1\uD669 \uB300\uC751 + \uACE0\uAC1D \uC548\uC804 \uBAA8\uB450\uB97C \uC601\uC0C1 \uAE30\uBC18\uC73C\uB85C \uAD00\uB9AC\uD574\uC57C \uD569\uB2C8\uB2E4.", tip: "AI \uAE30\uBC18 \uBBF8\uACB0\uC81C \uAC10\uC9C0, \uCCB4\uB958 \uC2DC\uAC04 \uBD84\uC11D, \uC774\uC0C1\uD589\uB3D9 \uD0D0\uC9C0 3\uC885 \uC138\uD2B8\uB97C \uC5F0\uB3D9\uD558\uBA74 \uBB34\uC778 \uB9E4\uC7A5\uB3C4 \uC548\uC804\uD558\uAC8C \uC6B4\uC601\uB429\uB2C8\uB2E4. \uD2B9\uD788 \uBBF8\uC131\uB144\uC790 \uCD9C\uC785 \uAC10\uC9C0\uC640 \uC8FC\uB958 \uB9E4\uC7A5\uC758 \uC5F0\uB839 \uD655\uC778\uC740 \uBC95\uC801 \uB9AC\uC2A4\uD06C \uAD00\uB9AC\uC5D0 \uD544\uC218\uC785\uB2C8\uB2E4.", review: "\uBB34\uC778 \uD3B8\uC758\uC810 \uC624\uD508 \uCCAB \uB2EC \uB3C4\uB09C\uC774 50\uAC74 \uB118\uC5C8\uB294\uB370 AI \uCE74\uBA54\uB77C\uB85C \uACBD\uACE0 \uC74C\uC131 \uC790\uB3D9 \uC1A1\uCD9C \uAE30\uB2A5\uC744 \uD65C\uC131\uD654\uD558\uB2C8 \uB2E4\uC74C \uB2EC\uC5D0 5\uAC74\uC73C\uB85C \uC904\uC5C8\uC5B4\uC694. \uAE30\uC220\uC774 \uC9C1\uC6D0 1\uBA85 \uBAAB\uC744 \uD569\uB2C8\uB2E4." }, { desc: "\uBB34\uC778 \uC138\uD0C1\uC18C\xB7\uBB34\uC778 \uBB38\uAD6C\uC810\uC740 24\uC2DC\uAC04 \uC6B4\uC601\uC774 \uB9E4\uCD9C \uADF9\uB300\uD654\uC758 \uD575\uC2EC\uC774\uB77C \uC57C\uAC04 \uBB34\uC778 \uC2DC\uAC04\uB300 \uBCF4\uC548\uC774 \uC0DD\uBA85\uC120\uC785\uB2C8\uB2E4. CCTV \uC5C6\uC774\uB294 \uC0AC\uC2E4\uC0C1 \uC6B4\uC601\uC774 \uBD88\uAC00\uB2A5\uD55C \uC5C5\uC885\uC785\uB2C8\uB2E4.", tip: "\uC57C\uAC04 \uC2DC\uAC04\uB300 \uC870\uBA85 \uC808\uAC10\uACFC \uBCF4\uC548 \uAC15\uD654\uB97C \uB3D9\uC2DC\uC5D0 \uB2EC\uC131\uD558\uB824\uBA74 \uC801\uC678\uC120+\uD480\uCEEC\uB7EC \uD558\uC774\uBE0C\uB9AC\uB4DC \uCE74\uBA54\uB77C\uAC00 \uD6A8\uACFC\uC801\uC785\uB2C8\uB2E4. \uC13C\uC11C\uB4F1\uACFC \uC5F0\uB3D9\uD558\uBA74 \uC774\uC6A9\uC790 \uAC10\uC9C0 \uC2DC\uB9CC \uC870\uBA85 \uCF1C\uC9C0\uACE0 \uD3C9\uC0C1\uC2DC\uB294 \uCD5C\uC18C \uC870\uBA85\uC73C\uB85C \uBE44\uC6A9 \uC808\uAC10\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", review: "24\uC2DC\uAC04 \uC138\uD0C1\uC18C \uC6B4\uC601 \uC911 \uC0C8\uBCBD\uC5D0 \uACE0\uAC1D\uC774 \uC138\uD0C1\uAE30 \uC704\uC5D0 \uC9C0\uAC11\uC744 \uB450\uACE0 \uAC14\uB294\uB370, \uB2E4\uC74C \uC774\uC6A9\uC790\uAC00 \uC601\uC0C1\uC73C\uB85C \uD655\uC778\uB41C \uD6C4 \uB3CC\uB824\uBC1B\uC558\uC5B4\uC694. CCTV\uAC00 \uACE0\uAC1D \uB9CC\uC871\uB3C4\uAE4C\uC9C0 \uB192\uC5EC\uC8FC\uACE0 \uC788\uC2B5\uB2C8\uB2E4." }, { desc: "\uBB34\uC778 \uC0AC\uC9C4\uAD00\xB7\uC140\uD504 \uC2A4\uD29C\uB514\uC624\uB294 \uACE0\uAC1D \uD504\uB77C\uC774\uBC84\uC2DC\uAC00 \uB2E4\uB978 \uBB34\uC778\uB9E4\uC7A5\uBCF4\uB2E4 \uB354 \uBBFC\uAC10\uD569\uB2C8\uB2E4. \uACF5\uC6A9 \uACF5\uAC04\uB9CC \uCD2C\uC601 \uD5C8\uC6A9, \uCD2C\uC601 \uBD80\uC2A4 \uB0B4\uBD80\uB294 \uC808\uB300 \uC81C\uC678\uB77C\uB294 \uBC95\uC801 \uC6D0\uCE59\uC744 \uC5C4\uACA9\uD788 \uC9C0\uCF1C\uC57C \uD569\uB2C8\uB2E4.", tip: "\uCD9C\uC785\uBB38\uACFC \uB300\uAE30\uC2E4, \uBB34\uC778 \uD0A4\uC624\uC2A4\uD06C \uC8FC\uBCC0\uB9CC \uCD2C\uC601\uD558\uACE0 \uCD2C\uC601 \uBD80\uC2A4\uB294 \uC678\uBD80 \uCD9C\uC785\uBB38\uB9CC \uAC10\uC2DC\uD558\uC138\uC694. \uC774\uC6A9 \uACE0\uC9C0\uBB38\uC5D0 CCTV \uCD2C\uC601 \uBC94\uC704\uB97C \uBA85\uD655\uD788 \uD45C\uC2DC\uD558\uBA74 \uBC95\uC801 \uB9AC\uC2A4\uD06C\uB97C \uCD5C\uC18C\uD654\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uC140\uD504 \uC2A4\uD29C\uB514\uC624\uC5D0\uC11C \uCD2C\uC601 \uD6C4 \uC18C\uD488\uC774 \uC5C6\uC5B4\uC84C\uB2E4\uB294 \uBBFC\uC6D0\uC774 \uC788\uC5C8\uB294\uB370, \uBD80\uC2A4 \uC678\uBD80 CCTV\uB85C \uC774\uC804 \uC774\uC6A9\uC790\uAC00 \uC2E4\uC218\uB85C \uAC00\uC838\uAC04 \uAC83\uC744 \uD655\uC778\uD574\uC11C \uD68C\uC218\uD588\uC5B4\uC694. \uBC94\uC704 \uC81C\uD55C \uC548\uC5D0\uC11C\uB3C4 \uCDA9\uBD84\uD788 \uD65C\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4." }, { desc: "\uBB34\uC778 \uCE74\uD398\xB7\uBB34\uC778 \uC544\uC774\uC2A4\uD06C\uB9BC\uC810 \uAC19\uC740 24\uC2DC\uAC04 \uC2DD\uC74C\uB8CC \uBB34\uC778\uB9E4\uC7A5\uC740 \uC2DD\uD488 \uC548\uC804\uAE4C\uC9C0 CCTV\uB85C \uAD00\uB9AC\uD569\uB2C8\uB2E4. \uB0C9\uC7A5\uACE0 \uBB38 \uAC1C\uD3D0 \uAC10\uC9C0, \uC720\uD1B5\uAE30\uD55C \uAD00\uB9AC, \uC7A5\uC2DC\uAC04 \uC0C1\uD488 \uBC29\uCE58 \uAC10\uC9C0 \uB4F1 \uBCF5\uD569 \uAE30\uB2A5\uC774 \uC6B4\uC601\uC758 \uD575\uC2EC\uC785\uB2C8\uB2E4.", tip: "\uB0C9\uC7A5\uACE0\xB7\uB0C9\uB3D9\uACE0 \uC8FC\uBCC0 \uCE74\uBA54\uB77C\uB294 \uBB38 \uAC1C\uD3D0 \uC2DC\uAC04\uACFC \uC5F0\uB3D9\uD558\uC5EC \uC7A5\uC2DC\uAC04 \uC5F4\uB824\uC788\uB294 \uACBD\uC6B0 \uC54C\uB9BC\uC744 \uBCF4\uB0B4\uC138\uC694. \uC0C1\uD488 \uAD00\uB9AC \uC790\uB3D9\uD654\uC5D0 \uD06C\uAC8C \uAE30\uC5EC\uD558\uACE0, \uC804\uB825 \uB0AD\uBE44\uC640 \uC2DD\uD488 \uC190\uC2E4\uC744 \uB3D9\uC2DC\uC5D0 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uBB34\uC778 \uC544\uC774\uC2A4\uD06C\uB9BC\uC810\uC5D0\uC11C \uACE0\uAC1D\uC774 \uB0C9\uB3D9\uACE0 \uBB38\uC744 \uC81C\uB300\uB85C \uC548 \uB2EB\uACE0 \uAC04 \uAC83\uC744 CCTV \uC54C\uB9BC\uC73C\uB85C \uBC14\uB85C \uD655\uC778\uD588\uC5B4\uC694. \uC9C1\uC6D0\uC744 \uBCF4\uB0B4 \uC870\uCE58\uD574\uC11C \uC218\uC2ED\uB9CC\uC6D0\uC5B4\uCE58 \uC544\uC774\uC2A4\uD06C\uB9BC\uC774 \uB179\uB294 \uC0AC\uACE0\uB97C \uB9C9\uC558\uC2B5\uB2C8\uB2E4." }],
    mobile: [{ desc: "\uC57C\uC678 \uD589\uC0AC\xB7\uC774\uB3D9 \uB9E4\uC7A5\uC5D0\uC11C \uD604\uAE08 \uBCF4\uAD00, \uC0C1\uD488 \uB3C4\uB09C, \uCC28\uB7C9 \uC8FC\uBCC0 \uBCF4\uC548\uC774 \uC774\uB3D9\uC2DD \uC5C5\uC885 CCTV\uC758 \uACFC\uC81C\uC785\uB2C8\uB2E4.", tip: "LTE \uC5F0\uACB0 \uBB34\uC120 \uCE74\uBA54\uB77C\uB85C \uC57C\uC678\uC5D0\uC11C\uB3C4 \uC2E4\uC2DC\uAC04 \uBAA8\uB2C8\uD130\uB9C1\uC774 \uAC00\uB2A5\uD558\uBA70, \uBC30\uD130\uB9AC \uAD6C\uB3D9\uC73C\uB85C \uC804\uC6D0 \uC5C6\uC774\uB3C4 \uC791\uB3D9\uD569\uB2C8\uB2E4.", review: "\uCD95\uC81C \uBD80\uC2A4\uC5D0\uC11C \uC0C1\uD488 \uB3C4\uB09C\uC774 \uC758\uC2EC\uB410\uB294\uB370 \uBB34\uC120 \uCE74\uBA54\uB77C \uC601\uC0C1\uC73C\uB85C \uD655\uC778\uD558\uB2C8 \uB2E4\uB978 \uACE0\uAC1D\uC774 \uC798\uBABB \uAC00\uC838\uAC04 \uAC83\uC774\uC5C8\uC5B4\uC694. \uBC14\uB85C \uC5F0\uB77D\uD574\uC11C \uD574\uACB0\uD588\uC2B5\uB2C8\uB2E4." }, { desc: "\uD478\uB4DC\uD2B8\uB7ED\xB7\uC774\uB3D9\uC2DD \uB9E4\uC7A5\uC740 \uC8FC\uCC28 \uC704\uCE58\uAC00 \uB9E4\uC77C \uBC14\uB00C\uB294 \uD2B9\uC218 \uD658\uACBD\uC774\uB77C \uACE0\uC815\uD615 CCTV \uC124\uCE58\uAC00 \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uB300\uC2E0 \uCC28\uB7C9\uC5D0 \uBD80\uCC29\uD615 \uCE74\uBA54\uB77C\uC640 LTE \uC5F0\uACB0 \uBB34\uC120 \uCE74\uBA54\uB77C\uB97C \uBCD1\uC6A9\uD558\uB294 \uBC29\uC2DD\uC774 \uD45C\uC900\uC785\uB2C8\uB2E4.", tip: "\uCC28\uB7C9 \uC804\uD6C4\uBC29 \uB300\uC2DC\uCEA0 + \uB9E4\uC7A5 \uAD6C\uC5ED \uBB34\uC120 \uCE74\uBA54\uB77C + \uD604\uAE08\uD568 \uB0B4\uBD80 \uCE74\uBA54\uB77C 3\uC885 \uC870\uD569\uC774 \uC774\uB3D9\uC2DD \uB9E4\uC7A5\uC5D0 \uCD5C\uC801\uD654\uB41C \uAD6C\uC131\uC785\uB2C8\uB2E4. \uBAA8\uB450 \uC2A4\uB9C8\uD2B8\uD3F0 \uC571\uC73C\uB85C \uD1B5\uD569 \uAD00\uC81C\uAC00 \uAC00\uB2A5\uD558\uBA74 \uC6B4\uC601 \uD6A8\uC728\uC774 \uD06C\uAC8C \uC62C\uB77C\uAC11\uB2C8\uB2E4.", review: "\uD478\uB4DC\uD2B8\uB7ED \uC6B4\uC601 \uC911 \uCD95\uC81C \uD6C4 \uC815\uB9AC\uD558\uB2E4 \uD604\uAE08\uD1B5\uC774 \uBE44\uC5B4\uC788\uB294 \uAC83\uC744 \uBC1C\uACAC\uD588\uC5B4\uC694. \uCC28\uB7C9 \uB0B4\uBD80 \uCE74\uBA54\uB77C\uB85C \uC601\uC5C5 \uC911 \uD55C \uACE0\uAC1D\uC774 \uACB0\uC81C \uD63C\uB780 \uC911 \uAC00\uC838\uAC04 \uAC83\uC774 \uD655\uC778\uB410\uC2B5\uB2C8\uB2E4. \uC774\uB3D9 \uB9E4\uC7A5\uC77C\uC218\uB85D \uC99D\uAC70 \uD655\uBCF4\uAC00 \uD544\uC218\uC785\uB2C8\uB2E4." }, { desc: "\uC2DC\uC7A5\uC0C1\uC778\xB7\uD50C\uB9AC\uB9C8\uCF13\xB7\uD589\uC0AC\uBD80\uC2A4 \uAC19\uC740 \uC784\uC2DC \uB9E4\uC7A5\uC740 24\uC2DC\uAC04 \uC774\uC6A9 \uAC00\uB2A5\uD55C \uACBD\uB7C9 CCTV\uAC00 \uD6A8\uACFC\uC801\uC785\uB2C8\uB2E4. \uC124\uCE58\uC640 \uD574\uCCB4\uAC00 \uBE68\uB77C\uC57C \uD558\uACE0, \uBC30\uD130\uB9AC \uAD6C\uB3D9\uC774 \uAC00\uB2A5\uD574\uC57C \uB2E4\uC591\uD55C \uC7A5\uC18C\uC5D0\uC11C \uD65C\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", tip: "\uC790\uC11D \uBD80\uCC29\uC2DD \uB610\uB294 \uD074\uB9BD \uACE0\uC815\uD615 \uACBD\uB7C9 \uCE74\uBA54\uB77C\uC640 \uBAA8\uBC14\uC77C \uD56B\uC2A4\uD31F \uC5F0\uACB0 \uBC29\uC2DD\uC774 \uD3B8\uB9AC\uD569\uB2C8\uB2E4. \uD558\uB8E8 \uB2E8\uC704 \uC784\uB300 \uC11C\uBE44\uC2A4\uB97C \uC774\uC6A9\uD558\uBA74 \uC7A5\uAE30 \uD22C\uC790 \uC5C6\uC774\uB3C4 \uB2E8\uAE30 \uD589\uC0AC \uBCF4\uC548\uC744 \uD655\uBCF4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", review: "\uC8FC\uB9D0 \uD50C\uB9AC\uB9C8\uCF13\uC5D0 \uC77C\uC77C \uC784\uB300 \uCE74\uBA54\uB77C\uB97C \uC124\uCE58\uD588\uB294\uB370 \uC18C\uB9E4\uCE58\uAE30 \uC2DC\uB3C4 1\uAC74\uC744 \uBC14\uB85C \uBC1C\uACAC\uD588\uC5B4\uC694. \uC7A5\uAE30 \uC124\uCE58\uAC00 \uC5B4\uB824\uC6B4 \uC784\uC2DC \uB9E4\uC7A5\uC5D0 \uB531 \uB9DE\uB294 \uC194\uB8E8\uC158\uC785\uB2C8\uB2E4." }]
  };
  const _ciarr = CI[catKey] || CI.retail;
  const ci = _ciarr[Math.abs(h >>> 5) % _ciarr.length];
  let body = "<p>" + biz + js(biz, "\uC740", "\uB294") + " \uD3C9\uADE0 " + cc.area + " \uADDC\uBAA8\uC774\uBA70, " + cc.risk + " \uC704\uD5D8\uC774 \uC0C1\uC874\uD558\uB294 \uC5C5\uC885\uC785\uB2C8\uB2E4. " + ci.desc + '</p><h2 style="color:' + mc + '">\u{1F50D} ' + biz + " \uBCF4\uC548 \uD658\uACBD \uBD84\uC11D</h2><p>" + s(["CCTV \uC601\uC0C1\uC740 \uC0AC\uACE0 \uB2F9\uC2DC \uC0C1\uD669\uC744 \uAC1D\uAD00\uC801\uC73C\uB85C \uC99D\uBA85\uD558\uB294 \uC720\uC77C\uD55C \uC99D\uAC70\uC785\uB2C8\uB2E4. \uBCF4\uD5D8\uAE08 \uCCAD\uAD6C, \uACBD\uCC30 \uC2E0\uACE0, \uACE0\uAC1D \uBD84\uC7C1 \uD574\uACB0 \uC5B4\uB514\uC11C\uB4E0 \uACB0\uC815\uC801 \uC5ED\uD560\uC744 \uD558\uBA70, \uD2B9\uD788 \uB9E4\uC7A5\uC774 \uBC14\uC05C \uD53C\uD06C\uD0C0\uC784\uC5D0 \uACE0\uAC1D\uC774 \uC9D1\uC911\uB418\uC5B4 \uC0AC\uACE0 \uBC1C\uC0DD \uD655\uB960\uC774 \uB192\uC544\uC9C0\uBBC0\uB85C \uADF8 \uC2DC\uAC04\uB300\uB97C \uBE48\uD2C8\uC5C6\uC774 \uB179\uD654\uD558\uB294 \uAC83\uC774 \uC911\uC694\uD569\uB2C8\uB2E4.", "\uB9E4\uC7A5\uC5D0\uC11C CCTV\uC758 \uC5ED\uD560\uC740 \uB2E8\uC21C \uBCF4\uC548\uC744 \uB118\uC5B4 \uC6B4\uC601 \uAD00\uB9AC \uB3C4\uAD6C\uB85C \uD655\uC7A5\uB429\uB2C8\uB2E4. \uACE0\uAC1D \uB3D9\uC120\uC744 \uBD84\uC11D\uD558\uBA74 \uB9E4\uC7A5 \uB808\uC774\uC544\uC6C3\uC744 \uCD5C\uC801\uD654\uD560 \uC218 \uC788\uACE0, \uC9C1\uC6D0 \uADFC\uD0DC\uC640 \uC11C\uBE44\uC2A4 \uD488\uC9C8\uC744 \uAC1D\uAD00\uC801\uC73C\uB85C \uD3C9\uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC0AC\uACE0 \uC608\uBC29\uBFD0 \uC544\uB2C8\uB77C \uB0B4\uBD80 \uAD50\uC721 \uC790\uB8CC\uB85C\uB3C4 \uD65C\uC6A9\uB429\uB2C8\uB2E4.", "\uC601\uC5C5\uC2DC\uAC04 \uC678 \uBB34\uC778 \uC2DC\uAC04\uB300\uC758 \uBCF4\uC548\uC774 \uD2B9\uD788 \uC911\uC694\uD569\uB2C8\uB2E4. \uC0C8\uBCBD\xB7\uC2EC\uC57C \uC2DC\uAC04\uB300\uC5D0 AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0\uAC00 \uC791\uB3D9\uD558\uBA74 \uC2E4\uC81C \uCE68\uC785\uACFC \uBC14\uB78C\xB7\uB3D9\uBB3C\uC744 \uAD6C\uBD84\uD558\uC5EC \uC815\uD655\uD55C \uC54C\uB9BC\uC744 \uBCF4\uB0B4\uBBC0\uB85C, \uC624\uC54C\uB9BC \uD53C\uB85C \uC5C6\uC774 \uC2E4\uC9C8\uC801\uC778 \uBCF4\uC548 \uD6A8\uACFC\uB97C \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "CCTV \uC124\uCE58 \uB9E4\uC7A5\uC740 \uD654\uC7AC\xB7\uB3C4\uB09C \uBCF4\uD5D8\uB8CC\uAC00 \uD3C9\uADE0 10~20% \uD560\uC778\uB429\uB2C8\uB2E4. \uC124\uCE58 \uBE44\uC6A9\uC744 \uBCF4\uD5D8\uB8CC \uD560\uC778\uB9CC\uC73C\uB85C\uB3C4 \uCDA9\uBD84\uD788 \uC0C1\uC1C4\uD560 \uC218 \uC788\uC5B4 \uC7A5\uAE30\uC801\uC73C\uB85C \uBD24\uC744 \uB54C \uC624\uD788\uB824 \uC774\uC775\uC785\uB2C8\uB2E4. \uBCF4\uD5D8\uC0AC \uC694\uAD6C \uC870\uAC74\uC5D0 \uB9DE\uCD98 \uCD5C\uC18C \uCC44\uB110 \uC218\uC640 \uD574\uC0C1\uB3C4\uB97C \uD655\uC778\uD558\uB294 \uAC83\uC774 \uCCAB \uB2E8\uACC4\uC785\uB2C8\uB2E4.", "\uCD5C\uADFC AI \uBD84\uC11D \uAE30\uB2A5\uC774 \uD0D1\uC7AC\uB41C \uC2A4\uB9C8\uD2B8 CCTV\uAC00 \uC8FC\uB958\uAC00 \uB418\uBA74\uC11C \uB2E8\uC21C \uB179\uD654\uC5D0\uC11C \uB2A5\uB3D9\uC801 \uBCF4\uC548\uC73C\uB85C \uD328\uB7EC\uB2E4\uC784\uC774 \uBC14\uB00C\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uC0AC\uB78C\uACFC \uCC28\uB7C9\uC744 \uAD6C\uBD84\uD558\uACE0, \uBC30\uD68C \uD328\uD134\uC744 \uD559\uC2B5\uD558\uBA70, \uC0AC\uC804 \uC124\uC815\uB41C \uC774\uC0C1\uD589\uB3D9\uC744 \uC790\uB3D9 \uAC10\uC9C0\uD574 \uC54C\uB9BC\uC744 \uBCF4\uB0C5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uC8FC\uBCC0\uC758 \uC6B0\uBC94 \uC815\uB3C4\uC640 \uC5C5\uC885 \uD2B9\uC131\uC744 \uACE0\uB824\uD55C \uCE74\uBA54\uB77C \uBC30\uCE58\uAC00 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uBC88\uD654\uAC00\xB7\uC720\uD765\uAC00 \uC778\uADFC \uB9E4\uC7A5\uC740 \uC57C\uAC04 \uD480\uCEEC\uB7EC \uCE74\uBA54\uB77C \uBE44\uC911\uC744 \uB192\uC774\uACE0, \uC8FC\uD0DD\uAC00\uB294 \uC785\uCD9C\uC785 \uAC10\uC2DC \uC704\uC8FC\uB85C \uC124\uACC4\uD558\uB294 \uAC83\uC774 \uD6A8\uC728\uC801\uC785\uB2C8\uB2E4.", "\uC608\uC0B0\uC774 \uD55C\uC815\uC801\uC774\uB77C\uBA74 \uC804\uB7B5\uC801 \uC6B0\uC120\uC21C\uC704\uAC00 \uC911\uC694\uD569\uB2C8\uB2E4. \uCD9C\uC785\uAD6C\xB7\uCE74\uC6B4\uD130\xB7\uACE0\uAC00\uD488 \uC9C4\uC5F4\uB300 \uC21C\uC11C\uB85C \uC608\uC0B0\uC744 \uBC30\uBD84\uD558\uACE0, \uB098\uBA38\uC9C0 \uAD6C\uC5ED\uC740 Full HD\uB85C \uAD6C\uC131\uD558\uBA74 \uBE44\uC6A9 \uB300\uBE44 \uD6A8\uACFC\uB97C \uADF9\uB300\uD654\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC601\uC0C1 \uC800\uC7A5 \uAE30\uAC04\uC740 \uBC95\uC801 \uC694\uAD6C\uC640 \uC5C5\uC885 \uD2B9\uC131\uC5D0 \uB530\uB77C \uB2E4\uB985\uB2C8\uB2E4. \uC77C\uBC18 \uB9E4\uC7A5\uC740 30\uC77C, \uAE08\uC735\uAE30\uAD00\uC740 \uC601\uAD6C, \uC758\uB8CC\uAE30\uAD00\uC740 \uBC95\uC815 \uBCF4\uAD00\uAE30\uAC04\uC5D0 \uB530\uB77C \uB2E4\uB974\uBBC0\uB85C \uC5C5\uC885\uBCC4 \uC694\uAC74\uC744 \uD655\uC778\uD558\uACE0 \uC800\uC7A5 \uC6A9\uB7C9\uC744 \uACB0\uC815\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC900\uC218\uAC00 \uB9E4\uC6B0 \uC911\uC694\uD55C \uC2DC\uB300\uC785\uB2C8\uB2E4. \uCD2C\uC601 \uBC94\uC704 \uC81C\uD55C, \uC548\uB0B4\uD310 \uBD80\uCC29, \uC601\uC0C1 \uC811\uADFC \uAD8C\uD55C \uAD00\uB9AC, \uC800\uC7A5 \uAE30\uAC04 \uACE0\uC9C0 \uB4F1 \uBAA8\uB4E0 \uC870\uAC74\uC744 \uC900\uC218\uD574\uC57C \uACFC\uD0DC\uB8CC\uB098 \uD615\uC0AC \uCC98\uBC8C\uC744 \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC804\uBB38 \uC5C5\uCCB4\uC758 \uCEE8\uC124\uD305\uC744 \uBC1B\uB294 \uAC83\uC774 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uCD5C\uADFC \uD074\uB77C\uC6B0\uB4DC \uAE30\uBC18 CCTV\uAC00 \uC8FC\uB958\uAC00 \uB418\uBA74\uC11C \uBB3C\uB9AC\uC801 NVR\uC774 \uACE0\uC7A5 \uB098\uB3C4 \uC601\uC0C1\uC774 \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uB418\uB294 \uAD6C\uC870\uAC00 \uD45C\uC900\uC774 \uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC124\uCE58 \uBE44\uC6A9\uC740 \uC870\uAE08 \uB354 \uB4E4\uC9C0\uB9CC \uC7A5\uAE30\uC801 \uC548\uC815\uC131\uC744 \uACE0\uB824\uD558\uBA74 \uD074\uB77C\uC6B0\uB4DC \uC635\uC158\uC744 \uC120\uD0DD\uD558\uB294 \uAC8C \uC720\uB9AC\uD569\uB2C8\uB2E4.", "\uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uC6B4\uC601\uD558\uB294 \uC0AC\uC5C5\uC790\uB77C\uBA74 \uD1B5\uD569 \uAD00\uC81C \uC2DC\uC2A4\uD15C\uC774 \uD544\uC218\uC785\uB2C8\uB2E4. \uC2A4\uB9C8\uD2B8\uD3F0 \uD558\uB098\uB85C \uC804\uAD6D \uB9E4\uC7A5\uC744 \uB3D9\uC2DC\uC5D0 \uBAA8\uB2C8\uD130\uB9C1\uD558\uACE0 \uC774\uC0C1 \uC0C1\uD669\uC744 \uC989\uC2DC \uD30C\uC545\uD560 \uC218 \uC788\uC5B4 \uB9E4\uC7A5 \uC218\uAC00 \uB9CE\uC744\uC218\uB85D \uAD00\uB9AC \uD6A8\uC728\uC774 \uADF9\uB300\uD654\uB429\uB2C8\uB2E4.", "\uD654\uC7AC \uAC10\uC9C0\uB294 CCTV\uC758 \uC228\uC740 \uC911\uC694 \uAE30\uB2A5\uC785\uB2C8\uB2E4. \uC5F0\uAE30 \uAC10\uC9C0 \uC13C\uC11C\uC640 \uC5F0\uB3D9\uB41C \uC5F4\uD654\uC0C1 \uCE74\uBA54\uB77C\uB294 \uC77C\uBC18 CCTV\uAC00 \uB193\uCE58\uB294 \uCD08\uAE30 \uD654\uC7AC\uB97C \uC870\uAE30 \uBC1C\uACAC\uD560 \uC218 \uC788\uC5B4 \uB300\uD615 \uC0AC\uACE0\uB85C \uBC88\uC9C0\uAE30 \uC804 \uB300\uC751\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "AI\uAC00 \uC0AC\uB78C\uACFC \uBB3C\uCCB4\uB97C \uAD6C\uBD84\uD558\uB294 \uB2A5\uB825\uC774 \uCD5C\uADFC \uAE09\uACA9\uD788 \uBC1C\uC804\uD588\uC2B5\uB2C8\uB2E4. \uC624\uD0D0\uC9C0\uC728\uC774 90% \uC774\uC0C1 \uAC10\uC18C\uD558\uBA74\uC11C \uC2E4\uC81C \uC911\uC694\uD55C \uC54C\uB9BC\uB9CC \uBC1B\uC744 \uC218 \uC788\uAC8C \uB418\uC5C8\uACE0, \uC774\uB294 \uB9E4\uC7A5 \uAD00\uB9AC\uC790\uC758 \uD53C\uB85C\uB3C4\uB97C \uD06C\uAC8C \uB0AE\uCD94\uB294 \uBCC0\uD654\uC785\uB2C8\uB2E4.", "\uCE74\uBA54\uB77C \uD654\uAC01\uC740 \uC5C5\uC885\uACFC \uACF5\uAC04\uC5D0 \uB530\uB77C \uC138\uC2EC\uD558\uAC8C \uC120\uD0DD\uD574\uC57C \uD569\uB2C8\uB2E4. \uC881\uC740 \uACC4\uC0B0\uB300\uB294 \uD45C\uC900 \uB80C\uC988, \uB113\uC740 \uD640\uC740 \uC640\uC774\uB4DC \uB80C\uC988, \uC6D0\uAC70\uB9AC \uC8FC\uCC28\uC7A5\uC740 \uC90C \uB80C\uC988\uAC00 \uC801\uD569\uD558\uBA70 \uD63C\uC6A9 \uC124\uACC4\uAC00 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4.", "\uC800\uC870\uB3C4 \uD658\uACBD \uCD2C\uC601 \uC131\uB2A5\uC774 \uCD5C\uADFC \uAE30\uC220\uC758 \uD575\uC2EC \uACBD\uC7C1 \uD3EC\uC778\uD2B8\uC785\uB2C8\uB2E4. 0.01lux \uC218\uC900\uC5D0\uC11C\uB3C4 \uD480\uCEEC\uB7EC \uCD2C\uC601\uC774 \uAC00\uB2A5\uD55C \uBAA8\uB378\uC774 \uB4F1\uC7A5\uD558\uBA74\uC11C \uC678\uBD80 \uC870\uBA85 \uC5C6\uC774\uB3C4 \uC57C\uAC04 \uC120\uBA85\uD55C \uC601\uC0C1 \uD655\uBCF4\uAC00 \uAC00\uB2A5\uD574\uC84C\uC2B5\uB2C8\uB2E4.", "\uB124\uD2B8\uC6CC\uD06C \uBCF4\uC548\uB3C4 \uC911\uC694\uD55C \uACE0\uB824\uC0AC\uD56D\uC785\uB2C8\uB2E4. CCTV\uAC00 \uD574\uD0B9\uB418\uBA74 \uC0AC\uC0DD\uD65C \uC720\uCD9C\uC740 \uBB3C\uB860 \uB0B4\uBD80 \uB124\uD2B8\uC6CC\uD06C \uCE68\uC785 \uACBD\uB85C\uAC00 \uB420 \uC218 \uC788\uC73C\uBBC0\uB85C, \uAC15\uB825\uD55C \uC554\uD638\uC640 \uC815\uAE30 \uD38C\uC6E8\uC5B4 \uC5C5\uB370\uC774\uD2B8, VPN \uC5F0\uACB0\uC774 \uD544\uC218\uC785\uB2C8\uB2E4.", "\uC6D0\uACA9 \uAD00\uB9AC\uC758 \uD3B8\uB9AC\uD568\uACFC \uBCF4\uC548\uC758 \uADE0\uD615\uC774 \uD575\uC2EC\uC785\uB2C8\uB2E4. \uD074\uB77C\uC6B0\uB4DC \uC5F0\uACB0\uC774 \uD3B8\uB9AC\uD558\uC9C0\uB9CC \uD574\uD0B9 \uC704\uD5D8\uC774 \uC788\uACE0, \uD3D0\uC1C4 \uB124\uD2B8\uC6CC\uD06C\uAC00 \uC548\uC804\uD558\uC9C0\uB9CC \uAD00\uB9AC\uAC00 \uBD88\uD3B8\uD569\uB2C8\uB2E4. \uC5C5\uC885\uBCC4 \uD2B9\uC131\uC5D0 \uB9DE\uB294 \uC808\uCDA9\uC810\uC744 \uCC3E\uB294 \uAC83\uC774 \uC911\uC694\uD569\uB2C8\uB2E4.", "\uC5BC\uAD74 \uC778\uC2DD \uAE30\uB2A5\uC774 \uBC95\uC801 \uADDC\uC81C\uB85C \uC81C\uD55C\uB418\uB294 \uCD94\uC138\uC774\uC9C0\uB9CC, \uB0B4\uBD80 \uC9C1\uC6D0 \uCD9C\uC785 \uAD00\uB9AC \uAC19\uC740 \uC81C\uD55C\uC801 \uC6A9\uB3C4\uB85C\uB294 \uD65C\uC6A9\uB3C4\uAC00 \uB9E4\uC6B0 \uB192\uC2B5\uB2C8\uB2E4. \uCD9C\uC785 \uD1B5\uC81C\uC640 \uACB0\uD569\uD558\uBA74 \uBCF4\uC548 \uD6A8\uACFC\uAC00 \uADF9\uB300\uD654\uB429\uB2C8\uB2E4.", "CCTV\uB294 \uB2E8\uC21C \uC0AC\uACE0 \uB300\uC751 \uB3C4\uAD6C\uAC00 \uC544\uB2CC \uB9E4\uC7A5 \uC6B4\uC601\uC758 \uD575\uC2EC \uC778\uD504\uB77C\uC785\uB2C8\uB2E4. \uACE0\uAC1D \uD589\uB3D9 \uBD84\uC11D, \uD53C\uD06C\uD0C0\uC784 \uD30C\uC545, \uC0C1\uD488 \uBC30\uCE58 \uCD5C\uC801\uD654\uAE4C\uC9C0 \uB370\uC774\uD130 \uAE30\uBC18 \uC6B4\uC601\uC73C\uB85C \uD655\uC7A5\uB418\uBA74 \uB9E4\uCD9C \uC0C1\uC2B9\uC5D0\uB3C4 \uAE30\uC5EC\uD569\uB2C8\uB2E4.", "\uAD6D\uB0B4 CCTV \uC2DC\uC7A5\uC740 \uC911\uAD6D\uC0B0 \uC800\uAC00\uD488\uACFC \uAD6D\uC0B0 \uD504\uB9AC\uBBF8\uC5C4\uC73C\uB85C \uC591\uADF9\uD654\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC800\uAC00\uD488\uC740 \uCD08\uAE30 \uBE44\uC6A9\uC740 \uC800\uB834\uD558\uC9C0\uB9CC 1~2\uB144 \uB0B4 \uACE0\uC7A5\uB960\uC774 \uB192\uACE0 A/S\uAC00 \uC5B4\uB824\uC6CC \uC7A5\uAE30\uC801\uC73C\uB85C \uBD88\uB9AC\uD569\uB2C8\uB2E4.", "\uB179\uD654 \uD574\uC0C1\uB3C4\uAC00 \uB192\uC744\uC218\uB85D \uC800\uC7A5 \uC6A9\uB7C9\uC774 \uD06C\uAC8C \uB298\uC5B4\uB0A9\uB2C8\uB2E4. 4K 24\uC2DC\uAC04 \uB179\uD654\uB294 2TB\uB85C \uC57D 15\uC77C \uBD84\uB7C9\uC774\uBBC0\uB85C \uD544\uC694 \uBCF4\uAD00 \uAE30\uAC04\uC5D0 \uB9DE\uCDB0 \uC6A9\uB7C9\uC744 \uACC4\uC0B0\uD574\uC57C \uC911\uAC04\uC5D0 \uC800\uC7A5 \uACF5\uAC04 \uBD80\uC871 \uBB38\uC81C\uAC00 \uC0DD\uAE30\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4."], 0) + "</p>";
  body += '<h2 style="color:' + mc + '">\u{1F4F9} ' + biz + " CCTV\uAC00 \uD544\uC694\uD55C \uC774\uC720</h2><p>" + biz + "\uC758 \uD575\uC2EC \uAC10\uC2DC \uD3EC\uC778\uD2B8\uB294 " + cc.spot + "\uC785\uB2C8\uB2E4. " + cc.cam + " \uAD6C\uC131\uC73C\uB85C \uC0AC\uAC01\uC9C0\uB300 \uC5C6\uC774 \uCEE4\uBC84\uD558\uB294 \uAC83\uC774 \uAE30\uBCF8\uC774\uBA70, \uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4 \uC804\uBB38 \uAE30\uC0AC\uAC00 " + biz + " \uB9E4\uC7A5\uC744 \uC9C1\uC811 \uBC29\uBB38\uD558\uC5EC \uCE74\uBA54\uB77C \uC704\uCE58\uB97C \uC124\uACC4\uD569\uB2C8\uB2E4. " + ci.tip + "</p>";
  body += rv(biz + " \uC0AC\uC7A5\uB2D8", 5, ci.review);
  body += rv(biz + " \uC0AC\uC7A5\uB2D8 B", 5, s(["CCTV \uC124\uCE58 \uD6C4 \uC9C1\uC6D0\uB4E4\uC774 \uB354 \uAE34\uC7A5\uAC10\uC744 \uAC16\uACE0 \uC77C\uD574\uC11C \uC11C\uBE44\uC2A4 \uD488\uC9C8\uC774 \uC62C\uB77C\uAC14\uC5B4\uC694. \uACE0\uAC1D \uC751\uB300\uB3C4 \uAC1C\uC120\uB418\uACE0, \uB9E4\uC7A5 \uBD84\uC704\uAE30\uAC00 \uC804\uCCB4\uC801\uC73C\uB85C \uC88B\uC544\uC84C\uC2B5\uB2C8\uB2E4.", "\uC57C\uAC04\uC5D0 \uC571\uC73C\uB85C \uB9E4\uC7A5\uC744 \uD655\uC778\uD560 \uC218 \uC788\uC73C\uB2C8 \uC548\uC2EC\uC774 \uB429\uB2C8\uB2E4. \uC774\uC804\uC5D0\uB294 \uD1F4\uADFC \uD6C4\uC5D0\uB3C4 \uAC71\uC815\uC774\uC5C8\uB294\uB370, \uC774\uC81C\uB294 \uC571 \uD55C \uBC88\uC774\uBA74 \uB05D\uC774\uC5D0\uC694.", "\uBCF4\uD5D8 \uAC31\uC2E0\uD560 \uB54C CCTV \uC124\uCE58 \uC99D\uBE59\uC744 \uB0B4\uB2C8\uAE4C \uBCF4\uD5D8\uB8CC\uAC00 15% \uD560\uC778\uB410\uC5B4\uC694. 1\uB144\uC774\uBA74 \uC124\uCE58\uBE44\uC758 \uC808\uBC18\uC744 \uD68C\uC218\uD55C \uC148\uC785\uB2C8\uB2E4.", "\uCC98\uC74C\uC5D0\uB294 \uBE44\uC6A9\uC774 \uC544\uAE4C\uC6B4 \uC0DD\uAC01\uC774\uC5C8\uB294\uB370 \uC124\uCE58 \uD6C4 2\uB2EC \uB9CC\uC5D0 \uB3C4\uB09C 2\uAC74\uC744 \uB9C9\uC73C\uBA74\uC11C \uD22C\uC790\uAE08\uC744 \uD68C\uC218\uD588\uC5B4\uC694. \uB9E4\uCD9C \uC9C1\uACB0\uB418\uB294 \uBB38\uC81C\uB77C \uBE60\uB974\uAC8C \uCCB4\uAC10\uD569\uB2C8\uB2E4.", "\uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1\uC774 \uC774\uB807\uAC8C \uD3B8\uD560 \uC904 \uBAB0\uB790\uC2B5\uB2C8\uB2E4. \uD574\uC678 \uCD9C\uC7A5 \uC911\uC5D0\uB3C4 \uB9E4\uC7A5 \uC0C1\uD669\uC744 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uD655\uC778\uD560 \uC218 \uC788\uC5B4 \uC0AC\uC5C5 \uD655\uC7A5\uC5D0 \uC790\uC2E0\uAC10\uC774 \uBD99\uC5C8\uC5B4\uC694.", "AI \uC774\uC0C1\uD589\uB3D9 \uAC10\uC9C0\uAC00 \uAE30\uB300 \uC774\uC0C1\uC785\uB2C8\uB2E4. \uC0AC\uB78C \uAC10\uC9C0\uB9CC \uC791\uB3D9\uD574\uC11C \uC608\uC804\uCC98\uB7FC \uBC14\uB78C\uC5D0 \uD754\uB4E4\uB9AC\uB294 \uB098\uBB47\uAC00\uC9C0 \uC54C\uB9BC\uC774 \uC548 \uC624\uB2C8\uAE4C \uC911\uC694\uD55C \uC54C\uB9BC\uB9CC \uD655\uC778\uD558\uBA74 \uB418\uC5B4\uC11C \uD3B8\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uAE30\uC0AC\uBD84\uC774 \uC5C5\uC885 \uB9DE\uCDA4\uC73C\uB85C \uCE74\uBA54\uB77C\uB97C \uBC30\uCE58\uD574 \uC8FC\uC168\uC5B4\uC694. \uC81C\uAC00 \uD3C9\uC18C \uB193\uCE58\uB358 \uC0AC\uAC01\uC9C0\uB300\uAE4C\uC9C0 \uAF3C\uAF3C\uD788 \uCC59\uACA8\uC8FC\uC154\uC11C 10\uB144 \uACBD\uB825\uC758 \uB178\uD558\uC6B0\uAC00 \uB290\uAEF4\uC84C\uC2B5\uB2C8\uB2E4.", "4K \uD654\uC9C8\uC774 \uC774\uB807\uAC8C \uB2E4\uB978\uC9C0 \uBAB0\uB790\uC5B4\uC694. \uC774\uC804 Full HD \uCE74\uBA54\uB77C\uB85C\uB294 \uBC88\uD638\uD310\uC774 \uD750\uB9BF\uD574\uC11C \uC54C\uC544\uBCFC \uC218 \uC5C6\uC5C8\uB294\uB370, 4K\uB85C \uBC14\uAFB8\uB2C8 \uC120\uBA85\uD558\uAC8C \uBCF4\uC5EC\uC11C \uC8FC\uCC28 \uBD84\uC7C1\uC774 \uC0AC\uB77C\uC84C\uC2B5\uB2C8\uB2E4.", "\uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5 \uAE30\uB2A5\uC774 \uACB0\uC815\uC801\uC774\uC5C8\uC5B4\uC694. \uB9E4\uC7A5 NVR\uC774 \uB3C4\uB09C\uB2F9\uD55C \uC0AC\uAC74\uC5D0\uC11C\uB3C4 \uD074\uB77C\uC6B0\uB4DC\uC5D0 \uC601\uC0C1\uC774 \uB0A8\uC544\uC788\uC5B4\uC11C \uACBD\uCC30 \uC218\uC0AC\uC5D0 \uBC14\uB85C \uC81C\uACF5\uD560 \uC218 \uC788\uC5C8\uC2B5\uB2C8\uB2E4.", "\uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95\uC5D0 \uB9DE\uB294 \uC548\uB0B4\uD310\uACFC \uC124\uC815\uAE4C\uC9C0 \uD55C \uBC88\uC5D0 \uD574\uC8FC\uC168\uC5B4\uC694. \uBC95\uC801 \uC774\uC288\uB85C \uACFC\uD0DC\uB8CC \uAC71\uC815\uD558\uC9C0 \uC54A\uC544\uB3C4 \uB418\uB2C8\uAE4C \uB9C8\uC74C\uC774 \uD3B8\uD569\uB2C8\uB2E4.", "\uB2E4\uC9C0\uC810 \uC6B4\uC601\uC5D0\uC11C \uD1B5\uD569 \uAD00\uC81C\uAC00 \uB108\uBB34 \uC720\uC6A9\uD569\uB2C8\uB2E4. \uC804\uAD6D 5\uAC1C \uB9E4\uC7A5\uC744 \uD55C \uD654\uBA74\uC5D0\uC11C \uBCF4\uACE0 \uC788\uC73C\uB2C8 \uC774\uC0C1 \uC9D5\uD6C4\uB97C \uBE60\uB974\uAC8C \uD30C\uC545\uD560 \uC218 \uC788\uC5B4 \uC6B4\uC601\uC774 \uCCB4\uACC4\uC801\uC774 \uB410\uC5B4\uC694.", "\uC9C1\uC6D0 \uBD84\uC7C1\uC774 \uC788\uC744 \uB54C\uB9C8\uB2E4 CCTV\uAC00 \uC99D\uC778 \uC5ED\uD560\uC744 \uD574\uC694. \uAC10\uC815\uC801 \uB300\uB9BD \uC5C6\uC774 \uC601\uC0C1\uC744 \uD568\uAED8 \uBCF4\uACE0 \uD574\uACB0\uD558\uB2C8\uAE4C \uC11C\uB85C \uC218\uAE0D\uD558\uB294 \uBD84\uC704\uAE30\uAC00 \uB410\uC2B5\uB2C8\uB2E4.", "\uC5F4\uD654\uC0C1 \uCE74\uBA54\uB77C\uAC00 \uC788\uC73C\uB2C8 \uC8FC\uBC29 \uD654\uC7AC \uC704\uD5D8\uC744 \uC0AC\uC804\uC5D0 \uAC10\uC9C0\uD560 \uC218 \uC788\uC5B4\uC694. \uC791\uC740 \uD654\uC7AC\uB97C \uCD08\uAE30 \uC9C4\uC555\uD55C \uACBD\uD5D8\uC774 \uC788\uC5B4 \uC124\uCE58 \uAC00\uCE58\uB97C 100% \uCCB4\uAC10\uD569\uB2C8\uB2E4.", "\uCD9C\uC785 \uD1B5\uC81C\uC640 \uC5F0\uB3D9\uD558\uB2C8 \uB204\uAC00 \uC5B8\uC81C \uB4E4\uC5B4\uC654\uB294\uC9C0 \uC790\uB3D9 \uAE30\uB85D\uB429\uB2C8\uB2E4. \uC11C\uB958 \uAD00\uB9AC\uAC00 \uC5C4\uACA9\uD55C \uC0AC\uBB34\uC2E4\uC778\uB370 \uC774 \uAE30\uB2A5\uC73C\uB85C \uB0B4\uBD80 \uAC10\uC0AC\uAC00 \uC218\uC6D4\uD574\uC84C\uC5B4\uC694.", "\uC2A4\uB9C8\uD2B8\uD3F0 \uC571 \uC0AC\uC6A9\uC774 \uC9C1\uAD00\uC801\uC774\uB77C 70\uB300\uC774\uC2E0 \uC5B4\uBA38\uB2C8\uB3C4 \uC4F0\uC2E4 \uC218 \uC788\uC5B4\uC694. \uB9E4\uC7A5 \uD558\uB098 \uC6B4\uC601\uD558\uC2DC\uB294\uB370 \uC774\uC81C \uC81C\uAC8C \uC804\uD654 \uC548 \uD558\uC2DC\uACE0 \uC9C1\uC811 \uD655\uC778\uD558\uC2ED\uB2C8\uB2E4.", "\uC57C\uAC04 \uD480\uCEEC\uB7EC \uAE30\uB2A5\uC774 \uC9C4\uC9DC \uC138\uC0C1\uC774 \uB2EC\uB77C\uC84C\uC5B4\uC694. \uC870\uBA85 \uC5C6\uC774\uB3C4 \uC637 \uC0C9\uAE54\uAE4C\uC9C0 \uAD6C\uBD84\uB418\uB2C8\uAE4C \uBC94\uC778 \uD2B9\uC815\uC774 \uD6E8\uC52C \uC26C\uC6CC\uC84C\uC2B5\uB2C8\uB2E4.", "\uC6D0\uACA9 \uD38C\uC6E8\uC5B4 \uC5C5\uB370\uC774\uD2B8\uAC00 \uC790\uB3D9\uC73C\uB85C \uB3FC\uC11C \uAD00\uB9AC \uBD80\uB2F4\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uC124\uCE58\uB9CC \uD574\uB450\uBA74 \uC2DC\uC2A4\uD15C\uC774 \uC54C\uC544\uC11C \uCD5C\uC2E0 \uC0C1\uD0DC\uB85C \uC720\uC9C0\uB418\uC5B4 \uC2E0\uACBD \uC4F8 \uAC8C \uC5C6\uC5B4\uC694.", "\uC5BC\uAD74 \uC778\uC2DD \uCD9C\uC785 \uC2DC\uC2A4\uD15C\uACFC \uC5F0\uB3D9\uD558\uB2C8 \uC77C\uC77C \uAD00\uB9AC \uB300\uC7A5\uC774 \uC790\uB3D9\uC73C\uB85C \uB9CC\uB4E4\uC5B4\uC838\uC694. \uC885\uC774 \uAD00\uB9AC \uB300\uC7A5 \uC2DC\uB300\uB294 \uC774\uC81C \uC644\uC804\uD788 \uB05D\uB09C \uAC83 \uAC19\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uBC16 \uAC70\uB9AC\uAE4C\uC9C0 \uC77C\uBD80 \uCD2C\uC601\uB418\uB2C8\uAE4C \uC8FC\uBCC0 \uC0AC\uACE0\uB3C4 \uC99D\uAC70 \uC81C\uACF5\uC774 \uAC00\uB2A5\uD588\uC5B4\uC694. \uD55C\uBC88\uC740 \uC774\uC6C3 \uB9E4\uC7A5 \uB3C4\uB09C \uC0AC\uAC74\uC5D0 \uB3C4\uC6C0\uC744 \uB4DC\uB9AC\uBA74\uC11C \uC0C1\uAD8C \uC548\uC804\uC5D0 \uAE30\uC5EC\uD558\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uD6C4 1\uB144 \uB3D9\uC548 \uD55C \uBC88\uB3C4 \uB9D0\uC37D \uC5C6\uC774 \uC798 \uB3CC\uC544\uAC00\uACE0 \uC788\uC5B4\uC694. \uCD08\uAE30 \uC124\uCE58\uB97C \uC798 \uD558\uBA74 \uC774\uD6C4 \uAD00\uB9AC\uAC00 \uC5C6\uB2E4\uB294 \uB9D0\uC774 \uB9DE\uB124\uC694."], 3));
  body += '<h2 style="color:' + mc + '">\u{1F4CA} ' + biz + " CCTV \uCD94\uCC9C \uAD6C\uC131</h2><p>" + biz + js(biz, "\uC774", "\uAC00") + " " + cc.area + " \uADDC\uBAA8\uB77C\uBA74 " + cc.cam + " \uAD6C\uC131\uC774 \uC801\uD569\uD569\uB2C8\uB2E4. " + s(["Full HD \uCE74\uBA54\uB77C\uB294 5m \uC774\uB0B4 \uC5BC\uAD74 \uC2DD\uBCC4\uC774 \uAC00\uB2A5\uD558\uBA70, \uB113\uC740 \uACF5\uAC04\uC740 4K\uB97C \uD63C\uC6A9\uD558\uBA74 \uBC88\uD638\uD310\uAE4C\uC9C0 \uAE30\uB85D\uB429\uB2C8\uB2E4. NVR 2TB \uC774\uC0C1\uC774\uBA74 30\uC77C \uC5F0\uC18D \uB179\uD654\uAC00 \uAC00\uB2A5\uD558\uBA70, \uC911\uC694 \uAD6C\uAC04\uC740 \uBCC4\uB3C4 \uBC31\uC5C5\uD558\uC5EC \uC7A5\uAE30 \uBCF4\uAD00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0 \uAE30\uB2A5\uC740 \uC0AC\uB78C\uB9CC \uC120\uBCC4\uD558\uC5EC \uC54C\uB9BC\uC744 \uBCF4\uB0B4\uBBC0\uB85C \uBC14\uB78C\xB7\uB3D9\uBB3C\uC5D0 \uC758\uD55C \uC624\uC791\uB3D9\uC774 \uD06C\uAC8C \uC904\uC5B4\uB4ED\uB2C8\uB2E4. \uC601\uC5C5 \uC885\uB8CC \uD6C4 \uC2E4\uC81C \uCE68\uC785\uB9CC \uD3EC\uCC29\uD574 \uC54C\uB9BC \uD53C\uB85C\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.", "\uC720\uC120(PoE) \uCE74\uBA54\uB77C\uB294 \uC548\uC815\uC801\uC774\uACE0 \uB04A\uAE40\uC774 \uC5C6\uC5B4 \uACE0\uC815 \uB9E4\uC7A5\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4. \uC57C\uAC04 \uD480\uCEEC\uB7EC \uCE74\uBA54\uB77C\uB294 \uC870\uBA85 \uC5C6\uC774\uB3C4 \uC637 \uC0C9\uC0C1\uACFC \uC778\uC0C1\uCC29\uC758\uB97C \uAE30\uB85D\uD569\uB2C8\uB2E4.", "\uB3D4\uD615 \uCE74\uBA54\uB77C\uB294 \uB0B4\uBD80 \uACF5\uAC04\uC5D0 \uC801\uD569\uD558\uACE0 360\uB3C4 \uCD2C\uC601\uC774 \uAC00\uB2A5\uD574 \uB113\uC740 \uACF5\uAC04 \uD55C \uB300\uB85C\uB3C4 \uCDA9\uBD84\uD569\uB2C8\uB2E4. \uC678\uBD80\uB098 \uC8FC\uCC28\uC7A5 \uAC19\uC740 \uB113\uC740 \uACF5\uAC04\uC740 \uBD88\uB9BF\uD615 \uCE74\uBA54\uB77C\uAC00 \uC801\uD569\uD574 \uC6D0\uAC70\uB9AC \uAC10\uC2DC\uC5D0 \uC720\uB9AC\uD569\uB2C8\uB2E4.", "\uC800\uC870\uB3C4 \uACE0\uC131\uB2A5 \uBAA8\uB378(STARVIS \uC13C\uC11C \uC774\uC0C1)\uC740 \uC870\uBA85\uC774 \uC5B4\uB450\uC6B4 \uD658\uACBD\uC5D0\uC11C\uB3C4 \uC120\uBA85\uD55C \uC601\uC0C1\uC744 \uD655\uBCF4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCC3D\uACE0\xB7\uC8FC\uCC28\uC7A5\xB7\uC57C\uC678 \uB4F1 \uC800\uC870\uB3C4 \uD658\uACBD\uC774 \uB9CE\uC740 \uACF3\uC5D0 \uD544\uC218 \uAE30\uB2A5\uC785\uB2C8\uB2E4.", "\uBC29\uC218\xB7\uBC29\uC9C4 \uB4F1\uAE09(IP67 \uC774\uC0C1) \uCE74\uBA54\uB77C\uB294 \uC2E4\uC678 \uC124\uCE58 \uC2DC \uD544\uC218\uC785\uB2C8\uB2E4. \uBE44\xB7\uB208\xB7\uBA3C\uC9C0\uC5D0 \uB178\uCD9C\uB418\uB294 \uD658\uACBD\uC5D0\uC11C\uB3C4 \uBA87 \uB144\uAC04 \uC548\uC815\uC801\uC73C\uB85C \uC791\uB3D9\uD558\uBBC0\uB85C \uC7A5\uAE30\uC801 \uAD00\uC810\uC5D0\uC11C \uD22C\uC790 \uAC00\uCE58\uAC00 \uB192\uC2B5\uB2C8\uB2E4.", "POE \uC2A4\uC704\uCE58\uC640 NVR\uC758 \uD638\uD658\uC131\uC774 \uC911\uC694\uD569\uB2C8\uB2E4. \uB3D9\uC77C \uC81C\uC870\uC0AC \uC81C\uD488\uC73C\uB85C \uAD6C\uC131\uD558\uBA74 \uD38C\uC6E8\uC5B4 \uC5C5\uB370\uC774\uD2B8 \uC2DC \uCDA9\uB3CC\uC774 \uC5C6\uACE0, \uD0C0\uC0AC \uC81C\uD488 \uD63C\uC6A9 \uC2DC \uD2B9\uC815 \uAE30\uB2A5\uC774 \uC81C\uD55C\uB420 \uC218 \uC788\uC73C\uB2C8 \uC2E0\uC911\uD55C \uC120\uD0DD\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uD074\uB77C\uC6B0\uB4DC \uB179\uD654 \uC635\uC158\uC740 NVR \uACE0\uC7A5\uC774\uB098 \uB3C4\uB09C\uC5D0 \uB300\uBE44\uD55C \uC774\uC911 \uBC31\uC5C5\uC785\uB2C8\uB2E4. \uC6D4 1~3\uB9CC\uC6D0\uC758 \uCD94\uAC00 \uBE44\uC6A9\uC774\uC9C0\uB9CC \uC911\uC694 \uC601\uC0C1 \uC190\uC2E4\uC744 \uC6D0\uCC9C \uCC28\uB2E8\uD560 \uC218 \uC788\uC5B4 \uB9AC\uC2A4\uD06C \uAD00\uB9AC \uCC28\uC6D0\uC5D0\uC11C \uCD94\uCC9C\uB429\uB2C8\uB2E4.", "16\uCC44\uB110 \uC774\uC0C1 \uB300\uADDC\uBAA8 \uC2DC\uC2A4\uD15C\uC740 NVR \uC5EC\uB7EC \uB300\uB97C VMS(Video Management System)\uB85C \uD1B5\uD569 \uAD00\uB9AC\uD558\uB294 \uAC83\uC774 \uD6A8\uC728\uC801\uC785\uB2C8\uB2E4. \uB2E8\uC77C \uD654\uBA74\uC5D0\uC11C \uC804\uCCB4 \uAD00\uC81C\uAC00 \uAC00\uB2A5\uD574\uC9C0\uACE0 \uC601\uC0C1 \uAC80\uC0C9\uB3C4 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uCE74\uBA54\uB77C \uB80C\uC988 \uCD08\uC810\uAC70\uB9AC \uC120\uD0DD\uC740 \uC911\uC694\uD55C \uACE0\uB824\uC0AC\uD56D\uC785\uB2C8\uB2E4. 2.8mm \uC640\uC774\uB4DC\uB294 \uC881\uC740 \uACF5\uAC04\uC5D0 \uC801\uD569\uD558\uACE0, 3.6mm \uD45C\uC900\uC740 \uC77C\uBC18 \uB9E4\uC7A5, 6~12mm \uB9DD\uC6D0\uC740 \uC6D0\uAC70\uB9AC \uAC10\uC2DC\uC5D0 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.", "\uC2A4\uB9C8\uD2B8\uD3F0 \uC571 \uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1\uC774 \uD45C\uC900 \uAE30\uB2A5\uC774 \uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC544\uC774\uD3F0\xB7\uC548\uB4DC\uB85C\uC774\uB4DC \uBAA8\uB450 \uC9C0\uC6D0\uD558\uBA70 \uC5EC\uB7EC \uB9E4\uC7A5\uC744 \uB3D9\uC2DC\uC5D0 \uAD00\uC81C\uD558\uB294 \uAE30\uB2A5\uB3C4 \uAE30\uBCF8 \uD0D1\uC7AC\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.", "\uC5BC\uAD74 \uC778\uC2DD \uAE30\uB2A5 \uD0D1\uC7AC \uCE74\uBA54\uB77C\uB294 \uCD9C\uC785 \uAD00\uB9AC\uC5D0 \uC720\uC6A9\uD558\uC9C0\uB9CC, \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC81C\uC57D\uC73C\uB85C \uCD2C\uC601 \uBC94\uC704\uC640 \uC0AC\uC6A9 \uBAA9\uC801\uC774 \uC81C\uD55C\uB429\uB2C8\uB2E4. \uB0B4\uBD80 \uC9C1\uC6D0 \uAD00\uB9AC \uC6A9\uB3C4 \uB4F1 \uC81C\uD55C\uC801\uC73C\uB85C\uB9CC \uD65C\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "\uC5F4\uD654\uC0C1 \uCE74\uBA54\uB77C\uB294 \uD654\uC7AC \uC608\uBC29\uC5D0 \uD0C1\uC6D4\uD569\uB2C8\uB2E4. \uC77C\uBC18 \uC870\uB9AC \uC628\uB3C4\uC640 \uD654\uC7AC \uCD08\uAE30 \uC628\uB3C4\uB97C \uAD6C\uBD84\uD558\uC5EC \uC54C\uB9BC\uC744 \uBCF4\uB0B4\uBBC0\uB85C \uC8FC\uBC29\uC774 \uC788\uB294 \uC5C5\uC885\uC5D0\uB294 \uD22C\uC790 \uAC00\uCE58\uAC00 \uD2B9\uD788 \uD07D\uB2C8\uB2E4.", "360\uB3C4 \uD30C\uB178\uB77C\uB9C8 \uCE74\uBA54\uB77C\uB294 1\uB300\uB85C 4\uB300 \uBAAB\uC744 \uD560 \uC218 \uC788\uC5B4 \uACF5\uAC04 \uB300\uBE44 \uBE44\uC6A9 \uD6A8\uC728\uC774 \uC6B0\uC218\uD569\uB2C8\uB2E4. \uAD6C\uC870\uC0C1 \uC0AC\uAC01\uC9C0\uB300\uAC00 \uAC70\uC758 \uC5C6\uC5B4 \uBD80\uC815\uD655\uD55C \uBC30\uCE58\uB3C4 \uC6A9\uB0A9\uB429\uB2C8\uB2E4.", "\uB179\uD654 \uD574\uC0C1\uB3C4\uB294 \uD544\uC694\uC5D0 \uB9DE\uAC8C \uC120\uD0DD\uD574\uC57C \uD569\uB2C8\uB2E4. \uC77C\uBC18 \uAD00\uC81C\uC6A9\uC740 1080p, \uC5BC\uAD74 \uC2DD\uBCC4 \uD544\uC694 \uC2DC 4K, \uBC88\uD638\uD310 \uC778\uC2DD\uC740 4K\uC5D0 \uBC88\uD638\uD310 \uC778\uC2DD \uAE30\uB2A5\uC774 \uD0D1\uC7AC\uB41C \uC804\uC6A9 \uBAA8\uB378\uC774 \uC801\uD569\uD569\uB2C8\uB2E4.", "CCTV\uC640 POS \uC5F0\uB3D9 \uC2DC\uC2A4\uD15C\uC740 \uC18C\uB9E4\uC5C5\uC5D0 \uD2B9\uD788 \uC720\uC6A9\uD569\uB2C8\uB2E4. \uACB0\uC81C \uAC74\uBCC4\uB85C \uC601\uC0C1\uC774 \uC790\uB3D9 \uB9E4\uCE6D\uB418\uC5B4 \uACB0\uC81C \uC624\uB958\uB098 \uBD80\uC815 \uAC70\uB798 \uD655\uC778\uC774 \uC989\uC2DC \uAC00\uB2A5\uD574\uC9D1\uB2C8\uB2E4.", "\uC57C\uAC04 \uD480\uCEEC\uB7EC \uCE74\uBA54\uB77C\uB294 \uC77C\uBC18 \uD751\uBC31 \uC57C\uAC04 \uCD2C\uC601\uBCF4\uB2E4 \uD6E8\uC52C \uC720\uC6A9\uD569\uB2C8\uB2E4. \uC637 \uC0C9\uC0C1, \uD53C\uBD80\uC0C9 \uB4F1\uC744 \uAD6C\uBD84\uD560 \uC218 \uC788\uC5B4 \uBC94\uC778 \uD2B9\uC815\uC774 \uD6E8\uC52C \uC26C\uC6CC\uC9D1\uB2C8\uB2E4. \uC124\uCE58 \uAC00\uACA9 \uCC28\uC774\uAC00 \uAC70\uC758 \uC5C6\uC5B4\uC838 \uD45C\uC900\uC774 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", "\uB3D9\uC791 \uAC10\uC9C0 + \uC774\uC0C1\uD589\uB3D9 \uAC10\uC9C0 AI\uB294 \uBCC4\uAC1C\uC758 \uAE30\uC220\uC785\uB2C8\uB2E4. \uB3D9\uC791 \uAC10\uC9C0\uB294 \uC6C0\uC9C1\uC784\uB9CC \uD3EC\uCC29\uD558\uC9C0\uB9CC, \uC774\uC0C1\uD589\uB3D9 \uAC10\uC9C0\uB294 '\uBC30\uD68C\xB7\uC8FC\uC800\uC549\uC74C\xB7\uC4F0\uB7EC\uC9D0' \uAC19\uC740 \uBCF5\uC7A1\uD55C \uD328\uD134\uC744 \uBD84\uC11D\uD569\uB2C8\uB2E4.", "NVR \uC800\uC7A5 \uC6A9\uB7C9\uC740 \uD544\uC694 \uB179\uD654 \uAE30\uAC04\uACFC \uD574\uC0C1\uB3C4\uB97C \uACF1\uD574 \uACC4\uC0B0\uD569\uB2C8\uB2E4. \uC77C\uBC18\uC801\uC73C\uB85C \uCC44\uB110 \uC218 \xD7 \uC77C\uBCC4 \uC6A9\uB7C9 \xD7 \uB179\uD654 \uAE30\uAC04\uC774\uBA70, \uC5EC\uC720\uBD84\uC744 30% \uB354 \uD655\uBCF4\uD558\uB294 \uAC83\uC774 \uC548\uC804\uD569\uB2C8\uB2E4.", "\uBC31\uC5C5 \uC800\uC7A5\uC18C\uB294 \uB2E4\uC911\uD654\uAC00 \uC6D0\uCE59\uC785\uB2C8\uB2E4. \uD604\uC7A5 NVR + \uD074\uB77C\uC6B0\uB4DC + \uC678\uC7A5 HDD \uAC19\uC740 3\uC911 \uAD6C\uC870\uAC00 \uAC00\uC7A5 \uC548\uC804\uD558\uBA70, \uCD5C\uC18C\uD55C \uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5\uC740 \uD544\uC218\uB85C \uAC16\uCD94\uB294 \uAC83\uC774 \uBC14\uB78C\uC9C1\uD569\uB2C8\uB2E4."], 2) + "</p>";
  body += '<h2 style="color:' + mc + '">\u{1F4A1} ' + biz + " CCTV \uD65C\uC6A9\uBC95</h2><p>\uBCF4\uC548 \uC678\uC5D0\uB3C4 " + biz + " \uC6B4\uC601\uC5D0 CCTV\uB97C \uB2E4\uC591\uD558\uAC8C \uD65C\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. " + s(["\uACE0\uAC1D \uB3D9\uC120\uACFC \uD53C\uD06C\uD0C0\uC784\uC744 \uC601\uC0C1\uC73C\uB85C \uBD84\uC11D\uD558\uBA74 \uB9E4\uC7A5 \uBC30\uCE58\uC640 \uC778\uB825 \uC6B4\uC6A9\uC744 \uCD5C\uC801\uD654\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uD3EC\uC2A4\uAE30 \uC5F0\uB3D9 \uC2DC \uACB0\uC81C \uC2DC\uC810 \uC601\uC0C1\uC744 \uC790\uB3D9 \uB9E4\uCE6D\uD558\uC5EC \uC815\uC0B0 \uC774\uC0C1 \uC2DC \uD574\uB2F9 \uC601\uC0C1\uC744 \uBC14\uB85C \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "CCTV \uC124\uCE58 \uB9E4\uC7A5\uC740 \uD654\uC7AC\xB7\uB3C4\uB09C \uBCF4\uD5D8\uB8CC\uB97C 10~20% \uD560\uC778\uBC1B\uC744 \uC218 \uC788\uC73C\uBA70, \uC0AC\uACE0 \uC2DC \uC601\uC0C1\uC740 \uBCF4\uD5D8\uAE08 \uCCAD\uAD6C\uC758 \uD575\uC2EC \uC99D\uAC70\uC785\uB2C8\uB2E4.", "\uC9C1\uC6D0 \uAD50\uC721 \uC790\uB8CC\uB85C \uD65C\uC6A9\uD558\uBA74 \uC2E4\uC81C \uACE0\uAC1D \uC751\uB300 \uC7A5\uBA74\uC744 \uBC14\uD0D5\uC73C\uB85C \uAD6C\uCCB4\uC801\uC778 \uAC1C\uC120 \uD3EC\uC778\uD2B8\uB97C \uCF54\uCE6D\uD560 \uC218 \uC788\uC5B4 \uC2E0\uADDC \uC9C1\uC6D0 \uC801\uC751 \uC2DC\uAC04\uC774 \uD06C\uAC8C \uB2E8\uCD95\uB429\uB2C8\uB2E4.", "\uC57C\uAC04 AI \uAC10\uC9C0 \uAE30\uB2A5\uC744 \uD65C\uC6A9\uD558\uBA74 \uC601\uC5C5 \uC885\uB8CC \uD6C4 \uCE68\uC785 \uC2DC\uB3C4\uC5D0 \uC989\uAC01 \uB300\uC751 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uD478\uC2DC \uC54C\uB9BC\uACFC \uACBD\uCC30 \uC5F0\uACC4 \uAE30\uB2A5\uC73C\uB85C \uC2E4\uC2DC\uAC04 \uB300\uC751\uC774 \uAC00\uB2A5\uD574\uC84C\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uB0B4 \uC774\uBCA4\uD2B8\uB098 \uD504\uB85C\uBAA8\uC158 \uC2DC \uACE0\uAC1D \uBC18\uC751\uC744 \uC601\uC0C1\uC73C\uB85C \uBD84\uC11D\uD558\uBA74 \uB9C8\uCF00\uD305 \uD6A8\uACFC \uCE21\uC815\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uB370\uC774\uD130 \uAE30\uBC18 \uC758\uC0AC\uACB0\uC815\uC758 \uC2DC\uC791\uC810\uC774 \uB429\uB2C8\uB2E4.", "\uC6D0\uACA9 \uADFC\uBB34 \uC2DC\uB300\uC5D0 \uB9E4\uC7A5 \uC6B4\uC601 \uAD00\uB9AC\uAC00 \uB354\uC6B1 \uC911\uC694\uD574\uC84C\uC2B5\uB2C8\uB2E4. CCTV \uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1\uC73C\uB85C \uC5EC\uB7EC \uC9C0\uC810\uC744 \uB3D9\uC2DC\uC5D0 \uAD00\uB9AC\uD560 \uC218 \uC788\uC5B4 \uAD00\uB9AC\uC790 1\uBA85\uC774 \uC804\uB2F4 \uAC00\uB2A5\uD55C \uB9E4\uC7A5 \uC218\uAC00 \uB298\uC5C8\uC2B5\uB2C8\uB2E4.", "\uC7AC\uACE0 \uB3C4\uB09C \uCD94\uC801\uC5D0 CCTV\uB294 \uACB0\uC815\uC801 \uB3C4\uAD6C\uC785\uB2C8\uB2E4. \uC7AC\uACE0 \uBD88\uC77C\uCE58 \uBC1C\uACAC \uC2DC \uD574\uB2F9 \uC2DC\uC810 \uC601\uC0C1\uC744 \uB3CC\uB824\uBCF4\uBA74 \uC6D0\uC778\uC744 \uBA85\uD655\uD788 \uD30C\uC545\uD560 \uC218 \uC788\uC5B4 \uBC18\uBCF5 \uC190\uC2E4\uC744 \uB9C9\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC2E0\uADDC \uC9C1\uC6D0 \uD589\uB3D9 \uAD00\uCC30\uC5D0\uB3C4 \uC720\uC6A9\uD569\uB2C8\uB2E4. \uAD50\uC721 \uACFC\uC815\uC5D0\uC11C \uB193\uCE5C \uBD80\uBD84\uC744 \uD30C\uC545\uD574 \uBCF4\uC644 \uAD50\uC721 \uC790\uB8CC\uB85C \uD65C\uC6A9\uD558\uBA74 \uC219\uB2EC \uC18D\uB3C4\uAC00 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.", "\uACE0\uAC1D \uB9CC\uC871\uB3C4 \uD5A5\uC0C1\uC5D0 \uAE30\uC5EC\uD569\uB2C8\uB2E4. \uBD84\uC2E4\uBB3C \uC870\uAE30 \uBC1C\uACAC, \uC751\uB300 \uD488\uC9C8 \uAC1C\uC120, \uBD84\uC7C1 \uAC1D\uAD00\uC801 \uD574\uACB0 \uB4F1\uC744 \uD1B5\uD574 \uACE0\uAC1D \uC2E0\uB8B0\uB3C4\uAC00 \uC62C\uB77C\uAC11\uB2C8\uB2E4.", "\uD504\uB79C\uCC28\uC774\uC988 \uBCF8\uC0AC\uC758 \uAC00\uB9F9\uC810 \uAD00\uB9AC \uB3C4\uAD6C\uB85C \uD65C\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uBCF8\uC0AC \uD45C\uC900 \uC6B4\uC601 \uC900\uC218 \uC5EC\uBD80\uB97C \uD604\uC7A5 \uBC29\uBB38 \uC5C6\uC774\uB3C4 \uD655\uC778\uD560 \uC218 \uC788\uC5B4 \uAD00\uB9AC \uD6A8\uC728\uC774 \uB300\uD3ED \uC99D\uAC00\uD569\uB2C8\uB2E4.", "\uACE0\uC6A9\uC8FC \uCC45\uC784 \uB9AC\uC2A4\uD06C \uAD00\uB9AC\uC5D0\uB3C4 \uC911\uC694\uD569\uB2C8\uB2E4. \uC9C1\uC6D0 \uBD80\uC0C1 \uC0AC\uACE0 \uC2DC \uC2E4\uC81C \uC0C1\uD669\uC744 CCTV\uB85C \uD655\uC778\uD574 \uC0B0\uC7AC \uCCAD\uAD6C\uB098 \uBBFC\uC0AC \uC18C\uC1A1\uC5D0\uC11C \uACF5\uC815\uD55C \uD310\uB2E8 \uADFC\uAC70\uAC00 \uB429\uB2C8\uB2E4.", "\uBCF4\uD5D8\uAE08 \uC0AC\uAE30 \uC2DC\uB3C4 \uBC29\uC9C0\uC5D0\uB3C4 \uD6A8\uACFC\uC801\uC785\uB2C8\uB2E4. \uB9E4\uC7A5\uC5D0\uC11C \uD5C8\uC704 \uB118\uC5B4\uC9D0 \uC0AC\uACE0\uB97C \uC8FC\uC7A5\uD558\uB294 \uC0AC\uB840\uAC00 \uC788\uB294\uB370 CCTV \uC601\uC0C1\uC774 \uC788\uC73C\uBA74 \uC989\uC2DC \uD310\uBCC4 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "\uB9E4\uCD9C \uC774\uC0C1 \uD0D0\uC9C0\uC758 \uCD9C\uBC1C\uC810\uC774 \uB429\uB2C8\uB2E4. \uD2B9\uC815 \uC2DC\uAC04\uB300 \uB9E4\uCD9C\uC774 \uB0AE\uC544\uC9C0\uBA74 CCTV\uB85C \uACE0\uAC1D \uBC29\uBB38 \uC218\uC640 \uBE44\uAD50\uD574 \uC9C1\uC6D0 \uADFC\uD0DC \uBB38\uC81C\uC778\uC9C0 \uB9E4\uC7A5 \uBB38\uC81C\uC778\uC9C0 \uD30C\uC545\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC9C0\uC5ED \uC0AC\uD68C \uC548\uC804 \uAE30\uC5EC\uB3C4 \uC7A5\uC810\uC785\uB2C8\uB2E4. \uB9E4\uC7A5 \uC678\uBD80 \uC778\uADFC\uC5D0\uC11C \uBC94\uC8C4 \uBC1C\uC0DD \uC2DC \uC601\uC0C1 \uC81C\uACF5\uC73C\uB85C \uC9C0\uC5ED \uACBD\uCC30 \uC218\uC0AC\uB97C \uB3C4\uC6B0\uBA74 \uB9E4\uC7A5 \uC2E0\uB8B0\uB3C4\uB3C4 \uD568\uAED8 \uC62C\uB77C\uAC11\uB2C8\uB2E4.", "\uC2A4\uD0C0\uD2B8\uC5C5\uC774\uB098 \uCC3D\uC5C5 \uCD08\uAE30 \uC5C5\uCCB4\uB294 \uD22C\uC790 \uC720\uCE58 \uC2DC CCTV \uAE30\uBC18 \uC6B4\uC601 \uB370\uC774\uD130\uB97C \uC81C\uC2DC\uD558\uBA74 \uAC1D\uAD00\uC801 \uC2E4\uC801 \uC790\uB8CC\uB85C \uD65C\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uB9E4\uC7A5 \uC218\uC900\uBD80\uD130 \uD22C\uC790 \uB9E4\uB825\uB3C4\uB97C \uB192\uC774\uB294 \uB3C4\uAD6C\uC785\uB2C8\uB2E4.", "\uB2E4\uAD6D\uC5B4 \uACE0\uAC1D \uC751\uB300 \uB9E4\uC7A5\uC740 CCTV\uAC00 \uD2B9\uD788 \uC720\uC6A9\uD569\uB2C8\uB2E4. \uC5B8\uC5B4 \uC7A5\uBCBD\uC73C\uB85C \uC778\uD55C \uC624\uD574 \uBC1C\uC0DD \uC2DC \uC601\uC0C1\uC73C\uB85C \uC0C1\uD669\uC744 \uC7AC\uAD6C\uC131\uD574 \uC6D0\uD65C\uD55C \uC18C\uD1B5\uC73C\uB85C \uD574\uACB0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC704\uC0DD \uAD00\uB9AC \uC99D\uBE59 \uC790\uB8CC\uB85C \uD65C\uC6A9\uB429\uB2C8\uB2E4. \uC2DD\uD488 \uAD00\uB828 \uC5C5\uC885\uC740 \uC704\uC0DD \uC810\uAC80 \uC2DC CCTV \uC601\uC0C1\uC774 \uC77C\uC0C1 \uC704\uC0DD \uAD00\uB9AC \uC900\uC218\uB97C \uC99D\uBA85\uD558\uB294 \uC911\uC694 \uC790\uB8CC\uAC00 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uACE0\uAC1D \uD074\uB808\uC784 \uBD84\uC11D\uC73C\uB85C \uB9E4\uC7A5 \uAC1C\uC120 \uD3EC\uC778\uD2B8\uB97C \uB3C4\uCD9C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBC18\uBCF5\uB418\uB294 \uD074\uB808\uC784 \uC601\uC0C1\uC744 \uBAA8\uC544 \uBD84\uC11D\uD558\uBA74 \uACF5\uD1B5\uB41C \uC6D0\uC778\uC744 \uCC3E\uC544 \uAD6C\uC870\uC801 \uAC1C\uC120\uC774 \uAC00\uB2A5\uD574\uC9D1\uB2C8\uB2E4.", "\uC784\uB300\uB8CC \uD611\uC0C1 \uC790\uB8CC\uB85C \uD65C\uC6A9\uB41C \uC0AC\uB840\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uB9E4\uC7A5 \uBC29\uBB38 \uACE0\uAC1D \uC218 \uB370\uC774\uD130\uB97C CCTV\uB85C \uC785\uC99D\uD558\uBA74 \uAC74\uBB3C\uC8FC\uC640 \uD611\uC0C1 \uC2DC \uAC1D\uAD00\uC801 \uADFC\uAC70\uB85C \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4."], 4) + " \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95\uC5D0 \uB530\uB77C \uC548\uB0B4\uD310 \uBD80\uCC29\uC774 \uD544\uC694\uD558\uBA70, \uC124\uCE58 \uC2DC \uC548\uB0B4\uD310\uACFC \uBCF4\uC548 \uC124\uC815\uC744 \uBAA8\uB450 \uC81C\uACF5\uD569\uB2C8\uB2E4. \uC601\uC0C1 \uC800\uC7A5 \uAE30\uAC04, \uC811\uADFC \uAD8C\uD55C \uC124\uC815, \uBC31\uC5C5 \uC8FC\uAE30 \uB4F1 \uBC95\uC801 \uC694\uAC74\uC5D0 \uB9DE\uB294 \uC6B4\uC601 \uAC00\uC774\uB4DC\uB3C4 \uD568\uAED8 \uC548\uB0B4\uD569\uB2C8\uB2E4.</p>";
  body += '<h2 style="color:' + mc + '">\u{1F4CB} ' + biz + " CCTV \uC124\uCE58 \uC548\uB0B4</h2><p>\uC804\uD654(010-9876-8282) \uD55C \uD1B5\uC774\uBA74 \uC804\uBB38 \uAE30\uC0AC\uAC00 " + biz + " \uB9E4\uC7A5(" + cc.area + ")\uC744 \uBC29\uBB38\uD558\uC5EC " + cc.spot + " \uAE30\uBC18\uC73C\uB85C " + cc.cam + " \uAD6C\uC131\uC744 \uC124\uACC4\uD569\uB2C8\uB2E4. \uC57D 2~3\uC2DC\uAC04\uC774\uBA74 \uC124\uCE58\uAC00 \uC644\uB8CC\uB418\uBA70, \uC2A4\uB9C8\uD2B8\uD3F0 \uC571 \uC6D0\uACA9 \uC811\uC18D \uC124\uC815\uACFC AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0 \uC138\uD305, \uC54C\uB9BC \uD14C\uC2A4\uD2B8\uAE4C\uC9C0 \uD604\uC7A5\uC5D0\uC11C \uBAA8\uB450 \uB9C8\uBB34\uB9AC\uD569\uB2C8\uB2E4.</p><p>" + s(["\uC124\uCE58 \uC804 \uB9E4\uC7A5 \uB3C4\uBA74\uC744 \uAE30\uBC18\uC73C\uB85C \uCE74\uBA54\uB77C \uC704\uCE58\uB97C \uC2DC\uBBAC\uB808\uC774\uC158\uD558\uACE0, \uC0AC\uAC01\uC9C0\uB300\uAC00 \uC5C6\uB294\uC9C0 \uC0AC\uC804 \uD655\uC778\uD569\uB2C8\uB2E4. \uBC30\uC120\uC740 \uCC9C\uC7A5\xB7\uBCBD\uBA74 \uB9E4\uB9BD\uC73C\uB85C \uAE54\uB054\uD558\uAC8C \uCC98\uB9AC\uD558\uBA70, \uAE30\uC874 \uC778\uD14C\uB9AC\uC5B4\uB97C \uD6FC\uC190\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC124\uCE58 \uD6C4 \uAC01 \uCE74\uBA54\uB77C\uC758 \uD654\uAC01\uACFC \uC57C\uAC04 \uCD2C\uC601 \uD488\uC9C8\uC744 \uD604\uC7A5\uC5D0\uC11C \uD568\uAED8 \uD655\uC778\uD569\uB2C8\uB2E4.", "\uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4\uB294 \uC5C5\uC885\uC5D0 \uD2B9\uD654\uB41C CCTV \uC124\uCE58 \uB178\uD558\uC6B0\uB97C \uBCF4\uC720\uD558\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uAC10\uC2DC \uD3EC\uC778\uD2B8\uC758 \uD2B9\uC131\uC744 \uACE0\uB824\uD55C \uB80C\uC988 \uC120\uD0DD(\uC640\uC774\uB4DC\xB7\uC90C), \uC870\uBA85 \uD658\uACBD\uC5D0 \uB9DE\uB294 \uAC10\uB3C4 \uC124\uC815, AI \uAC10\uC9C0 \uBBFC\uAC10\uB3C4 \uD29C\uB2DD\uAE4C\uC9C0 \uC5C5\uC885 \uB9DE\uCDA4\uC73C\uB85C \uC138\uD305\uD569\uB2C8\uB2E4. \uC124\uCE58 \uD6C4\uC5D0\uB3C4 \uC6D0\uACA9 \uC9C0\uC6D0\uC73C\uB85C \uC124\uC815 \uBCC0\uACBD\uC744 \uB3C4\uC640\uB4DC\uB9BD\uB2C8\uB2E4.", "\uB9E4\uC7A5\uC5D0 \uCD5C\uC801\uD654\uB41C CCTV \uAD6C\uC131\uC744 \uC81C\uC548\uD558\uBA70, \uBD88\uD544\uC694\uD55C \uACE0\uC0AC\uC591 \uC7A5\uBE44\uB85C \uBE44\uC6A9\uC744 \uB0AD\uBE44\uD558\uC9C0 \uC54A\uB3C4\uB85D \uD569\uB2C8\uB2E4. \uD5A5\uD6C4 \uB9E4\uC7A5 \uD655\uC7A5\uC774\uB098 \uB9AC\uBAA8\uB378\uB9C1 \uC2DC \uCE74\uBA54\uB77C\uB97C \uCD94\uAC00\uD558\uAC70\uB098 \uC704\uCE58\uB97C \uBCC0\uACBD\uD560 \uC218 \uC788\uB3C4\uB85D \uD655\uC7A5\uC131\uC744 \uACE0\uB824\uD55C \uBC30\uC120 \uC124\uACC4\uB97C \uAE30\uBCF8\uC73C\uB85C \uC81C\uACF5\uD569\uB2C8\uB2E4.", "\uC601\uC5C5 \uC2DC\uAC04 \uC678 \uC124\uCE58\uAC00 \uC6D0\uCE59\uC785\uB2C8\uB2E4. \uB9E4\uC7A5 \uC6B4\uC601\uC5D0 \uBC29\uD574\uAC00 \uB418\uC9C0 \uC54A\uB3C4\uB85D \uC800\uB141\xB7\uC57C\uAC04 \uC2DC\uAC04\uB300\uC5D0 \uC791\uC5C5 \uAC00\uB2A5\uD558\uBA70, \uC720\uBB34\uC120 \uD63C\uC6A9 \uC124\uACC4\uB85C \uC8FC\uC694 \uC601\uC5ED\uC744 \uBA3C\uC800 \uC124\uCE58\uD55C \uB4A4 \uBCF4\uC870 \uAD6C\uC5ED\uC744 \uB2E8\uACC4\uC801\uC73C\uB85C \uD655\uC7A5\uD558\uB294 \uBC29\uC2DD\uB3C4 \uC9C0\uC6D0\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uC644\uB8CC \uD6C4 \uCD5C\uC18C 1\uC2DC\uAC04\uC758 \uD604\uC7A5 \uAD50\uC721\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4. \uAD00\uB9AC\uC790 \uC571 \uC0AC\uC6A9\uBC95, \uBE44\uC0C1 \uC0C1\uD669 \uB300\uC751, \uC601\uC0C1 \uBC31\uC5C5 \uBC29\uBC95, \uC124\uC815 \uBCC0\uACBD \uC808\uCC28\uAE4C\uC9C0 \uC2E4\uC81C \uC2A4\uB9C8\uD2B8\uD3F0\uC73C\uB85C \uC2DC\uC5F0\uD558\uBA70 \uCCB4\uACC4\uC801\uC73C\uB85C \uC548\uB0B4\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uD6C4 2\uC8FC \uC774\uB0B4 \uBB34\uB8CC AS\uAC00 \uAE30\uBCF8 \uC81C\uACF5\uB429\uB2C8\uB2E4. \uCD08\uAE30 \uC138\uD305 \uD6C4 \uCD94\uAC00\uB85C \uCE74\uBA54\uB77C \uAC01\uB3C4 \uC870\uC815\uC774\uB098 \uC124\uC815 \uBCC0\uACBD\uC774 \uD544\uC694\uD55C \uACBD\uC6B0 \uC989\uC2DC \uBC29\uBB38\uD558\uC5EC \uD574\uACB0\uD574\uB4DC\uB9BD\uB2C8\uB2E4.", "\uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1 \uC571 \uC138\uD305\uC774 \uAC00\uC7A5 \uC911\uC694\uD55C \uC124\uCE58 \uB2E8\uACC4\uC785\uB2C8\uB2E4. \uC0AC\uC6A9\uC790 \uACC4\uC815 \uC0DD\uC131, 2\uB2E8\uACC4 \uC778\uC99D \uC124\uC815, \uC54C\uB9BC \uADDC\uCE59 \uC138\uBD80 \uC870\uC815\uAE4C\uC9C0 \uC644\uB8CC\uD574\uC57C \uC9C4\uC815\uD55C 24\uC2DC\uAC04 \uBCF4\uC548 \uCCB4\uACC4\uAC00 \uAC16\uCDB0\uC9D1\uB2C8\uB2E4.", "\uB9E4\uC7A5 \uB0B4 \uC640\uC774\uD30C\uC774 \uAC15\uB3C4\uAC00 \uCE74\uBA54\uB77C \uC131\uB2A5\uC744 \uC88C\uC6B0\uD569\uB2C8\uB2E4. \uC124\uCE58 \uC804 \uB124\uD2B8\uC6CC\uD06C \uD658\uACBD\uC744 \uCCB4\uD06C\uD574 \uD544\uC694 \uC2DC Wi-Fi \uD655\uC7A5\uAE30 \uCD94\uAC00 \uC124\uCE58\uB098 \uC720\uC120 \uCF00\uC774\uBE14 \uD3EC\uC124\uC744 \uBCD1\uD589 \uC81C\uC548\uD569\uB2C8\uB2E4.", "\uBAA8\uB4E0 \uC124\uCE58 \uC791\uC5C5\uC5D0 \uB300\uD55C \uBCF4\uC99D \uAE30\uAC04\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uCE74\uBA54\uB77C 2\uB144, NVR 3\uB144, \uC124\uCE58 \uC2DC\uACF5 1\uB144\uC774 \uD45C\uC900\uC774\uBA70, \uC774 \uAE30\uAC04 \uB0B4 \uD558\uC790 \uBC1C\uC0DD \uC2DC \uBAA8\uB4E0 \uBE44\uC6A9\uC744 \uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4\uC5D0\uC11C \uBD80\uB2F4\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uC2DC \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC900\uC218\uB97C \uC704\uD55C \uBAA8\uB4E0 \uC870\uCE58\uB97C \uBCD1\uD589\uD569\uB2C8\uB2E4. CCTV \uCD2C\uC601 \uC548\uB0B4\uD310 \uB514\uC790\uC778 \uBC0F \uC81C\uC791, \uC601\uC0C1 \uC811\uADFC \uAD8C\uD55C \uC124\uC815, \uCD2C\uC601 \uBC94\uC704 \uBC95\uC801 \uAC80\uD1A0\uAE4C\uC9C0 \uD55C\uBC88\uC5D0 \uD574\uACB0\uD569\uB2C8\uB2E4.", "\uAE30\uC874 CCTV\uB97C \uC774\uC804\xB7\uD655\uC7A5\uD558\uB294 \uACBD\uC6B0\uB3C4 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uAE30\uC874 \uBC30\uC120 \uD65C\uC6A9\uC774 \uAC00\uB2A5\uD55C\uC9C0 \uAC80\uD1A0\uD558\uACE0, \uD638\uD658\uB418\uB294 \uCE74\uBA54\uB77C\uB85C \uC5C5\uADF8\uB808\uC774\uB4DC\uD558\uAC70\uB098 \uC2E0\uADDC \uC7A5\uBE44\uC640 \uD63C\uC6A9\uD558\uB294 \uBC29\uC548\uC744 \uC81C\uC2DC\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uD6C4 \uC2DC\uC2A4\uD15C \uC815\uC0C1 \uC791\uB3D9\uC744 1\uC8FC\uC77C\uAC04 \uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1\uD569\uB2C8\uB2E4. \uC774\uC0C1 \uC9D5\uD6C4\uAC00 \uBCF4\uC774\uBA74 \uC120\uC81C \uB300\uC751\uD574 \uCD08\uAE30 \uC815\uCC29\uC744 \uC548\uC815\uD654\uD569\uB2C8\uB2E4. \uACE0\uAC1D\uC774 \uC9C1\uC811 \uC2E0\uACE0\uD558\uAE30 \uC804\uC5D0 \uBB38\uC81C\uB97C \uD574\uACB0\uD558\uB294 \uC11C\uBE44\uC2A4\uC785\uB2C8\uB2E4.", "\uB300\uADDC\uBAA8 \uB9E4\uC7A5\xB7\uB2E4\uC9C0\uC810 \uCCB4\uC778\uC810 \uC124\uCE58\uB294 \uD300 \uB2E8\uC704\uB85C \uC9C4\uD589\uB429\uB2C8\uB2E4. 2~4\uC778 \uC804\uBB38 \uAE30\uC0AC\uD300\uC774 \uD558\uB8E8\uC5D0 50\uB300 \uC774\uC0C1 \uC124\uCE58 \uAC00\uB2A5\uD558\uBA70, \uC9E7\uC740 \uAE30\uAC04 \uB0B4 \uB300\uB7C9 \uC124\uCE58\uAC00 \uD544\uC694\uD55C \uD504\uB85C\uC81D\uD2B8\uC5D0 \uCD5C\uC801\uD654\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uACAC\uC801\uC740 \uD604\uC7A5 \uC2E4\uCE21 \uD6C4 \uD655\uC815\uB429\uB2C8\uB2E4. \uC804\uD654 \uC0C1\uB2F4\uC73C\uB85C \uAC1C\uB7B5\uC801 \uACAC\uC801\uC744 \uC548\uB0B4\uD558\uACE0, \uBC29\uBB38 \uC2E4\uCE21 \uD6C4 \uCD5C\uC885 \uACAC\uC801\uC744 \uC81C\uC2DC\uD574 \uC228\uC740 \uBE44\uC6A9\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uACAC\uC801 \uD6C4 7\uC77C \uB0B4 \uACC4\uC57D \uC2DC \uD560\uC778 \uD61C\uD0DD\uB3C4 \uC81C\uACF5\uD569\uB2C8\uB2E4.", "CCTV\uC640 \uD568\uAED8 \uC124\uCE58 \uAC00\uB2A5\uD55C \uD1B5\uD569 \uBCF4\uC548 \uC2DC\uC2A4\uD15C\uB3C4 \uC81C\uC548\uD569\uB2C8\uB2E4. \uACBD\uBCF4\uAE30, \uCD9C\uC785 \uD1B5\uC81C, \uC2A4\uB9C8\uD2B8 \uB3C4\uC5B4\uB77D\uAE4C\uC9C0 \uD558\uB098\uC758 \uC571\uC5D0\uC11C \uAD00\uB9AC\uD560 \uC218 \uC788\uB294 \uD1A0\uD0C8 \uC194\uB8E8\uC158\uC744 \uAD6C\uC131\uD574\uB4DC\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58 \uD6C4 3\uAC1C\uC6D4, 6\uAC1C\uC6D4, 1\uB144 \uC815\uAE30 \uC810\uAC80\uC774 \uAE30\uBCF8 \uC81C\uACF5\uB429\uB2C8\uB2E4. \uCE74\uBA54\uB77C \uB80C\uC988 \uCCAD\uC18C, \uD38C\uC6E8\uC5B4 \uC5C5\uB370\uC774\uD2B8, \uB179\uD654 \uC0C1\uD0DC \uC810\uAC80\uC744 \uD1B5\uD574 \uC2DC\uC2A4\uD15C \uC131\uB2A5\uC744 \uCD5C\uC801 \uC0C1\uD0DC\uB85C \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\uACE0\uAC1D \uC694\uCCAD \uC2DC \uC124\uCE58 \uC601\uC0C1\uC744 \uAE30\uB85D\uC73C\uB85C \uB0A8\uAE41\uB2C8\uB2E4. \uD5A5\uD6C4 \uC774\uC804\xB7\uD655\uC7A5 \uC2DC \uAE30\uC874 \uBC30\uC120 \uC704\uCE58\uC640 \uC124\uCE58 \uBC29\uC2DD\uC744 \uC815\uD655\uD788 \uD30C\uC545\uD560 \uC218 \uC788\uC5B4 \uC7AC\uC124\uCE58 \uBE44\uC6A9\uC744 \uCD5C\uC18C\uD654\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "CCTV \uC124\uCE58 \uD6C4 \uC0AC\uC6A9 \uC911 \uBB38\uC81C\uAC00 \uC0DD\uAE30\uBA74 \uC6D0\uACA9 \uC9C4\uB2E8\uC774 1\uCC28 \uB300\uC751\uC785\uB2C8\uB2E4. \uC804\uD654 \uD55C \uD1B5\uC774\uBA74 \uAE30\uC0AC\uAC00 \uC6D0\uACA9 \uC811\uC18D\uD574 \uBB38\uC81C \uC9C4\uB2E8 \uD6C4 \uD574\uACB0\uD558\uAC70\uB098, \uD544\uC694 \uC2DC \uC989\uC2DC \uD604\uC7A5 \uBC29\uBB38\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uC2DC \uD558\uC790 \uBD80\uC704 \uC810\uAC80\uACFC \uD568\uAED8 \uB9E4\uC7A5 \uC804\uBC18\uC758 \uBCF4\uC548 \uCDE8\uC57D\uC810 \uCEE8\uC124\uD305\uB3C4 \uBCD1\uD589\uD569\uB2C8\uB2E4. CCTV \uC678\uC5D0\uB3C4 \uB9E4\uC7A5 \uBCF4\uC548\uC5D0 \uB3C4\uC6C0\uB418\uB294 \uAC1C\uC120 \uD3EC\uC778\uD2B8\uB97C \uC804\uBB38\uAC00 \uAD00\uC810\uC5D0\uC11C \uBB34\uC0C1\uC73C\uB85C \uC81C\uACF5\uD569\uB2C8\uB2E4.", "\uC124\uCE58 \uC791\uC5C5\uC758 \uD488\uC9C8\uC740 20\uB144 \uACBD\uB825\uC758 \uC804\uBB38 \uAE30\uC0AC\uAC00 \uBCF4\uC7A5\uD569\uB2C8\uB2E4. \uAD6D\uAC00\uACF5\uC778 \uC790\uACA9\uC99D\uACFC CCTV \uC81C\uC870\uC0AC \uC804\uBB38 \uAD50\uC721 \uC218\uB8CC \uACBD\uB825\uC744 \uBCF4\uC720\uD55C \uAE30\uC0AC\uB9CC \uD604\uC7A5\uC5D0 \uD22C\uC785\uB429\uB2C8\uB2E4."], 7) + "</p>";
  body += '<h2 style="color:' + mc + '">\u{1F4B0} ' + biz + " CCTV \uBE44\uC6A9 \uC548\uB0B4</h2><p>" + s(["\uADDC\uBAA8\uC5D0 \uB9DE\uB294 \uAD6C\uC131 \uC2DC \uCE74\uBA54\uB77C \uB300\uC218, \uB179\uD654\uAE30 \uC6A9\uB7C9, \uC124\uCE58 \uB09C\uC774\uB3C4\uC5D0 \uB530\uB77C \uBE44\uC6A9\uC774 \uB2EC\uB77C\uC9D1\uB2C8\uB2E4. \uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4\uB294 \uBB34\uB8CC \uD604\uC7A5 \uC2E4\uCE21 \uD6C4 \uC815\uCC30\uC81C \uACAC\uC801\uC744 \uD655\uC815\uD558\uBA70, \uCD94\uAC00 \uBE44\uC6A9\uC774 \uBC1C\uC0DD\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. CCTV \uC124\uCE58 \uB9E4\uC7A5\uC740 \uD654\uC7AC\xB7\uB3C4\uB09C \uBCF4\uD5D8\uB8CC\uB97C 10~20% \uD560\uC778\uBC1B\uC744 \uC218 \uC788\uC5B4 \uC124\uCE58 \uBE44\uC6A9\uC744 \uC0C1\uC1C4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uB9E4\uC7A5\uC5D0 CCTV\uB97C \uC124\uCE58\uD558\uBA74 \uCD08\uAE30 \uD22C\uC790 \uB300\uBE44 \uBCF4\uC548 \uC0AC\uACE0 \uC608\uBC29, \uBCF4\uD5D8\uB8CC \uD560\uC778, \uC9C1\uC6D0 \uAD00\uB9AC \uD6A8\uC728\uD654 \uB4F1 \uBCF5\uD569\uC801\uC778 \uD6A8\uACFC\uAC00 \uB098\uD0C0\uB0A9\uB2C8\uB2E4. \uD2B9\uD788 \uC704\uD5D8\uC774 \uC0C1\uC874\uD558\uB294 \uC5C5\uC885\uC740 \uC0AC\uACE0 \uD55C \uAC74\uB9CC \uC608\uBC29\uD574\uB3C4 \uC124\uCE58 \uBE44\uC6A9\uC744 \uCDA9\uBD84\uD788 \uD68C\uC218\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uAD6C\uC131\uC758 \uC6D4 \uC720\uC9C0\uBE44\uB294 \uC804\uAE30\uB8CC\uC640 \uC778\uD130\uB137 \uBE44\uC6A9 \uC815\uB3C4\uC774\uBA70, \uD074\uB77C\uC6B0\uB4DC \uC800\uC7A5\uC18C\uB97C \uC774\uC6A9\uD558\uBA74 NVR \uACE0\uC7A5 \uC2DC\uC5D0\uB3C4 \uC601\uC0C1\uC774 \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uB429\uB2C8\uB2E4. \uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4\uB294 \uB9E4\uCD9C \uADDC\uBAA8\uC5D0 \uB9DE\uB294 \uD569\uB9AC\uC801\uC778 \uAD6C\uC131\uC744 \uCD94\uCC9C\uD569\uB2C8\uB2E4.", "\uAD6D\uC0B0 \uD504\uB9AC\uBBF8\uC5C4 \uC7A5\uBE44\uC640 \uC911\uAD6D\uC0B0 \uC800\uAC00 \uC7A5\uBE44\uB294 \uCD08\uAE30 \uBE44\uC6A9\uC774 40~60% \uCC28\uC774\uAC00 \uB0A9\uB2C8\uB2E4. \uADF8\uB7EC\uB098 3\uB144 \uD6C4 \uCD1D \uBE44\uC6A9(\uAD50\uCCB4 \uBC0F \uC720\uC9C0\uBCF4\uC218 \uD3EC\uD568)\uC744 \uBCF4\uBA74 \uC800\uAC00 \uC7A5\uBE44\uAC00 \uB354 \uBE44\uC2FC \uACBD\uC6B0\uAC00 \uB300\uBD80\uBD84\uC785\uB2C8\uB2E4.", "\uB80C\uD0C8 \uBC29\uC2DD \uB3C4\uC785 \uC2DC \uCD08\uAE30 \uBE44\uC6A9 \uBD80\uB2F4 \uC5C6\uC774 \uC6D4 3\uB9CC\uC6D0\uB300\uBD80\uD130 \uC2DC\uC791 \uAC00\uB2A5\uD569\uB2C8\uB2E4. 1\uB144 \uC57D\uC815 \uAE30\uC900\uC73C\uB85C \uCD1D \uC9C0\uCD9C\uC774 \uD06C\uC9C0 \uC54A\uC544 \uB2E8\uAE30 \uC784\uCC28 \uB9E4\uC7A5\uC774\uB098 \uC790\uBCF8\uC774 \uBD80\uC871\uD55C \uCC3D\uC5C5 \uCD08\uAE30 \uB9E4\uC7A5\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4.", "\uC18C\uC0C1\uACF5\uC778 \uC9C0\uC6D0\uC0AC\uC5C5\uC744 \uD65C\uC6A9\uD558\uBA74 \uC124\uCE58 \uBE44\uC6A9\uC758 50% \uC774\uC0C1\uC744 \uC9C0\uC6D0\uBC1B\uC744 \uC218 \uC788\uB294 \uACBD\uC6B0\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uC9C0\uC790\uCCB4\uB9C8\uB2E4 \uC870\uAC74\uC774 \uB2E4\uB974\uBBC0\uB85C \uAD00\uD560 \uC9C0\uC790\uCCB4 \uD648\uD398\uC774\uC9C0\uB97C \uD655\uC778\uD558\uAC70\uB098 \uC0C1\uB2F4 \uC2DC \uBB38\uC758\uD574\uBCF4\uC138\uC694.", "\uBCF4\uD5D8\uB8CC \uD560\uC778 \uD6A8\uACFC\uB85C \uC124\uCE58 \uBE44\uC6A9 \uD68C\uC218\uAC00 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uC77C\uBC18\uC801\uC73C\uB85C CCTV \uC124\uCE58 \uD6C4 \uD654\uC7AC \uBCF4\uD5D8\uB8CC 10%, \uB3C4\uB09C \uBCF4\uD5D8\uB8CC 20% \uD560\uC778\uC774 \uC801\uC6A9\uB418\uC5B4 \uC5F0\uAC04 \uC218\uC2ED\uB9CC\uC6D0\uC758 \uBCF4\uD5D8\uB8CC \uC808\uAC10\uC774 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "\uC7A5\uAE30 \uC0AC\uC6A9\uC744 \uACE0\uB824\uD55C \uC7A5\uBE44 \uC120\uD0DD\uC774 \uC911\uC694\uD569\uB2C8\uB2E4. \uCE74\uBA54\uB77C \uC218\uBA85\uC740 5~7\uB144, NVR\uC740 3~5\uB144\uC774 \uD45C\uC900\uC774\uBA70, \uAD50\uCCB4 \uC8FC\uAE30\uB97C \uACE0\uB824\uD55C \uCD1D \uC18C\uC720 \uBE44\uC6A9(TCO) \uAE30\uC900 \uBE44\uAD50\uAC00 \uD604\uBA85\uD569\uB2C8\uB2E4.", "\uC720\uC9C0\uBCF4\uC218 \uACC4\uC57D\uC740 \uBCC4\uB3C4\uC785\uB2C8\uB2E4. \uC124\uCE58 \uD6C4 1\uB144\uAC04 \uBB34\uB8CC AS\uAC00 \uAE30\uBCF8\uC774\uBA70, \uC774\uD6C4 \uC5F0\uAC04 \uC7A5\uBE44\uAC00\uC561\uC758 10~15% \uC218\uC900\uC73C\uB85C \uC720\uC0C1 \uACC4\uC57D\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uADDC\uBAA8\uAC00 \uD070 \uB9E4\uC7A5\uC740 \uC774 \uBE44\uC6A9\uC774 \uC0C1\uB2F9\uD558\uBBC0\uB85C \uC0AC\uC804 \uAC80\uD1A0\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\uD074\uB77C\uC6B0\uB4DC \uC800\uC7A5\uC18C \uC6D4 \uC774\uC6A9\uB8CC\uB294 \uCC44\uB110 \uC218\uC640 \uBCF4\uAD00 \uAE30\uAC04\uC5D0 \uB530\uB77C \uACB0\uC815\uB429\uB2C8\uB2E4. 4\uCC44\uB110 30\uC77C \uBCF4\uAD00\uC740 \uC6D4 1~3\uB9CC\uC6D0, 16\uCC44\uB110 30\uC77C\uC740 \uC6D4 5~10\uB9CC\uC6D0 \uC218\uC900\uC785\uB2C8\uB2E4. NVR \uB0B4\uC7A5 \uC800\uC7A5\uC18C\uC640 \uBCD1\uD589 \uC0AC\uC6A9\uC774 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4.", "\uB124\uD2B8\uC6CC\uD06C \uC778\uD504\uB77C \uC5C5\uADF8\uB808\uC774\uB4DC \uBE44\uC6A9\uC744 \uAC04\uACFC\uD558\uBA74 \uC548 \uB429\uB2C8\uB2E4. \uAE30\uC874 \uC778\uD130\uB137 \uC18D\uB3C4\uAC00 \uB290\uB9AC\uAC70\uB098 \uC640\uC774\uD30C\uC774\uAC00 \uC57D\uD558\uBA74 \uCD94\uAC00 \uC7A5\uBE44 \uBE44\uC6A9\uC774 \uBC1C\uC0DD\uD569\uB2C8\uB2E4. \uC804\uCCB4 \uACAC\uC801\uC5D0 \uB124\uD2B8\uC6CC\uD06C \uC5C5\uADF8\uB808\uC774\uB4DC \uBE44\uC6A9\uC774 \uD3EC\uD568\uB418\uB294\uC9C0 \uBC18\uB4DC\uC2DC \uD655\uC778\uD558\uC138\uC694.", "AI \uAE30\uB2A5 \uD0D1\uC7AC \uCE74\uBA54\uB77C\uB294 \uAE30\uBCF8 \uBAA8\uB378 \uB300\uBE44 30~50% \uBE44\uC2F8\uC9C0\uB9CC, \uAD00\uB9AC \uD6A8\uC728\uC774 \uD06C\uAC8C \uC62C\uB77C\uAC11\uB2C8\uB2E4. \uC778\uAC74\uBE44 \uC808\uAC10 \uD6A8\uACFC\uB97C \uACE0\uB824\uD558\uBA74 \uD22C\uC790 \uD68C\uC218 \uAE30\uAC04\uC774 1~2\uB144 \uC774\uB0B4\uC785\uB2C8\uB2E4.", "\uC5F4\uD654\uC0C1 \uCE74\uBA54\uB77C\uB294 \uD2B9\uC218 \uC6A9\uB3C4\uB85C \uC77C\uBC18 \uCE74\uBA54\uB77C\uC758 3~5\uBC30 \uBE44\uC6A9\uC774 \uB4ED\uB2C8\uB2E4. \uADF8\uB7EC\uB098 \uD654\uC7AC \uAC10\uC9C0 \uAE30\uB2A5\uC73C\uB85C \uD55C \uBC88\uC758 \uC0AC\uACE0\uB9CC \uC608\uBC29\uD574\uB3C4 \uC218\uCC9C\uB9CC\uC6D0 \uC190\uD574\uB97C \uB9C9\uC744 \uC218 \uC788\uC5B4 \uC2DD\uB2F9\xB7\uACF5\uC7A5 \uB4F1\uC5D0\uC11C \uD544\uC218 \uC7A5\uBE44\uAC00 \uB418\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", "\uB300\uADDC\uBAA8 \uC124\uCE58\uB294 \uD560\uC778 \uD611\uC0C1 \uC5EC\uC9C0\uAC00 \uD07D\uB2C8\uB2E4. \uCE74\uBA54\uB77C 10\uB300 \uC774\uC0C1 \uC124\uCE58 \uC2DC 10~20% \uD560\uC778, 20\uB300 \uC774\uC0C1\uC740 15~25% \uD560\uC778\uC774 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4. \uC5EC\uB7EC \uC5C5\uCCB4 \uACAC\uC801\uC744 \uBE44\uAD50\uD558\uBA74 \uCD5C\uC801\uC758 \uC870\uAC74\uC744 \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\uC124\uCE58\uBE44\uC5D0 \uBC30\uC120 \uACF5\uC0AC\uBE44\uAC00 \uD3EC\uD568\uB418\uB294\uC9C0 \uD655\uC778\uD558\uC138\uC694. \uAE30\uBCF8 \uACAC\uC801\uC5D0 \uBC30\uC120 \uACF5\uC0AC\uBE44\uAC00 \uBE60\uC9C4 \uACBD\uC6B0\uAC00 \uB9CE\uC544 \uC2E4\uC81C \uCD1D \uBE44\uC6A9\uC774 30% \uC815\uB3C4 \uC99D\uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD22C\uBA85\uD55C \uACAC\uC801\uC744 \uC81C\uC2DC\uD558\uB294 \uC5C5\uCCB4\uB97C \uC120\uD0DD\uD574\uC57C \uD569\uB2C8\uB2E4.", "\uB178\uD6C4 NVR \uAD50\uCCB4\uB294 \uD3C9\uADE0 5\uB144 \uC8FC\uAE30\uB85C \uD544\uC694\uD569\uB2C8\uB2E4. \uCE74\uBA54\uB77C\uB294 \uADF8\uB300\uB85C \uC4F0\uBA74\uC11C NVR\uB9CC \uAD50\uCCB4\uD558\uB294 \uBD80\uBD84 \uC5C5\uADF8\uB808\uC774\uB4DC\uAC00 \uAC00\uB2A5\uD558\uBBC0\uB85C 10\uB144 \uC774\uC0C1 \uC7A5\uAE30 \uAD00\uC810\uC758 \uC608\uC0B0 \uACC4\uD68D\uC744 \uC138\uC6B0\uB294 \uAC83\uC774 \uBC14\uB78C\uC9C1\uD569\uB2C8\uB2E4.", "\uC2E0\uADDC \uCE74\uBA54\uB77C \uCD94\uAC00 \uC124\uCE58 \uC2DC \uAE30\uC874 \uC2DC\uC2A4\uD15C\uACFC \uD638\uD658\uC131\uC744 \uD655\uC778\uD574\uC57C \uD569\uB2C8\uB2E4. \uB3D9\uC77C \uC81C\uC870\uC0AC\uB294 \uBB34\uB8CC \uD1B5\uD569\uC774 \uAC00\uB2A5\uD558\uC9C0\uB9CC, \uD0C0\uC0AC \uD63C\uC6A9\uC740 VMS \uC18C\uD504\uD2B8\uC6E8\uC5B4 \uBE44\uC6A9\uC774 \uCD94\uAC00\uB85C \uB4E4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "CCTV\uC640 \uCD9C\uC785 \uD1B5\uC81C\uB97C \uD568\uAED8 \uC124\uCE58\uD558\uBA74 \uD1B5\uD569 \uD560\uC778\uC774 \uC801\uC6A9\uB429\uB2C8\uB2E4. \uBCC4\uB3C4 \uC124\uCE58 \uB300\uBE44 15~20% \uD560\uC778 \uBC1B\uC744 \uC218 \uC788\uC5B4 \uBCF4\uC548 \uD1A0\uD0C8 \uC194\uB8E8\uC158\uC73C\uB85C \uBB36\uC5B4 \uACC4\uC57D\uD558\uB294 \uAC83\uC774 \uACBD\uC81C\uC801\uC785\uB2C8\uB2E4.", "\uD604\uC7A5 \uB9DE\uCDA4 \uCEE8\uC124\uD305\uC740 \uBB34\uB8CC\uC785\uB2C8\uB2E4. \uCD9C\uC7A5\uBE44\xB7\uACAC\uC801\uBE44\xB7\uC124\uACC4\uBE44 \uBAA8\uB450 \uBB34\uB8CC\uB85C \uC81C\uACF5\uD558\uBA70, \uACC4\uC57D \uC131\uC0AC \uC2DC\uC5D0\uB9CC \uBE44\uC6A9\uC774 \uBC1C\uC0DD\uD558\uB294 \uAD6C\uC870\uC785\uB2C8\uB2E4. \uBD80\uB2F4 \uC5C6\uC774 \uC5EC\uB7EC \uC5C5\uCCB4\uB97C \uBE44\uAD50\uD574\uBCF4\uB294 \uAC83\uC774 \uD604\uBA85\uD569\uB2C8\uB2E4.", "\uC7A5\uAE30 \uACC4\uC57D \uC2DC \uCD94\uAC00 \uD61C\uD0DD\uC774 \uC788\uC2B5\uB2C8\uB2E4. 3\uB144 \uC57D\uC815 \uC2DC \uCE74\uBA54\uB77C 1\uB300 \uBB34\uC0C1 \uCD94\uAC00, 5\uB144 \uC57D\uC815 \uC2DC NVR \uBB34\uC0C1 \uC5C5\uADF8\uB808\uC774\uB4DC \uAC19\uC740 \uC870\uAC74\uC774 \uC77C\uBC18\uC801\uC785\uB2C8\uB2E4. \uC7A5\uAE30 \uACC4\uD68D\uC774 \uC788\uB2E4\uBA74 \uCD08\uAE30 \uD611\uC0C1 \uC2DC \uC694\uCCAD\uD574\uBCF4\uC138\uC694."], 1) + "</p>";
  body += '<h2 style="color:' + mc + '">\u2753 ' + biz + " CCTV \uC790\uC8FC \uBB3B\uB294 \uC9C8\uBB38</h2>";
  body += '<div style="background:#f9fafb;border-radius:12px;padding:20px;margin:16px 0"><p style="font-weight:700;color:#111;margin:0 0 8px">Q. ' + biz + '\uC5D0 CCTV\uAC00 \uBA87 \uB300 \uD544\uC694\uD55C\uAC00\uC694?</p><p style="color:#555;margin:0 0 16px;line-height:1.7">' + biz + js(biz, "\uC740", "\uB294") + " \uD3C9\uADE0 " + cc.area + " \uADDC\uBAA8\uC774\uBA70, " + cc.spot + "\uC744 \uCEE4\uBC84\uD558\uB824\uBA74 " + cc.cam + " \uAD6C\uC131\uC774 \uC801\uD569\uD569\uB2C8\uB2E4. \uC62C\uD398\uC774\uC2A4\uD1A0\uC5B4 \uC804\uBB38 \uAE30\uC0AC\uAC00 \uD604\uC7A5\uC744 \uBC29\uBB38\uD558\uC5EC \uC0AC\uAC01\uC9C0\uB300 \uC5C6\uB294 \uCD5C\uC801 \uBC30\uCE58\uB97C \uC124\uACC4\uD569\uB2C8\uB2E4.</p>";
  body += '<p style="font-weight:700;color:#111;margin:0 0 8px">Q. \uB179\uD654 \uC601\uC0C1\uC740 \uC5BC\uB9C8\uB098 \uBCF4\uAD00\uB418\uB098\uC694?</p><p style="color:#555;margin:0 0 16px;line-height:1.7">NVR 2TB \uAE30\uC900 ' + cc.cam + "\uB85C \uC57D 30\uC77C \uC5F0\uC18D \uB179\uD654\uAC00 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uC911\uC694 \uC601\uC0C1\uC740 \uBCC4\uB3C4 \uBC31\uC5C5\uD558\uAC70\uB098 \uD074\uB77C\uC6B0\uB4DC \uC800\uC7A5\uC18C\uC5D0 \uBCF4\uAD00\uD560 \uC218 \uC788\uC73C\uBA70, \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95\uC5D0 \uB530\uB77C 30\uC77C \uC774\uC0C1 \uBCF4\uAD00 \uC2DC \uBCC4\uB3C4 \uACE0\uC9C0\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.</p>";
  body += '<p style="font-weight:700;color:#111;margin:0 0 8px">Q. \uC2A4\uB9C8\uD2B8\uD3F0\uC73C\uB85C \uC6D0\uACA9 \uD655\uC778\uC774 \uB418\uB098\uC694?</p><p style="color:#555;margin:0;line-height:1.7">\uB124, \uC124\uCE58 \uC2DC \uC2A4\uB9C8\uD2B8\uD3F0 \uC571\uC744 \uC5F0\uB3D9\uD558\uC5EC \uC5B8\uC81C \uC5B4\uB514\uC11C\uB4E0 ' + biz + " \uB9E4\uC7A5\uC744 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0 \uC54C\uB9BC\uC744 \uC124\uC815\uD558\uBA74 \uC774\uC0C1 \uC0C1\uD669 \uBC1C\uC0DD \uC2DC \uC989\uC2DC \uD478\uC2DC \uC54C\uB9BC\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.</p></div>";
  body += '<h2 style="color:' + mc + '">\u2705 ' + biz + " CCTV \uC120\uD0DD \uCCB4\uD06C\uB9AC\uC2A4\uD2B8</h2>";
  body += '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;margin:16px 0;line-height:2">' + s(["\u2611 \uAC10\uC2DC \uD3EC\uC778\uD2B8 \uCEE4\uBC84 \uAC00\uB2A5\uD55C \uCE74\uBA54\uB77C \uB300\uC218<br>\u2611 \uC57C\uAC04 \uD480\uCEEC\uB7EC \uCD2C\uC601 \uC9C0\uC6D0<br>\u2611 AI \uC6C0\uC9C1\uC784 \uAC10\uC9C0\xB7\uC54C\uB9BC \uAE30\uB2A5<br>\u2611 \uC2A4\uB9C8\uD2B8\uD3F0 \uC6D0\uACA9 \uBAA8\uB2C8\uD130\uB9C1<br>\u2611 NVR 30\uC77C \uC774\uC0C1 \uB179\uD654 \uC6A9\uB7C9<br>\u2611 \uBC29\uC218\xB7\uBC29\uC9C4 \uB4F1\uAE09(\uC2E4\uC678 \uC124\uCE58 \uC2DC)<br>\u2611 \uAC1C\uC778\uC815\uBCF4\uBCF4\uD638\uBC95 \uC548\uB0B4\uD310 \uC81C\uACF5", "\u2611 \uB9E4\uC7A5 \uAD6C\uC870\uC5D0 \uB9DE\uB294 \uB80C\uC988(\uC640\uC774\uB4DC\xB7\uC90C)<br>\u2611 PoE(\uC720\uC120) \uB610\uB294 Wi-Fi \uC5F0\uACB0 \uBC29\uC2DD<br>\u2611 \uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5 \uC635\uC158<br>\u2611 \uBCF4\uD5D8\uB8CC \uD560\uC778 \uC99D\uBE59 \uC11C\uB958 \uC81C\uACF5<br>\u2611 A/S \uB300\uC751 \uC2DC\uAC04(\uC6D0\uACA9+\uD604\uC7A5)<br>\u2611 \uC124\uCE58 \uD6C4 \uC571 \uC5F0\uB3D9\xB7\uC0AC\uC6A9\uBC95 \uAD50\uC721<br>\u2611 \uCD94\uAC00 \uCE74\uBA54\uB77C \uD655\uC7A5 \uAC00\uB2A5 \uC5EC\uBD80", "\u2611 \uC800\uC870\uB3C4 \uD658\uACBD \uC131\uB2A5(STARVIS \uC13C\uC11C \uB4F1)<br>\u2611 POS \uC2DC\uC2A4\uD15C \uC5F0\uB3D9 \uAC00\uB2A5 \uC5EC\uBD80<br>\u2611 \uC774\uC0C1\uD589\uB3D9 AI \uD0D0\uC9C0 \uC815\uD655\uB3C4<br>\u2611 \uC601\uC0C1 \uC554\uD638\uD654 \uC804\uC1A1 \uC9C0\uC6D0<br>\u2611 \uB2E4\uC911 \uC0AC\uC6A9\uC790 \uAD8C\uD55C \uC124\uC815<br>\u2611 \uD38C\uC6E8\uC5B4 \uC790\uB3D9 \uC5C5\uB370\uC774\uD2B8 \uC5EC\uBD80<br>\u2611 \uC124\uCE58 \uD6C4 \uC7A5\uAE30 \uBCF4\uC99D \uAE30\uAC04", "\u2611 4K \uD574\uC0C1\uB3C4 \uC9C0\uC6D0 \uBAA8\uB378<br>\u2611 \uBC88\uD638\uD310 \uC778\uC2DD(LPR) \uAE30\uB2A5<br>\u2611 \uC5BC\uAD74 \uC778\uC2DD \uBCF4\uC548 \uC5F0\uB3D9<br>\u2611 \uC5F4\uD654\uC0C1 \uD654\uC7AC \uAC10\uC9C0 \uAE30\uB2A5<br>\u2611 360\uB3C4 \uD30C\uB178\uB77C\uB9C8 \uCD2C\uC601<br>\u2611 \uACBD\uBCF4\uAE30 \uC5F0\uB3D9 \uD1B5\uD569 \uC2DC\uC2A4\uD15C<br>\u2611 \uB2E4\uC9C0\uC810 \uD1B5\uD569 \uAD00\uC81C \uC571", "\u2611 \uC81C\uC870\uC0AC A/S \uB124\uD2B8\uC6CC\uD06C \uBC94\uC704<br>\u2611 \uBB34\uC0C1 \uC218\uB9AC \uAE30\uAC04\uACFC \uC870\uAC74<br>\u2611 \uC6D0\uACA9 \uC9C4\uB2E8 \uAC00\uB2A5 \uC5EC\uBD80<br>\u2611 \uD38C\uC6E8\uC5B4 \uC5C5\uB370\uC774\uD2B8 \uC815\uCC45<br>\u2611 \uBD80\uD488 \uAD50\uCCB4 \uC18C\uC694 \uC2DC\uAC04<br>\u2611 \uACE0\uC7A5 \uC2DC \uB300\uCCB4 \uC7A5\uBE44 \uC9C0\uC6D0<br>\u2611 \uC751\uAE09 \uC0C1\uD669 24\uC2DC\uAC04 \uB300\uC751", "\u2611 \uC608\uC0B0 \uBC94\uC704 \uB0B4 \uD569\uB9AC\uC801 \uAD6C\uC131<br>\u2611 \uACC4\uC57D\uC11C \uC870\uD56D \uD22C\uBA85\uC131<br>\u2611 \uC228\uC740 \uBE44\uC6A9 \uC5C6\uB294 \uACAC\uC801<br>\u2611 \uB2E8\uACC4\uC801 \uD655\uC7A5 \uAC00\uB2A5\uC131<br>\u2611 \uC18C\uC0C1\uACF5\uC778 \uC9C0\uC6D0\uC0AC\uC5C5 \uC5F0\uACC4<br>\u2611 \uB80C\uD0C8 \uC635\uC158 \uC6D4 \uB0A9\uC785 \uADDC\uBAA8<br>\u2611 \uC7A5\uAE30 \uACC4\uC57D \uD560\uC778 \uD61C\uD0DD", "\u2611 \uAD00\uB9AC\uC790 \uC571 UI/UX \uD3B8\uC758\uC131<br>\u2611 \uB3D9\uC2DC \uB2E4\uC218 \uD654\uBA74 \uBAA8\uB2C8\uD130\uB9C1<br>\u2611 \uC601\uC0C1 \uAC80\uC0C9\xB7\uC7AC\uC0DD \uC18D\uB3C4<br>\u2611 \uC774\uBCA4\uD2B8 \uC54C\uB9BC \uC138\uBD84\uD654 \uC124\uC815<br>\u2611 \uC601\uC0C1 \uB2E4\uC6B4\uB85C\uB4DC\xB7\uACF5\uC720 \uAE30\uB2A5<br>\u2611 \uC7A5\uAE30 \uBCF4\uAD00 \uC601\uC0C1 \uAC80\uC0C9 \uAC00\uB2A5<br>\u2611 \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uC571(iOS\xB7\uC548\uB4DC\uB85C\uC774\uB4DC)"], 5) + "</div>";
